#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct X86RegallocPressureEvidence {
    /// Number of virtual registers the allocator reported as spilled.
    pub spilled_vreg_count: usize,
    /// Number of x86 stack slots installed for those spilled virtual registers.
    pub spill_stack_slot_count: usize,
    /// Total stack slots present after spill-slot installation.
    pub total_stack_slot_count: usize,
    /// Number of reload instructions materialized before spilled-operand uses.
    pub spill_reload_count: usize,
    /// Number of store instructions materialized after spilled-operand defs.
    pub spill_store_count: usize,
    /// Number of MOV-like copies inserted by x86 two-address fixup.
    pub two_address_fixup_copy_count: usize,
    /// Number of System V / Windows x64 callee-saved GPRs saved by the frame.
    pub callee_saved_gpr_save_count: usize,
    /// Number of Windows x64 callee-saved XMM registers saved by the frame.
    pub callee_saved_xmm_save_count: usize,
    /// Final non-pseudo machine instruction count after frame lowering.
    pub instruction_count: usize,
    /// Emitted code size in bytes, excluding object-file wrappers.
    pub code_size_bytes: usize,
    /// Existing final opcode evidence from the post-regalloc instruction stream.
    pub machine_code: X86MachineCodeEvidence,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct X86SpillMaterializationEvidence {
    reload_count: usize,
    store_count: usize,
}

impl X86MachineCodeEvidence {
    pub fn total_tracked_opcodes(self) -> usize {
        self.pmovmskb_count
            + self.popcnt_count
            + self.ptest_count
            + self.pand_count
            + self.pandn_count
            + self.por_count
            + self.pxor_count
            + self.pcmpeqb_count
            + self.pcmpeqw_count
            + self.pcmpgtb_count
            + self.pcmpgtw_count
            + self.pcmpeqd_count
            + self.pcmpgtd_count
            + self.pshufd_count
            + self.paddb_count
            + self.paddw_count
            + self.paddd_count
            + self.psubb_count
            + self.psubw_count
            + self.psubd_count
            + self.paddq_count
            + self.psubq_count
            + self.pmullw_count
            + self.pmuludq_count
            + self.pmulld_count
            + self.pcmpeqq_count
            + self.pcmpgtq_count
            + self.pinsrd_count
            + self.pinsrq_count
            + self.pextrd_count
            + self.pextrq_count
            + self.movd_to_xmm_count
            + self.movq_to_xmm_count
            + self.movdqa_count
            + self.movdqu_load_count
            + self.movdqu_store_count
            + self.punpckldq_count
            + self.punpcklqdq_count
            + self.pblendvb_count
    }

    fn observe_opcode(&mut self, opcode: X86Opcode) {
        match opcode {
            X86Opcode::Popcnt => self.popcnt_count += 1,
            X86Opcode::Pmovmskb => self.pmovmskb_count += 1,
            X86Opcode::Ptest => self.ptest_count += 1,
            X86Opcode::Pand => self.pand_count += 1,
            X86Opcode::Pandn => self.pandn_count += 1,
            X86Opcode::Por => self.por_count += 1,
            X86Opcode::Pxor => self.pxor_count += 1,
            X86Opcode::Pcmpeqb => self.pcmpeqb_count += 1,
            X86Opcode::Pcmpeqw => self.pcmpeqw_count += 1,
            X86Opcode::Pcmpgtb => self.pcmpgtb_count += 1,
            X86Opcode::Pcmpgtw => self.pcmpgtw_count += 1,
            X86Opcode::Pcmpeqd => self.pcmpeqd_count += 1,
            X86Opcode::Pcmpgtd => self.pcmpgtd_count += 1,
            X86Opcode::Pshufd => self.pshufd_count += 1,
            X86Opcode::Paddb => self.paddb_count += 1,
            X86Opcode::Paddw => self.paddw_count += 1,
            X86Opcode::Paddd => self.paddd_count += 1,
            X86Opcode::Psubb => self.psubb_count += 1,
            X86Opcode::Psubw => self.psubw_count += 1,
            X86Opcode::Psubd => self.psubd_count += 1,
            X86Opcode::Paddq => self.paddq_count += 1,
            X86Opcode::Psubq => self.psubq_count += 1,
            X86Opcode::Pmullw => self.pmullw_count += 1,
            X86Opcode::Pmuludq => self.pmuludq_count += 1,
            X86Opcode::Pmulld => self.pmulld_count += 1,
            X86Opcode::Pcmpeqq => self.pcmpeqq_count += 1,
            X86Opcode::Pcmpgtq => self.pcmpgtq_count += 1,
            X86Opcode::Pinsrd => self.pinsrd_count += 1,
            X86Opcode::Pinsrq => self.pinsrq_count += 1,
            X86Opcode::Pextrd => self.pextrd_count += 1,
            X86Opcode::Pextrq => self.pextrq_count += 1,
            X86Opcode::MovdToXmm => self.movd_to_xmm_count += 1,
            X86Opcode::MovqToXmm => self.movq_to_xmm_count += 1,
            X86Opcode::MovdqaRR | X86Opcode::MovdqaRM | X86Opcode::MovdqaMR => {
                self.movdqa_count += 1
            }
            X86Opcode::MovdquRM => self.movdqu_load_count += 1,
            X86Opcode::MovdquMR => self.movdqu_store_count += 1,
            X86Opcode::Punpckldq => self.punpckldq_count += 1,
            X86Opcode::Punpcklqdq => self.punpcklqdq_count += 1,
            X86Opcode::Pblendvb => self.pblendvb_count += 1,
            _ => {}
        }
    }
}

#[derive(Debug, Clone)]
struct X86BranchFixup {
    disp32_offset: usize,
    target: LirBlock,
}

/// Exception-handling emission data for one x86 function.
///
/// Computed during per-function encoding (LSDA bytes + personality symbol) by
/// [`x86_lsda_for_function`] and carried on [`X86EncodedFunc`] so the Mach-O
/// module emitter can place the `__gcc_except_tab` section, its
/// `_GCC_except_table_<fn>` local symbol, the personality external, and the
/// zPLR FDE that references the LSDA (EH Lane 2 Steps 3-4). `None` for functions
/// without exception-handling structure.
#[derive(Debug, Clone)]
struct X86EhData {
    /// Personality routine symbol (the bare linker name, e.g.
    /// `rust_eh_personality`), unmangled. The Mach-O emitter adds the platform
    /// underscore (`format!("_{}", ...)`), yielding `_rust_eh_personality`.
    personality: String,
    /// The serialized `__gcc_except_tab` (LSDA) bytes for this function.
    lsda_bytes: Vec<u8>,
}

/// Per-function bookkeeping produced by [`X86Pipeline::compile_module`].
///
/// Records where each function lives inside the combined `__text` / `.text`
/// section and what CALL fixups it emitted, so the module-level object
/// emitter can resolve cross-function calls into section-scoped
/// relocations.
#[derive(Debug, Clone)]
struct X86EncodedFunc {
    /// Unmangled function name (as declared in the trust_ir module).
    name: String,
    /// Length of the function's code bytes in the combined section.
    ///
    /// Kept in the exact `u32` domain used by COFF unwind records, DWARF FDEs,
    /// compact-unwind entries, and LSDA call-site ranges. Construction performs
    /// the sole checked `usize -> u32` conversion, so no downstream object path
    /// can silently truncate a large executable range.
    #[allow(dead_code)]
    code_len: u32,
    /// Length of the function's per-function constant pool bytes.
    #[allow(dead_code)]
    const_pool_len: usize,
    /// Offset of this function's lifted constant pool bytes in module `.rdata`.
    const_pool_rdata_offset: u64,
    /// RIP-relative load fixups targeting this function's constant pool.
    const_pool_rel32_fixups: Vec<X86ConstPoolRel32Fixup>,
    /// CALL-site fixups with offsets local to this function's code range.
    call_fixups: Vec<X86CallFixup>,
    /// GlobalRef LEA fixups with offsets local to this function's code range.
    global_ref_fixups: Vec<X86GlobalRefFixup>,
    /// Byte offset where this function's code begins in the combined
    /// `__text` / `.text` section.
    text_offset: u64,
    /// Frame metadata needed to emit conservative unwind info for dynamic frames.
    frame_metadata: Option<X86FrameMetadata>,
    /// Exception-handling data (LSDA bytes + personality) for the Mach-O
    /// `__gcc_except_tab` + zPLR FDE emission. `None` for non-EH functions.
    eh: Option<X86EhData>,
}

/// A fully encoded and assembled x86 module — the output of Phase 1
/// (per-function regalloc+encode, then deterministic in-order reassembly) of
/// [`X86Pipeline::compile_module_impl`], BEFORE Phase-2 object emission.
///
/// CT-8 (encode reuse): the proof-certificate lane needs exactly this
/// assembly for the object relocation INVENTORY, and the final object
/// emission needs it again — carrying it as a value lets
/// `Compiler::compile_x86_64` run the dominant regalloc+encode ONCE and feed
/// both consumers, instead of the historical redundant full re-encode.
pub(crate) struct X86AssembledModule {
    /// Per-function encodings + fixups, in FUNCTION ORDER.
    encoded: Vec<X86EncodedFunc>,
    /// Concatenated `__text` / `.text` bytes (function code plus non-COFF
    /// inline const pools), in function order.
    combined_code: Vec<u8>,
    /// COFF-only combined `.rdata` (lifted const pools); empty otherwise.
    combined_rdata: Vec<u8>,
    /// The effective output format the assembly was built for.
    effective_format: X86OutputFormat,
}

impl X86AssembledModule {
    /// Length of the concatenated `__text` / `.text` bytes (function code
    /// plus non-COFF inline const pools) — the module's raw code size,
    /// excluding any object wrapper overhead. This is byte-for-byte what the
    /// RawBytes output format would return for the same functions, but
    /// readable from an assembly built under ANY output format (the compiler
    /// uses it for EH-carrying modules, which RawBytes refuses).
    pub(crate) fn code_size(&self) -> usize {
        self.combined_code.len()
    }
}

/// x86-64 frame facts captured before pseudo expansion and object emission.
#[derive(Debug, Clone, PartialEq, Eq)]
struct X86FrameMetadata {
    /// Callee-saved GPRs pushed after RBP, in prologue push order.
    callee_saved: Vec<X86PReg>,
    /// Windows x64 callee-saved XMM registers saved after the static frame allocation.
    callee_saved_xmms: Vec<X86PReg>,
    /// RBP-relative displacements for `callee_saved_xmms`.
    xmm_save_offsets: Vec<i32>,
    /// Static frame allocation emitted by the prologue.
    frame_size: u32,
    /// Whether this function adjusts RSP by a runtime-sized amount.
    has_dynamic_alloc: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct X86EhFrameRecord {
    callee_saved: Vec<X86PReg>,
    frame_size: u32,
    code_len: u32,
    symbol_index: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct X86CoffUnwindRecord {
    text_offset: u32,
    code_len: u32,
    unwind_info_offset: u32,
    unwind_info: Vec<u8>,
}

const WINDOWS_X64_SHADOW_SPACE_BYTES: u32 = 32;

fn collect_x86_machine_code_evidence(
    func: &X86ISelFunction,
    target_features: X86TargetFeatures,
) -> X86MachineCodeEvidence {
    let mut evidence = X86MachineCodeEvidence {
        target_features,
        ..X86MachineCodeEvidence::default()
    };
    for block_id in &func.block_order {
        let Some(block) = func.blocks.get(block_id) else {
            continue;
        };
        for inst in &block.insts {
            if !inst.opcode.is_pseudo() {
                evidence.observe_opcode(inst.opcode);
            }
        }
    }
    evidence
}

fn count_x86_non_pseudo_insts(func: &X86ISelFunction) -> usize {
    func.block_order
        .iter()
        .filter_map(|block_id| func.blocks.get(block_id))
        .flat_map(|block| block.insts.iter())
        .filter(|inst| !inst.opcode.is_pseudo())
        .count()
}

// ---------------------------------------------------------------------------
// Register allocation mode
// ---------------------------------------------------------------------------

/// Register allocation mode for the x86-64 pipeline.
///
/// Controls whether the pipeline uses the simplified first-appearance allocator
/// or the full `trust-cg-regalloc` pipeline (with liveness analysis, coalescing,
/// spill code generation, etc.).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum X86RegAllocMode {
    /// Simplified linear-scan assignment (no liveness analysis, no spill code).
    /// Fast but limited: assigns VRegs to physical registers in order of first
    /// appearance. Suitable for O0 or simple test functions.
    Simplified,
    /// Full register allocation via trust-cg-regalloc (linear scan or greedy).
    /// Requires converting X86ISelFunction to RegAllocFunction, running the
    /// allocator, and translating results back.
    Full(AllocStrategy),
}

// ---------------------------------------------------------------------------
// Target features
// ---------------------------------------------------------------------------

/// x86-64 target features used by the pipeline's fail-closed opcode gate.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum X86TargetFeature {
    /// POPCNT instruction.
    Popcnt,
    /// SSE4.1 instruction subset.
    Sse41,
    /// SSE4.2 instruction subset.
    Sse42,
    /// AVX instruction subset. The current encoder has no VEX/YMM emission
    /// path, so this bit is policy scaffolding until AVX lowering lands.
    Avx,
    /// AVX2 instruction subset. The current encoder has no VEX/YMM emission
    /// path, so this bit is policy scaffolding until AVX2 lowering lands.
    Avx2,
}

impl X86TargetFeature {
    /// All target features with stable metadata ordering.
    pub const ALL: [Self; 5] = [
        Self::Popcnt,
        Self::Sse41,
        Self::Sse42,
        Self::Avx,
        Self::Avx2,
    ];

    /// Canonical target-feature spelling used in diagnostics and metadata.
    pub const fn name(self) -> &'static str {
        match self {
            Self::Popcnt => "popcnt",
            Self::Sse41 => "sse4.1",
            Self::Sse42 => "sse4.2",
            Self::Avx => "avx",
            Self::Avx2 => "avx2",
        }
    }
}

/// Conservative x86-64 feature set for pipeline admission.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct X86TargetFeatures {
    bits: u32,
}

impl X86TargetFeatures {
    const POPCNT_BIT: u32 = 1 << 0;
    const SSE41_BIT: u32 = 1 << 1;
    const SSE42_BIT: u32 = 1 << 2;
    const AVX_BIT: u32 = 1 << 3;
    const AVX2_BIT: u32 = 1 << 4;

    /// Generic x86-64 baseline: no optional SSE4.x features are assumed.
    pub const fn generic_x86_64() -> Self {
        Self { bits: 0 }
    }

    /// Current Trust Codegen x86-64 backend profile.
    ///
    /// Existing host/current JIT and AOT paths already rely on native SSE4.1
    /// and SSE4.2 helpers. Keep that profile explicit instead of silently
    /// applying it to callers that request a generic x86-64 target.
    pub const fn current() -> Self {
        Self {
            bits: Self::SSE41_BIT | Self::SSE42_BIT,
        }
    }

    /// Runtime-detected feature set for in-process host JIT execution.
    pub fn host() -> Self {
        let features = Self::generic_x86_64();
        #[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
        {
            let mut features = features;
            if std::is_x86_feature_detected!("sse4.1") {
                features = features.with_feature(X86TargetFeature::Sse41);
            }
            if std::is_x86_feature_detected!("popcnt") {
                features = features.with_feature(X86TargetFeature::Popcnt);
            }
            if std::is_x86_feature_detected!("sse4.2") {
                features = features.with_feature(X86TargetFeature::Sse42);
            }
            if std::is_x86_feature_detected!("avx") {
                features = features.with_feature(X86TargetFeature::Avx);
            }
            if std::is_x86_feature_detected!("avx2") {
                features = features.with_feature(X86TargetFeature::Avx2);
            }
            features
        }
        #[cfg(not(any(target_arch = "x86", target_arch = "x86_64")))]
        {
            features
        }
    }

    /// Return a copy with `feature` enabled.
    pub const fn with_feature(self, feature: X86TargetFeature) -> Self {
        Self {
            bits: self.bits | Self::bit(feature),
        }
    }

    /// Return a copy with `feature` disabled.
    pub const fn without_feature(self, feature: X86TargetFeature) -> Self {
        Self {
            bits: self.bits & !Self::bit(feature),
        }
    }

    /// Whether `feature` is enabled.
    pub const fn contains(self, feature: X86TargetFeature) -> bool {
        (self.bits & Self::bit(feature)) != 0
    }

    /// Enabled feature names in stable metadata order.
    pub fn enabled_feature_names(self) -> Vec<&'static str> {
        X86TargetFeature::ALL
            .into_iter()
            .filter(|feature| self.contains(*feature))
            .map(X86TargetFeature::name)
            .collect()
    }

    /// Canonical comma-separated feature list for evidence metadata.
    pub fn metadata_feature_list(self) -> String {
        self.enabled_feature_names().join(",")
    }

    const fn bit(feature: X86TargetFeature) -> u32 {
        match feature {
            X86TargetFeature::Popcnt => Self::POPCNT_BIT,
            X86TargetFeature::Sse41 => Self::SSE41_BIT,
            X86TargetFeature::Sse42 => Self::SSE42_BIT,
            X86TargetFeature::Avx => Self::AVX_BIT,
            X86TargetFeature::Avx2 => Self::AVX2_BIT,
        }
    }
}

impl Default for X86TargetFeatures {
    fn default() -> Self {
        Self::current()
    }
}

// ---------------------------------------------------------------------------
// Pipeline errors
// ---------------------------------------------------------------------------

/// Errors during x86-64 compilation.
#[derive(Debug)]
pub enum X86PipelineError {
    /// Instruction selection failed.
    ISel(String),
    /// Register allocation ran out of registers.
    RegAlloc(String),
    /// Register allocation inserted a rematerialized instruction shape that
    /// x86 ISel replay has not proven safe to clone yet.
    RegAllocRematerializationReplayUnsupported { opcode: u16 },
    /// The selected x86-64 target feature set does not admit this opcode.
    UnsupportedTargetFeature {
        opcode: X86Opcode,
        feature: X86TargetFeature,
    },
    /// Constant-pool layout or fixup failed.
    ConstantPool(String),
    /// Encoding failed.
    Encoding(X86EncodeError),
    /// Prologue/epilogue generation failed.
    FrameLowering(String),
    /// A public x86 function boundary received a non-total block layout/CFG.
    MalformedFunction { function: String, detail: String },
    /// Windows x86-64 COFF would need .pdata/.xdata unwind metadata that the
    /// writer does not yet emit.
    WindowsCoffUnwindMetadataRequired { function: String, reason: String },
    /// COFF module emission saw a direct CALL to a symbol that is not defined
    /// in the module, but this writer does not yet emit undefined externals.
    CoffUndefinedExternalCall { caller: String, callee: String },
    /// Single-function emission saw a symbolic direct CALL but cannot emit the
    /// relocation needed to make the placeholder displacement linkable.
    SymbolicDirectCallRequiresRelocationEmission {
        function: String,
        callee: String,
        format: X86OutputFormat,
    },
    /// An EH-carrying function reached an output/API boundary that cannot
    /// carry its exact LSDA + unwind-frame metadata.
    EhOutputUnsupported {
        function: String,
        format: X86OutputFormat,
        reason: String,
    },
    /// Structural EH metadata omitted or supplied an unrepresentable
    /// personality symbol.
    InvalidEhPersonality { function: String, reason: String },
    /// An object/unwind field cannot represent a calculated byte size or offset.
    ObjectFieldTooLarge {
        function: String,
        field: &'static str,
        value: u128,
        max: u128,
    },
    /// A GlobalRef symbol-address materialization cannot be resolved by this
    /// x86-64 emission path.
    GlobalRefUnsupported {
        function: String,
        symbol: String,
        reason: String,
    },
    /// An ExternRef symbol-address materialization cannot be resolved by this
    /// x86-64 emission path.
    ExternRefUnsupported {
        function: String,
        symbol: String,
        reason: String,
    },
    /// COFF object emission failed.
    Coff(crate::coff::CoffError),
    /// Mach-O relocation emission failed validation.
    MachORelocation(crate::macho::MachORelocationError),
    /// Mach-O object layout or serialization failed validation.
    MachOWrite(crate::macho::MachOWriteError),
    /// ENC-3: the per-emission decode-check gate found that the emitted bytes do
    /// not structurally decode back to the intended post-RA instruction (a
    /// would-be miscompile in the byte encoder). Fail-closed redundancy gate.
    DecodeCheck(String),
    /// The enforce-mode ELF reparse gate (the ENC-9 sibling in
    /// `elf::reparse`) found the emitted object bytes do not re-parse to the
    /// writer's intent (a would-be malformed object). Fail-closed redundancy
    /// gate; also the per-object binding the relocation inventory claims.
    ElfReparse(String),
}

impl core::fmt::Display for X86PipelineError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::ISel(msg) => write!(f, "x86-64 ISel failed: {}", msg),
            Self::RegAlloc(msg) => write!(f, "x86-64 regalloc failed: {}", msg),
            Self::RegAllocRematerializationReplayUnsupported { opcode } => write!(
                f,
                "x86-64 regalloc rematerialization replay is not supported for inserted opcode {opcode}"
            ),
            Self::UnsupportedTargetFeature { opcode, feature } => {
                write!(
                    f,
                    "x86-64 opcode {opcode:?} requires target feature {}",
                    feature.name()
                )
            }
            Self::ConstantPool(msg) => write!(f, "x86-64 constant pool failed: {}", msg),
            Self::Encoding(e) => write!(f, "x86-64 encoding failed: {}", e),
            Self::FrameLowering(msg) => write!(f, "x86-64 frame lowering failed: {}", msg),
            Self::MalformedFunction { function, detail } => {
                write!(
                    f,
                    "malformed x86-64 machine function `{function}`: {detail}"
                )
            }
            Self::WindowsCoffUnwindMetadataRequired { function, reason } => write!(
                f,
                "Windows x86-64 COFF object emission for {function} requires .pdata/.xdata unwind metadata: {reason}"
            ),
            Self::CoffUndefinedExternalCall { caller, callee } => write!(
                f,
                "x86-64 COFF module object emission does not support undefined external call from {caller} to {callee}"
            ),
            Self::SymbolicDirectCallRequiresRelocationEmission {
                function,
                callee,
                format,
            } => {
                write!(
                    f,
                    "x86-64 single-function {:?} emission for {function} cannot encode symbolic direct call to {callee}: symbolic direct calls require module/object relocation emission",
                    format
                )
            }
            Self::EhOutputUnsupported {
                function,
                format,
                reason,
            } => write!(
                f,
                "x86-64 {:?} exception-handling emission for {function} is unsupported: {reason}",
                format
            ),
            Self::InvalidEhPersonality { function, reason } => write!(
                f,
                "x86-64 exception-handling metadata for {function} has an invalid personality: {reason}"
            ),
            Self::ObjectFieldTooLarge {
                function,
                field,
                value,
                max,
            } => write!(
                f,
                "x86-64 object field `{field}` for function `{function}` cannot represent byte count {value} (maximum {max})"
            ),
            Self::GlobalRefUnsupported {
                function,
                symbol,
                reason,
            } => {
                write!(
                    f,
                    "x86-64 GlobalRef from {function} to {symbol} is unsupported: {reason}"
                )
            }
            Self::ExternRefUnsupported {
                function,
                symbol,
                reason,
            } => {
                write!(
                    f,
                    "x86-64 ExternRef from {function} to {symbol} is unsupported: {reason}"
                )
            }
            Self::Coff(e) => write!(f, "x86-64 COFF object emission failed: {}", e),
            Self::MachORelocation(e) => {
                write!(f, "x86-64 Mach-O relocation emission failed: {e}")
            }
            Self::MachOWrite(e) => write!(f, "x86-64 Mach-O object serialization failed: {e}"),
            Self::DecodeCheck(msg) => {
                write!(f, "x86-64 decode-check gate rejected emission: {}", msg)
            }
            Self::ElfReparse(msg) => {
                write!(f, "x86-64 ELF reparse gate rejected serialization: {}", msg)
            }
        }
    }
}

/// Convert a host-sized object/unwind byte count at one named authority
/// boundary. Keeping this check shared prevents format-specific emitters from
/// drifting back to truncating `as u32` casts.
fn checked_x86_object_u32(
    function: &str,
    field: &'static str,
    value: usize,
) -> Result<u32, X86PipelineError> {
    checked_x86_object_u32_value(function, field, value as u128)
}

fn checked_x86_object_u32_u64(
    function: &str,
    field: &'static str,
    value: u64,
) -> Result<u32, X86PipelineError> {
    checked_x86_object_u32_value(function, field, u128::from(value))
}

fn checked_x86_object_u32_value(
    function: &str,
    field: &'static str,
    value: u128,
) -> Result<u32, X86PipelineError> {
    checked_x86_object_u32_with_max(function, field, value, u32::MAX)
}

fn checked_x86_object_u32_with_max(
    function: &str,
    field: &'static str,
    value: u128,
    max: u32,
) -> Result<u32, X86PipelineError> {
    let too_large = || X86PipelineError::ObjectFieldTooLarge {
        function: function.to_string(),
        field,
        value,
        max: u128::from(max),
    };
    let narrowed = u32::try_from(value).map_err(|_| too_large())?;
    if narrowed > max {
        return Err(too_large());
    }
    Ok(narrowed)
}

/// Mach-O stores `relocation_info.r_address` as a signed 32-bit nonnegative
/// section offset. Bit 31 is not extra range: it denotes a scattered
/// relocation. Accepting a general `u32` here would therefore silently turn a
/// large ordinary relocation into a negative/scattered record.
fn checked_x86_macho_relocation_offset_value(
    function: &str,
    field: &'static str,
    value: u128,
) -> Result<u32, X86PipelineError> {
    checked_x86_object_u32_with_max(function, field, value, i32::MAX as u32)
}

fn checked_x86_macho_relocation_offset_u64(
    function: &str,
    field: &'static str,
    value: u64,
) -> Result<u32, X86PipelineError> {
    checked_x86_macho_relocation_offset_value(function, field, u128::from(value))
}

fn checked_x86_macho_section_offset(
    function: &str,
    field: &'static str,
    base: u64,
    local: usize,
) -> Result<u32, X86PipelineError> {
    checked_x86_macho_relocation_offset_value(function, field, u128::from(base) + local as u128)
}

fn checked_x86_macho_table_member_offset(
    function: &str,
    field: &'static str,
    index: usize,
    stride: u32,
    member_offset: u32,
) -> Result<u32, X86PipelineError> {
    checked_x86_macho_relocation_offset_value(
        function,
        field,
        (index as u128) * u128::from(stride) + u128::from(member_offset),
    )
}

fn checked_x86_object_u64_value(
    function: &str,
    field: &'static str,
    value: u128,
) -> Result<u64, X86PipelineError> {
    u64::try_from(value).map_err(|_| X86PipelineError::ObjectFieldTooLarge {
        function: function.to_string(),
        field,
        value,
        max: u128::from(u64::MAX),
    })
}

/// Compute a serialized table-entry byte offset without overflowing either
/// host arithmetic or the destination's `u32` field.
fn checked_x86_object_table_offset(
    function: &str,
    field: &'static str,
    index: usize,
    stride: u32,
) -> Result<u32, X86PipelineError> {
    checked_x86_object_table_member_offset(function, field, index, stride, 0)
}

fn checked_x86_object_table_member_offset(
    function: &str,
    field: &'static str,
    index: usize,
    stride: u32,
    member_offset: u32,
) -> Result<u32, X86PipelineError> {
    // `usize -> u128` is widening on every Rust target. Multiplication in the
    // wider domain lets the typed range check report the true mathematical
    // byte offset rather than overflowing first in `usize`.
    let value = (index as u128) * u128::from(stride) + u128::from(member_offset);
    checked_x86_object_u32_value(function, field, value)
}

fn checked_x86_object_table_size(
    function: &str,
    field: &'static str,
    count: usize,
    stride: usize,
) -> Result<usize, X86PipelineError> {
    count
        .checked_mul(stride)
        .ok_or_else(|| X86PipelineError::ObjectFieldTooLarge {
            function: function.to_string(),
            field,
            value: (count as u128) * (stride as u128),
            max: usize::MAX as u128,
        })
}

fn checked_x86_object_u32_table_size(
    function: &str,
    field: &'static str,
    count: usize,
    stride: u32,
) -> Result<u32, X86PipelineError> {
    checked_x86_object_u32_value(function, field, (count as u128) * u128::from(stride))
}

/// Add a function/section base and a host-sized local offset in a widened
/// domain, then validate the serialized `u32` relocation-address field.
fn checked_x86_object_section_offset(
    function: &str,
    field: &'static str,
    base: u64,
    local: usize,
) -> Result<u32, X86PipelineError> {
    let value = u128::from(base) + local as u128;
    checked_x86_object_u32_value(function, field, value)
}

/// Checked `u64 + u64` for object section offsets that remain 64-bit (ELF
/// symbols/relocations and pre-serialization global layouts).
fn checked_x86_object_u64_sum(
    function: &str,
    field: &'static str,
    left: u64,
    right: u64,
) -> Result<u64, X86PipelineError> {
    let value = u128::from(left) + u128::from(right);
    checked_x86_object_u64_value(function, field, value)
}

fn checked_x86_object_u64_plus_usize(
    function: &str,
    field: &'static str,
    left: u64,
    right: usize,
) -> Result<u64, X86PipelineError> {
    let value = u128::from(left) + right as u128;
    checked_x86_object_u64_value(function, field, value)
}

fn checked_x86_code_len(function: &str, code_len: usize) -> Result<u32, X86PipelineError> {
    checked_x86_object_u32(function, "encoded code length", code_len)
}

fn checked_x86_symbol_initializer_slot(
    global: &str,
    symbol: &str,
    offset: u64,
    data_len: usize,
) -> Result<std::ops::Range<usize>, X86PipelineError> {
    let slot = usize::try_from(offset).map_err(|_| X86PipelineError::GlobalRefUnsupported {
        function: global.to_string(),
        symbol: symbol.to_string(),
        reason: format!("symbol-initializer offset {offset} does not fit the host index domain"),
    })?;
    let end = slot
        .checked_add(std::mem::size_of::<u64>())
        .ok_or_else(|| X86PipelineError::GlobalRefUnsupported {
            function: global.to_string(),
            symbol: symbol.to_string(),
            reason: "symbol-initializer slot range overflows usize".to_string(),
        })?;
    if end > data_len {
        return Err(X86PipelineError::GlobalRefUnsupported {
            function: global.to_string(),
            symbol: symbol.to_string(),
            reason: format!(
                "symbol-initializer slot [{slot},{end}) exceeds global byte length {data_len}"
            ),
        });
    }
    Ok(slot..end)
}

fn x86_symbol_ref_unsupported(
    kind: X86SymbolRefFixupKind,
    function: String,
    symbol: String,
    reason: impl Into<String>,
) -> X86PipelineError {
    match kind {
        X86SymbolRefFixupKind::GlobalRef => X86PipelineError::GlobalRefUnsupported {
            function,
            symbol,
            reason: reason.into(),
        },
        X86SymbolRefFixupKind::ExternRefGot => X86PipelineError::ExternRefUnsupported {
            function,
            symbol,
            reason: reason.into(),
        },
        // TLV rides the extern-ref error shape: it IS an external-symbol
        // reference; only the relocation kind differs.
        X86SymbolRefFixupKind::TlsTlv => X86PipelineError::ExternRefUnsupported {
            function,
            symbol,
            reason: reason.into(),
        },
    }
}

/// Fail closed if any object global is thread-local.
///
/// The x86-64 emitters (Mach-O / ELF) have no TLS section/relocation path; the
/// only wired thread-local backend is the AArch64 Darwin TLV emitter. Emitting a
/// thread-local as an ordinary data symbol would be a silent miscompile (one
/// shared copy instead of per-thread storage), so reject it here. The x86-64 TLS
/// *reader* path (`Opcode::TlsRef`) already fails closed at ISel; this guards the
/// *definition* side for a TLS global with no in-module reader.
fn reject_x86_thread_local_globals(
    globals: &[crate::pipeline::ObjectGlobal],
) -> Result<(), X86PipelineError> {
    if let Some(global) = globals.iter().find(|global| global.is_thread_local) {
        return Err(X86PipelineError::GlobalRefUnsupported {
            function: String::new(),
            symbol: global.name.clone(),
            reason:
                "thread-local globals are not supported by the x86-64 object emitter; only the \
                 AArch64 Darwin Mach-O TLV path is wired (fail-closed)"
                    .to_string(),
        });
    }
    Ok(())
}

impl From<X86EncodeError> for X86PipelineError {
    fn from(e: X86EncodeError) -> Self {
        Self::Encoding(e)
    }
}

impl From<crate::coff::CoffError> for X86PipelineError {
    fn from(e: crate::coff::CoffError) -> Self {
        Self::Coff(e)
    }
}

impl From<crate::macho::MachORelocationError> for X86PipelineError {
    fn from(e: crate::macho::MachORelocationError) -> Self {
        Self::MachORelocation(e)
    }
}

impl From<crate::macho::MachOWriteError> for X86PipelineError {
    fn from(e: crate::macho::MachOWriteError) -> Self {
        Self::MachOWrite(e)
    }
}

fn build_x86_constant_pool(
    func: &X86ISelFunction,
) -> Result<(crate::constant_pool::ConstantPool, Vec<usize>), X86PipelineError> {
    let mut pool = crate::constant_pool::ConstantPool::new();
    let mut isel_to_pool_idx = Vec::with_capacity(func.const_pool_entries.len());

    for (isel_idx, entry) in func.const_pool_entries.iter().enumerate() {
        let pool_idx = match entry.data.len() {
            4 => pool.add_f32(f32::from_le_bytes([
                entry.data[0],
                entry.data[1],
                entry.data[2],
                entry.data[3],
            ])),
            8 => pool.add_f64(f64::from_le_bytes([
                entry.data[0],
                entry.data[1],
                entry.data[2],
                entry.data[3],
                entry.data[4],
                entry.data[5],
                entry.data[6],
                entry.data[7],
            ])),
            len => {
                return Err(X86PipelineError::ConstantPool(format!(
                    "entry {isel_idx} has unsupported data length {len}; expected 4 or 8 bytes"
                )));
            }
        };
        isel_to_pool_idx.push(pool_idx);
    }

    pool.layout();
    Ok((pool, isel_to_pool_idx))
}

fn x86_constant_pool_fixup_offset(
    pool: &crate::constant_pool::ConstantPool,
    isel_to_pool_idx: &[usize],
    entry_idx: usize,
) -> Result<i64, X86PipelineError> {
    let Some(&pool_idx) = isel_to_pool_idx.get(entry_idx) else {
        return Err(X86PipelineError::ConstantPool(format!(
            "fixup references entry {entry_idx}, but function has {} constant-pool entries",
            isel_to_pool_idx.len()
        )));
    };
    Ok(pool.entry_offset(pool_idx) as i64)
}

fn align_vec_to(bytes: &mut Vec<u8>, alignment: usize) {
    debug_assert!(alignment.is_power_of_two());
    let aligned_len = (bytes.len() + alignment - 1) & !(alignment - 1);
    bytes.resize(aligned_len, 0);
}

/// `log2` of the x86 `__text` alignment this backend requests.
///
/// 16 bytes (2^4) is the System V convention. The JCC-erratum pass needs 32
/// (2^5), because it reasons about `encoder.position()` — an offset relative to
/// the START OF THE FUNCTION — while the erratum is a property of the ABSOLUTE
/// address. Those coincide only if every function begins on a 32-byte boundary,
/// which needs BOTH this section alignment AND per-function padding in
/// `combined_code`; either alone leaves the boundaries off in the final image.
fn x86_text_align_log2() -> u32 {
    if x86_jcc_align_enabled() { 5 } else { 4 }
}

/// Pad a code buffer up to `alignment` with one-byte `NOP`s (0x90).
///
/// ⚑ NOT `align_vec_to`, which fills with 0x00 — that is `add %al,(%rax)` when
/// decoded, which is wrong to leave lying in an executable section even where
/// it is unreachable. Inter-function padding is never entered, but the
/// disassembly is read by humans and by the ENC-2 objdump differential lane.
fn align_code_vec_with_nops(bytes: &mut Vec<u8>, alignment: usize) {
    debug_assert!(alignment.is_power_of_two());
    let aligned_len = (bytes.len() + alignment - 1) & !(alignment - 1);
    bytes.resize(aligned_len, 0x90);
}

// ---------------------------------------------------------------------------
// Simple register allocator for x86-64
// ---------------------------------------------------------------------------

/// Simple linear-scan register assignment for x86-64 ISel output.
///
/// This is a fast fallback used when `X86RegAllocMode::Simplified` is selected
/// (e.g., O0 builds). The default pipeline uses the full regalloc instead.
/// Assigns VRegs to physical registers in order of first appearance, with no
/// liveness analysis or spill code generation.
pub struct X86RegAssignment {
    /// VReg -> physical register mapping.
    pub allocation: HashMap<VReg, X86PReg>,
    /// Callee-saved GPRs that were used and need push/pop preservation.
    pub used_callee_saved: Vec<X86PReg>,
    /// Windows x64 callee-saved XMM registers that need 128-bit save/restore.
    pub used_callee_saved_xmms: Vec<X86PReg>,
    /// Number of spill slots needed.
    pub num_spills: u32,
    #[allow(dead_code)]
    spill_plan: X86SpillPlan,
}

#[derive(Debug, Clone, Default)]
#[allow(dead_code)]
struct X86SpillPlan {
    slots: Vec<X86SpillSlot>,
}

#[derive(Debug, Clone)]
#[allow(dead_code)]
struct X86SpillSlot {
    vreg: VReg,
    size: u32,
    align: u32,
}

fn x86_function_uses_pblendvb_implicit_xmm0(func: &X86ISelFunction) -> bool {
    func.block_order.iter().any(|block| {
        func.blocks.get(block).is_some_and(|mblock| {
            mblock
                .insts
                .iter()
                .any(|inst| inst.opcode == X86Opcode::Pblendvb)
        })
    })
}

fn x86_abi_callee_saved_gprs(abi: X86CallAbi) -> &'static [X86PReg] {
    match abi {
        X86CallAbi::SystemV => &X86_CALLEE_SAVED_GPRS,
        X86CallAbi::WindowsX64 => &[
            x86_64_regs::RBX,
            x86_64_regs::RBP,
            x86_64_regs::RSI,
            x86_64_regs::RDI,
            x86_64_regs::R12,
            x86_64_regs::R13,
            x86_64_regs::R14,
            x86_64_regs::R15,
        ],
    }
}

fn x86_abi_allocatable_gprs(_abi: X86CallAbi) -> Vec<X86PReg> {
    X86_ALLOCATABLE_GPRS.to_vec()
}

fn x86_abi_allocatable_gpr32s(_abi: X86CallAbi) -> Vec<X86PReg> {
    x86_64_regs::X86_ALLOCATABLE_GPR32S.to_vec()
}

fn x86_abi_allocatable_xmms(abi: X86CallAbi) -> Vec<X86PReg> {
    match abi {
        X86CallAbi::SystemV => X86_ALLOCATABLE_XMMS.to_vec(),
        X86CallAbi::WindowsX64 => X86_ALLOCATABLE_XMMS.to_vec(),
    }
}

fn x86_abi_callee_saved_xmms(abi: X86CallAbi) -> &'static [X86PReg] {
    match abi {
        X86CallAbi::SystemV => &[],
        X86CallAbi::WindowsX64 => &[
            x86_64_regs::XMM6,
            x86_64_regs::XMM7,
            x86_64_regs::XMM8,
            x86_64_regs::XMM9,
            x86_64_regs::XMM10,
            x86_64_regs::XMM11,
            x86_64_regs::XMM12,
            x86_64_regs::XMM13,
            x86_64_regs::XMM14,
            x86_64_regs::XMM15,
        ],
    }
}

fn x86_callee_saved_gpr_save_root(abi: X86CallAbi, reg: X86PReg) -> Option<X86PReg> {
    let root = x86_containing_gpr64(reg)?;
    x86_abi_callee_saved_gprs(abi)
        .contains(&root)
        .then_some(root)
}

fn x86_used_callee_saved_from_allocation(
    abi: X86CallAbi,
    allocation: &HashMap<VReg, X86PReg>,
) -> (Vec<X86PReg>, Vec<X86PReg>) {
    let callee_saved_xmms = x86_abi_callee_saved_xmms(abi);
    let mut used_callee_saved_set: HashSet<X86PReg> = HashSet::new();
    let mut used_callee_saved_xmm_set: HashSet<X86PReg> = HashSet::new();

    for x86_preg in allocation.values() {
        if let Some(save_root) = x86_callee_saved_gpr_save_root(abi, *x86_preg) {
            used_callee_saved_set.insert(save_root);
        }
        if callee_saved_xmms.contains(x86_preg) {
            used_callee_saved_xmm_set.insert(*x86_preg);
        }
    }

    let mut used_callee_saved: Vec<X86PReg> = used_callee_saved_set.into_iter().collect();
    used_callee_saved.sort_by_key(|reg| reg.encoding());
    let mut used_callee_saved_xmms: Vec<X86PReg> = used_callee_saved_xmm_set.into_iter().collect();
    used_callee_saved_xmms.sort_by_key(|reg| reg.encoding());

    (used_callee_saved, used_callee_saved_xmms)
}

fn apply_x86_abi_allocatable_regs(config: &mut trust_cg_regalloc::AllocConfig, abi: X86CallAbi) {
    if abi == X86CallAbi::SystemV {
        return;
    }

    let x86_gprs: Vec<_> = x86_abi_allocatable_gprs(abi)
        .into_iter()
        .filter_map(x86_to_preg)
        .collect();
    let x86_xmms: Vec<_> = x86_abi_allocatable_xmms(abi)
        .into_iter()
        .filter_map(x86_to_preg)
        .collect();

    config
        .allocatable_regs
        .insert(RegClass::Gpr64, x86_gprs.clone());
    config.allocatable_regs.insert(
        RegClass::Gpr32,
        x86_64_regs::X86_ALLOCATABLE_GPR32S
            .iter()
            .filter_map(|reg| x86_to_preg(*reg))
            .collect(),
    );
    config
        .allocatable_regs
        .insert(RegClass::Fpr128, x86_xmms.clone());
    config
        .allocatable_regs
        .insert(RegClass::Fpr64, x86_xmms.clone());
    config.allocatable_regs.insert(RegClass::Fpr32, x86_xmms);
}

#[allow(dead_code)]
fn remove_allocatable_x86_preg(config: &mut trust_cg_regalloc::AllocConfig, reg: X86PReg) {
    let Some(preg) = x86_to_preg(reg) else {
        return;
    };

    for regs in config.allocatable_regs.values_mut() {
        regs.retain(|candidate| *candidate != preg);
    }
}

#[allow(dead_code)]
fn reserve_x86_spill_scratch_regs(config: &mut trust_cg_regalloc::AllocConfig, abi: X86CallAbi) {
    remove_allocatable_x86_preg(config, R10);
    remove_allocatable_x86_preg(config, R10D);
    remove_allocatable_x86_preg(config, R11);
    remove_allocatable_x86_preg(config, R11D);
    for reg in x86_spill_xmm_scratch_regs(abi) {
        remove_allocatable_x86_preg(config, reg);
    }
}

#[allow(dead_code)]
fn x86_spill_gpr_scratch_regs(class: RegClass) -> [X86PReg; 2] {
    if class == RegClass::Gpr32 {
        [R10D, R11D]
    } else {
        [R10, R11]
    }
}

#[allow(dead_code)]
fn x86_spill_xmm_scratch_regs(abi: X86CallAbi) -> [X86PReg; 2] {
    match abi {
        X86CallAbi::SystemV => [XMM14, XMM15],
        X86CallAbi::WindowsX64 => [XMM4, XMM5],
    }
}

fn x86_operand_contains_vreg(operand: &X86ISelOperand, needle: VReg) -> bool {
    match operand {
        X86ISelOperand::VReg(vreg) => *vreg == needle,
        X86ISelOperand::MemAddr { base, .. } => x86_operand_contains_vreg(base, needle),
        X86ISelOperand::SibMemAddr { base, index, .. } => {
            x86_operand_contains_vreg(base, needle) || x86_operand_contains_vreg(index, needle)
        }
        _ => false,
    }
}

fn x86_vreg_has_use(func: &X86ISelFunction, needle: VReg) -> bool {
    func.block_order.iter().any(|block_id| {
        func.blocks.get(block_id).is_some_and(|block| {
            block.insts.iter().any(|inst| {
                inst.operands.iter().enumerate().any(|(idx, operand)| {
                    x86_operand_access(inst, idx).is_use
                        && x86_operand_contains_vreg(operand, needle)
                })
            })
        })
    })
}

fn x86_dead_volatile_load_scratch(class: RegClass, abi: X86CallAbi) -> Option<X86PReg> {
    match class {
        RegClass::Gpr64 => Some(R10),
        RegClass::Gpr32 => Some(R10D),
        RegClass::Fpr32 | RegClass::Fpr64 | RegClass::Fpr128 => {
            Some(x86_spill_xmm_scratch_regs(abi)[0])
        }
        _ => None,
    }
}

fn is_x86_volatile_load(opcode: X86Opcode) -> bool {
    matches!(
        opcode,
        X86Opcode::VolatileMovRM8
            | X86Opcode::VolatileMovRM16
            | X86Opcode::VolatileMovRM32
            | X86Opcode::VolatileMovRM
            | X86Opcode::VolatileMovssRM
            | X86Opcode::VolatileMovsdRM
            | X86Opcode::VolatileMovdquRM
            | X86Opcode::VolatileMovdqaRM
    )
}

/// Give a dead, side-effecting volatile load a reserved post-RA destination.
///
/// The full allocator intentionally omits zero-length (unused) definitions
/// from its allocation map. A volatile read cannot be deleted just because its
/// result is unused, and the encoder cannot accept the unresolved VReg. The
/// spill scratch registers are already excluded from full allocation, so
/// assigning the dead result to the first width-compatible scratch preserves
/// the access without clobbering an allocated value. Simplified allocation
/// assigns every appearing VReg, so it does not need this repair.
fn bind_x86_dead_volatile_load_defs(
    func: &X86ISelFunction,
    allocation: &mut HashMap<VReg, X86PReg>,
    abi: X86CallAbi,
) -> Result<(), X86PipelineError> {
    for block_id in &func.block_order {
        let Some(block) = func.blocks.get(block_id) else {
            continue;
        };
        for inst in &block.insts {
            if !is_x86_volatile_load(inst.opcode) {
                continue;
            }
            let Some(X86ISelOperand::VReg(dst)) = inst.operands.first() else {
                continue;
            };
            if allocation.contains_key(dst) || x86_vreg_has_use(func, *dst) {
                continue;
            }
            let scratch = x86_dead_volatile_load_scratch(dst.class, abi).ok_or_else(|| {
                X86PipelineError::RegAlloc(format!(
                    "cannot preserve dead {:?} destination v{} with class {:?}: \
                     no reserved x86-64 scratch register",
                    inst.opcode, dst.id, dst.class
                ))
            })?;
            allocation.insert(*dst, scratch);
        }
    }
    Ok(())
}

#[allow(dead_code)]
fn x86_spill_slot_size_align(class: RegClass) -> (u32, u32) {
    match class {
        RegClass::Gpr32 | RegClass::Fpr32 => (4, 4),
        RegClass::Fpr128 => (16, 16),
        _ => (8, 8),
    }
}

#[allow(dead_code)]
fn x86_spill_load_opcode(class: RegClass) -> X86Opcode {
    match class {
        RegClass::Gpr32 => X86Opcode::MovRM32,
        RegClass::Fpr32 => X86Opcode::MovssRM,
        RegClass::Fpr64 => X86Opcode::MovsdRM,
        RegClass::Fpr128 => X86Opcode::MovdquRM,
        _ => X86Opcode::MovRM,
    }
}

#[allow(dead_code)]
fn x86_spill_store_opcode(class: RegClass) -> X86Opcode {
    match class {
        RegClass::Gpr32 => X86Opcode::MovMR32,
        RegClass::Fpr32 => X86Opcode::MovssMR,
        RegClass::Fpr64 => X86Opcode::MovsdMR,
        RegClass::Fpr128 => X86Opcode::MovdquMR,
        _ => X86Opcode::MovMR,
    }
}

#[allow(dead_code)]
fn x86_spill_stack_mem(slot: u32) -> X86ISelOperand {
    X86ISelOperand::MemAddr {
        base: Box::new(X86ISelOperand::StackSlot(slot)),
        disp: 0,
    }
}

impl X86RegAssignment {
    /// Perform register assignment on an ISel function.
    ///
    /// This simplified allocator assigns VRegs to physical registers in order
    /// of first appearance. It handles register hints from `MOV vreg, PReg(X)`
    /// patterns: when a VReg is first defined as a copy from a physical register,
    /// it is assigned to that same physical register. This prevents clobbering
    /// arg registers (RDI, RSI, RDX, RCX, R8, R9) before they are read.
    ///
    /// Without hints, `MOV v1, RSI` might assign v1 -> RCX, clobbering the
    /// arg3 register before `MOV v3, RCX` reads it. With hints, v1 -> RSI
    /// so the MOV becomes a nop and RCX is preserved.
    pub fn assign(func: &X86ISelFunction) -> Result<Self, X86PipelineError> {
        Self::assign_with_abi(func, X86CallAbi::SystemV)
    }

    pub fn assign_with_abi(
        func: &X86ISelFunction,
        abi: X86CallAbi,
    ) -> Result<Self, X86PipelineError> {
        let mut allocation: HashMap<VReg, X86PReg> = HashMap::new();
        let mut used_gprs: HashSet<X86PReg> = HashSet::new();
        let mut used_xmms: HashSet<X86PReg> = HashSet::new();
        let mut used_callee_saved: Vec<X86PReg> = Vec::new();
        let mut used_callee_saved_xmms: Vec<X86PReg> = Vec::new();
        let allocatable_gprs = x86_abi_allocatable_gprs(abi);
        let allocatable_xmms = x86_abi_allocatable_xmms(abi);
        let callee_saved_gprs = x86_abi_callee_saved_gprs(abi);
        let callee_saved_xmms = x86_abi_callee_saved_xmms(abi);
        let allocatable_gpr32s = x86_abi_allocatable_gpr32s(abi);
        let reserve_xmm0_for_pblendvb = x86_function_uses_pblendvb_implicit_xmm0(func);

        // Pass 1: Collect register hints from `MOV vreg, PReg(X)` instructions.
        // These are typically argument loads from physical registers.
        let mut hints: HashMap<VReg, X86PReg> = HashMap::new();
        for block in func.block_order.iter() {
            if let Some(mblock) = func.blocks.get(block) {
                for inst in &mblock.insts {
                    let is_reg_copy = matches!(
                        inst.opcode,
                        X86Opcode::MovRR
                            | X86Opcode::MovRR32
                            | X86Opcode::MovsdRR
                            | X86Opcode::MovssRR
                            | X86Opcode::MovdqaRR
                    );
                    if is_reg_copy
                        && inst.operands.len() >= 2
                        && let (X86ISelOperand::VReg(dst), X86ISelOperand::PReg(src)) =
                            (&inst.operands[0], &inst.operands[1])
                    {
                        // Hint: assign dst vreg to src physical register.
                        hints.entry(*dst).or_insert(*src);
                    }
                }
            }
        }

        // Pass 2: Collect all VRegs in order of first appearance.
        let mut vregs: Vec<VReg> = Vec::new();
        for block in func.block_order.iter() {
            if let Some(mblock) = func.blocks.get(block) {
                for inst in &mblock.insts {
                    for op in &inst.operands {
                        if let X86ISelOperand::VReg(v) = op
                            && !vregs.contains(v)
                        {
                            vregs.push(*v);
                        }
                    }
                }
            }
        }

        // Pass 3: Assign hinted vregs first (to claim their preferred registers).
        for vreg in &vregs {
            if let Some(&hint_preg) = hints.get(vreg) {
                let is_allocatable_gpr = allocatable_gprs.contains(&hint_preg)
                    || allocatable_gpr32s.contains(&hint_preg);
                let is_allocatable_xmm = allocatable_xmms.contains(&hint_preg);

                if is_allocatable_gpr && !used_gprs.contains(&hint_preg) {
                    allocation.insert(*vreg, hint_preg);
                    used_gprs.insert(hint_preg);
                    if callee_saved_gprs.contains(&hint_preg)
                        && !used_callee_saved.contains(&hint_preg)
                    {
                        used_callee_saved.push(hint_preg);
                    }
                } else if is_allocatable_xmm
                    && !used_xmms.contains(&hint_preg)
                    && !(reserve_xmm0_for_pblendvb
                        && x86_64_regs::x86_regs_overlap(hint_preg, XMM0))
                {
                    allocation.insert(*vreg, hint_preg);
                    used_xmms.insert(hint_preg);
                    if callee_saved_xmms.contains(&hint_preg)
                        && !used_callee_saved_xmms.contains(&hint_preg)
                    {
                        used_callee_saved_xmms.push(hint_preg);
                    }
                }
                // If the hint can't be satisfied (already taken or not allocatable),
                // the vreg will be assigned in Pass 4.
            }
        }

        // Pass 4: Assign remaining vregs (no hint or hint unsatisfied).
        let mut gpr_idx: usize = 0;
        let mut xmm_idx: usize = 0;
        for vreg in &vregs {
            if allocation.contains_key(vreg) {
                continue; // Already assigned via hint.
            }

            let is_fp = matches!(
                vreg.class,
                RegClass::Fpr32 | RegClass::Fpr64 | RegClass::Fpr128
            );

            if is_fp {
                // Find next available XMM.
                while xmm_idx < allocatable_xmms.len()
                    && (used_xmms.contains(&allocatable_xmms[xmm_idx])
                        || (reserve_xmm0_for_pblendvb
                            && x86_64_regs::x86_regs_overlap(allocatable_xmms[xmm_idx], XMM0)))
                {
                    xmm_idx += 1;
                }
                if xmm_idx < allocatable_xmms.len() {
                    let preg = allocatable_xmms[xmm_idx];
                    allocation.insert(*vreg, preg);
                    used_xmms.insert(preg);
                    if callee_saved_xmms.contains(&preg) && !used_callee_saved_xmms.contains(&preg)
                    {
                        used_callee_saved_xmms.push(preg);
                    }
                    xmm_idx += 1;
                } else {
                    return Err(X86PipelineError::RegAlloc(format!(
                        "ran out of XMM registers for vreg v{}",
                        vreg.id
                    )));
                }
            } else {
                let allocatable_gpr_bank = if vreg.class == RegClass::Gpr32 {
                    &allocatable_gpr32s
                } else {
                    &allocatable_gprs
                };
                // Find next available GPR.
                while gpr_idx < allocatable_gpr_bank.len()
                    && used_gprs.contains(&allocatable_gpr_bank[gpr_idx])
                {
                    gpr_idx += 1;
                }
                if gpr_idx < allocatable_gpr_bank.len() {
                    let preg = allocatable_gpr_bank[gpr_idx];
                    allocation.insert(*vreg, preg);
                    used_gprs.insert(preg);

                    if callee_saved_gprs.contains(&preg) && !used_callee_saved.contains(&preg) {
                        used_callee_saved.push(preg);
                    }

                    gpr_idx += 1;
                } else {
                    return Err(X86PipelineError::RegAlloc(format!(
                        "ran out of GPR registers for vreg v{}",
                        vreg.id
                    )));
                }
            }
        }

        Ok(Self {
            allocation,
            used_callee_saved,
            used_callee_saved_xmms,
            num_spills: 0,
            spill_plan: X86SpillPlan::default(),
        })
    }
}

// ---------------------------------------------------------------------------
// Operand resolution: X86ISelOperand -> X86InstOperands for the encoder
// ---------------------------------------------------------------------------

/// Resolve an ISel operand to a physical register after allocation.
fn resolve_operand(op: &X86ISelOperand, alloc: &HashMap<VReg, X86PReg>) -> Option<X86PReg> {
    match op {
        X86ISelOperand::VReg(v) => alloc.get(v).copied(),
        X86ISelOperand::PReg(p) => Some(*p),
        _ => None,
    }
}

fn resolve_register_or_mem_source_operand(
    op: &X86ISelOperand,
    alloc: &HashMap<VReg, X86PReg>,
    ops: &mut X86InstOperands,
) {
    match op {
        X86ISelOperand::MemAddr { base, disp } => {
            ops.base = resolve_operand(base, alloc);
            ops.disp = i64::from(*disp);
        }
        _ => {
            ops.src = resolve_operand(op, alloc);
        }
    }
}

fn reject_unsupported_x86_isel(
    func: &X86ISelFunction,
    target_features: X86TargetFeatures,
) -> Result<(), X86PipelineError> {
    for block_id in &func.block_order {
        if let Some(block) = func.blocks.get(block_id) {
            for inst in &block.insts {
                reject_unsupported_x86_isel_inst(inst, target_features)?;
            }
        }
    }
    Ok(())
}

fn reject_unsupported_x86_isel_inst(
    inst: &X86ISelInst,
    target_features: X86TargetFeatures,
) -> Result<(), X86PipelineError> {
    reject_unsupported_x86_target_feature_isel_inst(inst, target_features)?;
    reject_unsupported_x86_sib_isel_inst(inst)?;
    reject_unsupported_x86_three_address_rm_alu_isel_inst(inst)?;
    Ok(())
}

fn x86_opcode_required_target_feature(opcode: X86Opcode) -> Option<X86TargetFeature> {
    match opcode {
        X86Opcode::Pinsrd
        | X86Opcode::Pinsrq
        | X86Opcode::Pextrd
        | X86Opcode::Pextrq
        | X86Opcode::Pmulld
        | X86Opcode::Pcmpeqq
        | X86Opcode::Ptest
        | X86Opcode::Pblendvb => Some(X86TargetFeature::Sse41),
        X86Opcode::Pcmpgtq => Some(X86TargetFeature::Sse42),
        X86Opcode::Popcnt => Some(X86TargetFeature::Popcnt),
        _ => None,
    }
}

fn reject_unsupported_x86_target_feature_isel_inst(
    inst: &X86ISelInst,
    target_features: X86TargetFeatures,
) -> Result<(), X86PipelineError> {
    if let Some(feature) = x86_opcode_required_target_feature(inst.opcode)
        && !target_features.contains(feature)
    {
        return Err(X86PipelineError::UnsupportedTargetFeature {
            opcode: inst.opcode,
            feature,
        });
    }
    Ok(())
}

fn reject_unsupported_x86_sib_isel_inst(inst: &X86ISelInst) -> Result<(), X86PipelineError> {
    if matches!(
        inst.opcode,
        X86Opcode::MovRMSib
            | X86Opcode::MovsxdRMSib
            | X86Opcode::MovMRSib
            | X86Opcode::LeaSib
            | X86Opcode::ImulRMSib
            | X86Opcode::MovRM32Sib
            | X86Opcode::MovMR32Sib
            | X86Opcode::MovsdRMSib
            | X86Opcode::MovssRMSib
            | X86Opcode::MovRM8Sib
            | X86Opcode::MovMR8Sib
    ) && !inst
        .operands
        .iter()
        .any(|op| matches!(op, X86ISelOperand::SibMemAddr { .. }))
    {
        return Err(X86PipelineError::ISel(format!(
            "{:?}: SIB ISel opcodes require X86ISelOperand::SibMemAddr carrying base/index/scale/disp",
            inst.opcode
        )));
    }
    Ok(())
}

fn reject_unsupported_x86_three_address_rm_alu_isel_inst(
    inst: &X86ISelInst,
) -> Result<(), X86PipelineError> {
    if matches!(
        inst.opcode,
        X86Opcode::AddRM | X86Opcode::SubRM | X86Opcode::ImulRM | X86Opcode::ImulRMSib
    ) && inst.operands.len() >= 3
    {
        return Err(X86PipelineError::ISel(format!(
            "{:?}: three-address RM ALU ISel operands are not supported; emit two-address form [dst, mem] or insert an explicit MOV before this opcode",
            inst.opcode
        )));
    }
    Ok(())
}

fn resolve_sib_memaddr_operand(
    op: &X86ISelOperand,
    alloc: &HashMap<VReg, X86PReg>,
    ops: &mut X86InstOperands,
) -> bool {
    if let X86ISelOperand::SibMemAddr {
        base,
        index,
        scale,
        disp,
    } = op
    {
        ops.base = resolve_operand(base, alloc);
        ops.index = resolve_operand(index, alloc);
        ops.scale = *scale;
        ops.disp = i64::from(*disp);
        true
    } else {
        false
    }
}

/// Convert an ISel instruction to encoder operands using the register assignment.
fn resolve_inst_operands(inst: &X86ISelInst, alloc: &HashMap<VReg, X86PReg>) -> X86InstOperands {
    let mut ops = X86InstOperands::none();

    match inst.opcode {
        // Pseudo-instructions: no operands needed.
        X86Opcode::Nop
        | X86Opcode::Phi
        | X86Opcode::StackAlloc
        | X86Opcode::V4I32MaskExtract
        | X86Opcode::V16I8MaskExtract
        | X86Opcode::V8I16MaskExtract
        | X86Opcode::V2I64MaskExtract
        | X86Opcode::V128BoolSelect
        // Proof-only bounds-check / null-check / div-zero-check / shift-range-check
        // carriers (Sentinel S5): no encoder operands. Each is expanded to
        // CMP/TEST+Jcc+UD2 (or deleted under kernel authorization) before this
        // point; if one survives to encoding the encoder rejects it
        // (UnsupportedOpcode), so synthesizing no operands here is fail-closed.
        | X86Opcode::TrapBoundsCheckExact
        | X86Opcode::TrapNullIfZeroExact
        | X86Opcode::TrapDivZeroExact
        | X86Opcode::TrapShiftRangeExact => {}

        // CDQ/CQO/MFENCE/UD2: no explicit register operands.
        X86Opcode::Cdq | X86Opcode::Cqo | X86Opcode::Mfence | X86Opcode::Ud2 => {}

        // NopMulti: imm controls NOP size (1-15 bytes)
        X86Opcode::NopMulti => {
            for op in &inst.operands {
                if let X86ISelOperand::Imm(imm) = op {
                    ops.imm = *imm;
                    break;
                }
            }
        }

        // Register-register: [dst, src] or [dst, lhs, rhs] (three-address -> two-address)
        X86Opcode::AddRR
        | X86Opcode::SubRR
        | X86Opcode::AdcRR
        | X86Opcode::SbbRR
        | X86Opcode::AndRR
        | X86Opcode::OrRR
        | X86Opcode::XorRR => {
            // Three-address ISel: [dst, lhs, rhs]
            // x86-64 two-address encoding: dst = lhs op rhs, where dst == lhs.
            // The encoder takes (dst, src) where dst is the first source.
            if inst.operands.len() >= 3 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                ops.src = resolve_operand(&inst.operands[2], alloc);
            } else if inst.operands.len() == 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                ops.src = resolve_operand(&inst.operands[1], alloc);
            }
        }

        // IMUL r64, r64: dst, src (two-operand form)
        X86Opcode::ImulRR => {
            if inst.operands.len() >= 3 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                ops.src = resolve_operand(&inst.operands[2], alloc);
            } else if inst.operands.len() == 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                ops.src = resolve_operand(&inst.operands[1], alloc);
            }
        }

        // CMP: [lhs, rhs] (no destination, just sets flags)
        X86Opcode::CmpRR | X86Opcode::TestRR => {
            if inst.operands.len() >= 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                ops.src = resolve_operand(&inst.operands[1], alloc);
            }
        }

        // CMP r, imm32 / CMP r, imm8
        X86Opcode::CmpRI | X86Opcode::CmpRI8 | X86Opcode::TestRI => {
            if let Some(reg_op) = inst.operands.first() {
                ops.dst = resolve_operand(reg_op, alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::Imm(imm) = op {
                    ops.imm = *imm;
                    break;
                }
            }
        }

        // ALU reg-imm: [dst, imm] or [dst, src, imm]
        X86Opcode::AddRI
        | X86Opcode::SubRI
        | X86Opcode::AndRI
        | X86Opcode::OrRI
        | X86Opcode::XorRI => {
            if let Some(reg_op) = inst.operands.first() {
                ops.dst = resolve_operand(reg_op, alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::Imm(imm) = op {
                    ops.imm = *imm;
                    break;
                }
            }
        }

        // Unary: [dst, src]
        X86Opcode::Neg | X86Opcode::Not | X86Opcode::Inc | X86Opcode::Dec => {
            // dst operand (in-place)
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
        }

        // MOV r, r
        X86Opcode::MovRR | X86Opcode::MovRR32 => {
            if inst.operands.len() >= 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                ops.src = resolve_operand(&inst.operands[1], alloc);
            }
        }

        // MOV r, imm64
        X86Opcode::MovRI => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::Imm(imm) = op {
                    ops.imm = *imm;
                    break;
                }
            }
        }

        // MOV r, [base+disp] (load)
        X86Opcode::MovRM8
        | X86Opcode::MovRM16
        | X86Opcode::MovRM32
        | X86Opcode::MovRM
        | X86Opcode::VolatileMovRM8
        | X86Opcode::VolatileMovRM16
        | X86Opcode::VolatileMovRM32
        | X86Opcode::VolatileMovRM => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::MemAddr { base, disp } = op {
                    ops.base = resolve_operand(base, alloc);
                    ops.disp = *disp as i64;
                    break;
                }
            }
        }

        // MOV [base+disp], r (store)
        X86Opcode::MovMR8
        | X86Opcode::MovMR16
        | X86Opcode::MovMR32
        | X86Opcode::MovMR
        | X86Opcode::VolatileMovMR8
        | X86Opcode::VolatileMovMR16
        | X86Opcode::VolatileMovMR32
        | X86Opcode::VolatileMovMR => {
            // For stores, the encoder expects dst = source register, base = mem base.
            for op in &inst.operands {
                if let X86ISelOperand::MemAddr { base, disp } = op {
                    ops.base = resolve_operand(base, alloc);
                    ops.disp = *disp as i64;
                } else {
                    // The non-memaddr operand is the source register.
                    if ops.dst.is_none() {
                        ops.dst = resolve_operand(op, alloc);
                    }
                }
            }
            // If MemAddr came first, dst might not be set yet.
            if ops.dst.is_none()
                && let Some(last) = inst.operands.last()
            {
                ops.dst = resolve_operand(last, alloc);
            }
        }

        // PUSH / POP: single register
        X86Opcode::Push | X86Opcode::Pop => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
        }

        // RET: no operands
        X86Opcode::Ret => {}

        // JMP rel32: block operand resolved to displacement
        X86Opcode::Jmp => {
            // Block operands are resolved during branch resolution.
            // After resolution, the displacement is stored in the operand.
            for op in &inst.operands {
                if let X86ISelOperand::Imm(imm) = op {
                    ops.disp = *imm;
                    break;
                }
            }
        }

        // Jcc: [cc, block/imm]
        X86Opcode::Jcc => {
            for op in &inst.operands {
                match op {
                    X86ISelOperand::CondCode(cc) => {
                        ops.cc = Some(*cc);
                    }
                    X86ISelOperand::Imm(imm) => {
                        ops.disp = *imm;
                    }
                    _ => {}
                }
            }
        }

        // CALL: symbol (rel32 = 0 placeholder for relocation)
        X86Opcode::Call => {
            ops.disp = 0; // Will be fixed by linker relocation
        }
        X86Opcode::CallR => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
        }
        X86Opcode::CallM => {
            for op in &inst.operands {
                if let X86ISelOperand::MemAddr { base, disp } = op {
                    ops.base = resolve_operand(base, alloc);
                    ops.disp = *disp as i64;
                    break;
                }
            }
        }

        // SSE arithmetic: three-address ISel [dst, lhs, rhs] or two-address [dst, src]
        X86Opcode::Addsd
        | X86Opcode::Subsd
        | X86Opcode::Mulsd
        | X86Opcode::Divsd
        | X86Opcode::Andpd
        | X86Opcode::Addss
        | X86Opcode::Subss
        | X86Opcode::Mulss
        | X86Opcode::Divss
        | X86Opcode::Andps
        | X86Opcode::Pand
        | X86Opcode::Pandn
        | X86Opcode::Por
        | X86Opcode::Pxor
        | X86Opcode::Pcmpeqb
        | X86Opcode::Pcmpeqw
        | X86Opcode::Pcmpgtb
        | X86Opcode::Pcmpgtw
        | X86Opcode::Pcmpeqd
        | X86Opcode::Pcmpgtd
        | X86Opcode::Paddb
        | X86Opcode::Paddw
        | X86Opcode::Paddd
        | X86Opcode::Psubb
        | X86Opcode::Psubw
        | X86Opcode::Psubd
        | X86Opcode::Paddq
        | X86Opcode::Psubq
        | X86Opcode::Pmullw
        | X86Opcode::Pmuludq
        | X86Opcode::Punpcklbw
        | X86Opcode::Punpckldq
        | X86Opcode::Packuswb
        | X86Opcode::Punpckhbw
        | X86Opcode::Punpcklqdq
        | X86Opcode::Pmulld
        // PSADBW: SSE2 horizontal sum-of-absolute-differences (byte-sum), a
        // two-address xmm-xmm producer resolved exactly like the packed ALU ops.
        | X86Opcode::Psadbw
        | X86Opcode::Pcmpeqq
        | X86Opcode::Pcmpgtq
        // SSE/SSE2 packed floating-point arithmetic (`<4 x f32>` / `<2 x f64>`).
        | X86Opcode::Addps
        | X86Opcode::Subps
        | X86Opcode::Mulps
        | X86Opcode::Divps
        | X86Opcode::Addpd
        | X86Opcode::Subpd
        | X86Opcode::Mulpd
        | X86Opcode::Divpd
        // Scalar min/max MINSD/MAXSD/MINSS/MAXSS: same two-address [dst, lhs, rhs]
        // shape as the SSE scalar arithmetic above (dst = lhs op rhs, dst == lhs).
        | X86Opcode::Minsd
        | X86Opcode::Maxsd
        | X86Opcode::Minss
        | X86Opcode::Maxss => {
            // Three-address ISel: [dst, lhs, rhs]
            // x86-64 two-address encoding: dst = lhs op rhs, where dst == lhs.
            // The encoder takes (dst, src) where dst is the first source.
            if inst.operands.len() >= 3 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                resolve_register_or_mem_source_operand(&inst.operands[2], alloc, &mut ops);
            } else if inst.operands.len() == 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                resolve_register_or_mem_source_operand(&inst.operands[1], alloc, &mut ops);
            }
        }

        // SSE2 packed shuffle: [dst, src, imm8]
        X86Opcode::Pshufd => {
            if inst.operands.len() >= 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                resolve_register_or_mem_source_operand(&inst.operands[1], alloc, &mut ops);
            }
            for op in &inst.operands {
                if let X86ISelOperand::Imm(imm) = op {
                    ops.imm = *imm;
                    break;
                }
            }
        }

        // PTEST xmm, xmm/m128: [lhs, rhs] where rhs may be an XMM reg or memory.
        X86Opcode::Ptest => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
            if let Some(rhs) = inst.operands.get(1) {
                match rhs {
                    X86ISelOperand::MemAddr { base, disp } => {
                        ops.base = resolve_operand(base, alloc);
                        ops.disp = *disp as i64;
                    }
                    _ => {
                        ops.src = resolve_operand(rhs, alloc);
                    }
                }
            }
        }

        // SSE4.1 packed lane insert:
        //   [dst, scalar, imm8] or three-address [dst, old_vector, scalar, imm8].
        X86Opcode::Pinsrd | X86Opcode::Pinsrq => {
            if let Some(dst) = inst.operands.first() {
                ops.dst = resolve_operand(dst, alloc);
            }
            let scalar_idx = if inst.operands.len() >= 4 { 2 } else { 1 };
            if let Some(src) = inst.operands.get(scalar_idx) {
                ops.src = resolve_operand(src, alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::Imm(imm) = op {
                    ops.imm = *imm;
                    break;
                }
            }
        }

        // SSE4.1 packed lane extract: [dst_gpr, src_xmm, imm8].
        X86Opcode::Pextrd | X86Opcode::Pextrq => {
            if inst.operands.len() >= 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                ops.src = resolve_operand(&inst.operands[1], alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::Imm(imm) = op {
                    ops.imm = *imm;
                    break;
                }
            }
        }

        // SSE4.1 scalar round-to-integral: [dst_xmm, src_xmm, imm8].
        X86Opcode::Roundsd | X86Opcode::Roundss => {
            if inst.operands.len() >= 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                ops.src = resolve_operand(&inst.operands[1], alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::Imm(imm) = op {
                    ops.imm = *imm;
                    break;
                }
            }
        }

        // SSE scalar compare-to-mask CMPSD/CMPSS: two-address with imm8 predicate.
        // ISel emits the three-address [dst, lhs, rhs, imm8]; the two-address
        // fixup makes dst == lhs, so the encoder takes (dst=lhs, src=rhs, imm).
        X86Opcode::Cmpsd | X86Opcode::Cmpss => {
            if inst.operands.len() >= 3 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                resolve_register_or_mem_source_operand(&inst.operands[2], alloc, &mut ops);
            } else if inst.operands.len() == 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                resolve_register_or_mem_source_operand(&inst.operands[1], alloc, &mut ops);
            }
            for op in &inst.operands {
                if let X86ISelOperand::Imm(imm) = op {
                    ops.imm = *imm;
                    break;
                }
            }
        }

        // SSE moves and compares: always [dst, src]
        X86Opcode::MovsdRR
        | X86Opcode::MovssRR
        | X86Opcode::MovdqaRR
        | X86Opcode::Pblendvb
        | X86Opcode::Pmovmskb
        | X86Opcode::Sqrtsd
        | X86Opcode::Sqrtss
        | X86Opcode::Ucomisd
        | X86Opcode::Ucomiss => {
            if inst.operands.len() >= 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                ops.src = resolve_operand(&inst.operands[1], alloc);
            }
        }

        // SSE RIP-relative constant pool load: [dst, ConstPoolEntry(idx)]
        // The disp field stores the constant pool entry index as a placeholder.
        // The actual RIP-relative displacement is fixed up after encoding.
        X86Opcode::MovssRipRel | X86Opcode::MovsdRipRel => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
            // Extract constant pool entry index from operands.
            for op in &inst.operands {
                if let X86ISelOperand::ConstPoolEntry(idx) = op {
                    // Store the entry index in imm for now; the pipeline will
                    // convert this to a proper RIP-relative displacement during
                    // the constant pool fixup phase.
                    ops.imm = *idx as i64;
                    break;
                }
            }
        }

        // Shifts: [dst, imm] or [dst]
        X86Opcode::ShlRI
        | X86Opcode::ShrRI
        | X86Opcode::SarRI
        | X86Opcode::RolRI
        | X86Opcode::Pslld
        | X86Opcode::Psrld
        | X86Opcode::Psrad
        | X86Opcode::Psllq
        | X86Opcode::Psrlq => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::Imm(imm) = op {
                    ops.imm = *imm;
                    break;
                }
            }
        }
        X86Opcode::ShlRR | X86Opcode::ShrRR | X86Opcode::SarRR => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
        }

        // LEA, MOVZX, MOVSX, etc. — handle generically
        X86Opcode::Lea => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::MemAddr { base, disp } = op {
                    ops.base = resolve_operand(base, alloc);
                    ops.disp = *disp as i64;
                    break;
                }
            }
        }
        X86Opcode::Movzx
        | X86Opcode::MovzxW
        | X86Opcode::MovsxB
        | X86Opcode::MovsxW
        | X86Opcode::Movsx => {
            if inst.operands.len() >= 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                ops.src = resolve_operand(&inst.operands[1], alloc);
            }
        }

        // CMOVcc, SETcc
        X86Opcode::Cmovcc | X86Opcode::Cmovcc32 => {
            if inst.operands.len() >= 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                ops.src = resolve_operand(&inst.operands[1], alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::CondCode(cc) = op {
                    ops.cc = Some(*cc);
                    break;
                }
            }
        }
        X86Opcode::Setcc => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::CondCode(cc) = op {
                    ops.cc = Some(*cc);
                    break;
                }
            }
        }

        // Bit manipulation: [dst, src]
        X86Opcode::Bsf
        | X86Opcode::Bsr
        | X86Opcode::Tzcnt
        | X86Opcode::Lzcnt
        | X86Opcode::Popcnt => {
            if inst.operands.len() >= 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                ops.src = resolve_operand(&inst.operands[1], alloc);
            }
        }

        // BT r, imm8: [reg, imm]
        X86Opcode::BtRI => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::Imm(imm) = op {
                    ops.imm = *imm;
                    break;
                }
            }
        }

        // BSWAP: single register [dst]
        X86Opcode::Bswap => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
        }

        // XCHG, CMPXCHG: register-register [dst, src] or memory [reg, mem].
        // The narrow CMPXCHG forms share the memory shape (reg + mem).
        X86Opcode::Xchg | X86Opcode::Cmpxchg | X86Opcode::Cmpxchg8 | X86Opcode::Cmpxchg16 => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::MemAddr { base, disp } = op {
                    ops.base = resolve_operand(base, alloc);
                    ops.disp = *disp as i64;
                    break;
                }
            }
            if ops.base.is_none() && inst.operands.len() >= 2 {
                ops.src = resolve_operand(&inst.operands[1], alloc);
            }
        }

        // AtomicRmwCasLoop pseudo: [dst, value, mem, op-kind].
        X86Opcode::AtomicRmwCasLoop
        | X86Opcode::AtomicRmwCasLoop8
        | X86Opcode::AtomicRmwCasLoop16 => {
            if inst.operands.len() >= 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                ops.src = resolve_operand(&inst.operands[1], alloc);
            }
            for op in &inst.operands {
                match op {
                    X86ISelOperand::MemAddr { base, disp } => {
                        ops.base = resolve_operand(base, alloc);
                        ops.disp = *disp as i64;
                    }
                    X86ISelOperand::Imm(imm) => {
                        ops.imm = *imm;
                    }
                    _ => {}
                }
            }
        }

        // GPR <-> XMM transfers: [dst, src]
        X86Opcode::MovdToXmm
        | X86Opcode::MovdFromXmm
        | X86Opcode::MovqToXmm
        | X86Opcode::MovqFromXmm => {
            if inst.operands.len() >= 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                ops.src = resolve_operand(&inst.operands[1], alloc);
            }
        }

        // IDIV/DIV, IMUL 3-operand, etc.
        X86Opcode::Idiv | X86Opcode::Div | X86Opcode::Mul => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
        }
        X86Opcode::ImulRRI => {
            if inst.operands.len() >= 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                ops.src = resolve_operand(&inst.operands[1], alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::Imm(imm) = op {
                    ops.imm = *imm;
                    break;
                }
            }
        }

        // Memory forms
        X86Opcode::AddRM
        | X86Opcode::SubRM
        | X86Opcode::CmpRM
        | X86Opcode::ImulRM
        | X86Opcode::TestRM => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::MemAddr { base, disp } = op {
                    ops.base = resolve_operand(base, alloc);
                    ops.disp = *disp as i64;
                    break;
                }
            }
        }

        // SSE memory forms
        X86Opcode::MovsdRM
        | X86Opcode::MovssRM
        | X86Opcode::MovdquRM
        | X86Opcode::MovdqaRM
        | X86Opcode::VolatileMovssRM
        | X86Opcode::VolatileMovsdRM
        | X86Opcode::VolatileMovdquRM
        | X86Opcode::VolatileMovdqaRM => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::MemAddr { base, disp } = op {
                    ops.base = resolve_operand(base, alloc);
                    ops.disp = *disp as i64;
                    break;
                }
            }
        }
        X86Opcode::MovsdMR
        | X86Opcode::MovssMR
        | X86Opcode::MovdquMR
        | X86Opcode::MovdqaMR
        | X86Opcode::VolatileMovssMR
        | X86Opcode::VolatileMovsdMR
        | X86Opcode::VolatileMovdquMR
        | X86Opcode::VolatileMovdqaMR => {
            for op in &inst.operands {
                if let X86ISelOperand::MemAddr { base, disp } = op {
                    ops.base = resolve_operand(base, alloc);
                    ops.disp = *disp as i64;
                } else if ops.dst.is_none() {
                    ops.dst = resolve_operand(op, alloc);
                }
            }
        }

        // SSE type conversion: [dst, src]
        X86Opcode::Cvtsi2sd
        | X86Opcode::Cvtsd2si
        | X86Opcode::Cvttsd2si
        | X86Opcode::Cvtsi2ss
        | X86Opcode::Cvtss2si
        | X86Opcode::Cvttss2si
        | X86Opcode::Cvtsd2ss
        | X86Opcode::Cvtss2sd => {
            if inst.operands.len() >= 2 {
                ops.dst = resolve_operand(&inst.operands[0], alloc);
                ops.src = resolve_operand(&inst.operands[1], alloc);
            }
        }

        // RIP-relative symbol/slot materialization: [dst, disp/symbol]
        X86Opcode::LeaRip | X86Opcode::MovRipRel | X86Opcode::MovRipRelTlv => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
            for op in &inst.operands {
                if let X86ISelOperand::Imm(imm) = op {
                    ops.disp = *imm;
                    break;
                }
            }
        }

        // Scaled-index memory: [dst/src, base, index, scale, disp]
        X86Opcode::MovRMSib
        | X86Opcode::MovsxdRMSib
        | X86Opcode::LeaSib
        | X86Opcode::ImulRMSib
        | X86Opcode::MovRM32Sib
        | X86Opcode::MovsdRMSib
        | X86Opcode::MovssRMSib
        | X86Opcode::MovRM8Sib => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
            for op in &inst.operands {
                if resolve_sib_memaddr_operand(op, alloc, &mut ops) {
                    break;
                }
            }
        }
        X86Opcode::MovMRSib | X86Opcode::MovMR32Sib | X86Opcode::MovMR8Sib => {
            for op in &inst.operands {
                if resolve_sib_memaddr_operand(op, alloc, &mut ops) {
                    continue;
                }
                if ops.dst.is_none() {
                    ops.dst = resolve_operand(op, alloc);
                }
            }
        }

        // Indirect near jump through a register (jump-table dispatch). The single
        // operand is the target VReg; resolve it into the ModRM.rm (`dst`) slot,
        // exactly like CallR (both are FF /r register-indirect transfers).
        X86Opcode::JmpR => {
            if let Some(op) = inst.operands.first() {
                ops.dst = resolve_operand(op, alloc);
            }
        }
    }

    ops
}

/// Fetch boundary for Intel's JCC erratum (doc 334524).
const X86_JCC_BOUNDARY: usize = 32;

/// Is padding for the JCC erratum enabled? Kill switch `TCG_NO_X86_JCC_ALIGN=1`.
///
/// ⚑ THIS FLAG ALSO CONTROLS FUNCTION AND SECTION ALIGNMENT, and it has to.
/// The erratum is a property of the ABSOLUTE address, but everything the pass
/// can see is `encoder.position()` — an offset relative to the START OF THE
/// FUNCTION. Those coincide only when every function begins on a 32-byte
/// boundary, which needs all three of:
///
///   1. this padding pass,
///   2. per-function 32-byte padding in `combined_code`,
///   3. a `__text` section alignment of 2^5 (see `x86_text_align_log2`).
///
/// With only (1), the pass was measured HALF-EFFECTIVE: function starts are
/// 16-byte aligned by default, landing at `0 mod 32` and `16 mod 32` in nearly
/// equal numbers (221 vs 215 in one binary), and on the `16 mod 32` half it
/// aligned to the WRONG grid. p4_matmul went 12 -> 10 hazards — the signature of
/// "fixed the aligned half". All three must move together or none should.
///
/// Padding is semantically neutral (multi-byte NOPs), so the cost of being
/// wrong here is size and speed, never correctness.
fn x86_jcc_align_enabled() -> bool {
    !crate::env_lock::var_os("TCG_NO_X86_JCC_ALIGN").is_some_and(|v| v != "0")
}

/// Branch forms the erratum applies to: conditional jump, direct and indirect
/// unconditional jump, direct and indirect call, and return.
///
/// Exhaustive over the opcode enum on purpose — a `matches!` allowlist here
/// would silently stop covering a newly added branch form, and this pass can
/// only be observed through its ACCEPT counter.
fn x86_is_erratum_branch(opcode: X86Opcode) -> bool {
    match opcode {
        X86Opcode::Jcc
        | X86Opcode::Jmp
        | X86Opcode::JmpR
        | X86Opcode::Call
        | X86Opcode::CallM
        | X86Opcode::CallR
        | X86Opcode::Ret => true,
        _ => false,
    }
}

/// Integer flag-setters that macro-fuse with an immediately following `Jcc` on
/// Skylake-family cores.
///
/// ⚑ A fused pair counts as ONE instruction STARTING AT THE ALU, so the hazard
/// depends on where the ALU landed, not the branch. Aligning only the `Jcc`
/// would leave the pair straddling a boundary and fix nothing — which is why
/// this list exists at all.
///
/// Deliberately over-inclusive: SKL fuses ADD/SUB/AND/INC/DEC only with a
/// subset of conditions, but treating them all as fusible costs at most a few
/// padding bytes, while missing one costs the whole 28.5%.
fn x86_is_macro_fusible_alu(opcode: X86Opcode) -> bool {
    match opcode {
        X86Opcode::CmpRR
        | X86Opcode::CmpRI
        | X86Opcode::CmpRI8
        | X86Opcode::CmpRM
        | X86Opcode::TestRR
        | X86Opcode::TestRI
        | X86Opcode::TestRM
        | X86Opcode::AddRR
        | X86Opcode::AddRI
        | X86Opcode::AddRM
        | X86Opcode::SubRR
        | X86Opcode::SubRI
        | X86Opcode::SubRM
        | X86Opcode::AndRR
        | X86Opcode::AndRI
        | X86Opcode::Inc
        | X86Opcode::Dec => true,
        _ => false,
    }
}

/// Exact encoded length, obtained by encoding into a scratch buffer.
///
/// ⚑ NOT `estimate_inst_size`, which is documented conservative (`_ => 7`).
/// Padding computed from an estimate would mis-place the very boundary it is
/// trying to avoid. Branch displacements are fixed-width rel32 here and are
/// patched after the fact, so an instruction's LENGTH does not depend on its
/// position and this probe is exact.
fn x86_encoded_len(opcode: X86Opcode, ops: &X86InstOperands) -> Option<usize> {
    let mut probe = X86Encoder::new();
    probe.encode_instruction(opcode, ops).ok()?;
    Some(probe.position())
}

/// Padding needed before the alignment unit starting at `pos`, or `None`.
///
/// The unit is the macro-fused `ALU + Jcc` pair when one starts here, otherwise
/// the single branch. Returns `Some(n)` only when emitting `n` bytes of NOP
/// moves the unit off a 32-byte boundary crossing.
fn x86_jcc_erratum_pad(
    pos: usize,
    opcode: X86Opcode,
    ops: &X86InstOperands,
    insts: &[X86ISelInst],
    inst_idx: usize,
    alloc: &HashMap<VReg, X86PReg>,
) -> Option<usize> {
    let mut unit_len = x86_encoded_len(opcode, ops)?;
    let trace = crate::env_lock::var_os("TCG_X86_JCC_ALIGN_TRACE").is_some();

    if !x86_is_erratum_branch(opcode) {
        // Only a fusible ALU whose next EMITTED instruction is a Jcc forms a unit.
        if !x86_is_macro_fusible_alu(opcode) {
            return None;
        }
        let Some(next) = insts[inst_idx + 1..].iter().find(|later| {
            !matches!(
                later.opcode,
                X86Opcode::Nop | X86Opcode::Phi | X86Opcode::StackAlloc
            )
        }) else {
            if trace {
                eprintln!(
                    "[jcc-trace] fusible {opcode:?} at idx {inst_idx}: NO next inst in block"
                );
            }
            return None;
        };
        let next_ops = resolve_inst_operands(next, alloc);
        let next_opcode = resolved_encode_opcode(next, &next_ops);
        if next_opcode != X86Opcode::Jcc {
            if trace {
                eprintln!(
                    "[jcc-trace] fusible {opcode:?} at idx {inst_idx}: next is {next_opcode:?}, not Jcc"
                );
            }
            return None;
        }
        unit_len += x86_encoded_len(next_opcode, &next_ops)?;
    }

    // A unit that cannot fit inside one 32-byte block is unavoidable; padding
    // would only add bytes. (Also makes the arithmetic below total.)
    if unit_len == 0 || unit_len >= X86_JCC_BOUNDARY {
        return None;
    }

    let last = pos + unit_len - 1;
    let crosses = pos / X86_JCC_BOUNDARY != last / X86_JCC_BOUNDARY;
    let ends_on_boundary = (last + 1) % X86_JCC_BOUNDARY == 0;
    if !crosses && !ends_on_boundary {
        return None;
    }

    let pad = X86_JCC_BOUNDARY - (pos % X86_JCC_BOUNDARY);
    if pad == 0 || pad >= X86_JCC_BOUNDARY {
        // `pos` was already aligned; with unit_len < 32 it cannot have crossed,
        // so reaching here would mean the hazard is not fixable by padding.
        return None;
    }
    Some(pad)
}

fn resolved_encode_opcode(inst: &X86ISelInst, ops: &X86InstOperands) -> X86Opcode {
    if inst.opcode == X86Opcode::MovRR
        && matches!((ops.dst, ops.src), (Some(dst), Some(src)) if dst.is_gpr32() && src.is_gpr32())
    {
        X86Opcode::MovRR32
    } else {
        inst.opcode
    }
}

// ---------------------------------------------------------------------------
// Two-address fixup pass
// ---------------------------------------------------------------------------

/// Returns `true` if the given opcode is an x86-64 register-register ALU
/// instruction that uses two-address form (dst is both read and written).
///
/// When ISel emits three-address form `OP v2, v0, v1` (where v2 != v0), we
/// must insert `MOV v2, v0` before the instruction so that the destination
/// register contains the correct first-source value.
///
/// This only covers RR (register-register) opcodes that can appear in
/// three-address form from ISel. Other explicit-source pseudo forms are
/// handled by `x86_two_address_lhs_operand_index`.
fn is_x86_two_address_rr(opcode: X86Opcode) -> bool {
    matches!(
        opcode,
        X86Opcode::AddRR
            | X86Opcode::SubRR
            | X86Opcode::AdcRR
            | X86Opcode::SbbRR
            | X86Opcode::AndRR
            | X86Opcode::OrRR
            | X86Opcode::XorRR
            | X86Opcode::ImulRR
            // SSE scalar arithmetic (may appear in three-address form)
            | X86Opcode::Addsd
            | X86Opcode::Subsd
            | X86Opcode::Mulsd
            | X86Opcode::Divsd
            | X86Opcode::Andpd
            | X86Opcode::Addss
            | X86Opcode::Subss
            | X86Opcode::Mulss
            | X86Opcode::Divss
            | X86Opcode::Andps
            // SSE2 packed integer two-address forms
            | X86Opcode::Pand
            | X86Opcode::Pandn
            | X86Opcode::Por
            | X86Opcode::Pxor
            | X86Opcode::Pcmpeqb
            | X86Opcode::Pcmpeqw
            | X86Opcode::Pcmpgtb
            | X86Opcode::Pcmpgtw
            | X86Opcode::Pcmpeqd
            | X86Opcode::Pcmpgtd
            | X86Opcode::Paddb
            | X86Opcode::Paddw
            | X86Opcode::Paddd
            | X86Opcode::Psubb
            | X86Opcode::Psubw
            | X86Opcode::Psubd
            | X86Opcode::Paddq
            | X86Opcode::Psubq
            | X86Opcode::Pmullw
            | X86Opcode::Pmuludq
            | X86Opcode::Punpcklbw
            | X86Opcode::Punpckldq
            | X86Opcode::Packuswb
            | X86Opcode::Punpckhbw
            | X86Opcode::Punpcklqdq
            | X86Opcode::Pmulld
            // PSADBW dst = SAD(dst, src): dst is read+written (two-address).
            | X86Opcode::Psadbw
            | X86Opcode::Pcmpeqq
            | X86Opcode::Pcmpgtq
            // SSE/SSE2 packed floating-point arithmetic two-address forms.
            | X86Opcode::Addps
            | X86Opcode::Subps
            | X86Opcode::Mulps
            | X86Opcode::Divps
            | X86Opcode::Addpd
            | X86Opcode::Subpd
            | X86Opcode::Mulpd
            | X86Opcode::Divpd
            // SSE scalar min/max + compare-to-mask (NaN-away min/max idiom).
            // Two-address (dst is also the first source). NOT commutative: the
            // hardware MINSD/MAXSD return the SECOND operand on unordered/equal,
            // so swapping operands changes the NaN/±0 result.
            | X86Opcode::Minsd
            | X86Opcode::Maxsd
            | X86Opcode::Minss
            | X86Opcode::Maxss
            | X86Opcode::Cmpsd
            | X86Opcode::Cmpss
    )
}

fn is_x86_commutative_two_address_rr(opcode: X86Opcode) -> bool {
    matches!(
        opcode,
        X86Opcode::AddRR
            | X86Opcode::AndRR
            | X86Opcode::OrRR
            | X86Opcode::XorRR
            | X86Opcode::ImulRR
            | X86Opcode::Addsd
            | X86Opcode::Mulsd
            | X86Opcode::Andpd
            | X86Opcode::Addss
            | X86Opcode::Mulss
            | X86Opcode::Andps
            | X86Opcode::Pand
            | X86Opcode::Por
            | X86Opcode::Pxor
            | X86Opcode::Pcmpeqb
            | X86Opcode::Pcmpeqw
            | X86Opcode::Pcmpeqd
            | X86Opcode::Paddb
            | X86Opcode::Paddw
            | X86Opcode::Paddd
            | X86Opcode::Paddq
            | X86Opcode::Pmullw
            | X86Opcode::Pmuludq
            | X86Opcode::Pmulld
            | X86Opcode::Pcmpeqq
            // Packed FP add/multiply are commutative (a+b == b+a, a*b == b*a;
            // both lanes including NaN agree under operand swap).
            | X86Opcode::Addps
            | X86Opcode::Mulps
            | X86Opcode::Addpd
            | X86Opcode::Mulpd
    )
}

fn is_x86_three_address_ri(opcode: X86Opcode) -> bool {
    matches!(
        opcode,
        X86Opcode::AddRI | X86Opcode::SubRI | X86Opcode::AndRI | X86Opcode::OrRI | X86Opcode::XorRI
    )
}

fn is_x86_shift_ri(opcode: X86Opcode) -> bool {
    matches!(
        opcode,
        X86Opcode::ShlRI
            | X86Opcode::ShrRI
            | X86Opcode::SarRI
            | X86Opcode::RolRI
            | X86Opcode::Pslld
            | X86Opcode::Psrld
            | X86Opcode::Psrad
            | X86Opcode::Psllq
            | X86Opcode::Psrlq
    )
}

fn is_x86_shift_rr(opcode: X86Opcode) -> bool {
    matches!(
        opcode,
        X86Opcode::ShlRR | X86Opcode::ShrRR | X86Opcode::SarRR
    )
}

fn is_x86_explicit_source_unary(opcode: X86Opcode) -> bool {
    matches!(opcode, X86Opcode::Neg | X86Opcode::Not)
}

fn x86_two_address_lhs_operand_index(inst: &X86ISelInst) -> Option<usize> {
    if matches!(inst.opcode, X86Opcode::Pinsrd | X86Opcode::Pinsrq) && inst.operands.len() >= 4 {
        return Some(1);
    }

    if inst.operands.len() >= 3
        && (is_x86_two_address_rr(inst.opcode)
            || is_x86_three_address_ri(inst.opcode)
            || is_x86_shift_ri(inst.opcode))
    {
        return Some(1);
    }

    if inst.operands.len() == 2
        && (is_x86_shift_rr(inst.opcode) || is_x86_explicit_source_unary(inst.opcode))
    {
        return Some(1);
    }

    None
}

fn x86_two_address_fixup_copy_opcode(inst: &X86ISelInst) -> X86Opcode {
    match inst.opcode {
        X86Opcode::Addss
        | X86Opcode::Subss
        | X86Opcode::Mulss
        | X86Opcode::Divss
        | X86Opcode::Minss
        | X86Opcode::Maxss
        | X86Opcode::Cmpss => X86Opcode::MovssRR,
        X86Opcode::Addsd
        | X86Opcode::Subsd
        | X86Opcode::Mulsd
        | X86Opcode::Divsd
        | X86Opcode::Minsd
        | X86Opcode::Maxsd
        | X86Opcode::Cmpsd => X86Opcode::MovsdRR,
        X86Opcode::Pand
        | X86Opcode::Pandn
        | X86Opcode::Por
        | X86Opcode::Pxor
        | X86Opcode::Pcmpeqb
        | X86Opcode::Pcmpeqw
        | X86Opcode::Pcmpgtb
        | X86Opcode::Pcmpgtw
        | X86Opcode::Pcmpeqd
        | X86Opcode::Pcmpgtd
        | X86Opcode::Paddb
        | X86Opcode::Paddw
        | X86Opcode::Paddd
        | X86Opcode::Psubb
        | X86Opcode::Psubw
        | X86Opcode::Psubd
        | X86Opcode::Paddq
        | X86Opcode::Psubq
        | X86Opcode::Pmullw
        | X86Opcode::Pmuludq
        | X86Opcode::Punpcklbw
        | X86Opcode::Punpckldq
        | X86Opcode::Packuswb
        | X86Opcode::Punpckhbw
        | X86Opcode::Punpcklqdq
        | X86Opcode::Pmulld
        // PSADBW lives in XMM (Fpr128); its two-address fixup copies the full
        // 128-bit register via MovdqaRR, same as the packed ALU ops.
        | X86Opcode::Psadbw
        | X86Opcode::Pcmpeqq
        | X86Opcode::Pcmpgtq
        | X86Opcode::Pinsrd
        | X86Opcode::Pinsrq
        | X86Opcode::Pslld
        | X86Opcode::Psrld
        | X86Opcode::Psrad
        | X86Opcode::Psllq
        | X86Opcode::Psrlq
        // Packed FP ops live in XMM (Fpr128); copy the full 128-bit register.
        | X86Opcode::Addps
        | X86Opcode::Subps
        | X86Opcode::Mulps
        | X86Opcode::Divps
        | X86Opcode::Addpd
        | X86Opcode::Subpd
        | X86Opcode::Mulpd
        | X86Opcode::Divpd
        // ANDPS/ANDPD are packed bitwise instructions even when ISel uses
        // them to implement scalar fabs.  Hardware reads the complete XMM
        // source, so a scalar MOVSS/MOVSD bridge cannot establish the tied
        // value for the untouched upper lanes.
        | X86Opcode::Andps
        | X86Opcode::Andpd => X86Opcode::MovdqaRR,
        _ => {
            if matches!(inst.operands.first(), Some(X86ISelOperand::VReg(vreg)) if vreg.class == RegClass::Gpr32)
            {
                X86Opcode::MovRR32
            } else {
                X86Opcode::MovRR
            }
        }
    }
}

fn x86_two_address_fixup_scratch_class(inst: &X86ISelInst) -> Option<RegClass> {
    match x86_two_address_fixup_copy_opcode(inst) {
        X86Opcode::MovRR32 => Some(RegClass::Gpr32),
        X86Opcode::MovRR => Some(RegClass::Gpr64),
        X86Opcode::MovssRR => Some(RegClass::Fpr32),
        X86Opcode::MovsdRR => Some(RegClass::Fpr64),
        X86Opcode::MovdqaRR => Some(RegClass::Fpr128),
        _ => None,
    }
}

fn push_unique_x86_scratch_candidate(dst: &mut Vec<X86PReg>, preg: X86PReg) {
    if !dst.contains(&preg) {
        dst.push(preg);
    }
}

fn x86_two_address_scratch_candidates(class: RegClass, abi: X86CallAbi) -> Vec<X86PReg> {
    let mut candidates = Vec::new();
    match x86_reg_bank_for_class(class) {
        Some(X86RegBank::Gpr) => {
            for reg in x86_spill_gpr_scratch_regs(class) {
                push_unique_x86_scratch_candidate(&mut candidates, reg);
            }
        }
        Some(X86RegBank::Xmm) => {
            for reg in x86_spill_xmm_scratch_regs(abi) {
                push_unique_x86_scratch_candidate(&mut candidates, reg);
            }
            let fallback: &[X86PReg] = match abi {
                X86CallAbi::SystemV => &X86_ALLOCATABLE_XMMS,
                X86CallAbi::WindowsX64 => &[
                    x86_64_regs::XMM5,
                    x86_64_regs::XMM4,
                    x86_64_regs::XMM3,
                    x86_64_regs::XMM2,
                    x86_64_regs::XMM1,
                    x86_64_regs::XMM0,
                ],
            };
            for reg in fallback {
                push_unique_x86_scratch_candidate(&mut candidates, *reg);
            }
        }
        None => {}
    }
    candidates
}

fn x86_preg_overlaps_any(preg: X86PReg, regs: &[X86PReg]) -> bool {
    regs.iter()
        .any(|other| x86_64_regs::x86_regs_overlap(preg, *other))
}

fn select_x86_two_address_scratch(
    inst: &X86ISelInst,
    alloc: &HashMap<VReg, X86PReg>,
    abi: X86CallAbi,
    forbidden: &[X86PReg],
) -> Option<X86PReg> {
    let class = x86_two_address_fixup_scratch_class(inst)?;
    x86_two_address_scratch_candidates(class, abi)
        .into_iter()
        .find(|candidate| {
            !x86_preg_overlaps_any(*candidate, forbidden)
                && !alloc
                    .values()
                    .any(|allocated| x86_64_regs::x86_regs_overlap(*candidate, *allocated))
        })
}

fn x86_requires_noncommutative_rhs_alias_scratch(
    inst: &X86ISelInst,
    dst_preg: X86PReg,
    lhs_preg: X86PReg,
    rhs_preg: X86PReg,
) -> bool {
    inst.operands.len() >= 3
        && is_x86_two_address_rr(inst.opcode)
        && !is_x86_commutative_two_address_rr(inst.opcode)
        && !x86_64_regs::x86_regs_overlap(dst_preg, lhs_preg)
        && x86_64_regs::x86_regs_overlap(dst_preg, rhs_preg)
}

/// Two-address fixup pass: insert MOV copies before two-address instructions
/// when `dst != first_src`.
///
/// x86-64 ALU instructions use two-address form: `ADD dst, src` means
/// `dst = dst + src`. When ISel emits three-address `ADD v2, v0, v1`,
/// the register allocator may assign v2 and v0 to different physical
/// registers. Without this pass, `ADD preg(v2), preg(v1)` would compute
/// `preg(v2) = preg(v2) + preg(v1)` — using whatever garbage was in
/// preg(v2) instead of v0's value.
///
/// The fix: for each three-address two-address instruction where
/// `preg(dst) != preg(lhs)`, insert `MOV dst, lhs` to initialize the
/// destination register before the ALU operation.
///
/// Reference: x86_adapter.rs `is_two_address_opcode()` and `TiedOperand`.
fn fixup_two_address(
    func: &mut X86ISelFunction,
    alloc: &HashMap<VReg, X86PReg>,
    abi: X86CallAbi,
) -> Result<usize, X86PipelineError> {
    let mut copy_count = 0;
    for block_id in func.block_order.clone() {
        if let Some(block) = func.blocks.get_mut(&block_id) {
            let mut new_insts = Vec::with_capacity(block.insts.len() + block.insts.len() / 4);

            for inst in &block.insts {
                let lhs_operand_index = x86_two_address_lhs_operand_index(inst);
                let mut fixed_inst = inst.clone();

                if let Some(lhs_operand_index) = lhs_operand_index {
                    let dst_op = &inst.operands[0];
                    let lhs_op = &inst.operands[lhs_operand_index];
                    if let (Some(dst_preg), Some(lhs_preg)) = (
                        resolve_operand(dst_op, alloc),
                        resolve_operand(lhs_op, alloc),
                    ) && !x86_64_regs::x86_regs_overlap(dst_preg, lhs_preg)
                    {
                        if is_x86_two_address_rr(inst.opcode)
                            && let Some(rhs_preg) = resolve_operand(&inst.operands[2], alloc)
                            && x86_64_regs::x86_regs_overlap(dst_preg, rhs_preg)
                            && is_x86_commutative_two_address_rr(inst.opcode)
                        {
                            fixed_inst.operands.swap(1, 2);
                        } else if is_x86_two_address_rr(inst.opcode)
                            && let Some(rhs_preg) = resolve_operand(&inst.operands[2], alloc)
                            && x86_requires_noncommutative_rhs_alias_scratch(
                                inst, dst_preg, lhs_preg, rhs_preg,
                            )
                        {
                            let scratch = select_x86_two_address_scratch(
                                inst,
                                alloc,
                                abi,
                                &[dst_preg, lhs_preg, rhs_preg],
                            )
                            .ok_or_else(|| {
                                X86PipelineError::RegAlloc(format!(
                                    "x86-64 two-address fixup for {:?} cannot repair dst/rhs alias without a free scratch register",
                                    inst.opcode
                                ))
                            })?;
                            let scratch_op = X86ISelOperand::PReg(scratch);
                            let copy_opcode = x86_two_address_fixup_copy_opcode(inst);
                            new_insts.push(X86ISelInst::new(
                                copy_opcode,
                                vec![scratch_op.clone(), lhs_op.clone()],
                            ));
                            copy_count += 1;
                            fixed_inst.operands[0] = scratch_op.clone();
                            fixed_inst.operands[lhs_operand_index] = scratch_op.clone();
                            new_insts.push(fixed_inst);
                            new_insts.push(X86ISelInst::new(
                                copy_opcode,
                                vec![dst_op.clone(), scratch_op],
                            ));
                            copy_count += 1;
                            continue;
                        } else {
                            // Select the correct MOV opcode based on whether
                            // this is an SSE (float) or GPR (integer) operation.
                            // Insert MOV dst, lhs to copy the first source into dst.
                            new_insts.push(X86ISelInst::new(
                                x86_two_address_fixup_copy_opcode(inst),
                                vec![dst_op.clone(), lhs_op.clone()],
                            ));
                            copy_count += 1;
                        }
                    }
                }

                new_insts.push(fixed_inst);
            }

            block.insts = new_insts;
        }
    }
    Ok(copy_count)
}

// ---------------------------------------------------------------------------
// Post-fixup redundant-`MovRR` copy coalescing (runtime performance)
// ---------------------------------------------------------------------------
//
// After two-address fixup the stream can contain redundant 64-bit `movq %src,
// %dst` scratch copies that the pre-RA interference coalescer cannot remove:
// when a value (e.g. a loop counter in `%rbx`) is CSE'd into a scratch that the
// allocator places in a DIFFERENT physical register (`%rax`), the copy source
// and destination are BOTH live across the copy, so they interfere and cannot
// be interference-coalesced. Removing them needs a value-aware, post-allocation
// RENAME: rewrite later reads of the copy destination to the source and delete
// the copy.
//
// This is the x86 analogue of `trust_cg_regalloc::post_ra_coalesce`'s rename
// phase (`try_rename_coalesce`). That pass operates on a physical-register
// `MachFunction`; the x86 pipeline instead keeps the `X86ISelFunction` as the
// source of truth and replays regalloc mutations into it in VReg space
// (`replay_x86_regalloc_stream_mutations`). The VReg-keyed replay cannot carry
// physical-register renames (`x86_validate_removed_original_copy` only accepts
// plain `VReg->VReg` copies; `x86_replay_existing_operand_rewrite` only rewrites
// `VReg->VReg`), so the tested pass cannot be reused through that channel.
// Instead we port its exact safety conditions here and operate directly on the
// post-fixup `X86ISelFunction`, resolving each operand through the allocation.
//
// SOUNDNESS: the scan conditions below are the PRIMARY soundness argument —
// they are a faithful port of the tested `post_ra_coalesce::try_rename_coalesce`
// conditions. TV-5 (`trust_cg_verify::post_ra_dataflow`, run from
// `recheck_post_regalloc` AFTER this pass on every compile path) is
// defense-in-depth, NOT a license: it fail-closes tied-site misroutes and
// deleted two-address bridge copies with a `[TCG-POST-RA-DATAFLOW]` compile
// error, but its documented v1 misses (wrong-value renames of NON-tied use
// slots, spill-slot/memory dataflow) mean a bad rename of a PLAIN read would
// still miscompile silently — exactly the class the first draft of this pass
// exhibited before TV-5 existed, when the recheck was structural+opcode only.
// The conditions therefore carry the argument on their own: all reasoning is
// done at 64-bit-root granularity with x86 partial-register aliasing handled
// explicitly (a partial-width read of the destination that cannot be rewritten
// to the source bails the whole copy). Liveness is a conservative
// over-approximation; the only mutations performed (deleting a copy def of the
// destination and rewriting destination reads to the source) never grow any
// block's live-in, so the pre-computed live-out stays a valid
// over-approximation for later blocks (matching post_ra_coalesce's staleness
// argument), which can only PREVENT coalescing, never enable an unsound one.
//
// TV-5 GHOST-OPERAND INTERACTION (load-bearing): the rename below rewrites
// EVERY pure-use slot naming the deleted copy's destination — including the
// encoder-ignored ghost `operands[1]` of a downstream tied-form instruction —
// in lockstep with the adjacent bridge copy that TV-5's symbolic walk
// propagates through. This is the sym-faithful-rename carve-out documented in
// `trust_cg_verify::post_ra_dataflow`'s module doc: skipping ghost slots after
// deleting the copy would leave a STALE ghost sym while the renamed bridge
// carries the new one, and TV-5 would refute the (sound) output with
// TiedOperandValueMismatch, failing the compile closed. Self-certification
// (ghost := tied dst) is unreachable here: any def of the copy source before
// the ghost read sets `src_redef` and bails the scan first. Pinned by
// `x86_movrr_coalesce_renames_ghost_and_passes_tv5` and
// `x86_movrr_coalesce_ghost_skip_variant_refuted_by_tv5`.

/// Whether operand `idx` is READ at the machine level in the POST-FIXUP stream.
///
/// This is the critical correctness hook. `x86_operand_access` models the
/// PRE-fixup SSA form, where a three-operand two-address op `[dst, lhs, rhs]`
/// has `dst` (op0) as a def-ONLY operand and attributes the read-modify read to
/// the separate `lhs` operand (op1). After `fixup_two_address` runs, the encoder
/// emits the real two-address form `dst OP= rhs`, so the MACHINE reads `dst`
/// (op0) as the tied source — `fixup_two_address` guarantees op0 holds the lhs
/// value by inserting `MOV dst, lhs` when they differ. A block-local coalescer
/// operating on the post-fixup stream must therefore treat op0 of every
/// two-address op as a use, or it will delete the load-bearing bridge copy that
/// populates the destination (reading an uninitialized register). Deleting a
/// bridge is the exact class TV-5's dataflow walk now fails closed, but this
/// hook keeps the scan from ever PROPOSING such a deletion (check-then-apply:
/// the guard in `x86_try_rename_coalesce_copy` bails before any mutation).
fn x86_operand_is_machine_use(inst: &X86ISelInst, idx: usize) -> bool {
    if x86_operand_access(inst, idx).is_use {
        return true;
    }
    // op0 of a fixed-up two-address op is the tied destination, read as a source.
    idx == 0 && x86_two_address_lhs_operand_index(inst).is_some()
}

/// Collect the physical registers named by a resolved register/memory operand
/// (recursing into memory-address base/index), in width-specific `X86PReg` form.
fn x86_operand_resolved_pregs(
    op: &X86ISelOperand,
    alloc: &HashMap<VReg, X86PReg>,
    out: &mut Vec<X86PReg>,
) {
    match op {
        X86ISelOperand::VReg(_) | X86ISelOperand::PReg(_) => {
            if let Some(p) = resolve_operand(op, alloc) {
                out.push(p);
            }
        }
        X86ISelOperand::MemAddr { base, .. } => {
            x86_operand_resolved_pregs(base, alloc, out);
        }
        X86ISelOperand::SibMemAddr { base, index, .. } => {
            x86_operand_resolved_pregs(base, alloc, out);
            x86_operand_resolved_pregs(index, alloc, out);
        }
        _ => {}
    }
}

/// Implicit GPR64-root uses/defs of an x86 ISel instruction (fixed-register
/// clobbers plus call-argument and return-value registers), mirroring
/// `add_x86_fixed_implicit_operands` + the call/return conventions in
/// `x86_isel_to_regalloc`, reduced to containing-GPR64 roots.
///
/// Caller-saved clobbers of a plain call are deliberately NOT added as defs:
/// the copy scan treats calls as hard barriers, and for liveness omitting them
/// only over-approximates (keeps registers live across the call), which is safe.
fn x86_inst_implicit_gpr64_roots(
    inst: &X86ISelInst,
    uses: &mut Vec<X86PReg>,
    defs: &mut Vec<X86PReg>,
) {
    fn push_root(v: &mut Vec<X86PReg>, r: X86PReg) {
        if let Some(root) = x86_64_regs::x86_containing_gpr64(r) {
            v.push(root);
        }
    }
    match inst.opcode {
        X86Opcode::Cdq => {
            push_root(uses, x86_64_regs::EAX);
            push_root(defs, x86_64_regs::EDX);
        }
        X86Opcode::Cqo => {
            push_root(uses, x86_64_regs::RAX);
            push_root(defs, x86_64_regs::RDX);
        }
        X86Opcode::ShlRR | X86Opcode::ShrRR | X86Opcode::SarRR => {
            push_root(uses, x86_64_regs::RCX);
        }
        X86Opcode::Idiv | X86Opcode::Div => {
            push_root(uses, x86_64_regs::RAX);
            push_root(uses, x86_64_regs::RDX);
            push_root(defs, x86_64_regs::RAX);
            push_root(defs, x86_64_regs::RDX);
        }
        X86Opcode::Mul => {
            push_root(uses, x86_64_regs::RAX);
            push_root(defs, x86_64_regs::RAX);
            push_root(defs, x86_64_regs::RDX);
        }
        X86Opcode::Cmpxchg | X86Opcode::Cmpxchg8 | X86Opcode::Cmpxchg16 => {
            push_root(uses, x86_64_regs::RAX);
            push_root(defs, x86_64_regs::RAX);
        }
        X86Opcode::AtomicRmwCasLoop
        | X86Opcode::AtomicRmwCasLoop8
        | X86Opcode::AtomicRmwCasLoop16 => {
            push_root(defs, x86_64_regs::RAX);
            push_root(defs, x86_64_regs::R10);
        }
        _ => {}
    }
    if inst.flags.is_call() {
        for arg in &inst.call_arg_regs {
            push_root(uses, arg.reg);
        }
    }
    if inst.flags.is_return() {
        // GPR return-value registers (SysV/Windows). Modeling these as uses keeps
        // a value copied into a return register live into the `ret`.
        push_root(uses, x86_64_regs::RAX);
        push_root(uses, x86_64_regs::RDX);
    }
}

/// GPR64-root read set of an instruction (explicit operands + implicit uses).
fn x86_inst_gpr64_use_roots(inst: &X86ISelInst, alloc: &HashMap<VReg, X86PReg>) -> Vec<X86PReg> {
    let mut roots = Vec::new();
    for i in 0..inst.operands.len() {
        if x86_operand_is_machine_use(inst, i) {
            let mut pregs = Vec::new();
            x86_operand_resolved_pregs(&inst.operands[i], alloc, &mut pregs);
            for p in pregs {
                if let Some(root) = x86_64_regs::x86_containing_gpr64(p) {
                    roots.push(root);
                }
            }
        }
    }
    let mut idefs = Vec::new();
    x86_inst_implicit_gpr64_roots(inst, &mut roots, &mut idefs);
    roots
}

/// GPR64-root FULL-kill set of an instruction: roots that are completely
/// overwritten (64-bit or 32-bit — the latter zero-extends and thus clears the
/// full 64-bit register). Partial (8/16-bit) writes are NOT kills. Used only by
/// liveness; omitting a kill only over-approximates liveness, which is safe.
fn x86_inst_gpr64_kill_roots(inst: &X86ISelInst, alloc: &HashMap<VReg, X86PReg>) -> Vec<X86PReg> {
    let mut kills = Vec::new();
    for i in 0..inst.operands.len() {
        if x86_operand_access(inst, i).is_def
            && let Some(p) = resolve_operand(&inst.operands[i], alloc)
            && (p.is_gpr64() || p.is_gpr32())
            && let Some(root) = x86_64_regs::x86_containing_gpr64(p)
        {
            kills.push(root);
        }
    }
    let mut iuses = Vec::new();
    x86_inst_implicit_gpr64_roots(inst, &mut iuses, &mut kills);
    kills
}

/// Return `true` if the instruction writes (fully OR partially) a register whose
/// containing GPR64 is `root` — used for interference/clobber detection.
fn x86_inst_clobbers_gpr64_root(
    inst: &X86ISelInst,
    alloc: &HashMap<VReg, X86PReg>,
    root: X86PReg,
) -> bool {
    for i in 0..inst.operands.len() {
        if x86_operand_access(inst, i).is_def {
            let mut pregs = Vec::new();
            x86_operand_resolved_pregs(&inst.operands[i], alloc, &mut pregs);
            if pregs
                .iter()
                .any(|&p| x86_64_regs::x86_containing_gpr64(p) == Some(root))
            {
                return true;
            }
        }
    }
    let mut iuses = Vec::new();
    let mut idefs = Vec::new();
    x86_inst_implicit_gpr64_roots(inst, &mut iuses, &mut idefs);
    idefs.contains(&root)
}

/// Return `true` if the instruction FULLY overwrites `root`.
fn x86_inst_full_def_of_gpr64_root(
    inst: &X86ISelInst,
    alloc: &HashMap<VReg, X86PReg>,
    root: X86PReg,
) -> bool {
    for i in 0..inst.operands.len() {
        if x86_operand_access(inst, i).is_def
            && let Some(p) = resolve_operand(&inst.operands[i], alloc)
            && (p.is_gpr64() || p.is_gpr32())
            && x86_64_regs::x86_containing_gpr64(p) == Some(root)
        {
            return true;
        }
    }
    let mut iuses = Vec::new();
    let mut idefs = Vec::new();
    x86_inst_implicit_gpr64_roots(inst, &mut iuses, &mut idefs);
    idefs.contains(&root)
}

/// Return `true` if the instruction implicitly USES `root`.
fn x86_inst_implicit_uses_gpr64_root(inst: &X86ISelInst, root: X86PReg) -> bool {
    let mut iuses = Vec::new();
    let mut idefs = Vec::new();
    x86_inst_implicit_gpr64_roots(inst, &mut iuses, &mut idefs);
    iuses.contains(&root)
}

/// Explicit reads of `root` by an instruction, split into `(full, partial)`:
/// `full` means an explicit read resolves EXACTLY to `exact` (the full 64-bit
/// register); `partial` means a read whose containing GPR64 is `root` but is a
/// narrower alias (cannot be soundly rewritten to another register) OR a
/// tied read-modify operand.
fn x86_inst_explicit_reads_of_root(
    inst: &X86ISelInst,
    alloc: &HashMap<VReg, X86PReg>,
    root: X86PReg,
    exact: X86PReg,
) -> (bool, bool) {
    let mut full = false;
    let mut partial = false;
    for i in 0..inst.operands.len() {
        if !x86_operand_is_machine_use(inst, i) {
            continue;
        }
        let is_def = x86_operand_access(inst, i).is_def;
        let mut pregs = Vec::new();
        x86_operand_resolved_pregs(&inst.operands[i], alloc, &mut pregs);
        for p in pregs {
            if x86_64_regs::x86_containing_gpr64(p) == Some(root) {
                // A tied (read+write) operand — including the tied destination of
                // a two-address op — is never renameable.
                if is_def || p != exact {
                    partial = true;
                } else {
                    full = true;
                }
            }
        }
    }
    (full, partial)
}

/// Rewrite every renameable explicit read of `pdst` (exact 64-bit) to `psrc`
/// within an instruction. Only pure-use operands (`is_use && !is_def`) are
/// rewritten; tied read-modify operands are left untouched (the caller bails
/// before reaching here if the destination is used as one).
fn x86_rename_reads_pdst_to_psrc(
    inst: &mut X86ISelInst,
    pdst: X86PReg,
    psrc: X86PReg,
    alloc: &HashMap<VReg, X86PReg>,
) {
    fn rewrite(
        op: &mut X86ISelOperand,
        pdst: X86PReg,
        psrc: X86PReg,
        alloc: &HashMap<VReg, X86PReg>,
    ) {
        match op {
            X86ISelOperand::VReg(_) | X86ISelOperand::PReg(_) => {
                if resolve_operand(op, alloc) == Some(pdst) {
                    *op = X86ISelOperand::PReg(psrc);
                }
            }
            X86ISelOperand::MemAddr { base, .. } => rewrite(base, pdst, psrc, alloc),
            X86ISelOperand::SibMemAddr { base, index, .. } => {
                rewrite(base, pdst, psrc, alloc);
                rewrite(index, pdst, psrc, alloc);
            }
            _ => {}
        }
    }
    for i in 0..inst.operands.len() {
        let access = x86_operand_access(inst, i);
        if access.is_use && !access.is_def {
            rewrite(&mut inst.operands[i], pdst, psrc, alloc);
        }
    }
}

/// Conservative per-block GPR64-root live-out via iterative backward liveness.
fn compute_x86_gpr64_live_out(
    func: &X86ISelFunction,
    alloc: &HashMap<VReg, X86PReg>,
) -> HashMap<LirBlock, HashSet<X86PReg>> {
    let mut live_in: HashMap<LirBlock, HashSet<X86PReg>> = HashMap::new();
    for b in &func.block_order {
        live_in.insert(*b, HashSet::new());
    }

    let mut changed = true;
    let mut guard = 0usize;
    let cap = func.block_order.len().saturating_mul(4).max(16);
    while changed && guard < cap {
        changed = false;
        guard += 1;
        for block in func.block_order.iter().rev() {
            let Some(blk) = func.blocks.get(block) else {
                continue;
            };
            let mut live: HashSet<X86PReg> = HashSet::new();
            for succ in &blk.successors {
                if let Some(s_in) = live_in.get(succ) {
                    live.extend(s_in.iter().copied());
                }
            }
            for inst in blk.insts.iter().rev() {
                for k in x86_inst_gpr64_kill_roots(inst, alloc) {
                    live.remove(&k);
                }
                for u in x86_inst_gpr64_use_roots(inst, alloc) {
                    live.insert(u);
                }
            }
            if live_in.get(block) != Some(&live) {
                live_in.insert(*block, live);
                changed = true;
            }
        }
    }

    // FAIL-CLOSED on non-convergence: liveness is a MAY analysis whose sets
    // only grow, so exiting the fixpoint early UNDER-approximates live-out —
    // the coalescer (the sole consumer) would then treat a live register as
    // dead at block end and commit an unsound rename that the tied-only TV-5
    // check cannot catch. The cap (4×blocks) exceeds the reverse-order
    // convergence bound for any realistic CFG, so this path should be
    // unreachable; if it ever fires, report EVERY register live-out for every
    // block — the coalescer then refuses all merges in this function (a pure
    // missed-optimization, never a miscompile).
    if changed {
        let all: HashSet<X86PReg> = (0u16..16).map(X86PReg::new).collect();
        return func
            .block_order
            .iter()
            .map(|block| (*block, all.clone()))
            .collect();
    }

    let mut live_out: HashMap<LirBlock, HashSet<X86PReg>> = HashMap::new();
    for block in &func.block_order {
        let Some(blk) = func.blocks.get(block) else {
            continue;
        };
        let mut lo = HashSet::new();
        for succ in &blk.successors {
            if let Some(s_in) = live_in.get(succ) {
                lo.extend(s_in.iter().copied());
            }
        }
        live_out.insert(*block, lo);
    }
    live_out
}

/// Try to rename-coalesce the 64-bit `MovRR` copy at `copy_pos` (`pdst <- psrc`,
/// distinct registers). On success, later reads of `pdst` in the block are
/// rewritten to `psrc` (in place) and `true` is returned so the caller can
/// delete the copy. Faithful port of `post_ra_coalesce::try_rename_coalesce`.
#[allow(clippy::too_many_arguments)]
/// Collapse a `producer / writeback-copy` pair by redirecting the producer's
/// destination, so the copy disappears entirely.
///
/// ```text
///   AddRI [d, a, 16]     ; d = a + 16      <- producer (three-address, pre-fixup)
///   MovRR [a, d]         ; a = d           <- writeback / loop latch
/// ==>
///   AddRI [a, a, 16]     ; a = a + 16
/// ```
///
/// This is the loop-carried induction-variable update, and it is where the
/// two-address copy cost actually comes from: 24 such pairs across 11 of the 18
/// beat-llvm programs, all in hot loops. Collapsing here — BEFORE
/// [`fixup_two_address`] — is strictly better than cleaning up afterwards,
/// because with `dst == src1` the fixup then inserts NO bridge copy at all, so
/// one rewrite removes two instructions.
///
/// This is the coalesce the register allocator could not perform: `d`'s live
/// range begins exactly where `a`'s ends, and a whole-interval overlap test
/// calls that an interference (the finding recorded against the dynamic
/// tied-operand experiment). Nothing here changes allocation — it rewrites an
/// already-assigned stream under a local deadness test.
///
/// Returns `true` if the pair was collapsed (the caller deletes the writeback).
///
/// # Soundness
///
/// Net effect of the pair is `a = <producer>`, which is exactly the post-state
/// of the rewritten producer. Specifically:
///
/// * `a`'s OLD value dies at the writeback. The two instructions are ADJACENT,
///   so the only instruction that could read the old value is the producer
///   itself — and x86 reads every operand before writing the result, so a
///   producer that names `a` as a source (`AddRR [d, a, b]` -> `AddRR [a, a,
///   b]`) still reads the old value first. That is why no "operand must not
///   name `a`" condition is needed here.
/// * `d` must be DEAD after the writeback, so discarding its register is
///   unobservable.
/// * FLAGS are unaffected: `MovRR` writes none, so the pair leaves exactly the
///   flags the producer leaves, before and after.
/// POST-RA bridge-into-LEA collapse.
///
/// ```text
///   movq %rbx, %r8        ; d = a       <- two-address bridge, at copy_pos
///   addq %rcx, %r8        ; d = d + b   <- post-fixup tied AddRR
/// ==>
///   leaq (%rbx,%rcx), %r8 ; d = a + b
/// ```
///
/// Removes the bridge outright: `LEA` is three-address and writes no flags.
///
/// ⚑ WHY POST-RA AND NOT IN THE PEEPHOLE. The same rewrite applied PRE-RA to
/// the three-address `AddRR d,a,b` was implemented, measured on all 18 programs
/// and REVERTED: p2_collatz +25% and p8_closure_nest +22%, but
/// h1_vec_push_sum **-34%** and p1_xorshift -14%, for a paired suite geomean of
/// 0.9927x. The mechanism of the loss was NOT code placement — h1's `main` grew
/// from 200 to 214 instructions because turning a TIED destination into an
/// untied fresh def changed live ranges and the allocator answered with 14
/// extra instructions.
///
/// Here that cannot happen. Register assignment is already fixed, and the
/// rewrite fires ONLY where the two-address fixup actually inserted a bridge —
/// i.e. only where the allocator failed to give `d` and `a` the same register,
/// which is exactly the case the rewrite is meant to serve. It is a guaranteed
/// one-instruction reduction with no effect on allocation.
///
/// Returns true if the caller should delete the copy at `copy_pos`.
///
/// # Soundness
///
/// `d = a; d = d + b` leaves `d = a + b` with `a` and `b` unchanged, which is
/// exactly `lea d,[a+b]`. Conditions:
///
/// * ⚑ `d != b`. If `d` aliased `b` the original would compute `a + a` (because
///   `b`'s register was overwritten by the copy first), while the LEA reads
///   `b`'s ORIGINAL value. That is a silent wrong-answer miscompile and it is
///   the one condition here whose absence would not fail closed.
/// * `d != a`, otherwise the copy is an identity and there is no bridge.
/// * The add's RFLAGS must be dead — `LEA` writes none.
/// * All three registers are whole 64-bit GPRs.
fn x86_try_collapse_bridge_into_lea(
    insts: &[X86ISelInst],
    copy_pos: usize,
    d: X86PReg,
    a: X86PReg,
    d_root: X86PReg,
    a_root: X86PReg,
    alloc: &HashMap<VReg, X86PReg>,
) -> Option<X86PReg> {
    if !bridge_into_lea_enabled() {
        return None;
    }
    if d != d_root || a != a_root || d_root == a_root {
        return None;
    }
    let add = insts.get(copy_pos + 1)?;
    if add.opcode != X86Opcode::AddRR
        || add.flags != X86Opcode::AddRR.default_flags()
        || add.proof_origin.is_some()
    {
        return None;
    }
    // ⚑ POST-FIXUP SHAPE. A tied op KEEPS its original three-address operands
    // `[dst, ghost_src1, src2]`; the tie is established by the preceding bridge
    // copy, not by rewriting operand 1. (This is the same "ghost source" the
    // TV-5 dataflow check reports as "tied destination X does not overlap ghost
    // source Y".) So operand 1 is `a` — the copy's SOURCE — not `d`. Matching
    // `o1 == d` here made this fire ZERO times on all 18 programs.
    let [o0, o1, o2] = add.operands.as_slice() else {
        return None;
    };
    if resolve_operand(o0, alloc) != Some(d) || resolve_operand(o1, alloc) != Some(a) {
        return None;
    }
    let b = resolve_operand(o2, alloc)?;
    let b_root = x86_64_regs::x86_containing_gpr64(b)?;
    // ⚑ The aliasing guard: see the doc comment. `d == b` would change the value.
    if b != b_root || b_root == d_root {
        return None;
    }
    // LEA writes no flags, so the add's flag definition must be dead.
    if !x86_add_flags_dead_after(insts, copy_pos + 1) {
        return None;
    }
    Some(b)
}

/// RFLAGS written at `idx` are dead: no reader before a FULL redefinition.
///
/// Conservative by construction — falling off the block end returns false,
/// because the flags could be live into a successor. `x86_defines_all_cc_flags`
/// is the shared predicate for "architecturally overwrites every condition
/// flag" and deliberately excludes partial writers such as the shifts, so the
/// coverage argument never rests on an undefined or preserved flag.
fn x86_add_flags_dead_after(insts: &[X86ISelInst], idx: usize) -> bool {
    for later in insts.iter().skip(idx + 1) {
        if trust_cg_opt::effects::x86_reads_flags(later.opcode) {
            return false;
        }
        if trust_cg_opt::effects::x86_defines_all_cc_flags(later.opcode) {
            return true;
        }
        if later.flags.is_call() || later.flags.is_branch() || later.flags.is_terminator() {
            return false;
        }
    }
    false
}

/// Kill switch for the post-RA bridge-into-LEA collapse.
fn bridge_into_lea_enabled() -> bool {
    std::env::var_os("TCG_NO_X86_BRIDGE_LEA").is_none()
}

fn x86_try_collapse_producer_writeback(
    insts: &[X86ISelInst],
    wb_pos: usize,
    a: X86PReg,
    d: X86PReg,
    a_root: X86PReg,
    d_root: X86PReg,
    block_live_out: &HashSet<X86PReg>,
    alloc: &HashMap<VReg, X86PReg>,
) -> bool {
    if !copy_op_writeback_enabled() || wb_pos == 0 {
        return false;
    }
    // Whole 64-bit GPRs only: sub-register writebacks would need width
    // reasoning the caller's `MovRR` match does not establish.
    if a != a_root || d != d_root || a_root == d_root {
        return false;
    }
    let prod_idx = wb_pos - 1;
    let prod = &insts[prod_idx];

    let tracing = std::env::var_os("TCG_X86_COPY_OP_WRITEBACK_TRACE").is_some();
    macro_rules! decline {
        ($why:expr) => {{
            if tracing && x86_collapsible_two_address_alu(prod.opcode) {
                eprintln!(
                    "[cow-trace] DECLINE({}) {:?} {:?} ; mov {:?}<-{:?}",
                    $why, prod.opcode, prod.operands, a, d,
                );
            }
            return false;
        }};
    }

    if !x86_collapsible_two_address_alu(prod.opcode)
        || prod.flags != prod.opcode.default_flags()
        || prod.proof_origin.is_some()
        || prod.flags.is_call()
        || prod.flags.is_branch()
        || prod.flags.is_terminator()
        || prod.flags.is_return()
        || prod.flags.reads_memory()
        || prod.flags.writes_memory()
        || prod.flags.has_side_effects()
    {
        return false;
    }
    // The producer must define exactly `d` in operand 0.
    if prod.operands.is_empty() || resolve_operand(&prod.operands[0], alloc) != Some(d) {
        decline!("prod-does-not-define-d");
    }
    // ⚑ The producer's FIRST SOURCE must already be `a`, i.e. the shape is
    // `d = a op X ; a = d`. This is both the soundness condition and the only
    // case that actually wins:
    //
    //   * src1 == a  -> rewriting the destination to `a` makes the instruction
    //     SELF-TIED (`a = a op X`), so the two-address fixup needs no bridge and
    //     the writeback disappears outright: two instructions become one.
    //   * src1 != a  -> redirecting the destination BREAKS an already-established
    //     tie, and this pass runs POST-fixup so nothing repairs it. TV-5 catches
    //     it ("the two-address bridge copy is missing, redirected, or
    //     clobbered") and fails the compile closed, which is exactly what
    //     happened on p6_branch_match before this condition existed.
    //   * src1 == d  -> the producer is already self-tied; redirecting would
    //     INTRODUCE a bridge while removing the writeback. Net zero, so there is
    //     no reason to take the risk.
    if prod.operands.len() < 2 || resolve_operand(&prod.operands[1], alloc) != Some(a) {
        decline!("src1-is-not-a");
    }
    // No implicit register traffic in either register (Idiv/Mul-style forms are
    // already excluded by the allowlist, but guard against future additions).
    if x86_inst_implicit_uses_gpr64_root(prod, a_root)
        || x86_inst_implicit_uses_gpr64_root(prod, d_root)
    {
        decline!("implicit-traffic");
    }

    // `d` must be DEAD after the writeback.
    if block_live_out.contains(&d_root) {
        decline!("d-live-out");
    }
    for later in insts.iter().skip(wb_pos + 1) {
        if later.flags.is_call() || later.flags.is_return() {
            decline!("call-barrier");
        }
        let (full, partial) = x86_inst_explicit_reads_of_root(later, alloc, d_root, d);
        if full || partial || x86_inst_implicit_uses_gpr64_root(later, d_root) {
            decline!("d-read-later");
        }
        if x86_inst_clobbers_gpr64_root(later, alloc, d_root) {
            return true;
        }
        if later.flags.is_branch() || later.flags.is_terminator() {
            break;
        }
    }
    true
}

/// Two-address ALU opcodes whose operand 0 is a pure read-modify-write of a
/// GPR and which touch no memory and read no flags. `AdcRR`/`SbbRR` are
/// EXCLUDED (they read CF, so they are not a pure function of their operands
/// for this rewrite's purposes) and so is anything with an implicit register.
fn x86_collapsible_two_address_alu(opcode: X86Opcode) -> bool {
    use X86Opcode::*;
    matches!(
        opcode,
        AddRR
            | SubRR
            | AndRR
            | OrRR
            | XorRR
            | ImulRR
            | AddRI
            | SubRI
            | AndRI
            | OrRI
            | XorRI
            | ShlRI
            | ShrRI
            | SarRI
            | RolRI
            | Neg
            | Not
            | Inc
            | Dec
    )
}

/// Kill switch for the copy/op/writeback collapse (paired A/B in ONE dylib).
fn copy_op_writeback_enabled() -> bool {
    std::env::var_os("TCG_NO_X86_COPY_OP_WRITEBACK").is_none()
}

fn x86_try_rename_coalesce_copy(
    insts: &mut [X86ISelInst],
    copy_pos: usize,
    pdst: X86PReg,
    psrc: X86PReg,
    pdst_root: X86PReg,
    psrc_root: X86PReg,
    block_live_out: &HashSet<X86PReg>,
    alloc: &HashMap<VReg, X86PReg>,
) -> bool {
    let start = copy_pos + 1;
    let n = insts.len();

    let mut last_dst_use: Option<usize> = None;
    let mut src_redef: Option<usize> = None;
    let mut dst_redef: Option<usize> = None;
    let mut call_barrier: Option<usize> = None;

    let mut i = start;
    while i < n {
        // Calls and returns are conservative barriers (implicit clobbers / live
        // return values). Never rename across them.
        if insts[i].flags.is_call() || insts[i].flags.is_return() {
            call_barrier = Some(i);
            break;
        }

        let defines_pdst = x86_inst_clobbers_gpr64_root(&insts[i], alloc, pdst_root);
        let (uses_full, uses_partial) =
            x86_inst_explicit_reads_of_root(&insts[i], alloc, pdst_root, pdst);
        let uses_pdst_any = uses_full || uses_partial;
        let implicit_uses_pdst = x86_inst_implicit_uses_gpr64_root(&insts[i], pdst_root);

        // A read-modify of `pdst` (tied) makes the copy load-bearing and is
        // unrenameable; also bail on any implicit use of `pdst`.
        if defines_pdst && (uses_pdst_any || implicit_uses_pdst) {
            return false;
        }
        if implicit_uses_pdst {
            return false;
        }

        if x86_inst_clobbers_gpr64_root(&insts[i], alloc, psrc_root) && src_redef.is_none() {
            src_redef = Some(i);
        }
        if defines_pdst && dst_redef.is_none() {
            dst_redef = Some(i);
        }

        if uses_pdst_any {
            // A partial-width read of `pdst` cannot be rewritten to `psrc`.
            if uses_partial {
                return false;
            }
            if src_redef.is_some() {
                return false;
            }
            if dst_redef.is_some() {
                break;
            }
            last_dst_use = Some(i);
        }

        if let Some(redef) = dst_redef
            && i >= redef
        {
            break;
        }
        i += 1;
    }

    // Dead-copy case: `pdst` never read after the copy.
    if last_dst_use.is_none() {
        let Some(redef) = dst_redef else {
            // `pdst` may be live-out; conservatively keep the copy.
            return false;
        };
        if !x86_inst_full_def_of_gpr64_root(&insts[redef], alloc, pdst_root) {
            return false;
        }
        // A later call/return that reads `pdst` would observe a value this copy
        // is delivering across it; keep the copy then.
        let reads_after = insts[redef + 1..].iter().any(|inst| {
            (inst.flags.is_call() || inst.flags.is_return())
                && (x86_inst_explicit_reads_of_root(inst, alloc, pdst_root, pdst).0
                    || x86_inst_explicit_reads_of_root(inst, alloc, pdst_root, pdst).1
                    || x86_inst_implicit_uses_gpr64_root(inst, pdst_root))
        });
        return !reads_after;
    }

    let last_use = last_dst_use.expect("checked Some above");

    if let Some(sr) = src_redef
        && sr <= last_use
    {
        return false;
    }

    // If the scan stopped at a call/return without a prior redef of `pdst`,
    // ensure `pdst` is dead from the barrier onward.
    if let Some(cb) = call_barrier
        && dst_redef.is_none_or(|r| r > cb)
    {
        for inst in &insts[cb..] {
            let (f, p) = x86_inst_explicit_reads_of_root(inst, alloc, pdst_root, pdst);
            if f || p || x86_inst_implicit_uses_gpr64_root(inst, pdst_root) {
                return false;
            }
            if x86_inst_clobbers_gpr64_root(inst, alloc, pdst_root) {
                break;
            }
        }
    }

    // Deleting the copy also drops an edge-commit of `pdst`; refuse when `pdst`
    // is live-out and not redefined in-block.
    if dst_redef.is_none() && block_live_out.contains(&pdst_root) {
        return false;
    }

    // Apply: rewrite all reads of `pdst` in [start..=last_use] to `psrc`.
    for inst in &mut insts[start..=last_use] {
        x86_rename_reads_pdst_to_psrc(inst, pdst, psrc, alloc);
    }
    true
}

/// Bisect kill-switch for the post-fixup redundant-`MovRR` coalescer:
/// `TRUST_CG_DISABLE_PASSES=x86_movrr_coalesce`.
fn x86_movrr_coalesce_disabled() -> bool {
    crate::env_lock::var("TRUST_CG_DISABLE_PASSES")
        .unwrap_or_default()
        .split(',')
        .any(|d| d.trim() == "x86_movrr_coalesce")
}

/// Block-local redundant-`MovRR` coalescing over the post-fixup function.
/// Returns the number of copies removed.
fn coalesce_x86_redundant_movrr_copies(
    func: &mut X86ISelFunction,
    alloc: &HashMap<VReg, X86PReg>,
) -> usize {
    let live_out = compute_x86_gpr64_live_out(func, alloc);
    let mut total = 0usize;

    for block in func.block_order.clone() {
        let blk_live_out = live_out.get(&block).cloned().unwrap_or_default();

        let mut insts = {
            let Some(b) = func.blocks.get_mut(&block) else {
                continue;
            };
            std::mem::take(&mut b.insts)
        };

        let mut delete = vec![false; insts.len()];
        let mut pos = 0;
        while pos < insts.len() {
            // An instruction already scheduled for deletion is not a valid
            // anchor: a collapsed pair must not be re-examined, and the
            // rename path must never fire on an instruction that is going away
            // and rewrite uses against something that will not exist.
            if delete[pos] {
                pos += 1;
                continue;
            }
            if insts[pos].opcode == X86Opcode::MovRR
                && insts[pos].operands.len() == 2
                && let Some(pdst) = resolve_operand(&insts[pos].operands[0], alloc)
                && let Some(psrc) = resolve_operand(&insts[pos].operands[1], alloc)
                && let Some(pdst_root) = x86_64_regs::x86_containing_gpr64(pdst)
                && let Some(psrc_root) = x86_64_regs::x86_containing_gpr64(psrc)
            {
                if pdst_root == psrc_root {
                    // Identity 64-bit self-move (a genuine no-op): drop it.
                    if pdst == psrc {
                        delete[pos] = true;
                        total += 1;
                    }
                } else if x86_try_rename_coalesce_copy(
                    &mut insts,
                    pos,
                    pdst,
                    psrc,
                    pdst_root,
                    psrc_root,
                    &blk_live_out,
                    alloc,
                ) {
                    delete[pos] = true;
                    total += 1;
                } else if let Some(b_reg) = x86_try_collapse_bridge_into_lea(
                    &insts, pos, pdst, psrc, pdst_root, psrc_root, alloc,
                ) {
                    // `mov d,a ; add d,d,b`  =>  `lea d,[a+b]`; drop the bridge.
                    //
                    // ⚑ REUSE THE ADD'S OWN OPERANDS. Rebuilding these from raw
                    // `PReg`s discards the VREG identity they carry, and the
                    // destination vreg then has no definition at this
                    // instruction even though its register is still written.
                    // TV-5 tracks vregs, so it walks back to that vreg's
                    // previous def and — if a call sits in between — correctly
                    // refuses with `call-severed-vreg-read`. That failed CLOSED
                    // on 7 of the 18 bench programs at -O2/-O3. Operands 0/1/2
                    // are already exactly `d`, `a` and `b` (see the predicate),
                    // so the faithful rewrite changes the opcode and repackages
                    // the two sources — it never re-spells them.
                    let add_idx = pos + 1;
                    let [dst_op, a_op, b_op] = insts[add_idx].operands.as_slice() else {
                        unreachable!("the predicate matched a three-operand AddRR");
                    };
                    let (dst_op, a_op, b_op) = (dst_op.clone(), a_op.clone(), b_op.clone());
                    insts[add_idx].opcode = X86Opcode::LeaSib;
                    insts[add_idx].flags = X86Opcode::LeaSib.default_flags();
                    insts[add_idx].operands = vec![
                        dst_op,
                        X86ISelOperand::SibMemAddr {
                            base: Box::new(a_op),
                            index: Box::new(b_op),
                            scale: 1,
                            disp: 0,
                        },
                    ];
                    if std::env::var_os("TCG_X86_BRIDGE_LEA_LOG").is_some() {
                        eprintln!(
                            "[bridge-lea] ACCEPT lea {:?} <- [{:?} + {:?}] in `{}`",
                            pdst, psrc, b_reg, func.name,
                        );
                    }
                    delete[pos] = true;
                    total += 1;
                } else if pos > 0
                    && !delete[pos - 1]
                    && x86_try_collapse_producer_writeback(
                        &insts,
                        pos,
                        pdst,
                        psrc,
                        pdst_root,
                        psrc_root,
                        &blk_live_out,
                        alloc,
                    )
                {
                    // Redirect the producer's destination to the writeback's
                    // destination, then drop the writeback. `dst == src1` then
                    // makes `fixup_two_address` insert no bridge either.
                    let prod_idx = pos - 1;
                    insts[prod_idx].operands[0] = insts[pos].operands[0].clone();
                    // The two-address bridge that established the OLD tie
                    // (`mov d, a`, inserted by `fixup_two_address` right before
                    // the producer) now defines a register that is dead: the
                    // producer no longer writes `d`, nothing sits between the
                    // bridge and the producer, and `d`'s deadness after the
                    // writeback was just proven. Drop it too — otherwise the
                    // rewrite trades one instruction for another instead of
                    // removing two.
                    if prod_idx > 0
                        && !delete[prod_idx - 1]
                        && insts[prod_idx - 1].opcode == X86Opcode::MovRR
                        && insts[prod_idx - 1].proof_origin.is_none()
                        && insts[prod_idx - 1].operands.len() == 2
                        && resolve_operand(&insts[prod_idx - 1].operands[0], alloc) == Some(psrc)
                    {
                        delete[prod_idx - 1] = true;
                        total += 1;
                    }
                    if std::env::var_os("TCG_X86_COPY_OP_WRITEBACK_LOG").is_some() {
                        eprintln!(
                            "[copy-op-writeback] ACCEPT {:?} ops={:?} dest {:?} <- {:?} in `{}`",
                            insts[prod_idx].opcode, insts[prod_idx].operands, pdst, psrc, func.name,
                        );
                    }
                    delete[pos] = true;
                    total += 1;
                }
            }
            pos += 1;
        }

        let rebuilt: Vec<X86ISelInst> = insts
            .into_iter()
            .enumerate()
            .filter_map(|(idx, inst)| if delete[idx] { None } else { Some(inst) })
            .collect();
        if let Some(b) = func.blocks.get_mut(&block) {
            b.insts = rebuilt;
        }
    }

    total
}

// ---------------------------------------------------------------------------
// Formal-argument parallel-copy fixup (#497, #499)
// ---------------------------------------------------------------------------

/// Return `true` if `preg` aliases a supported x86-64 integer argument
/// register. The Windows x64 integer argument registers are a subset of the
/// System V AMD64 register roots represented by `X86_ARG_GPRS`.
#[inline]
fn is_arg_gpr(preg: X86PReg) -> bool {
    x86_containing_gpr64(preg).is_some_and(|root| X86_ARG_GPRS.contains(&root))
}

/// Return `true` if `preg` is a System V AMD64 FP-argument register
/// (XMM0..XMM7).
#[inline]
fn is_arg_xmm(preg: X86PReg) -> bool {
    X86_ARG_XMMS.contains(&preg)
}

const WINDOWS_X64_FORMAL_ARG_GPR_COUNT: usize = 4;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum FormalSysVAggregateLaneClass {
    Integer,
    Sse,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct FormalSysVAggregateLayout {
    lane_count: usize,
    gpr_count: usize,
    xmm_count: usize,
    eightbyte_count: i64,
}

/// An aggregate ABI type, kept in lockstep with the x86-64 ISel classifier
/// (`x86_64_isel.rs::reject_x86_aggregate_abi` / `is_large_x86_sret_aggregate`):
/// `Struct`, `Array`, and `Enum` are all aggregates for ABI placement, so the
/// prologue-length computation here must recognize the same set. `I128` is a
/// scalar handled by its own register-pair path, not an aggregate.
fn formal_is_aggregate_type(ty: &Type) -> bool {
    matches!(ty, Type::Struct(_) | Type::Array(_, _) | Type::Enum { .. })
}

fn formal_is_large_x86_sret_aggregate(ty: &Type) -> bool {
    formal_is_aggregate_type(ty) && ty.bytes() > 16
}

/// Mirror of ISel `is_sysv_memory_byval_aggregate`: a >16-byte SysV
/// `Struct`/`Array` passed by value on the stack (MEMORY class). ISel binds it
/// in the post-prefix materialization phase, consuming no argument register and
/// emitting no formal-arg prefix instruction.
fn formal_is_sysv_memory_byval_aggregate(ty: &Type, abi: X86CallAbi) -> bool {
    abi == X86CallAbi::SystemV
        && matches!(ty, Type::Struct(_) | Type::Array(_, _))
        && ty.bytes() > 16
}

fn formal_is_x86_sret_return_aggregate(ty: &Type, abi: X86CallAbi) -> bool {
    match abi {
        X86CallAbi::SystemV => formal_is_large_x86_sret_aggregate(ty),
        X86CallAbi::WindowsX64 => formal_is_aggregate_type(ty) && ty.bytes() > 8,
    }
}

fn formal_has_sret_return(func: &X86ISelFunction, abi: X86CallAbi) -> bool {
    func.sig.returns.len() == 1 && formal_is_x86_sret_return_aggregate(&func.sig.returns[0], abi)
}

fn formal_is_single_integer_gpr_lane_type(ty: &Type) -> bool {
    matches!(ty, Type::I8 | Type::I16 | Type::I32 | Type::I64)
}

fn formal_single_x86_gpr_aggregate_lane_type(ty: &Type) -> bool {
    match ty {
        Type::Struct(fields) if matches!(fields.as_slice(), [lane] if formal_is_single_integer_gpr_lane_type(lane)) => {
            true
        }
        Type::Array(elem, 1) if formal_is_single_integer_gpr_lane_type(elem) => true,
        _ => false,
    }
}

// -------------------------------------------------------------------------
// System V AMD64 eightbyte classification (mirror of x86_64_isel.rs).
//
// This MUST stay byte-for-byte equivalent to ISel's
// `classify_sysv_register_aggregate`: ISel decides how many formal-arg copy
// pseudos to emit (and which register banks they consume), and this prologue
// scanner must count exactly the same prologue prefix. Any divergence
// silently desynchronizes the parallel-copy fixup. The two implementations are
// kept structurally identical; only the result shape differs (ISel needs lane
// types/offsets to emit code, the pipeline needs only lane/bank counts).
// -------------------------------------------------------------------------

/// SysV eightbyte class of a scalar *leaf* field (psABI §3.2.3).
fn formal_sysv_scalar_leaf_class(ty: &Type) -> Option<FormalSysVAggregateLaneClass> {
    match ty {
        Type::B1 | Type::I8 | Type::I16 | Type::I32 | Type::I64 => {
            Some(FormalSysVAggregateLaneClass::Integer)
        }
        Type::F16 | Type::F32 | Type::F64 => Some(FormalSysVAggregateLaneClass::Sse),
        _ => None,
    }
}

fn formal_merge_sysv_eightbyte_class(
    acc: &mut Option<FormalSysVAggregateLaneClass>,
    leaf: FormalSysVAggregateLaneClass,
) {
    *acc = Some(match (*acc, leaf) {
        (None, c) => c,
        (Some(FormalSysVAggregateLaneClass::Integer), _)
        | (_, FormalSysVAggregateLaneClass::Integer) => FormalSysVAggregateLaneClass::Integer,
        (Some(FormalSysVAggregateLaneClass::Sse), FormalSysVAggregateLaneClass::Sse) => {
            FormalSysVAggregateLaneClass::Sse
        }
    });
}

/// A single 16-byte `V128` leaf occupying the whole aggregate (SSE vector
/// carrier): one XMM register spanning both eightbytes.
fn formal_is_sysv_v128_carrier(ty: &Type) -> bool {
    match ty {
        Type::V128 => true,
        Type::Struct(fields) => matches!(fields.as_slice(), [f] if formal_is_sysv_v128_carrier(f)),
        Type::Array(elem, 1) => formal_is_sysv_v128_carrier(elem),
        _ => false,
    }
}

fn formal_collect_sysv_aggregate_leaves(
    ty: &Type,
    base: u32,
    eightbytes: &mut [Option<FormalSysVAggregateLaneClass>; 2],
) -> Option<()> {
    match ty {
        Type::Struct(fields) => {
            for (idx, field) in fields.iter().enumerate() {
                let offset = ty.offset_of(idx)?;
                formal_collect_sysv_aggregate_leaves(field, base.checked_add(offset)?, eightbytes)?;
            }
            Some(())
        }
        Type::Array(elem, count) => {
            let stride = elem.bytes();
            for idx in 0..*count {
                let offset = stride.checked_mul(idx)?;
                formal_collect_sysv_aggregate_leaves(elem, base.checked_add(offset)?, eightbytes)?;
            }
            Some(())
        }
        Type::I128 => {
            let end = base.checked_add(16)?;
            if !base.is_multiple_of(8) || end > 16 {
                return None;
            }
            let lo = (base / 8) as usize;
            formal_merge_sysv_eightbyte_class(
                &mut eightbytes[lo],
                FormalSysVAggregateLaneClass::Integer,
            );
            formal_merge_sysv_eightbyte_class(
                &mut eightbytes[lo + 1],
                FormalSysVAggregateLaneClass::Integer,
            );
            Some(())
        }
        Type::V128 | Type::Enum { .. } => None,
        scalar => {
            let bytes = scalar.bytes();
            if bytes == 0 {
                return None;
            }
            let end = base.checked_add(bytes)?;
            if end > 16 || base / 8 != (end - 1) / 8 {
                return None;
            }
            let class = formal_sysv_scalar_leaf_class(scalar)?;
            formal_merge_sysv_eightbyte_class(&mut eightbytes[(base / 8) as usize], class);
            Some(())
        }
    }
}

/// Number of valid (live) bytes mapping to a representable eightbyte lane:
/// full 8-byte and 4/2/1-byte partial tails are modeled (one width-correct GPR
/// access per lane); 3/5/6/7-byte partials have no single non-over-reading access
/// and are rejected (return `false`) so we fail closed instead of miscompiling.
/// Mirrors ISel `sysv_eightbyte_lane_type`; both must admit the same widths so the
/// classifiers stay in lockstep (`formal_arg_prologue_len` counts one copy per
/// lane regardless of lane width).
fn formal_sysv_eightbyte_lane_representable(valid_bytes: u32) -> bool {
    matches!(valid_bytes, 8 | 4 | 2 | 1)
}

fn formal_sysv_packed_i32_pair_aggregate_layout(ty: &Type) -> Option<FormalSysVAggregateLayout> {
    let is_i32_pair = match ty {
        Type::Struct(fields) => matches!(fields.as_slice(), [Type::I32, Type::I32]),
        Type::Array(elem, 2) => matches!(elem.as_ref(), Type::I32),
        _ => false,
    };
    if !is_i32_pair || ty.bytes() != 8 {
        return None;
    }
    Some(FormalSysVAggregateLayout {
        lane_count: 1,
        gpr_count: 1,
        xmm_count: 0,
        eightbyte_count: 1,
    })
}

fn formal_classify_sysv_register_aggregate(
    ty: &Type,
    abi: X86CallAbi,
) -> Option<FormalSysVAggregateLayout> {
    if abi != X86CallAbi::SystemV || !formal_is_aggregate_type(ty) {
        return None;
    }
    if let Some(layout) = formal_sysv_packed_i32_pair_aggregate_layout(ty) {
        return Some(layout);
    }
    // Single-field integer aggregates use the dedicated single-GPR path (see
    // ISel `classify_sysv_register_aggregate`); keep them out of the eightbyte
    // path so the two classifiers stay in lockstep.
    if formal_single_x86_gpr_aggregate_lane_type(ty) {
        return None;
    }
    let size = ty.bytes();
    if size == 0 || size > 16 {
        return None;
    }

    if formal_is_sysv_v128_carrier(ty) {
        if size != 16 {
            return None;
        }
        return Some(FormalSysVAggregateLayout {
            lane_count: 1,
            gpr_count: 0,
            xmm_count: 1,
            eightbyte_count: 2,
        });
    }

    let mut eightbytes: [Option<FormalSysVAggregateLaneClass>; 2] = [None, None];
    formal_collect_sysv_aggregate_leaves(ty, 0, &mut eightbytes)?;

    let eightbyte_count = size.div_ceil(8) as usize;
    let mut gpr_count = 0usize;
    let mut xmm_count = 0usize;
    for (idx, class) in eightbytes.iter().enumerate().take(eightbyte_count) {
        let class = (*class)?;
        let valid_bytes = (size - (idx as u32) * 8).min(8);
        if !formal_sysv_eightbyte_lane_representable(valid_bytes) {
            return None;
        }
        match class {
            FormalSysVAggregateLaneClass::Integer => gpr_count += 1,
            FormalSysVAggregateLaneClass::Sse => xmm_count += 1,
        }
    }

    let lane_count = gpr_count + xmm_count;
    if lane_count == 0 {
        return None;
    }

    Some(FormalSysVAggregateLayout {
        lane_count,
        gpr_count,
        xmm_count,
        eightbyte_count: i64::from(size.div_ceil(8)),
    })
}

fn formal_is_two_i64_x86_gpr_aggregate(ty: &Type) -> bool {
    match ty {
        Type::Struct(fields) => matches!(fields.as_slice(), [Type::I64, Type::I64]),
        Type::Array(elem, 2) => matches!(elem.as_ref(), Type::I64),
        _ => false,
    }
}

/// Count the leading formal-argument prologue instructions that ISel
/// (`x86_64_isel.rs::lower_formal_arguments`) emits at the top of the entry
/// block, and the register banks they consume. `fixup_formal_arg_parallel_copy`
/// uses this to bound its scan of the formal-arg shuffle prefix.
///
/// This MUST agree with ISel exactly. Every parameter is either classified the
/// same way ISel classifies it, or this fails closed with a clear
/// [`X86PipelineError`] naming the unsupported shape — never a silent skip,
/// which would desynchronize the prefix scan and miscompile the shuffle. (ISel
/// itself rejects unclassifiable aggregates before the pipeline runs, so a
/// fail-closed here is a defense-in-depth backstop against classifier drift.)
fn formal_arg_prologue_len(
    func: &X86ISelFunction,
    abi: X86CallAbi,
) -> Result<usize, X86PipelineError> {
    let has_sret_return = formal_has_sret_return(func, abi);
    let mut len = usize::from(has_sret_return);
    let mut gpr_idx: usize = if abi == X86CallAbi::SystemV && has_sret_return {
        1
    } else {
        0
    };
    let mut xmm_idx: usize = 0;

    for (idx, ty) in func.sig.params.iter().enumerate() {
        if formal_single_x86_gpr_aggregate_lane_type(ty) {
            match abi {
                X86CallAbi::WindowsX64 => {
                    if idx + usize::from(has_sret_return) < WINDOWS_X64_FORMAL_ARG_GPR_COUNT {
                        len += 1;
                    }
                }
                X86CallAbi::SystemV => {
                    if gpr_idx < X86_ARG_GPRS.len() {
                        len += 1;
                        gpr_idx += 1;
                    }
                }
            }
            continue;
        }

        if let Some(layout) = formal_classify_sysv_register_aggregate(ty, abi) {
            if gpr_idx + layout.gpr_count <= X86_ARG_GPRS.len()
                && xmm_idx + layout.xmm_count <= X86_ARG_XMMS.len()
            {
                // In-register aggregate: ISel emits one copy pseudo per lane.
                len += layout.lane_count;
                gpr_idx += layout.gpr_count;
                xmm_idx += layout.xmm_count;
            } else {
                // Out of registers: ISel defers the loads to the post-prefix
                // materialization phase, so no prefix instruction is emitted.
                let _ = layout.eightbyte_count;
            }
            continue;
        }

        if formal_is_sysv_memory_byval_aggregate(ty, abi) {
            // MEMORY class (>16 bytes, by value): ISel defers the byte copy to
            // the post-prefix materialization phase and consumes no argument
            // register, so no formal-arg prefix instruction is emitted here.
            continue;
        }

        if abi == X86CallAbi::WindowsX64 && formal_is_two_i64_x86_gpr_aggregate(ty) {
            if idx + usize::from(has_sret_return) < WINDOWS_X64_FORMAL_ARG_GPR_COUNT {
                len += 1;
            }
            continue;
        }

        // i128 is a scalar that SysV passes in a *consecutive GPR pair* (two
        // INTEGER eightbytes), so ISel emits two formal-arg copies and consumes
        // two GPRs — not one. Mirror that here, including the two-load SysV
        // stack fallback, and fail closed for the unsupported Windows x64 path
        // so the prefix count can never disagree.
        if *ty == Type::I128 {
            match abi {
                X86CallAbi::WindowsX64 => {
                    return Err(X86PipelineError::ISel(
                        "x86-64 Windows x64 i128 formal parameter ABI not yet implemented \
                         (fail-closed prologue length)"
                            .to_string(),
                    ));
                }
                X86CallAbi::SystemV => {
                    if gpr_idx + 1 < X86_ARG_GPRS.len() {
                        len += 2;
                        gpr_idx += 2;
                    } else {
                        // Stack-passed i128: ISel emits TWO MovRM loads (lo/hi
                        // eightbytes), so count two prefix instructions and do
                        // NOT consume any GPRs. Mirrors the ISel formal-param
                        // stack path so the prologue/body boundary stays exact.
                        len += 2;
                    }
                }
            }
            continue;
        }

        // No aggregate may reach here: ISel classifies every accepted aggregate
        // formal as single-GPR, a register eightbyte aggregate, or a Windows
        // by-ref aggregate above (and rejects all others before the pipeline
        // runs). A leftover aggregate means the two classifiers have drifted —
        // fail closed instead of silently mis-sizing the prologue.
        if formal_is_aggregate_type(ty) {
            return Err(X86PipelineError::ISel(format!(
                "x86-64 formal-arg prologue: unclassified aggregate parameter {idx} \
                 ({ty:?}, {} bytes) under {abi:?} — pipeline/ISel ABI classifiers disagree",
                ty.bytes()
            )));
        }

        // Plain scalar: ISel always emits exactly one prefix instruction (a
        // register copy when a register is available, otherwise a stack load).
        len += 1;
        match abi {
            X86CallAbi::WindowsX64 => {}
            X86CallAbi::SystemV => {
                if matches!(ty, Type::F16 | Type::F32 | Type::F64 | Type::V128) {
                    if xmm_idx < X86_ARG_XMMS.len() {
                        xmm_idx += 1;
                    }
                } else if gpr_idx < X86_ARG_GPRS.len() {
                    gpr_idx += 1;
                }
            }
        }
    }

    Ok(len)
}

/// Classify a formal-arg MOV pseudo-instruction.
///
/// Returns `Some((dst_preg, src_preg, opcode))` if `inst` is
/// `MOV vreg, PReg(arg_reg)` or `MOVSD vreg, PReg(xmm_arg)` where:
/// * the second operand is an argument register for the System V AMD64 ABI,
/// * the first operand is a VReg that the allocator has assigned to a physical
///   register.
///
/// Otherwise returns `None`.
///
/// The returned `opcode` preserves the width of the original move so the
/// resolved PReg-to-PReg copy encodes correctly (`MovRR`/`MovRR32` for GPR,
/// scalar XMM moves for scalar FP, and `MovdqaRR` for full 128-bit values).
fn classify_formal_arg_mov(
    inst: &X86ISelInst,
    alloc: &HashMap<VReg, X86PReg>,
) -> Option<(X86PReg, X86PReg, X86Opcode)> {
    match inst.opcode {
        X86Opcode::MovRR
        | X86Opcode::MovRR32
        | X86Opcode::MovsdRR
        | X86Opcode::MovssRR
        | X86Opcode::MovdqaRR => {}
        _ => return None,
    }
    if inst.operands.len() < 2 {
        return None;
    }
    let X86ISelOperand::VReg(dst_vreg) = &inst.operands[0] else {
        return None;
    };
    let X86ISelOperand::PReg(src_preg) = &inst.operands[1] else {
        return None;
    };
    let src_preg = *src_preg;
    let is_gpr = matches!(inst.opcode, X86Opcode::MovRR | X86Opcode::MovRR32);
    let is_xmm = matches!(
        inst.opcode,
        X86Opcode::MovsdRR | X86Opcode::MovssRR | X86Opcode::MovdqaRR
    );
    if is_gpr && !is_arg_gpr(src_preg) {
        return None;
    }
    if is_xmm && !is_arg_xmm(src_preg) {
        return None;
    }
    let dst_preg = alloc.get(dst_vreg).copied()?;
    Some((dst_preg, src_preg, inst.opcode))
}

fn classify_spilled_formal_arg_mov(
    inst: &X86ISelInst,
    installed_spills: &HashMap<VReg, u32>,
) -> Option<(VReg, X86PReg, u32, X86Opcode)> {
    match inst.opcode {
        X86Opcode::MovRR
        | X86Opcode::MovRR32
        | X86Opcode::MovsdRR
        | X86Opcode::MovssRR
        | X86Opcode::MovdqaRR => {}
        _ => return None,
    }
    if inst.operands.len() < 2 {
        return None;
    }
    let X86ISelOperand::VReg(dst_vreg) = &inst.operands[0] else {
        return None;
    };
    let X86ISelOperand::PReg(src_preg) = &inst.operands[1] else {
        return None;
    };
    let src_preg = *src_preg;
    let is_gpr = matches!(inst.opcode, X86Opcode::MovRR | X86Opcode::MovRR32);
    let is_xmm = matches!(
        inst.opcode,
        X86Opcode::MovsdRR | X86Opcode::MovssRR | X86Opcode::MovdqaRR
    );
    if is_gpr && !is_arg_gpr(src_preg) {
        return None;
    }
    if is_xmm && !is_arg_xmm(src_preg) {
        return None;
    }
    let slot = installed_spills.get(dst_vreg).copied()?;
    Some((*dst_vreg, src_preg, slot, inst.opcode))
}

fn is_formal_stack_arg_load(inst: &X86ISelInst) -> bool {
    match inst.opcode {
        X86Opcode::MovRM8
        | X86Opcode::MovRM16
        | X86Opcode::MovRM32
        | X86Opcode::MovRM
        | X86Opcode::MovsdRM
        | X86Opcode::MovssRM
        | X86Opcode::MovdquRM => {}
        _ => return false,
    }
    if inst.operands.len() < 2 {
        return false;
    }
    if !matches!(&inst.operands[0], X86ISelOperand::VReg(_)) {
        return false;
    }
    matches!(
        &inst.operands[1],
        X86ISelOperand::MemAddr { base, disp }
            if *disp >= 16 && matches!(base.as_ref(), X86ISelOperand::PReg(reg) if *reg == RBP)
    )
}

fn is_interleaved_split_replay_copy(inst: &X86ISelInst) -> bool {
    matches!(
        inst.opcode,
        X86Opcode::MovRR
            | X86Opcode::MovRR32
            | X86Opcode::MovssRR
            | X86Opcode::MovsdRR
            | X86Opcode::MovdqaRR
    ) && matches!(
        inst.operands.as_slice(),
        [X86ISelOperand::VReg(_), X86ISelOperand::VReg(_)]
    )
}

fn x86_spill_formal_copy_opcode(class: RegClass) -> X86Opcode {
    match class {
        RegClass::Gpr32 => X86Opcode::MovRR32,
        RegClass::Fpr32 => X86Opcode::MovssRR,
        RegClass::Fpr64 => X86Opcode::MovsdRR,
        RegClass::Fpr128 => X86Opcode::MovdqaRR,
        _ => X86Opcode::MovRR,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct PhysRegCopy {
    dst: X86PReg,
    src: X86PReg,
    opcode: X86Opcode,
}

fn gpr_copy_opcode_uses_32bit(opcode: X86Opcode) -> bool {
    opcode == X86Opcode::MovRR32
}

fn formal_gpr_copy_error(message: impl Into<String>) -> X86PipelineError {
    X86PipelineError::RegAlloc(message.into())
}

fn gpr_root(reg: X86PReg) -> Result<X86PReg, X86PipelineError> {
    x86_containing_gpr64(reg).ok_or_else(|| {
        formal_gpr_copy_error(format!(
            "x86-64 formal GPR copy expected a GPR register, got {reg:?}"
        ))
    })
}

fn gpr32_alias(reg64: X86PReg) -> Result<X86PReg, X86PipelineError> {
    x86_64_regs::x86_gpr64_to_gpr32(reg64).ok_or_else(|| {
        formal_gpr_copy_error(format!(
            "x86-64 formal GPR copy scratch {reg64:?} has no GPR32 alias"
        ))
    })
}

fn gpr_alias_for_opcode(root64: X86PReg, opcode: X86Opcode) -> Result<X86PReg, X86PipelineError> {
    if gpr_copy_opcode_uses_32bit(opcode) {
        gpr32_alias(root64)
    } else {
        Ok(root64)
    }
}

fn select_gpr_parallel_copy_scratch(copies: &[PhysRegCopy]) -> Result<X86PReg, X86PipelineError> {
    [R11, R10]
        .iter()
        .copied()
        .chain(X86_ALLOCATABLE_GPRS.iter().copied())
        .find(|candidate| {
            copies.iter().all(|copy| {
                !x86_64_regs::x86_regs_overlap(*candidate, copy.dst)
                    && !x86_64_regs::x86_regs_overlap(*candidate, copy.src)
            })
        })
        .ok_or_else(|| {
            formal_gpr_copy_error(
                "x86-64 formal GPR copy has no scratch register outside ABI sources/dests",
            )
        })
}

/// Resolve GPR formal copies across mixed 64-bit/32-bit aliases.
///
/// Unlike the generic resolver below, this keeps `MovRR` and `MovRR32`
/// attached to each copy while treating their roots as one shared storage
/// graph. That prevents a 64-bit destination such as `RCX` from overwriting an
/// incoming 32-bit source such as `ECX` before it has been preserved.
fn resolve_gpr_physreg_parallel_copy(
    copies: &[PhysRegCopy],
    scratch_root: X86PReg,
) -> Result<Vec<PhysRegCopy>, X86PipelineError> {
    let mut remaining: Vec<PhysRegCopy> = copies
        .iter()
        .copied()
        .filter(|copy| !x86_64_regs::x86_regs_overlap(copy.dst, copy.src))
        .collect();
    let mut result: Vec<PhysRegCopy> = Vec::with_capacity(remaining.len() + 2);

    loop {
        let mut progress = true;
        while progress {
            progress = false;
            let mut i = 0;
            while i < remaining.len() {
                let dst = remaining[i].dst;
                let is_source = remaining
                    .iter()
                    .enumerate()
                    .any(|(j, copy)| j != i && x86_64_regs::x86_regs_overlap(copy.src, dst));
                if !is_source {
                    result.push(remaining.remove(i));
                    progress = true;
                } else {
                    i += 1;
                }
            }
        }
        if remaining.is_empty() {
            break;
        }

        let source_root = gpr_root(remaining[0].src)?;
        let save_as_64 =
            remaining
                .iter()
                .try_fold(false, |found, copy| -> Result<bool, X86PipelineError> {
                    Ok(found
                        || (gpr_root(copy.src)? == source_root && copy.opcode == X86Opcode::MovRR))
                })?;
        let save_opcode = if save_as_64 {
            X86Opcode::MovRR
        } else {
            X86Opcode::MovRR32
        };
        result.push(PhysRegCopy {
            dst: gpr_alias_for_opcode(scratch_root, save_opcode)?,
            src: gpr_alias_for_opcode(source_root, save_opcode)?,
            opcode: save_opcode,
        });
        for copy in &mut remaining {
            if gpr_root(copy.src)? == source_root {
                copy.src = gpr_alias_for_opcode(scratch_root, copy.opcode)?;
            }
        }
    }

    Ok(result)
}

/// Resolve a set of `dst <- src` moves on physical registers into a valid
/// sequential schedule. Breaks cycles using `scratch`.
///
/// Input invariants:
/// * All moves have distinct destinations (by construction: regalloc produced
///   them and each writes a different VReg, which maps to a different PReg;
///   duplicates would indicate an allocator bug).
/// * `scratch` must not be any destination nor any source.
/// * All moves share a single `opcode` (the caller batches GPR moves separately
///   from XMM moves so the same `opcode` applies to every entry).
///
/// Output: a sequence of `(dst, src)` moves that, when emitted in order as
/// ordinary `MOV`/`MOVSD`, produces the same simultaneous effect as the input
/// parallel copy. Self-copies (`dst == src`) are dropped.
///
/// Algorithm: topological sort — repeatedly emit any move whose destination is
/// not used as a source by any remaining move. When no such move exists, all
/// remaining moves participate in cycles; break the first cycle by saving its
/// destination into `scratch` and rewriting every reader of that destination
/// to read from `scratch` instead. Repeat until empty.
///
/// Reference: Hack et al., "Register Allocation for Programs in SSA Form",
/// chapter on parallel copies; also see `phi_elim.rs::resolve_parallel_copies`
/// which implements the same algorithm on VRegs.
#[cfg(test)]
fn resolve_physreg_parallel_copy(
    copies: &[(X86PReg, X86PReg)],
    scratch: X86PReg,
) -> Vec<(X86PReg, X86PReg)> {
    // Drop self-copies up front; they are no-ops in parallel-copy semantics.
    let mut remaining: Vec<(X86PReg, X86PReg)> =
        copies.iter().copied().filter(|(d, s)| d != s).collect();
    let mut result: Vec<(X86PReg, X86PReg)> = Vec::with_capacity(remaining.len() + 2);

    // Interleave topological emit with cycle breaking. Each outer iteration
    // drains all moves whose destination is not read by any remaining move
    // (safe to emit directly), then breaks one cycle if any remain.
    //
    // Breaking a cycle by copying `src -> scratch` (exposing the value for
    // later reads) and rewriting any remaining move that reads `src` to
    // read `scratch` instead transforms the graph so `src` is no longer a
    // source in `remaining`. A subsequent topological pass will then emit
    // the move that writes `src` safely — which in turn unblocks more moves.
    loop {
        // Phase 1: topological emit — repeat until no more progress.
        let mut progress = true;
        while progress {
            progress = false;
            let mut i = 0;
            while i < remaining.len() {
                let (dst, _) = remaining[i];
                let is_source = remaining
                    .iter()
                    .enumerate()
                    .any(|(j, &(_, s))| j != i && s == dst);
                if !is_source {
                    result.push(remaining.remove(i));
                    progress = true;
                } else {
                    i += 1;
                }
            }
        }
        if remaining.is_empty() {
            break;
        }

        // Phase 2: break one cycle. Pick any remaining move (pop the first)
        // and copy its SOURCE into scratch; rewrite every remaining read of
        // that source to read from scratch instead. This makes `src` no
        // longer appear as a source in `remaining`, so the move that writes
        // `src` can be safely topologically emitted in the next phase-1 pass.
        let (_d0, s0) = remaining[0];
        result.push((scratch, s0));
        for copy in &mut remaining {
            if copy.1 == s0 {
                copy.1 = scratch;
            }
        }
    }

    result
}

fn resolve_xmm_physreg_parallel_copy(copies: &[PhysRegCopy], scratch: X86PReg) -> Vec<PhysRegCopy> {
    let mut remaining: Vec<PhysRegCopy> = copies
        .iter()
        .copied()
        .filter(|copy| copy.dst != copy.src)
        .collect();
    let mut result: Vec<PhysRegCopy> = Vec::with_capacity(remaining.len() + 2);

    loop {
        let mut progress = true;
        while progress {
            progress = false;
            let mut i = 0;
            while i < remaining.len() {
                let dst = remaining[i].dst;
                let is_source = remaining
                    .iter()
                    .enumerate()
                    .any(|(j, copy)| j != i && copy.src == dst);
                if !is_source {
                    result.push(remaining.remove(i));
                    progress = true;
                } else {
                    i += 1;
                }
            }
        }
        if remaining.is_empty() {
            break;
        }

        let source = remaining[0].src;
        result.push(PhysRegCopy {
            dst: scratch,
            src: source,
            opcode: X86Opcode::MovdqaRR,
        });
        for copy in &mut remaining {
            if copy.src == source {
                copy.src = scratch;
            }
        }
    }

    result
}

/// Post-regalloc fixup for the formal-argument parallel copy (#497, #499).
///
/// `lower_formal_arguments` emits a formal-preservation prefix before any
/// aggregate materialization: scalar formals contribute one register move or
/// stack load, while supported register aggregates contribute one move per
/// ABI lane. After register allocation maps each `vreg` to some physical
/// register, these sequential moves can clobber each other:
///
/// ```text
/// # trust_ir: fn sum8(i0..i7: i64). i3 arrives in RCX.
/// # Regalloc picked v0 -> RCX (fine on its own), v3 -> some callee-saved.
/// MOV RCX, RDI    # v0 <- RDI     *** OVERWRITES incoming i3 (still in RCX) ***
/// MOV RSI, RSI    # (elided self-copy)
/// MOV RDX, RDX    # ...
/// MOV <v3>, RCX   # v3 <- RCX, but RCX now holds i0, not i3 -> WRONG.
/// ```
///
/// The register allocator is not aware that the incoming arg PRegs are live
/// across the MOV sequence, so it freely reassigns VRegs to any arg PReg.
/// The fix is to treat the entire MOV prologue as a parallel copy on physical
/// registers and resolve it using a topological schedule with cycle-breaking
/// via a scratch register.
///
/// This pass runs AFTER regalloc assigns VRegs to PRegs and BEFORE the
/// two-address fixup (so downstream passes see a sequence of ordinary MOVs
/// that happens to be correct).
///
/// GPR and XMM copies are resolved independently (disjoint register files).
/// The scratch register for GPR cycle-breaking is `R11`, which is volatile and
/// not an argument register on both supported x86-64 host ABIs. For XMM
/// cycle-breaking, SysV uses `XMM15`; Windows x64 uses volatile `XMM4` because
/// `XMM6..=XMM15` are non-volatile there.
///
/// Limitations:
/// * Stack-argument loads (`MOV vreg, [RBP+disp]`) are not parallel-copy
///   sources, but they can clobber incoming argument registers. This pass
///   preserves all register arguments first, then emits stack loads in their
///   original order.
/// * If regalloc ever assigns an incoming source value to the selected scratch,
///   using it as scratch would clobber that source. The configured scratches
///   are deliberately outside the register-argument source set for their ABI.
///
/// # Arguments
/// * `func` — the ISel function to rewrite in place.
/// * `alloc` — the VReg-to-PReg allocation produced by regalloc.
fn fixup_formal_arg_parallel_copy(
    func: &mut X86ISelFunction,
    alloc: &HashMap<VReg, X86PReg>,
    installed_spills: &HashMap<VReg, u32>,
    abi: X86CallAbi,
) -> Result<(), X86PipelineError> {
    let formal_count_limit = formal_arg_prologue_len(func, abi)?;
    if formal_count_limit == 0 {
        return Ok(());
    }
    let entry = match func.block_order.first().copied() {
        Some(b) => b,
        None => return Ok(()),
    };
    let block = match func.blocks.get_mut(&entry) {
        Some(b) => b,
        None => return Ok(()),
    };

    // 1. Identify the leading formal-argument prologue. Stack-passed formals
    //    can be interleaved with later register-passed formals from another
    //    register bank, so keep scanning through stack loads.
    let mut prefix_len: usize = 0;
    let mut gpr_copies: Vec<PhysRegCopy> = Vec::new();
    let mut xmm_copies: Vec<PhysRegCopy> = Vec::new();
    let mut spilled_formals: Vec<(VReg, X86PReg, u32)> = Vec::new();
    let mut post_preserve_prefix: Vec<X86ISelInst> = Vec::new();
    let mut scan_len: usize = 0;
    for inst in &block.insts {
        if prefix_len >= formal_count_limit {
            break;
        }
        match classify_formal_arg_mov(inst, alloc) {
            Some((dst, src, X86Opcode::MovRR)) => {
                gpr_copies.push(PhysRegCopy {
                    dst,
                    src,
                    opcode: X86Opcode::MovRR,
                });
                prefix_len += 1;
            }
            Some((dst, src, X86Opcode::MovRR32)) => {
                gpr_copies.push(PhysRegCopy {
                    dst,
                    src,
                    opcode: X86Opcode::MovRR32,
                });
                prefix_len += 1;
            }
            Some((dst, src, X86Opcode::MovsdRR))
            | Some((dst, src, X86Opcode::MovssRR))
            | Some((dst, src, X86Opcode::MovdqaRR)) => {
                xmm_copies.push(PhysRegCopy {
                    dst,
                    src,
                    opcode: inst.opcode,
                });
                prefix_len += 1;
            }
            Some(_) => break, // unreachable: classify_formal_arg_mov filters opcodes
            None => {
                if is_formal_stack_arg_load(inst) {
                    post_preserve_prefix.push(inst.clone());
                    prefix_len += 1;
                } else if let Some((vreg, src, slot, _opcode)) =
                    classify_spilled_formal_arg_mov(inst, installed_spills)
                {
                    spilled_formals.push((vreg, src, slot));
                    prefix_len += 1;
                } else if prefix_len > 0 && is_interleaved_split_replay_copy(inst) {
                    post_preserve_prefix.push(inst.clone());
                } else {
                    break;
                }
            }
        }
        scan_len += 1;
    }

    if prefix_len == 0 {
        return Ok(());
    }

    // 2. Resolve each partition independently. GPR and XMM share no physical
    //    storage, so they cannot form cross-class cycles.
    let gpr_scratch = select_gpr_parallel_copy_scratch(&gpr_copies)?;
    let resolved_gpr = resolve_gpr_physreg_parallel_copy(&gpr_copies, gpr_scratch)?;
    let xmm_scratch = match abi {
        X86CallAbi::SystemV => XMM15,
        X86CallAbi::WindowsX64 => XMM4,
    };
    let resolved_xmm = resolve_xmm_physreg_parallel_copy(&xmm_copies, xmm_scratch);

    // 3. Splice the resolved sequence in place of the original prefix.
    //
    //    The ordering between the GPR and XMM blocks is irrelevant: they
    //    commute (no shared storage). We emit GPR first for readability;
    //    downstream disassembly conventionally shows integer-arg-shuffle
    //    before FP-arg-shuffle. Stack loads come after all register sources
    //    are preserved because their destinations may be argument registers.
    let tail: Vec<X86ISelInst> = block.insts.drain(scan_len..).collect();
    block.insts.clear();
    for (vreg, src, slot) in spilled_formals {
        let scratch = match x86_reg_bank_for_class(vreg.class) {
            Some(X86RegBank::Gpr) => x86_spill_gpr_scratch_regs(vreg.class)[0],
            Some(X86RegBank::Xmm) => x86_spill_xmm_scratch_regs(abi)[0],
            None => continue,
        };
        block.insts.push(X86ISelInst::new(
            x86_spill_formal_copy_opcode(vreg.class),
            vec![X86ISelOperand::PReg(scratch), X86ISelOperand::PReg(src)],
        ));
        block.insts.push(X86ISelInst::new(
            x86_spill_store_opcode(vreg.class),
            vec![x86_spill_stack_mem(slot), X86ISelOperand::PReg(scratch)],
        ));
    }
    for copy in resolved_gpr {
        block.insts.push(X86ISelInst::new(
            copy.opcode,
            vec![
                X86ISelOperand::PReg(copy.dst),
                X86ISelOperand::PReg(copy.src),
            ],
        ));
    }
    for copy in resolved_xmm {
        block.insts.push(X86ISelInst::new(
            copy.opcode,
            vec![
                X86ISelOperand::PReg(copy.dst),
                X86ISelOperand::PReg(copy.src),
            ],
        ));
    }
    block.insts.extend(post_preserve_prefix);
    block.insts.extend(tail);
    Ok(())
}

// ---------------------------------------------------------------------------
// System V AMD64 ABI prologue/epilogue
// ---------------------------------------------------------------------------

/// Compute the stack frame size (16-byte aligned).
///
/// System V AMD64 frame layout:
/// ```text
/// [caller's frame]
/// return address        <- RSP on entry
/// saved RBP             <- RBP after push
/// callee-saved regs
/// local variables / spill slots
/// [outgoing args area]  <- RSP (16-byte aligned)
/// ```
#[cfg(test)]
fn compute_frame_size(num_callee_saved: usize, num_spills: u32) -> u32 {
    compute_frame_size_for_locals(num_callee_saved, num_spills * 8)
}

fn compute_frame_size_for_locals(num_callee_saved: usize, local_bytes: u32) -> u32 {
    // Each callee-saved register is 8 bytes (PUSH).
    // RBP is saved separately.
    // After PUSH RBP: RSP is 16-byte aligned (return addr + RBP = 16 bytes).
    // After pushing callee-saved: may be misaligned.
    // We need the total to bring RSP to 16-byte alignment.
    let total_pushes = 1 + num_callee_saved as u32; // RBP + callee-saved
    let push_bytes = total_pushes * 8;
    // Return address is 8 bytes, so on entry RSP % 16 == 8.
    // After all pushes: (8 + push_bytes) % 16 should equal 0 after sub.
    let unaligned = (8 + push_bytes + local_bytes) % 16;
    let padding = if unaligned != 0 { 16 - unaligned } else { 0 };

    local_bytes + padding
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct X86StackFrameLayout {
    frame_size: u32,
    stack_slot_offsets: Vec<Option<i32>>,
    xmm_save_offsets: Vec<i32>,
    has_dynamic_alloc: bool,
}

fn align_up(value: u32, align: u32) -> Result<u32, X86PipelineError> {
    if align == 0 || !align.is_power_of_two() {
        return Err(X86PipelineError::FrameLowering(format!(
            "invalid x86-64 stack slot alignment {align}"
        )));
    }
    let mask = align - 1;
    value
        .checked_add(mask)
        .map(|v| v & !mask)
        .ok_or_else(|| X86PipelineError::FrameLowering("x86-64 frame size overflow".to_string()))
}

fn compute_x86_stack_frame_layout(
    func: &X86ISelFunction,
    num_callee_saved: usize,
    num_callee_saved_xmms: usize,
    num_spills: u32,
) -> Result<X86StackFrameLayout, X86PipelineError> {
    let callee_saved_bytes = (num_callee_saved as u32)
        .checked_mul(8)
        .ok_or_else(|| X86PipelineError::FrameLowering("x86-64 frame size overflow".to_string()))?;
    let spill_bytes = num_spills
        .checked_mul(8)
        .ok_or_else(|| X86PipelineError::FrameLowering("x86-64 frame size overflow".to_string()))?;
    let mut cursor = callee_saved_bytes
        .checked_add(spill_bytes)
        .ok_or_else(|| X86PipelineError::FrameLowering("x86-64 frame size overflow".to_string()))?;
    let mut xmm_save_offsets = Vec::with_capacity(num_callee_saved_xmms);
    if num_callee_saved_xmms > 0 {
        cursor = align_up(cursor, 16)?;
        for _ in 0..num_callee_saved_xmms {
            cursor = cursor.checked_add(16).ok_or_else(|| {
                X86PipelineError::FrameLowering("x86-64 frame size overflow".to_string())
            })?;
            let offset = i32::try_from(cursor).map_err(|_| {
                X86PipelineError::FrameLowering("x86-64 XMM save offset overflow".to_string())
            })?;
            xmm_save_offsets.push(-offset);
        }
    }
    let mut stack_slot_offsets = Vec::with_capacity(func.stack_slots.len());
    let has_dynamic_alloc = function_has_x86_dynamic_stack_alloc_pseudos(func);

    for slot in &func.stack_slots {
        if slot.is_runtime_sized() {
            stack_slot_offsets.push(None);
            continue;
        }

        cursor = align_up(cursor, slot.align)?;
        cursor = cursor.checked_add(slot.size).ok_or_else(|| {
            X86PipelineError::FrameLowering("x86-64 frame size overflow".to_string())
        })?;
        let offset = i32::try_from(cursor).map_err(|_| {
            X86PipelineError::FrameLowering("x86-64 stack slot offset overflow".to_string())
        })?;
        stack_slot_offsets.push(Some(-offset));
    }

    if func.max_outgoing_call_bytes > 0 {
        let outgoing_bytes = align_up(func.max_outgoing_call_bytes, 16)?;
        cursor = cursor.checked_add(outgoing_bytes).ok_or_else(|| {
            X86PipelineError::FrameLowering("x86-64 frame size overflow".to_string())
        })?;
    }

    let local_bytes = cursor.checked_sub(callee_saved_bytes).ok_or_else(|| {
        X86PipelineError::FrameLowering("x86-64 frame size underflow".to_string())
    })?;
    let frame_size = compute_frame_size_for_locals(num_callee_saved, local_bytes);

    Ok(X86StackFrameLayout {
        frame_size,
        stack_slot_offsets,
        xmm_save_offsets,
        has_dynamic_alloc,
    })
}

fn resolve_x86_stack_slots_in_operand(
    op: &mut X86ISelOperand,
    layout: &X86StackFrameLayout,
) -> Result<(), X86PipelineError> {
    match op {
        X86ISelOperand::MemAddr { base, disp } => {
            if let X86ISelOperand::StackSlot(slot) = base.as_ref() {
                let Some(slot_offset) = layout.stack_slot_offsets.get(*slot as usize) else {
                    return Err(X86PipelineError::FrameLowering(format!(
                        "x86-64 StackAddr references missing stack slot {slot}"
                    )));
                };
                let Some(slot_offset) = slot_offset else {
                    return Err(X86PipelineError::FrameLowering(format!(
                        "runtime-sized x86-64 stack slot {slot} requires dynamic SP cursor lowering before frame index elimination"
                    )));
                };
                let total_disp = i64::from(*slot_offset) + i64::from(*disp);
                let resolved_disp = i32::try_from(total_disp).map_err(|_| {
                    X86PipelineError::FrameLowering(
                        "x86-64 resolved stack slot displacement overflow".to_string(),
                    )
                })?;
                **base = X86ISelOperand::PReg(RBP);
                *disp = resolved_disp;
            } else {
                resolve_x86_stack_slots_in_operand(base, layout)?;
            }
        }
        X86ISelOperand::SibMemAddr {
            base, index, disp, ..
        } => {
            if let X86ISelOperand::StackSlot(slot) = base.as_ref() {
                let Some(slot_offset) = layout.stack_slot_offsets.get(*slot as usize) else {
                    return Err(X86PipelineError::FrameLowering(format!(
                        "x86-64 StackAddr references missing stack slot {slot}"
                    )));
                };
                let Some(slot_offset) = slot_offset else {
                    return Err(X86PipelineError::FrameLowering(format!(
                        "runtime-sized x86-64 stack slot {slot} requires dynamic SP cursor lowering before frame index elimination"
                    )));
                };
                let total_disp = i64::from(*slot_offset) + i64::from(*disp);
                let resolved_disp = i32::try_from(total_disp).map_err(|_| {
                    X86PipelineError::FrameLowering(
                        "x86-64 resolved stack slot displacement overflow".to_string(),
                    )
                })?;
                **base = X86ISelOperand::PReg(RBP);
                *disp = resolved_disp;
            } else {
                resolve_x86_stack_slots_in_operand(base, layout)?;
            }
            resolve_x86_stack_slots_in_operand(index, layout)?;
        }
        X86ISelOperand::StackSlot(slot) => {
            return Err(X86PipelineError::FrameLowering(format!(
                "bare x86-64 StackSlot operand {slot} cannot be encoded"
            )));
        }
        _ => {}
    }
    Ok(())
}

fn resolve_x86_stack_slots(
    func: &mut X86ISelFunction,
    layout: &X86StackFrameLayout,
) -> Result<(), X86PipelineError> {
    for block_id in func.block_order.clone() {
        if let Some(block) = func.blocks.get_mut(&block_id) {
            for inst in &mut block.insts {
                for op in &mut inst.operands {
                    resolve_x86_stack_slots_in_operand(op, layout)?;
                }
            }
        }
    }
    Ok(())
}

fn has_x86_stack_slot_operand(op: &X86ISelOperand) -> bool {
    match op {
        X86ISelOperand::StackSlot(_) => true,
        X86ISelOperand::MemAddr { base, .. } => has_x86_stack_slot_operand(base),
        X86ISelOperand::SibMemAddr { base, index, .. } => {
            has_x86_stack_slot_operand(base) || has_x86_stack_slot_operand(index)
        }
        _ => false,
    }
}

fn function_has_x86_stack_slot_operands(func: &X86ISelFunction) -> bool {
    func.blocks.values().any(|block| {
        block
            .insts
            .iter()
            .any(|inst| inst.operands.iter().any(has_x86_stack_slot_operand))
    })
}

fn collect_x86_stack_slot_uses(op: &X86ISelOperand, used: &mut HashSet<u32>) {
    match op {
        X86ISelOperand::StackSlot(slot) => {
            used.insert(*slot);
        }
        X86ISelOperand::MemAddr { base, .. } => collect_x86_stack_slot_uses(base, used),
        X86ISelOperand::SibMemAddr { base, index, .. } => {
            collect_x86_stack_slot_uses(base, used);
            collect_x86_stack_slot_uses(index, used);
        }
        _ => {}
    }
}

fn remap_x86_stack_slot_operand(op: &mut X86ISelOperand, old_to_new: &HashMap<u32, u32>) {
    match op {
        X86ISelOperand::StackSlot(slot) => {
            if let Some(new_slot) = old_to_new.get(slot) {
                *slot = *new_slot;
            }
        }
        X86ISelOperand::MemAddr { base, .. } => remap_x86_stack_slot_operand(base, old_to_new),
        X86ISelOperand::SibMemAddr { base, index, .. } => {
            remap_x86_stack_slot_operand(base, old_to_new);
            remap_x86_stack_slot_operand(index, old_to_new);
        }
        _ => {}
    }
}

fn prune_unused_x86_stack_slots(func: &mut X86ISelFunction) {
    if func.stack_slots.is_empty() {
        return;
    }

    let mut used = HashSet::new();
    for block in func.blocks.values() {
        for inst in &block.insts {
            for operand in &inst.operands {
                collect_x86_stack_slot_uses(operand, &mut used);
            }
        }
    }

    if used.len() == func.stack_slots.len() {
        return;
    }

    let mut old_to_new = HashMap::new();
    let mut stack_slots = Vec::with_capacity(used.len());
    for (old_slot, slot) in func.stack_slots.iter().cloned().enumerate() {
        let old_slot = old_slot as u32;
        if used.contains(&old_slot) {
            old_to_new.insert(old_slot, stack_slots.len() as u32);
            stack_slots.push(slot);
        }
    }

    for block in func.blocks.values_mut() {
        for inst in &mut block.insts {
            for operand in &mut inst.operands {
                remap_x86_stack_slot_operand(operand, &old_to_new);
            }
        }
    }

    func.stack_slots = stack_slots;
}

fn function_has_x86_dynamic_stack_alloc_pseudos(func: &X86ISelFunction) -> bool {
    func.blocks.values().any(|block| {
        block
            .insts
            .iter()
            .any(|inst| inst.opcode == X86Opcode::StackAlloc)
    })
}

fn function_has_x86_calls(func: &X86ISelFunction) -> bool {
    func.blocks.values().any(|block| {
        block.insts.iter().any(|inst| {
            matches!(
                inst.opcode,
                X86Opcode::Call | X86Opcode::CallR | X86Opcode::CallM
            )
        })
    })
}

fn prepare_x86_windows_fixed_outgoing_frame(
    config: &X86PipelineConfig,
    func: &mut X86ISelFunction,
) {
    if config.call_abi == X86CallAbi::WindowsX64 && function_has_x86_calls(func) {
        func.max_outgoing_call_bytes = func
            .max_outgoing_call_bytes
            .max(WINDOWS_X64_SHADOW_SPACE_BYTES);
    }
}

fn reject_windows_x64_frameless_non_leaf(
    config: &X86PipelineConfig,
    func: &X86ISelFunction,
) -> Result<(), X86PipelineError> {
    if config.call_abi == X86CallAbi::WindowsX64
        && !config.emit_frame
        && function_has_x86_calls(func)
    {
        return Err(X86PipelineError::FrameLowering(
            "Windows x64 calls require a fixed outgoing call frame; emit_frame=false".to_string(),
        ));
    }
    Ok(())
}

fn effective_x86_output_format(config: &X86PipelineConfig) -> X86OutputFormat {
    if config.output_format != X86OutputFormat::RawBytes {
        config.output_format
    } else if config.emit_elf {
        X86OutputFormat::Elf
    } else {
        X86OutputFormat::RawBytes
    }
}

/// Fail closed before lowering an EH function for an output format whose
/// writer cannot carry the exact LSDA/personality/FDE bundle.
///
/// Mach-O module emission is the sole wired x86 EH path. Raw bytes have no
/// unwind metadata at all, the ELF writer currently emits only LSDA-less
/// backtrace FDEs, and the COFF writer has no `.pdata`/`.xdata` EH path.
fn reject_unwired_x86_eh_output(
    config: &X86PipelineConfig,
    func: &X86ISelFunction,
) -> Result<(), X86PipelineError> {
    if func.eh_info.is_empty() {
        return Ok(());
    }
    let format = effective_x86_output_format(config);
    let reason = match format {
        X86OutputFormat::MachO => return Ok(()),
        X86OutputFormat::RawBytes => {
            "raw bytes cannot carry LSDA, personality, or unwind-frame metadata"
        }
        X86OutputFormat::Elf => {
            "the ELF writer emits no LSDA/personality-bearing FDEs for language-level EH"
        }
        X86OutputFormat::Coff => {
            "the COFF writer emits no .pdata/.xdata language-level EH metadata"
        }
    };
    Err(X86PipelineError::EhOutputUnsupported {
        function: func.name.clone(),
        format,
        reason: format!(
            "{reason}; emitting code alone would strand landing pads and skip cleanup Drops \
             (fail-closed)"
        ),
    })
}

/// Raw per-function fixup APIs cannot return the EH sidecar even when their
/// configured object format is Mach-O. Reject instead of silently discarding
/// metadata; callers that need EH must use `compile_module`/`compile_function`.
fn reject_x86_eh_sidecar_drop(
    config: &X86PipelineConfig,
    func: &X86ISelFunction,
    api: &str,
) -> Result<(), X86PipelineError> {
    if func.eh_info.is_empty() {
        return Ok(());
    }
    Err(X86PipelineError::EhOutputUnsupported {
        function: func.name.clone(),
        format: effective_x86_output_format(config),
        reason: format!(
            "`{api}` returns code/fixups without the exact LSDA/FDE sidecar; use the \
             EH-aware object/module API instead (fail-closed)"
        ),
    })
}

fn windows_coff_unwind_requirement_reason(
    func: &X86ISelFunction,
    assignment: &X86RegAssignment,
    emit_frame: bool,
) -> Option<String> {
    if emit_frame {
        let unsupported_callee_saved: Vec<X86PReg> = assignment
            .used_callee_saved
            .iter()
            .copied()
            .filter(|reg| x86_windows_nonvolatile_gpr_push_size(*reg).is_none())
            .collect();
        if !unsupported_callee_saved.is_empty() {
            return Some(format!(
                "unsupported Windows callee-saved GPR save metadata: {unsupported_callee_saved:?}"
            ));
        }
        if function_has_x86_dynamic_stack_alloc_pseudos(func)
            && !assignment.used_callee_saved_xmms.is_empty()
        {
            return Some("callee-saved XMM saves with dynamic stack allocation".to_string());
        }
        return None;
    }
    if function_has_x86_calls(func) {
        return Some("direct or indirect call in a non-leaf function".to_string());
    }
    if assignment.num_spills > 0 {
        return Some(format!("{} register spill slot(s)", assignment.num_spills));
    }
    if !assignment.used_callee_saved.is_empty() {
        return Some(format!(
            "callee-saved GPR save(s): {:?}",
            assignment.used_callee_saved
        ));
    }
    if !assignment.used_callee_saved_xmms.is_empty() {
        return Some(format!(
            "Windows callee-saved XMM save(s): {:?}",
            assignment.used_callee_saved_xmms
        ));
    }
    if function_has_x86_stack_slot_operands(func) {
        return Some("fixed stack-slot operand".to_string());
    }
    if function_has_x86_dynamic_stack_alloc_pseudos(func) {
        return Some("dynamic stack allocation".to_string());
    }
    None
}

fn reject_windows_coff_without_unwind_metadata(
    config: &X86PipelineConfig,
    func: &X86ISelFunction,
    assignment: &X86RegAssignment,
) -> Result<(), X86PipelineError> {
    if effective_x86_output_format(config) != X86OutputFormat::Coff
        || config.call_abi != X86CallAbi::WindowsX64
    {
        return Ok(());
    }

    if let Some(reason) =
        windows_coff_unwind_requirement_reason(func, assignment, config.emit_frame)
    {
        return Err(X86PipelineError::WindowsCoffUnwindMetadataRequired {
            function: func.name.clone(),
            reason,
        });
    }
    Ok(())
}

const UWOP_PUSH_NONVOL: u8 = 0;
const UWOP_ALLOC_LARGE: u8 = 1;
const UWOP_ALLOC_SMALL: u8 = 2;
const UWOP_SET_FPREG: u8 = 3;
const UWOP_SAVE_XMM128: u8 = 8;

fn x86_alu_ri_uses_imm8(imm: i64) -> bool {
    let imm32 = imm as i32;
    i32::from(imm32 as i8) == imm32
}

fn x86_alu_ri_encoded_size(dst: X86PReg, imm: i64) -> usize {
    let rex_len = usize::from(!dst.is_gpr32() || dst.needs_rex());
    let imm_len = if x86_alu_ri_uses_imm8(imm) { 1 } else { 4 };
    rex_len + 1 + 1 + imm_len
}

fn x86_low_byte_reg_needs_rex(reg: X86PReg) -> bool {
    matches!(reg.hw_enc() & 0x7, 4..=7)
}

fn x86_mem_reg_rex_len(reg: X86PReg, base: X86PReg, w: bool, byte_reg: bool) -> usize {
    let needs_rex = w || reg.needs_rex() || base.needs_rex();
    let forced_rex = byte_reg && x86_low_byte_reg_needs_rex(reg);
    usize::from(needs_rex || forced_rex)
}

fn x86_base_disp_mem_reg_encoded_size(
    reg: X86PReg,
    base: X86PReg,
    disp: i64,
    w: bool,
    operand_size_prefix: bool,
    byte_reg: bool,
) -> usize {
    usize::from(operand_size_prefix)
        + x86_mem_reg_rex_len(reg, base, w, byte_reg)
        + 1
        + x86_base_disp_mem_operand_size(base, disp)
}

fn x86_mem_width_for_opcode(opcode: X86Opcode) -> Option<(bool, bool, bool)> {
    match opcode {
        X86Opcode::MovRM8 | X86Opcode::MovMR8 => Some((false, false, true)),
        X86Opcode::MovRM16 | X86Opcode::MovMR16 => Some((false, true, false)),
        X86Opcode::MovRM32 | X86Opcode::MovMR32 => Some((false, false, false)),
        X86Opcode::MovRM | X86Opcode::MovMR | X86Opcode::Lea => Some((true, false, false)),
        _ => None,
    }
}

fn x86_mem_reg_fallback_size(opcode: X86Opcode) -> usize {
    if matches!(opcode, X86Opcode::MovRM16 | X86Opcode::MovMR16) {
        9
    } else {
        8
    }
}

fn x86_simple_mem_reg_operands(inst: &X86ISelInst) -> Option<(X86PReg, X86PReg, i64)> {
    let mut reg = None;
    let mut mem = None;

    for operand in &inst.operands {
        match operand {
            X86ISelOperand::PReg(preg) if reg.is_none() => reg = Some(*preg),
            X86ISelOperand::MemAddr { base, disp } => match base.as_ref() {
                X86ISelOperand::PReg(base) => mem = Some((*base, i64::from(*disp))),
                _ => return None,
            },
            _ => {}
        }
    }

    let (base, disp) = mem?;
    Some((reg?, base, disp))
}

fn estimate_x86_base_disp_mem_reg_size(inst: &X86ISelInst) -> usize {
    let Some((w, operand_size_prefix, byte_reg)) = x86_mem_width_for_opcode(inst.opcode) else {
        return x86_mem_reg_fallback_size(inst.opcode);
    };
    let Some((reg, base, disp)) = x86_simple_mem_reg_operands(inst) else {
        return x86_mem_reg_fallback_size(inst.opcode);
    };

    x86_base_disp_mem_reg_encoded_size(reg, base, disp, w, operand_size_prefix, byte_reg)
}

fn estimate_x86_base_disp_rm_alu_size(inst: &X86ISelInst, opcode_len: usize) -> usize {
    let Some((_reg, base, disp)) = x86_simple_mem_reg_operands(inst) else {
        return if opcode_len == 2 { 9 } else { 8 };
    };

    1 + opcode_len + x86_base_disp_mem_operand_size(base, disp)
}

fn x86_movri_uses_zero_extending_gpr32_form(imm: i64) -> bool {
    (imm as u64) <= u64::from(u32::MAX)
}

fn x86_movri_preg_encoded_size(dst: X86PReg, imm: i64) -> usize {
    if dst.is_gpr8() {
        return usize::from(dst.needs_rex()) + 1 + 1;
    }
    if dst.is_gpr16() {
        return 1 + usize::from(dst.needs_rex()) + 1 + 2;
    }
    if dst.is_gpr32() {
        return usize::from(dst.needs_rex()) + 1 + 4;
    }
    if dst.is_gpr64() {
        if x86_movri_uses_zero_extending_gpr32_form(imm) {
            let Some(alias) = x86_64_regs::x86_gpr64_to_gpr32(dst) else {
                return 10;
            };
            return usize::from(alias.needs_rex()) + 1 + 4;
        }
        return 10;
    }
    10
}

fn x86_movri_vreg_estimated_size(vreg: VReg, imm: i64) -> usize {
    match vreg.class {
        RegClass::Gpr32 => 6,
        RegClass::Gpr64 if x86_movri_uses_zero_extending_gpr32_form(imm) => 6,
        RegClass::Gpr64 => 10,
        _ => 10,
    }
}

fn estimate_x86_movri_size(inst: &X86ISelInst) -> usize {
    match (inst.operands.first(), inst.operands.get(1)) {
        (Some(X86ISelOperand::PReg(dst)), Some(X86ISelOperand::Imm(imm))) => {
            x86_movri_preg_encoded_size(*dst, *imm)
        }
        (Some(X86ISelOperand::VReg(vreg)), Some(X86ISelOperand::Imm(imm))) => {
            x86_movri_vreg_estimated_size(*vreg, *imm)
        }
        _ => 10,
    }
}

fn x86_base_disp_mem_operand_size(base: X86PReg, disp: i64) -> usize {
    let base_low3 = base.hw_enc() & 0x7;
    let sib_len = usize::from(base_low3 == 4);
    let disp_len = if disp == 0 && base_low3 != 5 {
        0
    } else if (-128..=127).contains(&disp) {
        1
    } else {
        4
    };
    1 + sib_len + disp_len
}

fn estimate_x86_ptest_size(inst: &X86ISelInst) -> usize {
    const PREFIX_AND_OPCODE_LEN: usize = 4; // 66 0F 38 17
    let Some(X86ISelOperand::PReg(dst)) = inst.operands.first() else {
        return 11;
    };

    match inst.operands.get(1) {
        Some(X86ISelOperand::PReg(src)) => {
            PREFIX_AND_OPCODE_LEN + usize::from(dst.needs_rex() || src.needs_rex()) + 1
        }
        Some(X86ISelOperand::MemAddr { base, disp }) => {
            let X86ISelOperand::PReg(base) = base.as_ref() else {
                return 11;
            };
            PREFIX_AND_OPCODE_LEN
                + usize::from(dst.needs_rex() || base.needs_rex())
                + x86_base_disp_mem_operand_size(*base, i64::from(*disp))
        }
        _ => 11,
    }
}

fn estimate_x86_pshufd_size(inst: &X86ISelInst) -> usize {
    const PREFIX_OPCODE_IMM_LEN: usize = 4; // 66 0F 70 ib
    let Some(X86ISelOperand::PReg(dst)) = inst.operands.first() else {
        return 11;
    };

    match inst.operands.get(1) {
        Some(X86ISelOperand::PReg(src)) => {
            PREFIX_OPCODE_IMM_LEN + usize::from(dst.needs_rex() || src.needs_rex()) + 1
        }
        Some(X86ISelOperand::MemAddr { base, disp }) => {
            let X86ISelOperand::PReg(base) = base.as_ref() else {
                return 11;
            };
            PREFIX_OPCODE_IMM_LEN
                + usize::from(dst.needs_rex() || base.needs_rex())
                + x86_base_disp_mem_operand_size(*base, i64::from(*disp))
        }
        _ => 11,
    }
}

fn x86_stack_alloc_encoded_size(frame_size: u32) -> u8 {
    x86_alu_ri_encoded_size(RSP, i64::from(frame_size)) as u8
}

fn x86_windows_nonvolatile_gpr_push_size(reg: X86PReg) -> Option<u8> {
    match reg {
        x86_64_regs::RBX | x86_64_regs::RSI | x86_64_regs::RDI => Some(1),
        x86_64_regs::R12 | x86_64_regs::R13 | x86_64_regs::R14 | x86_64_regs::R15 => Some(2),
        _ => None,
    }
}

fn x86_windows_xmm_save_size(reg: X86PReg, rbp_disp: i32) -> Result<u8, X86PipelineError> {
    if !reg.is_xmm() {
        return Err(X86PipelineError::WindowsCoffUnwindMetadataRequired {
            function: "<unknown>".to_string(),
            reason: format!("unsupported Windows x64 XMM save register: {reg:?}"),
        });
    }

    let rex_len = usize::from(reg.hw_enc() >= 8);
    let disp_len = if (-128..=127).contains(&rbp_disp) {
        1usize
    } else {
        4usize
    };
    u8::try_from(1 + rex_len + 2 + 1 + disp_len).map_err(|_| {
        X86PipelineError::WindowsCoffUnwindMetadataRequired {
            function: "<unknown>".to_string(),
            reason: "Windows x64 XMM save size exceeds UNWIND_INFO range".to_string(),
        }
    })
}

#[derive(Debug, Clone, Copy)]
struct X86UnwindCode {
    code_offset: u8,
    unwind_op: u8,
    op_info: u8,
}

impl X86UnwindCode {
    fn emit(self, out: &mut Vec<u8>) {
        out.push(self.code_offset);
        out.push((self.op_info << 4) | (self.unwind_op & 0x0f));
    }
}

#[derive(Debug, Clone, Copy)]
struct X86UnwindEntry {
    code: X86UnwindCode,
    extra_word: Option<u16>,
}

impl X86UnwindEntry {
    fn new(code: X86UnwindCode) -> Self {
        Self {
            code,
            extra_word: None,
        }
    }

    fn with_extra_word(mut self, value: u16) -> Self {
        self.extra_word = Some(value);
        self
    }

    fn slot_count(self) -> usize {
        1 + usize::from(self.extra_word.is_some())
    }

    fn emit(self, out: &mut Vec<u8>) {
        self.code.emit(out);
        if let Some(value) = self.extra_word {
            out.extend_from_slice(&value.to_le_bytes());
        }
    }
}

fn x86_64_coff_unwind_info(metadata: &X86FrameMetadata) -> Result<Vec<u8>, X86PipelineError> {
    if metadata.has_dynamic_alloc && !metadata.callee_saved_xmms.is_empty() {
        return Err(X86PipelineError::WindowsCoffUnwindMetadataRequired {
            function: "<unknown>".to_string(),
            reason: "Windows x64 COFF unwind metadata does not yet support callee-saved XMM saves with dynamic stack allocation".to_string(),
        });
    }
    if !metadata.frame_size.is_multiple_of(8) {
        return Err(X86PipelineError::FrameLowering(format!(
            "Windows x64 frame size {} is not 8-byte aligned",
            metadata.frame_size
        )));
    }
    if metadata.callee_saved_xmms.len() != metadata.xmm_save_offsets.len() {
        return Err(X86PipelineError::FrameLowering(format!(
            "Windows x64 XMM save metadata length mismatch: {} register(s), {} offset(s)",
            metadata.callee_saved_xmms.len(),
            metadata.xmm_save_offsets.len()
        )));
    }

    let mut entries: Vec<X86UnwindEntry> = Vec::new();
    let mut prologue_cursor = 4u8; // PUSH RBP (1) + MOV RBP, RSP (3).
    let mut callee_saved_pushes = Vec::with_capacity(metadata.callee_saved.len());
    for &reg in &metadata.callee_saved {
        let push_size = x86_windows_nonvolatile_gpr_push_size(reg).ok_or_else(|| {
            X86PipelineError::WindowsCoffUnwindMetadataRequired {
                function: "<unknown>".to_string(),
                reason: format!("unsupported Windows x64 callee-saved GPR push: {reg:?}"),
            }
        })?;
        prologue_cursor = prologue_cursor.checked_add(push_size).ok_or_else(|| {
            X86PipelineError::WindowsCoffUnwindMetadataRequired {
                function: "<unknown>".to_string(),
                reason: "Windows x64 prologue size exceeds UNWIND_INFO range".to_string(),
            }
        })?;
        callee_saved_pushes.push((reg, prologue_cursor));
    }
    let frame_alloc_code_offset = if metadata.frame_size > 0 {
        prologue_cursor
            .checked_add(x86_stack_alloc_encoded_size(metadata.frame_size))
            .ok_or_else(|| X86PipelineError::WindowsCoffUnwindMetadataRequired {
                function: "<unknown>".to_string(),
                reason: "Windows x64 prologue size exceeds UNWIND_INFO range".to_string(),
            })?
    } else {
        prologue_cursor
    };
    if metadata.frame_size > 0 {
        if metadata.frame_size <= 128 {
            entries.push(X86UnwindEntry::new(X86UnwindCode {
                code_offset: frame_alloc_code_offset,
                unwind_op: UWOP_ALLOC_SMALL,
                op_info: ((metadata.frame_size - 8) / 8) as u8,
            }));
        } else if metadata.frame_size <= (512 * 1024 - 8) {
            entries.push(
                X86UnwindEntry::new(X86UnwindCode {
                    code_offset: frame_alloc_code_offset,
                    unwind_op: UWOP_ALLOC_LARGE,
                    op_info: 0,
                })
                .with_extra_word((metadata.frame_size / 8) as u16),
            );
        } else {
            return Err(X86PipelineError::WindowsCoffUnwindMetadataRequired {
                function: "<unknown>".to_string(),
                reason: format!(
                    "frame allocation {} exceeds supported UWOP_ALLOC_LARGE short form",
                    metadata.frame_size
                ),
            });
        }
    }

    let final_rsp_from_rbp =
        i64::from(metadata.frame_size) + (metadata.callee_saved.len() as i64 * 8);
    let mut xmm_cursor = frame_alloc_code_offset;
    for (&reg, &rbp_disp) in metadata
        .callee_saved_xmms
        .iter()
        .zip(metadata.xmm_save_offsets.iter())
    {
        let save_len = x86_windows_xmm_save_size(reg, rbp_disp)?;
        xmm_cursor = xmm_cursor.checked_add(save_len).ok_or_else(|| {
            X86PipelineError::WindowsCoffUnwindMetadataRequired {
                function: "<unknown>".to_string(),
                reason: "Windows x64 prologue size exceeds UNWIND_INFO range".to_string(),
            }
        })?;
        let stack_offset = final_rsp_from_rbp + i64::from(rbp_disp);
        if stack_offset < 0 || stack_offset % 16 != 0 {
            return Err(X86PipelineError::WindowsCoffUnwindMetadataRequired {
                function: "<unknown>".to_string(),
                reason: format!(
                    "callee-saved XMM save for {reg:?} has unsupported stack offset {stack_offset}"
                ),
            });
        }
        let scaled_offset =
            u16::try_from(stack_offset / 16).map_err(|_| {
                X86PipelineError::WindowsCoffUnwindMetadataRequired {
                    function: "<unknown>".to_string(),
                    reason: format!(
                        "callee-saved XMM save offset {stack_offset} exceeds supported UWOP_SAVE_XMM128 range"
                    ),
                }
            })?;
        entries.push(
            X86UnwindEntry::new(X86UnwindCode {
                code_offset: xmm_cursor,
                unwind_op: UWOP_SAVE_XMM128,
                op_info: reg.hw_enc(),
            })
            .with_extra_word(scaled_offset),
        );
    }
    let prolog_size = xmm_cursor;

    for &(reg, code_offset) in callee_saved_pushes.iter().rev() {
        entries.push(X86UnwindEntry::new(X86UnwindCode {
            code_offset,
            unwind_op: UWOP_PUSH_NONVOL,
            op_info: reg.hw_enc(),
        }));
    }
    let uses_frame_register = metadata.callee_saved_xmms.is_empty();
    if uses_frame_register {
        entries.push(X86UnwindEntry::new(X86UnwindCode {
            code_offset: 4,
            unwind_op: UWOP_SET_FPREG,
            op_info: 0,
        }));
    }
    entries.push(X86UnwindEntry::new(X86UnwindCode {
        code_offset: 1,
        unwind_op: UWOP_PUSH_NONVOL,
        op_info: RBP.hw_enc(),
    }));
    entries.sort_by_key(|right| std::cmp::Reverse(right.code.code_offset));

    let count_of_codes = entries
        .iter()
        .copied()
        .map(X86UnwindEntry::slot_count)
        .sum::<usize>();
    let count_of_codes_u8 = u8::try_from(count_of_codes).map_err(|_| {
        X86PipelineError::WindowsCoffUnwindMetadataRequired {
            function: "<unknown>".to_string(),
            reason: format!("too many Windows unwind code slots: {count_of_codes}"),
        }
    })?;

    let mut out = Vec::new();
    out.push(1); // version 1, no flags
    out.push(prolog_size);
    out.push(count_of_codes_u8);
    out.push(if uses_frame_register { RBP.hw_enc() } else { 0 });

    for entry in entries.iter().copied() {
        entry.emit(&mut out);
    }
    if count_of_codes % 2 != 0 {
        out.extend_from_slice(&[0, 0]);
    }
    while out.len() % 4 != 0 {
        out.push(0);
    }
    Ok(out)
}

fn x86_64_coff_unwind_record(
    metadata: &X86FrameMetadata,
    function: &str,
    text_offset: u64,
    code_len: u32,
    xdata_offset: u32,
) -> Result<X86CoffUnwindRecord, X86PipelineError> {
    let mut unwind_info = x86_64_coff_unwind_info(metadata).map_err(|err| match err {
        X86PipelineError::WindowsCoffUnwindMetadataRequired { reason, .. } => {
            X86PipelineError::WindowsCoffUnwindMetadataRequired {
                function: function.to_string(),
                reason,
            }
        }
        other => other,
    })?;
    while unwind_info.len() % 4 != 0 {
        unwind_info.push(0);
    }

    let text_offset = checked_x86_object_u32_u64(function, "COFF unwind text offset", text_offset)?;
    Ok(X86CoffUnwindRecord {
        text_offset,
        code_len,
        unwind_info_offset: xdata_offset,
        unwind_info,
    })
}

fn build_x86_64_coff_unwind_sections(
    records: &[X86CoffUnwindRecord],
) -> Result<(Vec<u8>, Vec<u8>), X86PipelineError> {
    checked_x86_object_u32_table_size("<module>", "COFF .pdata byte length", records.len(), 12)?;
    if let Some(last_index) = records.len().checked_sub(1) {
        // Validate the last serialized relocation-bearing member before a
        // potentially multi-gigabyte allocation. All earlier records are then
        // in range by monotonicity.
        checked_x86_object_table_member_offset(
            "<module>",
            "COFF .pdata unwind relocation offset",
            last_index,
            12,
            8,
        )?;
    }
    let pdata_capacity =
        checked_x86_object_table_size("<module>", "COFF .pdata byte length", records.len(), 12)?;
    let mut pdata = Vec::with_capacity(pdata_capacity);
    let mut xdata = Vec::new();
    for record in records {
        pdata.extend_from_slice(&record.text_offset.to_le_bytes());
        let end = record
            .text_offset
            .checked_add(record.code_len)
            .ok_or_else(|| {
                X86PipelineError::FrameLowering("COFF unwind function range overflow".to_string())
            })?;
        pdata.extend_from_slice(&end.to_le_bytes());
        pdata.extend_from_slice(&record.unwind_info_offset.to_le_bytes());

        if xdata.len() != record.unwind_info_offset as usize {
            return Err(X86PipelineError::FrameLowering(
                "COFF unwind .xdata offset mismatch".to_string(),
            ));
        }
        xdata.extend_from_slice(&record.unwind_info);
    }
    Ok((pdata, xdata))
}

fn x86_stack_alloc_preg(
    operand: &X86ISelOperand,
    alloc: &HashMap<VReg, X86PReg>,
    context: &'static str,
) -> Result<X86PReg, X86PipelineError> {
    let reg = resolve_operand(operand, alloc).ok_or_else(|| {
        X86PipelineError::FrameLowering(format!(
            "x86-64 StackAlloc {context} must be a register, got {operand:?}"
        ))
    })?;
    x86_containing_gpr64(reg).ok_or_else(|| {
        X86PipelineError::FrameLowering(format!(
            "x86-64 StackAlloc {context} must be a GPR, got {reg:?}"
        ))
    })
}

fn x86_preg_operand(reg: X86PReg) -> X86ISelOperand {
    X86ISelOperand::PReg(reg)
}

fn x86_push_inst(opcode: X86Opcode, operands: Vec<X86ISelOperand>, out: &mut Vec<X86ISelInst>) {
    out.push(X86ISelInst::new(opcode, operands));
}

fn x86_fresh_vreg_operand(func: &mut X86ISelFunction, class: RegClass) -> X86ISelOperand {
    let vreg = VReg::new(func.next_vreg, class);
    func.next_vreg += 1;
    X86ISelOperand::VReg(vreg)
}

fn x86_isel_operand_is_gpr32(op: &X86ISelOperand) -> bool {
    match op {
        X86ISelOperand::VReg(vreg) => vreg.class == RegClass::Gpr32,
        X86ISelOperand::PReg(preg) => preg.is_gpr32(),
        _ => false,
    }
}

fn x86_isel_operand_gpr_class(op: &X86ISelOperand) -> Option<RegClass> {
    match op {
        X86ISelOperand::VReg(vreg) if vreg.class == RegClass::Gpr32 => Some(RegClass::Gpr32),
        X86ISelOperand::VReg(vreg) if vreg.class == RegClass::Gpr64 => Some(RegClass::Gpr64),
        X86ISelOperand::PReg(preg) if preg.is_gpr32() => Some(RegClass::Gpr32),
        X86ISelOperand::PReg(preg) if preg.is_gpr64() => Some(RegClass::Gpr64),
        _ => None,
    }
}

fn x86_isel_operand_is_xmm128(op: &X86ISelOperand) -> bool {
    match op {
        X86ISelOperand::VReg(vreg) => vreg.class == RegClass::Fpr128,
        X86ISelOperand::PReg(preg) => preg.is_xmm(),
        _ => false,
    }
}

fn x86_gpr_copy_opcode(class: RegClass) -> X86Opcode {
    match class {
        RegClass::Gpr32 => X86Opcode::MovRR32,
        RegClass::Gpr64 => X86Opcode::MovRR,
        _ => unreachable!("x86_gpr_copy_opcode called for non-GPR class"),
    }
}

fn expand_x86_popcnt_inst(
    inst: &X86ISelInst,
    func: &mut X86ISelFunction,
) -> Result<Option<Vec<X86ISelInst>>, X86PipelineError> {
    if inst.opcode != X86Opcode::Popcnt {
        return Ok(None);
    }
    if inst.operands.len() != 2 {
        return Err(X86PipelineError::ISel(format!(
            "Popcnt requires operands [dst_gpr, src_gpr], got {} operand(s)",
            inst.operands.len()
        )));
    }

    let dst = inst.operands[0].clone();
    let src = inst.operands[1].clone();
    let Some(class) = x86_isel_operand_gpr_class(&dst) else {
        return Err(X86PipelineError::ISel(format!(
            "Popcnt requires GPR destination, got {:?}",
            inst.operands
        )));
    };
    if x86_isel_operand_gpr_class(&src) != Some(class) {
        return Err(X86PipelineError::ISel(format!(
            "Popcnt requires matching GPR source/destination widths, got {:?}",
            inst.operands
        )));
    }

    let copy_opcode = x86_gpr_copy_opcode(class);
    let tmp = x86_fresh_vreg_operand(func, class);
    let mask = x86_fresh_vreg_operand(func, class);
    let mut replacement = Vec::with_capacity(if class == RegClass::Gpr64 { 31 } else { 27 });

    let push_masked_tmp = |shift: i64, mask_value: i64, out: &mut Vec<X86ISelInst>| {
        x86_push_inst(copy_opcode, vec![tmp.clone(), dst.clone()], out);
        x86_push_inst(
            X86Opcode::ShrRI,
            vec![tmp.clone(), X86ISelOperand::Imm(shift)],
            out,
        );
        x86_push_inst(
            X86Opcode::MovRI,
            vec![mask.clone(), X86ISelOperand::Imm(mask_value)],
            out,
        );
        x86_push_inst(
            X86Opcode::AndRR,
            vec![tmp.clone(), tmp.clone(), mask.clone()],
            out,
        );
    };

    let (m1, m2, m4, final_mask) = match class {
        RegClass::Gpr32 => (0x5555_5555_i64, 0x3333_3333_i64, 0x0f0f_0f0f_i64, 0x3f_i64),
        RegClass::Gpr64 => (
            0x5555_5555_5555_5555_i64,
            0x3333_3333_3333_3333_i64,
            0x0f0f_0f0f_0f0f_0f0f_i64,
            0x7f_i64,
        ),
        _ => unreachable!("class checked above"),
    };

    x86_push_inst(copy_opcode, vec![dst.clone(), src], &mut replacement);

    push_masked_tmp(1, m1, &mut replacement);
    x86_push_inst(
        X86Opcode::SubRR,
        vec![dst.clone(), dst.clone(), tmp.clone()],
        &mut replacement,
    );

    x86_push_inst(
        copy_opcode,
        vec![tmp.clone(), dst.clone()],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::MovRI,
        vec![mask.clone(), X86ISelOperand::Imm(m2)],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::AndRR,
        vec![dst.clone(), dst.clone(), mask.clone()],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::ShrRI,
        vec![tmp.clone(), X86ISelOperand::Imm(2)],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::AndRR,
        vec![tmp.clone(), tmp.clone(), mask.clone()],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::AddRR,
        vec![dst.clone(), dst.clone(), tmp.clone()],
        &mut replacement,
    );

    x86_push_inst(
        copy_opcode,
        vec![tmp.clone(), dst.clone()],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::ShrRI,
        vec![tmp.clone(), X86ISelOperand::Imm(4)],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::AddRR,
        vec![dst.clone(), dst.clone(), tmp.clone()],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::MovRI,
        vec![mask.clone(), X86ISelOperand::Imm(m4)],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::AndRR,
        vec![dst.clone(), dst.clone(), mask.clone()],
        &mut replacement,
    );

    for shift in [8_i64, 16] {
        x86_push_inst(
            copy_opcode,
            vec![tmp.clone(), dst.clone()],
            &mut replacement,
        );
        x86_push_inst(
            X86Opcode::ShrRI,
            vec![tmp.clone(), X86ISelOperand::Imm(shift)],
            &mut replacement,
        );
        x86_push_inst(
            X86Opcode::AddRR,
            vec![dst.clone(), dst.clone(), tmp.clone()],
            &mut replacement,
        );
    }
    if class == RegClass::Gpr64 {
        x86_push_inst(
            copy_opcode,
            vec![tmp.clone(), dst.clone()],
            &mut replacement,
        );
        x86_push_inst(
            X86Opcode::ShrRI,
            vec![tmp.clone(), X86ISelOperand::Imm(32)],
            &mut replacement,
        );
        x86_push_inst(
            X86Opcode::AddRR,
            vec![dst.clone(), dst.clone(), tmp.clone()],
            &mut replacement,
        );
    }

    x86_push_inst(
        X86Opcode::AndRI,
        vec![dst, X86ISelOperand::Imm(final_mask)],
        &mut replacement,
    );

    Ok(Some(replacement))
}

fn expand_x86_generic_popcnts(
    func: &mut X86ISelFunction,
    target_features: X86TargetFeatures,
) -> Result<(), X86PipelineError> {
    if target_features.contains(X86TargetFeature::Popcnt) {
        return Ok(());
    }

    for block_id in func.block_order.clone() {
        let old_insts = {
            let Some(block) = func.blocks.get_mut(&block_id) else {
                continue;
            };
            std::mem::take(&mut block.insts)
        };
        let mut new_insts = Vec::with_capacity(old_insts.len());

        for inst in old_insts {
            if let Some(replacement) = expand_x86_popcnt_inst(&inst, func)? {
                new_insts.extend(replacement);
            } else {
                new_insts.push(inst);
            }
        }

        let Some(block) = func.blocks.get_mut(&block_id) else {
            continue;
        };
        block.insts = new_insts;
    }

    Ok(())
}

fn x86_ptest_self_operand(inst: &X86ISelInst) -> Option<X86ISelOperand> {
    if inst.opcode != X86Opcode::Ptest || inst.operands.len() != 2 {
        return None;
    }

    let lhs = &inst.operands[0];
    let rhs = &inst.operands[1];
    if lhs != rhs || !x86_isel_operand_is_xmm128(lhs) {
        return None;
    }

    Some(lhs.clone())
}

fn x86_inst_uses_e_or_ne_flags(inst: &X86ISelInst) -> bool {
    if !matches!(
        inst.opcode,
        X86Opcode::Jcc | X86Opcode::Cmovcc | X86Opcode::Cmovcc32
    ) {
        return false;
    }

    inst.operands.iter().any(|operand| {
        matches!(
            operand,
            X86ISelOperand::CondCode(X86CondCode::E | X86CondCode::NE)
        )
    })
}

fn expand_x86_ptest_self_zero_test_inst(
    inst: &X86ISelInst,
    next: Option<&X86ISelInst>,
    func: &mut X86ISelFunction,
) -> Option<Vec<X86ISelInst>> {
    let src = x86_ptest_self_operand(inst)?;
    if !next.is_some_and(x86_inst_uses_e_or_ne_flags) {
        return None;
    }

    let zero = x86_fresh_vreg_operand(func, RegClass::Fpr128);
    let mask = x86_fresh_vreg_operand(func, RegClass::Gpr32);
    let mut replacement = Vec::with_capacity(4);
    let (cmp_dst, cmp_lhs, cmp_rhs) = if matches!(src, X86ISelOperand::VReg(_)) {
        (zero.clone(), zero.clone(), src)
    } else {
        (
            x86_fresh_vreg_operand(func, RegClass::Fpr128),
            src,
            zero.clone(),
        )
    };

    x86_push_inst(
        X86Opcode::Pxor,
        vec![zero.clone(), zero.clone()],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::Pcmpeqd,
        vec![cmp_dst.clone(), cmp_lhs, cmp_rhs],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::Pmovmskb,
        vec![mask.clone(), cmp_dst],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::CmpRI,
        vec![mask, X86ISelOperand::Imm(0xffff)],
        &mut replacement,
    );

    Some(replacement)
}

fn expand_x86_generic_ptest_zero_tests(
    func: &mut X86ISelFunction,
    target_features: X86TargetFeatures,
) {
    if target_features.contains(X86TargetFeature::Sse41) {
        return;
    }

    for block_id in func.block_order.clone() {
        let old_insts = {
            let Some(block) = func.blocks.get_mut(&block_id) else {
                continue;
            };
            std::mem::take(&mut block.insts)
        };
        let mut new_insts = Vec::with_capacity(old_insts.len());

        for index in 0..old_insts.len() {
            let inst = &old_insts[index];
            if let Some(replacement) =
                expand_x86_ptest_self_zero_test_inst(inst, old_insts.get(index + 1), func)
            {
                new_insts.extend(replacement);
            } else {
                new_insts.push(inst.clone());
            }
        }

        let Some(block) = func.blocks.get_mut(&block_id) else {
            continue;
        };
        block.insts = new_insts;
    }
}

fn expand_x86_v4i32_mask_extract_inst(
    inst: &X86ISelInst,
    _func: &mut X86ISelFunction,
) -> Result<Option<Vec<X86ISelInst>>, X86PipelineError> {
    if inst.opcode != X86Opcode::V4I32MaskExtract {
        return Ok(None);
    }
    if inst.operands.len() != 2 {
        return Err(X86PipelineError::ISel(format!(
            "V4I32MaskExtract requires operands [dst_gpr32, src_xmm], got {} operand(s)",
            inst.operands.len()
        )));
    }

    let dst = inst.operands[0].clone();
    let src = inst.operands[1].clone();
    if !x86_isel_operand_is_gpr32(&dst) || !x86_isel_operand_is_xmm128(&src) {
        return Err(X86PipelineError::ISel(format!(
            "V4I32MaskExtract requires dst_gpr32 and src_xmm operands, got {:?}",
            inst.operands
        )));
    }

    let mut replacement = Vec::with_capacity(4);

    x86_push_inst(
        X86Opcode::Pmovmskb,
        vec![dst.clone(), src],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::ImulRRI,
        vec![dst.clone(), dst.clone(), X86ISelOperand::Imm(39)],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::ShrRI,
        vec![dst.clone(), X86ISelOperand::Imm(9)],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::AndRI,
        vec![dst, X86ISelOperand::Imm(0x0f)],
        &mut replacement,
    );

    Ok(Some(replacement))
}

fn expand_x86_v16i8_mask_extract_inst(
    inst: &X86ISelInst,
    _func: &mut X86ISelFunction,
) -> Result<Option<Vec<X86ISelInst>>, X86PipelineError> {
    if inst.opcode != X86Opcode::V16I8MaskExtract {
        return Ok(None);
    }
    if inst.operands.len() != 2 {
        return Err(X86PipelineError::ISel(format!(
            "V16I8MaskExtract requires operands [dst_gpr32, src_xmm], got {} operand(s)",
            inst.operands.len()
        )));
    }

    let dst = inst.operands[0].clone();
    let src = inst.operands[1].clone();
    if !x86_isel_operand_is_gpr32(&dst) || !x86_isel_operand_is_xmm128(&src) {
        return Err(X86PipelineError::ISel(format!(
            "V16I8MaskExtract requires dst_gpr32 and src_xmm operands, got {:?}",
            inst.operands
        )));
    }

    let mut replacement = Vec::with_capacity(2);
    x86_push_inst(
        X86Opcode::Pmovmskb,
        vec![dst.clone(), src],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::AndRI,
        vec![dst, X86ISelOperand::Imm(0xffff)],
        &mut replacement,
    );

    Ok(Some(replacement))
}

fn expand_x86_v8i16_mask_extract_inst(
    inst: &X86ISelInst,
    func: &mut X86ISelFunction,
) -> Result<Option<Vec<X86ISelInst>>, X86PipelineError> {
    if inst.opcode != X86Opcode::V8I16MaskExtract {
        return Ok(None);
    }
    if inst.operands.len() != 2 {
        return Err(X86PipelineError::ISel(format!(
            "V8I16MaskExtract requires operands [dst_gpr32, src_xmm], got {} operand(s)",
            inst.operands.len()
        )));
    }

    let dst = inst.operands[0].clone();
    let src = inst.operands[1].clone();
    if !x86_isel_operand_is_gpr32(&dst) || !x86_isel_operand_is_xmm128(&src) {
        return Err(X86PipelineError::ISel(format!(
            "V8I16MaskExtract requires dst_gpr32 and src_xmm operands, got {:?}",
            inst.operands
        )));
    }

    let tmp = x86_fresh_vreg_operand(func, RegClass::Gpr32);
    let mut replacement = Vec::with_capacity(14);

    x86_push_inst(
        X86Opcode::Pmovmskb,
        vec![dst.clone(), src],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::AndRI,
        vec![dst.clone(), X86ISelOperand::Imm(0x5555)],
        &mut replacement,
    );

    for (shift, mask) in [(1_i64, 0x3333_i64), (2, 0x0f0f), (4, 0x00ff)] {
        x86_push_inst(
            X86Opcode::MovRR32,
            vec![tmp.clone(), dst.clone()],
            &mut replacement,
        );
        x86_push_inst(
            X86Opcode::ShrRI,
            vec![tmp.clone(), X86ISelOperand::Imm(shift)],
            &mut replacement,
        );
        x86_push_inst(
            X86Opcode::OrRR,
            vec![dst.clone(), dst.clone(), tmp.clone()],
            &mut replacement,
        );
        x86_push_inst(
            X86Opcode::AndRI,
            vec![dst.clone(), X86ISelOperand::Imm(mask)],
            &mut replacement,
        );
    }

    Ok(Some(replacement))
}

fn expand_x86_v2i64_mask_extract_inst(
    inst: &X86ISelInst,
    _func: &mut X86ISelFunction,
) -> Result<Option<Vec<X86ISelInst>>, X86PipelineError> {
    if inst.opcode != X86Opcode::V2I64MaskExtract {
        return Ok(None);
    }
    if inst.operands.len() != 2 {
        return Err(X86PipelineError::ISel(format!(
            "V2I64MaskExtract requires operands [dst_gpr32, src_xmm], got {} operand(s)",
            inst.operands.len()
        )));
    }

    let dst = inst.operands[0].clone();
    let src = inst.operands[1].clone();
    if !x86_isel_operand_is_gpr32(&dst) || !x86_isel_operand_is_xmm128(&src) {
        return Err(X86PipelineError::ISel(format!(
            "V2I64MaskExtract requires dst_gpr32 and src_xmm operands, got {:?}",
            inst.operands
        )));
    }

    let mut replacement = Vec::with_capacity(3);

    x86_push_inst(
        X86Opcode::Pmovmskb,
        vec![dst.clone(), src],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::ShrRI,
        vec![dst.clone(), X86ISelOperand::Imm(7)],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::AndRI,
        vec![dst, X86ISelOperand::Imm(0x03)],
        &mut replacement,
    );

    Ok(Some(replacement))
}

fn x86_operand_overlaps_preg(op: &X86ISelOperand, preg: X86PReg) -> bool {
    matches!(op, X86ISelOperand::PReg(p) if x86_64_regs::x86_regs_overlap(*p, preg))
}

fn x86_operands_alias(lhs: &X86ISelOperand, rhs: &X86ISelOperand) -> bool {
    match (lhs, rhs) {
        (X86ISelOperand::VReg(lhs), X86ISelOperand::VReg(rhs)) => lhs == rhs,
        (X86ISelOperand::PReg(lhs), X86ISelOperand::PReg(rhs)) => {
            x86_64_regs::x86_regs_overlap(*lhs, *rhs)
        }
        _ => false,
    }
}

fn expand_x86_v128_bool_select_inst(
    inst: &X86ISelInst,
    func: &mut X86ISelFunction,
    target_features: X86TargetFeatures,
) -> Result<Option<Vec<X86ISelInst>>, X86PipelineError> {
    if inst.opcode != X86Opcode::V128BoolSelect {
        return Ok(None);
    }
    if inst.operands.len() != 4 {
        return Err(X86PipelineError::ISel(format!(
            "V128BoolSelect requires operands [dst_xmm, mask_xmm, true_xmm, false_xmm], got {} operand(s)",
            inst.operands.len()
        )));
    }

    let dst = inst.operands[0].clone();
    let mask = inst.operands[1].clone();
    let true_val = inst.operands[2].clone();
    let false_val = inst.operands[3].clone();
    if !x86_isel_operand_is_xmm128(&dst)
        || !x86_isel_operand_is_xmm128(&mask)
        || !x86_isel_operand_is_xmm128(&true_val)
        || !x86_isel_operand_is_xmm128(&false_val)
    {
        return Err(X86PipelineError::ISel(format!(
            "V128BoolSelect requires four XMM operands, got {:?}",
            inst.operands
        )));
    }

    if x86_operands_alias(&true_val, &false_val) {
        if x86_operands_alias(&dst, &true_val) {
            return Ok(Some(Vec::new()));
        }
        return Ok(Some(vec![X86ISelInst::new(
            X86Opcode::MovdqaRR,
            vec![dst, true_val],
        )]));
    }

    let dst_aliases_mask = x86_operands_alias(&dst, &mask);
    let dst_aliases_true = x86_operands_alias(&dst, &true_val);
    let dst_aliases_false = x86_operands_alias(&dst, &false_val);
    let false_overlaps_implicit_mask = x86_operand_overlaps_preg(&false_val, XMM0);
    // `false_val` would be clobbered when it lives in the implicit XMM0 mask
    // register that `dst` also aliases. Named so the guard below stays a plain
    // conjunction of preconditions (rewriting it as a negated disjunction to
    // satisfy `nonminimal_bool` would obscure what each term rules out).
    let false_clobbered_by_mask = dst_aliases_mask && false_overlaps_implicit_mask;

    if target_features.contains(X86TargetFeature::Sse41)
        && !x86_operand_overlaps_preg(&dst, XMM0)
        && !x86_operand_overlaps_preg(&true_val, XMM0)
        && !dst_aliases_true
        && !false_clobbered_by_mask
    {
        let mut replacement = Vec::with_capacity(3);

        if dst_aliases_mask {
            x86_push_inst(
                X86Opcode::MovdqaRR,
                vec![x86_preg_operand(XMM0), mask],
                &mut replacement,
            );
            if !dst_aliases_false {
                x86_push_inst(
                    X86Opcode::MovdqaRR,
                    vec![dst.clone(), false_val],
                    &mut replacement,
                );
            }
        } else {
            if !dst_aliases_false {
                x86_push_inst(
                    X86Opcode::MovdqaRR,
                    vec![dst.clone(), false_val],
                    &mut replacement,
                );
            }
            x86_push_inst(
                X86Opcode::MovdqaRR,
                vec![x86_preg_operand(XMM0), mask],
                &mut replacement,
            );
        }

        x86_push_inst(X86Opcode::Pblendvb, vec![dst, true_val], &mut replacement);
        return Ok(Some(replacement));
    }

    let true_masked = x86_fresh_vreg_operand(func, RegClass::Fpr128);
    let false_masked = x86_fresh_vreg_operand(func, RegClass::Fpr128);
    let mut replacement = Vec::with_capacity(3);
    x86_push_inst(
        X86Opcode::Pand,
        vec![true_masked.clone(), mask.clone(), true_val],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::Pandn,
        vec![false_masked.clone(), mask, false_val],
        &mut replacement,
    );
    x86_push_inst(
        X86Opcode::Por,
        vec![dst, true_masked, false_masked],
        &mut replacement,
    );

    Ok(Some(replacement))
}

fn expand_x86_vector_bool_selects(
    func: &mut X86ISelFunction,
    target_features: X86TargetFeatures,
) -> Result<(), X86PipelineError> {
    for block_id in func.block_order.clone() {
        let old_insts = {
            let Some(block) = func.blocks.get_mut(&block_id) else {
                continue;
            };
            std::mem::take(&mut block.insts)
        };
        let mut new_insts = Vec::with_capacity(old_insts.len());

        for inst in old_insts {
            if inst.opcode == X86Opcode::V128BoolSelect {
                if let Some(replacement) =
                    expand_x86_v128_bool_select_inst(&inst, func, target_features)?
                {
                    new_insts.extend(replacement);
                }
            } else {
                new_insts.push(inst);
            }
        }

        let Some(block) = func.blocks.get_mut(&block_id) else {
            continue;
        };
        block.insts = new_insts;
    }

    Ok(())
}

fn expand_x86_vector_mask_extracts(func: &mut X86ISelFunction) -> Result<(), X86PipelineError> {
    for block_id in func.block_order.clone() {
        let old_insts = {
            let Some(block) = func.blocks.get_mut(&block_id) else {
                continue;
            };
            std::mem::take(&mut block.insts)
        };
        let mut new_insts = Vec::with_capacity(old_insts.len());

        for inst in old_insts {
            if matches!(
                inst.opcode,
                X86Opcode::V4I32MaskExtract
                    | X86Opcode::V16I8MaskExtract
                    | X86Opcode::V8I16MaskExtract
                    | X86Opcode::V2I64MaskExtract
            ) {
                let replacement = match inst.opcode {
                    X86Opcode::V4I32MaskExtract => expand_x86_v4i32_mask_extract_inst(&inst, func)?,
                    X86Opcode::V16I8MaskExtract => expand_x86_v16i8_mask_extract_inst(&inst, func)?,
                    X86Opcode::V8I16MaskExtract => expand_x86_v8i16_mask_extract_inst(&inst, func)?,
                    X86Opcode::V2I64MaskExtract => expand_x86_v2i64_mask_extract_inst(&inst, func)?,
                    _ => None,
                };
                if let Some(replacement) = replacement {
                    new_insts.extend(replacement);
                }
            } else {
                new_insts.push(inst);
            }
        }

        let Some(block) = func.blocks.get_mut(&block_id) else {
            continue;
        };
        block.insts = new_insts;
    }

    Ok(())
}

fn expand_x86_dynamic_stack_alloc_inst(
    inst: &X86ISelInst,
    alloc: &HashMap<VReg, X86PReg>,
    outgoing_call_bytes: u32,
) -> Result<Option<Vec<X86ISelInst>>, X86PipelineError> {
    if inst.opcode != X86Opcode::StackAlloc {
        return Ok(None);
    }

    let dst = x86_stack_alloc_preg(
        inst.operands.first().ok_or_else(|| {
            X86PipelineError::FrameLowering("x86-64 StackAlloc missing destination".to_string())
        })?,
        alloc,
        "destination",
    )?;
    let count_operand = inst.operands.get(1).ok_or_else(|| {
        X86PipelineError::FrameLowering("x86-64 StackAlloc missing count".to_string())
    })?;
    let unit_size = inst
        .operands
        .get(2)
        .and_then(|op| match op {
            X86ISelOperand::Imm(imm) => Some(*imm),
            _ => None,
        })
        .unwrap_or(1);
    if unit_size <= 0 || unit_size > i32::MAX as i64 {
        return Err(X86PipelineError::FrameLowering(format!(
            "x86-64 StackAlloc unit size must fit i32 and be positive, got {unit_size}"
        )));
    }

    let align = inst
        .operands
        .get(3)
        .and_then(|op| match op {
            X86ISelOperand::Imm(imm) => Some(*imm),
            _ => None,
        })
        .unwrap_or(16);
    if align <= 0 || !((align as u64).is_power_of_two()) {
        return Err(X86PipelineError::FrameLowering(format!(
            "x86-64 StackAlloc alignment must be a positive power of two, got {align}"
        )));
    }
    let align_padding = align - 1;
    if align_padding > i32::MAX as i64 || align > i32::MAX as i64 + 1 {
        return Err(X86PipelineError::FrameLowering(format!(
            "x86-64 StackAlloc alignment must fit imm32 encoding, got {align}"
        )));
    }

    let outgoing_call_bytes = if outgoing_call_bytes == 0 {
        0
    } else {
        align_up(outgoing_call_bytes, 16)?
    };
    if outgoing_call_bytes > i32::MAX as u32 {
        return Err(X86PipelineError::FrameLowering(format!(
            "x86-64 StackAlloc outgoing call area must fit imm32, got {outgoing_call_bytes}"
        )));
    }

    let mut replacement = Vec::with_capacity(7);
    match count_operand {
        X86ISelOperand::Imm(count) => {
            if *count < 0 {
                return Err(X86PipelineError::FrameLowering(format!(
                    "x86-64 StackAlloc count must be non-negative, got {count}"
                )));
            }
            let bytes = count.checked_mul(unit_size).ok_or_else(|| {
                X86PipelineError::FrameLowering(
                    "x86-64 StackAlloc immediate size overflow".to_string(),
                )
            })?;
            x86_push_inst(
                X86Opcode::MovRI,
                vec![x86_preg_operand(dst), X86ISelOperand::Imm(bytes)],
                &mut replacement,
            );
        }
        _ => {
            let src = x86_stack_alloc_preg(count_operand, alloc, "count")?;
            if unit_size == 1 {
                if src != dst {
                    x86_push_inst(
                        X86Opcode::MovRR,
                        vec![x86_preg_operand(dst), x86_preg_operand(src)],
                        &mut replacement,
                    );
                }
            } else {
                x86_push_inst(
                    X86Opcode::ImulRRI,
                    vec![
                        x86_preg_operand(dst),
                        x86_preg_operand(src),
                        X86ISelOperand::Imm(unit_size),
                    ],
                    &mut replacement,
                );
            }
        }
    }

    if align <= 16 {
        x86_push_inst(
            X86Opcode::AddRI,
            vec![x86_preg_operand(dst), X86ISelOperand::Imm(15)],
            &mut replacement,
        );
        x86_push_inst(
            X86Opcode::AndRI,
            vec![x86_preg_operand(dst), X86ISelOperand::Imm(-16)],
            &mut replacement,
        );
        x86_push_inst(
            X86Opcode::SubRR,
            vec![x86_preg_operand(RSP), x86_preg_operand(dst)],
            &mut replacement,
        );
    } else {
        x86_push_inst(
            X86Opcode::AddRI,
            vec![x86_preg_operand(dst), X86ISelOperand::Imm(align_padding)],
            &mut replacement,
        );
        x86_push_inst(
            X86Opcode::SubRR,
            vec![x86_preg_operand(RSP), x86_preg_operand(dst)],
            &mut replacement,
        );
        x86_push_inst(
            X86Opcode::AndRI,
            vec![x86_preg_operand(RSP), X86ISelOperand::Imm(-align)],
            &mut replacement,
        );
    }
    x86_push_inst(
        X86Opcode::MovRR,
        vec![x86_preg_operand(dst), x86_preg_operand(RSP)],
        &mut replacement,
    );
    if outgoing_call_bytes > 0 {
        x86_push_inst(
            X86Opcode::SubRI,
            vec![
                x86_preg_operand(RSP),
                X86ISelOperand::Imm(i64::from(outgoing_call_bytes)),
            ],
            &mut replacement,
        );
    }

    Ok(Some(replacement))
}

fn expand_x86_dynamic_stack_allocs(
    func: &mut X86ISelFunction,
    alloc: &HashMap<VReg, X86PReg>,
) -> Result<(), X86PipelineError> {
    let outgoing_call_bytes = func.max_outgoing_call_bytes;
    for block_id in func.block_order.clone() {
        let Some(block) = func.blocks.get_mut(&block_id) else {
            continue;
        };
        let old_insts = std::mem::take(&mut block.insts);
        let mut new_insts = Vec::with_capacity(old_insts.len());

        for inst in old_insts {
            if let Some(replacement) =
                expand_x86_dynamic_stack_alloc_inst(&inst, alloc, outgoing_call_bytes)?
            {
                new_insts.extend(replacement);
            } else {
                new_insts.push(inst);
            }
        }

        block.insts = new_insts;
    }

    Ok(())
}

/// Translation-validation canary for a Sentinel-S5 guard-carrier expansion: prove
/// the EXACT condition code `cond` the expander is about to emit makes the `Jcc`
/// trap on precisely the carrier's intended set (`index >=u bound` for bounds /
/// shift-range; `== 0` for null / div-zero). The carrier opcode is gone before
/// emission, so the per-instruction certs see only the individually-correct `CMP`
/// and `Jcc` and never bind `cond` to the guard's meaning — a wrong cc (e.g. `B`
/// for `AE`) certifies instruction-by-instruction yet silently inverts the guard.
///
/// Each caller derives ONE local `trap_cond` and passes it here AND to the emitted
/// `Jcc`, so the proof and the emitted code cannot drift. Memoized per kind (the
/// expansion is a static fact) and only ever reached when a carrier of that kind
/// is actually present, so non-guard programs pay nothing. i8 is exhaustive; i32
/// and i64 (the real operand widths) are added when a formal solver is available
/// (each discharges in ~30 ms — the obligation is a single CMP-flag/`Jcc`
/// equality, not a popcount).
fn run_guard_carrier_canary(
    kind: trust_cg_verify::pass_validators::GuardCarrierKind,
    cond: trust_cg_ir::x86_64_ops::X86CondCode,
) -> Result<(), X86PipelineError> {
    use std::sync::OnceLock;
    use trust_cg_verify::ay_bridge::z3_available;
    use trust_cg_verify::pass_validators::{
        GuardCarrierExpansionValidator, GuardCarrierKind, PassValidation, PassValidator,
    };

    static BOUNDS: OnceLock<Result<(), String>> = OnceLock::new();
    static SHIFT: OnceLock<Result<(), String>> = OnceLock::new();
    static NULLZ: OnceLock<Result<(), String>> = OnceLock::new();
    static DIVZ: OnceLock<Result<(), String>> = OnceLock::new();
    let cell = match kind {
        GuardCarrierKind::Bounds => &BOUNDS,
        GuardCarrierKind::ShiftRange => &SHIFT,
        GuardCarrierKind::NullIfZero => &NULLZ,
        GuardCarrierKind::DivZero => &DIVZ,
    };
    cell.get_or_init(|| {
        let mut widths: Vec<u32> = vec![8];
        if z3_available() {
            widths.push(32);
            widths.push(64);
        }
        for width in widths {
            let validator =
                GuardCarrierExpansionValidator::new("x86-guard-carrier-expand", kind, cond, width);
            if let PassValidation::Rejected {
                obligation_name,
                reason,
            } = validator.validate()
            {
                return Err(format!("{obligation_name}: {reason}"));
            }
        }
        Ok(())
    })
    .clone()
    .map_err(|reason| {
        X86PipelineError::ISel(format!(
            "guard-carrier {kind:?} expansion canary REJECTED the emitted condition code \
             {cond:?} — the Jcc would not trap on exactly the intended set (a wrong cc \
             silently inverts/drops the guard): {reason}"
        ))
    })
}

/// OPT-8 kill switch: branch-layout optimization (the `X86BranchLayout` pass
/// AND the encoder's `jmp <layout-next>` fall-through elision) is ON by
/// default and disabled by setting `TCG_NO_BRANCH_LAYOUT` (forensic
/// rollback / A-B comparison; mirrors `TCG_NO_PROOF_CERTS`).
fn x86_branch_layout_enabled() -> bool {
    std::env::var_os("TCG_NO_BRANCH_LAYOUT").is_none()
}

/// OPT-11 kill switch: if-conversion (the `X86IfConvert` pass — value-select
/// diamonds to branchless `CMOVcc`) is ON by default and disabled by setting
/// `TCG_NO_IFCONVERT` (forensic rollback / A-B comparison; mirrors
/// `TCG_NO_BRANCH_LAYOUT`).
fn x86_if_convert_enabled() -> bool {
    std::env::var_os("TCG_NO_IFCONVERT").is_none()
}

/// OPT-12 kill switch: the conservative SSE2 integer vectorizer
/// (`X86Vectorize`) is ON by default and disabled by setting `TCG_NO_VECTORIZE`
/// (forensic rollback / A-B comparison; mirrors `TCG_NO_BRANCH_LAYOUT`). The
/// pass only ever rewrites a loop whose legality is provable by construction
/// (element-wise map over distinct fixed-size local arrays); with the switch
/// set every candidate loop stays scalar (always correct).
fn x86_vectorize_enabled() -> bool {
    std::env::var_os("TCG_NO_VECTORIZE").is_none()
}

/// Kill switch for dominated-identical-compare bounds-check elimination
/// (`X86BoundsCheckElimination`). ON by default at O2/O3; set `TCG_NO_X86_BCE`
/// for forensic rollback / A-B comparison (mirrors `TCG_NO_VECTORIZE`). This
/// pass is safety-critical and sound by construction: it removes a bounds-check
/// trap edge only when a dominating IDENTICAL compare proves it dead, and keeps
/// the check on any doubt. With the switch set every bounds check is kept
/// (always correct).
fn x86_bce_enabled() -> bool {
    std::env::var_os("TCG_NO_X86_BCE").is_none()
}

/// OPT-3a kill switch: induction-variable strength reduction
/// (`X86StrengthReduce` — loop-body `imul iv, stride` to an add recurrence)
/// is ON by default and disabled by setting `TCG_NO_STRENGTH_REDUCE`
/// (forensic rollback / A-B comparison; mirrors `TCG_NO_VECTORIZE`). With the
/// switch set every candidate multiply stays a multiply (always correct).
fn x86_strength_reduce_enabled() -> bool {
    std::env::var_os("TCG_NO_STRENGTH_REDUCE").is_none()
}

/// X9 slice 1: full unrolling of small constant-trip loops
/// (`X86LoopUnroll`) at O2/O3. DEFAULT-ON since 2026-07-20: the recognizer
/// is fail-closed on every dialect deviation, and the exact default
/// configuration (unroll + the slice-2/3 cleanup passes) carries the
/// pre-flip record — 500-seed 15-family soak + 600+ array-kernel
/// differential seeds CLEAN at TCG_OPT_LEVEL 0/2/3, 18/18 bench checksums,
/// proofs-ON discharge, b05 exit-80 differential at every stage.
/// `TCG_NO_X86_UNROLL` is the forensic opt-out (the legacy `TCG_X86_UNROLL`
/// opt-in name remains accepted and redundant). See
/// `trust_cg_opt::x86_loop_unroll` (module docs) for the recognizer's
/// fail-closed conditions and the soundness argument.
fn x86_unroll_enabled() -> bool {
    std::env::var_os("TCG_NO_X86_UNROLL").is_none()
}

/// Kill switch for the LICM invariant stack-slot load tier (O2/O3 only; O1
/// always runs the pure-only tier). ON by default; set `TCG_NO_LICM_LOADS`
/// for forensic rollback / A-B comparison (mirrors `TCG_NO_VECTORIZE`). With
/// the switch set every loop load stays in the loop (always correct).
fn x86_licm_load_hoisting_enabled() -> bool {
    std::env::var_os("TCG_NO_LICM_LOADS").is_none()
}

/// Kill switch for the LICM invariant flag-writing-arithmetic tier (Lever B;
/// O2/O3 only). Hoists a provably loop-invariant, non-trapping `imul` (the inner
/// loop's `i*n` index product) whose written RFLAGS is proven dead at both its
/// original site and the preheader insertion point. ON by default; set
/// `TCG_NO_LICM_FLAG_ARITH` for forensic rollback / A-B comparison (mirrors
/// `TCG_NO_LICM_LOADS`). With the switch set every invariant multiply stays in
/// the loop (always correct). Sound by construction: only relocates a flag
/// write whose flags no reader can observe — see `trust_cg_opt::x86_licm`
/// (module docs, "Lever-B" section).
fn x86_licm_flag_arith_enabled() -> bool {
    std::env::var_os("TCG_NO_LICM_FLAG_ARITH").is_none()
}

/// Kill switch for x86 Scalar Replacement of Aggregates (O2/O3 only). Promotes
/// non-escaped stack slots (the frontend's memory-backed slice fat-pointers) to
/// SSA vregs pre-regalloc, eliminating the per-iteration `leaq/movq` reloads
/// that LICM cannot hoist past an in-loop heap store. ON by default; set
/// `TCG_NO_X86_SROA` for forensic rollback / A-B comparison (mirrors
/// `TCG_NO_LICM_LOADS`). With the switch set every slot stays memory-backed
/// (always correct). Sound by construction: a slot is promoted only when its
/// address provably never escapes (strict `trace_addr_uses` allowlist) — see
/// `trust_cg_opt::x86_sroa` (module docs, "Soundness / correctness").
fn x86_sroa_enabled() -> bool {
    std::env::var_os("TCG_NO_X86_SROA").is_none()
}

/// Whether the stats-only register-allocator spill probes are enabled (cached).
/// Shares `TCG_RA_SPILL_STATS` with `trust-cg-regalloc`'s per-function line so
/// one env var turns on the whole measurement lane. Off by default and
/// zero-cost: one relaxed load, and the emitted object is byte-identical.
fn x86_ra_spill_stats_enabled() -> bool {
    use std::sync::OnceLock;
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var_os("TCG_RA_SPILL_STATS").is_some())
}

/// Whether the inverted R10/R11 full-pool retry (Lever 1) is enabled. OPT-IN
/// (`TCG_X86_RA_FULL_POOL`), because the counterfactual measured it firing on
/// almost nothing: only a function whose 14-wide allocation spills NOTHING can
/// soundly keep the retry, and in the corpus loss cluster only b01 reaches zero.
/// Default-OFF keeps current codegen byte-identical.
fn x86_ra_full_pool_enabled() -> bool {
    use std::sync::OnceLock;
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var_os("TCG_X86_RA_FULL_POOL").is_some())
}

/// Production rule policy for the OPT-8 branch-layout pass.
///
/// Default: the loop-latch rewrite ONLY (profile-independent — a loop always
/// benefits from one fewer branch per iteration; measured p2_collatz -32%,
/// b1_mispredict -13%). The fall-through inversion for non-loop two-way
/// exits is a profile-FREE heuristic ("layout-successor == hot") that
/// regressed a real match-heavy program (p6_branch_match +4.3%), so it is
/// DEFERRED off by default. Opt in for A/B experiments with
/// `TCG_BRANCH_LAYOUT_FALLTHROUGH=1`.
fn x86_branch_layout_config() -> trust_cg_opt::X86BranchLayoutConfig {
    trust_cg_opt::X86BranchLayoutConfig {
        latch_rule: true,
        fallthrough_rule: std::env::var_os("TCG_BRANCH_LAYOUT_FALLTHROUGH").is_some(),
        // Cold-trap fall-through inversion (bounds/null/abort exits): profile-
        // free-correct, default ON. `TCG_NO_X86_COLD_TRAP_LAYOUT` opts out.
        cold_trap_rule: std::env::var_os("TCG_NO_X86_COLD_TRAP_LAYOUT").is_none(),
    }
}

/// Per-inversion obligation for the OPT-8 branch-layout pass (the
/// #3-trap-carriers wrong-cc class): admit the substitution
/// `jcc cc, T; jmp F  ->  jcc inverted, F; jmp T` ONLY when `inverted` is
/// PROVEN to branch on exactly the complement of `cc` for every RFLAGS
/// state.
///
/// Discipline mirrors `run_guard_carrier_canary`: the pass derives
/// `inverted` from the SAME local value it writes into the rewritten
/// instruction and passes both cc's here, so the proof and the emitted code
/// cannot drift. The obligation
/// (`trust_cg_verify::pass_validators::CondCodeInversionValidator`) is
/// exhaustive over the 32 packed flag states, and — per the roadmap's OPT-8
/// correction — each admitted cc additionally MINTS a per-inversion
/// `CertifiedPassChainEntry` that is checked through the fail-closed
/// `CertifiedPassChain` machinery. Memoized per (original) cc: `inverted`
/// is a pure function of it, and there are only 16 condition codes.
///
/// This is an ADMISSION gate, not a rejection gate: `false` leaves the
/// (correct, two-branch) original in place and the compile proceeds
/// unoptimized. It never fails the compile.
fn admit_x86_cc_inversion(
    original: trust_cg_ir::x86_64_ops::X86CondCode,
    inverted: trust_cg_ir::x86_64_ops::X86CondCode,
) -> bool {
    use std::sync::OnceLock;
    use trust_cg_verify::CertifiedPassChain;
    use trust_cg_verify::pass_validators::{CondCodeInversionValidator, PassValidator};

    // The pass must always pair a cc with its true hardware complement; a
    // mismatched pair is validator misuse — refuse without memoizing (the
    // memo is keyed on `original` alone).
    if inverted != original.invert() {
        return false;
    }

    static ADMITTED: [OnceLock<bool>; 16] = [const { OnceLock::new() }; 16];
    *ADMITTED[original.encoding() as usize].get_or_init(|| {
        let validator = CondCodeInversionValidator::new("x86-branch-layout", original, inverted);
        // Mint the per-inversion certificate and run it through the
        // fail-closed chain checker; any rejection (refuted obligation,
        // malformed certificate, chain check failure) => not admitted.
        match validator.certify("x86-branch-layout-cc-inversion", 0) {
            Ok(entry) => CertifiedPassChain::from_entries(vec![entry]).is_ok(),
            Err(_) => false,
        }
    })
}

/// Per-inversion obligation for the OPT-11 if-conversion pass (the
/// #3-trap-carriers wrong-cc class): the pass rewrites a value-select diamond
/// `jcc cc, T; jmp F  /  T: m=a  /  F: m=b` into the branchless
/// `mov m, a; cmovcc inv(cc), m, b` (complement encoding, so the result is
/// `cc ? a : b`). It is admitted ONLY when `inverted` is PROVEN to branch on
/// exactly the complement of `cc` for every RFLAGS state — the SAME exhaustive
/// `CondCodeInversionValidator` proof + fail-closed `CertifiedPassChain` OPT-8
/// uses, memoized per (original) cc.
///
/// Shared-local discipline: the if-convert pass derives `inverted` from the
/// SAME value it writes into the emitted `cmovcc` (`DiamondPlan::inverted_cc`,
/// passed to both this callback and the instruction), so the proof and the
/// emitted code cannot drift. Admission gate, not a rejection gate: `false`
/// leaves the correct two-branch diamond in place and the compile proceeds
/// unoptimized.
fn admit_x86_ifconv_cc_inversion(
    original: trust_cg_ir::x86_64_ops::X86CondCode,
    inverted: trust_cg_ir::x86_64_ops::X86CondCode,
) -> bool {
    use std::sync::OnceLock;
    use trust_cg_verify::CertifiedPassChain;
    use trust_cg_verify::pass_validators::{CondCodeInversionValidator, PassValidator};

    if inverted != original.invert() {
        return false;
    }

    static ADMITTED: [OnceLock<bool>; 16] = [const { OnceLock::new() }; 16];
    *ADMITTED[original.encoding() as usize].get_or_init(|| {
        let validator = CondCodeInversionValidator::new("x86-if-convert", original, inverted);
        match validator.certify("x86-if-convert-cc-inversion", 0) {
            Ok(entry) => CertifiedPassChain::from_entries(vec![entry]).is_ok(),
            Err(_) => false,
        }
    })
}

/// Per-`(width, step, stride)` obligation for the OPT-3a strength-reduction
/// pass: admit replacing a loop-body `imul iv, s` (`iv` a step-`step`
/// induction variable, `s` the compile-time constant `stride`, possibly
/// materialized in a loop-invariant register) with the add recurrence
/// `r += s*step` ONLY when the inductive-step identity
///
/// ```text
///   forall iv : bv<width> .  (iv + step)*stride == iv*stride + stride*step
/// ```
///
/// is discharged at that width by exact recognition of the cited ring identity,
/// with a fail-closed formal-solver fallback for any non-matching shape. The
/// structural side conditions (loop-invariance/constancy of the stride,
/// single IV update, lockstep advance placement, dead RFLAGS) are enforced by
/// construction in `trust_cg_opt::x86_strength_reduce`; this callback
/// discharges the one algebraic step, and each admitted triple additionally
/// MINTS a `CertifiedPassChainEntry` checked through the fail-closed
/// `CertifiedPassChain` machinery — the same discipline as the cc-inversion
/// admissions above.
///
/// Shared-local discipline: the pass calls this with the SAME `width`,
/// `step`, and `stride` values it writes into the rewritten instructions, so
/// the proof and the emitted code cannot drift. This is an ADMISSION gate,
/// not a rejection gate: `false` leaves the (correct) multiply in place and
/// the compile proceeds unoptimized. It never fails the compile. Memoized per
/// triple in-process, and the solver verdict is content-keyed in the on-disk
/// AY result cache, so a given kernel shape pays the solver once per machine.
///
/// # Discharge: cited ring axiom, no solver (the fnv/crc compile-time win)
///
/// The obligation `(iv + step)*stride == iv*stride + stride*step` is a RING
/// IDENTITY — true for ALL `iv, step, stride` by distributivity and
/// commutativity of `*` over `+` in `Z/2^width` — so there is nothing to
/// solve. We first try [`StrengthReduceRecurrenceValidator::certify_by_ring_axiom`],
/// which STRUCTURALLY recognizes the exact ring-recurrence shape and, on a
/// match, mints the same registered `CertifiedPassChainEntry` a `Verified`
/// solve would, discharged by the cited lemma (distributivity +
/// commutativity, documented as the sole trust point on
/// `certify_by_ring_axiom`). This replaces a per-concrete-stride bit-blast
/// that cost ~11-14s for large strides (fnv stride=31, crc stride=131) with an
/// instant citation. If the obligation is for ANY reason NOT that exact
/// always-true shape, `certify_by_ring_axiom` returns `None` and we FALL
/// THROUGH to the fail-closed `certify` solver path — we never blindly admit.
fn admit_x86_strength_reduce_recurrence(width: u32, step: i64, stride: i64) -> bool {
    use std::collections::HashMap;
    use std::sync::{Mutex, OnceLock};
    use trust_cg_verify::CertifiedPassChain;
    use trust_cg_verify::pass_validators::{PassValidator, StrengthReduceRecurrenceValidator};

    static ADMITTED: OnceLock<Mutex<HashMap<(u32, i64, i64), bool>>> = OnceLock::new();
    let memo = ADMITTED.get_or_init(|| Mutex::new(HashMap::new()));
    if let Some(&admitted) = memo
        .lock()
        .expect("strength-reduce admission memo")
        .get(&(width, step, stride))
    {
        return admitted;
    }
    let validator =
        StrengthReduceRecurrenceValidator::new("x86-strength-reduce", width, step, stride);
    // Fast path: the obligation is the always-true ring-recurrence identity;
    // recognize it and discharge by the cited ring axioms (no solve). Falls
    // through to the solver iff the posed obligation is not that exact shape.
    let entry = match validator.certify_by_ring_axiom("x86-strength-reduce-recurrence", 0) {
        Some(entry) => Ok(entry),
        None => validator.certify("x86-strength-reduce-recurrence", 0),
    };
    let admitted = match entry {
        Ok(entry) => CertifiedPassChain::from_entries(vec![entry]).is_ok(),
        Err(_) => false,
    };
    memo.lock()
        .expect("strength-reduce admission memo")
        .insert((width, step, stride), admitted);
    admitted
}

/// Sentinel S5 — expand surviving proof-only bounds-check carriers into real
/// runtime checks.
///
/// A `TrapBoundsCheckExact [base, index, Imm(bound)]` carrier that the
/// kernel-gated proof pass did NOT delete must lower to a genuine unsigned
/// `index < bound` check, exactly like the eager check the x86 ISel used to emit
/// directly. Each carrier becomes:
///
/// ```text
///     CMP index, bound          ; (or MOV r, bound64 ; CMP index, r for bound > i32::MAX)
///     Jcc AE -> <trap_block>    ; index >= bound (unsigned) traps
///     ... rest of block falls through ...
///   trap_block:
///     UD2
/// ```
///
/// This runs BEFORE register allocation so the fresh `bound` vreg (large-bound
/// path) and the synthetic trap block participate in regalloc/encoding normally.
/// It is fail-closed: any carrier the encoder would otherwise reject
/// (`UnsupportedOpcode`) is guaranteed to be replaced here, so a dropped bounds
/// check can never reach object emission as a silent NOP.
///
/// The `base` operand is intentionally not referenced by the runtime check (the
/// unsigned `index < bound` comparison fully captures the safety condition); it
/// is preserved on the carrier solely for proof-operand identity.
/// What sits in a `TrapBoundsCheckExact` carrier's bound slot.
///
/// `GuardBoundsCheck` puts a constant length there; `GuardBoundsCheckDyn` puts
/// a register holding a runtime one. Naming the two shapes keeps the expander's
/// emit site a `match` — so a new carrier shape is a compile error here rather
/// than silently taking whichever arm happens to fall through.
enum X86BoundsCarrierBound {
    Const(i64),
    Reg(X86ISelOperand),
}

fn expand_x86_bounds_check_carriers(func: &mut X86ISelFunction) -> Result<(), X86PipelineError> {
    // Bind the proof to the emit: this ONE local drives both the canary and the
    // `Jcc` below, so they cannot drift. The canary (memoized) runs only when a
    // bounds carrier is actually present, so non-guard programs pay nothing.
    let trap_cond = X86CondCode::AE;
    if func.blocks.values().any(|b| {
        b.insts
            .iter()
            .any(|i| i.opcode == X86Opcode::TrapBoundsCheckExact)
    }) {
        run_guard_carrier_canary(
            trust_cg_verify::pass_validators::GuardCarrierKind::Bounds,
            trap_cond,
        )?;
    }

    expand_x86_bounds_check_carriers_after_canary(func, trap_cond)
}

/// Structural half of [`expand_x86_bounds_check_carriers`]. Keeping the
/// already-validated rewrite separate lets unit tests pin its exact instruction
/// shape without making their result depend on which external proof tools happen
/// to be installed on the host. Production always enters through the wrapper.
fn expand_x86_bounds_check_carriers_after_canary(
    func: &mut X86ISelFunction,
    trap_cond: X86CondCode,
) -> Result<(), X86PipelineError> {
    // First locate every carrier so we can mint trap blocks without iterating a
    // map we are also mutating. (block_id, index-in-block) -> carrier operands.
    let mut new_trap_blocks: Vec<LirBlock> = Vec::new();
    let mut next_block_id: u32 = func
        .block_order
        .iter()
        .map(|b| b.0)
        .max()
        .unwrap_or(0)
        .saturating_add(1);

    for block_id in func.block_order.clone() {
        let old_insts = {
            let Some(block) = func.blocks.get_mut(&block_id) else {
                continue;
            };
            if !block
                .insts
                .iter()
                .any(|i| i.opcode == X86Opcode::TrapBoundsCheckExact)
            {
                continue;
            }
            std::mem::take(&mut block.insts)
        };

        let mut new_insts = Vec::with_capacity(old_insts.len());
        let mut added_trap_succs: Vec<LirBlock> = Vec::new();

        for inst in old_insts {
            if inst.opcode != X86Opcode::TrapBoundsCheckExact {
                new_insts.push(inst);
                continue;
            }

            // Carrier shape: [base, index, Imm(bound)]. Fail closed if malformed.
            if inst.operands.len() != 3 {
                return Err(X86PipelineError::FrameLowering(format!(
                    "x86-64 TrapBoundsCheckExact carrier must have 3 operands, got {}",
                    inst.operands.len()
                )));
            }
            let index = inst.operands[1].clone();
            // The bound slot is an `Imm` for `GuardBoundsCheck` (a constant
            // length) and a REGISTER for `GuardBoundsCheckDyn` (a runtime one).
            //
            // ⚑ A register must never be routed through `CmpRI` — that encodes
            // the register NUMBER as the compare immediate, leaving a program
            // that still looks bounds-checked while admitting out-of-bounds
            // indices. Anything that is neither shape fails closed below rather
            // than being coerced into something that encodes.
            let bound = match &inst.operands[2] {
                X86ISelOperand::Imm(b) => X86BoundsCarrierBound::Const(*b),
                reg @ (X86ISelOperand::VReg(_) | X86ISelOperand::PReg(_)) => {
                    X86BoundsCarrierBound::Reg(reg.clone())
                }
                other => {
                    return Err(X86PipelineError::FrameLowering(format!(
                        "x86-64 TrapBoundsCheckExact carrier bound must be an immediate \
                         or a register, got {other:?}"
                    )));
                }
            };

            // Mint a fresh synthetic trap block id.
            while func.blocks.contains_key(&LirBlock(next_block_id)) {
                next_block_id = next_block_id.checked_add(1).ok_or_else(|| {
                    X86PipelineError::FrameLowering(
                        "exhausted x86 synthetic trap block ids".to_string(),
                    )
                })?;
            }
            let trap_block = LirBlock(next_block_id);
            next_block_id = next_block_id.checked_add(1).ok_or_else(|| {
                X86PipelineError::FrameLowering(
                    "exhausted x86 synthetic trap block ids".to_string(),
                )
            })?;

            // CMP index, bound (compact imm32 form), or MOV r64, bound64 ; CMP
            // index, r64, or — for a runtime length — CMP index, len directly.
            match bound {
                X86BoundsCarrierBound::Const(b)
                    if (i32::MIN as i64..=i32::MAX as i64).contains(&b) =>
                {
                    x86_push_inst(
                        X86Opcode::CmpRI,
                        vec![index, X86ISelOperand::Imm(b)],
                        &mut new_insts,
                    );
                }
                X86BoundsCarrierBound::Const(b) => {
                    let bound_reg = x86_fresh_vreg_operand(func, RegClass::Gpr64);
                    x86_push_inst(
                        X86Opcode::MovRI,
                        vec![bound_reg.clone(), X86ISelOperand::Imm(b)],
                        &mut new_insts,
                    );
                    x86_push_inst(X86Opcode::CmpRR, vec![index, bound_reg], &mut new_insts);
                }
                // Runtime length: compare against the register itself. Same
                // `Jcc AE -> trap` below, so this is the already-proven CmpRR
                // shape the oversized-immediate path above emits.
                X86BoundsCarrierBound::Reg(bound_reg) => {
                    x86_push_inst(X86Opcode::CmpRR, vec![index, bound_reg], &mut new_insts);
                }
            }
            // Jcc AE -> trap_block (unsigned index >= bound traps). `trap_cond` is
            // the canary-proven AE bound to the proof above.
            x86_push_inst(
                X86Opcode::Jcc,
                vec![
                    X86ISelOperand::CondCode(trap_cond),
                    X86ISelOperand::Block(trap_block),
                ],
                &mut new_insts,
            );

            added_trap_succs.push(trap_block);
            new_trap_blocks.push(trap_block);
        }

        if let Some(block) = func.blocks.get_mut(&block_id) {
            block.insts = new_insts;
            block.successors.extend(added_trap_succs);
        }
    }

    // Materialize the synthetic trap blocks (each is a single UD2).
    for trap_block in new_trap_blocks {
        func.ensure_block(trap_block);
        if let Some(block) = func.blocks.get_mut(&trap_block) {
            block.insts.push(X86ISelInst::new(X86Opcode::Ud2, vec![]));
        }
    }

    Ok(())
}

/// Sentinel S5 — expand surviving proof-only null-check carriers into real
/// runtime checks.
///
/// A `TrapNullIfZeroExact [ptr]` carrier that the kernel-gated proof pass did NOT
/// delete must lower to a genuine null check, byte-identical to the eager check
/// the x86 ISel used to emit directly. Each carrier becomes:
///
/// ```text
///     TEST ptr, ptr             ; ZF = (ptr == 0)
///     Jcc E -> <trap_block>     ; ptr == 0 traps
///     ... rest of block falls through ...
///   trap_block:
///     UD2
/// ```
///
/// This runs BEFORE register allocation so the synthetic trap block participates
/// in regalloc/encoding normally. It is fail-closed: any carrier the encoder would
/// otherwise reject (`UnsupportedOpcode`) is guaranteed to be replaced here, so a
/// dropped null check can never reach object emission as a silent NOP. It is the
/// exact structural mirror of [`expand_x86_bounds_check_carriers`] (the only
/// differences are `TEST ptr, ptr` instead of `CMP index, bound` and the `E`
/// condition instead of `AE`).
fn expand_x86_null_check_carriers(func: &mut X86ISelFunction) -> Result<(), X86PipelineError> {
    // One local trap cond binds the canary to the emitted `Jcc` (memoized; runs
    // only when a null carrier is present).
    let trap_cond = X86CondCode::E;
    if func.blocks.values().any(|b| {
        b.insts
            .iter()
            .any(|i| i.opcode == X86Opcode::TrapNullIfZeroExact)
    }) {
        run_guard_carrier_canary(
            trust_cg_verify::pass_validators::GuardCarrierKind::NullIfZero,
            trap_cond,
        )?;
    }

    expand_x86_null_check_carriers_after_canary(func, trap_cond)
}

/// Structural half of [`expand_x86_null_check_carriers`]; see
/// [`expand_x86_bounds_check_carriers_after_canary`] for the test-isolation
/// rationale. Production always enters through the proof-bearing wrapper.
fn expand_x86_null_check_carriers_after_canary(
    func: &mut X86ISelFunction,
    trap_cond: X86CondCode,
) -> Result<(), X86PipelineError> {
    let mut new_trap_blocks: Vec<LirBlock> = Vec::new();
    let mut next_block_id: u32 = func
        .block_order
        .iter()
        .map(|b| b.0)
        .max()
        .unwrap_or(0)
        .saturating_add(1);

    for block_id in func.block_order.clone() {
        let old_insts = {
            let Some(block) = func.blocks.get_mut(&block_id) else {
                continue;
            };
            if !block
                .insts
                .iter()
                .any(|i| i.opcode == X86Opcode::TrapNullIfZeroExact)
            {
                continue;
            }
            std::mem::take(&mut block.insts)
        };

        let mut new_insts = Vec::with_capacity(old_insts.len());
        let mut added_trap_succs: Vec<LirBlock> = Vec::new();

        for inst in old_insts {
            if inst.opcode != X86Opcode::TrapNullIfZeroExact {
                new_insts.push(inst);
                continue;
            }

            // Carrier shape: [ptr]. Fail closed if malformed.
            if inst.operands.len() != 1 {
                return Err(X86PipelineError::FrameLowering(format!(
                    "x86-64 TrapNullIfZeroExact carrier must have 1 operand, got {}",
                    inst.operands.len()
                )));
            }
            let ptr = inst.operands[0].clone();

            // Mint a fresh synthetic trap block id.
            while func.blocks.contains_key(&LirBlock(next_block_id)) {
                next_block_id = next_block_id.checked_add(1).ok_or_else(|| {
                    X86PipelineError::FrameLowering(
                        "exhausted x86 synthetic trap block ids".to_string(),
                    )
                })?;
            }
            let trap_block = LirBlock(next_block_id);
            next_block_id = next_block_id.checked_add(1).ok_or_else(|| {
                X86PipelineError::FrameLowering(
                    "exhausted x86 synthetic trap block ids".to_string(),
                )
            })?;

            // TEST ptr, ptr ; Jcc E -> trap_block (ptr == 0 traps). `trap_cond` is
            // the canary-proven E bound to the proof above.
            x86_push_inst(X86Opcode::TestRR, vec![ptr.clone(), ptr], &mut new_insts);
            x86_push_inst(
                X86Opcode::Jcc,
                vec![
                    X86ISelOperand::CondCode(trap_cond),
                    X86ISelOperand::Block(trap_block),
                ],
                &mut new_insts,
            );

            added_trap_succs.push(trap_block);
            new_trap_blocks.push(trap_block);
        }

        if let Some(block) = func.blocks.get_mut(&block_id) {
            block.insts = new_insts;
            block.successors.extend(added_trap_succs);
        }
    }

    // Materialize the synthetic trap blocks (each is a single UD2).
    for trap_block in new_trap_blocks {
        func.ensure_block(trap_block);
        if let Some(block) = func.blocks.get_mut(&trap_block) {
            block.insts.push(X86ISelInst::new(X86Opcode::Ud2, vec![]));
        }
    }

    Ok(())
}

