/// Sentinel S5 — expand surviving proof-only shift-range-check carriers into real
/// runtime checks.
///
/// A `TrapShiftRangeExact [amount, Imm(bitwidth)]` carrier that the kernel-gated
/// proof pass did NOT delete must lower to a genuine shift-range check,
/// byte-identical to the eager check the x86 ISel used to emit directly. Each
/// carrier becomes:
///
/// ```text
///     CMP amount, #bitwidth     ; sets CF for unsigned amount < bitwidth
///     Jcc AE -> <trap_block>    ; amount >= bitwidth (unsigned) traps
///     ... rest of block falls through ...
///   trap_block:
///     UD2
/// ```
///
/// This runs BEFORE register allocation so the synthetic trap block participates
/// in regalloc/encoding normally. It is fail-closed: any carrier the encoder would
/// otherwise reject (`UnsupportedOpcode`) is guaranteed to be replaced here, so a
/// dropped shift-range check can never reach object emission as a silent NOP. It is
/// the exact structural mirror of [`expand_x86_bounds_check_carriers`] — a
/// shift-range guard is "trap if amount >= bitwidth (unsigned)", identical in shape
/// to bounds' "trap if index >= bound". The width is always in `1..=64` (the x86
/// ISel rejects anything else), so it always fits the compact `CMP r, imm32` form;
/// no `MOV+CMP` widening fallback is needed.
fn expand_x86_shift_range_check_carriers(
    func: &mut X86ISelFunction,
) -> Result<(), X86PipelineError> {
    // One local trap cond binds the canary to the emitted `Jcc` (memoized; runs
    // only when a shift-range carrier is present).
    let trap_cond = X86CondCode::AE;
    if func.blocks.values().any(|b| {
        b.insts
            .iter()
            .any(|i| i.opcode == X86Opcode::TrapShiftRangeExact)
    }) {
        run_guard_carrier_canary(
            trust_cg_verify::pass_validators::GuardCarrierKind::ShiftRange,
            trap_cond,
        )?;
    }

    expand_x86_shift_range_check_carriers_after_canary(func, trap_cond)
}

/// Structural half of [`expand_x86_shift_range_check_carriers`]; see
/// [`expand_x86_bounds_check_carriers_after_canary`] for the test-isolation
/// rationale. Production always enters through the proof-bearing wrapper.
fn expand_x86_shift_range_check_carriers_after_canary(
    func: &mut X86ISelFunction,
    trap_cond: X86CondCode,
) -> Result<(), X86PipelineError> {
    let mut new_trap_blocks: Vec<LirBlock> = Vec::new();
    let mut next_block_id: u32 = func
        .block_order
        .iter()
        .map(|b| b.0)
        .max()
        .unwrap_or(0)
        .saturating_add(1);

    for block_id in func.block_order.clone() {
        let old_insts = {
            let Some(block) = func.blocks.get_mut(&block_id) else {
                continue;
            };
            if !block
                .insts
                .iter()
                .any(|i| i.opcode == X86Opcode::TrapShiftRangeExact)
            {
                continue;
            }
            std::mem::take(&mut block.insts)
        };

        let mut new_insts = Vec::with_capacity(old_insts.len());
        let mut added_trap_succs: Vec<LirBlock> = Vec::new();

        for inst in old_insts {
            if inst.opcode != X86Opcode::TrapShiftRangeExact {
                new_insts.push(inst);
                continue;
            }

            // Carrier shape: [amount, Imm(bitwidth)]. Fail closed if malformed.
            if inst.operands.len() != 2 {
                return Err(X86PipelineError::FrameLowering(format!(
                    "x86-64 TrapShiftRangeExact carrier must have 2 operands, got {}",
                    inst.operands.len()
                )));
            }
            let amount = inst.operands[0].clone();
            let bitwidth = match &inst.operands[1] {
                X86ISelOperand::Imm(w) => *w,
                other => {
                    return Err(X86PipelineError::FrameLowering(format!(
                        "x86-64 TrapShiftRangeExact carrier bitwidth must be an immediate, got {other:?}"
                    )));
                }
            };

            // Mint a fresh synthetic trap block id.
            while func.blocks.contains_key(&LirBlock(next_block_id)) {
                next_block_id = next_block_id.checked_add(1).ok_or_else(|| {
                    X86PipelineError::FrameLowering(
                        "exhausted x86 synthetic trap block ids".to_string(),
                    )
                })?;
            }
            let trap_block = LirBlock(next_block_id);
            next_block_id = next_block_id.checked_add(1).ok_or_else(|| {
                X86PipelineError::FrameLowering(
                    "exhausted x86 synthetic trap block ids".to_string(),
                )
            })?;

            // CMP amount, #bitwidth ; Jcc AE -> trap_block (unsigned amount >= bitwidth traps).
            // `trap_cond` is the canary-proven AE bound to the proof above.
            x86_push_inst(
                X86Opcode::CmpRI,
                vec![amount, X86ISelOperand::Imm(bitwidth)],
                &mut new_insts,
            );
            x86_push_inst(
                X86Opcode::Jcc,
                vec![
                    X86ISelOperand::CondCode(trap_cond),
                    X86ISelOperand::Block(trap_block),
                ],
                &mut new_insts,
            );

            added_trap_succs.push(trap_block);
            new_trap_blocks.push(trap_block);
        }

        if let Some(block) = func.blocks.get_mut(&block_id) {
            block.insts = new_insts;
            block.successors.extend(added_trap_succs);
        }
    }

    // Materialize the synthetic trap blocks (each is a single UD2).
    for trap_block in new_trap_blocks {
        func.ensure_block(trap_block);
        if let Some(block) = func.blocks.get_mut(&trap_block) {
            block.insts.push(X86ISelInst::new(X86Opcode::Ud2, vec![]));
        }
    }

    Ok(())
}

/// Generate the `__eh_frame` section bytes for an x86-64 function.
///
/// Creates a DWARF CIE + FDE describing the System V AMD64 ABI prologue:
/// PUSH RBP; MOV RBP, RSP; PUSH callee-saved regs; SUB RSP, frame_size.
///
/// The resulting bytes are suitable for the `__TEXT,__eh_frame` Mach-O section.
///
/// # Arguments
/// - `callee_saved`: Callee-saved registers pushed after RBP (in push order).
/// - `frame_size`: Bytes allocated via SUB RSP for locals/spills (may be 0).
/// - `code_len`: Total encoded code length in bytes.
/// - `symbol_index`: Symbol table index for the function (for relocations).
///
#[allow(dead_code)]
fn generate_eh_frame_section(
    callee_saved: &[X86PReg],
    frame_size: u32,
    code_len: u32,
    symbol_index: u32,
) -> Vec<u8> {
    let mut section = DwarfCfiSection::new_x86_64();
    let fde = x86_64_fde_from_prologue(
        callee_saved,
        frame_size,
        0, // function_offset (placeholder, relocated by linker)
        code_len,
        symbol_index,
    );
    section.add_fde(fde);
    section.to_bytes()
}

/// Resolved, post-layout x86 exception-handling descriptors for one function.
///
/// The x86 pipeline works directly on `X86ISelFunction.eh_info` (a LIR
/// [`trust_cg_lower::function::EhFunctionInfo`] keyed by [`LirBlock`], byte
/// offsets unresolved) plus the encoder's `block_offsets: HashMap<LirBlock,
/// usize>`. This is the x86 analog of the AArch64 pipeline's `resolve_eh_offsets`
/// output (which mutates an `IrMachFunction`'s `eh_metadata` in place); it
/// carries the target-agnostic descriptors the checked shared LSDA boundary
/// ([`crate::exception_handling::generate_lsda_from_pads`]) consumes,
/// with the mandatory `[0, code_len)` gap-filler call sites already synthesized.
#[derive(Debug, Clone, Default)]
struct ResolvedX86Eh {
    /// Landing-pad descriptors carrying post-layout (function-relative) byte
    /// offsets.
    landing_pads: Vec<crate::exception_handling::LandingPadDesc>,
    /// Call-site regions `(start_offset, length, landing_pad_offset)`, sorted by
    /// `start_offset` and covering ALL of `[0, code_len)`: exact protected-call
    /// byte spans plus mandatory `landing_pad == 0` gap fillers over every
    /// other instruction byte.
    call_site_ranges: Vec<(u32, u32, u32)>,
}

/// Resolve `X86ISelFunction.eh_info` against post-layout `block_offsets` into
/// [`ResolvedX86Eh`] (byte offsets + full-coverage call-site table).
///
/// Each landing pad resolves to its block offset. Each block-granular
/// [`EhCallSite`](trust_cg_lower::function::EhCallSite) must resolve to exactly
/// one final `Call`/`CallR`/`CallM`; its range comes from the encoder rather
/// than from a guessed block span. Zero or multiple calls are ambiguous and
/// fail closed. A `landing_pad == 0 / action == 0` filler is then synthesized
/// over every other byte in `[0, code_len)`.
///
/// The gap-filler synthesis is MANDATORY (not an optimization): a CLEANUP pad's
/// `_Unwind_Resume` re-consults this function's personality at a PC inside the
/// pad block — outside every throwing region — and the Itanium personality calls
/// `std::terminate()` on a PC that no call-site entry covers. Offsets are
/// FUNCTION-relative (the LSDA uses `LPStart`-omit = function start), so the
/// per-function offsets are exactly right; do NOT add `text_offset`.
fn resolve_x86_eh_offsets(
    func: &X86ISelFunction,
    block_offsets: &HashMap<LirBlock, usize>,
    encoded_call_ranges: &X86EncodedCallRanges,
    code_len: usize,
) -> Result<ResolvedX86Eh, X86PipelineError> {
    use crate::exception_handling::LandingPadDesc;

    let malformed = |detail: String| X86PipelineError::MalformedFunction {
        function: func.name.clone(),
        detail: format!("invalid x86 EH metadata/layout: {detail}"),
    };
    let code_len_u32 = u32::try_from(code_len)
        .map_err(|_| malformed(format!("encoded code length {code_len} exceeds u32::MAX")))?;
    if !func.eh_info.is_empty() && code_len == 0 {
        return Err(malformed(
            "non-empty EH metadata on an empty encoded function".to_string(),
        ));
    }

    // Sorted distinct block starts let us prove that an encoder-recorded call
    // range remains within the block named by the block-granular EH record.
    let mut starts: Vec<usize> = block_offsets.values().copied().collect();
    starts.sort_unstable();
    starts.dedup();
    let block_end = |start: usize| -> usize {
        starts
            .iter()
            .copied()
            .find(|&s| s > start)
            .unwrap_or(code_len)
    };

    // Landing pads: byte offset = the pad block's post-layout offset. Offset 0
    // is the LSDA sentinel for "no landing pad", so it cannot name a real pad.
    let mut landing_pad_blocks = HashSet::new();
    let mut landing_pad_offsets = HashMap::new();
    let mut landing_pads = Vec::with_capacity(func.eh_info.landing_pads.len());
    for lp in &func.eh_info.landing_pads {
        if !landing_pad_blocks.insert(lp.block) {
            return Err(malformed(format!(
                "duplicate landing-pad record for block {}",
                lp.block.0
            )));
        }
        let offset = block_offsets.get(&lp.block).copied().ok_or_else(|| {
            malformed(format!(
                "landing-pad block {} has no final encoded offset",
                lp.block.0
            ))
        })?;
        if offset == 0 {
            return Err(malformed(format!(
                "landing-pad block {} resolves to offset 0, reserved by the LSDA as no-handler",
                lp.block.0
            )));
        }
        if offset >= code_len {
            return Err(malformed(format!(
                "landing-pad block {} offset {offset} is outside encoded code length {code_len}",
                lp.block.0
            )));
        }
        let offset = u32::try_from(offset).map_err(|_| {
            malformed(format!(
                "landing-pad block {} offset {offset} exceeds u32::MAX",
                lp.block.0
            ))
        })?;
        landing_pad_offsets.insert(lp.block, offset);
        landing_pads.push(LandingPadDesc {
            landing_pad_offset: offset,
            catch_type_indices: lp.catch_type_indices.clone(),
            is_cleanup: lp.is_cleanup,
        });
    }

    // Explicit throwing regions: exactly the bytes of each protected call.
    let mut ranges: Vec<(u32, u32, u32)> = Vec::new();
    let mut protected_blocks = HashSet::new();
    for cs in &func.eh_info.call_sites {
        if !protected_blocks.insert(cs.call_block) {
            return Err(malformed(format!(
                "EH call block {} has multiple call-site records; block-granular metadata is ambiguous",
                cs.call_block.0
            )));
        }
        let block = func
            .blocks
            .get(&cs.call_block)
            .ok_or_else(|| malformed(format!("EH call block {} is missing", cs.call_block.0)))?;
        if !block.successors.contains(&cs.landing_pad_block) {
            return Err(malformed(format!(
                "exceptional edge {} -> {} is absent from semantic successor metadata",
                cs.call_block.0, cs.landing_pad_block.0
            )));
        }
        let landing_pad_offset = landing_pad_offsets
            .get(&cs.landing_pad_block)
            .copied()
            .ok_or_else(|| {
                malformed(format!(
                    "EH call block {} targets block {}, which has no landing-pad descriptor",
                    cs.call_block.0, cs.landing_pad_block.0
                ))
            })?;
        let calls: Vec<usize> = block
            .insts
            .iter()
            .enumerate()
            .filter_map(|(index, inst)| {
                matches!(
                    inst.opcode,
                    X86Opcode::Call | X86Opcode::CallR | X86Opcode::CallM
                )
                .then_some(index)
            })
            .collect();
        let [call_index] = calls.as_slice() else {
            return Err(malformed(format!(
                "EH call block {} contains {} eligible calls; exactly one is required by block-granular metadata",
                cs.call_block.0,
                calls.len()
            )));
        };
        let &(start, end) = encoded_call_ranges
            .get(&(cs.call_block, *call_index))
            .ok_or_else(|| {
                malformed(format!(
                    "protected call {}.{} has no exact final-encoding byte range",
                    cs.call_block.0, call_index
                ))
            })?;
        let call_block_start = block_offsets.get(&cs.call_block).copied().ok_or_else(|| {
            malformed(format!(
                "EH call block {} has no final encoded offset",
                cs.call_block.0
            ))
        })?;
        let call_block_end = block_end(call_block_start);
        if start < call_block_start || start >= end || end > call_block_end || end > code_len {
            return Err(malformed(format!(
                "protected call {}.{} range [{start},{end}) is not a non-empty subrange of block [{call_block_start},{call_block_end}) and code [0,{code_len})",
                cs.call_block.0, call_index
            )));
        }
        let start = u32::try_from(start).map_err(|_| {
            malformed(format!(
                "protected call {}.{} start {start} exceeds u32::MAX",
                cs.call_block.0, call_index
            ))
        })?;
        let end = u32::try_from(end).map_err(|_| {
            malformed(format!(
                "protected call {}.{} end {end} exceeds u32::MAX",
                cs.call_block.0, call_index
            ))
        })?;
        ranges.push((start, end - start, landing_pad_offset));
    }

    // Ensure the call-site table covers the ENTIRE function `[0, code_len)`:
    // sort the explicit (throwing) regions and fill every gap — and the tail —
    // with a `landing_pad == 0` filler the personality reads as "no handler
    // here, continue unwinding".
    ranges.sort_by_key(|&(start, _, _)| start);
    let mut fillers: Vec<(u32, u32, u32)> = Vec::new();
    let mut cursor = 0u32;
    for &(start, length, _) in &ranges {
        if start < cursor {
            return Err(malformed(format!(
                "protected call ranges overlap at byte {start}"
            )));
        }
        if start > cursor {
            fillers.push((cursor, start - cursor, 0));
        }
        cursor = start + length;
    }
    if cursor < code_len_u32 {
        fillers.push((cursor, code_len_u32 - cursor, 0));
    }
    if !fillers.is_empty() {
        ranges.extend(fillers);
        ranges.sort_by_key(|&(start, _, _)| start);
    }

    Ok(ResolvedX86Eh {
        landing_pads,
        call_site_ranges: ranges,
    })
}

/// Serialize a [`ResolvedX86Eh`] into `__gcc_except_tab` (LSDA) bytes.
///
/// Reuses the checked target-agnostic LSDA boundary
/// ([`crate::exception_handling::generate_lsda_from_pads`]) unchanged — this
/// is the x86 analog of the AArch64 `generate_lsda_for_function`.
fn generate_x86_lsda(
    resolved: &ResolvedX86Eh,
    personality: &str,
) -> Result<Vec<u8>, crate::exception_handling::ExceptionTableBuildError> {
    crate::exception_handling::generate_lsda_from_pads(
        personality,
        &resolved.landing_pads,
        &resolved.call_site_ranges,
    )
}

/// Build the `(personality, lsda_bytes)` for one function's EH info, or `None`
/// when the function carries no exception-handling structure.
///
/// `code_len` is the function's INSTRUCTION byte length (the encoder's
/// `code.len()` at EH-resolution time, before the per-function constant pool is
/// appended — the const pool is not a throwing region). Structural EH requires
/// an explicit, nonempty, NUL-free personality. Known historical Rust aliases
/// are canonicalized before the Mach-O emitter adds its platform underscore.
fn x86_lsda_for_function(
    func: &X86ISelFunction,
    block_offsets: &HashMap<LirBlock, usize>,
    encoded_call_ranges: &X86EncodedCallRanges,
    code_len: usize,
) -> Result<Option<(String, Vec<u8>)>, X86PipelineError> {
    if func.eh_info.is_empty() {
        return Ok(None);
    }
    let personality =
        crate::exception_handling::required_personality_symbol(func.eh_info.personality.as_deref())
            .map_err(|error| X86PipelineError::InvalidEhPersonality {
                function: func.name.clone(),
                reason: error.to_string(),
            })?
            .to_string();
    let resolved = resolve_x86_eh_offsets(func, block_offsets, encoded_call_ranges, code_len)?;
    let lsda = generate_x86_lsda(&resolved, &personality).map_err(|error| {
        X86PipelineError::MalformedFunction {
            function: func.name.clone(),
            detail: format!("invalid resolved exception table: {error}"),
        }
    })?;
    Ok(Some((personality, lsda)))
}

#[cfg(test)]
mod x86_eh_lsda_tests {
    //! Step 1 (EH Lane 2): byte-level LSDA correctness for the x86 pipeline,
    //! mirroring the AArch64 `generate_lsda_for_function_*` tests
    //! (pipeline.rs). They resolve final machine calls + synthetic exact encoder
    //! ranges into an LSDA and assert byte output, fail-closed binding, and full
    //! `[0, code_len)` coverage.
    use super::{
        ResolvedX86Eh, X86EncodedCallRanges, X86PipelineError, generate_x86_lsda,
        resolve_x86_eh_offsets,
    };
    use std::collections::HashMap;
    use trust_cg_ir::x86_64_ops::X86Opcode;
    use trust_cg_lower::function::{EhCallSite, EhFunctionInfo, EhLandingPad, Signature};
    use trust_cg_lower::instructions::Block;
    use trust_cg_lower::x86_64_isel::{X86ISelFunction, X86ISelInst};

    fn offsets(pairs: &[(u32, usize)]) -> HashMap<Block, usize> {
        pairs.iter().map(|&(b, o)| (Block(b), o)).collect()
    }

    fn encoded_calls(pairs: &[(u32, usize, usize, usize)]) -> X86EncodedCallRanges {
        pairs
            .iter()
            .map(|&(block, inst, start, end)| ((Block(block), inst), (start, end)))
            .collect()
    }

    /// Build the final-stream structure the resolver authenticates. Each
    /// distinct protected block gets one eligible call at instruction index 0.
    fn function_with_eh(eh: EhFunctionInfo) -> X86ISelFunction {
        let mut func = X86ISelFunction::new("eh_test".to_string(), Signature::default());
        for pad in &eh.landing_pads {
            func.ensure_block(pad.block);
        }
        for site in &eh.call_sites {
            func.ensure_block(site.call_block);
            func.ensure_block(site.landing_pad_block);
            if !func.blocks[&site.call_block]
                .insts
                .iter()
                .any(|inst| inst.opcode == X86Opcode::Call)
            {
                func.push_inst(site.call_block, X86ISelInst::new(X86Opcode::Call, vec![]));
            }
            func.add_successor(site.call_block, site.landing_pad_block);
        }
        func.eh_info = eh;
        func
    }

    /// The call-site table must be sorted, gap-free, and cover exactly
    /// `[0, code_len)` (the mandatory personality-coverage invariant).
    fn assert_full_coverage(resolved: &ResolvedX86Eh, code_len: u32) {
        let mut cursor = 0u32;
        for &(start, length, _) in &resolved.call_site_ranges {
            assert_eq!(start, cursor, "call-site table has a gap or overlap");
            cursor = start + length;
        }
        assert_eq!(cursor, code_len, "call-site table must cover [0, code_len)");
    }

    fn landing_pad_for_pc(resolved: &ResolvedX86Eh, pc: u32) -> u32 {
        resolved
            .call_site_ranges
            .iter()
            .find_map(|&(start, length, pad)| (start <= pc && pc < start + length).then_some(pad))
            .expect("full-coverage LSDA must classify every in-function PC")
    }

    #[test]
    fn generate_x86_lsda_no_eh_is_empty() {
        let eh = EhFunctionInfo::default();
        assert!(eh.is_empty());
        let func = function_with_eh(eh);
        let resolved = resolve_x86_eh_offsets(
            &func,
            &offsets(&[(0, 0)]),
            &X86EncodedCallRanges::new(),
            0x20,
        )
        .unwrap();
        assert!(resolved.landing_pads.is_empty());
    }

    #[test]
    fn generate_x86_lsda_with_cleanup() {
        // One cleanup landing pad on block 1, one invoke call site on block 0.
        let eh = EhFunctionInfo {
            personality: Some("__rust_eh_personality".to_string()),
            landing_pads: vec![EhLandingPad {
                block: Block(1),
                catch_type_indices: Vec::new(),
                is_cleanup: true,
            }],
            call_sites: vec![EhCallSite {
                call_block: Block(0),
                landing_pad_block: Block(1),
            }],
        };
        let func = function_with_eh(eh);
        let block_offsets = offsets(&[(0, 0x00), (1, 0x40)]);
        let resolved = resolve_x86_eh_offsets(
            &func,
            &block_offsets,
            &encoded_calls(&[(0, 0, 8, 13)]),
            0x60,
        )
        .unwrap();
        assert_full_coverage(&resolved, 0x60);
        // The cleanup pad resolves to block 1's byte offset.
        assert_eq!(resolved.landing_pads[0].landing_pad_offset, 0x40);
        assert!(resolved.landing_pads[0].is_cleanup);

        let lsda = generate_x86_lsda(&resolved, "__rust_eh_personality").unwrap();
        assert_eq!(lsda[0], 0xFF, "LPStart encoding should be DW_EH_PE_omit");
        assert!(lsda.len() > 4, "LSDA should have header + call-site table");
        // No typed catches => TType table omitted.
        assert_eq!(lsda[1], 0xFF, "TType should be omit for a cleanup-only pad");
    }

    #[test]
    fn generate_x86_lsda_rejects_typed_catch_without_typeinfo_relocations() {
        let eh = EhFunctionInfo {
            personality: Some("__gxx_personality_v0".to_string()),
            landing_pads: vec![EhLandingPad {
                block: Block(2),
                catch_type_indices: vec![1],
                is_cleanup: false,
            }],
            call_sites: vec![EhCallSite {
                call_block: Block(0),
                landing_pad_block: Block(2),
            }],
        };
        let func = function_with_eh(eh);
        let block_offsets = offsets(&[(0, 0x00), (2, 0x80)]);
        let resolved = resolve_x86_eh_offsets(
            &func,
            &block_offsets,
            &encoded_calls(&[(0, 0, 0x20, 0x25)]),
            0xA0,
        )
        .unwrap();
        assert_full_coverage(&resolved, 0xA0);
        assert_eq!(resolved.landing_pads[0].landing_pad_offset, 0x80);

        let error = generate_x86_lsda(&resolved, "__gxx_personality_v0").unwrap_err();
        assert!(matches!(
            error,
            crate::exception_handling::ExceptionTableBuildError::TypedCatchRelocationUnsupported {
                type_index: 1,
                ..
            }
        ));
    }

    #[test]
    fn generate_x86_lsda_multiple_call_sites() {
        // Two throwing blocks (0 and 2) to two pads (1 catch, 3 cleanup), with a
        // non-throwing block (4) in between so the gap-filler is exercised.
        let eh = EhFunctionInfo {
            personality: Some("__gxx_personality_v0".to_string()),
            landing_pads: vec![
                EhLandingPad {
                    block: Block(1),
                    catch_type_indices: vec![0],
                    is_cleanup: false,
                },
                EhLandingPad {
                    block: Block(3),
                    catch_type_indices: Vec::new(),
                    is_cleanup: true,
                },
            ],
            call_sites: vec![
                EhCallSite {
                    call_block: Block(0),
                    landing_pad_block: Block(1),
                },
                EhCallSite {
                    call_block: Block(2),
                    landing_pad_block: Block(3),
                },
            ],
        };
        let func = function_with_eh(eh);
        // Layout: b0=[0,0x10) b1=[0x10,0x20) b2=[0x20,0x30) b3=[0x30,0x40) tail to 0x50.
        let block_offsets = offsets(&[(0, 0x00), (1, 0x10), (2, 0x20), (3, 0x30)]);
        let resolved = resolve_x86_eh_offsets(
            &func,
            &block_offsets,
            &encoded_calls(&[(0, 0, 0x05, 0x0A), (2, 0, 0x24, 0x29)]),
            0x50,
        )
        .unwrap();
        assert_full_coverage(&resolved, 0x50);

        // Only each call's exact bytes target its pad; the rest of both blocks
        // is filler and cannot accidentally catch an exception.
        let cs0 = resolved
            .call_site_ranges
            .iter()
            .find(|&&(s, _, _)| s == 0x05)
            .unwrap();
        assert_eq!(cs0.2, 0x10, "block 0 call site targets the catch pad");
        let cs2 = resolved
            .call_site_ranges
            .iter()
            .find(|&&(s, _, _)| s == 0x24)
            .unwrap();
        assert_eq!(cs2.2, 0x30, "block 2 call site targets the cleanup pad");
        // The non-throwing region containing the pad blocks + tail (offset 0x40
        // lands here) is covered by a landing_pad==0 filler.
        let covering = resolved
            .call_site_ranges
            .iter()
            .find(|&&(s, l, _)| s <= 0x40 && 0x40 < s + l)
            .expect("offset 0x40 must be covered");
        assert_eq!(covering.2, 0, "the tail region is a landing_pad==0 filler");

        let lsda = generate_x86_lsda(&resolved, "__gxx_personality_v0").unwrap();
        assert_eq!(lsda[0], 0xFF);
        assert_ne!(lsda[1], 0xFF, "a catch-all NULL type-table slot is present");
    }

    #[test]
    fn resolve_x86_eh_offsets_gap_filler_full_coverage() {
        // A function with a personality but a single invoke on a middle block:
        // the resolver must still fill the head, the pad block, and the tail.
        let eh = EhFunctionInfo {
            personality: Some("__rust_eh_personality".to_string()),
            landing_pads: vec![EhLandingPad {
                block: Block(2),
                catch_type_indices: Vec::new(),
                is_cleanup: true,
            }],
            call_sites: vec![EhCallSite {
                call_block: Block(1),
                landing_pad_block: Block(2),
            }],
        };
        let func = function_with_eh(eh);
        let block_offsets = offsets(&[(0, 0x00), (1, 0x18), (2, 0x30)]);
        let resolved = resolve_x86_eh_offsets(
            &func,
            &block_offsets,
            &encoded_calls(&[(1, 0, 0x20, 0x25)]),
            0x48,
        )
        .unwrap();
        assert_full_coverage(&resolved, 0x48);
        assert_eq!(resolved.call_site_ranges[0], (0x00, 0x20, 0x00));
        assert_eq!(resolved.call_site_ranges[1], (0x20, 0x05, 0x30));
        assert_eq!(resolved.call_site_ranges[2], (0x25, 0x23, 0x00));
    }

    #[test]
    fn exact_call_range_excludes_other_instructions_and_covers_return_address_minus_one() {
        let eh = EhFunctionInfo {
            personality: Some("__rust_eh_personality".to_string()),
            landing_pads: vec![EhLandingPad {
                block: Block(2),
                catch_type_indices: Vec::new(),
                is_cleanup: true,
            }],
            call_sites: vec![EhCallSite {
                call_block: Block(0),
                landing_pad_block: Block(2),
            }],
        };
        let mut func = function_with_eh(eh);
        // Model unrelated instructions on both sides of the Invoke call. Their
        // bytes must remain no-handler filler even though they share its block.
        let block = func.blocks.get_mut(&Block(0)).unwrap();
        block
            .insts
            .insert(0, X86ISelInst::new(X86Opcode::Nop, vec![]));
        block.insts.push(X86ISelInst::new(X86Opcode::Nop, vec![]));

        let resolved = resolve_x86_eh_offsets(
            &func,
            &offsets(&[(0, 0x00), (2, 0x20)]),
            &encoded_calls(&[(0, 1, 0x08, 0x0D)]),
            0x30,
        )
        .unwrap();
        assert_full_coverage(&resolved, 0x30);
        assert_eq!(landing_pad_for_pc(&resolved, 0x07), 0);
        assert_eq!(landing_pad_for_pc(&resolved, 0x08), 0x20);
        assert_eq!(landing_pad_for_pc(&resolved, 0x0C), 0x20);
        // Itanium personalities classify the saved return address after
        // subtracting one, so CALL end-1 must still be inside the exact range.
        assert_eq!(landing_pad_for_pc(&resolved, 0x0D - 1), 0x20);
        assert_eq!(landing_pad_for_pc(&resolved, 0x0D), 0);
    }

    #[test]
    fn ambiguous_second_call_in_protected_block_fails_closed() {
        let eh = EhFunctionInfo {
            personality: Some("__rust_eh_personality".to_string()),
            landing_pads: vec![EhLandingPad {
                block: Block(2),
                catch_type_indices: Vec::new(),
                is_cleanup: true,
            }],
            call_sites: vec![EhCallSite {
                call_block: Block(0),
                landing_pad_block: Block(2),
            }],
        };
        let mut func = function_with_eh(eh);
        func.push_inst(Block(0), X86ISelInst::new(X86Opcode::CallR, vec![]));
        let err = resolve_x86_eh_offsets(
            &func,
            &offsets(&[(0, 0x00), (2, 0x20)]),
            &encoded_calls(&[(0, 0, 0x08, 0x0D), (0, 1, 0x10, 0x12)]),
            0x30,
        )
        .expect_err("block-granular metadata cannot guess which call is protected");
        assert!(matches!(err, X86PipelineError::MalformedFunction { .. }));
        assert!(err.to_string().contains("contains 2 eligible calls"));
    }

    #[test]
    fn unprotected_call_in_another_block_remains_no_handler_filler() {
        let eh = EhFunctionInfo {
            personality: Some("__rust_eh_personality".to_string()),
            landing_pads: vec![EhLandingPad {
                block: Block(2),
                catch_type_indices: Vec::new(),
                is_cleanup: true,
            }],
            call_sites: vec![EhCallSite {
                call_block: Block(0),
                landing_pad_block: Block(2),
            }],
        };
        let mut func = function_with_eh(eh);
        func.ensure_block(Block(1));
        func.push_inst(Block(1), X86ISelInst::new(X86Opcode::Call, vec![]));
        let resolved = resolve_x86_eh_offsets(
            &func,
            &offsets(&[(0, 0x00), (1, 0x10), (2, 0x20)]),
            &encoded_calls(&[(0, 0, 0x08, 0x0D), (1, 0, 0x18, 0x1D)]),
            0x30,
        )
        .unwrap();
        assert_full_coverage(&resolved, 0x30);
        assert_eq!(landing_pad_for_pc(&resolved, 0x0C), 0x20);
        assert_eq!(
            landing_pad_for_pc(&resolved, 0x1C),
            0,
            "a plain call absent from EH metadata must not inherit another Invoke's handler"
        );
    }

    #[test]
    fn missing_exact_call_range_and_zero_offset_pad_fail_closed() {
        let eh = EhFunctionInfo {
            personality: Some("__rust_eh_personality".to_string()),
            landing_pads: vec![EhLandingPad {
                block: Block(2),
                catch_type_indices: Vec::new(),
                is_cleanup: true,
            }],
            call_sites: vec![EhCallSite {
                call_block: Block(0),
                landing_pad_block: Block(2),
            }],
        };
        let func = function_with_eh(eh.clone());
        let err = resolve_x86_eh_offsets(
            &func,
            &offsets(&[(0, 0x00), (2, 0x20)]),
            &X86EncodedCallRanges::new(),
            0x30,
        )
        .expect_err("an unbound protected call must not widen to its block");
        assert!(
            err.to_string()
                .contains("no exact final-encoding byte range")
        );

        let zero_pad_func = function_with_eh(eh);
        let err = resolve_x86_eh_offsets(
            &zero_pad_func,
            &offsets(&[(2, 0x00), (0, 0x10)]),
            &encoded_calls(&[(0, 0, 0x18, 0x1D)]),
            0x30,
        )
        .expect_err("offset zero is the LSDA no-handler sentinel");
        assert!(err.to_string().contains("offset 0"));
    }
}

fn build_x86_64_eh_frame_cfi(records: &[X86EhFrameRecord]) -> DwarfCfiSection {
    let mut section = DwarfCfiSection::new_x86_64();
    for record in records {
        let fde = x86_64_fde_from_prologue(
            &record.callee_saved,
            record.frame_size,
            0,
            record.code_len,
            record.symbol_index,
        );
        section.add_fde(fde);
    }
    section
}

/// Overwrite the little-endian `i32` at `offset` in the `__eh_frame` bytes.
/// Used to bake the x86-64 personality `+4` field-end pcrel-bias addend.
fn bake_le_i32(eh_frame: &mut [u8], offset: u32, value: i32) -> Result<(), X86PipelineError> {
    let start = offset as usize;
    let end = start.checked_add(4).ok_or_else(|| {
        X86PipelineError::FrameLowering("x86-64 eh_frame i32 bake offset overflow".to_string())
    })?;
    let slot = eh_frame.get_mut(start..end).ok_or_else(|| {
        X86PipelineError::FrameLowering("x86-64 eh_frame i32 bake offset out of range".to_string())
    })?;
    slot.copy_from_slice(&value.to_le_bytes());
    Ok(())
}

/// Overwrite the little-endian `i64` at `offset` in the `__eh_frame` bytes.
/// Used to bake the x86-64 self-relative FDE PC-begin / LSDA pointers (the
/// no-relocation, ld64-re-synthesized form).
fn bake_le_i64(eh_frame: &mut [u8], offset: u32, value: i64) -> Result<(), X86PipelineError> {
    let start = offset as usize;
    let end = start.checked_add(8).ok_or_else(|| {
        X86PipelineError::FrameLowering("x86-64 eh_frame i64 bake offset overflow".to_string())
    })?;
    let slot = eh_frame.get_mut(start..end).ok_or_else(|| {
        X86PipelineError::FrameLowering("x86-64 eh_frame i64 bake offset out of range".to_string())
    })?;
    slot.copy_from_slice(&value.to_le_bytes());
    Ok(())
}

fn patch_x86_64_macho_eh_frame_addends(
    eh_frame: &mut [u8],
    cfi: &DwarfCfiSection,
) -> Result<(), X86PipelineError> {
    // Every self-relative (DW_EH_PE_pcrel|sdata4) 4-byte slot referenced by a
    // subtractor pair needs its addend baked to `-(slot_offset)`: the pair
    // computes `symbol - eh_frame_base + addend`, and with the eh_frame section
    // symbol at offset 0 that yields `symbol - (eh_frame_base + slot_offset)` =
    // `symbol - slot_addr`, i.e. a true self-relative pointer. This covers both
    // the FDE PC-begin (all FDEs) and the FDE LSDA slot (zPLR/EH FDEs; log2=2,
    // 4-byte -- NOT aarch64's 8-byte). The CIE personality slot is NOT patched
    // here: it stays the 0 sentinel and is resolved by an X86_64_RELOC_GOT
    // (GOT-indirect pcrel), mirroring the aarch64 personality path.
    let pcrel_slots = cfi
        .fde_pc_begin_relocation_offsets()
        .into_iter()
        .chain(cfi.fde_lsda_relocation_offsets());
    for slot_offset in pcrel_slots {
        let addend = -i32::try_from(slot_offset).map_err(|_| {
            X86PipelineError::FrameLowering("x86-64 eh_frame offset overflow".to_string())
        })?;
        let offset = slot_offset as usize;
        let end = offset.checked_add(4).ok_or_else(|| {
            X86PipelineError::FrameLowering("x86-64 eh_frame offset overflow".to_string())
        })?;
        let Some(slot) = eh_frame.get_mut(offset..end) else {
            return Err(X86PipelineError::FrameLowering(
                "x86-64 eh_frame relocation offset out of range".to_string(),
            ));
        };
        slot.copy_from_slice(&addend.to_le_bytes());
    }
    Ok(())
}

fn x86_64_dynamic_eh_frame_record(
    metadata: &X86FrameMetadata,
    code_len: u32,
    symbol_index: u32,
) -> Option<X86EhFrameRecord> {
    metadata.has_dynamic_alloc.then(|| X86EhFrameRecord {
        callee_saved: metadata.callee_saved.clone(),
        frame_size: metadata.frame_size,
        code_len,
        symbol_index,
    })
}

fn add_x86_64_eh_frame_to_elf(writer: &mut ElfWriter, records: &[X86EhFrameRecord]) {
    use crate::elf::constants::{SHF_ALLOC, SHT_PROGBITS};
    use crate::elf::reloc::{Elf64Rela, X86_64RelocType};

    if records.is_empty() {
        return;
    }

    let cfi = build_x86_64_eh_frame_cfi(records);
    let eh_frame = cfi.to_bytes();
    if eh_frame.is_empty() {
        return;
    }

    let section = writer.add_section(".eh_frame", &eh_frame, SHT_PROGBITS, SHF_ALLOC, 8);
    let section_index = usize::from(section - 1);
    for (offset, record) in cfi
        .fde_pc_begin_relocation_offsets()
        .into_iter()
        .zip(records.iter())
    {
        writer.add_relocation(
            section_index,
            Elf64Rela::x86_64(
                u64::from(offset),
                record.symbol_index,
                X86_64RelocType::Pc32,
                0,
            ),
        );
    }
}

/// Per-function unwind input for the x86-64 Mach-O `__eh_frame` emitter.
///
/// Owns the small pieces needed to build an FDE plus the symbols an EH FDE
/// references. A function contributes an FDE when it has a dynamic-alloc frame
/// (backtrace support, zR) OR carries exception-handling structure (zPLR: the
/// LSDA is referenced ONLY from the FDE on x86 -- there is no compact-unwind).
struct X86EhFrameInput {
    callee_saved: Vec<X86PReg>,
    frame_size: u32,
    code_len: u32,
    has_dynamic_alloc: bool,
    function_symbol_id: crate::macho::writer::SymbolId,
    /// `Some` when the function has EH: the personality (name + external symbol)
    /// plus the local `_GCC_except_table_<fn>` symbol the FDE's LSDA slot points
    /// at.
    eh: Option<X86EhFdeInput>,
}

struct X86EhFdeInput {
    personality: String,
    personality_symbol_id: crate::macho::writer::SymbolId,
    lsda_symbol_id: crate::macho::writer::SymbolId,
}

fn add_x86_64_eh_frame_to_macho(
    writer: &mut MachOWriter,
    inputs: &[X86EhFrameInput],
) -> Result<(), X86PipelineError> {
    use crate::dwarf_cfi::DwarfCfiSection;
    use crate::macho::x86_64_reloc::{X86_64Relocation, create_x86_64_subtractor_pair};

    // A function needs an FDE when it has a dynamic-alloc frame OR carries EH.
    let fde_inputs: Vec<&X86EhFrameInput> = inputs
        .iter()
        .filter(|i| i.has_dynamic_alloc || i.eh.is_some())
        .collect();
    if fde_inputs.is_empty() {
        return Ok(());
    }

    let has_any_eh = fde_inputs.iter().any(|i| i.eh.is_some());

    // All EH FDEs in one object share ONE CIE and therefore ONE personality
    // pointer. The Rust unwinding path is single-personality; a module mixing
    // DISTINCT personalities would need multiple CIEs, so fail closed rather than
    // silently wire every FDE to the wrong personality.
    let mut personality_symbol: Option<crate::macho::writer::SymbolId> = None;
    let mut personality_name: Option<&str> = None;
    for eh in fde_inputs.iter().filter_map(|i| i.eh.as_ref()) {
        match personality_name {
            None => {
                personality_name = Some(eh.personality.as_str());
                personality_symbol = Some(eh.personality_symbol_id);
            }
            Some(existing) if existing != eh.personality.as_str() => {
                return Err(X86PipelineError::FrameLowering(format!(
                    "x86-64 Mach-O eh_frame: distinct personalities in one object \
                     ({existing} vs {}) require multiple CIEs (unsupported)",
                    eh.personality
                )));
            }
            _ => {}
        }
    }

    // zPLR CIE when ANY FDE has EH, else the plain zR CIE (backtrace-only).
    let mut cfi = if has_any_eh {
        DwarfCfiSection::new_x86_64_with_eh()
    } else {
        DwarfCfiSection::new_x86_64()
    };
    for input in &fde_inputs {
        // symbol_index is unused for Mach-O (relocations are emitted below via
        // the writer's final symbol indices); pass 0.
        let mut fde =
            x86_64_fde_from_prologue(&input.callee_saved, input.frame_size, 0, input.code_len, 0);
        if input.eh.is_some() {
            fde = fde.with_lsda();
        }
        cfi.add_fde(fde);
    }

    let mut eh_frame = cfi.to_bytes();
    if eh_frame.is_empty() {
        return Ok(());
    }
    // ENC-EHDC: fail-closed decode-check honesty gate. Independently re-decode
    // the emitted __eh_frame bytes and confirm every CIE/FDE field equals the
    // emitter intent BEFORE relocation-addend patching (the check expects the
    // pre-patch sentinel 0 for PC-begin / LSDA / personality). trust-cg refuses
    // to emit an unwind table it cannot round-trip back to its own intent.
    crate::dwarf_cfi_decode_check::verify_eh_frame_roundtrip(&cfi, &eh_frame)
        .map_err(|e| X86PipelineError::FrameLowering(e.to_string()))?;

    // LD-PRIME COMPAT (x86 EH executed lane): the modern Mach-O linker
    // (ld-prime, default since Xcode 15) PARSES a relocatable object's
    // `__TEXT,__eh_frame` record-by-record and REJECTS a zero-length record
    // with `ld: empty CIE` — exactly the 4-zero-byte terminator `to_bytes()`
    // appends. clang emits NO terminator in x86-64 Mach-O objects (the linker
    // owns the final image's `__eh_frame` layout); classic ld64 merely
    // tolerated ours. Strip it AFTER the decode-check gate above (which
    // verifies the full serialization contract, terminator included) so the
    // emitted section is clang-shaped: bare CIE + FDEs. Verified empirically:
    // with the terminator `cc -arch x86_64` fails to link (`empty CIE`);
    // without it ld-prime links and the catch RUNS under Rosetta.
    let terminator = eh_frame.split_off(eh_frame.len() - 4);
    debug_assert_eq!(
        terminator, [0u8; 4],
        "__eh_frame serialization must end with the zero terminator"
    );

    const EH_FRAME_FLAGS: u32 = 0x6800_000B;
    const EH_FRAME_ALIGN_LOG2: u32 = 3;

    if has_any_eh {
        // x86-64 macOS EH (zPLR) __eh_frame. ld64's x86-64 __eh_frame reader
        // (unlike arm64's) does NOT consume SUBTRACTOR/UNSIGNED relocations for
        // the FDE PC-begin / LSDA pointers — it re-synthesizes __unwind_info from
        // the SELF-RELATIVE 8-byte (pcrel|absptr) pointer values it reads directly
        // out of the section, exactly as clang emits them. Emitting subtractor
        // pairs here makes ld64 fail ("symbol index out of range"), so we BAKE
        // the self-relative pointers and emit NO relocation for them. Only the
        // personality keeps a GOT relocation, and its 4-byte slot needs a baked
        // `+4` addend: X86_64_RELOC_GOT is pcrel biased by the field END, while
        // DW_EH_PE_pcrel is field-START relative, so +4 compensates (matches
        // clang; the arm64 GOT reloc is field-relative and needs no addend).
        // [EH Lane 3]
        let eh_frame_addr = writer.next_section_vmaddr(EH_FRAME_ALIGN_LOG2)?;

        // Personality: keep the 0 sentinel + a baked +4 (field-end pcrel bias).
        if let Some(offset) = cfi.cie_personality_relocation_offset() {
            bake_le_i32(&mut eh_frame, offset, 4)?;
        }
        // FDE PC-begin (every FDE): self-relative `function - pc_begin_field`.
        for (pc_begin_offset, input) in cfi
            .fde_pc_begin_relocation_offsets()
            .into_iter()
            .zip(&fde_inputs)
        {
            let func_addr = writer.symbol_vmaddr(input.function_symbol_id)? as i64;
            let field_addr = (eh_frame_addr + u64::from(pc_begin_offset)) as i64;
            bake_le_i64(&mut eh_frame, pc_begin_offset, func_addr - field_addr)?;
        }
        // FDE LSDA (EH FDEs only): self-relative `_GCC_except_table - lsda_field`.
        let eh_lsda_symbols: Vec<crate::macho::writer::SymbolId> = fde_inputs
            .iter()
            .filter_map(|i| i.eh.as_ref().map(|e| e.lsda_symbol_id))
            .collect();
        for (lsda_offset, lsda_symbol_id) in cfi
            .fde_lsda_relocation_offsets()
            .into_iter()
            .zip(eh_lsda_symbols)
        {
            let lsda_addr = writer.symbol_vmaddr(lsda_symbol_id)? as i64;
            let field_addr = (eh_frame_addr + u64::from(lsda_offset)) as i64;
            bake_le_i64(&mut eh_frame, lsda_offset, lsda_addr - field_addr)?;
        }

        let eh_frame_section = writer.add_custom_section(
            b"__eh_frame",
            b"__TEXT",
            &eh_frame,
            EH_FRAME_ALIGN_LOG2,
            EH_FRAME_FLAGS,
        );
        // The ONLY x86-64 __eh_frame relocation: the personality GOT pointer.
        if let (Some(offset), Some(personality_symbol_id)) =
            (cfi.cie_personality_relocation_offset(), personality_symbol)
        {
            let personality_index = writer
                .final_symbol_index(personality_symbol_id)?
                .ok_or_else(|| {
                    X86PipelineError::FrameLowering(
                        "x86-64 Mach-O personality symbol missing before relocation emission"
                            .to_string(),
                    )
                })?;
            let relocation_offset = checked_x86_macho_relocation_offset_value(
                "<module>",
                "Mach-O personality relocation offset",
                u128::from(offset),
            )?;
            writer.add_x86_64_relocation(
                eh_frame_section,
                X86_64Relocation::got(relocation_offset, personality_index),
            )?;
        }
        return Ok(());
    }

    // Non-EH (backtrace-only, zR) path: unchanged self-relative subtractor pairs.
    patch_x86_64_macho_eh_frame_addends(&mut eh_frame, &cfi)?;
    let eh_frame_section = writer.add_custom_section(
        b"__eh_frame",
        b"__TEXT",
        &eh_frame,
        EH_FRAME_ALIGN_LOG2,
        EH_FRAME_FLAGS,
    );
    let eh_frame_symbol_id = writer.add_symbol("EH_Frame", eh_frame_section + 1, 0, false)?;
    let eh_frame_symbol_index =
        writer
            .final_symbol_index(eh_frame_symbol_id)?
            .ok_or_else(|| {
                X86PipelineError::FrameLowering(
                    "x86-64 Mach-O EH frame section symbol missing before relocation emission"
                        .to_string(),
                )
            })?;

    // FDE PC-begin relocations (every FDE): self-relative `function - eh_frame`
    // subtractor pair (log2=2, 4-byte).
    for (pc_begin_offset, input) in cfi
        .fde_pc_begin_relocation_offsets()
        .into_iter()
        .zip(&fde_inputs)
    {
        let function_symbol_index = writer
            .final_symbol_index(input.function_symbol_id)?
            .ok_or_else(|| {
                X86PipelineError::FrameLowering(
                    "x86-64 Mach-O function symbol missing before unwind relocation emission"
                        .to_string(),
                )
            })?;
        let relocation_offset = checked_x86_macho_relocation_offset_value(
            "<module>",
            "Mach-O FDE PC-begin relocation offset",
            u128::from(pc_begin_offset),
        )?;
        let (subtractor, unsigned) = create_x86_64_subtractor_pair(
            relocation_offset,
            function_symbol_index,
            eh_frame_symbol_index,
            2,
        );
        writer.add_x86_64_relocation(eh_frame_section, subtractor)?;
        writer.add_x86_64_relocation(eh_frame_section, unsigned)?;
    }

    // FDE LSDA relocations (EH FDEs only, in FDE order): self-relative
    // `_GCC_except_table_<fn> - eh_frame` subtractor pair (log2=2, 4-byte). The
    // `fde_lsda_relocation_offsets()` list has one entry per with_lsda() FDE, in
    // the same order the EH FDEs were added, so it zips with the EH inputs.
    let eh_lsda_symbols: Vec<crate::macho::writer::SymbolId> = fde_inputs
        .iter()
        .filter_map(|i| i.eh.as_ref().map(|e| e.lsda_symbol_id))
        .collect();
    for (lsda_offset, lsda_symbol_id) in cfi
        .fde_lsda_relocation_offsets()
        .into_iter()
        .zip(eh_lsda_symbols)
    {
        let lsda_symbol_index = writer.final_symbol_index(lsda_symbol_id)?.ok_or_else(|| {
            X86PipelineError::FrameLowering(
                "x86-64 Mach-O LSDA symbol missing before unwind relocation emission".to_string(),
            )
        })?;
        let relocation_offset = checked_x86_macho_relocation_offset_value(
            "<module>",
            "Mach-O FDE LSDA relocation offset",
            u128::from(lsda_offset),
        )?;
        let (subtractor, unsigned) = create_x86_64_subtractor_pair(
            relocation_offset,
            lsda_symbol_index,
            eh_frame_symbol_index,
            2,
        );
        writer.add_x86_64_relocation(eh_frame_section, subtractor)?;
        writer.add_x86_64_relocation(eh_frame_section, unsigned)?;
    }

    Ok(())
}

/// Mangle a trust_ir/C-level symbol name to its Mach-O symbol-table name.
///
/// Mach-O prefixes every C symbol with exactly one leading underscore, so a C
/// function `foo` becomes `_foo` and a C runtime helper `__divti3` becomes
/// `___divti3`. The prefix is therefore applied UNCONDITIONALLY (matching
/// clang and the AArch64 `macho_symbol_name`): callers pass the bare C-level
/// name, never a pre-mangled one. This is what lets a compiler-rt libcall
/// like `__udivti3` resolve against the `___udivti3` the linker provides.
fn macho_x86_64_symbol_name(name: &str) -> String {
    format!("_{name}")
}

fn coff_x86_64_import_symbol_name(name: &str) -> String {
    if name.starts_with("__imp_") {
        name.to_string()
    } else {
        format!("__imp_{name}")
    }
}

/// Generate prologue instructions for an x86-64 stack frame.
fn generate_prologue(
    callee_saved: &[X86PReg],
    callee_saved_xmms: &[X86PReg],
    xmm_save_offsets: &[i32],
    frame_size: u32,
) -> Vec<X86ISelInst> {
    let mut prologue = Vec::new();

    // PUSH RBP
    prologue.push(X86ISelInst::new(
        X86Opcode::Push,
        vec![X86ISelOperand::PReg(RBP)],
    ));

    // MOV RBP, RSP
    prologue.push(X86ISelInst::new(
        X86Opcode::MovRR,
        vec![X86ISelOperand::PReg(RBP), X86ISelOperand::PReg(RSP)],
    ));

    // Push callee-saved registers.
    for &reg in callee_saved {
        prologue.push(X86ISelInst::new(
            X86Opcode::Push,
            vec![X86ISelOperand::PReg(reg)],
        ));
    }

    // SUB RSP, frame_size (allocate stack frame for locals/spills).
    if frame_size > 0 {
        prologue.push(X86ISelInst::new(
            X86Opcode::SubRI,
            vec![
                X86ISelOperand::PReg(RSP),
                X86ISelOperand::Imm(frame_size as i64),
            ],
        ));
    }

    for (&reg, &offset) in callee_saved_xmms.iter().zip(xmm_save_offsets.iter()) {
        prologue.push(X86ISelInst::new(
            X86Opcode::MovdquMR,
            vec![
                X86ISelOperand::MemAddr {
                    base: Box::new(X86ISelOperand::PReg(RBP)),
                    disp: offset,
                },
                X86ISelOperand::PReg(reg),
            ],
        ));
    }

    prologue
}

/// Generate epilogue instructions for an x86-64 stack frame.
fn generate_epilogue(
    callee_saved: &[X86PReg],
    callee_saved_xmms: &[X86PReg],
    xmm_save_offsets: &[i32],
    frame_size: u32,
    has_dynamic_alloc: bool,
) -> Vec<X86ISelInst> {
    let mut epilogue = Vec::new();

    for (&reg, &offset) in callee_saved_xmms.iter().zip(xmm_save_offsets.iter()).rev() {
        epilogue.push(X86ISelInst::new(
            X86Opcode::MovdquRM,
            vec![
                X86ISelOperand::PReg(reg),
                X86ISelOperand::MemAddr {
                    base: Box::new(X86ISelOperand::PReg(RBP)),
                    disp: offset,
                },
            ],
        ));
    }

    if has_dynamic_alloc {
        let callee_saved_bytes = (callee_saved.len() as i32) * 8;
        epilogue.push(X86ISelInst::new(
            X86Opcode::Lea,
            vec![
                X86ISelOperand::PReg(RSP),
                X86ISelOperand::MemAddr {
                    base: Box::new(X86ISelOperand::PReg(RBP)),
                    disp: -callee_saved_bytes,
                },
            ],
        ));
    } else if frame_size > 0 {
        // ADD RSP, frame_size (deallocate locals/spills).
        epilogue.push(X86ISelInst::new(
            X86Opcode::AddRI,
            vec![
                X86ISelOperand::PReg(RSP),
                X86ISelOperand::Imm(frame_size as i64),
            ],
        ));
    }

    // Pop callee-saved registers in reverse order.
    for &reg in callee_saved.iter().rev() {
        epilogue.push(X86ISelInst::new(
            X86Opcode::Pop,
            vec![X86ISelOperand::PReg(reg)],
        ));
    }

    // POP RBP
    epilogue.push(X86ISelInst::new(
        X86Opcode::Pop,
        vec![X86ISelOperand::PReg(RBP)],
    ));

    epilogue
}

// ---------------------------------------------------------------------------
// Branch resolution for variable-length x86-64 instructions
// ---------------------------------------------------------------------------

/// Estimate the encoded byte size of an x86-64 instruction.
///
/// This is used for branch offset calculation. The estimates are
/// conservative — we use the maximum encoding size for each class.
fn estimate_inst_size(inst: &X86ISelInst) -> usize {
    match inst.opcode {
        // Pseudo-instructions: 0 bytes.
        X86Opcode::Nop
        | X86Opcode::Phi
        | X86Opcode::StackAlloc
        | X86Opcode::V4I32MaskExtract
        | X86Opcode::V16I8MaskExtract
        | X86Opcode::V8I16MaskExtract
        | X86Opcode::V2I64MaskExtract
        | X86Opcode::V128BoolSelect => 0,

        // RET: 1 byte.
        X86Opcode::Ret => 1,

        // MFENCE: 0F AE F0.
        X86Opcode::Mfence => 3,

        // UD2: 0F 0B.
        X86Opcode::Ud2 => 2,

        // AtomicRmwCasLoop expands to load + ALU + locked CMPXCHG retry + result copy.
        X86Opcode::AtomicRmwCasLoop
        | X86Opcode::AtomicRmwCasLoop8
        | X86Opcode::AtomicRmwCasLoop16 => 32,

        // PUSH/POP: 1 byte (50+rd) without REX, 2 bytes (REX.B + 50+rd) with REX.
        X86Opcode::Push | X86Opcode::Pop => {
            if let Some(X86ISelOperand::PReg(preg)) = inst.operands.first() {
                if preg.needs_rex() { 2 } else { 1 }
            } else {
                2 // Conservative fallback for unresolved operands
            }
        }

        // JMP rel32: 5 bytes.
        X86Opcode::Jmp => 5,

        // JMP r64 (indirect, jump-table dispatch): [REX.B] + FF + ModRM = 2-3
        // bytes; 3 is the exact upper bound (final offsets come from the actual
        // encoder position, so this is a layout hint).
        X86Opcode::JmpR => 3,

        // Jcc rel32: 6 bytes (0F 8x + 4-byte displacement).
        X86Opcode::Jcc => 6,

        // CALL rel32: 5 bytes.
        X86Opcode::Call => 5,

        // MOV r, imm: exact for physical regs, conservative for virtual regs.
        X86Opcode::MovRI => estimate_x86_movri_size(inst),

        // ALU r/m, imm: 3-7 bytes depending on REX and imm8/imm32 form.
        X86Opcode::AddRI
        | X86Opcode::SubRI
        | X86Opcode::AndRI
        | X86Opcode::OrRI
        | X86Opcode::XorRI
        | X86Opcode::CmpRI => match (inst.operands.first(), inst.operands.get(1)) {
            (Some(X86ISelOperand::PReg(dst)), Some(X86ISelOperand::Imm(imm))) => {
                x86_alu_ri_encoded_size(*dst, *imm)
            }
            _ => 7,
        },

        // TEST r/m64, imm32: 7 bytes (REX.W + F7 + ModRM + imm32).
        X86Opcode::TestRI => 7,

        // ALU r/m64, r64: 3 bytes (REX.W + opcode + ModRM).
        X86Opcode::AddRR
        | X86Opcode::SubRR
        | X86Opcode::AdcRR
        | X86Opcode::SbbRR
        | X86Opcode::AndRR
        | X86Opcode::OrRR
        | X86Opcode::XorRR
        | X86Opcode::CmpRR
        | X86Opcode::TestRR
        | X86Opcode::MovRR
        | X86Opcode::MovRR32 => 3,

        // One-operand multiply/divide: F7 /r, plus REX.W for 64-bit operands.
        X86Opcode::Idiv | X86Opcode::Div | X86Opcode::Mul => match inst.operands.first() {
            Some(X86ISelOperand::PReg(preg)) if preg.is_gpr32() => 2,
            Some(X86ISelOperand::VReg(vreg)) if vreg.class == RegClass::Gpr32 => 2,
            _ => 3,
        },

        // Base+disp memory operations: exact for physical regs, conservative otherwise.
        X86Opcode::MovRM8
        | X86Opcode::MovRM16
        | X86Opcode::MovRM32
        | X86Opcode::MovRM
        | X86Opcode::MovMR8
        | X86Opcode::MovMR16
        | X86Opcode::MovMR32
        | X86Opcode::MovMR
        | X86Opcode::Lea => estimate_x86_base_disp_mem_reg_size(inst),

        // GPR base+disp reg-memory operations: exact for physical regs, conservative otherwise.
        X86Opcode::AddRM | X86Opcode::SubRM | X86Opcode::CmpRM | X86Opcode::TestRM => {
            estimate_x86_base_disp_rm_alu_size(inst, 1)
        }
        X86Opcode::ImulRM => estimate_x86_base_disp_rm_alu_size(inst, 2),

        // RIP-relative GPR forms: 7 bytes (REX.W + opcode + ModRM + disp32).
        // MovRipRelTlv is byte-identical to MovRipRel (only the reloc differs).
        X86Opcode::LeaRip | X86Opcode::MovRipRel | X86Opcode::MovRipRelTlv => 7,

        // SIB memory: up to 9 bytes (REX.W + opcode + ModRM + SIB + disp32).
        X86Opcode::MovRMSib | X86Opcode::MovsxdRMSib | X86Opcode::MovMRSib | X86Opcode::LeaSib => 9,
        // 32-bit SIB MOVs: optional REX + opcode + ModRM + SIB + disp32 = 8.
        X86Opcode::MovRM32Sib | X86Opcode::MovMR32Sib => 8,
        // 8-bit SIB MOVs: optional (or FORCED, for SPL/BPL/SIL/DIL) REX +
        // opcode + ModRM + SIB + disp32 = 8.
        X86Opcode::MovRM8Sib | X86Opcode::MovMR8Sib => 8,
        // Scalar-FP SIB loads: mandatory SIMD prefix (F2/F3) + optional REX +
        // 0F escape + opcode + ModRM + SIB + disp32 = 10 bytes max. This MUST
        // NOT be under-estimated: branch displacements are laid out against it.
        X86Opcode::MovsdRMSib | X86Opcode::MovssRMSib => 10,
        // SIB memory with a two-byte opcode: REX.W + 0F AF + ModRM + SIB +
        // disp32 = 9 bytes max (the 0F escape replaces the single-byte MOV
        // opcode, net identical to the row above).
        X86Opcode::ImulRMSib => 9,

        // SSE: 4-5 bytes.
        X86Opcode::Addsd
        | X86Opcode::Subsd
        | X86Opcode::Mulsd
        | X86Opcode::Divsd
        | X86Opcode::Sqrtsd
        | X86Opcode::Andpd
        | X86Opcode::Addss
        | X86Opcode::Subss
        | X86Opcode::Mulss
        | X86Opcode::Divss
        | X86Opcode::Sqrtss
        | X86Opcode::Andps
        | X86Opcode::MovsdRR
        | X86Opcode::MovssRR
        | X86Opcode::Pand
        | X86Opcode::Pandn
        | X86Opcode::Por
        | X86Opcode::Pxor
        | X86Opcode::Pcmpeqb
        | X86Opcode::Pcmpeqw
        | X86Opcode::Pcmpgtb
        | X86Opcode::Pcmpgtw
        | X86Opcode::Pcmpeqd
        | X86Opcode::Pcmpgtd
        | X86Opcode::Paddb
        | X86Opcode::Paddw
        | X86Opcode::Paddd
        | X86Opcode::Psubb
        | X86Opcode::Psubw
        | X86Opcode::Psubd
        | X86Opcode::Paddq
        | X86Opcode::Psubq
        | X86Opcode::Pmullw
        | X86Opcode::Pmuludq
        | X86Opcode::Punpcklbw
        | X86Opcode::Punpckldq
        | X86Opcode::Packuswb
        | X86Opcode::Punpckhbw
        | X86Opcode::Punpcklqdq
        // PSADBW: 66 0F F6 /r — same 2-byte-opcode length class (5 bytes) as the
        // packed SSE2 ops above (NOT the 3-byte-map SSE4.1 Pmulld group).
        | X86Opcode::Psadbw
        | X86Opcode::Pmovmskb
        | X86Opcode::MovdToXmm
        | X86Opcode::MovdFromXmm
        | X86Opcode::MovqToXmm
        | X86Opcode::MovqFromXmm
        | X86Opcode::MovdqaRR
        | X86Opcode::Ucomisd
        | X86Opcode::Ucomiss
        | X86Opcode::Minsd
        | X86Opcode::Maxsd
        | X86Opcode::Minss
        | X86Opcode::Maxss => 5,
        // CMPSD/CMPSS carry a 1-byte imm8 predicate: prefix+REX+0F+C2+ModRM+ib.
        X86Opcode::Pmulld
        | X86Opcode::Pcmpeqq
        | X86Opcode::Pcmpgtq
        | X86Opcode::Pblendvb
        | X86Opcode::Cmpsd
        | X86Opcode::Cmpss => 6,
        X86Opcode::Pshufd => estimate_x86_pshufd_size(inst),
        X86Opcode::Ptest => estimate_x86_ptest_size(inst),
        X86Opcode::Pinsrd | X86Opcode::Pextrd | X86Opcode::Pinsrq | X86Opcode::Pextrq => 7,
        // SSE4.1 scalar round-to-integral: 66 [REX] 0F 3A 0B/0A /r ib = 6-7 bytes.
        X86Opcode::Roundsd | X86Opcode::Roundss => 7,

        // SSE memory: 6-8 bytes.
        X86Opcode::MovsdRM
        | X86Opcode::MovsdMR
        | X86Opcode::MovssRM
        | X86Opcode::MovssMR
        | X86Opcode::MovdquRM
        | X86Opcode::MovdquMR
        | X86Opcode::MovdqaRM
        | X86Opcode::MovdqaMR => 8,

        // SSE RIP-relative: 8 bytes (prefix + [REX] + 0F + opcode + ModRM + disp32).
        X86Opcode::MovssRipRel | X86Opcode::MovsdRipRel => 8,

        // SSE conversion: 5-6 bytes (prefix + REX.W + 0F + opcode + ModRM).
        X86Opcode::Cvtsi2sd
        | X86Opcode::Cvtsd2si
        | X86Opcode::Cvttsd2si
        | X86Opcode::Cvtsi2ss
        | X86Opcode::Cvtss2si
        | X86Opcode::Cvttss2si => 6,
        X86Opcode::Cvtsd2ss | X86Opcode::Cvtss2sd => 5,

        // SETcc r/m8 is 3 bytes, plus one REX byte for R8-R15 or SPL/BPL/SIL/DIL.
        X86Opcode::Setcc => 4,

        // CMOVcc r64/r32, r64/r32: optional REX + 0F 4x + ModRM.
        X86Opcode::Cmovcc | X86Opcode::Cmovcc32 => 4,

        // MOVZX r64, r/m8 and MOVZX r64, r/m16 are 4 bytes in this encoder.
        X86Opcode::Movzx | X86Opcode::MovzxW => 4,

        // Default conservative estimate.
        _ => 7,
    }
}

/// Validate the construction-friendly x86 block map at every whole-function
/// boundary before passes are allowed to skip missing blocks or emit a block
/// more than once. `block_order` is the executable layout. CFG cleanup may
/// retain unreachable entries in the construction map, so the layout need not
/// be an exact permutation of `blocks`; instead, it must begin at the
/// conventional entry block and be closed under every executable CFG edge,
/// branch operand, and EH transfer. Omitted map entries are therefore harmless
/// unreachable shells, never hidden executable code.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum X86CfgValidationStage {
    /// Branch operands are symbolic and successors are about to become
    /// regalloc/TV-5 authority, so require an exact semantic CFG match.
    SymbolicAuthority,
    /// A known internal post-resolution funnel has replaced Block operands
    /// with displacements after the symbolic-authority check already passed.
    ResolvedEncoding,
}

fn validate_x86_function_layout_impl(
    func: &X86ISelFunction,
    cfg_stage: X86CfgValidationStage,
) -> Result<(), X86PipelineError> {
    let malformed = |detail: String| X86PipelineError::MalformedFunction {
        function: func.name.clone(),
        detail,
    };
    let mut has_symbolic_branch = false;
    let mut has_resolved_branch = false;

    let entry = LirBlock(0);
    if !func.blocks.contains_key(&entry) {
        return Err(malformed(format!(
            "entry block {:?} is absent from the block map",
            entry
        )));
    }
    if func.block_order.first().copied() != Some(entry) {
        return Err(malformed(format!(
            "block_order must start with entry block {:?}, got {:?}",
            entry,
            func.block_order.first()
        )));
    }

    let mut seen = HashSet::with_capacity(func.block_order.len());
    for &block_id in &func.block_order {
        if !func.blocks.contains_key(&block_id) {
            return Err(malformed(format!(
                "block_order contains block {:?} absent from the block map",
                block_id
            )));
        }
        if !seen.insert(block_id) {
            return Err(malformed(format!(
                "block_order duplicates block {:?}",
                block_id
            )));
        }
    }

    for (&block_id, block) in &func.blocks {
        let is_laid_out = seen.contains(&block_id);
        for &successor in &block.successors {
            if !func.blocks.contains_key(&successor) {
                return Err(malformed(format!(
                    "block {:?} has invalid successor target {:?}",
                    block_id, successor
                )));
            }
            if is_laid_out && !seen.contains(&successor) {
                return Err(malformed(format!(
                    "laid-out block {:?} has successor {:?} absent from block_order",
                    block_id, successor
                )));
            }
        }
        for (inst_index, inst) in block.insts.iter().enumerate() {
            if is_laid_out && matches!(inst.opcode, X86Opcode::Jmp | X86Opcode::Jcc) {
                let has_block_target = inst
                    .operands
                    .iter()
                    .any(|operand| matches!(operand, X86ISelOperand::Block(_)));
                let has_immediate = inst
                    .operands
                    .iter()
                    .any(|operand| matches!(operand, X86ISelOperand::Imm(_)));
                has_symbolic_branch |= has_block_target;
                if !has_block_target && has_immediate {
                    has_resolved_branch = true;
                    if cfg_stage == X86CfgValidationStage::SymbolicAuthority {
                        return Err(malformed(format!(
                            "block {:?} instruction {} carries a resolved branch immediate before the symbolic CFG authority boundary",
                            block_id, inst_index
                        )));
                    }
                }
            }
            for (operand_index, operand) in inst.operands.iter().enumerate() {
                if let X86ISelOperand::Block(target) = operand {
                    if !func.blocks.contains_key(target) {
                        return Err(malformed(format!(
                            "block {:?} instruction {} operand {} has invalid block target {:?}",
                            block_id, inst_index, operand_index, target
                        )));
                    }
                    if is_laid_out && !seen.contains(target) {
                        return Err(malformed(format!(
                            "laid-out block {:?} instruction {} operand {} targets {:?}, which is absent from block_order",
                            block_id, inst_index, operand_index, target
                        )));
                    }
                }
            }
        }
    }
    for landing_pad in &func.eh_info.landing_pads {
        if !func.blocks.contains_key(&landing_pad.block) {
            return Err(malformed(format!(
                "exception landing pad has invalid block target {:?}",
                landing_pad.block
            )));
        }
        if !seen.contains(&landing_pad.block) {
            return Err(malformed(format!(
                "exception landing pad targets block {:?}, which is absent from block_order",
                landing_pad.block
            )));
        }
    }
    for call_site in &func.eh_info.call_sites {
        if !func.blocks.contains_key(&call_site.call_block) {
            return Err(malformed(format!(
                "exception call site has invalid call block {:?}",
                call_site.call_block
            )));
        }
        if !seen.contains(&call_site.call_block) {
            return Err(malformed(format!(
                "exception call site uses block {:?}, which is absent from block_order",
                call_site.call_block
            )));
        }
        if !func.blocks.contains_key(&call_site.landing_pad_block) {
            return Err(malformed(format!(
                "exception call site has invalid landing-pad block {:?}",
                call_site.landing_pad_block
            )));
        }
        if !seen.contains(&call_site.landing_pad_block) {
            return Err(malformed(format!(
                "exception call site targets landing-pad block {:?}, which is absent from block_order",
                call_site.landing_pad_block
            )));
        }
    }

    if cfg_stage == X86CfgValidationStage::ResolvedEncoding
        && has_symbolic_branch
        && has_resolved_branch
    {
        return Err(malformed(
            "post-resolution branch stream mixes symbolic Block targets with resolved immediates"
                .to_string(),
        ));
    }

    if cfg_stage == X86CfgValidationStage::SymbolicAuthority || !has_resolved_branch {
        let mut expected: HashMap<LirBlock, HashSet<LirBlock>> = func
            .block_order
            .iter()
            .copied()
            .map(|block| (block, HashSet::new()))
            .collect();
        for (layout_index, &block_id) in func.block_order.iter().enumerate() {
            let block = &func.blocks[&block_id];
            for inst in &block.insts {
                if matches!(inst.opcode, X86Opcode::Jmp | X86Opcode::Jcc) {
                    for operand in &inst.operands {
                        if let X86ISelOperand::Block(target) = operand {
                            expected.get_mut(&block_id).unwrap().insert(*target);
                        }
                    }
                }
                // An indirect jump-table dispatch (JmpR) carries no Block operand;
                // its control edges are the DISTINCT targets of the jump table its
                // LeaRip references (the dense value->block map is proven by the
                // #62 gate `check_jump_table_preserved` in the ISel). Cross-check
                // the block's successor metadata against that authoritative set.
                if inst.opcode == X86Opcode::JmpR {
                    let jt_idx = block.insts.iter().find_map(|i| {
                        if i.opcode == X86Opcode::LeaRip {
                            i.operands.iter().find_map(|op| match op {
                                X86ISelOperand::JumpTableIndex(idx) => Some(*idx),
                                _ => None,
                            })
                        } else {
                            None
                        }
                    });
                    if let Some(idx) = jt_idx
                        && let Some(jt) = func.jump_tables.get(idx as usize)
                    {
                        for &tgt in &jt.targets {
                            expected.get_mut(&block_id).unwrap().insert(tgt);
                        }
                    }
                }
            }
            let hard_terminator = block
                .insts
                .iter()
                .rev()
                .find(|inst| !inst.opcode.is_pseudo())
                .is_some_and(|inst| {
                    matches!(
                        inst.opcode,
                        X86Opcode::Jmp | X86Opcode::Ret | X86Opcode::Ud2 | X86Opcode::JmpR
                    )
                });
            if !hard_terminator && let Some(&fallthrough) = func.block_order.get(layout_index + 1) {
                expected.get_mut(&block_id).unwrap().insert(fallthrough);
            }
        }
        for call_site in &func.eh_info.call_sites {
            expected
                .get_mut(&call_site.call_block)
                .unwrap()
                .insert(call_site.landing_pad_block);
        }
        for &block_id in &func.block_order {
            let block = &func.blocks[&block_id];
            let actual: HashSet<_> = block.successors.iter().copied().collect();
            if actual.len() != block.successors.len() {
                return Err(malformed(format!(
                    "block {:?} contains duplicate successor metadata: {:?}",
                    block_id, block.successors
                )));
            }
            if actual != expected[&block_id] {
                return Err(malformed(format!(
                    "block {:?} successor metadata {:?} does not match semantic control edges {:?}",
                    block_id, actual, expected[&block_id]
                )));
            }
        }
    }

    Ok(())
}

fn validate_x86_function_layout(func: &X86ISelFunction) -> Result<(), X86PipelineError> {
    validate_x86_function_layout_impl(func, X86CfgValidationStage::SymbolicAuthority)
}

fn validate_x86_resolved_function_layout(func: &X86ISelFunction) -> Result<(), X86PipelineError> {
    validate_x86_function_layout_impl(func, X86CfgValidationStage::ResolvedEncoding)
}

/// Resolve block operands in branch instructions to byte offsets.
///
/// x86-64 branches use PC-relative offsets where the offset is relative
/// to the end of the branch instruction itself (i.e., the start of the
/// next instruction).
fn resolve_x86_branches(func: &mut X86ISelFunction) {
    use trust_cg_lower::instructions::Block;

    // Phase 1: Compute byte offset of each block.
    let mut block_offsets: HashMap<Block, i64> = HashMap::new();
    let mut current_offset: i64 = 0;

    for &block_id in &func.block_order {
        block_offsets.insert(block_id, current_offset);
        if let Some(mblock) = func.blocks.get(&block_id) {
            for inst in &mblock.insts {
                current_offset += estimate_inst_size(inst) as i64;
            }
        }
    }

    // Phase 2: Replace Block operands with Imm offsets.
    // For each branch, compute the PC-relative offset from the end of
    // the branch instruction to the target block.
    let block_order = func.block_order.clone();
    for &block_id in &block_order {
        let mut inst_offset: i64 = *block_offsets.get(&block_id).unwrap_or(&0);

        if let Some(mblock) = func.blocks.get_mut(&block_id) {
            for inst in &mut mblock.insts {
                let inst_size = estimate_inst_size(inst) as i64;

                let is_branch = matches!(inst.opcode, X86Opcode::Jmp | X86Opcode::Jcc);

                if is_branch {
                    // The offset for x86-64 branches is relative to the
                    // instruction *after* the branch (i.e., inst_offset + inst_size).
                    let branch_end = inst_offset + inst_size;

                    inst.operands = inst
                        .operands
                        .iter()
                        .map(|op| {
                            if let X86ISelOperand::Block(target_block) = op {
                                if let Some(&target_offset) = block_offsets.get(target_block) {
                                    let rel_offset = target_offset - branch_end;
                                    X86ISelOperand::Imm(rel_offset)
                                } else {
                                    op.clone()
                                }
                            } else {
                                op.clone()
                            }
                        })
                        .collect();
                }

                inst_offset += inst_size;
            }
        }
    }
}

// ---------------------------------------------------------------------------
// X86Pipeline — main entry point
// ---------------------------------------------------------------------------

#[cfg(all(target_arch = "x86_64", target_os = "windows"))]
const X86_64_JIT_PROFILE_COUNTER_TRAMPOLINE_BYTES: usize = 14;
#[cfg(not(all(target_arch = "x86_64", target_os = "windows")))]
const X86_64_JIT_PROFILE_COUNTER_TRAMPOLINE_BYTES: usize = 18;

fn emit_x86_64_jit_profile_counter_trampoline(code: &mut Vec<u8>) -> usize {
    let start = code.len();
    #[cfg(all(target_arch = "x86_64", target_os = "windows"))]
    {
        code.extend_from_slice(&[0x49, 0xBA]);
        let imm64_offset = code.len();
        code.extend_from_slice(&[0u8; 8]);
        code.extend_from_slice(&[0xF0, 0x49, 0xFF, 0x02]);
        debug_assert_eq!(
            code.len() - start,
            X86_64_JIT_PROFILE_COUNTER_TRAMPOLINE_BYTES
        );
        imm64_offset
    }

    #[cfg(not(all(target_arch = "x86_64", target_os = "windows")))]
    {
        code.extend_from_slice(&[0x50, 0x9C, 0x48, 0xB8]);
        let imm64_offset = code.len();
        code.extend_from_slice(&[0u8; 8]);
        code.extend_from_slice(&[0xF0, 0x48, 0xFF, 0x00, 0x9D, 0x58]);
        debug_assert_eq!(
            code.len() - start,
            X86_64_JIT_PROFILE_COUNTER_TRAMPOLINE_BYTES
        );
        imm64_offset
    }
}

fn collect_x86_branch_targets(func: &X86ISelFunction) -> HashMap<(LirBlock, usize), LirBlock> {
    let mut targets = HashMap::new();
    for &block_id in &func.block_order {
        if let Some(mblock) = func.blocks.get(&block_id) {
            for (inst_idx, inst) in mblock.insts.iter().enumerate() {
                if !matches!(inst.opcode, X86Opcode::Jmp | X86Opcode::Jcc) {
                    continue;
                }
                if let Some(target) = inst.operands.iter().find_map(|op| {
                    if let X86ISelOperand::Block(target) = op {
                        Some(*target)
                    } else {
                        None
                    }
                }) {
                    targets.insert((block_id, inst_idx), target);
                }
            }
        }
    }
    targets
}

fn x86_block_offset(
    block_offsets: &HashMap<LirBlock, usize>,
    block: LirBlock,
    purpose: &str,
) -> Result<usize, X86PipelineError> {
    block_offsets.get(&block).copied().ok_or_else(|| {
        X86PipelineError::ConstantPool(format!(
            "x86 block profiling: block {:?} missing byte offset while {}",
            block, purpose
        ))
    })
}

fn x86_block_shift_for_offset(
    block_order: &[LirBlock],
    block_offsets: &HashMap<LirBlock, usize>,
    code_len: usize,
    offset: usize,
) -> Result<usize, X86PipelineError> {
    for (idx, &block) in block_order.iter().enumerate() {
        let start = x86_block_offset(block_offsets, block, "shifting fixup")?;
        let end = if idx + 1 < block_order.len() {
            x86_block_offset(block_offsets, block_order[idx + 1], "shifting fixup")?
        } else {
            code_len
        };
        if offset >= start && offset < end {
            return Ok((idx + 1) * X86_64_JIT_PROFILE_COUNTER_TRAMPOLINE_BYTES);
        }
    }
    Err(X86PipelineError::ConstantPool(format!(
        "x86 block profiling: byte offset {} is outside function body length {}",
        offset, code_len
    )))
}

fn patch_x86_rel32(
    code: &mut [u8],
    disp32_offset: usize,
    target: usize,
) -> Result<(), X86PipelineError> {
    if disp32_offset + 4 > code.len() {
        return Err(X86PipelineError::ConstantPool(format!(
            "x86 block profiling: rel32 patch site {} outside code length {}",
            disp32_offset,
            code.len()
        )));
    }
    let inst_end = disp32_offset + 4;
    let distance = target as i64 - inst_end as i64;
    if distance < i32::MIN as i64 || distance > i32::MAX as i64 {
        return Err(X86PipelineError::ConstantPool(format!(
            "x86 block profiling: rel32 target {} from patch site {} is out of range ({})",
            target, disp32_offset, distance
        )));
    }
    code[disp32_offset..disp32_offset + 4].copy_from_slice(&(distance as i32).to_le_bytes());
    Ok(())
}

fn patch_x86_branch_fixups_to_block_offsets(
    code: &mut [u8],
    block_offsets: &HashMap<LirBlock, usize>,
    branch_fixups: Vec<X86BranchFixup>,
) -> Result<(), X86PipelineError> {
    for branch in branch_fixups {
        let target = block_offsets.get(&branch.target).copied().ok_or_else(|| {
            X86PipelineError::ConstantPool(format!(
                "x86 branch resolution: target block {:?} missing byte offset",
                branch.target
            ))
        })?;
        patch_x86_rel32(code, branch.disp32_offset, target)?;
    }
    Ok(())
}

fn splice_x86_block_counter_trampolines(
    func: &X86ISelFunction,
    body_bytes: &[u8],
    block_offsets: &HashMap<LirBlock, usize>,
) -> Result<
    (
        Vec<u8>,
        Vec<X86BlockCounterPatchSite>,
        HashMap<LirBlock, usize>,
    ),
    X86PipelineError,
> {
    if func.block_order.is_empty() {
        return Err(X86PipelineError::ConstantPool(
            "x86 block profiling: empty block order".to_string(),
        ));
    }

    let tramp = X86_64_JIT_PROFILE_COUNTER_TRAMPOLINE_BYTES;
    let mut block_trampoline_starts = HashMap::with_capacity(func.block_order.len());
    for (idx, &block) in func.block_order.iter().enumerate() {
        let original = x86_block_offset(block_offsets, block, "computing trampoline start")?;
        block_trampoline_starts.insert(block, original + idx * tramp);
    }

    let mut out = Vec::with_capacity(body_bytes.len() + func.block_order.len() * tramp);
    let mut patch_sites = Vec::with_capacity(func.block_order.len());
    for (idx, &block) in func.block_order.iter().enumerate() {
        let start = x86_block_offset(block_offsets, block, "copying block body")?;
        let end = if idx + 1 < func.block_order.len() {
            x86_block_offset(
                block_offsets,
                func.block_order[idx + 1],
                "copying block body",
            )?
        } else {
            body_bytes.len()
        };
        if start > end || end > body_bytes.len() {
            return Err(X86PipelineError::ConstantPool(format!(
                "x86 block profiling: block {:?} byte range {}..{} outside body length {}",
                block,
                start,
                end,
                body_bytes.len()
            )));
        }

        let imm64_offset = emit_x86_64_jit_profile_counter_trampoline(&mut out);
        patch_sites.push(X86BlockCounterPatchSite {
            block,
            imm64_offset,
        });
        let expected_trampoline_start =
            block_trampoline_starts
                .get(&block)
                .copied()
                .ok_or_else(|| {
                    X86PipelineError::ConstantPool(format!(
                        "x86 block profiling: missing computed trampoline start for block {:?}",
                        block
                    ))
                })?;
        debug_assert_eq!(out.len() - tramp, expected_trampoline_start);
        out.extend_from_slice(&body_bytes[start..end]);
    }

    Ok((out, patch_sites, block_trampoline_starts))
}

/// Output format for the x86-64 pipeline.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum X86OutputFormat {
    /// Raw machine code bytes (no object file wrapper).
    RawBytes,
    /// ELF .o object file (for Linux/BSD).
    Elf,
    /// Mach-O .o object file (for macOS).
    MachO,
    /// COFF .obj object file (for Windows).
    Coff,
}

/// Configuration for the x86-64 pipeline.
#[derive(Debug, Clone)]
pub struct X86PipelineConfig {
    /// x86 optimization level used before register allocation.
    pub opt_level: trust_cg_opt::OptLevel,
    /// Output format: raw bytes, ELF, Mach-O, or COFF.
    pub output_format: X86OutputFormat,
    /// Whether to emit an ELF .o wrapper (vs raw code bytes).
    /// Deprecated: use `output_format` instead.
    pub emit_elf: bool,
    /// Whether to emit prologue/epilogue (false for leaf functions that
    /// don't need a frame).
    pub emit_frame: bool,
    /// Register allocation mode (default: Full(Greedy)).
    ///
    /// - `Simplified`: fast first-appearance allocation, no spill support.
    ///   Use for O0 or trivial test functions.
    /// - `Full(LinearScan)`: full pipeline with linear scan allocator.
    /// - `Full(Greedy)`: full pipeline with LLVM-style greedy allocator
    ///   (default — same as AArch64 pipeline).
    pub regalloc_mode: X86RegAllocMode,
    /// C ABI used for x86-64 formal arguments, calls, and callee-saved policy.
    pub call_abi: X86CallAbi,
    /// Target features admitted by the x86-64 opcode gate.
    pub target_features: X86TargetFeatures,
    /// Whole-program `panic=unwind` mode (FUZZ-7 / EH Lane 5, cross-object).
    ///
    /// When true, the Mach-O emitter extends EH Lane 5 (all-filler walkable FDE
    /// coverage) to EVERY frame-covered object — not just objects carrying a
    /// local exception-handling function — so a panic can unwind through
    /// pass-through frames (`lang_start` closure, `rust_begin_short_backtrace`,
    /// `main`) that live in objects with no local landing pad. Read ONLY inside
    /// the `X86OutputFormat::MachO` arms; false keeps the object byte-identical.
    pub panic_unwind: bool,
}

impl Default for X86PipelineConfig {
    fn default() -> Self {
        Self {
            opt_level: trust_cg_opt::OptLevel::O2,
            output_format: X86OutputFormat::RawBytes,
            emit_elf: false,
            emit_frame: true,
            regalloc_mode: X86RegAllocMode::Full(AllocStrategy::Greedy),
            call_abi: X86CallAbi::SystemV,
            target_features: X86TargetFeatures::default(),
            panic_unwind: false,
        }
    }
}

impl X86PipelineConfig {
    /// Current Trust Codegen x86-64 profile used by default host/current pipelines.
    pub fn current() -> Self {
        Self::default()
    }

    /// Runtime-detected host profile for in-process x86-64 JIT execution.
    pub fn host_jit() -> Self {
        Self {
            target_features: X86TargetFeatures::host(),
            ..Self::default()
        }
    }

    /// JIT-8: latency-tuned host JIT profile.
    ///
    /// Same as [`host_jit`](Self::host_jit) but drives the **LinearScan**
    /// allocator core instead of Greedy. LinearScan sidesteps the greedy
    /// allocator's eviction / live-range-splitting / interference-query cost, so
    /// JIT-compile latency drops toward the aarch64 `jit_fast` numbers
    /// (measured ~11% lower total JIT-compile time on the uuf50-218 BCP kernel).
    ///
    /// This is a latency/code-quality trade only: the always-on regalloc
    /// translation validator ([`trust_cg_regalloc::allocate`]) proves the
    /// resulting allocation equivalent to the SSA input, so a lower-quality
    /// allocation fails closed rather than miscompiling, and the JIT-5
    /// CachedVerified cert path still covers every emitted byte. The production
    /// JIT ([`crate::CompilerConfig::for_host_jit`]) selects this when
    /// `enable_jit_fast_regalloc` is set; `TCG_NO_X86_JIT_LINEARSCAN` forces the
    /// previous [`host_jit`](Self::host_jit) Greedy profile.
    ///
    /// Coalescing is deliberately left ON (unlike the aarch64
    /// [`AllocConfig::jit_latency_aarch64`](trust_cg_regalloc::AllocConfig::jit_latency_aarch64)
    /// profile, which turns it off): this matches the already-tested x86
    /// LinearScan config, and turning coalescing off raises register pressure,
    /// which on x86 pushes high-pressure vector functions past the spill-replay
    /// scratch budget without any net latency gain. The JIT compile path pairs
    /// this profile with a Greedy fallback for exactly those functions
    /// LinearScan cannot allocate within the x86 spill-replay budget, so
    /// completeness is preserved.
    pub fn host_jit_fast() -> Self {
        Self {
            regalloc_mode: X86RegAllocMode::Full(AllocStrategy::LinearScan),
            ..Self::host_jit()
        }
    }

    /// Generic x86-64 profile with optional SSE4.x opcodes disabled.
    pub fn generic_x86_64() -> Self {
        Self {
            target_features: X86TargetFeatures::generic_x86_64(),
            ..Self::default()
        }
    }
}

/// Maximum O3 x86 optimization fixpoint iterations.
///
/// This mirrors the AArch64 optimization pipeline cap and bounds compile time
/// while still allowing local x86 cleanup passes to expose follow-on wins.
const TCG_X86_O3_FIXPOINT_MAX_ITERATIONS: u32 = 4;

/// Run the x86 CEGIS superoptimization pass iff the `TCG_CEGIS_X86` gate is set.
///
/// Default OFF: with the gate unset this reads the env once and returns without
/// touching `func`, so the pipeline output is byte-identical to a build without
/// CEGIS. When enabled, the pass only commits QF_BV-proven-equivalent rewrites
/// (`trust_cg_verify::CegisLoop::verify` == `Equivalent`) and otherwise leaves
/// instructions untouched (fail-closed). Requires the `verify` feature (which
/// is on by default for this crate).
#[cfg(feature = "verify")]
fn run_x86_cegis_superopt_if_enabled(func: &mut X86ISelFunction) {
    let config = trust_cg_verify::X86CegisSuperoptConfig::from_env();
    if !config.is_enabled() {
        return;
    }
    let mut pass = trust_cg_verify::X86CegisSuperoptPass::new(config);
    let _ = pass.run(func);
}

#[cfg(not(feature = "verify"))]
fn run_x86_cegis_superopt_if_enabled(_func: &mut X86ISelFunction) {}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum X86RegBank {
    Gpr,
    Xmm,
}

fn x86_reg_bank_for_class(class: RegClass) -> Option<X86RegBank> {
    match class {
        RegClass::Gpr64 | RegClass::Gpr32 | RegClass::System => Some(X86RegBank::Gpr),
        RegClass::Fpr128 | RegClass::Fpr64 | RegClass::Fpr32 => Some(X86RegBank::Xmm),
        RegClass::Fpr16 | RegClass::Fpr8 => None,
    }
}

fn x86_regalloc_inst_unchanged(lhs: &RegAllocInst, rhs: &RegAllocInst) -> bool {
    lhs.opcode == rhs.opcode
        && lhs.defs == rhs.defs
        && lhs.uses == rhs.uses
        && lhs.implicit_defs == rhs.implicit_defs
        && lhs.implicit_uses == rhs.implicit_uses
        && lhs.flags == rhs.flags
}

fn x86_regalloc_inserted_inst_looks_like_remat(
    before: &RegAllocFunction,
    inserted: &RegAllocInst,
) -> bool {
    let remat_cost = trust_cg_regalloc::classify_remat_cost(inserted);
    if !matches!(
        remat_cost,
        trust_cg_regalloc::RematCost::Free | trust_cg_regalloc::RematCost::Cheap
    ) || inserted.vreg_defs().next().is_none()
    {
        return false;
    }

    before
        .insts
        .iter()
        .any(|candidate| x86_regalloc_inst_unchanged(candidate, inserted))
}

fn x86_regalloc_stack_slots_unchanged_except_spills(
    before: &RegAllocFunction,
    after: &RegAllocFunction,
    reported_spill_slots: &HashSet<StackSlotId>,
) -> bool {
    before.stack_slots.iter().all(|(slot_id, before_slot)| {
        after.stack_slots.get(slot_id).is_some_and(|after_slot| {
            before_slot.size == after_slot.size
                && before_slot.align == after_slot.align
                && before_slot.allocation == after_slot.allocation
        })
    }) && after.stack_slots.keys().all(|slot_id| {
        before.stack_slots.contains_key(slot_id) || reported_spill_slots.contains(slot_id)
    })
}

fn x86_pseudo_copy_vreg_operand(
    operand: Option<&RegAllocOperand>,
    role: &str,
) -> Result<VReg, X86PipelineError> {
    match operand {
        Some(RegAllocOperand::VReg(vreg)) => Ok(*vreg),
        other => Err(X86PipelineError::RegAlloc(format!(
            "x86-64 PSEUDO_COPY replay expected {role} VReg operand, got {other:?}"
        ))),
    }
}

fn x86_split_copy_opcode(dst: VReg, src: VReg) -> Result<X86Opcode, X86PipelineError> {
    if x86_reg_bank_for_class(dst.class) != x86_reg_bank_for_class(src.class) {
        return Err(X86PipelineError::RegAlloc(format!(
            "x86-64 PSEUDO_COPY replay cannot copy between {:?} and {:?}",
            src.class, dst.class
        )));
    }

    match dst.class {
        RegClass::Gpr32 => Ok(X86Opcode::MovRR32),
        RegClass::Gpr64 | RegClass::System => Ok(X86Opcode::MovRR),
        RegClass::Fpr32 => Ok(X86Opcode::MovssRR),
        RegClass::Fpr64 => Ok(X86Opcode::MovsdRR),
        RegClass::Fpr128 => Ok(X86Opcode::MovdqaRR),
        RegClass::Fpr16 | RegClass::Fpr8 => Err(X86PipelineError::RegAlloc(format!(
            "x86-64 PSEUDO_COPY replay does not support {:?} values",
            dst.class
        ))),
    }
}

fn x86_isel_copy_like_vregs(inst: &X86ISelInst) -> Option<(VReg, VReg)> {
    let [X86ISelOperand::VReg(dst), X86ISelOperand::VReg(src)] = inst.operands.as_slice() else {
        return None;
    };
    if dst.class != src.class {
        return None;
    }

    let supported = matches!(
        (inst.opcode, dst.class),
        (X86Opcode::MovRR, RegClass::Gpr64 | RegClass::System)
            | (X86Opcode::MovRR32, RegClass::Gpr32)
            | (X86Opcode::MovssRR, RegClass::Fpr32)
            | (X86Opcode::MovsdRR, RegClass::Fpr64)
            | (X86Opcode::MovdqaRR, RegClass::Fpr128)
    );
    supported.then_some((*dst, *src))
}

fn x86_regalloc_opcode_for_isel_inst(inst: &X86ISelInst) -> u16 {
    if x86_isel_copy_like_vregs(inst).is_some() {
        trust_cg_regalloc::phi_elim::PSEUDO_COPY
    } else {
        inst.opcode as u16
    }
}

fn x86_pseudo_copy_to_isel(inst: &RegAllocInst) -> Result<X86ISelInst, X86PipelineError> {
    if inst.opcode != trust_cg_regalloc::phi_elim::PSEUDO_COPY {
        return Err(X86PipelineError::RegAlloc(format!(
            "x86-64 split replay expected PSEUDO_COPY, got opcode {}",
            inst.opcode
        )));
    }
    if inst.defs.len() != 1 || inst.uses.len() != 1 {
        return Err(X86PipelineError::RegAlloc(format!(
            "x86-64 PSEUDO_COPY replay expected one def and one use, got {} defs and {} uses",
            inst.defs.len(),
            inst.uses.len()
        )));
    }

    let dst = x86_pseudo_copy_vreg_operand(inst.defs.first(), "destination")?;
    let src = x86_pseudo_copy_vreg_operand(inst.uses.first(), "source")?;
    Ok(X86ISelInst::new(
        x86_split_copy_opcode(dst, src)?,
        vec![X86ISelOperand::VReg(dst), X86ISelOperand::VReg(src)],
    ))
}

fn x86_regalloc_dead_fresh_copy_vregs(
    before: &RegAllocFunction,
    after: &RegAllocFunction,
) -> HashSet<VReg> {
    if after.next_vreg <= before.next_vreg {
        return HashSet::new();
    }

    let fresh_start = before.next_vreg;
    let fresh_end = after.next_vreg;
    let mut copy_defined = HashSet::new();
    let mut copy_successors: HashMap<VReg, Vec<VReg>> = HashMap::new();
    let mut non_copy_referenced = HashSet::new();

    for inst in &after.insts {
        let is_pseudo_copy = inst.opcode == trust_cg_regalloc::phi_elim::PSEUDO_COPY;
        if is_pseudo_copy
            && let (Some(dst), Some(src)) = (
                inst.defs.first().and_then(x86_regalloc_operand_vreg),
                inst.uses.first().and_then(x86_regalloc_operand_vreg),
            )
            && (fresh_start..fresh_end).contains(&dst.id)
            && (fresh_start..fresh_end).contains(&src.id)
        {
            copy_successors.entry(src).or_default().push(dst);
        }
        for vreg in inst.vreg_defs() {
            if (fresh_start..fresh_end).contains(&vreg.id) && is_pseudo_copy {
                copy_defined.insert(vreg);
            }
        }
        for vreg in inst.vreg_uses() {
            if !is_pseudo_copy && (fresh_start..fresh_end).contains(&vreg.id) {
                non_copy_referenced.insert(vreg);
            }
        }
    }

    let mut dead = HashSet::new();
    for vreg in copy_defined {
        if !x86_fresh_vreg_reaches_non_copy_reference(vreg, &copy_successors, &non_copy_referenced)
        {
            dead.insert(vreg);
        }
    }

    dead
}

fn x86_fresh_vreg_reaches_non_copy_reference(
    vreg: VReg,
    copy_successors: &HashMap<VReg, Vec<VReg>>,
    non_copy_referenced: &HashSet<VReg>,
) -> bool {
    let mut stack = vec![vreg];
    let mut seen = HashSet::new();

    while let Some(current) = stack.pop() {
        if non_copy_referenced.contains(&current) {
            return true;
        }
        if !seen.insert(current) {
            continue;
        }
        if let Some(successors) = copy_successors.get(&current) {
            stack.extend(successors.iter().copied());
        }
    }

    false
}

fn x86_regalloc_operand_vreg(operand: &RegAllocOperand) -> Option<VReg> {
    match operand {
        RegAllocOperand::VReg(vreg) => Some(*vreg),
        _ => None,
    }
}

struct X86RegAllocOperandCursor<'a> {
    before: &'a [RegAllocOperand],
    after: &'a [RegAllocOperand],
    next: usize,
    role: &'static str,
}

impl<'a> X86RegAllocOperandCursor<'a> {
    fn new(
        before: &'a [RegAllocOperand],
        after: &'a [RegAllocOperand],
        role: &'static str,
    ) -> Self {
        Self {
            before,
            after,
            next: 0,
            role,
        }
    }

    fn consume_exact(&mut self, expected: RegAllocOperand) -> Result<(), X86PipelineError> {
        let before = self.before.get(self.next).ok_or_else(|| {
            X86PipelineError::RegAlloc(format!(
                "x86-64 replay expected {} operand {:?}, but the regalloc stream ended",
                self.role, expected
            ))
        })?;
        let after = self.after.get(self.next).ok_or_else(|| {
            X86PipelineError::RegAlloc(format!(
                "x86-64 replay missing rewritten {} operand {}",
                self.role, self.next
            ))
        })?;
        self.next += 1;

        if *before != expected || after != before {
            return Err(X86PipelineError::RegAlloc(format!(
                "x86-64 regalloc mutated a non-register {} operand from {:?} to {:?}",
                self.role, before, after
            )));
        }

        Ok(())
    }

    fn consume_vreg(&mut self, expected: VReg) -> Result<VReg, X86PipelineError> {
        let before = self.before.get(self.next).ok_or_else(|| {
            X86PipelineError::RegAlloc(format!(
                "x86-64 replay expected {} VReg operand {:?}, but the regalloc stream ended",
                self.role, expected
            ))
        })?;
        let after = self.after.get(self.next).ok_or_else(|| {
            X86PipelineError::RegAlloc(format!(
                "x86-64 replay missing rewritten {} operand {}",
                self.role, self.next
            ))
        })?;
        self.next += 1;

        let Some(before_vreg) = x86_regalloc_operand_vreg(before) else {
            return Err(X86PipelineError::RegAlloc(format!(
                "x86-64 replay expected {} VReg {:?}, got {:?}",
                self.role, expected, before
            )));
        };
        if before_vreg != expected {
            return Err(X86PipelineError::RegAlloc(format!(
                "x86-64 replay {} operand mismatch: x86 has {:?}, regalloc has {:?}",
                self.role, expected, before_vreg
            )));
        }

        let Some(after_vreg) = x86_regalloc_operand_vreg(after) else {
            return Err(X86PipelineError::RegAlloc(format!(
                "x86-64 replay cannot rewrite {} VReg {:?} to non-VReg {:?}",
                self.role, expected, after
            )));
        };
        if after_vreg.class != expected.class {
            return Err(X86PipelineError::RegAlloc(format!(
                "x86-64 replay cannot rewrite {:?} to different class {:?}",
                expected, after_vreg
            )));
        }

        Ok(after_vreg)
    }

    fn finish(&self) -> Result<(), X86PipelineError> {
        if self.next != self.before.len() || self.next != self.after.len() {
            return Err(X86PipelineError::RegAlloc(format!(
                "x86-64 replay did not consume all {} operands: consumed {}, before has {}, after has {}",
                self.role,
                self.next,
                self.before.len(),
                self.after.len()
            )));
        }
        Ok(())
    }
}

fn x86_replay_memaddr_operand_rewrite(
    base: &mut Box<X86ISelOperand>,
    disp: i32,
    uses: &mut X86RegAllocOperandCursor<'_>,
) -> Result<(), X86PipelineError> {
    match base.as_mut() {
        X86ISelOperand::VReg(vreg) => {
            *vreg = uses.consume_vreg(*vreg)?;
        }
        X86ISelOperand::StackSlot(slot) => {
            uses.consume_exact(RegAllocOperand::StackSlot(StackSlotId(*slot)))?;
        }
        X86ISelOperand::PReg(_) => {}
        _ => {}
    }
    uses.consume_exact(RegAllocOperand::Imm(i64::from(disp)))?;
    Ok(())
}

fn x86_replay_sib_memaddr_operand_rewrite(
    base: &mut Box<X86ISelOperand>,
    index: &mut Box<X86ISelOperand>,
    scale: u8,
    disp: i32,
    uses: &mut X86RegAllocOperandCursor<'_>,
) -> Result<(), X86PipelineError> {
    x86_replay_memaddr_operand_rewrite(base, disp, uses)?;
    match index.as_mut() {
        X86ISelOperand::VReg(vreg) => {
            *vreg = uses.consume_vreg(*vreg)?;
        }
        X86ISelOperand::StackSlot(slot) => {
            uses.consume_exact(RegAllocOperand::StackSlot(StackSlotId(*slot)))?;
        }
        X86ISelOperand::PReg(_) => {}
        _ => {}
    }
    uses.consume_exact(RegAllocOperand::Imm(i64::from(scale)))?;
    Ok(())
}

fn x86_pseudo_copy_dst(inst: &RegAllocInst) -> Option<VReg> {
    if inst.opcode != trust_cg_regalloc::phi_elim::PSEUDO_COPY {
        return None;
    }
    inst.defs.first().and_then(x86_regalloc_operand_vreg)
}

fn x86_validate_removed_original_copy(
    original: &X86ISelInst,
    before: &RegAllocInst,
) -> Result<(), X86PipelineError> {
    if before.opcode != trust_cg_regalloc::phi_elim::PSEUDO_COPY {
        return Err(X86PipelineError::RegAlloc(format!(
            "x86-64 regalloc removed unsupported opcode {} from the instruction stream; only safe copy-like x86 instructions can be replayed",
            before.opcode
        )));
    }
    if !before.implicit_defs.is_empty() || !before.implicit_uses.is_empty() {
        return Err(X86PipelineError::RegAlloc(
            "x86-64 regalloc removed a copy-like instruction with implicit operands; replay only supports plain VReg copies"
                .to_string(),
        ));
    }

    let Some((dst, src)) = x86_isel_copy_like_vregs(original) else {
        return Err(X86PipelineError::RegAlloc(format!(
            "x86-64 regalloc removed unsupported x86 instruction {:?}; replay only supports VReg-to-VReg MovRR/MovRR32/MovssRR/MovsdRR/MovdqaRR copies",
            original.opcode
        )));
    };
    if before.defs != [RegAllocOperand::VReg(dst)] || before.uses != [RegAllocOperand::VReg(src)] {
        return Err(X86PipelineError::RegAlloc(format!(
            "x86-64 regalloc removed copy {:?} with mismatched regalloc operands defs={:?} uses={:?}",
            original.opcode, before.defs, before.uses
        )));
    }

    Ok(())
}

fn x86_replay_existing_operand_rewrite(
    original: &X86ISelInst,
    before: &RegAllocInst,
    after: &RegAllocInst,
) -> Result<X86ISelInst, X86PipelineError> {
    if before.opcode != after.opcode
        || before.implicit_defs != after.implicit_defs
        || before.implicit_uses != after.implicit_uses
        || before.flags != after.flags
        || before.defs.len() != after.defs.len()
        || before.uses.len() != after.uses.len()
    {
        return Err(X86PipelineError::RegAlloc(
            "x86-64 regalloc mutated an existing instruction beyond operand VReg rewrites, but replay into the x86 instruction stream is not wired"
                .to_string(),
        ));
    }

    let mut rewritten = original.clone();
    let mut defs = X86RegAllocOperandCursor::new(&before.defs, &after.defs, "def");
    let mut uses = X86RegAllocOperandCursor::new(&before.uses, &after.uses, "use");

    for idx in 0..rewritten.operands.len() {
        let access = x86_operand_access(&rewritten, idx);
        match &mut rewritten.operands[idx] {
            X86ISelOperand::VReg(vreg) => {
                if access.is_def {
                    let def_vreg = defs.consume_vreg(*vreg)?;
                    if access.is_use {
                        let use_vreg = uses.consume_vreg(*vreg)?;
                        if def_vreg != use_vreg {
                            return Err(X86PipelineError::RegAlloc(format!(
                                "x86-64 replay cannot map one def-use operand to distinct VRegs {:?} and {:?}",
                                def_vreg, use_vreg
                            )));
                        }
                    }
                    *vreg = def_vreg;
                } else if access.is_use {
                    *vreg = uses.consume_vreg(*vreg)?;
                }
            }
            X86ISelOperand::PReg(_) => {}
            X86ISelOperand::Imm(imm) => {
                uses.consume_exact(RegAllocOperand::Imm(*imm))?;
            }
            X86ISelOperand::FImm(fimm) => {
                uses.consume_exact(RegAllocOperand::FImm(*fimm))?;
            }
            X86ISelOperand::Block(block) => {
                uses.consume_exact(RegAllocOperand::Block(BlockId(block.0)))?;
            }
            X86ISelOperand::CondCode(_) | X86ISelOperand::Symbol(_) => {
                uses.consume_exact(RegAllocOperand::Imm(0))?;
            }
            X86ISelOperand::StackSlot(slot) => {
                uses.consume_exact(RegAllocOperand::StackSlot(StackSlotId(*slot)))?;
            }
            X86ISelOperand::MemAddr { base, disp } => {
                x86_replay_memaddr_operand_rewrite(base, *disp, &mut uses)?;
            }
            X86ISelOperand::SibMemAddr {
                base,
                index,
                scale,
                disp,
            } => {
                x86_replay_sib_memaddr_operand_rewrite(base, index, *scale, *disp, &mut uses)?;
            }
            X86ISelOperand::ConstPoolEntry(idx) => {
                uses.consume_exact(RegAllocOperand::Imm(*idx as i64))?;
            }
            X86ISelOperand::JumpTableIndex(idx) => {
                // A compile-time table index, not a register — consumed as an
                // immediate use during regalloc replay, exactly like ConstPoolEntry.
                uses.consume_exact(RegAllocOperand::Imm(i64::from(*idx)))?;
            }
        }
    }

    defs.finish()?;
    uses.finish()?;
    Ok(rewritten)
}

fn replay_x86_regalloc_stream_mutations(
    func: &mut X86ISelFunction,
    before: &RegAllocFunction,
    after: &RegAllocFunction,
    reported_spill_slots: &HashSet<StackSlotId>,
) -> Result<(), X86PipelineError> {
    if before.block_order != after.block_order
        || before.entry_block != after.entry_block
        || before.blocks.len() != after.blocks.len()
    {
        return Err(X86PipelineError::RegAlloc(
            "x86-64 regalloc changed block topology, but replay into the x86 instruction stream is not wired"
                .to_string(),
        ));
    }

    if !x86_regalloc_stack_slots_unchanged_except_spills(before, after, reported_spill_slots) {
        return Err(X86PipelineError::RegAlloc(
            "x86-64 regalloc changed stack slots outside reported spills".to_string(),
        ));
    }

    let dead_fresh_copy_vregs = x86_regalloc_dead_fresh_copy_vregs(before, after);

    if func.block_order.len() != before.blocks.len() {
        return Err(X86PipelineError::RegAlloc(format!(
            "x86-64 regalloc replay block count mismatch: x86 has {}, regalloc has {}",
            func.block_order.len(),
            before.blocks.len()
        )));
    }

    let original_func = func.clone();

    for &block_id in &before.block_order {
        let block_idx = block_id.0 as usize;
        let before_block = before.blocks.get(block_idx).ok_or_else(|| {
            X86PipelineError::RegAlloc(format!(
                "x86-64 regalloc replay references missing before block {}",
                block_id.0
            ))
        })?;
        let after_block = after.blocks.get(block_idx).ok_or_else(|| {
            X86PipelineError::RegAlloc(format!(
                "x86-64 regalloc replay references missing after block {}",
                block_id.0
            ))
        })?;
        if before_block.preds != after_block.preds
            || before_block.succs != after_block.succs
            || before_block.loop_depth != after_block.loop_depth
        {
            return Err(X86PipelineError::RegAlloc(
                "x86-64 regalloc changed block metadata, but replay into the x86 instruction stream is not wired"
                .to_string(),
            ));
        }

        let x86_block_id = LirBlock(block_id.0);
        let original_x86_block = original_func.blocks.get(&x86_block_id).ok_or_else(|| {
            X86PipelineError::RegAlloc(format!(
                "x86-64 replay missing original block {}",
                x86_block_id.0
            ))
        })?;
        if original_x86_block.insts.len() != before_block.insts.len() {
            return Err(X86PipelineError::RegAlloc(format!(
                "x86-64 replay block {} length mismatch: x86 has {}, regalloc has {}",
                x86_block_id.0,
                original_x86_block.insts.len(),
                before_block.insts.len()
            )));
        }

        let mut next_before = 0usize;
        let mut replayed_insts = Vec::with_capacity(after_block.insts.len());
        for after_inst_id in &after_block.insts {
            let after_inst = after.insts.get(after_inst_id.0 as usize).ok_or_else(|| {
                X86PipelineError::RegAlloc(format!(
                    "x86-64 regalloc replay references missing instruction {}",
                    after_inst_id.0
                ))
            })?;

            if next_before < before_block.insts.len()
                && *after_inst_id != before_block.insts[next_before]
                && let Some(removed_count) = before_block.insts[next_before..]
                    .iter()
                    .position(|inst_id| inst_id == after_inst_id)
                && removed_count > 0
            {
                for removed_idx in next_before..next_before + removed_count {
                    let before_inst_id = before_block.insts[removed_idx];
                    let before_inst =
                        before.insts.get(before_inst_id.0 as usize).ok_or_else(|| {
                            X86PipelineError::RegAlloc(format!(
                                "x86-64 regalloc replay references missing removed instruction {}",
                                before_inst_id.0
                            ))
                        })?;
                    let original_inst = &original_x86_block.insts[removed_idx];
                    x86_validate_removed_original_copy(original_inst, before_inst)?;
                }
                next_before += removed_count;
            }

            if next_before < before_block.insts.len()
                && *after_inst_id == before_block.insts[next_before]
            {
                let before_inst_id = before_block.insts[next_before];
                let before_inst = before.insts.get(before_inst_id.0 as usize).ok_or_else(|| {
                    X86PipelineError::RegAlloc(format!(
                        "x86-64 regalloc replay references missing original instruction {}",
                        before_inst_id.0
                    ))
                })?;
                let original_inst = &original_x86_block.insts[next_before];
                if x86_regalloc_inst_unchanged(before_inst, after_inst) {
                    replayed_insts.push(original_inst.clone());
                } else {
                    replayed_insts.push(x86_replay_existing_operand_rewrite(
                        original_inst,
                        before_inst,
                        after_inst,
                    )?);
                }
                next_before += 1;
                continue;
            }

            if after_inst.opcode == trust_cg_regalloc::phi_elim::PSEUDO_COPY {
                if x86_pseudo_copy_dst(after_inst)
                    .is_some_and(|dst| dead_fresh_copy_vregs.contains(&dst))
                {
                    continue;
                }
                replayed_insts.push(x86_pseudo_copy_to_isel(after_inst)?);
                continue;
            }

            if x86_regalloc_inserted_inst_looks_like_remat(before, after_inst) {
                return Err(
                    X86PipelineError::RegAllocRematerializationReplayUnsupported {
                        opcode: after_inst.opcode,
                    },
                );
            }

            return Err(X86PipelineError::RegAlloc(format!(
                "x86-64 regalloc inserted unsupported opcode {} into the instruction stream",
                after_inst.opcode
            )));
        }

        while next_before < before_block.insts.len() {
            let before_inst_id = before_block.insts[next_before];
            let before_inst = before.insts.get(before_inst_id.0 as usize).ok_or_else(|| {
                X86PipelineError::RegAlloc(format!(
                    "x86-64 regalloc replay references missing removed instruction {}",
                    before_inst_id.0
                ))
            })?;
            let original_inst = &original_x86_block.insts[next_before];
            x86_validate_removed_original_copy(original_inst, before_inst)?;
            next_before += 1;
        }

        let block = func.blocks.get_mut(&x86_block_id).ok_or_else(|| {
            X86PipelineError::RegAlloc(format!(
                "x86-64 replay missing mutable block {}",
                x86_block_id.0
            ))
        })?;
        block.insts = replayed_insts;
    }

    func.next_vreg = after.next_vreg;
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum X86SplitReplayCfgDiagnostic {
    BlockOrderLengthMismatch {
        block_order_len: usize,
        blocks_len: usize,
    },
    EntryBlockNotFirst {
        entry: BlockId,
        first: Option<BlockId>,
    },
    BlockOrderReferencesMissingBlock {
        block: BlockId,
    },
    DuplicateBlockOrder {
        block: BlockId,
    },
    EntryBlockHasPredecessors {
        block: BlockId,
    },
    UnreachableBlock {
        block: BlockId,
    },
    CyclicMultiDefVReg {
        vreg: VReg,
    },
    InconsistentCfgEdge {
        predecessor: BlockId,
        successor: BlockId,
    },
    MissingJoinEdgeTerminator {
        predecessor: BlockId,
        successor: BlockId,
    },
    /// The function contains BOTH a `call` instruction AND a join block (a block
    /// with more than one predecessor). The greedy live-range splitter's
    /// join-block split-copy placement is unsound for this shape: a value live
    /// across the call AND across the join (e.g. a memory-aggregate return-slot
    /// pointer produced by the `?`-operator desugaring's diamond) can have its
    /// split copy dropped/misplaced on the taken path, so the post-call reload
    /// reads a stale stack slot and the program faults or miscompiles. We fail
    /// the splitting admission closed (falling back to the plain greedy
    /// allocator, which spills instead of splits — always sound) rather than
    /// emit the unsound split. See `try_operator_x86.rs`.
    CallAcrossJoin {
        join: BlockId,
    },
    /// The function contains a fixed-physical-register-clobbering instruction
    /// (x86 DIV/IDIV pins the dividend in RAX and clobbers RDX; MUL, CDQ/CQO,
    /// CMPXCHG and the atomic CAS loops likewise define fixed physical
    /// registers). These constraints are carried as implicit RAX/RDX def/use
    /// edges, which the greedy live-range splitter does NOT model when it places
    /// split copies. A live range that crosses such a clobber can therefore have
    /// its split copy spilled to / reloaded from a slot that the fixed-register
    /// op corrupted (or that was never written), corrupting the result under
    /// register pressure (the div/rem-under-pressure miscompile, m52). Splitting
    /// is a pure code-quality optimization, so we fail its admission closed
    /// (plain greedy spill, always sound) whenever such a clobber is present.
    FixedRegClobber {
        opcode: u16,
    },
    /// The function contains a join block (a block with more than one
    /// predecessor) — e.g. the continuation after an `if`/`match`/`&&`/`||`.
    /// The greedy live-range splitter's join-block split-copy placement is
    /// unsound under register pressure even WITHOUT a call crossing the join:
    /// a value live into the join can have its split copy mis-placed on one
    /// incoming path, so the join reloads a stale stack slot and the program
    /// miscompiles at O2/O3 (MISCOMPILE #64 — a ~13-live-value scalar program
    /// with `match`/select joins returns wrong results). The earlier guard only
    /// rejected the call+join shape (`CallAcrossJoin`, the `?` diamond / m52);
    /// this broadens the rejection to ALL joins. Straight-line and linear
    /// (single-predecessor-chain) code still splits. Splitting is a pure
    /// code-quality optimization, so failing its admission closed (plain greedy
    /// spill, always sound) is the correct verified-compiler tradeoff.
    JoinBlockUnderSplit {
        join: BlockId,
    },
}

fn x86_regalloc_splitting_cfg_diagnostic(
    func: &RegAllocFunction,
) -> Result<(), X86SplitReplayCfgDiagnostic> {
    if func.block_order.len() != func.blocks.len() {
        return Err(X86SplitReplayCfgDiagnostic::BlockOrderLengthMismatch {
            block_order_len: func.block_order.len(),
            blocks_len: func.blocks.len(),
        });
    }
    if func.block_order.first() != Some(&func.entry_block) {
        return Err(X86SplitReplayCfgDiagnostic::EntryBlockNotFirst {
            entry: func.entry_block,
            first: func.block_order.first().copied(),
        });
    }

    let mut order_index = HashMap::with_capacity(func.block_order.len());
    for (idx, &block_id) in func.block_order.iter().enumerate() {
        if block_id.0 as usize >= func.blocks.len() {
            return Err(
                X86SplitReplayCfgDiagnostic::BlockOrderReferencesMissingBlock { block: block_id },
            );
        }
        if order_index.insert(block_id, idx).is_some() {
            return Err(X86SplitReplayCfgDiagnostic::DuplicateBlockOrder { block: block_id });
        }
    }

    for &block_id in &func.block_order {
        let block = &func.blocks[block_id.0 as usize];
        if block_id == func.entry_block {
            if !block.preds.is_empty() {
                return Err(X86SplitReplayCfgDiagnostic::EntryBlockHasPredecessors {
                    block: block_id,
                });
            }
        } else if block.preds.is_empty() {
            return Err(X86SplitReplayCfgDiagnostic::UnreachableBlock { block: block_id });
        }

        for &pred in &block.preds {
            if !order_index.contains_key(&pred) {
                return Err(
                    X86SplitReplayCfgDiagnostic::BlockOrderReferencesMissingBlock { block: pred },
                );
            }
            let Some(pred_block) = func.blocks.get(pred.0 as usize) else {
                return Err(
                    X86SplitReplayCfgDiagnostic::BlockOrderReferencesMissingBlock { block: pred },
                );
            };
            if !pred_block.succs.contains(&block_id) {
                return Err(X86SplitReplayCfgDiagnostic::InconsistentCfgEdge {
                    predecessor: pred,
                    successor: block_id,
                });
            }
        }

        for &succ in &block.succs {
            if !order_index.contains_key(&succ) {
                return Err(
                    X86SplitReplayCfgDiagnostic::BlockOrderReferencesMissingBlock { block: succ },
                );
            }
            let Some(succ_block) = func.blocks.get(succ.0 as usize) else {
                return Err(
                    X86SplitReplayCfgDiagnostic::BlockOrderReferencesMissingBlock { block: succ },
                );
            };
            if !succ_block.preds.contains(&block_id) {
                return Err(X86SplitReplayCfgDiagnostic::InconsistentCfgEdge {
                    predecessor: block_id,
                    successor: succ,
                });
            }
            if succ_block.preds.len() > 1 && !x86_regalloc_block_has_terminator(func, block_id) {
                return Err(X86SplitReplayCfgDiagnostic::MissingJoinEdgeTerminator {
                    predecessor: block_id,
                    successor: succ,
                });
            }
        }
    }

    if x86_regalloc_cfg_contains_cycle(func)
        && let Some(vreg) = x86_regalloc_first_multi_def_vreg(func)
    {
        return Err(X86SplitReplayCfgDiagnostic::CyclicMultiDefVReg { vreg });
    }

    // Reject splitting when the function has BOTH a call and a join block. The
    // greedy splitter's join-block split-copy placement is unsound for that
    // combination (a value live across the call and the join can lose its split
    // copy on the taken path -> stale-slot reload -> fault/miscompile). This is
    // exactly the `?`-operator diamond. Splitting is a pure code-quality
    // optimization, so failing its admission closed (plain greedy spill instead)
    // is always sound.
    if x86_regalloc_func_contains_call(func)
        && let Some(join) = x86_regalloc_first_join_block(func)
    {
        return Err(X86SplitReplayCfgDiagnostic::CallAcrossJoin { join });
    }

    // Reject splitting for ANY remaining join block (a block with >1
    // predecessor), even with no call crossing it. The greedy splitter's
    // join-block split-copy placement is unsound under register pressure for
    // ordinary `if`/`match`/`&&`/`||` continuations too (MISCOMPILE #64): a
    // value live into the join can lose its split copy on one incoming path, so
    // the join reloads a stale slot and the program returns the wrong result at
    // O2/O3. The earlier `CallAcrossJoin` guard (m52) caught only the call+join
    // diamond; this closes the call-free-join hole. Straight-line / linear
    // (single-pred-chain) functions still split; plain greedy spill is sound.
    if let Some(join) = x86_regalloc_first_join_block(func) {
        return Err(X86SplitReplayCfgDiagnostic::JoinBlockUnderSplit { join });
    }

    // Reject splitting when the function contains a fixed-physical-register
    // clobber (DIV/IDIV/MUL/CDQ/CQO/CMPXCHG/atomic-CAS). The splitter does not
    // model these fixed-register constraints (x86 DIV pins the dividend in RAX
    // and clobbers RDX), so a live range crossing the clobber can be spilled to
    // / reloaded from a corrupted-or-unwritten slot under register pressure.
    // This is the div/rem-under-pressure miscompile (m52). Falling back to plain
    // greedy spill is always sound.
    if let Some(opcode) = x86_regalloc_func_first_fixed_reg_clobber(func) {
        return Err(X86SplitReplayCfgDiagnostic::FixedRegClobber { opcode });
    }

    Ok(())
}

/// True iff the regalloc opcode (an `X86Opcode as u16`) is a fixed-physical-
/// register-clobbering instruction: DIV/IDIV/MUL pin the dividend/factor in
/// RAX/EAX and define RAX:RDX (EAX:EDX); CDQ/CQO sign-extend RAX into RDX;
/// CMPXCHG and the atomic CAS loops define a fixed accumulator. These opcodes
/// carry their fixed register constraints as IMPLICIT def/use edges (see
/// `add_x86_fixed_implicit_operands`), not as explicit operands, which the
/// greedy live-range splitter does not model when placing split copies.
/// Matching on the opcode (rather than merely "has implicit defs") precisely
/// excludes ordinary explicit-physical-register moves such as `mov RAX, vN` for
/// arg/return setup — those define RAX as an *explicit* operand and stay safe to
/// split. Must mirror `add_x86_fixed_implicit_operands`'s clobbering arms.
fn x86_regalloc_opcode_is_fixed_reg_clobber(opcode: u16) -> bool {
    use X86Opcode::*;
    opcode == Div as u16
        || opcode == Idiv as u16
        || opcode == Mul as u16
        || opcode == Cdq as u16
        || opcode == Cqo as u16
        || opcode == Cmpxchg as u16
        || opcode == Cmpxchg8 as u16
        || opcode == Cmpxchg16 as u16
        || opcode == AtomicRmwCasLoop as u16
        || opcode == AtomicRmwCasLoop8 as u16
        || opcode == AtomicRmwCasLoop16 as u16
}

/// The opcode of the first fixed-physical-register-clobbering instruction
/// (DIV/IDIV/MUL, CDQ/CQO, CMPXCHG, atomic CAS) in `func`, if any. Such an op
/// forces a value into / clobbers a fixed physical register (x86 DIV pins the
/// dividend in RAX and clobbers RDX). The greedy splitter does not model these
/// implicit fixed-register constraints when it places split copies, so a value
/// whose live range crosses the clobber can be read back from a slot that was
/// clobbered or never written. Splitting is a pure code-quality optimization, so
/// we fail its admission closed (plain greedy spill, always sound) whenever such
/// a clobber is present (m52).
fn x86_regalloc_func_first_fixed_reg_clobber(func: &RegAllocFunction) -> Option<u16> {
    func.insts
        .iter()
        .map(|inst| inst.opcode)
        .find(|&opcode| x86_regalloc_opcode_is_fixed_reg_clobber(opcode))
}

/// True iff any instruction in `func` is a call (the unsound interaction below
/// only arises when a value can be live across a call).
fn x86_regalloc_func_contains_call(func: &RegAllocFunction) -> bool {
    func.insts
        .iter()
        .any(|inst| inst.flags.contains(trust_cg_ir::inst::InstFlags::IS_CALL))
}

/// The first join block (a block with more than one predecessor) in block order,
/// if any. A join is where the greedy splitter must place edge/join split copies,
/// the placement that is unsound when combined with a call (see `CallAcrossJoin`).
fn x86_regalloc_first_join_block(func: &RegAllocFunction) -> Option<BlockId> {
    func.block_order.iter().copied().find(|&block_id| {
        func.blocks
            .get(block_id.0 as usize)
            .is_some_and(|block| block.preds.len() > 1)
    })
}

fn x86_regalloc_block_has_terminator(func: &RegAllocFunction, block_id: BlockId) -> bool {
    func.blocks.get(block_id.0 as usize).is_some_and(|block| {
        block.insts.iter().any(|inst_id| {
            func.insts.get(inst_id.0 as usize).is_some_and(|inst| {
                inst.flags
                    .contains(trust_cg_ir::inst::InstFlags::IS_TERMINATOR)
            })
        })
    })
}

fn x86_regalloc_cfg_contains_cycle(func: &RegAllocFunction) -> bool {
    for &block_id in &func.block_order {
        let Some(block) = func.blocks.get(block_id.0 as usize) else {
            continue;
        };
        for &succ in &block.succs {
            if succ == block_id || x86_regalloc_cfg_reaches_block(func, succ, block_id) {
                return true;
            }
        }
    }

    false
}

fn x86_regalloc_cfg_reaches_block(
    func: &RegAllocFunction,
    start: BlockId,
    target: BlockId,
) -> bool {
    let mut stack = vec![start];
    let mut seen = HashSet::new();

    while let Some(block_id) = stack.pop() {
        if block_id == target {
            return true;
        }
        if !seen.insert(block_id) {
            continue;
        }
        if let Some(block) = func.blocks.get(block_id.0 as usize) {
            stack.extend(block.succs.iter().copied());
        }
    }

    false
}

fn x86_regalloc_first_multi_def_vreg(func: &RegAllocFunction) -> Option<VReg> {
    let mut def_counts: HashMap<VReg, u32> = HashMap::new();
    for inst in &func.insts {
        for vreg in inst.vreg_defs() {
            let count = def_counts.entry(vreg).or_insert(0);
            *count += 1;
            if *count > 1 {
                return Some(vreg);
            }
        }
    }

    None
}

fn x86_regalloc_splitting_supported_cfg(func: &RegAllocFunction) -> bool {
    x86_regalloc_splitting_cfg_diagnostic(func).is_ok()
}

// ---------------------------------------------------------------------------
// X86ISelFunction -> RegAllocFunction conversion
// ---------------------------------------------------------------------------

/// Classify whether an x86-64 opcode's first operand is a definition.
///
/// Returns `true` if the first operand is a def (output), `false` if all
/// operands are uses (e.g., branches, returns, compares, stores).
fn opcode_has_def(opcode: X86Opcode) -> bool {
    use X86Opcode::*;
    match opcode {
        // Control flow: no defs (all operands are uses or implicit).
        Jmp | Jcc | Ret | Call | CallR | CallM | Ud2 => false,

        // Compares/tests: set flags only, no register def.
        CmpRR | CmpRI | CmpRI8 | TestRR | TestRI | TestRM | Ucomisd | Ucomiss | CmpRM | BtRI
        | Ptest => false,

        // Memory stores: write to memory, no register def.
        MovMR8 | MovMR16 | MovMR32 | MovMR | MovsdMR | MovssMR | MovdquMR | MovdqaMR | MovMRSib
        | MovMR8Sib | MovMR32Sib | VolatileMovMR8 | VolatileMovMR16 | VolatileMovMR32
        | VolatileMovMR | VolatileMovssMR | VolatileMovsdMR | VolatileMovdquMR
        | VolatileMovdqaMR => false,

        // Stack manipulation: implicit RSP modification, no register def.
        Push => false,

        // CDQ/CQO: implicit operands only (writes RDX).
        Cdq | Cqo => false,

        // IDIV/DIV: implicit RDX:RAX operands.
        Idiv | Div | Mul => false,

        // Pseudo/no-def instructions.
        Nop | NopMulti | Mfence => false,

        // StackAlloc materializes the returned runtime stack address in operand 0.
        StackAlloc => true,

        // PHI: def is first operand.
        Phi => true,

        // Everything else: first operand is a def.
        _ => true,
    }
}

/// Returns `true` if the instruction's first operand is both read and written.
///
/// This covers:
/// - Unary in-place ops like `NEG dst`
/// - RI/RM/shift forms like `ADD dst, imm` where operand 0 is live-in
///
/// RR/SSE three-address forms do not need special handling here because a
/// two-address-safe instruction already carries the live-in value explicitly
/// as operand 1 (`ADD v0, v0, v1`).
fn first_operand_is_def_and_use(inst: &X86ISelInst) -> bool {
    use X86Opcode::*;

    if inst.operands.len() == 2 && is_x86_two_address_rr(inst.opcode) {
        return true;
    }
    if inst.operands.len() == 2 && is_x86_three_address_ri(inst.opcode) {
        return true;
    }

    match inst.opcode {
        Neg | Not => inst.operands.len() == 1,
        Inc | Dec => true,
        Bswap | Cmovcc | Cmovcc32 | Xchg | Cmpxchg | Cmpxchg8 | Cmpxchg16 | Pblendvb => true,
        Pinsrd | Pinsrq => inst.operands.len() == 3,
        AddRM | SubRM | ImulRM | ImulRMSib | ShlRI | ShrRI | SarRI => inst.operands.len() == 2,
        ShlRR | ShrRR | SarRR => inst.operands.len() == 1,
        _ => false,
    }
}

fn x86_cmpxchg_has_memory_operand(inst: &X86ISelInst) -> bool {
    inst.operands.iter().any(|operand| {
        matches!(
            operand,
            X86ISelOperand::MemAddr { .. } | X86ISelOperand::SibMemAddr { .. }
        )
    })
}

#[derive(Clone, Copy)]
struct X86OperandAccess {
    is_use: bool,
    is_def: bool,
}

fn x86_operand_access(inst: &X86ISelInst, idx: usize) -> X86OperandAccess {
    match inst.opcode {
        X86Opcode::Xchg if idx < 2 => {
            return X86OperandAccess {
                is_use: true,
                is_def: true,
            };
        }
        X86Opcode::Cmpxchg | X86Opcode::Cmpxchg8 | X86Opcode::Cmpxchg16
            if idx == 0 && x86_cmpxchg_has_memory_operand(inst) =>
        {
            return X86OperandAccess {
                is_use: true,
                is_def: false,
            };
        }
        X86Opcode::Cmpxchg | X86Opcode::Cmpxchg8 | X86Opcode::Cmpxchg16 if idx == 0 => {
            return X86OperandAccess {
                is_use: true,
                is_def: true,
            };
        }
        _ => {}
    }

    let is_first_def = idx == 0 && opcode_has_def(inst.opcode);
    X86OperandAccess {
        is_use: !is_first_def || first_operand_is_def_and_use(inst),
        is_def: is_first_def,
    }
}

fn push_unique_preg(dst: &mut Vec<trust_cg_regalloc::PReg>, preg: trust_cg_regalloc::PReg) {
    if !dst.contains(&preg) {
        dst.push(preg);
    }
}

fn push_unique_x86_preg(dst: &mut Vec<trust_cg_regalloc::PReg>, x86_preg: X86PReg) {
    if let Some(preg) = x86_to_preg(x86_preg) {
        push_unique_preg(dst, preg);
    }
}

/// Like [`push_unique_x86_preg`] but resolves BYTE/WORD GPR aliases (AL/AX,
/// R10B/R10W) to their containing GPR64 PReg via `x86_fixed_operand_to_preg`.
///
/// `x86_to_preg` returns `None` for gpr8/gpr16 registers (they are not their own
/// allocatable class), so pushing e.g. `AL` through `push_unique_x86_preg`
/// silently no-ops -- which would leave a narrow-CAS-loop's RAX clobber
/// UNDECLARED, letting the allocator place the source/base operand into RAX and
/// hitting the encoder's fixed-register conflict at O2/O3. Mapping the alias to
/// its parent GPR64 registers the clobber against the real interference unit.
fn push_unique_x86_fixed_preg(dst: &mut Vec<trust_cg_regalloc::PReg>, x86_preg: X86PReg) {
    if let Some(preg) = x86_fixed_operand_to_preg(x86_preg) {
        push_unique_preg(dst, preg);
    }
}

fn add_x86_memaddr_regalloc_uses(
    base: &X86ISelOperand,
    disp: i32,
    uses: &mut Vec<RegAllocOperand>,
    implicit_uses: &mut Vec<trust_cg_regalloc::PReg>,
) {
    match base {
        X86ISelOperand::VReg(v) => {
            uses.push(RegAllocOperand::VReg(*v));
        }
        X86ISelOperand::PReg(p) => {
            if let Some(preg) = x86_fixed_operand_to_preg(*p) {
                push_unique_preg(implicit_uses, preg);
            }
        }
        X86ISelOperand::StackSlot(slot) => {
            uses.push(RegAllocOperand::StackSlot(StackSlotId(*slot)));
        }
        _ => {}
    }
    uses.push(RegAllocOperand::Imm(i64::from(disp)));
}

fn add_x86_sib_memaddr_regalloc_uses(
    base: &X86ISelOperand,
    index: &X86ISelOperand,
    scale: u8,
    disp: i32,
    uses: &mut Vec<RegAllocOperand>,
    implicit_uses: &mut Vec<trust_cg_regalloc::PReg>,
) {
    add_x86_memaddr_regalloc_uses(base, disp, uses, implicit_uses);
    match index {
        X86ISelOperand::VReg(v) => {
            uses.push(RegAllocOperand::VReg(*v));
        }
        X86ISelOperand::PReg(p) => {
            if let Some(preg) = x86_fixed_operand_to_preg(*p) {
                push_unique_preg(implicit_uses, preg);
            }
        }
        X86ISelOperand::StackSlot(slot) => {
            uses.push(RegAllocOperand::StackSlot(StackSlotId(*slot)));
        }
        _ => {}
    }
    uses.push(RegAllocOperand::Imm(i64::from(scale)));
}

fn x86_div_uses_gpr32_fixed_regs(inst: &X86ISelInst) -> bool {
    match inst.operands.first() {
        Some(X86ISelOperand::VReg(vreg)) => vreg.class == RegClass::Gpr32,
        Some(X86ISelOperand::PReg(preg)) => preg.is_gpr32(),
        _ => false,
    }
}

fn x86_cmpxchg_accumulator_reg(inst: &X86ISelInst) -> X86PReg {
    match inst.operands.first() {
        Some(X86ISelOperand::VReg(vreg)) if vreg.class == RegClass::Gpr32 => x86_64_regs::EAX,
        Some(X86ISelOperand::PReg(preg)) if preg.is_gpr32() => x86_64_regs::EAX,
        _ => x86_64_regs::RAX,
    }
}

fn x86_atomic_rmw_cas_loop_fixed_regs(inst: &X86ISelInst) -> (X86PReg, X86PReg) {
    match inst.opcode {
        X86Opcode::AtomicRmwCasLoop8 => (AL, R10B),
        X86Opcode::AtomicRmwCasLoop16 => (AX, R10W),
        _ => match inst.operands.first() {
            Some(X86ISelOperand::VReg(vreg)) if vreg.class == RegClass::Gpr32 => {
                (x86_64_regs::EAX, x86_64_regs::R10D)
            }
            Some(X86ISelOperand::PReg(preg)) if preg.is_gpr32() => {
                (x86_64_regs::EAX, x86_64_regs::R10D)
            }
            _ => (x86_64_regs::RAX, x86_64_regs::R10),
        },
    }
}

fn add_x86_fixed_implicit_operands(
    inst: &X86ISelInst,
    implicit_defs: &mut Vec<trust_cg_regalloc::PReg>,
    implicit_uses: &mut Vec<trust_cg_regalloc::PReg>,
) {
    match inst.opcode {
        X86Opcode::Cdq => {
            push_unique_x86_preg(implicit_uses, x86_64_regs::EAX);
            push_unique_x86_preg(implicit_defs, x86_64_regs::EDX);
        }
        X86Opcode::Cqo => {
            push_unique_x86_preg(implicit_uses, x86_64_regs::RAX);
            push_unique_x86_preg(implicit_defs, x86_64_regs::RDX);
        }
        X86Opcode::ShlRR | X86Opcode::ShrRR | X86Opcode::SarRR => {
            push_unique_x86_preg(implicit_uses, x86_64_regs::RCX);
        }
        X86Opcode::Idiv | X86Opcode::Div => {
            let (acc, high) = if x86_div_uses_gpr32_fixed_regs(inst) {
                (x86_64_regs::EAX, x86_64_regs::EDX)
            } else {
                (x86_64_regs::RAX, x86_64_regs::RDX)
            };
            push_unique_x86_preg(implicit_uses, acc);
            push_unique_x86_preg(implicit_uses, high);
            push_unique_x86_preg(implicit_defs, acc);
            push_unique_x86_preg(implicit_defs, high);
        }
        X86Opcode::Mul => {
            let (acc, high) = if x86_div_uses_gpr32_fixed_regs(inst) {
                (x86_64_regs::EAX, x86_64_regs::EDX)
            } else {
                (x86_64_regs::RAX, x86_64_regs::RDX)
            };
            push_unique_x86_preg(implicit_uses, acc);
            push_unique_x86_preg(implicit_defs, acc);
            push_unique_x86_preg(implicit_defs, high);
        }
        X86Opcode::Cmpxchg | X86Opcode::Cmpxchg8 | X86Opcode::Cmpxchg16 => {
            let acc = x86_cmpxchg_accumulator_reg(inst);
            push_unique_x86_preg(implicit_uses, acc);
            push_unique_x86_preg(implicit_defs, acc);
        }
        X86Opcode::AtomicRmwCasLoop
        | X86Opcode::AtomicRmwCasLoop8
        | X86Opcode::AtomicRmwCasLoop16 => {
            // The narrow (i8/i16) loops pin AL/AX (accumulator) and R10B/R10W
            // (scratch) -- BYTE/WORD aliases whose parent GPR64 is the real
            // interference unit. Use the fixed-operand mapping so the RAX clobber
            // is DECLARED (x86_to_preg no-ops on gpr8/gpr16); otherwise the
            // allocator may place the source/base into RAX and trip the encoder's
            // fixed-register conflict at O2/O3. The i32/i64 loop's EAX/RAX +
            // R10D/R10 map identically under either helper.
            let (acc, scratch) = x86_atomic_rmw_cas_loop_fixed_regs(inst);
            push_unique_x86_fixed_preg(implicit_defs, acc);
            push_unique_x86_fixed_preg(implicit_defs, scratch);
        }
        X86Opcode::Pblendvb => {
            push_unique_x86_preg(implicit_uses, XMM0);
        }
        _ => {}
    }
}

/// The rbp-relative displacements of the regalloc-created spill slots: the
/// LAST `num_spills` entries of the frame layout ([`install_x86_spill_slots`]
/// appends spill slots after every frontend-created slot). Feeds recheck (5).
fn x86_spill_slot_disps(layout: &X86StackFrameLayout, num_spills: u32) -> HashSet<i32> {
    layout
        .stack_slot_offsets
        .iter()
        .rev()
        .take(num_spills as usize)
        .filter_map(|o| *o)
        .collect()
}

/// Whole-function spill-slot initialization check (recheck (5)). Returns the
/// first spill-slot displacement that is READ but never STORED in the final
/// resolved stream. Store-form opcodes carry their memory operand as the
/// DESTINATION; every other instruction's rbp-based memory operand at a spill
/// displacement is a read (plain reloads and folded ALU/packed rhs forms
/// alike). An `Lea` of a spill slot would count as a read and fail closed —
/// the spiller never takes a spill slot's address, so that shape appearing at
/// all is itself a pipeline invariant violation.
fn x86_uninitialized_spill_read(func: &X86ISelFunction, spill_disps: &HashSet<i32>) -> Option<i32> {
    if spill_disps.is_empty() {
        return None;
    }
    let is_store_form = |op: X86Opcode| {
        matches!(
            op,
            X86Opcode::MovMR8
                | X86Opcode::MovMR16
                | X86Opcode::MovMR32
                | X86Opcode::MovMR
                | X86Opcode::MovsdMR
                | X86Opcode::MovssMR
                | X86Opcode::MovdquMR
                | X86Opcode::MovdqaMR
                | X86Opcode::MovMRSib
                | X86Opcode::MovMR32Sib
                | X86Opcode::MovMR8Sib
                | X86Opcode::VolatileMovMR8
                | X86Opcode::VolatileMovMR16
                | X86Opcode::VolatileMovMR32
                | X86Opcode::VolatileMovMR
                | X86Opcode::VolatileMovssMR
                | X86Opcode::VolatileMovsdMR
                | X86Opcode::VolatileMovdquMR
                | X86Opcode::VolatileMovdqaMR
        )
    };
    let mut reads: HashSet<i32> = HashSet::new();
    let mut writes: HashSet<i32> = HashSet::new();
    for block_id in &func.block_order {
        let Some(block) = func.blocks.get(block_id) else {
            continue;
        };
        for inst in &block.insts {
            for op in &inst.operands {
                let d = match op {
                    X86ISelOperand::MemAddr { base, disp } if matches!(base.as_ref(), X86ISelOperand::PReg(p) if *p == RBP) => {
                        *disp
                    }
                    X86ISelOperand::SibMemAddr { base, disp, .. } if matches!(base.as_ref(), X86ISelOperand::PReg(p) if *p == RBP) => {
                        *disp
                    }
                    _ => continue,
                };
                if !spill_disps.contains(&d) {
                    continue;
                }
                if is_store_form(inst.opcode) {
                    writes.insert(d);
                } else {
                    reads.insert(d);
                }
            }
        }
    }
    reads.difference(&writes).next().copied()
}

fn install_x86_spill_slots(func: &mut X86ISelFunction, plan: &X86SpillPlan) -> HashMap<VReg, u32> {
    let mut installed = HashMap::with_capacity(plan.slots.len());
    for spill in &plan.slots {
        let slot = func.stack_slots.len() as u32;
        func.stack_slots
            .push(StackSlotInfo::new(spill.size, spill.align));
        installed.insert(spill.vreg, slot);
    }
    installed
}

struct X86SpillScratchState {
    abi: X86CallAbi,
    assigned: HashMap<VReg, X86PReg>,
    loaded: HashSet<VReg>,
    stores: Vec<VReg>,
    gpr_used: usize,
    xmm_used: usize,
}

impl X86SpillScratchState {
    fn new(abi: X86CallAbi) -> Self {
        Self {
            abi,
            assigned: HashMap::new(),
            loaded: HashSet::new(),
            stores: Vec::new(),
            gpr_used: 0,
            xmm_used: 0,
        }
    }

    fn scratch_for(&mut self, vreg: VReg) -> Result<X86PReg, X86PipelineError> {
        if let Some(scratch) = self.assigned.get(&vreg) {
            return Ok(*scratch);
        }

        let bank = x86_reg_bank_for_class(vreg.class).ok_or_else(|| {
            X86PipelineError::RegAlloc(format!(
                "x86-64 spill replay does not support {:?} values",
                vreg.class
            ))
        })?;
        let scratch = match bank {
            X86RegBank::Gpr => {
                if self.gpr_used >= 2 {
                    return Err(X86PipelineError::RegAlloc(
                        "x86-64 spill replay needs more than two GPR scratch registers for one instruction"
                            .to_string(),
                    ));
                }
                let reg = x86_spill_gpr_scratch_regs(vreg.class)[self.gpr_used];
                self.gpr_used += 1;
                reg
            }
            X86RegBank::Xmm => {
                if self.xmm_used >= 2 {
                    return Err(X86PipelineError::RegAlloc(
                        "x86-64 spill replay needs more than two XMM scratch registers for one instruction"
                            .to_string(),
                    ));
                }
                let reg = x86_spill_xmm_scratch_regs(self.abi)[self.xmm_used];
                self.xmm_used += 1;
                reg
            }
        };

        self.assigned.insert(vreg, scratch);
        Ok(scratch)
    }

    /// Force a two-address instruction's spilled destination and first source
    /// to share a single scratch register before per-operand rewriting begins.
    ///
    /// For a three-address ISel form `OP [dst, lhs, rhs]` whose x86 encoding is
    /// two-address (`dst = dst OP rhs`, with `dst == lhs`), an unaliased replay
    /// would need three distinct scratches when all three vregs are spilled —
    /// one each for `dst`, `lhs`, and `rhs` — which overflows the two-register
    /// scratch budget. Tying `dst` and `lhs` to the same scratch reproduces
    /// exactly what the later `fixup_two_address` pass would do (it would place
    /// `dst` and `lhs` in the same physical register and emit no copy), so the
    /// reload of `lhs` lands in the scratch, the op computes in place, and the
    /// result is stored back to `dst`'s slot. This drops the requirement to two
    /// scratches without changing semantics.
    fn alias_two_address(&mut self, dst: VReg, lhs: VReg) -> Result<(), X86PipelineError> {
        // Both must be the same register bank/class to legally share a scratch.
        if dst.class != lhs.class {
            return Ok(());
        }
        // If either is already assigned (shouldn't happen — this runs first),
        // do not override; fall back to the per-operand path.
        if self.assigned.contains_key(&dst) || self.assigned.contains_key(&lhs) {
            return Ok(());
        }
        let scratch = self.scratch_for(dst)?;
        self.assigned.insert(lhs, scratch);
        Ok(())
    }

    fn mark_store(&mut self, vreg: VReg) {
        if !self.stores.contains(&vreg) {
            self.stores.push(vreg);
        }
    }

    /// Reserve one GPR scratch register without binding it to a vreg.
    ///
    /// Used by the SIB-address pre-sequencing path: after folding a SIB memory
    /// operand's effective address into the FIRST scratch register, that
    /// register holds a live value (the computed address) for the remainder of
    /// the instruction, so it must not be handed out again. Bumping `gpr_used`
    /// makes the next `scratch_for` return the SECOND scratch, leaving the
    /// address register untouched.
    fn reserve_gpr_scratch(&mut self) {
        self.gpr_used += 1;
    }
}

/// A spilled vreg whose value can be RE-MATERIALIZED at each use point more
/// cheaply than a stack reload — the reload (`mov r, [slot]`, an L1 access on
/// the hot loop path) is replaced by recomputing the value from scratch. The
/// vreg must have EXACTLY ONE def in the whole function whose result is a
/// pure, invariant function of nothing (a constant) or only of RBP (a frame
/// address), so recomputing at any later point yields the identical value.
#[derive(Debug, Clone, Copy)]
enum X86SpillRemat {
    /// Sole def is `MovRI [vreg, Imm(k)]` — recompute as `MovRI scratch, k`.
    /// The scratch preg is width-typed by the vreg class
    /// (`x86_spill_gpr_scratch_regs`), so the emitted `MovRI` matches the
    /// original def's width (a Gpr32 scratch takes the low 32 bits and
    /// zero-extends, exactly as the original def and the reload did).
    Const { imm: i64 },
    /// Sole def is `Lea [vreg, MemAddr{ StackSlot(s), disp }]` — a frame
    /// address, recompute as `Lea scratch, [StackSlot(s)+disp]`. RBP is
    /// function-invariant so the address is identical at any point.
    FrameAddr { slot: u32, disp: i32 },
}

/// Build the spill-rematerialization map: for every vreg with exactly ONE
/// value-producing def in the function, if that def is a rematerializable
/// constant / frame-address, record how to recompute it. Multi-def vregs are
/// excluded (a later def could change the value between the def and a use, so
/// recomputing from the FIRST def would be wrong). Fail-closed: any shape not
/// on the exact allowlist is simply absent from the map (→ normal reload).
fn build_x86_spill_remat_map(func: &X86ISelFunction) -> HashMap<VReg, X86SpillRemat> {
    // Count value-producing defs per vreg (operand 0 of an `opcode_has_def`
    // inst — the authoritative x86 def model). The exchange/atomic family
    // (`Xchg`/`Cmpxchg*`/`AtomicRmwCasLoop*`) defines operands BEYOND operand 0
    // (the second register, and implicit RAX), which the operand-0 model
    // misses — so we conservatively count EVERY vreg operand of those as a def
    // to poison single-def status (a hidden second def would otherwise let
    // remat recompute the stale first-def value at a use that must see the
    // exchanged value). This mirrors the unroller / fold / DCE hidden-def
    // discipline.
    let mut def_count: HashMap<VReg, u32> = HashMap::new();
    for block_id in &func.block_order {
        let Some(block) = func.blocks.get(block_id) else {
            continue;
        };
        for inst in &block.insts {
            if matches!(
                inst.opcode,
                X86Opcode::Xchg
                    | X86Opcode::Cmpxchg
                    | X86Opcode::Cmpxchg8
                    | X86Opcode::Cmpxchg16
                    | X86Opcode::AtomicRmwCasLoop
                    | X86Opcode::AtomicRmwCasLoop8
                    | X86Opcode::AtomicRmwCasLoop16
            ) {
                for op in &inst.operands {
                    if let X86ISelOperand::VReg(v) = op {
                        *def_count.entry(*v).or_insert(0) += 1;
                    }
                }
                continue;
            }
            if opcode_has_def(inst.opcode)
                && let Some(X86ISelOperand::VReg(d)) = inst.operands.first()
            {
                *def_count.entry(*d).or_insert(0) += 1;
            }
        }
    }

    let mut map: HashMap<VReg, X86SpillRemat> = HashMap::new();
    for block_id in &func.block_order {
        let Some(block) = func.blocks.get(block_id) else {
            continue;
        };
        for inst in &block.insts {
            if inst.flags != inst.opcode.default_flags() || inst.proof_origin.is_some() {
                continue;
            }
            match inst.opcode {
                X86Opcode::MovRI => {
                    if let [X86ISelOperand::VReg(d), X86ISelOperand::Imm(k)] =
                        inst.operands.as_slice()
                        && def_count.get(d).copied() == Some(1)
                    {
                        map.insert(*d, X86SpillRemat::Const { imm: *k });
                    }
                }
                X86Opcode::Lea => {
                    if let [
                        X86ISelOperand::VReg(d),
                        X86ISelOperand::MemAddr { base, disp },
                    ] = inst.operands.as_slice()
                        && let X86ISelOperand::StackSlot(s) = base.as_ref()
                        && d.class == RegClass::Gpr64
                        && def_count.get(d).copied() == Some(1)
                    {
                        map.insert(
                            *d,
                            X86SpillRemat::FrameAddr {
                                slot: *s,
                                disp: *disp,
                            },
                        );
                    }
                }
                _ => {}
            }
        }
    }

    // Copy-hop closure: a `MovRR d, s` (class-exact GPR copy, single-def `d`)
    // where `s` is already rematerializable makes `d` rematerializable to the
    // SAME expr — `d`'s value is `s`'s value at the copy, and the recompute
    // (a constant / frame address) is invariant, so it yields that value at
    // any later point. This catches the common `Lea base; MovRR copy` shape
    // where the SPILLED vreg is the copy (b07's array base). Iterated to a
    // fixpoint over copy chains; the map only grows, so it terminates.
    // MovRR32 is excluded — a 32-bit copy of a 64-bit frame address would
    // truncate; class-exact MovRR of a Gpr64 preserves the value.
    loop {
        let mut added = false;
        for block_id in &func.block_order {
            let Some(block) = func.blocks.get(block_id) else {
                continue;
            };
            for inst in &block.insts {
                if inst.opcode != X86Opcode::MovRR
                    || inst.flags != inst.opcode.default_flags()
                    || inst.proof_origin.is_some()
                {
                    continue;
                }
                if let [X86ISelOperand::VReg(d), X86ISelOperand::VReg(s)] = inst.operands.as_slice()
                    && d.class == s.class
                    && def_count.get(d).copied() == Some(1)
                    && !map.contains_key(d)
                    && let Some(&expr) = map.get(s)
                {
                    map.insert(*d, expr);
                    added = true;
                }
            }
        }
        if !added {
            break;
        }
    }
    map
}

/// Emit the rematerialization recompute for `remat` into `scratch`.
fn x86_spill_remat_inst(remat: X86SpillRemat, scratch: X86PReg) -> X86ISelInst {
    match remat {
        X86SpillRemat::Const { imm } => X86ISelInst::new(
            X86Opcode::MovRI,
            vec![X86ISelOperand::PReg(scratch), X86ISelOperand::Imm(imm)],
        ),
        X86SpillRemat::FrameAddr { slot, disp } => X86ISelInst::new(
            X86Opcode::Lea,
            vec![
                X86ISelOperand::PReg(scratch),
                X86ISelOperand::MemAddr {
                    base: Box::new(X86ISelOperand::StackSlot(slot)),
                    disp,
                },
            ],
        ),
    }
}

/// Spill rematerialization: DEFAULT-ON (opt-out `TCG_NO_X86_SPILL_REMAT`).
/// Sound by construction — the recompute (`MovRI`/`Lea`) yields the identical
/// value as the reload it replaces, gated on a single, non-exchanged def
/// (adversarial review 2026-07-21: SOUND across all seven hazards; the Xchg
/// operand-1 hidden-def hole is closed by the exchange-family poisoning in
/// `build_x86_spill_remat_map`). The legacy opt-in name is accepted and
/// redundant.
fn x86_spill_remat_enabled() -> bool {
    std::env::var_os("TCG_NO_X86_SPILL_REMAT").is_none()
}

fn rewrite_x86_spilled_operand(
    op: &mut X86ISelOperand,
    installed_spills: &HashMap<VReg, u32>,
    remat_map: &HashMap<VReg, X86SpillRemat>,
    state: &mut X86SpillScratchState,
    loads: &mut Vec<X86ISelInst>,
    is_use: bool,
    is_def: bool,
) -> Result<(), X86PipelineError> {
    match op {
        X86ISelOperand::VReg(vreg) => {
            let Some(&slot) = installed_spills.get(vreg) else {
                return Ok(());
            };
            let vreg = *vreg;
            let scratch = state.scratch_for(vreg)?;
            if is_use && state.loaded.insert(vreg) {
                // Rematerialize instead of reloading when the spilled vreg's
                // sole def is a constant / frame address (cheaper than an L1
                // reload, no memory access). Sound by construction: the
                // recompute yields the identical value at any point.
                if let Some(remat) = remat_map.get(&vreg) {
                    loads.push(x86_spill_remat_inst(*remat, scratch));
                } else {
                    loads.push(X86ISelInst::new(
                        x86_spill_load_opcode(vreg.class),
                        vec![X86ISelOperand::PReg(scratch), x86_spill_stack_mem(slot)],
                    ));
                }
            }
            if is_def {
                state.mark_store(vreg);
            }
            *op = X86ISelOperand::PReg(scratch);
        }
        X86ISelOperand::MemAddr { base, .. } => {
            rewrite_x86_spilled_operand(
                base,
                installed_spills,
                remat_map,
                state,
                loads,
                true,
                false,
            )?;
        }
        X86ISelOperand::SibMemAddr { base, index, .. } => {
            rewrite_x86_spilled_operand(
                base,
                installed_spills,
                remat_map,
                state,
                loads,
                true,
                false,
            )?;
            rewrite_x86_spilled_operand(
                index,
                installed_spills,
                remat_map,
                state,
                loads,
                true,
                false,
            )?;
        }
        _ => {}
    }
    Ok(())
}

fn is_x86_spill_foldable_packed_opcode(opcode: X86Opcode) -> bool {
    matches!(
        opcode,
        X86Opcode::Pand
            | X86Opcode::Por
            | X86Opcode::Pxor
            | X86Opcode::Pcmpeqb
            | X86Opcode::Pcmpeqw
            | X86Opcode::Pcmpgtb
            | X86Opcode::Pcmpgtw
            | X86Opcode::Pcmpeqd
            | X86Opcode::Pcmpgtd
            | X86Opcode::Paddb
            | X86Opcode::Paddw
            | X86Opcode::Paddd
            | X86Opcode::Psubb
            | X86Opcode::Psubw
            | X86Opcode::Psubd
            | X86Opcode::Paddq
            | X86Opcode::Psubq
            | X86Opcode::Pmullw
            | X86Opcode::Pmuludq
            | X86Opcode::Punpcklbw
            | X86Opcode::Packuswb
            | X86Opcode::Punpckhbw
            | X86Opcode::Pshufd
            | X86Opcode::Pmulld
            | X86Opcode::Pcmpeqq
            | X86Opcode::Pcmpgtq
    )
}

fn x86_spill_foldable_rhs_index(inst: &X86ISelInst) -> Option<usize> {
    if !is_x86_spill_foldable_packed_opcode(inst.opcode) {
        return None;
    }

    if inst.opcode == X86Opcode::Pshufd {
        let Some(X86ISelOperand::Imm(imm)) = inst.operands.get(2) else {
            return None;
        };
        return (inst.operands.len() == 3 && (0..=255).contains(imm)).then_some(1);
    }

    match inst.operands.len() {
        2 => Some(1),
        3 => Some(2),
        _ => None,
    }
}

fn x86_operand_vreg_occurrences(op: &X86ISelOperand, needle: VReg) -> usize {
    match op {
        X86ISelOperand::VReg(vreg) if *vreg == needle => 1,
        X86ISelOperand::MemAddr { base, .. } => x86_operand_vreg_occurrences(base, needle),
        X86ISelOperand::SibMemAddr { base, index, .. } => {
            x86_operand_vreg_occurrences(base, needle) + x86_operand_vreg_occurrences(index, needle)
        }
        _ => 0,
    }
}

fn x86_inst_vreg_occurrences(inst: &X86ISelInst, needle: VReg) -> usize {
    inst.operands
        .iter()
        .map(|operand| x86_operand_vreg_occurrences(operand, needle))
        .sum()
}

fn try_fold_x86_spilled_packed_rhs(
    original: &X86ISelInst,
    rewritten: &mut X86ISelInst,
    idx: usize,
    installed_spills: &HashMap<VReg, u32>,
) -> bool {
    if x86_spill_foldable_rhs_index(original) != Some(idx) {
        return false;
    }

    let access = x86_operand_access(original, idx);
    if !access.is_use || access.is_def {
        return false;
    }

    let Some(X86ISelOperand::VReg(vreg)) = original.operands.get(idx) else {
        return false;
    };
    if vreg.class != RegClass::Fpr128 {
        return false;
    }
    let Some(&slot) = installed_spills.get(vreg) else {
        return false;
    };

    if x86_inst_vreg_occurrences(original, *vreg) != 1 {
        return false;
    }

    rewritten.operands[idx] = x86_spill_stack_mem(slot);
    true
}

/// For a three-address ISel instruction whose x86 encoding is two-address
/// (`OP [dst, lhs, rhs]` lowering to `dst = dst OP rhs`), return the spilled
/// `(dst, lhs)` vreg pair when BOTH are spilled.
///
/// This mirrors the `fixup_two_address` constraint that `dst` and `lhs` end up
/// in the same physical register: when both are spilled, the spill replay can
/// reuse a single scratch for them, so an all-spilled three-address op needs
/// only two scratches (the shared dst/lhs scratch plus one for `rhs`) instead
/// of three. Only the genuine three-address `[dst, lhs, rhs]` register form is
/// matched (operand 0 a pure-def vreg, the lhs operand a vreg); two-operand
/// in-place forms, immediate forms, and memory forms are left untouched.
fn x86_two_address_spilled_pair(
    inst: &X86ISelInst,
    installed_spills: &HashMap<VReg, u32>,
) -> Option<(VReg, VReg)> {
    if !is_x86_two_address_rr(inst.opcode) || inst.operands.len() < 3 {
        return None;
    }
    let lhs_index = x86_two_address_lhs_operand_index(inst)?;
    let (X86ISelOperand::VReg(dst), X86ISelOperand::VReg(lhs)) =
        (&inst.operands[0], &inst.operands[lhs_index])
    else {
        return None;
    };
    // Aliasing only helps (and is only required) when dst and lhs are distinct
    // vregs that are both spilled to the stack.
    if dst == lhs {
        return None;
    }
    if installed_spills.contains_key(dst) && installed_spills.contains_key(lhs) {
        Some((*dst, *lhs))
    } else {
        None
    }
}

/// The base-only memory addressing opcode equivalent to a SIB-form opcode.
///
/// When a SIB memory operand's `base + index*scale + disp` effective address is
/// precomputed into a single register (via `LeaSib`), the memory access itself
/// degenerates to a base-only `[reg]` form, so the SIB opcode must be swapped
/// for its base+disp counterpart. Each pair encodes the identical operation and
/// operand width (both 64-bit REX.W MOV / LEA); only the addressing mode differs.
fn x86_sib_opcode_base_only_form(opcode: X86Opcode) -> Option<X86Opcode> {
    match opcode {
        X86Opcode::MovRMSib => Some(X86Opcode::MovRM),
        X86Opcode::MovMRSib => Some(X86Opcode::MovMR),
        X86Opcode::MovRM8Sib => Some(X86Opcode::MovRM8),
        X86Opcode::MovMR8Sib => Some(X86Opcode::MovMR8),
        X86Opcode::LeaSib => Some(X86Opcode::Lea),
        X86Opcode::ImulRMSib => Some(X86Opcode::ImulRM),
        X86Opcode::MovRM32Sib => Some(X86Opcode::MovRM32),
        X86Opcode::MovMR32Sib => Some(X86Opcode::MovMR32),
        _ => None,
    }
}

/// Index of the first `SibMemAddr` operand of an instruction, if any.
fn x86_sib_operand_index(inst: &X86ISelInst) -> Option<usize> {
    inst.operands
        .iter()
        .position(|op| matches!(op, X86ISelOperand::SibMemAddr { .. }))
}

/// Number of distinct spilled GPR vregs referenced (as reads or writes,
/// including inside memory operands) by an instruction.
fn x86_distinct_spilled_gpr_count(
    inst: &X86ISelInst,
    installed_spills: &HashMap<VReg, u32>,
) -> usize {
    fn walk(op: &X86ISelOperand, seen: &mut Vec<VReg>, installed_spills: &HashMap<VReg, u32>) {
        match op {
            X86ISelOperand::VReg(v) => {
                if x86_reg_bank_for_class(v.class) == Some(X86RegBank::Gpr)
                    && installed_spills.contains_key(v)
                    && !seen.contains(v)
                {
                    seen.push(*v);
                }
            }
            X86ISelOperand::MemAddr { base, .. } => walk(base, seen, installed_spills),
            X86ISelOperand::SibMemAddr { base, index, .. } => {
                walk(base, seen, installed_spills);
                walk(index, seen, installed_spills);
            }
            _ => {}
        }
    }
    let mut seen: Vec<VReg> = Vec::new();
    for op in &inst.operands {
        walk(op, &mut seen, installed_spills);
    }
    seen.len()
}

/// When a single instruction, after spilling, would need more than two GPR
/// scratch registers to reload its operands, precompute a SIB memory operand's
/// effective address into one scratch so the replay fits in the two-register
/// budget.
///
/// The overflow shape is a SIB memory op (`MovMRSib`/`MovRMSib`/`LeaSib`) whose
/// `base` and `index` are two distinct spilled GPRs while a THIRD spilled GPR
/// (the stored value, or the loaded/lea destination) also demands a scratch —
/// three distinct scratches for one instruction, which the two-register scratch
/// budget cannot satisfy (the pre-existing `alias_two_address` mitigation only
/// covers three-address two-address ALU forms, not SIB memory operands).
///
/// The fix reloads `base` and `index` into the two scratch registers, folds the
/// full effective address `base + index*scale + disp` into the FIRST scratch via
/// `LeaSib`, and rewrites the memory operand to the base-only form `[scratch0]`
/// (swapping the opcode to its base+disp counterpart). The first scratch is then
/// reserved so the remaining spilled operand reloads into the SECOND scratch —
/// two scratches total. `base` and `index` are dead after the LEA, so reusing
/// their scratch registers is sound; the LEA computes exactly the address the
/// original SIB access would have formed (`base + index*scale + disp`),
/// preserving the load/store target.
///
/// Returns `true` (having emitted the reload+LEA into `loads`, mutated
/// `rewritten` to the base-only form, and reserved the address scratch in
/// `state`) when it sequentialized; `false` when the instruction is not an
/// overflowing SIB shape and the generic per-operand replay should proceed. The
/// non-overflowing SIB cases (fewer than three distinct spilled GPRs) are left
/// byte-identical to the generic replay.
fn try_presequence_x86_sib_address(
    rewritten: &mut X86ISelInst,
    installed_spills: &HashMap<VReg, u32>,
    state: &mut X86SpillScratchState,
    loads: &mut Vec<X86ISelInst>,
) -> Result<bool, X86PipelineError> {
    // Only SIB-form memory opcodes with a base-only counterpart can overflow
    // this way; anything else is left to the generic replay.
    let Some(base_only_opcode) = x86_sib_opcode_base_only_form(rewritten.opcode) else {
        return Ok(false);
    };
    let Some(sib_idx) = x86_sib_operand_index(rewritten) else {
        return Ok(false);
    };

    // Extract the SIB components. Only the fully-general form (base and index
    // both spilled distinct GPR vregs) can consume two scratches for the
    // address alone; other forms already fit and must stay byte-identical.
    let (base_vreg, index_vreg, scale, disp) = match &rewritten.operands[sib_idx] {
        X86ISelOperand::SibMemAddr {
            base,
            index,
            scale,
            disp,
        } => {
            let (X86ISelOperand::VReg(b), X86ISelOperand::VReg(i)) =
                (base.as_ref(), index.as_ref())
            else {
                return Ok(false);
            };
            (*b, *i, *scale, *disp)
        }
        _ => return Ok(false),
    };
    if base_vreg == index_vreg {
        return Ok(false);
    }
    let (Some(&base_slot), Some(&index_slot)) = (
        installed_spills.get(&base_vreg),
        installed_spills.get(&index_vreg),
    ) else {
        return Ok(false);
    };

    // Only sequentialize when the instruction genuinely overflows the two-GPR
    // scratch budget: base + index + (>=1 more distinct spilled GPR). When only
    // base and index are spilled, the generic replay already fits in two
    // scratches, and sequentializing would perturb otherwise byte-identical
    // codegen for that instruction.
    if x86_distinct_spilled_gpr_count(rewritten, installed_spills) < 3 {
        return Ok(false);
    }

    // Reserve the two scratch registers as 64-bit address registers: the folded
    // effective address is a full 64-bit pointer, so the LEA targets the GPR64
    // aliases (R10/R11) even if base/index were narrower. A narrow reload
    // (MovRM32 into R10D/R11D) zero-extends into the full register, matching the
    // 64-bit SIB component the original op would have used.
    let addr_scratch = x86_spill_gpr_scratch_regs(RegClass::Gpr64)[0]; // R10
    let tmp_scratch = x86_spill_gpr_scratch_regs(RegClass::Gpr64)[1]; // R11

    // Reload base into R10 and index into R11 (transient), then fold the full
    // address into R10. base/index are dead after the LEA.
    loads.push(X86ISelInst::new(
        x86_spill_load_opcode(base_vreg.class),
        vec![
            X86ISelOperand::PReg(x86_spill_gpr_scratch_regs(base_vreg.class)[0]),
            x86_spill_stack_mem(base_slot),
        ],
    ));
    loads.push(X86ISelInst::new(
        x86_spill_load_opcode(index_vreg.class),
        vec![
            X86ISelOperand::PReg(x86_spill_gpr_scratch_regs(index_vreg.class)[1]),
            x86_spill_stack_mem(index_slot),
        ],
    ));
    loads.push(X86ISelInst::new(
        X86Opcode::LeaSib,
        vec![
            X86ISelOperand::PReg(addr_scratch),
            X86ISelOperand::SibMemAddr {
                base: Box::new(X86ISelOperand::PReg(addr_scratch)),
                index: Box::new(X86ISelOperand::PReg(tmp_scratch)),
                scale,
                disp,
            },
        ],
    ));

    // Rewrite the memory operand to the base-only form `[R10]` and swap the
    // opcode to its base+disp counterpart; the disp is already folded into R10.
    rewritten.operands[sib_idx] = X86ISelOperand::MemAddr {
        base: Box::new(X86ISelOperand::PReg(addr_scratch)),
        disp: 0,
    };
    rewritten.opcode = base_only_opcode;

    // Reserve R10 as consumed so the remaining spilled operand (value/dst)
    // reloads into R11 rather than clobbering the computed address. R10 already
    // holds the live address; no vreg is associated with it.
    state.reserve_gpr_scratch();

    Ok(true)
}

fn materialize_x86_spills(
    func: &mut X86ISelFunction,
    installed_spills: &HashMap<VReg, u32>,
    abi: X86CallAbi,
) -> Result<X86SpillMaterializationEvidence, X86PipelineError> {
    let mut evidence = X86SpillMaterializationEvidence::default();
    if installed_spills.is_empty() {
        return Ok(evidence);
    }

    // Spill rematerialization (opt-in `TCG_X86_SPILL_REMAT`): for spilled vregs
    // whose sole def is a constant / frame address, recompute at each use
    // instead of reloading from the stack (no L1 access on the hot loop path).
    // Built once from the pre-materialization function; empty when disabled so
    // every reload is the plain stack load.
    let remat_map: HashMap<VReg, X86SpillRemat> = if x86_spill_remat_enabled() {
        build_x86_spill_remat_map(func)
    } else {
        HashMap::new()
    };

    for block_id in func.block_order.clone() {
        let Some(block) = func.blocks.get_mut(&block_id) else {
            continue;
        };
        let mut new_insts = Vec::with_capacity(block.insts.len() + installed_spills.len() * 2);

        for inst in &block.insts {
            let mut rewritten = inst.clone();
            let mut state = X86SpillScratchState::new(abi);
            let mut loads = Vec::new();

            // Two-address fixup runs after this pass and would place a
            // three-address SSE/GPR op's destination and first source in the
            // same physical register. When all of {dst, lhs, rhs} are spilled,
            // honor that tie up front so dst and lhs share one scratch — this
            // keeps the per-instruction scratch demand within the two-register
            // budget instead of needing three.
            if let Some((dst_vreg, lhs_vreg)) = x86_two_address_spilled_pair(inst, installed_spills)
            {
                state.alias_two_address(dst_vreg, lhs_vreg)?;
            }

            // A SIB memory op whose base and index are two distinct spilled GPRs
            // plus a third spilled GPR operand (stored value or loaded/lea dst)
            // needs three scratch registers — one over budget. Fold the
            // effective address into a single scratch first so the memory op
            // degenerates to a base-only form and the generic replay below fits
            // in two scratches. Untouched when the instruction is not this
            // overflowing SIB shape (byte-identical to the prior behavior).
            try_presequence_x86_sib_address(
                &mut rewritten,
                installed_spills,
                &mut state,
                &mut loads,
            )?;

            for idx in 0..rewritten.operands.len() {
                if try_fold_x86_spilled_packed_rhs(inst, &mut rewritten, idx, installed_spills) {
                    continue;
                }

                let access = x86_operand_access(&rewritten, idx);
                rewrite_x86_spilled_operand(
                    &mut rewritten.operands[idx],
                    installed_spills,
                    &remat_map,
                    &mut state,
                    &mut loads,
                    access.is_use,
                    access.is_def,
                )?;
            }

            evidence.reload_count += loads.len();
            new_insts.extend(loads);
            new_insts.push(rewritten);
            let stores = state.stores.clone();
            for vreg in stores {
                let Some(&slot) = installed_spills.get(&vreg) else {
                    continue;
                };
                let scratch = state.scratch_for(vreg)?;
                new_insts.push(X86ISelInst::new(
                    x86_spill_store_opcode(vreg.class),
                    vec![x86_spill_stack_mem(slot), X86ISelOperand::PReg(scratch)],
                ));
                evidence.store_count += 1;
            }
        }

        block.insts = new_insts;
    }

    Ok(evidence)
}

/// Convert an [`X86ISelFunction`] to a [`RegAllocFunction`] for the full
/// register allocation pipeline.
///
/// This bridges the x86-64 ISel type universe to the target-independent
/// regalloc type universe:
/// - Flattens per-block instruction lists into a single `Vec<RegAllocInst>`.
/// - Classifies operands into defs and uses based on opcode semantics.
/// - Converts `Block(u32)` to `BlockId(u32)`, `X86PReg` to `PReg`.
/// - Computes predecessor lists from successor information.
/// Per-block natural-loop depth on the x86 ISel CFG, used to weight regalloc
/// spill decisions (`compute_spill_weight` scales each use/def by
/// 10^loop_depth). Mirrors the dominator/back-edge/loop-body computation the
/// x86 LICM/vectorizer passes use (Cooper/Harvey/Kennedy idoms; a back-edge is
/// `latch -> header` where the header dominates the latch; the body is the
/// backward reachability from the latch that stays clear of the header).
/// Depth = number of distinct headers whose merged loop body contains the
/// block (outermost = 1; blocks outside any loop = 0).
///
/// OPT-IN (`TCG_X86_RA_LOOP_DEPTH=1`): measured 2026-07-15 across the 18-bench
/// suite, depth weighting is a large win on memory-bound loop kernels (b01
/// -31%, b02 -27%, b05 -8%, b12/b16 -6..-11%) but a REAL regression on
/// register-pressure-shuffle kernels (b17 +14%, b06 +12%, interleaved 7-rep
/// verified) — with all-or-nothing spilling (no live-range splitting),
/// protecting hot-loop values evicts other hot values. Default stays flat
/// until live-range splitting lands; the weights only choose WHICH interval
/// spills — allocation correctness is independently enforced by the regalloc
/// validator + TV-5 on every compile.
fn x86_block_loop_depths(func: &X86ISelFunction) -> Vec<u32> {
    use std::collections::{HashMap as DepthMap, HashSet as DepthSet};
    let max_block_id = func
        .block_order
        .iter()
        .map(|b| b.0 as usize)
        .max()
        .unwrap_or(0);
    let mut depths = vec![0u32; max_block_id + 1];
    if std::env::var_os("TCG_X86_RA_LOOP_DEPTH").is_none() || func.block_order.len() < 2 {
        return depths;
    }

    // Predecessor map.
    let mut preds: DepthMap<LirBlock, Vec<LirBlock>> = DepthMap::new();
    for block_id in &func.block_order {
        let Some(block) = func.blocks.get(block_id) else {
            continue;
        };
        for succ in &block.successors {
            preds.entry(*succ).or_default().push(*block_id);
        }
    }

    // Reverse postorder from the entry.
    let entry = func.block_order[0];
    let mut visited: DepthSet<LirBlock> = DepthSet::new();
    let mut postorder: Vec<LirBlock> = Vec::new();
    let mut stack: Vec<(LirBlock, usize)> = vec![(entry, 0)];
    visited.insert(entry);
    while let Some((block, succ_idx)) = stack.pop() {
        let succs: &[LirBlock] = func
            .blocks
            .get(&block)
            .map(|b| b.successors.as_slice())
            .unwrap_or(&[]);
        if succ_idx < succs.len() {
            let next = succs[succ_idx];
            stack.push((block, succ_idx + 1));
            if visited.insert(next) {
                stack.push((next, 0));
            }
        } else {
            postorder.push(block);
        }
    }
    postorder.reverse();
    let rpo_order = postorder;
    let rpo_number: DepthMap<LirBlock, u32> = rpo_order
        .iter()
        .enumerate()
        .map(|(i, b)| (*b, i as u32))
        .collect();

    // Immediate dominators (Cooper/Harvey/Kennedy), mirroring the x86 LICM
    // implementation: first processed predecessor seeds, then intersect.
    let mut idom: DepthMap<LirBlock, LirBlock> = DepthMap::new();
    idom.insert(entry, entry);
    let empty: Vec<LirBlock> = Vec::new();
    let mut changed = true;
    while changed {
        changed = false;
        for &block in &rpo_order {
            if block == entry {
                continue;
            }
            let block_preds = preds.get(&block).unwrap_or(&empty);
            let mut new_idom: Option<LirBlock> = None;
            for &pred in block_preds {
                if !idom.contains_key(&pred) {
                    continue;
                }
                new_idom = Some(match new_idom {
                    None => pred,
                    Some(current) => {
                        // Intersect along the dominator tree by RPO number.
                        let (mut a, mut b) = (pred, current);
                        loop {
                            if a == b {
                                break a;
                            }
                            let (Some(&ra), Some(&rb)) = (rpo_number.get(&a), rpo_number.get(&b))
                            else {
                                break current;
                            };
                            if ra > rb {
                                let Some(&ia) = idom.get(&a) else {
                                    break current;
                                };
                                if ia == a && a != entry {
                                    break current;
                                }
                                if a == entry {
                                    break entry;
                                }
                                a = ia;
                            } else {
                                let Some(&ib) = idom.get(&b) else {
                                    break current;
                                };
                                if ib == b && b != entry {
                                    break current;
                                }
                                if b == entry {
                                    break entry;
                                }
                                b = ib;
                            }
                        }
                    }
                });
            }
            if let Some(n) = new_idom
                && idom.get(&block) != Some(&n)
            {
                idom.insert(block, n);
                changed = true;
            }
        }
    }
    let dominates = |a: LirBlock, mut b: LirBlock| -> bool {
        loop {
            if a == b {
                return true;
            }
            let Some(&up) = idom.get(&b) else {
                return false;
            };
            if up == b {
                return false;
            }
            b = up;
        }
    };

    // Back-edges -> loop bodies (backward reachability from the latch, stopping
    // at the header), merged per header; depth = number of distinct headers
    // whose body contains the block.
    let mut bodies: DepthMap<LirBlock, DepthSet<LirBlock>> = DepthMap::new();
    for &block in &func.block_order {
        let Some(b) = func.blocks.get(&block) else {
            continue;
        };
        for &succ in &b.successors {
            if dominates(succ, block) {
                let header = succ;
                let latch = block;
                let mut body: DepthSet<LirBlock> = DepthSet::new();
                body.insert(header);
                body.insert(latch);
                if header != latch {
                    let mut worklist: Vec<LirBlock> = vec![latch];
                    while let Some(w) = worklist.pop() {
                        for &pred in preds.get(&w).unwrap_or(&empty) {
                            if body.insert(pred) {
                                worklist.push(pred);
                            }
                        }
                    }
                }
                bodies
                    .entry(header)
                    .and_modify(|existing| existing.extend(body.iter().copied()))
                    .or_insert(body);
            }
        }
    }
    for body in bodies.values() {
        for block in body {
            if let Some(d) = depths.get_mut(block.0 as usize) {
                *d = d.saturating_add(1);
            }
        }
    }
    depths
}

fn x86_isel_to_regalloc(func: &X86ISelFunction) -> Result<RegAllocFunction, X86PipelineError> {
    let block_loop_depths = x86_block_loop_depths(func);
    let mut ra_insts: Vec<RegAllocInst> = Vec::new();
    let max_block_id = func
        .block_order
        .iter()
        .map(|block| block.0 as usize)
        .max()
        .unwrap_or(0);
    let mut ra_blocks: Vec<Option<RegAllocBlock>> = if func.block_order.is_empty() {
        Vec::new()
    } else {
        vec![None; max_block_id + 1]
    };
    let mut seen_blocks = HashSet::new();

    // First pass: convert blocks and instructions.
    for blk in &func.block_order {
        if !seen_blocks.insert(blk.0) {
            return Err(X86PipelineError::RegAlloc(format!(
                "duplicate x86 block {} in block order",
                blk.0
            )));
        }
        let isel_block = func.blocks.get(blk).ok_or_else(|| {
            X86PipelineError::RegAlloc(format!("block {} not found in function", blk.0))
        })?;

        let mut inst_ids: Vec<InstId> = Vec::new();

        for isel_inst in &isel_block.insts {
            let inst_id = InstId(ra_insts.len() as u32);
            inst_ids.push(inst_id);

            let opcode = x86_regalloc_opcode_for_isel_inst(isel_inst);
            let flags = isel_inst.flags;

            let mut defs: Vec<RegAllocOperand> = Vec::new();
            let mut uses: Vec<RegAllocOperand> = Vec::new();
            let mut implicit_defs: Vec<trust_cg_regalloc::PReg> = Vec::new();
            let mut implicit_uses: Vec<trust_cg_regalloc::PReg> = Vec::new();

            for (i, op) in isel_inst.operands.iter().enumerate() {
                let access = x86_operand_access(isel_inst, i);
                match op {
                    X86ISelOperand::VReg(v) => {
                        let ra_op = RegAllocOperand::VReg(*v);
                        if access.is_def {
                            defs.push(ra_op.clone());
                        }
                        if access.is_use {
                            uses.push(ra_op);
                        }
                    }
                    X86ISelOperand::PReg(x86_preg) => {
                        // Physical registers go to implicit defs/uses.
                        if let Some(preg) = x86_fixed_operand_to_preg(*x86_preg) {
                            if access.is_def {
                                push_unique_preg(&mut implicit_defs, preg);
                            }
                            if access.is_use {
                                push_unique_preg(&mut implicit_uses, preg);
                            }
                        }
                    }
                    X86ISelOperand::Imm(imm) => {
                        uses.push(RegAllocOperand::Imm(*imm));
                    }
                    X86ISelOperand::FImm(fimm) => {
                        uses.push(RegAllocOperand::FImm(*fimm));
                    }
                    X86ISelOperand::Block(b) => {
                        uses.push(RegAllocOperand::Block(BlockId(b.0)));
                    }
                    X86ISelOperand::CondCode(_cc) => {
                        // Condition codes are encoded in the opcode for the
                        // regalloc's purposes — store as Imm(0) placeholder.
                        uses.push(RegAllocOperand::Imm(0));
                    }
                    X86ISelOperand::Symbol(_s) => {
                        // Symbols are relocation targets, not register operands.
                        uses.push(RegAllocOperand::Imm(0));
                    }
                    X86ISelOperand::StackSlot(slot) => {
                        uses.push(RegAllocOperand::StackSlot(StackSlotId(*slot)));
                    }
                    X86ISelOperand::ConstPoolEntry(idx) => {
                        // Constant pool entry index — treated as an immediate
                        // for register allocation purposes.
                        uses.push(RegAllocOperand::Imm(*idx as i64));
                    }
                    X86ISelOperand::JumpTableIndex(idx) => {
                        // Jump-table index — a compile-time constant, treated as an
                        // immediate for register allocation (like ConstPoolEntry).
                        uses.push(RegAllocOperand::Imm(i64::from(*idx)));
                    }
                    X86ISelOperand::MemAddr { base, disp } => {
                        add_x86_memaddr_regalloc_uses(base, *disp, &mut uses, &mut implicit_uses);
                    }
                    X86ISelOperand::SibMemAddr {
                        base,
                        index,
                        scale,
                        disp,
                    } => {
                        add_x86_sib_memaddr_regalloc_uses(
                            base,
                            index,
                            *scale,
                            *disp,
                            &mut uses,
                            &mut implicit_uses,
                        );
                    }
                }
            }

            // Add call clobbers as implicit defs for call instructions.
            if flags.is_call() {
                let clobbers = trust_cg_regalloc::x86_64_caller_saved_regs();
                for preg in clobbers {
                    push_unique_preg(&mut implicit_defs, preg);
                }
                // Model the call's argument registers as implicit USES. The ISel
                // populated `call_arg_regs` with every physical register written by
                // the arg-setup moves immediately preceding the call (the SysV /
                // Windows outgoing-argument registers, the variadic AL count, and
                // the `sret` pointer). Without these, the arg-setup `mov RDI, vN`
                // looks like a dead def (nothing reads RDI before the call's
                // clobber), so the allocator may reuse RDI for an unrelated value
                // still live across the setup span and clobber a populated argument
                // register before the call (MISCOMPILE #53). Marking them as uses
                // keeps each argument register live from its setup move to the call.
                for arg in &isel_inst.call_arg_regs {
                    // Liveness is width-agnostic: regalloc consumes only the
                    // register root; the per-arg `read_bits` width is TV-5's.
                    push_unique_x86_preg(&mut implicit_uses, arg.reg);
                }
            }

            add_x86_fixed_implicit_operands(isel_inst, &mut implicit_defs, &mut implicit_uses);

            // NOTE: no `tied_operands` are stamped here. `is_two_address_opcode`
            // matches raw ModRM byte constants (0x01/0x81/...) but is fed
            // X86Opcode ENUM ORDINALS (`x86_regalloc_opcode_for_isel_inst`
            // returns `inst.opcode as u16`), so it spuriously tied producers
            // like AddRI(ordinal 1)/Idiv(ordinal 9). No allocator reads
            // `tied_operands` except the coalescer, where a non-empty entry
            // REFUSES the sound kill-at-def loop-carried latch merge; the real
            // two-address constraint is enforced post-RA by `is_x86_two_address_rr`.
            ra_insts.push(RegAllocInst {
                opcode,
                defs,
                uses,
                implicit_defs,
                implicit_uses,
                tied_operands: Vec::new(),
                flags,
            });
        }

        // Convert successors to BlockId.
        let succs: Vec<BlockId> = isel_block.successors.iter().map(|b| BlockId(b.0)).collect();

        ra_blocks[blk.0 as usize] = Some(RegAllocBlock {
            insts: inst_ids,
            preds: Vec::new(), // Filled in second pass.
            succs,
            // Natural-loop depth on the ISel CFG: spill weights scale each
            // use/def by 10^depth, so hot-loop values out-prioritize the
            // single-use temps that used to evict them (matmul's base-pointer
            // reloads). See `x86_block_loop_depths`.
            loop_depth: block_loop_depths.get(blk.0 as usize).copied().unwrap_or(0),
        });
    }

    // Second pass: compute predecessors from successor info.
    for &src in &func.block_order {
        let src_idx = src.0 as usize;
        let Some(src_block) = ra_blocks.get(src_idx).and_then(Option::as_ref) else {
            continue;
        };
        let succs: Vec<BlockId> = src_block.succs.clone();
        for succ in &succs {
            let dst_idx = succ.0 as usize;
            if let Some(Some(dst_block)) = ra_blocks.get_mut(dst_idx) {
                let pred_bid = BlockId(src.0);
                if !dst_block.preds.contains(&pred_bid) {
                    dst_block.preds.push(pred_bid);
                }
            }
        }
    }

    let block_order: Vec<BlockId> = func
        .block_order
        .iter()
        .map(|block| BlockId(block.0))
        .collect();
    let entry_block = block_order.first().copied().unwrap_or(BlockId(0));
    let blocks: Vec<RegAllocBlock> = ra_blocks
        .into_iter()
        .enumerate()
        .map(|(idx, block)| {
            block.ok_or_else(|| {
                X86PipelineError::RegAlloc(format!(
                    "x86 block ids must be contiguous for regalloc replay; missing block {}",
                    idx
                ))
            })
        })
        .collect::<Result<_, _>>()?;

    let mut stack_slots = BTreeMap::new();
    for (idx, slot) in func.stack_slots.iter().enumerate() {
        stack_slots.insert(
            StackSlotId(idx as u32),
            RegAllocStackSlot::from(&slot.to_ir_stack_slot()),
        );
    }

    Ok(RegAllocFunction {
        name: func.name.clone(),
        insts: ra_insts,
        blocks,
        block_order,
        entry_block,
        next_vreg: func.next_vreg,
        next_stack_slot: func.stack_slots.len() as u32,
        stack_slots,
    })
}

/// The x86-64 compilation pipeline.
///
/// Orchestrates: ISel output -> regalloc -> frame lowering -> encoding -> object file.
/// Supports output to raw bytes, ELF, or Mach-O object files.
pub struct X86Pipeline {
    pub config: X86PipelineConfig,
}

impl X86Pipeline {
    /// Create a new pipeline with the given configuration.
    pub fn new(config: X86PipelineConfig) -> Self {
        Self { config }
    }

    /// Create a pipeline with default configuration (raw code bytes, with frame).
    pub fn default_config() -> Self {
        Self::new(X86PipelineConfig::default())
    }

    #[cfg(test)]
    fn default_x86_pass_manager() -> trust_cg_opt::X86PassManager {
        Self::x86_o2_pass_manager()
    }

    fn x86_o1_pass_manager() -> trust_cg_opt::X86PassManager {
        Self::x86_o1_pass_manager_with_branch_layout(x86_branch_layout_enabled())
    }

    fn x86_o1_pass_manager_with_branch_layout(branch_layout: bool) -> trust_cg_opt::X86PassManager {
        // O1 is the production policy the rustc backend selects. It runs the
        // verified local cleanups (peephole + DCE) plus two loop/dataflow wins:
        //
        //   * LICM hoists provably loop-invariant, flag-free, single-def,
        //     non-trapping computations (chiefly `mov reg, imm` constant
        //     materializations) into a proven natural loop preheader so they
        //     run once instead of every iteration.
        //   * Copy-propagation rewrites uses of `mov`-copied vregs to their
        //     source, exposing the copies to DCE.
        //
        // LICM runs first so the copies it relocates and the now-shorter loop
        // body are exposed to copy-prop and DCE. Both passes are individually
        // verified and only ever delete or relocate provably-equivalent work,
        // so they are sound to run at the conservative O1 level. const-fold and
        // CSE remain O2-only to keep O1's surface minimal.
        //
        // If-conversion (OPT-11) runs after DCE (so copy-prop/DCE have
        // collapsed the diamond arms to their essential mov) and BEFORE branch
        // layout — it deletes convertible value-select diamonds entirely, so
        // branch layout only sees the two-way exits that survive. It is
        // verdict-preserving by construction (no speculation; every applied cc
        // inversion admitted by the same exhaustive `CondCodeInversionValidator`
        // proof, via `admit_x86_ifconv_cc_inversion`). Kill switch:
        // `TCG_NO_IFCONVERT=1`.
        //
        // Branch layout (OPT-8) runs LAST so it sees the final block shapes:
        // it is layout-only (in-place `jcc/jmp` pair swaps; every applied cc
        // inversion is admitted by an exhaustive per-cc equivalence proof via
        // `admit_x86_cc_inversion`), hence sound at O1. Kill switch:
        // `TCG_NO_BRANCH_LAYOUT=1`.
        let mut pm = trust_cg_opt::X86PassManager::new()
            .with_pass(Box::new(
                trust_cg_opt::X86LoopInvariantCodeMotion::pure_only(),
            ))
            .with_pass(Box::new(trust_cg_opt::X86CopyPropagation))
            .with_pass(Box::new(trust_cg_opt::X86Peephole))
            .with_pass(Box::new(trust_cg_opt::X86DeadCodeElimination));
        if x86_if_convert_enabled() {
            pm = pm.with_pass(Box::new(trust_cg_opt::X86IfConvert::new(
                admit_x86_ifconv_cc_inversion,
            )));
        }
        if branch_layout {
            pm = pm.with_pass(Box::new(trust_cg_opt::X86BranchLayout::with_config(
                admit_x86_cc_inversion,
                x86_branch_layout_config(),
            )));
        }
        pm
    }

    fn x86_o2_pass_manager() -> trust_cg_opt::X86PassManager {
        Self::x86_o2_pass_manager_with_branch_layout(x86_branch_layout_enabled())
    }

    fn x86_o2_pass_manager_with_branch_layout(branch_layout: bool) -> trust_cg_opt::X86PassManager {
        // LICM runs first so the loop-invariant constant materializations it
        // hoists into the preheader are exposed to copy-prop/CSE/DCE, and the
        // now-shorter loop body is cleaned up by the subsequent passes. LICM is
        // strictly subtractive inside loops (it only relocates pure, flag-free,
        // single-def, non-trapping computations to a proven natural preheader),
        // so placing it ahead of the local cleanups is sound and maximizes the
        // win. See `trust_cg_opt::x86_licm` for the full safety argument.
        // If-conversion (OPT-11) after DCE, before branch layout — see
        // `x86_o1_pass_manager`. Branch layout (OPT-8) runs last.
        //
        // The conservative SSE2 integer vectorizer (OPT-12) runs FIRST, on the
        // raw post-ISel loop shape, before LICM/copy-prop/CSE rename or relocate
        // the loop body. It only ever rewrites a loop whose legality is provable
        // by construction; anything else stays scalar. Kill switch:
        // `TCG_NO_VECTORIZE`.
        //
        // Strength reduction (OPT-3a) runs right after LICM: LICM has hoisted
        // the loop-invariant constant materializations (the stride vregs) into
        // preheaders, giving the pass its canonical `imul iv, invariant`
        // shape, and the flag-free `mov` it leaves behind (plus the recurrence
        // it seeds) is then exposed to const-fold/copy-prop/CSE/peephole/DCE
        // for cleanup. Every applied instance is gated on the per-(width,
        // step) recurrence proof via `admit_x86_strength_reduce_recurrence`.
        // Kill switch: `TCG_NO_STRENGTH_REDUCE`.
        let mut pm = trust_cg_opt::X86PassManager::new();
        if x86_vectorize_enabled() {
            pm = pm.with_pass(Box::new(trust_cg_opt::X86Vectorize));
        }
        // The invariant stack-slot load tier (O2+ only; kill switch
        // `TCG_NO_LICM_LOADS`) additionally hoists provably invariant,
        // provably non-trapping fixed-slot loads out of loops whose entire
        // store set is statically attributed to disjoint slots — the vec
        // ptr/len lane re-loads of an indexing loop are the canonical win.
        // See `trust_cg_opt::x86_licm` (module docs, "Invariant-load tier")
        // for the full safety argument.
        // SROA runs BEFORE LICM: it promotes non-escaped stack slots (the
        // memory-backed slice fat-pointers) to SSA vregs, turning the
        // per-iteration `leaq/movq` slot reloads into plain register values that
        // the subsequent copy-prop/CSE/DCE clean up. This is exactly the win
        // LICM's load tier cannot get when an in-loop heap store (`y[i] = ...`)
        // is present, because a non-escaped slot cannot be aliased whereas LICM
        // must conservatively account for every store. Kill switch:
        // `TCG_NO_X86_SROA`. See `trust_cg_opt::x86_sroa` for the safety
        // argument (strict non-escape allowlist, dominating-store forwarding).
        if x86_sroa_enabled() {
            pm = pm.with_pass(Box::new(
                trust_cg_opt::X86ScalarReplacementOfAggregates::new(),
            ));
        }
        let licm = if x86_licm_load_hoisting_enabled() {
            trust_cg_opt::X86LoopInvariantCodeMotion::with_invariant_load_hoisting()
                .with_flag_arith(x86_licm_flag_arith_enabled())
        } else {
            trust_cg_opt::X86LoopInvariantCodeMotion::pure_only()
        };
        let mut pm = pm.with_pass(Box::new(licm));
        if x86_strength_reduce_enabled() {
            pm = pm.with_pass(Box::new(trust_cg_opt::X86StrengthReduce::new(
                admit_x86_strength_reduce_recurrence,
            )));
        }
        // Full unrolling of small constant-trip loops (X9 slice 1, OPT-IN
        // `TCG_X86_UNROLL=1`). After LICM/strength-reduce (canonicalized IVs),
        // before const-fold/copy-prop/CSE/peephole/BCE/DCE so the replicated
        // straight-line body — whose IV chain the pass seeds with its proven
        // initial constant — collapses in the same pass-manager run; before
        // LoopRotate so the recognizer sees the frontend's top-tested shape.
        if x86_unroll_enabled() {
            pm = pm.with_pass(Box::new(trust_cg_opt::X86LoopUnroll));
        }
        let mut pm = pm.with_pass(Box::new(trust_cg_opt::X86ConstantFolding));
        // Const-index guard elimination: deletes guard pseudos whose
        // assertion is statically true by the SAME block-local constant
        // authority const-fold just applied (the unrolled-body shape). Runs
        // only under the unroll opt-in and respects the BCE kill switch.
        if x86_unroll_enabled() && x86_bce_enabled() {
            pm = pm.with_pass(Box::new(trust_cg_opt::X86ConstGuardElim));
        }
        // Straight-line block merging (`TCG_NO_X86_BLOCK_MERGE` to opt out).
        // Placed HERE deliberately, ahead of the copy-prop / CSE / peephole
        // cluster and ahead of if-conversion:
        //   * those passes are BLOCK-LOCAL, so merging widens their window;
        //   * `X86IfConvert` requires each diamond arm to be exactly ONE block,
        //     and a trivial pass-through block in an arm makes the arms look
        //     like they do not reconverge (this is what kept b1_mispredict's
        //     rotate diamond a mispredicting branch).
        // Measured 123 mergeable pairs across all 18 beat-llvm programs.
        let mut pm = pm
            .with_pass(Box::new(trust_cg_opt::X86BlockMerge::new()))
            .with_pass(Box::new(trust_cg_opt::X86CopyPropagation))
            .with_pass(Box::new(trust_cg_opt::X86CommonSubexpressionElimination))
            .with_pass(Box::new(trust_cg_opt::X86Peephole));
        // Dominated-identical-compare bounds-check elimination (safety-critical,
        // sound by construction). Runs AFTER the peephole's cmp+setcc+zero-test
        // +Jcc fusion, which collapses the frontend's materialized-boolean
        // bounds-check branches back into the direct `Cmp; Jcc` diamond form this
        // pass matches; and before DCE so any residue is cleaned. Only removes a
        // bounds-check trap edge when a dominating IDENTICAL compare proves it
        // dead; keeps the check on any doubt. Kill switch: `TCG_NO_X86_BCE`.
        if x86_bce_enabled() {
            pm = pm.with_pass(Box::new(trust_cg_opt::X86BoundsCheckElimination::new()));
        }
        let mut pm = pm.with_pass(Box::new(trust_cg_opt::X86DeadCodeElimination));
        // Loop rotation (task #72 pass 1): thread latch `Jmp header` through
        // pure-test headers so hot loops bottom-test (one branch/iteration
        // instead of test+Jcc+Jmp). Runs after DCE so headers are in their
        // final minimal shape; before if-convert/branch-layout which consume
        // the rotated CFG. Default-on at O2/O3 after the staged differential
        // gate; `TCG_NO_X86_ROTATE` is the forensic opt-out.
        pm = pm.with_pass(Box::new(trust_cg_opt::X86LoopRotate));
        // Branchless conditional-swap for sort inner loops (task #77,
        // DEFAULT-ON; `TCG_NO_X86_CMOV_SWAP` is the forensic opt-out):
        // converts the compare-and-swap store-pair diamond
        // (`if a[j-1] > a[j] { swap }`) into CMOVcc min/max plus an
        // unconditional same-value store pair. Runs after LoopRotate (the
        // recognizer matches the rotated single-pred guard chain) and before
        // if-convert/branch-layout, which consume the simplified CFG. Flipped
        // default-on after the opt-in soak: b06 -24% measured + independently
        // reproduced (gap 2.10x -> 1.58x), all other benches noise-neutral,
        // 120-program sort fuzz + a 126-binary adversarial near-miss corpus
        // all checksum==LLVM, proofs-ON compile+run verified. See
        // `trust_cg_opt::x86_cmov_swap` (module docs) for the recognizer's
        // fail-closed conditions and the soundness argument.
        if crate::env_lock::var_os("TCG_NO_X86_CMOV_SWAP").is_none() {
            pm = pm.with_pass(Box::new(trust_cg_opt::X86CmovSwap::new()));
        }
        if x86_if_convert_enabled() {
            pm = pm.with_pass(Box::new(trust_cg_opt::X86IfConvert::new(
                admit_x86_ifconv_cc_inversion,
            )));
        }
        if branch_layout {
            pm = pm.with_pass(Box::new(trust_cg_opt::X86BranchLayout::with_config(
                admit_x86_cc_inversion,
                x86_branch_layout_config(),
            )));
        }
        // Two-address pre-expansion (OPT-IN `TCG_X86_TWOADDR_EXPAND`): the LAST
        // pass — mechanically expands `Op d,a,b` -> `MovRR d,a; Op d,d,b` so the
        // proven regalloc coalescer folds the copy (`d<-a`) when they don't
        // interfere, eliminating the redundant post-RA two-address `MovRR`. Runs
        // after every other pass (nothing should optimize the `[d,d,b]` form) and
        // its copies must be in the ISel stream the regalloc replay reconstructs
        // from. Added ONLY under the opt-in gate so the default pass schedule is
        // byte-identical (the `optimization_passes_run == 16` pin holds). See
        // `trust_cg_opt::x86_two_addr_expand`.
        if crate::env_lock::var_os("TCG_X86_TWOADDR_EXPAND").is_some() {
            pm = pm.with_pass(Box::new(trust_cg_opt::X86TwoAddressExpand));
        }
        pm
    }

    fn x86_pass_manager_for_opt_level(
        opt_level: trust_cg_opt::OptLevel,
    ) -> trust_cg_opt::X86PassManager {
        match opt_level {
            trust_cg_opt::OptLevel::O0 => trust_cg_opt::X86PassManager::new(),
            trust_cg_opt::OptLevel::O1 => Self::x86_o1_pass_manager(),
            trust_cg_opt::OptLevel::O2
            | trust_cg_opt::OptLevel::Os
            | trust_cg_opt::OptLevel::O3 => Self::x86_o2_pass_manager(),
        }
    }

    /// Run the x86 optimization policy selected by this pipeline's opt level.
    ///
    /// O0 intentionally runs no machine optimization passes. O1 runs only the
    /// local peephole cleanup plus DCE. O2 and Os run the current production
    /// order once. O3 runs that same order to a bounded fixpoint.
    pub fn run_x86_optimization_passes(
        &self,
        func: &mut X86ISelFunction,
    ) -> trust_cg_opt::X86PassStats {
        let stats = if self.config.opt_level == trust_cg_opt::OptLevel::O0 {
            trust_cg_opt::X86PassStats::default()
        } else {
            let mut pass_manager = Self::x86_pass_manager_for_opt_level(self.config.opt_level);
            match self.config.opt_level {
                trust_cg_opt::OptLevel::O0 => trust_cg_opt::X86PassStats::default(),
                trust_cg_opt::OptLevel::O1
                | trust_cg_opt::OptLevel::O2
                | trust_cg_opt::OptLevel::Os => pass_manager.run_once_with_stats(func),
                trust_cg_opt::OptLevel::O3 => {
                    pass_manager.run_to_fixpoint(func, TCG_X86_O3_FIXPOINT_MAX_ITERATIONS)
                }
            }
        };

        // LEVER 1 (X1): x86 CEGIS superoptimization. Disabled by default; the
        // `TCG_CEGIS_X86=<secs>` gate opts in. When disabled this is a strict
        // no-op, so the emitted bytes are byte-identical to a build without it.
        // Every rewrite it commits is proven QF_BV-equivalent by
        // `trust_cg_verify::CegisLoop::verify`; on timeout/error/not-equivalent
        // the original instructions are kept (fail-closed).
        run_x86_cegis_superopt_if_enabled(func);

        stats
    }

    #[cfg(test)]
    fn run_default_x86_passes(func: &mut X86ISelFunction) {
        let mut pass_manager = Self::default_x86_pass_manager();
        let _ = pass_manager.run_once(func);
    }

    /// Run the full register allocator (linear scan or greedy) on an x86-64
    /// ISel function, returning an `X86RegAssignment` compatible with the rest
    /// of the pipeline.
    ///
    /// This converts the ISel function to the target-independent
    /// `RegAllocFunction`, runs the full allocator pipeline (liveness, phi
    /// elimination, coalescing, allocation, spill code), and translates the
    /// result back to x86-64 physical registers.
    fn run_full_regalloc(
        &self,
        func: &mut X86ISelFunction,
        strategy: AllocStrategy,
    ) -> Result<X86RegAssignment, X86PipelineError> {
        // 1. Convert X86ISelFunction -> RegAllocFunction.
        let mut ra_func = x86_isel_to_regalloc(func)?;

        // 2. Collect arg register hints from MOV vreg, PReg(X) patterns.
        //
        // When ISel emits `MOV v0, RDI` (load arg from physical register),
        // we hint the allocator to assign v0 -> RDI. This prevents the
        // allocator from assigning other vregs to arg registers (RDI, RSI,
        // RDX, RCX, R8, R9) before they are read, which would clobber the
        // argument values. (Fixes #300: arg register interference bug.)
        let mut hints: BTreeMap<VReg, Vec<trust_cg_regalloc::PReg>> = BTreeMap::new();
        for block in func.block_order.iter() {
            if let Some(mblock) = func.blocks.get(block) {
                for inst in &mblock.insts {
                    let is_mov = matches!(inst.opcode, X86Opcode::MovRR | X86Opcode::MovsdRR);
                    if is_mov
                        && inst.operands.len() >= 2
                        && let (X86ISelOperand::VReg(dst), X86ISelOperand::PReg(src_preg)) =
                            (&inst.operands[0], &inst.operands[1])
                        && let Some(preg) = x86_to_preg(*src_preg)
                    {
                        hints.entry(*dst).or_default().push(preg);
                    }
                }
            }
        }

        // 3. Build config based on requested strategy, with hints.
        let mut config = match strategy {
            AllocStrategy::LinearScan => x86_64_alloc_config(),
            AllocStrategy::Greedy => x86_64_greedy_alloc_config(),
        };
        apply_x86_abi_allocatable_regs(&mut config, self.config.call_abi);
        config.hints = hints;
        // Snapshot the FULL pool before the scratch reservation, so the
        // stats-only counterfactual probe below can answer "would this function
        // still spill with all 14 GPRs?" without a second build.
        let unreserved_allocatable_regs = config.allocatable_regs.clone();
        reserve_x86_spill_scratch_regs(&mut config, self.config.call_abi);
        // x86 replays target-independent live-range split copies after
        // allocation for straight-line CFGs, forward acyclic CFGs, safe
        // edge-copy joins, and acyclic non-linear joins repaired with
        // join-block split copies, including critical-edge joins that do not
        // require CFG topology mutation. Loop-containing functions without
        // loop-carried multi-def vregs are admitted so greedy can use safe
        // preheader/entry splits; actual loop-carried, loop-body, and backedge
        // copy placements still fail closed. Missing edge terminators stay
        // fail-closed here.
        // Remat stays disabled because its stream mutations are not yet
        // replayed into the x86 ISel stream.
        config.enable_coalescing = true;
        config.enable_remat = false;
        config.enable_critical_edge_splitting = false;
        // Live-range splitting is admitted only for CFG shapes whose split-copy
        // replay is sound. In particular a function with BOTH a call and a join
        // block (the `?`-operator diamond) is rejected: the greedy splitter's
        // join-block split-copy placement is unsound there — a value live across
        // the call AND the join (e.g. a memory-aggregate return-slot pointer) can
        // lose its split copy on the taken path, so the post-call reload reads a
        // stale stack slot and the program faults (SIGBUS/SIGSEGV) or miscompiles.
        // Rejected shapes fall back to the plain greedy allocator (spill instead
        // of split), which is always sound. See `x86_regalloc_splitting_cfg_diagnostic`
        // and the differential `try_operator_x86.rs` tests.
        config.enable_splitting = x86_regalloc_splitting_supported_cfg(&ra_func);
        config.enable_spill_code = false;
        config.enable_spill_slot_reuse = false;
        let original_ra_func = ra_func.clone();

        // 4. Run the full allocator pipeline.
        let mut result = trust_cg_regalloc::allocate(&mut ra_func, &config)
            .map_err(|e| X86PipelineError::RegAlloc(format!("{:?}", e)))?;

        // LEVER 1, INVERTED (opt-in: `TCG_X86_RA_FULL_POOL`).
        //
        // `reserve_x86_spill_scratch_regs` strips R10/R11 from EVERY x86
        // function, so the pool is 12 wide where LLVM allocates 14. This retries
        // a SPILLING function on the full pool.
        //
        // ORDER IS INVERTED ON PURPOSE. The original plan ran the 14-wide pass
        // FIRST and kept it when it happened not to spill — which perturbs the
        // allocation of every zero-spill function in the corpus for no mechanism
        // reason, making the lever unmeasurable by construction (any delta mixes
        // real spill removal with pure perturbation). Running today's allocation
        // first means the common path is BYTE-IDENTICAL to current output and
        // costs nothing; only a function that already spills pays a second pass.
        //
        // THE KEEP CONDITION IS A SOUNDNESS CONSTRAINT, NOT A HEURISTIC. The
        // unreserved allocation hands out R10/R11 — exactly the scratch registers
        // `materialize_x86_spills` needs to emit spill/reload code. So the retry
        // may be kept ONLY when it spills NOTHING, because `materialize_x86_spills`
        // early-returns on an empty spill set and never demands the scratch
        // (pipeline.rs:11830). A retry that still spills is DISCARDED, however
        // much it improved the count.
        //
        // MEASURED, before building: of the corpus loss cluster only b01 reaches
        // zero (1 -> 0); b05 35 -> 32, b07 21 -> 20, b18 20 -> 19, b06 8 -> 8,
        // b11 3 -> 1 all still spill and are therefore all DISCARDED by the keep
        // condition. The lever is sound and correct, and fires almost never —
        // which is why it stays default-OFF. Flip it on only against a paired,
        // same-dylib A/B, never a cross-sweep comparison.
        if x86_ra_full_pool_enabled() && !result.spills.is_empty() {
            let reserved = std::mem::replace(
                &mut config.allocatable_regs,
                unreserved_allocatable_regs.clone(),
            );
            let mut retry_func = original_ra_func.clone();
            if let Ok(retry) = trust_cg_regalloc::allocate(&mut retry_func, &config)
                && retry.spills.is_empty()
            {
                // Sound: no spill code will be materialized, so no scratch is
                // demanded and R10/R11 being allocatable is unobservable.
                ra_func = retry_func;
                result = retry;
            }
            config.allocatable_regs = reserved;
        }

        // COUNTERFACTUAL PROBE (stats-only, `TCG_RA_SPILL_STATS`). Answers the
        // one question the R10/R11 reservation lever rests on: of the functions
        // that spill under the reserved 12-wide pool, how many would STOP
        // spilling with the full 14?
        //
        // Run on a CLONE with the result DISCARDED — nothing here reaches the
        // emitted object, so a mis-modelled unreserved allocation cannot
        // miscompile. That is the whole point of measuring this way instead of
        // commenting out the reservation in a throwaway build and running the
        // binaries: the counterfactual allocation is exactly the one that would
        // be unsound to EXECUTE (it hands out R10/R11, which spill
        // materialization needs as scratch).
        if x86_ra_spill_stats_enabled() && !result.spills.is_empty() {
            // `AllocConfig` is not Clone, so swap the pool in and restore it —
            // exactly reversible, and `config` is not borrowed here (the
            // allocate() call above has returned).
            let reserved = std::mem::replace(
                &mut config.allocatable_regs,
                unreserved_allocatable_regs.clone(),
            );
            let mut probe_func = original_ra_func.clone();
            let counterfactual = trust_cg_regalloc::allocate(&mut probe_func, &config)
                .map(|r| r.spills.len().to_string())
                .unwrap_or_else(|e| format!("ERR({e:?})"));
            config.allocatable_regs = reserved;
            eprintln!(
                "[trust-cg-ra-counterfactual] func={} spilled_at_12={} spilled_at_14={}",
                ra_func.name,
                result.spills.len(),
                counterfactual,
            );
        }
        let reported_spill_slots: HashSet<StackSlotId> =
            result.spills.iter().map(|spill| spill.slot).collect();
        let mut spill_plan = X86SpillPlan::default();
        for spill in &result.spills {
            let slot = ra_func.stack_slots.get(&spill.slot).ok_or_else(|| {
                X86PipelineError::RegAlloc(format!(
                    "x86-64 spill v{} references missing stack slot {}",
                    spill.vreg.id, spill.slot.0
                ))
            })?;
            spill_plan.slots.push(X86SpillSlot {
                vreg: spill.vreg,
                size: slot.size,
                align: slot.align,
            });
        }
        replay_x86_regalloc_stream_mutations(
            func,
            &original_ra_func,
            &ra_func,
            &reported_spill_slots,
        )?;

        // 5. Translate PReg -> X86PReg.
        let mut allocation: HashMap<VReg, X86PReg> = translate_allocation(&result.allocation)
            .into_iter()
            .collect();
        bind_x86_dead_volatile_load_defs(func, &mut allocation, self.config.call_abi)?;

        // 6. Determine which callee-saved registers were used.
        let (used_callee_saved, used_callee_saved_xmms) =
            x86_used_callee_saved_from_allocation(self.config.call_abi, &allocation);

        Ok(X86RegAssignment {
            allocation,
            used_callee_saved,
            used_callee_saved_xmms,
            num_spills: 0,
            spill_plan,
        })
    }

    /// Compile an x86-64 ISel function to machine code bytes.
    ///
    /// This is the main entry point. It takes an `X86ISelFunction` (post-ISel,
    /// pre-regalloc) and returns encoded machine code bytes, optionally
    /// wrapped in an ELF, Mach-O, or COFF object file.
    pub fn compile_function(&self, func: &X86ISelFunction) -> Result<Vec<u8>, X86PipelineError> {
        validate_x86_function_layout(func)?;
        let mut func = func.clone();
        let _ = self.run_x86_optimization_passes(&mut func);
        self.compile_function_after_x86_passes(&func)
    }

    fn compile_function_after_x86_passes(
        &self,
        func: &X86ISelFunction,
    ) -> Result<Vec<u8>, X86PipelineError> {
        let (code, _) = self.compile_function_after_x86_passes_with_pressure_evidence(func)?;
        Ok(code)
    }

    /// Compile an x86-64 ISel function and return final regalloc pressure
    /// evidence alongside the emitted bytes.
    pub fn compile_function_with_regalloc_pressure_evidence(
        &self,
        func: &X86ISelFunction,
    ) -> Result<(Vec<u8>, X86RegallocPressureEvidence), X86PipelineError> {
        validate_x86_function_layout(func)?;
        let mut func = func.clone();
        let _ = self.run_x86_optimization_passes(&mut func);
        self.compile_function_after_x86_passes_with_pressure_evidence(&func)
    }

    fn compile_function_after_x86_passes_with_pressure_evidence(
        &self,
        func: &X86ISelFunction,
    ) -> Result<(Vec<u8>, X86RegallocPressureEvidence), X86PipelineError> {
        validate_x86_function_layout(func)?;
        reject_unwired_x86_eh_output(&self.config, func)?;
        let mut func = func.clone();
        expand_x86_vector_bool_selects(&mut func, self.config.target_features)?;
        expand_x86_vector_mask_extracts(&mut func)?;
        expand_x86_generic_popcnts(&mut func, self.config.target_features)?;
        expand_x86_generic_ptest_zero_tests(&mut func, self.config.target_features);
        // Sentinel S5: expand any proof-only bounds-check carrier the kernel gate
        // did NOT delete into a real CMP+Jcc(AE)+UD2 runtime check. Runs before
        // regalloc so the synthetic trap block + large-bound vreg are allocated.
        expand_x86_bounds_check_carriers(&mut func)?;
        // Sentinel S5: likewise expand any surviving proof-only null-check carrier
        // into a real TEST+Jcc(E)+UD2 runtime null check (byte-identical to the
        // pre-S5 eager guard). Runs before regalloc so its synthetic trap block is
        // allocated/encoded normally.
        expand_x86_null_check_carriers(&mut func)?;
        // Sentinel S5: likewise expand any surviving proof-only div-by-zero-check
        // carrier into a real TEST+Jcc(E)+UD2 runtime div-by-zero check
        // (byte-identical to the pre-S5 eager guard). Runs before regalloc so its
        // synthetic trap block is allocated/encoded normally.
        expand_x86_div_zero_check_carriers(&mut func)?;
        // Sentinel S5: likewise expand any surviving proof-only shift-range-check
        // carrier into a real CMP+Jcc(AE)+UD2 runtime shift-range check
        // (byte-identical to the pre-S5 eager guard). Runs before regalloc so its
        // synthetic trap block is allocated/encoded normally.
        expand_x86_shift_range_check_carriers(&mut func)?;
        prune_unused_x86_stack_slots(&mut func);
        reject_unsupported_x86_isel(&func, self.config.target_features)?;

        // Phase 1: Register allocation (full greedy/linear-scan, or simplified).
        let assignment = match self.config.regalloc_mode {
            X86RegAllocMode::Simplified => {
                X86RegAssignment::assign_with_abi(&func, self.config.call_abi)?
            }
            X86RegAllocMode::Full(strategy) => self.run_full_regalloc(&mut func, strategy)?,
        };

        // Phase 1b: Resolve the formal-argument parallel copy (#497, #499).
        // Must run BEFORE fixup_two_address so the latter sees correct PRegs.
        let installed_spills = install_x86_spill_slots(&mut func, &assignment.spill_plan);
        let spill_stack_slot_count = installed_spills.len();
        fixup_formal_arg_parallel_copy(
            &mut func,
            &assignment.allocation,
            &installed_spills,
            self.config.call_abi,
        )?;
        let spill_evidence =
            materialize_x86_spills(&mut func, &installed_spills, self.config.call_abi)?;

        // Phase 2: Two-address fixup — insert MOV copies for dst != lhs.
        let two_address_fixup_copy_count =
            fixup_two_address(&mut func, &assignment.allocation, self.config.call_abi)?;

        // Phase 2b: Post-fixup redundant-`MovRR` coalescing (runtime perf). The
        // pre-RA interference coalescer cannot remove `movq %src,%dst` scratch
        // copies whose source and destination are both live (they interfere); a
        // value-aware block-local RENAME removes them. Soundness is carried by
        // the pass's own scan conditions; TV-5's dataflow validation (inside
        // `recheck_post_regalloc` below) fail-closes tied-site misroutes and
        // deleted bridges, and the Stage A captured-spec check inside this
        // wrapper compares the coalesced stream's full register value flow
        // against the post-fixup spec (WARN-only rollout). Skipped at O0 to
        // keep the unoptimized stream untouched.
        self.run_x86_movrr_coalesce_with_captured_spec(&mut func, &assignment.allocation)?;

        prepare_x86_windows_fixed_outgoing_frame(&self.config, &mut func);
        reject_windows_coff_without_unwind_metadata(&self.config, &func, &assignment)?;
        reject_windows_x64_frameless_non_leaf(&self.config, &func)?;

        // Phase 3: Resolve fixed stack slots and insert prologue/epilogue.
        let mut frame_metadata = None;
        let mut spill_disps: HashSet<i32> = HashSet::new();
        if self.config.emit_frame {
            let layout = compute_x86_stack_frame_layout(
                &func,
                assignment.used_callee_saved.len(),
                assignment.used_callee_saved_xmms.len(),
                assignment.num_spills,
            )?;
            frame_metadata = Some(X86FrameMetadata {
                callee_saved: assignment.used_callee_saved.clone(),
                callee_saved_xmms: assignment.used_callee_saved_xmms.clone(),
                xmm_save_offsets: layout.xmm_save_offsets.clone(),
                frame_size: layout.frame_size,
                has_dynamic_alloc: layout.has_dynamic_alloc,
            });
            spill_disps = x86_spill_slot_disps(&layout, assignment.num_spills);
            resolve_x86_stack_slots(&mut func, &layout)?;
            expand_x86_dynamic_stack_allocs(&mut func, &assignment.allocation)?;
            self.insert_prologue_epilogue(&mut func, &assignment, &layout);
        } else if function_has_x86_stack_slot_operands(&func)
            || function_has_x86_dynamic_stack_alloc_pseudos(&func)
        {
            return Err(X86PipelineError::FrameLowering(
                "x86-64 StackAddr requires frame lowering; emit_frame=false".to_string(),
            ));
        }

        // Phase 4: Resolve branch offsets.
        validate_x86_function_layout(&func)?;
        let branch_targets = collect_x86_branch_targets(&func);
        resolve_x86_branches(&mut func);

        // TV-4/TV-5: post-regalloc re-verification of the FINAL post-fixup
        // stream (structural + register dataflow).
        self.recheck_post_regalloc(&func, &assignment.allocation, &spill_disps)?;

        let machine_code = collect_x86_machine_code_evidence(&func, self.config.target_features);
        let instruction_count = count_x86_non_pseudo_insts(&func);

        // Phase 5: Encode all instructions (with constant pool fixup tracking).
        let (
            mut code,
            cp_fixups,
            call_fixups,
            global_ref_fixups,
            block_offsets,
            encoded_call_ranges,
            branch_fixups,
        ) = self.encode_function_with_all_fixups_and_block_metadata(
            &func,
            &assignment.allocation,
            &branch_targets,
        )?;
        let effective_format = effective_x86_output_format(&self.config);
        patch_x86_branch_fixups_to_block_offsets(&mut code, &block_offsets, branch_fixups)?;

        // The single-function Mach-O API uses the same exact final call ranges
        // and LSDA builder as module emission. Other formats were rejected at
        // entry by `reject_unwired_x86_eh_output`.
        let eh = x86_lsda_for_function(&func, &block_offsets, &encoded_call_ranges, code.len())?
            .map(|(personality, lsda_bytes)| X86EhData {
                personality,
                lsda_bytes,
            });
        let eh_aware_single_macho = eh.is_some() && effective_format == X86OutputFormat::MachO;

        if !eh_aware_single_macho && let Some(fixup) = call_fixups.first() {
            return Err(
                X86PipelineError::SymbolicDirectCallRequiresRelocationEmission {
                    function: func.name.clone(),
                    callee: fixup.callee.clone(),
                    format: effective_format,
                },
            );
        }
        if !eh_aware_single_macho && let Some(fixup) = global_ref_fixups.first() {
            return Err(x86_symbol_ref_unsupported(
                fixup.kind,
                func.name.clone(),
                fixup.symbol.clone(),
                match fixup.kind {
                    X86SymbolRefFixupKind::GlobalRef => {
                        "single-function emission has no in-module symbol table"
                    }
                    X86SymbolRefFixupKind::ExternRefGot => {
                        "single-function emission has no GOT/IAT symbol table"
                    }
                    X86SymbolRefFixupKind::TlsTlv => {
                        "single-function emission has no TLV symbol table"
                    }
                },
            ));
        }

        // Phase 5b: Build constant pool and fix up RIP-relative displacements.
        let mut coff_rdata_rel32_offsets = Vec::new();
        let const_pool_data = if !func.const_pool_entries.is_empty() {
            let (pool, isel_to_pool_idx) = build_x86_constant_pool(&func)?;
            let cp_bytes = pool.emit();

            // Fix up each RIP-relative reference.
            // Each fixup records: (offset_of_disp32_in_code, entry_index)
            if effective_format == X86OutputFormat::Coff {
                for (disp32_offset, entry_idx) in &cp_fixups {
                    let entry_offset =
                        x86_constant_pool_fixup_offset(&pool, &isel_to_pool_idx, *entry_idx)?;
                    let addend = i32::try_from(entry_offset).map_err(|_| {
                        X86PipelineError::ConstantPool(format!(
                            "COFF constant-pool entry offset {entry_offset} does not fit in REL32 addend"
                        ))
                    })?;
                    code[*disp32_offset..*disp32_offset + 4].copy_from_slice(&addend.to_le_bytes());
                    coff_rdata_rel32_offsets.push(*disp32_offset);
                }
            } else {
                // The constant pool is placed immediately after the code.
                let cp_start = code.len() as i64;

                // RIP-relative displacement = (cp_start + entry_offset) - fixup_offset - 4
                // (The -4 is because RIP points to the end of the instruction, i.e., past the disp32.)
                for (disp32_offset, entry_idx) in &cp_fixups {
                    let entry_offset =
                        x86_constant_pool_fixup_offset(&pool, &isel_to_pool_idx, *entry_idx)?;
                    let target = cp_start + entry_offset;
                    let rip_disp = target - (*disp32_offset as i64) - 4;
                    let disp_bytes = (rip_disp as i32).to_le_bytes();
                    code[*disp32_offset..*disp32_offset + 4].copy_from_slice(&disp_bytes);
                }
            }

            cp_bytes
        } else {
            Vec::new()
        };

        let evidence = X86RegallocPressureEvidence {
            spilled_vreg_count: assignment.spill_plan.slots.len(),
            spill_stack_slot_count,
            total_stack_slot_count: func.stack_slots.len(),
            spill_reload_count: spill_evidence.reload_count,
            spill_store_count: spill_evidence.store_count,
            two_address_fixup_copy_count,
            callee_saved_gpr_save_count: assignment.used_callee_saved.len(),
            callee_saved_xmm_save_count: assignment.used_callee_saved_xmms.len(),
            instruction_count,
            code_size_bytes: code.len(),
            machine_code,
        };
        let instruction_code_len = code.len();

        // Phase 6: Optionally wrap in object file format.
        match effective_format {
            X86OutputFormat::RawBytes => {
                // For raw bytes, append the constant pool after the code.
                if !const_pool_data.is_empty() {
                    code.extend_from_slice(&const_pool_data);
                }
                Ok((code, evidence))
            }
            X86OutputFormat::Elf => Ok((
                self.emit_elf_with_rodata(
                    &func.name,
                    &code,
                    &const_pool_data,
                    frame_metadata.as_ref(),
                )?,
                evidence,
            )),
            X86OutputFormat::MachO if eh.is_some() => {
                // Preserve EH authority by routing the one-function object
                // through the exact module emitter: it is the wired owner of
                // `__gcc_except_tab`, personality/LSDA symbols, zPLR FDEs, and
                // the corresponding call/global relocations.  Reusing it here
                // avoids a second, drifting single-function unwind writer.
                let mut combined_code = code;
                combined_code.extend_from_slice(&const_pool_data);
                let instruction_code_len = checked_x86_code_len(&func.name, instruction_code_len)?;
                let encoded = X86EncodedFunc {
                    name: func.name.clone(),
                    code_len: instruction_code_len,
                    const_pool_len: const_pool_data.len(),
                    const_pool_rdata_offset: 0,
                    const_pool_rel32_fixups: Vec::new(),
                    call_fixups,
                    global_ref_fixups,
                    text_offset: 0,
                    frame_metadata,
                    eh,
                };
                Ok((
                    self.emit_module_macho(&[encoded], &combined_code, &[])?,
                    evidence,
                ))
            }
            X86OutputFormat::MachO => Ok((
                self.emit_macho_with_rodata(
                    &func.name,
                    &code,
                    &const_pool_data,
                    frame_metadata.as_ref(),
                )?,
                evidence,
            )),
            X86OutputFormat::Coff => Ok((
                self.emit_coff_with_rodata(
                    &func.name,
                    &code,
                    &const_pool_data,
                    &coff_rdata_rel32_offsets,
                    if self.config.call_abi == X86CallAbi::WindowsX64 {
                        frame_metadata.as_ref()
                    } else {
                        None
                    },
                )?,
                evidence,
            )),
        }
    }

    /// Compile after running an x86 pass manager once on a cloned ISel function.
    ///
    /// This explicit hook lets tests and callers supply a custom x86 machine
    /// pipeline without mutating the caller-owned ISel function.
    pub fn compile_function_with_pass_manager(
        &self,
        func: &X86ISelFunction,
        pass_manager: &mut trust_cg_opt::X86PassManager,
    ) -> Result<Vec<u8>, X86PipelineError> {
        validate_x86_function_layout(func)?;
        let mut func = func.clone();
        let _ = pass_manager.run_once(&mut func);
        self.compile_function_after_x86_passes(&func)
    }

    /// Compile a single function to raw code bytes + constant-pool data +
    /// call fixups, without wrapping in any object file format.
    ///
    /// Used by [`Self::compile_module`] to assemble a multi-function
    /// Mach-O / ELF object with cross-function call relocations (#464).
    ///
    /// Returns `(code, const_pool_data, call_fixups, global_ref_fixups)`.
    /// The fixups reference offsets *within this function's local code*; the
    /// caller is responsible for adjusting them to the combined section offset.
    pub fn compile_function_with_fixups(
        &self,
        func: &X86ISelFunction,
    ) -> Result<(Vec<u8>, Vec<u8>, Vec<X86CallFixup>, Vec<X86GlobalRefFixup>), X86PipelineError>
    {
        reject_x86_eh_sidecar_drop(&self.config, func, "compile_function_with_fixups")?;
        let (code, const_pool_data, call_fixups, global_ref_fixups, _, _, _) =
            self.compile_function_with_fixups_and_frame(func)?;
        Ok((code, const_pool_data, call_fixups, global_ref_fixups))
    }

    pub(crate) fn compile_function_with_jit_block_counters_after_x86_passes(
        &self,
        func: &X86ISelFunction,
    ) -> Result<X86JitBlockCounterFunction, X86PipelineError> {
        validate_x86_function_layout(func)?;
        reject_x86_eh_sidecar_drop(
            &self.config,
            func,
            "compile_function_with_jit_block_counters_after_x86_passes",
        )?;
        let mut func = func.clone();
        expand_x86_vector_bool_selects(&mut func, self.config.target_features)?;
        expand_x86_vector_mask_extracts(&mut func)?;
        expand_x86_generic_popcnts(&mut func, self.config.target_features)?;
        expand_x86_generic_ptest_zero_tests(&mut func, self.config.target_features);
        // Sentinel S5: expand any proof-only bounds-check carrier the kernel gate
        // did NOT delete into a real CMP+Jcc(AE)+UD2 runtime check. Runs before
        // regalloc so the synthetic trap block + large-bound vreg are allocated.
        expand_x86_bounds_check_carriers(&mut func)?;
        // Sentinel S5: likewise expand any surviving proof-only null-check carrier
        // into a real TEST+Jcc(E)+UD2 runtime null check (byte-identical to the
        // pre-S5 eager guard). Runs before regalloc so its synthetic trap block is
        // allocated/encoded normally.
        expand_x86_null_check_carriers(&mut func)?;
        // Sentinel S5: likewise expand any surviving proof-only div-by-zero-check
        // carrier into a real TEST+Jcc(E)+UD2 runtime div-by-zero check
        // (byte-identical to the pre-S5 eager guard). Runs before regalloc so its
        // synthetic trap block is allocated/encoded normally.
        expand_x86_div_zero_check_carriers(&mut func)?;
        // Sentinel S5: likewise expand any surviving proof-only shift-range-check
        // carrier into a real CMP+Jcc(AE)+UD2 runtime shift-range check
        // (byte-identical to the pre-S5 eager guard). Runs before regalloc so its
        // synthetic trap block is allocated/encoded normally.
        expand_x86_shift_range_check_carriers(&mut func)?;
        prune_unused_x86_stack_slots(&mut func);
        reject_unsupported_x86_isel(&func, self.config.target_features)?;
        if cfg!(all(target_arch = "x86_64", target_os = "windows"))
            && self.config.regalloc_mode == X86RegAllocMode::Simplified
        {
            return Err(X86PipelineError::RegAlloc(
                "Windows x86_64 JIT block counters require full regalloc: \
                 the stack-neutral counter trampoline uses R10, and simplified regalloc may allocate R10"
                    .to_string(),
            ));
        }

        let assignment = match self.config.regalloc_mode {
            X86RegAllocMode::Simplified => {
                X86RegAssignment::assign_with_abi(&func, self.config.call_abi)?
            }
            X86RegAllocMode::Full(strategy) => self.run_full_regalloc(&mut func, strategy)?,
        };

        let installed_spills = install_x86_spill_slots(&mut func, &assignment.spill_plan);
        fixup_formal_arg_parallel_copy(
            &mut func,
            &assignment.allocation,
            &installed_spills,
            self.config.call_abi,
        )?;
        materialize_x86_spills(&mut func, &installed_spills, self.config.call_abi)?;

        fixup_two_address(&mut func, &assignment.allocation, self.config.call_abi)?;

        // Phase 2b: post-fixup redundant-`MovRR` coalescing (runtime perf). See
        // the companion call in `compile_function_after_x86_passes_with_pressure_evidence`.
        // Soundness is the pass's own scan conditions; TV-5 (inside
        // `recheck_post_regalloc`) fail-closes tied-site/bridge corruption and
        // the Stage A captured-spec check inside this wrapper covers non-tied
        // register value flow (WARN-only rollout).
        self.run_x86_movrr_coalesce_with_captured_spec(&mut func, &assignment.allocation)?;

        prepare_x86_windows_fixed_outgoing_frame(&self.config, &mut func);
        reject_windows_x64_frameless_non_leaf(&self.config, &func)?;

        let mut spill_disps: HashSet<i32> = HashSet::new();
        if self.config.emit_frame {
            let layout = compute_x86_stack_frame_layout(
                &func,
                assignment.used_callee_saved.len(),
                assignment.used_callee_saved_xmms.len(),
                assignment.num_spills,
            )?;
            spill_disps = x86_spill_slot_disps(&layout, assignment.num_spills);
            resolve_x86_stack_slots(&mut func, &layout)?;
            expand_x86_dynamic_stack_allocs(&mut func, &assignment.allocation)?;
            self.insert_prologue_epilogue(&mut func, &assignment, &layout);
        } else if function_has_x86_stack_slot_operands(&func)
            || function_has_x86_dynamic_stack_alloc_pseudos(&func)
        {
            return Err(X86PipelineError::FrameLowering(
                "x86-64 StackAddr requires frame lowering; emit_frame=false".to_string(),
            ));
        }

        validate_x86_function_layout(&func)?;
        let branch_targets = collect_x86_branch_targets(&func);
        resolve_x86_branches(&mut func);

        // TV-4/TV-5: post-regalloc re-verification of the FINAL post-fixup
        // stream (the profiling-JIT path is a first-class G4 consumer, same
        // structural + register-dataflow gate).
        self.recheck_post_regalloc(&func, &assignment.allocation, &spill_disps)?;

        let machine_code_evidence =
            collect_x86_machine_code_evidence(&func, self.config.target_features);

        let (
            code,
            cp_fixups,
            call_fixups,
            global_ref_fixups,
            block_offsets,
            _encoded_call_ranges,
            branch_fixups,
        ) = self.encode_function_with_all_fixups_and_block_metadata(
            &func,
            &assignment.allocation,
            &branch_targets,
        )?;

        let const_pool_data = if !func.const_pool_entries.is_empty() {
            let (pool, isel_to_pool_idx) = build_x86_constant_pool(&func)?;
            let cp_bytes = pool.emit();
            let (mut spliced, counter_patch_sites, block_trampoline_starts) =
                splice_x86_block_counter_trampolines(&func, &code, &block_offsets)?;

            for branch in branch_fixups {
                let shift = x86_block_shift_for_offset(
                    &func.block_order,
                    &block_offsets,
                    code.len(),
                    branch.disp32_offset,
                )?;
                let disp32_offset = branch.disp32_offset + shift;
                let target = block_trampoline_starts
                    .get(&branch.target)
                    .copied()
                    .ok_or_else(|| {
                        X86PipelineError::ConstantPool(format!(
                            "x86 block profiling: branch target {:?} missing trampoline start",
                            branch.target
                        ))
                    })?;
                patch_x86_rel32(&mut spliced, disp32_offset, target)?;
            }

            let mut shifted_call_fixups = Vec::with_capacity(call_fixups.len());
            for mut fixup in call_fixups {
                let shift = x86_block_shift_for_offset(
                    &func.block_order,
                    &block_offsets,
                    code.len(),
                    fixup.offset,
                )?;
                fixup.offset += shift;
                shifted_call_fixups.push(fixup);
            }

            let mut shifted_global_ref_fixups = Vec::with_capacity(global_ref_fixups.len());
            for mut fixup in global_ref_fixups {
                let shift = x86_block_shift_for_offset(
                    &func.block_order,
                    &block_offsets,
                    code.len(),
                    fixup.offset,
                )?;
                fixup.offset += shift;
                shifted_global_ref_fixups.push(fixup);
            }

            let cp_start = spliced.len() as i64;
            for (disp32_offset, entry_idx) in &cp_fixups {
                let shift = x86_block_shift_for_offset(
                    &func.block_order,
                    &block_offsets,
                    code.len(),
                    *disp32_offset,
                )?;
                let shifted_disp32_offset = *disp32_offset + shift;
                let entry_offset =
                    x86_constant_pool_fixup_offset(&pool, &isel_to_pool_idx, *entry_idx)?;
                let target = cp_start + entry_offset;
                let rip_disp = target - (shifted_disp32_offset as i64) - 4;
                spliced[shifted_disp32_offset..shifted_disp32_offset + 4]
                    .copy_from_slice(&(rip_disp as i32).to_le_bytes());
            }

            return Ok(X86JitBlockCounterFunction {
                code: spliced,
                const_pool: cp_bytes,
                call_fixups: shifted_call_fixups,
                global_ref_fixups: shifted_global_ref_fixups,
                counter_patch_sites,
                machine_code_evidence,
            });
        } else {
            Vec::new()
        };

        let (mut spliced, counter_patch_sites, block_trampoline_starts) =
            splice_x86_block_counter_trampolines(&func, &code, &block_offsets)?;

        for branch in branch_fixups {
            let shift = x86_block_shift_for_offset(
                &func.block_order,
                &block_offsets,
                code.len(),
                branch.disp32_offset,
            )?;
            let disp32_offset = branch.disp32_offset + shift;
            let target = block_trampoline_starts
                .get(&branch.target)
                .copied()
                .ok_or_else(|| {
                    X86PipelineError::ConstantPool(format!(
                        "x86 block profiling: branch target {:?} missing trampoline start",
                        branch.target
                    ))
                })?;
            patch_x86_rel32(&mut spliced, disp32_offset, target)?;
        }

        let mut shifted_call_fixups = Vec::with_capacity(call_fixups.len());
        for mut fixup in call_fixups {
            let shift = x86_block_shift_for_offset(
                &func.block_order,
                &block_offsets,
                code.len(),
                fixup.offset,
            )?;
            fixup.offset += shift;
            shifted_call_fixups.push(fixup);
        }

        let mut shifted_global_ref_fixups = Vec::with_capacity(global_ref_fixups.len());
        for mut fixup in global_ref_fixups {
            let shift = x86_block_shift_for_offset(
                &func.block_order,
                &block_offsets,
                code.len(),
                fixup.offset,
            )?;
            fixup.offset += shift;
            shifted_global_ref_fixups.push(fixup);
        }

        Ok(X86JitBlockCounterFunction {
            code: spliced,
            const_pool: const_pool_data,
            call_fixups: shifted_call_fixups,
            global_ref_fixups: shifted_global_ref_fixups,
            counter_patch_sites,
            machine_code_evidence,
        })
    }

    /// TV-5 Stage A wrapper around the post-fixup `MovRR` coalescer: capture
    /// the stream right after `fixup_two_address` as the value-routing SPEC,
    /// run the coalescer, then compare the coalesced stream against the spec
    /// (`trust_cg_verify::post_ra_captured_spec`). This is check (4)'s
    /// companion to `recheck_post_regalloc`'s checks (1)-(3): it closes TV-5
    /// v1's documented non-tied wrong-value-routing miss REGISTERS-ONLY, on
    /// exactly the window whose only value-routing mutator is the coalescer.
    ///
    /// Skipped entirely at O0 and under the coalescer kill-switch (the window
    /// is empty — nothing mutates between capture and check). Stage A ships
    /// WARN-only by default: a mismatch records `[TCG-POST-RA-SPEC-WARN]`
    /// telemetry and never fails the compile; `TCG_POST_RA_SPEC=enforce`
    /// opts in to fail-closed once the corpus is proven hit-free.
    fn run_x86_movrr_coalesce_with_captured_spec(
        &self,
        func: &mut X86ISelFunction,
        alloc: &HashMap<VReg, X86PReg>,
    ) -> Result<(), X86PipelineError> {
        if self.config.opt_level == trust_cg_opt::OptLevel::O0 || x86_movrr_coalesce_disabled() {
            return Ok(());
        }
        let spec = trust_cg_verify::post_ra_captured_spec::capture_x86_post_fixup_spec(func);
        let _ = coalesce_x86_redundant_movrr_copies(func, alloc);
        if let Some(spec) = &spec
            && let Some(v) = trust_cg_verify::post_ra_captured_spec::evaluate_x86_captured_spec(
                spec,
                func,
                alloc,
                "x86_64",
                self.config.call_abi,
            )
        {
            return Err(X86PipelineError::RegAlloc(format!(
                "[TCG-POST-RA-SPEC] fn `{}` post-fixup captured-spec value-flow violation ({}): {}",
                func.name,
                v.kind.tag(),
                v.detail
            )));
        }
        Ok(())
    }

    /// TV-4: post-regalloc re-verification on the FINAL post-fixup instruction
    /// stream, run immediately before encoding.
    ///
    /// Per-instruction certs, the TV-2 provenance cross-check and the TV-3
    /// dataflow-integrity gate all run PRE-regalloc; everything after (regalloc
    /// rewrite, spill store/reload, the formal-arg parallel-copy fixup, the
    /// two-address fixup, prologue/epilogue, branch resolution) was covered only
    /// by the regalloc translation validator (with a documented reload-register
    /// blind spot) plus opcode counters. This closes that gap so no post-ISel
    /// stage is validator-only.
    ///
    /// Tier 1 (default-ON, pure-lattice — mirrors the unconditional
    /// [`check_x86_carrier_hygiene`]/dataflow-integrity gates so the default
    /// bridge build stays honest): a structural block-integrity re-derivation
    /// (no real instruction may follow an unconditional terminator on the final
    /// stream) plus an opcode-legality re-derivation (`reject_unsupported_x86_isel`
    /// re-run post-regalloc). Both fail the compile CLOSED under the ENFORCE
    /// invariant. Process environment cannot downgrade it. The heavier
    /// per-instruction cert re-derivation (Tier 2) runs in `compiler.rs`'s
    /// `verify`-feature cert path.
    fn recheck_post_regalloc(
        &self,
        func: &X86ISelFunction,
        alloc: &HashMap<VReg, X86PReg>,
        spill_disps: &HashSet<i32>,
    ) -> Result<(), X86PipelineError> {
        validate_x86_resolved_function_layout(func)?;

        use trust_cg_verify::post_regalloc_recheck as prr;
        // The structural (TV-4) and dataflow (TV-5) checks resolve their modes
        // INDEPENDENTLY: turning the structural recheck off must not silently
        // disable the dataflow gate (and vice versa).
        let mode = prr::post_regalloc_recheck_mode(prr::X86_POST_RA_RECHECK_DEFAULT);
        if mode != prr::PostRegallocRecheckMode::Off {
            // (1) Structural: no real (non-pseudo) instruction after an
            // unconditional terminator on the FINAL post-regalloc stream.
            if let Some(violation) = prr::evaluate(func, "x86_64", mode) {
                return Err(X86PipelineError::RegAlloc(format!(
                    "[TCG-POST-RA-RECHECK] fn `{}` post-regalloc structural integrity violation ({}): {}",
                    func.name,
                    violation.kind.tag(),
                    violation.detail
                )));
            }
            // (2) Opcode-legality: the two-address fixup / spill materialization /
            // prologue must not have introduced an unsupported form. Re-run the
            // same gate that ran pre-regalloc, routed through the recheck mode so a
            // warn-only rollout can observe it before it fails closed.
            if let Err(e) = reject_unsupported_x86_isel(func, self.config.target_features)
                && prr::report_opcode_legality_failure("x86_64", &func.name, &e.to_string(), mode)
            {
                return Err(e);
            }
        }
        // (3) TV-5: register-dataflow validation of the FINAL post-fixup
        // stream. Running at this recheck point (after frame + branch
        // resolution, immediately before encode) puts spill materialization,
        // the two-address fixup, the formal-arg fixup, the frame stages,
        // dyn-alloc expansion, branch resolution AND any future post-RA
        // peephole inside the validated window; branch Imm displacements are
        // provisional (re-patched at encode) and deliberately unvalidated;
        // post-recheck byte-level work is ENC-3's jurisdiction.
        let df_mode = trust_cg_verify::post_ra_dataflow::post_ra_dataflow_mode();
        if let Some(v) = trust_cg_verify::post_ra_dataflow::evaluate_with_abi(
            func,
            alloc,
            "x86_64",
            df_mode,
            self.config.call_abi,
        ) {
            return Err(X86PipelineError::RegAlloc(format!(
                "[TCG-POST-RA-DATAFLOW] fn `{}` post-RA register-dataflow violation ({}): {}",
                func.name,
                v.kind.tag(),
                v.detail
            )));
        }
        // (5) Spill-slot initialization: every regalloc-created spill slot READ
        // in the final stream must have at least one store somewhere in the
        // function. The spiller only accesses spill slots directly
        // ([rbp+disp]; their address is never taken), so a whole-function
        // existence check is exact. This is the mechanical net for the cf9dc74
        // escape class: a carrier-kept vreg whose def was dropped shipped a
        // runtime test of a never-written slot — every prior TV passed.
        if let Some(disp) = x86_uninitialized_spill_read(func, spill_disps) {
            return Err(X86PipelineError::RegAlloc(format!(
                "[TCG-POST-RA-SPILL-INIT] fn `{}` reads spill slot [rbp{disp:+}] \
                 with no store anywhere in the final stream",
                func.name
            )));
        }
        Ok(())
    }

    fn compile_function_with_fixups_and_frame(
        &self,
        func: &X86ISelFunction,
    ) -> Result<
        (
            Vec<u8>,
            Vec<u8>,
            Vec<X86CallFixup>,
            Vec<X86GlobalRefFixup>,
            Option<X86FrameMetadata>,
            Vec<X86ConstPoolRel32Fixup>,
            Option<X86EhData>,
        ),
        X86PipelineError,
    > {
        validate_x86_function_layout(func)?;
        let mut func = func.clone();
        let _ = self.run_x86_optimization_passes(&mut func);
        self.compile_function_with_fixups_and_frame_after_x86_passes(&func)
    }

    fn compile_function_with_fixups_and_frame_after_x86_passes(
        &self,
        func: &X86ISelFunction,
    ) -> Result<
        (
            Vec<u8>,
            Vec<u8>,
            Vec<X86CallFixup>,
            Vec<X86GlobalRefFixup>,
            Option<X86FrameMetadata>,
            Vec<X86ConstPoolRel32Fixup>,
            Option<X86EhData>,
        ),
        X86PipelineError,
    > {
        let (
            code,
            const_pool_data,
            call_fixups,
            global_ref_fixups,
            frame_metadata,
            const_pool_rel32_fixups,
            _machine_code_evidence,
            eh,
        ) = self.compile_function_with_fixups_frame_and_evidence_after_x86_passes(func)?;
        Ok((
            code,
            const_pool_data,
            call_fixups,
            global_ref_fixups,
            frame_metadata,
            const_pool_rel32_fixups,
            eh,
        ))
    }

    pub(crate) fn compile_function_with_fixups_and_evidence_after_x86_passes(
        &self,
        func: &X86ISelFunction,
    ) -> Result<
        (
            Vec<u8>,
            Vec<u8>,
            Vec<X86CallFixup>,
            Vec<X86GlobalRefFixup>,
            X86MachineCodeEvidence,
        ),
        X86PipelineError,
    > {
        reject_x86_eh_sidecar_drop(
            &self.config,
            func,
            "compile_function_with_fixups_and_evidence_after_x86_passes",
        )?;
        let (
            code,
            const_pool_data,
            call_fixups,
            global_ref_fixups,
            _frame_metadata,
            _const_pool_rel32_fixups,
            machine_code_evidence,
            _eh,
        ) = self.compile_function_with_fixups_frame_and_evidence_after_x86_passes(func)?;
        Ok((
            code,
            const_pool_data,
            call_fixups,
            global_ref_fixups,
            machine_code_evidence,
        ))
    }

    fn compile_function_with_fixups_frame_and_evidence_after_x86_passes(
        &self,
        func: &X86ISelFunction,
    ) -> Result<
        (
            Vec<u8>,
            Vec<u8>,
            Vec<X86CallFixup>,
            Vec<X86GlobalRefFixup>,
            Option<X86FrameMetadata>,
            Vec<X86ConstPoolRel32Fixup>,
            X86MachineCodeEvidence,
            Option<X86EhData>,
        ),
        X86PipelineError,
    > {
        validate_x86_function_layout(func)?;
        reject_unwired_x86_eh_output(&self.config, func)?;

        // STEP-0 perf attribution (inert unless TCG_PERF_STATS is set): capture
        // the post-optimizer, PRE-regalloc instruction mix + the innermost-loop
        // body while branch targets are still `Block` operands (resolve below
        // rewrites them to numeric offsets). Read-only — the returned bytes are
        // byte-identical whether or not this fires.
        let perf_capture = if trust_cg_lower::perf_stats::enabled() {
            let body = trust_cg_lower::perf_stats::innermost_loop_body(func);
            let pre_whole = trust_cg_lower::perf_stats::count_function(func);
            let pre_loop = body
                .as_ref()
                .map(|b| trust_cg_lower::perf_stats::count_blocks(func, b));
            Some((body, pre_whole, pre_loop))
        } else {
            None
        };

        let mut func = func.clone();
        expand_x86_vector_bool_selects(&mut func, self.config.target_features)?;
        expand_x86_vector_mask_extracts(&mut func)?;
        expand_x86_generic_popcnts(&mut func, self.config.target_features)?;
        expand_x86_generic_ptest_zero_tests(&mut func, self.config.target_features);
        // Sentinel S5: expand any proof-only bounds-check carrier the kernel gate
        // did NOT delete into a real CMP+Jcc(AE)+UD2 runtime check. Runs before
        // regalloc so the synthetic trap block + large-bound vreg are allocated.
        expand_x86_bounds_check_carriers(&mut func)?;
        // Sentinel S5: likewise expand any surviving proof-only null-check carrier
        // into a real TEST+Jcc(E)+UD2 runtime null check (byte-identical to the
        // pre-S5 eager guard). Runs before regalloc so its synthetic trap block is
        // allocated/encoded normally.
        expand_x86_null_check_carriers(&mut func)?;
        // Sentinel S5: likewise expand any surviving proof-only div-by-zero-check
        // carrier into a real TEST+Jcc(E)+UD2 runtime div-by-zero check
        // (byte-identical to the pre-S5 eager guard). Runs before regalloc so its
        // synthetic trap block is allocated/encoded normally.
        expand_x86_div_zero_check_carriers(&mut func)?;
        // Sentinel S5: likewise expand any surviving proof-only shift-range-check
        // carrier into a real CMP+Jcc(AE)+UD2 runtime shift-range check
        // (byte-identical to the pre-S5 eager guard). Runs before regalloc so its
        // synthetic trap block is allocated/encoded normally.
        expand_x86_shift_range_check_carriers(&mut func)?;
        prune_unused_x86_stack_slots(&mut func);
        reject_unsupported_x86_isel(&func, self.config.target_features)?;

        // Phase 1: Register allocation (full greedy/linear-scan, or simplified).
        let assignment = match self.config.regalloc_mode {
            X86RegAllocMode::Simplified => {
                X86RegAssignment::assign_with_abi(&func, self.config.call_abi)?
            }
            X86RegAllocMode::Full(strategy) => self.run_full_regalloc(&mut func, strategy)?,
        };

        // Phase 1b: Resolve the formal-argument parallel copy (#497, #499).
        // Must run BEFORE fixup_two_address so the latter sees correct PRegs.
        let installed_spills = install_x86_spill_slots(&mut func, &assignment.spill_plan);
        fixup_formal_arg_parallel_copy(
            &mut func,
            &assignment.allocation,
            &installed_spills,
            self.config.call_abi,
        )?;
        let perf_spill_evidence =
            materialize_x86_spills(&mut func, &installed_spills, self.config.call_abi)?;

        // Phase 2: Two-address fixup — insert MOV copies for dst != lhs.
        let perf_two_addr_copies =
            fixup_two_address(&mut func, &assignment.allocation, self.config.call_abi)?;

        // Phase 2b: post-fixup redundant-`MovRR` coalescing (runtime perf). This
        // is the object-emission path used by the rustc backend. Soundness is the
        // pass's own scan conditions; TV-5 (inside `recheck_post_regalloc`)
        // fail-closes tied-site/bridge corruption and the Stage A captured-spec
        // check inside this wrapper covers non-tied register value flow
        // (WARN-only rollout).
        self.run_x86_movrr_coalesce_with_captured_spec(&mut func, &assignment.allocation)?;

        prepare_x86_windows_fixed_outgoing_frame(&self.config, &mut func);
        reject_windows_coff_without_unwind_metadata(&self.config, &func, &assignment)?;
        reject_windows_x64_frameless_non_leaf(&self.config, &func)?;

        // Phase 3: Resolve fixed stack slots and insert prologue/epilogue.
        let mut frame_metadata = None;
        let mut spill_disps: HashSet<i32> = HashSet::new();
        if self.config.emit_frame {
            let layout = compute_x86_stack_frame_layout(
                &func,
                assignment.used_callee_saved.len(),
                assignment.used_callee_saved_xmms.len(),
                assignment.num_spills,
            )?;
            frame_metadata = Some(X86FrameMetadata {
                callee_saved: assignment.used_callee_saved.clone(),
                callee_saved_xmms: assignment.used_callee_saved_xmms.clone(),
                xmm_save_offsets: layout.xmm_save_offsets.clone(),
                frame_size: layout.frame_size,
                has_dynamic_alloc: layout.has_dynamic_alloc,
            });
            spill_disps = x86_spill_slot_disps(&layout, assignment.num_spills);
            resolve_x86_stack_slots(&mut func, &layout)?;
            expand_x86_dynamic_stack_allocs(&mut func, &assignment.allocation)?;
            self.insert_prologue_epilogue(&mut func, &assignment, &layout);
        } else if function_has_x86_stack_slot_operands(&func)
            || function_has_x86_dynamic_stack_alloc_pseudos(&func)
        {
            return Err(X86PipelineError::FrameLowering(
                "x86-64 StackAddr requires frame lowering; emit_frame=false".to_string(),
            ));
        }

        // Phase 4: Resolve branch offsets.
        validate_x86_function_layout(&func)?;
        let branch_targets = collect_x86_branch_targets(&func);
        resolve_x86_branches(&mut func);

        // TV-4/TV-5: post-regalloc re-verification of the FINAL post-fixup
        // stream (structural + register dataflow), immediately before encoding
        // (default-ON, fail-closed).
        self.recheck_post_regalloc(&func, &assignment.allocation, &spill_disps)?;

        let machine_code_evidence =
            collect_x86_machine_code_evidence(&func, self.config.target_features);

        // Phase 5: Encode all instructions (track constant pool + call fixups).
        let (
            mut code,
            cp_fixups,
            call_fixups,
            global_ref_fixups,
            block_offsets,
            encoded_call_ranges,
            branch_fixups,
        ) = self.encode_function_with_all_fixups_and_block_metadata(
            &func,
            &assignment.allocation,
            &branch_targets,
        )?;
        patch_x86_branch_fixups_to_block_offsets(&mut code, &block_offsets, branch_fixups)?;

        // EH Lane 2: resolve the function's exception-handling structure against
        // post-layout block offsets and exact encoder-recorded call byte ranges
        // into LSDA (`__gcc_except_tab`) bytes.
        // `code.len()` here is the INSTRUCTION byte length (the throwing region);
        // the per-function constant pool is appended AFTER (Phase 5b) and is not
        // a throwing region, so it is correctly excluded from the call-site
        // table's `[0, code_len)` coverage. `block_offsets` are function-relative
        // and remain valid after the in-place branch patch above (patching does
        // not change any block's length). Inert unless the function carries EH
        // structure (double-gated OFF for the corpus); consumed by the Mach-O
        // emitter in Steps 3-4.
        let eh = x86_lsda_for_function(&func, &block_offsets, &encoded_call_ranges, code.len())?
            .map(|(personality, lsda_bytes)| X86EhData {
                personality,
                lsda_bytes,
            });

        // Phase 5b: Build per-function constant pool and fix up RIP-relative
        // displacements relative to the END of this function's code.
        //
        // NOTE: In a multi-function module each function carries its own
        // constant pool concatenated immediately after its own code, so the
        // RIP-relative fixup math stays correct regardless of the function's
        // position in the combined section. This is a simple per-function
        // layout; a future optimization could deduplicate pools across the
        // module into a single __const section.
        let mut const_pool_rel32_fixups = Vec::new();
        let const_pool_data = if !func.const_pool_entries.is_empty() {
            let (pool, isel_to_pool_idx) = build_x86_constant_pool(&func)?;
            let cp_bytes = pool.emit();

            // The constant pool is placed immediately after this function's code.
            let cp_start = code.len() as i64;

            for (disp32_offset, entry_idx) in &cp_fixups {
                let entry_offset =
                    x86_constant_pool_fixup_offset(&pool, &isel_to_pool_idx, *entry_idx)?;
                let const_pool_offset = u32::try_from(entry_offset).map_err(|_| {
                    X86PipelineError::ConstantPool(format!(
                        "constant-pool entry offset {entry_offset} does not fit in u32"
                    ))
                })?;
                const_pool_rel32_fixups.push(X86ConstPoolRel32Fixup {
                    disp32_offset: *disp32_offset,
                    const_pool_offset,
                });
                let target = cp_start + entry_offset;
                let rip_disp = target - (*disp32_offset as i64) - 4;
                let disp_bytes = (rip_disp as i32).to_le_bytes();
                code[*disp32_offset..*disp32_offset + 4].copy_from_slice(&disp_bytes);
            }

            cp_bytes
        } else {
            Vec::new()
        };

        // STEP-0 perf attribution: print the isel-vs-optimizer-vs-regalloc share
        // for this function's innermost loop. `func` here is the FINAL
        // post-regalloc, post-frame, post-branch-resolution stream; `perf_capture`
        // holds the pre-regalloc (post-optimizer) mix captured above. Building the
        // whole multi-line report as one string and printing it with a single
        // `eprintln!` keeps lines from interleaving under the parallel encode.
        if let Some((body, pre_whole, pre_loop)) = perf_capture {
            let final_whole = trust_cg_lower::perf_stats::count_function(&func);
            let mut report = format!(
                "TCG_PERF_STATS stage=post_opt fn={} mir_insts={} {}\n",
                func.name, func.source_mir_inst_count, pre_whole,
            );
            report.push_str(&format!(
                "TCG_PERF_STATS stage=post_regalloc fn={} {} \
                 spilled_vregs={} spill_reloads={} spill_stores={} two_addr_copies={}\n",
                func.name,
                final_whole,
                assignment.spill_plan.slots.len(),
                perf_spill_evidence.reload_count,
                perf_spill_evidence.store_count,
                perf_two_addr_copies,
            ));
            match (body, pre_loop) {
                (Some(body), Some(pre_loop)) => {
                    let final_loop = trust_cg_lower::perf_stats::count_blocks(&func, &body);
                    report.push_str(&format!(
                        "TCG_PERF_STATS stage=post_opt fn={} loop={} {}\n",
                        func.name,
                        trust_cg_lower::perf_stats::loop_label(&body),
                        pre_loop,
                    ));
                    report.push_str(&format!(
                        "TCG_PERF_STATS stage=post_regalloc fn={} loop={} {}",
                        func.name,
                        trust_cg_lower::perf_stats::loop_label(&body),
                        final_loop,
                    ));
                }
                _ => {
                    report.push_str(&format!(
                        "TCG_PERF_STATS stage=post_regalloc fn={} loop=none",
                        func.name
                    ));
                }
            }
            eprintln!("{report}");
        }

        Ok((
            code,
            const_pool_data,
            call_fixups,
            global_ref_fixups,
            frame_metadata,
            const_pool_rel32_fixups,
            machine_code_evidence,
            eh,
        ))
    }

    /// Compile multiple pre-ISel'd functions into a single Mach-O / ELF object
    /// with cross-function CALL relocations (#464).
    ///
    /// Mirrors the AArch64 `compile_module` path in
    /// [`crate::pipeline::Pipeline::compile_module`]:
    /// 1. Per-function code is encoded independently and concatenated into a
    ///    single `__text` / `.text` section.
    /// 2. Each function gets a global symbol at its start offset.
    /// 3. Cross-function `CALL rel32` sites become Mach-O
    ///    `X86_64_RELOC_BRANCH`, ELF `R_X86_64_PLT32`, or COFF
    ///    `IMAGE_REL_AMD64_REL32` relocations against those symbols. The
    ///    linker (or a follow-up static link step) patches the displacements.
    /// 4. COFF lifts per-function constant pools into a combined `.rdata`
    ///    section and emits `.text -> .rdata` REL32 relocations for RIP-relative
    ///    loads.
    ///
    /// The per-function output format (via `self.config.output_format`) is
    /// honored: `MachO`, `Elf`, `Coff`, or `RawBytes` (latter simply
    /// concatenates the code bytes without any object wrapper; CALL
    /// displacements are left as zero placeholders).
    pub fn compile_module(
        &self,
        functions: &[X86ISelFunction],
    ) -> Result<Vec<u8>, X86PipelineError> {
        self.compile_module_impl(functions, true, &[], false)
    }

    /// Like [`Self::compile_module`] but also emits module-level data globals
    /// into a `__DATA,__data` (mutable) / `__TEXT,__const` (immutable) Mach-O
    /// section — or `.data` / `.rodata` (ELF) — and resolves `GlobalRef` symbol
    /// addresses that target those data symbols (not just defined functions).
    ///
    /// This mirrors the AArch64
    /// [`crate::pipeline::Pipeline::compile_module_with_globals`] path so a
    /// trust-ir `GlobalRef` to a static data symbol becomes a proper
    /// RIP-relative `X86_64_RELOC_SIGNED` (Mach-O) / `R_X86_64_PC32` (ELF)
    /// relocation against the in-object data symbol.
    pub fn compile_module_with_globals(
        &self,
        functions: &[X86ISelFunction],
        globals: &[crate::pipeline::ObjectGlobal],
    ) -> Result<Vec<u8>, X86PipelineError> {
        self.compile_module_impl(functions, true, globals, false)
    }

    /// Compile multiple functions that have already had the selected x86
    /// optimization policy applied.
    pub(crate) fn compile_module_after_x86_passes(
        &self,
        functions: &[X86ISelFunction],
    ) -> Result<Vec<u8>, X86PipelineError> {
        self.compile_module_impl(functions, false, &[], false)
    }

    /// [`Self::compile_module_after_x86_passes`] with module-level data globals.
    pub(crate) fn compile_module_after_x86_passes_with_globals(
        &self,
        functions: &[X86ISelFunction],
        globals: &[crate::pipeline::ObjectGlobal],
    ) -> Result<Vec<u8>, X86PipelineError> {
        self.compile_module_impl(functions, false, globals, false)
    }

    /// CT-5: parallel-encode variant of [`Self::compile_module_after_x86_passes`].
    ///
    /// Fans the per-function register-allocation + encoding out across a bounded
    /// rayon pool when there are enough functions to justify it, then reassembles
    /// byte-identically in function order. Selected by `Compiler::compile_x86_64`
    /// when `CompilerConfig::parallel` is set; the serial method above stays the
    /// default so the `parallel: false` posture (and every existing caller) is
    /// unchanged.
    pub(crate) fn compile_module_after_x86_passes_parallel(
        &self,
        functions: &[X86ISelFunction],
    ) -> Result<Vec<u8>, X86PipelineError> {
        self.compile_module_impl(functions, false, &[], true)
    }

    /// [`Self::compile_module_after_x86_passes_parallel`] with module-level data
    /// globals — the parallel-encode variant of
    /// [`Self::compile_module_after_x86_passes_with_globals`].
    pub(crate) fn compile_module_after_x86_passes_with_globals_parallel(
        &self,
        functions: &[X86ISelFunction],
        globals: &[crate::pipeline::ObjectGlobal],
    ) -> Result<Vec<u8>, X86PipelineError> {
        self.compile_module_impl(functions, false, globals, true)
    }

    // CT-8: the production path now composes `assemble_module_after_x86_passes`
    // + `relocation_inventory_report_for_assembled` so the assembly is shared
    // with the final object emission; this one-shot wrapper is retained as the
    // inventory tests' entry point (its only remaining callers are in-crate
    // `#[cfg(test)]`, hence the allow under non-test builds).
    #[cfg(feature = "verify")]
    #[allow(dead_code)]
    pub(crate) fn module_relocation_inventory_report_after_x86_passes(
        &self,
        functions: &[X86ISelFunction],
        globals: &[crate::pipeline::ObjectGlobal],
        object_name: impl Into<String>,
        parallel: bool,
    ) -> Result<trust_cg_verify::ObjectRelocationInventoryReport, X86PipelineError> {
        let assembled = self.assemble_module(functions, false, parallel)?;
        self.relocation_inventory_report_for_assembled(&assembled, globals, object_name)
    }

    /// CT-8 (encode reuse): [`Self::assemble_module`] for post-pass
    /// functions — the proof-cert lane's entry, paired with
    /// [`Self::relocation_inventory_report_for_assembled`] (inventory rows)
    /// and [`Self::emit_assembled_module`] (final object), so the dominant
    /// per-function regalloc+encode runs ONCE for both consumers.
    #[cfg(feature = "verify")]
    pub(crate) fn assemble_module_after_x86_passes(
        &self,
        functions: &[X86ISelFunction],
        parallel: bool,
    ) -> Result<X86AssembledModule, X86PipelineError> {
        self.assemble_module(functions, false, parallel)
    }

    /// Concatenated code-byte size ([`X86AssembledModule::code_size`]) the
    /// module's object will carry, from a full assemble under THIS pipeline's
    /// real output format.
    ///
    /// Used by the compiler's code-size metric for EH-carrying
    /// (`panic=unwind`) modules, which the RawBytes size probe correctly
    /// refuses (raw bytes cannot carry the LSDA/FDE sidecar). Unlike
    /// [`Self::assemble_module_after_x86_passes`] this is available without
    /// the `verify` feature (the proofs-off lane needs the metric too).
    pub(crate) fn module_code_size_after_x86_passes(
        &self,
        functions: &[X86ISelFunction],
        parallel: bool,
    ) -> Result<usize, X86PipelineError> {
        Ok(self
            .assemble_module(functions, false, parallel)?
            .code_size())
    }

    /// Relocation-inventory report for an ALREADY-assembled module (CT-8).
    ///
    /// A deterministic pure function of `(assembled, globals, object_name)`
    /// — identical to
    /// [`Self::module_relocation_inventory_report_after_x86_passes`] on the
    /// same inputs (that entry point is now literally assemble + this).
    #[cfg(feature = "verify")]
    pub(crate) fn relocation_inventory_report_for_assembled(
        &self,
        assembled: &X86AssembledModule,
        globals: &[crate::pipeline::ObjectGlobal],
        object_name: impl Into<String>,
    ) -> Result<trust_cg_verify::ObjectRelocationInventoryReport, X86PipelineError> {
        // EH inventory scope: the Mach-O EH relocation surface — one
        // SECTION-BASED compact-unwind `X86_64_RELOC_UNSIGNED` per
        // frame-covered function plus the single zPLR personality
        // `X86_64_RELOC_GOT` — is now ENUMERATED by
        // `x86_object_relocation_inventory_rows` (mirroring
        // `emit_module_macho`'s exact emission conditions), so a `panic=unwind`
        // Mach-O module produces a complete report instead of failing closed.
        // Only the Mach-O emitter can serialize the LSDA/FDE sidecar
        // (`emit_assembled_module` refuses every other format), so a non-Mach-O
        // EH assembly still refuses here rather than returning a report for an
        // object that can never be emitted.
        if assembled.effective_format != X86OutputFormat::MachO
            && let Some(func) = assembled.encoded.iter().find(|func| func.eh.is_some())
        {
            return Err(X86PipelineError::EhOutputUnsupported {
                function: func.name.clone(),
                format: assembled.effective_format,
                reason: "the carried assembly contains an LSDA/FDE sidecar, but only the Mach-O emitter can serialize it; refusing to inventory an object that cannot be emitted (fail-closed)"
                    .to_string(),
            });
        }
        let emitted = self.x86_object_relocation_inventory_rows(
            &assembled.encoded,
            &assembled.combined_rdata,
            assembled.effective_format,
            globals,
        )?;
        let (registry, binding) = match assembled.effective_format {
            X86OutputFormat::Elf => {
                // The Certified composition, ELF lane: registry rows cite the
                // standing solver-backed value proofs (elf_data/call_reloc_
                // proofs, registered with negative controls in the proof
                // database); the BINDING half is the ELF reparse gate (the
                // ENC-9 sibling), which `emit_module_elf` runs UNCONDITIONALLY
                // at Enforce over the exact bytes of every emitted object via
                // `ElfWriter::write_checked` (a record mismatch fails the
                // write closed, so a promoted-but-unreparsed object cannot
                // exist). If the gate is downgraded (`TCG_NO_ELF_REPARSE` /
                // warn / off), the binding is absent and every row reports
                // Unverified — promotion re-fails closed.
                let binding = if crate::elf::reparse::elf_reparse_mode()
                    == crate::elf::reparse::ElfReparseMode::Enforce
                {
                    trust_cg_verify::ObjectProofBinding::ElfReparseEnforced
                } else {
                    trust_cg_verify::ObjectProofBinding::Unbound
                };
                (
                    trust_cg_verify::ObjectRelocationProofRegistry::x86_64_elf_production(),
                    binding,
                )
            }
            X86OutputFormat::MachO => {
                // The Certified composition: registry rows cite the standing
                // solver-backed value proofs (macho_data/call_reloc_proofs,
                // registered with negative controls in the proof database);
                // the BINDING half is the ENC-9 Mach-O reparse gate, which
                // the writer runs UNCONDITIONALLY at Enforce over the exact
                // bytes of every emitted object (a record mismatch fails the
                // write closed, so a promoted-but-unreparsed object cannot
                // exist). If the gate is downgraded (`TCG_NO_MACHO_REPARSE`
                // / warn / off), the binding is absent and every row reports
                // Unverified — promotion re-fails closed.
                let binding = if crate::macho::reparse::macho_reparse_mode()
                    == crate::macho::reparse::MachoReparseMode::Enforce
                {
                    trust_cg_verify::ObjectProofBinding::MachOReparseEnforced
                } else {
                    trust_cg_verify::ObjectProofBinding::Unbound
                };
                (
                    trust_cg_verify::ObjectRelocationProofRegistry::x86_64_macho_production(),
                    binding,
                )
            }
            X86OutputFormat::Coff | X86OutputFormat::RawBytes => (
                trust_cg_verify::ObjectRelocationProofRegistry::empty(),
                trust_cg_verify::ObjectProofBinding::Unbound,
            ),
        };
        Ok(
            trust_cg_verify::ObjectRelocationInventoryReport::from_emitted_kinds_with_registry_and_binding(
                object_name,
                emitted,
                &registry,
                binding,
            ),
        )
    }

    /// Inventory rows for the relocations the module WOULD emit.
    ///
    /// `globals` carries the module's data globals for two reasons, both
    /// mirroring the real emission path
    /// ([`Self::compile_module_after_x86_passes_with_globals`]):
    ///
    /// 1. DEFINED-SET: the writer resolves a `GlobalRef` against function AND
    ///    data symbols (a vtable or static is a same-module `__DATA`/`.data`
    ///    symbol reached via X86_64_RELOC_SIGNED / R_X86_64_PC32). Building
    ///    the defined-set from functions alone made the PROOF path reject any
    ///    function referencing a same-module data global with a spurious
    ///    `GlobalRefUnsupported` — an error the object writer itself never
    ///    raises for that module.
    /// 2. DATA-SECTION ROWS: each [`crate::pipeline::GlobalSymbolRef`] pointer
    ///    slot inside a global (vtable method slots, `static FNS: [fn(); N]`)
    ///    becomes an absolute-pointer relocation (`X86_64_RELOC_UNSIGNED` on
    ///    Mach-O, `R_X86_64_64` on ELF). Omitting those rows would let the
    ///    proof gate certify an object whose emitted relocation surface was
    ///    never inventoried — an unsound under-report. They are inventoried
    ///    here; both kinds now carry registered value-proof lanes
    ///    (macho_data_reloc_proofs / elf_data_reloc_proofs), so they promote
    ///    exactly when the container's per-object reparse binding also holds.
    ///
    /// EH SURFACE (Mach-O, `panic=unwind`): when the module carries ANY EH
    /// function, this inventory mirrors [`Self::emit_module_macho`]'s exact EH
    /// emission conditions so predicted == emitted:
    ///
    /// - one SECTION-BASED (r_extern=0, r_symbolnum=1 `__text`)
    ///   `X86_64_RELOC_UNSIGNED` per function WITH frame metadata — the
    ///   `__LD,__compact_unwind` 32-byte entry function pointers (in an EH
    ///   module the synthetic-filler LSDA pass gives every frame-covered
    ///   function EH data, so every one gets a compact-unwind entry);
    /// - exactly ONE `X86_64_RELOC_GOT` per module — the zPLR CIE personality
    ///   pointer slot in `__TEXT,__eh_frame`;
    /// - NO `SUBTRACTOR`+`UNSIGNED` pair for dynamic-alloc functions: the zPLR
    ///   path BAKES the FDE PC-begin/LSDA pointers self-relative and emits
    ///   zero relocations for them (ld64's x86-64 `__eh_frame` reader does not
    ///   consume subtractor pairs); the pair belongs to the non-EH zR path
    ///   ONLY. The LSDA section itself carries zero relocations.
    #[cfg(feature = "verify")]
    fn x86_object_relocation_inventory_rows(
        &self,
        encoded: &[X86EncodedFunc],
        combined_rdata: &[u8],
        effective_format: X86OutputFormat,
        globals: &[crate::pipeline::ObjectGlobal],
    ) -> Result<Vec<trust_cg_verify::ObjectRelocationKind>, X86PipelineError> {
        use trust_cg_verify::ObjectRelocationKind;

        let mut emitted = Vec::new();
        match effective_format {
            X86OutputFormat::RawBytes => {}
            X86OutputFormat::MachO => {
                let defined: std::collections::BTreeSet<_> = encoded
                    .iter()
                    .map(|ef| ef.name.as_str())
                    .chain(globals.iter().map(|g| g.name.as_str()))
                    .collect();
                // EH surface predictor (see the doc comment above): mirrors
                // `emit_module_macho`'s emit-EH gate (its filler pass +
                // compact-unwind emission + `add_x86_64_eh_frame_to_macho`).
                // This predicate is shared VERBATIM with the emitter's filler
                // trigger so predicted == emitted, including the cross-object
                // `panic=unwind` case where a frame-covered object with NO local
                // EH function still emits full walkable FDE coverage.
                let module_emits_eh_frame = encoded.iter().any(|ef| ef.eh.is_some())
                    || (self.config.panic_unwind
                        && encoded.iter().any(|ef| ef.frame_metadata.is_some()));
                if module_emits_eh_frame {
                    // Mirror emission's fail-closed: an EH function without
                    // frame metadata cannot get an FDE/LSDA, so the module
                    // never emits (`emit_module_macho` unwind-input loop).
                    if let Some(ef) = encoded
                        .iter()
                        .find(|ef| ef.eh.is_some() && ef.frame_metadata.is_none())
                    {
                        return Err(X86PipelineError::FrameLowering(format!(
                            "x86-64 Mach-O: EH function `{}` has no frame metadata; \
                             cannot emit its FDE/LSDA",
                            ef.name
                        )));
                    }
                    // (a) `__LD,__compact_unwind`: one SECTION-BASED
                    // (r_extern=0, `__text`) UNSIGNED per 32-byte entry — one
                    // entry per function with frame metadata (the filler pass
                    // gives each of them EH data, so each gets an FDE and a
                    // compact-unwind entry).
                    emitted.extend(
                        encoded
                            .iter()
                            .filter(|ef| ef.frame_metadata.is_some())
                            .map(|_| ObjectRelocationKind::X86_64MachOUnsigned),
                    );
                    // (b) `__TEXT,__eh_frame`: exactly ONE GOT row — the zPLR
                    // CIE personality pointer. The FDE PC-begin/LSDA pointers
                    // are baked self-relative (zero relocations).
                    emitted.push(ObjectRelocationKind::X86_64MachOGot);
                }
                for global in globals {
                    emitted.extend(
                        global
                            .symbol_refs
                            .iter()
                            .map(|_| ObjectRelocationKind::X86_64MachOUnsigned),
                    );
                }
                for ef in encoded {
                    // Non-EH (zR, backtrace-only) dynamic-alloc FDE PC-begin:
                    // a SUBTRACTOR+UNSIGNED pair per dynamic-alloc function.
                    // In an EH module the zPLR path bakes these pointers and
                    // emits NO pair (do not double-count the EH rows above).
                    if !module_emits_eh_frame
                        && ef
                            .frame_metadata
                            .as_ref()
                            .is_some_and(|m| m.has_dynamic_alloc)
                    {
                        emitted.push(ObjectRelocationKind::X86_64MachOSubtractor);
                        emitted.push(ObjectRelocationKind::X86_64MachOUnsigned);
                    }
                    for gf in &ef.global_ref_fixups {
                        match gf.kind {
                            X86SymbolRefFixupKind::GlobalRef => {
                                if !defined.contains(gf.symbol.as_str()) {
                                    return Err(X86PipelineError::GlobalRefUnsupported {
                                        function: ef.name.clone(),
                                        symbol: gf.symbol.clone(),
                                        reason:
                                            "Mach-O GlobalRef only supports symbols defined in the same x86 module"
                                                .to_string(),
                                    });
                                }
                                emitted.push(ObjectRelocationKind::X86_64MachOSigned);
                            }
                            X86SymbolRefFixupKind::ExternRefGot => {
                                emitted.push(ObjectRelocationKind::X86_64MachOGotLoad);
                            }
                            X86SymbolRefFixupKind::TlsTlv => {
                                emitted.push(ObjectRelocationKind::X86_64MachOTlv);
                            }
                        }
                    }
                    emitted.extend(
                        ef.call_fixups
                            .iter()
                            .map(|_| ObjectRelocationKind::X86_64MachOBranch),
                    );
                }
            }
            X86OutputFormat::Elf => {
                let defined: std::collections::BTreeSet<_> = encoded
                    .iter()
                    .map(|ef| ef.name.as_str())
                    .chain(globals.iter().map(|g| g.name.as_str()))
                    .collect();
                for global in globals {
                    emitted.extend(
                        global
                            .symbol_refs
                            .iter()
                            .map(|_| ObjectRelocationKind::X86_64ElfAbs64),
                    );
                }
                for ef in encoded {
                    if ef
                        .frame_metadata
                        .as_ref()
                        .is_some_and(|m| m.has_dynamic_alloc)
                    {
                        emitted.push(ObjectRelocationKind::X86_64ElfPc32);
                    }
                    for gf in &ef.global_ref_fixups {
                        match gf.kind {
                            X86SymbolRefFixupKind::GlobalRef => {
                                if !defined.contains(gf.symbol.as_str()) {
                                    return Err(X86PipelineError::GlobalRefUnsupported {
                                        function: ef.name.clone(),
                                        symbol: gf.symbol.clone(),
                                        reason:
                                            "ELF GlobalRef only supports symbols defined in the same x86 module"
                                                .to_string(),
                                    });
                                }
                                emitted.push(ObjectRelocationKind::X86_64ElfPc32);
                            }
                            X86SymbolRefFixupKind::ExternRefGot => {
                                emitted.push(ObjectRelocationKind::X86_64ElfGotPcRel);
                            }
                            X86SymbolRefFixupKind::TlsTlv => {
                                return Err(x86_symbol_ref_unsupported(
                                    gf.kind,
                                    ef.name.clone(),
                                    gf.symbol.clone(),
                                    "x86-64 ELF has no TLV model; Darwin-only relocation",
                                ));
                            }
                        }
                    }
                    emitted.extend(
                        ef.call_fixups
                            .iter()
                            .map(|_| ObjectRelocationKind::X86_64ElfPlt32),
                    );
                }
            }
            X86OutputFormat::Coff => {
                let defined: std::collections::BTreeSet<_> = encoded
                    .iter()
                    .map(|ef| ef.name.as_str())
                    .chain(globals.iter().map(|g| g.name.as_str()))
                    .collect();
                for global in globals {
                    // IMAGE_REL_AMD64_ADDR64 (= 0x0001): absolute 64-bit
                    // pointer slot. No named inventory variant yet; the COFF
                    // registry is empty so this fails closed either way.
                    emitted.extend(
                        global
                            .symbol_refs
                            .iter()
                            .map(|_| ObjectRelocationKind::X86_64CoffOther(1)),
                    );
                }
                for ef in encoded {
                    if !ef.const_pool_rel32_fixups.is_empty() && combined_rdata.is_empty() {
                        return Err(X86PipelineError::ConstantPool(
                            "module x86-64 COFF has .text constant-pool relocations but no .rdata"
                                .to_string(),
                        ));
                    }
                    emitted.extend(
                        ef.const_pool_rel32_fixups
                            .iter()
                            .map(|_| ObjectRelocationKind::X86_64CoffRel32),
                    );
                    for cf in &ef.call_fixups {
                        if !defined.contains(cf.callee.as_str()) {
                            return Err(X86PipelineError::CoffUndefinedExternalCall {
                                caller: ef.name.clone(),
                                callee: cf.callee.clone(),
                            });
                        }
                        emitted.push(ObjectRelocationKind::X86_64CoffRel32);
                    }
                    for gf in &ef.global_ref_fixups {
                        if gf.kind == X86SymbolRefFixupKind::GlobalRef
                            && !defined.contains(gf.symbol.as_str())
                        {
                            return Err(X86PipelineError::GlobalRefUnsupported {
                                function: ef.name.clone(),
                                symbol: gf.symbol.clone(),
                                reason:
                                    "COFF GlobalRef only supports symbols defined in the same x86 module"
                                        .to_string(),
                            });
                        }
                        emitted.push(ObjectRelocationKind::X86_64CoffRel32);
                    }
                }

                if self.config.call_abi == X86CallAbi::WindowsX64 {
                    let mut xdata_offset = 0u32;
                    for ef in encoded {
                        if let Some(metadata) = ef.frame_metadata.as_ref() {
                            let record = x86_64_coff_unwind_record(
                                metadata,
                                &ef.name,
                                ef.text_offset,
                                ef.code_len,
                                xdata_offset,
                            )?;
                            let unwind_info_len = checked_x86_object_u32(
                                &ef.name,
                                "COFF unwind-info length",
                                record.unwind_info.len(),
                            )?;
                            xdata_offset =
                                xdata_offset.checked_add(unwind_info_len).ok_or_else(|| {
                                    X86PipelineError::FrameLowering(
                                        "COFF unwind .xdata size overflow".to_string(),
                                    )
                                })?;
                            emitted.extend([
                                ObjectRelocationKind::X86_64CoffAddr32Nb,
                                ObjectRelocationKind::X86_64CoffAddr32Nb,
                                ObjectRelocationKind::X86_64CoffAddr32Nb,
                            ]);
                        }
                    }
                }
            }
        }

        Ok(emitted)
    }

    /// Encode every function's post-ISel machine code INDEPENDENTLY, returning
    /// the per-function `(code, const_pool, call_fixups, global_ref_fixups,
    /// frame_metadata, const_pool_rel32_fixups)` tuples in INPUT (function)
    /// ORDER.
    ///
    /// This is the parallelizable chokepoint of the x86 backend: each tuple is
    /// produced by `compile_function_with_fixups_and_frame*`, a pure function of
    /// `(&self, func)` (register allocation + frame lowering + byte encoding)
    /// with no shared mutable output state. When `parallel` is set and there are
    /// enough functions to justify the pool ([`worker_count_for_items`]), the
    /// encodes fan out across a bounded rayon pool; otherwise they run serially.
    ///
    /// DETERMINISM: `par_iter().map().collect::<Result<Vec<_>>>()` is an indexed
    /// parallel collect, so the returned Vec is always in function order — the
    /// caller's sequential reassembly (Phase 1b) is therefore byte-identical to
    /// the serial path regardless of thread scheduling. The solver is never on
    /// this path (encoding/regalloc do not verify), so no BENCH-8 parallel-z3
    /// hazard is introduced.
    #[allow(clippy::type_complexity)]
    fn encode_functions_ordered(
        &self,
        functions: &[X86ISelFunction],
        run_x86_passes: bool,
        parallel: bool,
    ) -> Result<
        Vec<(
            Vec<u8>,
            Vec<u8>,
            Vec<X86CallFixup>,
            Vec<X86GlobalRefFixup>,
            Option<X86FrameMetadata>,
            Vec<X86ConstPoolRel32Fixup>,
            Option<X86EhData>,
        )>,
        X86PipelineError,
    > {
        let encode_one = |func: &X86ISelFunction| {
            if run_x86_passes {
                self.compile_function_with_fixups_and_frame(func)
            } else {
                self.compile_function_with_fixups_and_frame_after_x86_passes(func)
            }
        };

        let pool = if parallel {
            crate::resource_limits::worker_count_for_items(functions.len())
                .map(crate::resource_limits::build_rayon_pool)
                .transpose()
                .map_err(|err| {
                    X86PipelineError::RegAlloc(format!("parallel worker pool error: {err}"))
                })?
        } else {
            None
        };

        if let Some(pool) = pool.as_ref() {
            use rayon::prelude::*;
            pool.install(|| functions.par_iter().map(&encode_one).collect())
        } else {
            functions.iter().map(&encode_one).collect()
        }
    }

    fn compile_module_impl(
        &self,
        functions: &[X86ISelFunction],
        run_x86_passes: bool,
        globals: &[crate::pipeline::ObjectGlobal],
        parallel: bool,
    ) -> Result<Vec<u8>, X86PipelineError> {
        if functions.is_empty() {
            // Nothing to emit. Mirror the AArch64 path: compile_module on an
            // empty module produces an empty object. Callers (the dispatcher)
            // guard against empty modules up front, so this path is a defensive
            // backstop rather than a common case.
            return Ok(Vec::new());
        }

        let assembled = self.assemble_module(functions, run_x86_passes, parallel)?;
        self.emit_assembled_module(assembled, globals)
    }

    /// Phase 1 of [`Self::compile_module_impl`]: per-function encode +
    /// deterministic in-order reassembly, producing an
    /// [`X86AssembledModule`] ready for Phase-2 object emission
    /// ([`Self::emit_assembled_module`]) and/or the relocation inventory
    /// ([`Self::relocation_inventory_report_for_assembled`]).
    fn assemble_module(
        &self,
        functions: &[X86ISelFunction],
        run_x86_passes: bool,
        parallel: bool,
    ) -> Result<X86AssembledModule, X86PipelineError> {
        // Resolve effective output format (matches compile_function semantics).
        let effective_format = effective_x86_output_format(&self.config);

        // Phase 1a: Encode each function INDEPENDENTLY — register allocation
        // (`run_full_regalloc`, the dominant backend cost), frame lowering, and
        // byte encoding. `compile_function_with_fixups_and_frame*` is a pure
        // function of `(&self, func)` with NO shared mutable output state (the
        // only process globals in the encode/regalloc path are `OnceLock`
        // validation canaries, read-only after their idempotent init), so this
        // phase parallelizes across a BOUNDED rayon pool (CT-5).
        //
        // DETERMINISM (byte-identity gate): `par_iter().map().collect::<Vec>()`
        // preserves INPUT ORDER, so `per_func[i]` is always function `i`'s
        // encoding regardless of thread scheduling. Phase 1b then reassembles
        // in that same function order, so the emitted object is byte-for-byte
        // identical to the serial path. No per-function symbol numbering,
        // counter, or map-iteration order feeds the emitted bytes.
        let per_func = self.encode_functions_ordered(functions, run_x86_passes, parallel)?;

        // Phase 1b: Reassemble per-function buffers SEQUENTIALLY (fast memcpy),
        // in deterministic function order. `text_offset` is the running length
        // of `combined_code`, computed here — identical to the serial path.
        let mut encoded: Vec<X86EncodedFunc> = Vec::with_capacity(functions.len());
        let mut combined_code: Vec<u8> = Vec::new();
        let mut combined_rdata: Vec<u8> = Vec::new();

        for (
            func,
            (
                code,
                const_pool,
                call_fixups,
                global_ref_fixups,
                frame_metadata,
                const_pool_rel32_fixups,
                eh,
            ),
        ) in functions.iter().zip(per_func)
        {
            // Start every function on a 32-byte boundary when the JCC-erratum
            // pass is on, so that its function-relative reasoning IS absolute
            // (see `x86_text_align_log2`). Padding goes BEFORE `text_offset` is
            // taken, so the symbol points at the function's first real byte.
            //
            // ⚑ ALL OUTPUT FORMATS, deliberately. ELF, Mach-O, and COFF request
            // the matching 32-byte text-section alignment at their emission
            // boundaries, so this padding establishes the grid the branch pass
            // assumes after linking. RawBytes is non-linkable and carries no
            // section-base alignment contract; it retains the same inter-function
            // padding only for deterministic code-size/layout parity with object
            // output, not as a claim that arbitrary raw-byte placement is aligned.
            // The kill switch returns both this padding and object-section
            // alignment to the 16-byte convention.
            if x86_jcc_align_enabled() {
                align_code_vec_with_nops(&mut combined_code, 1 << x86_text_align_log2());
            }
            let text_offset = combined_code.len() as u64;
            combined_code.extend_from_slice(&code);
            let code_len = checked_x86_code_len(&func.name, code.len())?;
            let mut const_pool_rdata_offset = 0;
            if effective_format == X86OutputFormat::Coff {
                if !const_pool.is_empty() {
                    align_vec_to(&mut combined_rdata, 8);
                    const_pool_rdata_offset = combined_rdata.len() as u64;
                    combined_rdata.extend_from_slice(&const_pool);
                }
            } else {
                // Keep non-COFF module pools inline in text so the already
                // patched RIP-relative displacements remain valid.
                combined_code.extend_from_slice(&const_pool);
            }

            encoded.push(X86EncodedFunc {
                name: func.name.clone(),
                code_len,
                const_pool_len: const_pool.len(),
                const_pool_rdata_offset,
                const_pool_rel32_fixups,
                call_fixups,
                global_ref_fixups,
                text_offset,
                frame_metadata,
                eh,
            });
        }

        Ok(X86AssembledModule {
            encoded,
            combined_code,
            combined_rdata,
            effective_format,
        })
    }

    /// Phase 2 of [`Self::compile_module_impl`]: emit the object for an
    /// assembled module (consumes the assembly — RawBytes returns its code
    /// buffer directly).
    ///
    /// Emission is a deterministic pure function of `(assembled, globals,
    /// &self.config)`: emitting from a CARRIED assembly is byte-identical to
    /// re-assembling the same functions under the same config and emitting —
    /// which is what lets the compiler share ONE assembly between the proof
    /// lane's relocation inventory and the final object (CT-8).
    pub(crate) fn emit_assembled_module(
        &self,
        assembled: X86AssembledModule,
        globals: &[crate::pipeline::ObjectGlobal],
    ) -> Result<Vec<u8>, X86PipelineError> {
        let X86AssembledModule {
            encoded,
            combined_code,
            combined_rdata,
            effective_format,
        } = assembled;
        if encoded.is_empty() {
            // Mirror `compile_module_impl`'s empty-module backstop (an empty
            // module emits an empty object, not a bare object wrapper).
            return Ok(Vec::new());
        }
        if effective_format != X86OutputFormat::MachO
            && let Some(eh_func) = encoded.iter().find(|func| func.eh.is_some())
        {
            return Err(X86PipelineError::EhOutputUnsupported {
                function: eh_func.name.clone(),
                format: effective_format,
                reason: "the carried assembly contains an LSDA/FDE sidecar, but only the Mach-O emitter can serialize it; refusing to discard it at the final emission boundary (fail-closed)"
                    .to_string(),
            });
        }
        match effective_format {
            X86OutputFormat::RawBytes => {
                // No object wrapper — return the raw concatenated code. CALL
                // displacements stay zero, and symbol-address (`GlobalRef` /
                // `ExternRef`) RIP-relative disp32 fields likewise stay zero
                // placeholders, exactly like CALL: RawBytes is non-linkable
                // output used by tests and by the `compile_x86_64` code-size
                // probe, never executed directly. The real symbol-address
                // relocations are emitted by the MachO / ELF / COFF paths
                // below.
                Ok(combined_code)
            }
            X86OutputFormat::MachO => self.emit_module_macho(&encoded, &combined_code, globals),
            X86OutputFormat::Elf => self.emit_module_elf(&encoded, &combined_code, globals),
            X86OutputFormat::Coff => {
                self.emit_module_coff(&encoded, &combined_code, &combined_rdata, globals)
            }
        }
    }

    /// Emit a multi-function Mach-O object with x86-64 CALL relocations (#464).
    fn emit_module_macho(
        &self,
        encoded: &[X86EncodedFunc],
        combined_code: &[u8],
        globals: &[crate::pipeline::ObjectGlobal],
    ) -> Result<Vec<u8>, X86PipelineError> {
        use crate::macho::constants::S_REGULAR;
        use crate::macho::x86_64_reloc::X86_64Relocation;

        // Thread-local DEFINITIONS are now emitted through the shared, arch-neutral
        // `add_tls_global_sections` (see the `__DATA,__thread_vars` descriptor +
        // `__DATA,__thread_data` template emission below), so the AArch64-only
        // `reject_x86_thread_local_globals` fail-closed guard no longer fires here.
        // A thread-local IMPORT (a `#[thread_local] static` DEFINED in another
        // object) still falls through to the undefined-external `TlsTlv` path, and
        // the ELF/COFF x86 emitters keep the rejection (no `.tdata`/`.tbss` wiring).

        // EH Lane 5 (whole-program `panic=unwind`, FUZZ-7): when the module
        // carries ANY exception-handling function, EVERY function in it must be
        // WALKABLE by the unwinder — a panic raised in (or below) one function
        // of this module unwinds through its sibling frames (`main`, the
        // `lang_start` closure / `call_once` shims, plain no-drop helpers) on
        // its way to libstd's catch. A frame with no unwind entry stops phase 1
        // dead (`_URC_END_OF_STACK` — libstd aborts with "failed to initiate
        // panic, error 5"), skipping every cleanup Drop.
        //
        // Give each non-EH function a synthetic ALL-FILLER LSDA (one
        // `landing_pad == 0` call-site region covering `[0, code_len)` — the
        // personality reads it as "no handler here, continue unwinding", the
        // exact gap-filler semantics `resolve_x86_eh_offsets` mandates), so
        // every function takes the ONE proven zPLR FDE + LSDA path below (the
        // section is single-CIE; mixing LSDA-less FDEs under a zPLR CIE would
        // be malformed — libunwind reads the FDE's LSDA field whenever the CIE
        // declares "L"). Sound: the filler can only tell the unwinder to KEEP
        // WALKING — it can never dispatch to a wrong pad. No-EH modules are
        // left byte-identical (nothing in them raises or lands).
        //
        // CROSS-OBJECT (FUZZ-7 task #16): the bridge emits ONE object per mono
        // item, so a pass-through frame on the panic path (the `lang_start`
        // closure, `rust_begin_short_backtrace`) lands in an object with NO
        // local EH function. Module-scoped Lane 5 (`any(eh.is_some())`) never
        // fires for it, it gets no FDE, and phase-1 unwind stops dead at that
        // frame. So under whole-program `panic=unwind` (`self.config.panic_unwind`)
        // trigger Lane 5 for EVERY frame-covered object even with zero local EH,
        // giving each frame-covered function the all-filler walkable FDE. The
        // trigger predicate is shared VERBATIM with the relocation inventory
        // (`x86_object_relocation_inventory_rows`) so predicted == emitted.
        let module_emits_eh_frame = encoded.iter().any(|ef| ef.eh.is_some())
            || (self.config.panic_unwind && encoded.iter().any(|ef| ef.frame_metadata.is_some()));
        let encoded_storage: Vec<X86EncodedFunc>;
        let encoded: &[X86EncodedFunc] = if module_emits_eh_frame {
            // A pass-through-only object has no local personality; every filler
            // LSDA references libstd's extern `rust_eh_personality` (registered
            // below as an undefined external the linker resolves) — the same
            // personality a real EH function would name. This is a "keep walking,
            // never dispatch" table, so any Rust personality is sound here.
            let personality = encoded
                .iter()
                .find_map(|ef| ef.eh.as_ref().map(|e| e.personality.clone()))
                .unwrap_or_else(|| {
                    crate::exception_handling::RUST_EH_PERSONALITY_SYMBOL.to_string()
                });
            let mut with_filler = encoded.to_vec();
            for ef in &mut with_filler {
                if ef.eh.is_none() && ef.frame_metadata.is_some() {
                    let resolved = ResolvedX86Eh {
                        landing_pads: Vec::new(),
                        call_site_ranges: vec![(0, ef.code_len, 0)],
                    };
                    let lsda_bytes =
                        generate_x86_lsda(&resolved, &personality).map_err(|error| {
                            X86PipelineError::MalformedFunction {
                                function: ef.name.clone(),
                                detail: format!(
                                    "invalid synthetic filler exception table: {error}"
                                ),
                            }
                        })?;
                    ef.eh = Some(X86EhData {
                        personality: personality.clone(),
                        lsda_bytes,
                    });
                }
            }
            encoded_storage = with_filler;
            &encoded_storage
        } else {
            encoded
        };

        let mut writer = MachOWriter::for_target(MachOTarget::X86_64);
        writer.add_text_section_with_align(combined_code, x86_text_align_log2());

        // Build symbol table: one global symbol per function at its text offset.
        // Mach-O convention: prefix external symbol names with '_'.
        //
        // symbol_map maps both the unmangled and mangled names to the symbol
        // table index, so call-site fixups can resolve by either spelling.
        let mut symbol_map: std::collections::HashMap<String, crate::macho::writer::SymbolId> =
            std::collections::HashMap::new();
        for ef in encoded {
            let mangled = format!("_{}", ef.name);
            let symbol_id = writer.add_symbol(&mangled, 1, ef.text_offset, true)?;
            symbol_map.insert(ef.name.clone(), symbol_id);
            symbol_map.insert(mangled, symbol_id);
        }

        // EH Lane 2 Step 3: emit the `__gcc_except_tab` (LSDA) section + its
        // symbols for every function that carries exception-handling structure.
        //
        // Placed HERE — after the per-function symbol pass, BEFORE the
        // data-reloc / global-ref / call relocation loops below — so the LSDA
        // *local* symbols are registered before any `final_symbol_index` is read.
        // Mach-O emits locals, then external-defined, then undefined; inserting a
        // local later would shift every undefined index and mis-wire a CALL
        // relocation to the wrong callee (the AArch64 hazard documented in
        // pipeline.rs::emit_macho). All EH functions concatenate their LSDAs into
        // ONE section (each 4-byte aligned), each with its own local
        // `_GCC_except_table_<fn>` symbol at its offset; personality externals
        // (`_<personality>`) are deduped by name. x86 emits NO compact-unwind, so
        // the LSDA is referenced ONLY from the zPLR FDE (wired in Step 4). The
        // symbol ids are recovered from `symbol_map` by name in Step 4.
        if encoded.iter().any(|ef| ef.eh.is_some()) {
            let mut lsda_section_data: Vec<u8> = Vec::new();
            let mut lsda_offsets: Vec<(usize, u64)> = Vec::new();
            for (i, ef) in encoded.iter().enumerate() {
                let Some(eh) = ef.eh.as_ref() else {
                    continue;
                };
                align_vec_to(&mut lsda_section_data, 4);
                lsda_offsets.push((i, lsda_section_data.len() as u64));
                lsda_section_data.extend_from_slice(&eh.lsda_bytes);
            }
            let lsda_section = writer.add_custom_section(
                b"__gcc_except_tab",
                b"__TEXT",
                &lsda_section_data,
                2, // 2^2 = 4-byte alignment (matching LLVM)
                S_REGULAR,
            );
            for (i, offset) in lsda_offsets {
                let ef = &encoded[i];
                let eh = ef.eh.as_ref().expect("EH function has EH data");
                let lsda_name = format!("_GCC_except_table_{}", ef.name);
                let lsda_symbol_id =
                    writer.add_symbol(&lsda_name, lsda_section + 1, offset, false)?;
                symbol_map.insert(lsda_name, lsda_symbol_id);

                let personality_name = format!("_{}", eh.personality);
                if let std::collections::hash_map::Entry::Vacant(entry) =
                    symbol_map.entry(personality_name)
                {
                    let id = writer.add_symbol(entry.key(), 0, 0, true)?;
                    entry.insert(id);
                }
            }
        }

        // Emit module-level data globals so a `GlobalRef` to a static data
        // symbol resolves to an in-object definition. Mutable globals go to
        // `__DATA,__data`; immutable globals to `__TEXT,__const`. Both use
        // `S_REGULAR` (NOT `__cstring`/`S_CSTRING_LITERALS`, which the linker
        // may merge/dedupe on NUL boundaries — wrong for arbitrary 8-byte
        // binary data). Symbols are defined (`section != 0`) and mangled with
        // the leading `_`.
        // A global carrying symbol-address relocations MUST live in a writable
        // `__DATA` section: an `X86_64_RELOC_UNSIGNED` (absolute pointer)
        // relocation cannot be applied to a `__TEXT` section (the text segment
        // is read-only / code-signed, and dyld does not rebase text). This
        // mirrors clang, which places `static long *p = &g;` in `__DATA,__data`
        // even though the pointer is logically const. Plain byte globals with
        // no relocations keep their `__TEXT,__const` (immutable) /
        // `__DATA,__data` (mutable) placement.
        let needs_data_section =
            |g: &&crate::pipeline::ObjectGlobal| g.mutable || !g.symbol_refs.is_empty();
        // A cross-object data IMPORT (`is_import` — e.g. a `static mut` DEFINED in
        // another object) contributes NO bytes here; it is an undefined external the
        // linker resolves. Exclude it from both definition sections (it is registered
        // as an undefined external when its `GlobalRef` relocation is emitted below);
        // emitting it as a definition would be a duplicate symbol.
        //
        // A THREAD-LOCAL global is likewise excluded from the ordinary
        // `__data`/`__const` definition sections: it is emitted (definition) or
        // imported (undefined TLV) exclusively through the `__thread_vars` /
        // `__thread_data` descriptor path above. Without this exclusion a genuine
        // TLS DEFINITION (`is_thread_local && !is_import`, e.g. a `#[thread_local]
        // static X = V;`) is emitted BOTH as a plain `__data` symbol `_X` AND as
        // the `__thread_vars` descriptor `_X` — a duplicate-symbol link error.
        // (This mirrors the AArch64 emitter's `!global.is_thread_local` guard;
        // wp10 never tripped it because every wp10 TLS global is an import.)
        let mutable_globals: Vec<&crate::pipeline::ObjectGlobal> = globals
            .iter()
            .filter(|g| !g.is_import && !g.is_thread_local && needs_data_section(g))
            .collect();
        let immutable_globals: Vec<&crate::pipeline::ObjectGlobal> = globals
            .iter()
            .filter(|g| !g.is_import && !g.is_thread_local && !needs_data_section(g))
            .collect();
        // Deferred data-section relocations from symbol-address initializer
        // elements (vtable / `static FNS: [fn(); N]` slots). Collected as
        // `(section_index_0based, section_relative_offset, symbol, addend)` and
        // emitted only AFTER every defined module symbol (functions + all data
        // globals) is registered, so a slot may target a symbol defined later
        // in iteration order.
        let mut data_reloc_work: Vec<(usize, u64, String, i64)> = Vec::new();
        for (section_name, segment, section_globals, flags) in [
            (&b"__data"[..], &b"__DATA"[..], &mutable_globals, S_REGULAR),
            (
                &b"__const"[..],
                &b"__TEXT"[..],
                &immutable_globals,
                S_REGULAR,
            ),
        ] {
            if section_globals.is_empty() {
                continue;
            }
            let mut data = Vec::new();
            let mut offsets = Vec::with_capacity(section_globals.len());
            // The section's own alignment must cover the strictest per-global
            // alignment (a `#[repr(align(64))]` static needs a 64-aligned
            // section so the loader places its first byte 64-aligned).
            let mut max_align: u32 = 1;
            for g in section_globals.iter() {
                // Align each global up to its OWN declared alignment within the
                // section (over-aligned statics must not be packed back-to-back).
                let galign = g.align.max(1) as usize;
                max_align = max_align.max(g.align.max(1));
                let padding = (galign - (data.len() % galign)) % galign;
                data.resize(data.len() + padding, 0);
                let global_offset_usize = data.len();
                let global_offset = data.len() as u64;
                offsets.push(global_offset);
                data.extend_from_slice(&g.data);
                // Bake any non-zero addend into the 8-byte slot now (while we
                // still own the section bytes). Mach-O `X86_64_RELOC_UNSIGNED`
                // adds the resolved symbol address to the in-place value, so a
                // non-zero addend must already be present in the section data.
                for sref in &g.symbol_refs {
                    let bytes = sref.addend.to_le_bytes();
                    let local_slot = checked_x86_symbol_initializer_slot(
                        &g.name,
                        &sref.symbol,
                        sref.offset,
                        g.data.len(),
                    )?;
                    if sref.addend != 0 {
                        let slot = global_offset_usize
                            .checked_add(local_slot.start)
                            .ok_or_else(|| X86PipelineError::GlobalRefUnsupported {
                                function: g.name.clone(),
                                symbol: sref.symbol.clone(),
                                reason:
                                    "section-relative symbol-initializer offset overflows usize"
                                        .to_string(),
                            })?;
                        let end = slot.checked_add(local_slot.len()).ok_or_else(|| {
                            X86PipelineError::GlobalRefUnsupported {
                                function: g.name.clone(),
                                symbol: sref.symbol.clone(),
                                reason: "section-relative symbol-initializer range overflows usize"
                                    .to_string(),
                            }
                        })?;
                        let target = data.get_mut(slot..end).ok_or_else(|| {
                            X86PipelineError::GlobalRefUnsupported {
                                function: g.name.clone(),
                                symbol: sref.symbol.clone(),
                                reason: "symbol-initializer slot is outside emitted section data"
                                    .to_string(),
                            }
                        })?;
                        target.copy_from_slice(&bytes);
                    }
                }
            }
            let section_index = writer.add_custom_section(
                section_name,
                segment,
                &data,
                max_align.trailing_zeros(),
                flags,
            );
            // `add_*_section` / `add_custom_section` return a 0-based index;
            // symbol `section` fields are 1-based ordinals.
            let section_ordinal = section_index + 1;
            for (g, offset) in section_globals.iter().zip(offsets) {
                let mangled = macho_x86_64_symbol_name(&g.name);
                // A weak DEFINITION (`Weak`/`LinkOnce` linkage) is emitted with
                // `N_WEAK_DEF` so that a promoted/merged immutable static referenced
                // by another static (the cross-static `ptr::eq` case) COALESCES
                // across objects instead of raising a duplicate-strong-definition
                // error. A strong global stays a plain external def.
                //
                // The symbol's external bit honors `ObjectGlobal::is_external`
                // (the documented contract; the AArch64 Mach-O emitter already
                // does): a module-local const-alloc copy (`const.*` string /
                // vtable pool) must be a LOCAL symbol. Hardcoding `true` here
                // made every module export its private `const.allocN`, and any
                // two x86 modules whose pools shared an index collided at link
                // ("duplicate symbol '_const.allocN'") — first surfaced by the
                // wp10-x86 whole-corpus link (2600 objects, one ld invocation).
                let symbol_id = if g.is_weak {
                    writer.add_weak_symbol(&mangled, section_ordinal, offset, g.is_external)
                } else {
                    writer.add_symbol(&mangled, section_ordinal, offset, g.is_external)
                }?;
                symbol_map.insert(g.name.clone(), symbol_id);
                symbol_map.insert(mangled, symbol_id);
                for sref in &g.symbol_refs {
                    let section_offset = checked_x86_object_u64_sum(
                        &g.name,
                        "Mach-O data relocation offset",
                        offset,
                        sref.offset,
                    )?;
                    data_reloc_work.push((
                        section_index,
                        section_offset,
                        sref.symbol.clone(),
                        sref.addend,
                    ));
                }
            }
        }
        // x86-64 Darwin thread-local DEFINITIONS: emit the TLV descriptor
        // (`__DATA,__thread_vars`) + initial-value template (`__DATA,__thread_data`)
        // sections and register the descriptor symbol `_X`, so an in-module
        // `movq _X@TLVP(%rip), r` (a `TlsTlv` fixup) resolves to the in-object
        // descriptor instead of an undefined external (an abort at first access —
        // the wp10-x86 `LOCAL_PANIC_COUNT` crux). The section/symbol layout is
        // shared VERBATIM with the AArch64 emitter (`add_tls_global_sections`);
        // only the two internal descriptor pointer relocations are emitted here as
        // `X86_64_RELOC_UNSIGNED` (vs the AArch64 caller's `ARM64_RELOC_UNSIGNED`).
        //
        // Registered BEFORE `defined_symbol_map` is snapshotted and before any
        // `final_symbol_index`/extern-relocation call freezes the nlist table, so
        // every descriptor / init-template / `__tlv_bootstrap` symbol exists ahead
        // of the relocation phase. A thread-local IMPORT (`is_import`) is EXCLUDED —
        // it defines no descriptor here; its `TlsTlv` fixup resolves to the
        // canonical descriptor in the defining object via the undefined-external
        // path below (exactly like the AArch64 emitter's import exclusion).
        let tls_globals: Vec<&crate::pipeline::ObjectGlobal> = globals
            .iter()
            .filter(|g| g.is_thread_local && !g.is_import)
            .collect();
        let (tls_descriptor_symbols, pending_tls_relocs) =
            crate::pipeline::add_tls_global_sections(&mut writer, &tls_globals).map_err(
                |error| {
                    X86PipelineError::ConstantPool(format!(
                        "x86-64 Mach-O thread-local descriptor section emission failed: {error}"
                    ))
                },
            )?;
        for (name, symbol_id) in tls_descriptor_symbols {
            let mangled = macho_x86_64_symbol_name(&name);
            symbol_map.insert(name, symbol_id);
            symbol_map.insert(mangled, symbol_id);
        }

        let defined_symbol_map = symbol_map.clone();
        // Names of cross-object data IMPORTS (e.g. a `static mut` defined in another
        // object): a `GlobalRef` to one of these resolves to an undefined external
        // the linker satisfies, rather than failing closed as an unknown symbol.
        let import_symbols: std::collections::HashSet<&str> = globals
            .iter()
            .filter(|g| g.is_import)
            .map(|g| g.name.as_str())
            .collect();

        // Register every undefined symbol before exposing any final nlist
        // index. Mach-O relocation records store that final numeric index; the
        // first lookup/extern relocation therefore freezes the writer's symbol
        // table so a later local/definition cannot silently shift an earlier
        // reference.
        for (_, _, symbol, _) in &data_reloc_work {
            if symbol_map
                .get(symbol)
                .or_else(|| symbol_map.get(&macho_x86_64_symbol_name(symbol)))
                .is_none()
            {
                let symbol_name = macho_x86_64_symbol_name(symbol);
                let symbol_id = writer.add_symbol(&symbol_name, 0, 0, true)?;
                symbol_map.insert(symbol.clone(), symbol_id);
                symbol_map.insert(symbol_name, symbol_id);
            }
        }
        for ef in encoded {
            for gf in &ef.global_ref_fixups {
                let may_be_undefined = match gf.kind {
                    X86SymbolRefFixupKind::GlobalRef => import_symbols.contains(gf.symbol.as_str()),
                    X86SymbolRefFixupKind::ExternRefGot | X86SymbolRefFixupKind::TlsTlv => true,
                };
                if may_be_undefined
                    && symbol_map
                        .get(&gf.symbol)
                        .or_else(|| symbol_map.get(&macho_x86_64_symbol_name(&gf.symbol)))
                        .is_none()
                {
                    let symbol_name = macho_x86_64_symbol_name(&gf.symbol);
                    let symbol_id = writer.add_symbol(&symbol_name, 0, 0, true)?;
                    symbol_map.insert(gf.symbol.clone(), symbol_id);
                    symbol_map.insert(symbol_name, symbol_id);
                }
            }
            for cf in &ef.call_fixups {
                if symbol_map
                    .get(&cf.callee)
                    .or_else(|| symbol_map.get(&macho_x86_64_symbol_name(&cf.callee)))
                    .is_none()
                {
                    let symbol_name = macho_x86_64_symbol_name(&cf.callee);
                    let symbol_id = writer.add_symbol(&symbol_name, 0, 0, true)?;
                    symbol_map.insert(cf.callee.clone(), symbol_id);
                    symbol_map.insert(symbol_name, symbol_id);
                }
            }
        }

        // EH Lane 2 Step 4: build the per-function unwind inputs, resolving each
        // EH function's LSDA + personality symbols (registered in Step 3) by name
        // from `symbol_map`. Fail closed if an EH function is missing its frame
        // metadata or symbols rather than silently dropping its LSDA (which would
        // abort/leak on unwind instead of unwinding).
        let mut unwind_inputs: Vec<X86EhFrameInput> = Vec::new();
        // `(text_offset, code_len)` per unwind-covered function, parallel to
        // `unwind_inputs` — the Step-4a `__compact_unwind` entry inputs.
        let mut compact_unwind_funcs: Vec<(u64, u32)> = Vec::new();
        for ef in encoded {
            let has_eh = ef.eh.is_some();
            let Some(metadata) = ef.frame_metadata.as_ref() else {
                if has_eh {
                    return Err(X86PipelineError::FrameLowering(format!(
                        "x86-64 Mach-O: EH function `{}` has no frame metadata; \
                         cannot emit its FDE/LSDA",
                        ef.name
                    )));
                }
                continue;
            };
            let Some(&function_symbol_id) = symbol_map.get(&ef.name) else {
                if has_eh {
                    return Err(X86PipelineError::FrameLowering(format!(
                        "x86-64 Mach-O: EH function `{}` symbol missing before unwind emission",
                        ef.name
                    )));
                }
                continue;
            };
            let eh = match ef.eh.as_ref() {
                Some(eh_data) => {
                    let lsda_name = format!("_GCC_except_table_{}", ef.name);
                    let personality_name = format!("_{}", eh_data.personality);
                    let lsda_symbol_id = *symbol_map.get(&lsda_name).ok_or_else(|| {
                        X86PipelineError::FrameLowering(format!(
                            "x86-64 Mach-O: LSDA symbol {lsda_name} missing before unwind emission"
                        ))
                    })?;
                    let personality_symbol_id =
                        *symbol_map.get(&personality_name).ok_or_else(|| {
                            X86PipelineError::FrameLowering(format!(
                                "x86-64 Mach-O: personality symbol {personality_name} missing \
                                 before unwind emission"
                            ))
                        })?;
                    Some(X86EhFdeInput {
                        personality: eh_data.personality.clone(),
                        personality_symbol_id,
                        lsda_symbol_id,
                    })
                }
                None => None,
            };
            unwind_inputs.push(X86EhFrameInput {
                callee_saved: metadata.callee_saved.clone(),
                frame_size: metadata.frame_size,
                code_len: ef.code_len,
                has_dynamic_alloc: metadata.has_dynamic_alloc,
                function_symbol_id,
                eh,
            });
            compact_unwind_funcs.push((ef.text_offset, ef.code_len));
        }
        // EH Lane 5 Step 4a (`__LD,__compact_unwind`): ld64's PRIMARY x86-64
        // unwind input. ld64 associates unwind info to atoms through these
        // 32-byte entries (function pointer via a SECTION-based UNSIGNED
        // relocation against `__text` with the function's offset baked in the
        // bytes — exactly the encoding clang emits); its `__eh_frame`-only
        // reader is a rarely-exercised fallback that mis-associates FDEs in
        // multi-function objects (observed: entries landing mid-atom, dropped
        // LSDAs — skipped cleanup Drops). Every entry uses the DWARF-fallback
        // mode (`UNWIND_X86_64_MODE_DWARF`, low 24 bits 0 exactly as clang
        // emits in objects), pointing the unwinder at the function's zPLR FDE
        // + LSDA emitted in Step 4b below, so the proven FDE path stays the
        // single source of unwind truth (no separate compact re-encoding of
        // the prologue to drift). Entries carry NO personality/LSDA fields —
        // ld64 reads both from the FDE for DWARF-mode entries. Gated on the
        // module carrying EH (mirroring Step 4b's FDE selection: in an EH
        // module every function has an LSDA — synthetic filler or real — and
        // gets an FDE; a no-EH module emits neither section, byte-identical
        // to before).
        if unwind_inputs.iter().any(|i| i.eh.is_some()) {
            const UNWIND_X86_64_MODE_DWARF: u32 = 0x0400_0000;
            const S_ATTR_DEBUG: u32 = 0x0200_0000;
            if let Some(last_index) = compact_unwind_funcs.len().checked_sub(1) {
                // `relocation_info.r_address` is signed/nonnegative i32. Check
                // the last entry before reserving the table so an oversized
                // count fails without attempting a multi-gigabyte allocation.
                checked_x86_macho_table_member_offset(
                    "<module>",
                    "compact-unwind entry offset",
                    last_index,
                    32,
                    0,
                )?;
            }
            let cu_capacity = checked_x86_object_table_size(
                "<module>",
                "compact-unwind table byte length",
                compact_unwind_funcs.len(),
                32,
            )?;
            let mut cu_data: Vec<u8> = Vec::with_capacity(cu_capacity);
            for &(text_offset, code_len) in &compact_unwind_funcs {
                cu_data.extend_from_slice(&text_offset.to_le_bytes()); // function
                cu_data.extend_from_slice(&code_len.to_le_bytes()); // length
                cu_data.extend_from_slice(&UNWIND_X86_64_MODE_DWARF.to_le_bytes());
                cu_data.extend_from_slice(&0u64.to_le_bytes()); // personality
                cu_data.extend_from_slice(&0u64.to_le_bytes()); // lsda
            }
            if !cu_data.is_empty() {
                let cu_section = writer.add_custom_section(
                    b"__compact_unwind",
                    b"__LD",
                    &cu_data,
                    3, // 2^3 = 8-byte alignment
                    S_ATTR_DEBUG,
                );
                for (i, _) in compact_unwind_funcs.iter().enumerate() {
                    // Section-based (extern=0) UNSIGNED reloc against __text
                    // (section ordinal 1); the baked bytes carry the offset.
                    let entry_offset = checked_x86_macho_table_member_offset(
                        "<module>",
                        "compact-unwind entry offset",
                        i,
                        32,
                        0,
                    )?;
                    writer.add_x86_64_relocation(
                        cu_section,
                        X86_64Relocation::section_relative(
                            entry_offset,
                            1,
                            crate::macho::x86_64_reloc::X86_64RelocKind::Unsigned,
                        ),
                    )?;
                }
            }
        }
        add_x86_64_eh_frame_to_macho(&mut writer, &unwind_inputs)?;

        // Emit data-pointer relocations only after unwind creation has added
        // its optional `EH_Frame` local symbol. The first final-index lookup
        // freezes the symbol table, so doing this earlier would make a module
        // containing both an address initializer and a backtrace-only FDE fail
        // (or, before freeze enforcement, silently stale the pointer index).
        for (section_index, section_offset, symbol, _addend) in &data_reloc_work {
            let symbol_id = symbol_map
                .get(symbol)
                .or_else(|| symbol_map.get(&macho_x86_64_symbol_name(symbol)))
                .copied()
                .ok_or_else(|| {
                    X86PipelineError::ConstantPool(format!(
                        "x86-64 Mach-O data-reloc symbol {symbol} was not registered before symbol-table freeze"
                    ))
                })?;
            let sym_idx = writer.final_symbol_index(symbol_id)?.ok_or_else(|| {
                X86PipelineError::ConstantPool(format!(
                    "x86-64 Mach-O data-reloc symbol {symbol} missing before relocation emission"
                ))
            })?;
            let relocation_offset = checked_x86_macho_relocation_offset_u64(
                symbol,
                "Mach-O data relocation offset",
                *section_offset,
            )?;
            let reloc = X86_64Relocation::unsigned_ptr(relocation_offset, sym_idx);
            writer.add_x86_64_relocation(*section_index, reloc)?;
        }

        // Emit the deferred `__DATA,__thread_vars` descriptor relocations (word 0
        // = `__tlv_bootstrap` dyld import, word 2 = `_X$tlv$init` template) as
        // `X86_64_RELOC_UNSIGNED` (8-byte absolute pointer slots) using final nlist
        // indices — the x86 mirror of the AArch64 emitter's `ARM64_RELOC_UNSIGNED`
        // descriptor fill. Every referenced symbol (`__tlv_bootstrap`, `_X$tlv$init`)
        // was registered by `add_tls_global_sections` above, before the freeze.
        for reloc in &pending_tls_relocs {
            let final_index = writer.final_symbol_index(reloc.symbol_id)?.ok_or_else(|| {
                X86PipelineError::ConstantPool(
                    "x86-64 Mach-O TLV descriptor relocation symbol missing before emission"
                        .to_string(),
                )
            })?;
            writer.add_x86_64_relocation(
                reloc.section_index,
                X86_64Relocation::unsigned_ptr(reloc.offset, final_index),
            )?;
        }

        // Convert symbol-address materialization fixups into x86-64
        // data-address relocations. GlobalRef uses SIGNED against defined
        // module symbols; ExternRef uses GOT_LOAD and may target undefined
        // externals.
        for ef in encoded {
            for gf in &ef.global_ref_fixups {
                let reloc = match gf.kind {
                    X86SymbolRefFixupKind::GlobalRef => {
                        let symbol_id = if let Some(&symbol_id) = defined_symbol_map
                            .get(&gf.symbol)
                            .or_else(|| defined_symbol_map.get(&format!("_{}", gf.symbol)))
                        {
                            symbol_id
                        } else if import_symbols.contains(gf.symbol.as_str()) {
                            // A cross-object data IMPORT (a `static mut` DEFINED in
                            // another object): register it as an undefined external the
                            // linker resolves to the canonical definition, and emit a
                            // DIRECT RIP-relative SIGNED reference — the symbol is
                            // statically linked into the same image, so no GOT
                            // indirection is needed (mirrors the call-fixup undefined
                            // external below).
                            let symbol_name = macho_x86_64_symbol_name(&gf.symbol);
                            if let Some(&id) = symbol_map
                                .get(&gf.symbol)
                                .or_else(|| symbol_map.get(&symbol_name))
                            {
                                id
                            } else {
                                let id = writer.add_symbol(&symbol_name, 0, 0, true)?;
                                symbol_map.insert(gf.symbol.clone(), id);
                                symbol_map.insert(symbol_name, id);
                                id
                            }
                        } else {
                            return Err(X86PipelineError::GlobalRefUnsupported {
                                function: ef.name.clone(),
                                symbol: gf.symbol.clone(),
                                reason:
                                    "Mach-O GlobalRef only supports symbols defined in the same x86 \
                                     module or declared as a cross-object data import"
                                        .to_string(),
                            });
                        };
                        let sym_idx = writer.final_symbol_index(symbol_id)?.ok_or_else(|| {
                            x86_symbol_ref_unsupported(
                                gf.kind,
                                ef.name.clone(),
                                gf.symbol.clone(),
                                "Mach-O GlobalRef symbol missing before relocation emission",
                            )
                        })?;
                        let relocation_offset = checked_x86_macho_section_offset(
                            &ef.name,
                            "Mach-O GlobalRef relocation offset",
                            ef.text_offset,
                            gf.offset,
                        )?;
                        X86_64Relocation::signed(relocation_offset, sym_idx)
                    }
                    X86SymbolRefFixupKind::ExternRefGot => {
                        let symbol_id = if let Some(&symbol_id) = symbol_map
                            .get(&gf.symbol)
                            .or_else(|| symbol_map.get(&format!("_{}", gf.symbol)))
                        {
                            symbol_id
                        } else {
                            let symbol_name = macho_x86_64_symbol_name(&gf.symbol);
                            let symbol_id = writer.add_symbol(&symbol_name, 0, 0, true)?;
                            symbol_map.insert(gf.symbol.clone(), symbol_id);
                            symbol_map.insert(symbol_name, symbol_id);
                            symbol_id
                        };
                        let sym_idx = writer.final_symbol_index(symbol_id)?.ok_or_else(|| {
                            x86_symbol_ref_unsupported(
                                gf.kind,
                                ef.name.clone(),
                                gf.symbol.clone(),
                                "Mach-O ExternRef symbol missing before relocation emission",
                            )
                        })?;
                        let relocation_offset = checked_x86_macho_section_offset(
                            &ef.name,
                            "Mach-O GOT relocation offset",
                            ef.text_offset,
                            gf.offset,
                        )?;
                        X86_64Relocation::got_load(relocation_offset, sym_idx)
                    }
                    X86SymbolRefFixupKind::TlsTlv => {
                        // Mach-O x86-64 Darwin TLS: X86_64_RELOC_TLV (pcrel,
                        // 4-byte) on the `movq _sym@TLVP(%rip), r` disp32.
                        // The symbol (`_tls.<hash>` runtime-defined
                        // `_Thread_local`) is an undefined external exactly
                        // like the GOT case; ld64 relaxes the load to LEA for
                        // image-local TLVs and the descriptor address lands in
                        // the register.
                        let symbol_id = if let Some(&symbol_id) = symbol_map
                            .get(&gf.symbol)
                            .or_else(|| symbol_map.get(&format!("_{}", gf.symbol)))
                        {
                            symbol_id
                        } else {
                            let symbol_name = macho_x86_64_symbol_name(&gf.symbol);
                            let symbol_id = writer.add_symbol(&symbol_name, 0, 0, true)?;
                            symbol_map.insert(gf.symbol.clone(), symbol_id);
                            symbol_map.insert(symbol_name, symbol_id);
                            symbol_id
                        };
                        let sym_idx = writer.final_symbol_index(symbol_id)?.ok_or_else(|| {
                            x86_symbol_ref_unsupported(
                                gf.kind,
                                ef.name.clone(),
                                gf.symbol.clone(),
                                "Mach-O TLV symbol missing before relocation emission",
                            )
                        })?;
                        let relocation_offset = checked_x86_macho_section_offset(
                            &ef.name,
                            "Mach-O TLV relocation offset",
                            ef.text_offset,
                            gf.offset,
                        )?;
                        X86_64Relocation::new(
                            relocation_offset,
                            sym_idx,
                            crate::macho::x86_64_reloc::X86_64RelocKind::Tlv,
                        )
                    }
                };
                writer.add_x86_64_relocation(0, reloc)?;
            }
        }

        // Convert each call fixup into an X86_64_RELOC_BRANCH relocation.
        // The fixup.offset is local to its function; add the function's
        // text_offset to get the offset within the combined __text section.
        for ef in encoded {
            for cf in &ef.call_fixups {
                // Missing callees are valid Mach-O undefined externals; the
                // linker or dynamic loader resolves or rejects them later.
                let symbol_id = if let Some(&symbol_id) = symbol_map
                    .get(&cf.callee)
                    .or_else(|| symbol_map.get(&format!("_{}", cf.callee)))
                {
                    symbol_id
                } else {
                    let symbol_name = macho_x86_64_symbol_name(&cf.callee);
                    let symbol_id = writer.add_symbol(&symbol_name, 0, 0, true)?;
                    symbol_map.insert(cf.callee.clone(), symbol_id);
                    symbol_map.insert(symbol_name, symbol_id);
                    symbol_id
                };
                let sym_idx = writer.final_symbol_index(symbol_id)?.ok_or_else(|| {
                    X86PipelineError::ConstantPool(format!(
                        "x86-64 Mach-O callee symbol {} missing before call relocation emission",
                        cf.callee
                    ))
                })?;
                let relocation_offset = checked_x86_macho_section_offset(
                    &ef.name,
                    "Mach-O branch relocation offset",
                    ef.text_offset,
                    cf.offset,
                )?;
                let reloc = X86_64Relocation::branch(relocation_offset, sym_idx);
                writer.add_x86_64_relocation(0, reloc)?;
            }
        }

        Ok(writer.write()?)
    }

    /// Emit a multi-function ELF object with x86-64 PLT32 CALL relocations (#464).
    fn emit_module_elf(
        &self,
        encoded: &[X86EncodedFunc],
        combined_code: &[u8],
        globals: &[crate::pipeline::ObjectGlobal],
    ) -> Result<Vec<u8>, X86PipelineError> {
        use crate::elf::constants::{SHF_ALLOC, SHF_WRITE, SHT_PROGBITS, STT_FUNC, STT_OBJECT};
        use crate::elf::reloc::{Elf64Rela, X86_64RelocType};

        // Thread-local globals are not wired for the x86-64 ELF emitter (no
        // `.tdata`/`.tbss` + TLS relocations). Fail closed rather than miscompile.
        reject_x86_thread_local_globals(globals)?;

        let mut writer = ElfWriter::new(ElfMachine::X86_64);
        writer.add_text_section_with_align(combined_code, 1u64 << x86_text_align_log2());

        // Build symbol table: one STT_FUNC per function at its text offset.
        //
        // ELF symbol indices start at 1 (index 0 is the null STN_UNDEF symbol,
        // automatically emitted by the writer). ElfWriter::add_symbol appends
        // to the symbol list in insertion order; our first add_symbol call
        // therefore corresponds to symbol index 1. The writer's stable
        // locals-before-globals partition preserves insertion order within the
        // all-global symbol set we emit here, so insertion order == final
        // symbol index. All data globals are emitted as global symbols too to
        // keep that invariant.
        let mut symbol_map: std::collections::HashMap<String, u32> =
            std::collections::HashMap::new();
        let mut next_symbol_index = 1u32;
        for ef in encoded {
            writer.add_symbol(&ef.name, 1, ef.text_offset, 0, true, STT_FUNC);
            symbol_map.insert(ef.name.clone(), next_symbol_index);
            next_symbol_index += 1;
        }

        // Emit module-level data globals into `.data` (mutable) or `.rodata`
        // (immutable) with a defined `STT_OBJECT` symbol each, so a `GlobalRef`
        // to a static data symbol resolves to an in-object PC32 relocation.
        //
        // A cross-object data IMPORT (`is_import` — e.g. a `static mut` DEFINED
        // in another object) contributes NO bytes here; it is an undefined
        // external the linker resolves. Exclude it from both definition
        // sections (its `GlobalRef` registers it as an undefined external
        // below); emitting it as a definition would be a duplicate symbol —
        // mirroring `emit_module_macho`'s import exclusion.
        let mutable_globals: Vec<&crate::pipeline::ObjectGlobal> = globals
            .iter()
            .filter(|g| !g.is_import && g.mutable)
            .collect();
        let immutable_globals: Vec<&crate::pipeline::ObjectGlobal> = globals
            .iter()
            .filter(|g| !g.is_import && !g.mutable)
            .collect();
        // Deferred data-section relocations from symbol-address slots. Stored
        // as `(reloc_section_idx_0based, section_relative_offset, symbol,
        // addend)`. ELF `RELA` carries the addend explicitly, so the slot stays
        // zero and `addend` is the rela's r_addend.
        let mut data_reloc_work: Vec<(usize, u64, String, i64)> = Vec::new();
        for (section_name, section_globals, sh_flags) in [
            (".data", &mutable_globals, SHF_ALLOC | SHF_WRITE),
            (".rodata", &immutable_globals, SHF_ALLOC),
        ] {
            if section_globals.is_empty() {
                continue;
            }
            let mut data = Vec::new();
            let mut offsets = Vec::with_capacity(section_globals.len());
            for g in section_globals.iter() {
                offsets.push(data.len() as u64);
                data.extend_from_slice(&g.data);
            }
            // `add_section` returns the 1-based section header table index,
            // which is exactly what `add_symbol`'s `section` field expects.
            // `add_relocation` uses the 0-based user-section index, hence -1.
            let section_idx = writer.add_section(section_name, &data, SHT_PROGBITS, sh_flags, 8);
            let reloc_section_idx = (section_idx - 1) as usize;
            for (g, offset) in section_globals.iter().zip(offsets) {
                // A weak DEFINITION gets STB_WEAK (coalescable across objects); a
                // strong one stays STB_GLOBAL. Both live in the writer's global
                // partition, so insertion order == final symbol index is preserved.
                if g.is_weak {
                    writer.add_weak_symbol(
                        &g.name,
                        section_idx,
                        offset,
                        g.data.len() as u64,
                        STT_OBJECT,
                    );
                } else {
                    writer.add_symbol(
                        &g.name,
                        section_idx,
                        offset,
                        g.data.len() as u64,
                        true,
                        STT_OBJECT,
                    );
                }
                symbol_map.insert(g.name.clone(), next_symbol_index);
                next_symbol_index += 1;
                for sref in &g.symbol_refs {
                    checked_x86_symbol_initializer_slot(
                        &g.name,
                        &sref.symbol,
                        sref.offset,
                        g.data.len(),
                    )?;
                    let section_offset = checked_x86_object_u64_sum(
                        &g.name,
                        "ELF data relocation offset",
                        offset,
                        sref.offset,
                    )?;
                    data_reloc_work.push((
                        reloc_section_idx,
                        section_offset,
                        sref.symbol.clone(),
                        sref.addend,
                    ));
                }
            }
        }
        let defined_symbol_map = symbol_map.clone();
        // Names of cross-object data IMPORTS: a `GlobalRef` to one of these
        // resolves to an undefined external the linker satisfies, rather than
        // failing closed as an unknown symbol (mirrors the Mach-O emitter's
        // `import_symbols` handling).
        let import_symbols: std::collections::HashSet<&str> = globals
            .iter()
            .filter(|g| g.is_import)
            .map(|g| g.name.as_str())
            .collect();

        // Emit one `R_X86_64_64` (absolute 64-bit) relocation per
        // symbol-address slot, into the `.rela.data` / `.rela.rodata` the ELF
        // writer auto-creates for any data section that has relocations. The
        // target may be a function or data global defined in this module, or an
        // external symbol (added as an undefined `STT_NOTYPE`). Verified for
        // shape only on this host — ELF cannot link/run here — mirroring the
        // Mach-O path that the on-host oracle exercises at run time.
        for (reloc_section_idx, section_offset, symbol, addend) in &data_reloc_work {
            let sym_idx = if let Some(&idx) = symbol_map.get(symbol) {
                idx
            } else {
                let idx = next_symbol_index;
                next_symbol_index += 1;
                writer.add_symbol(symbol, 0, 0, 0, true, crate::elf::constants::STT_NOTYPE);
                symbol_map.insert(symbol.clone(), idx);
                idx
            };
            let rela = Elf64Rela::x86_64(*section_offset, sym_idx, X86_64RelocType::Abs64, *addend);
            writer.add_relocation(*reloc_section_idx, rela);
        }

        let unwind_records: Vec<_> = encoded
            .iter()
            .filter_map(|ef| {
                let metadata = ef.frame_metadata.as_ref()?;
                let symbol_index = *symbol_map.get(&ef.name)?;
                x86_64_dynamic_eh_frame_record(metadata, ef.code_len, symbol_index)
            })
            .collect();
        add_x86_64_eh_frame_to_elf(&mut writer, &unwind_records);

        for ef in encoded {
            for gf in &ef.global_ref_fixups {
                let section_offset = checked_x86_object_u64_plus_usize(
                    &ef.name,
                    "ELF symbol-address relocation offset",
                    ef.text_offset,
                    gf.offset,
                )?;
                let (sym_idx, reloc_type) = match gf.kind {
                    X86SymbolRefFixupKind::GlobalRef => {
                        let sym_idx = if let Some(&sym_idx) = defined_symbol_map.get(&gf.symbol) {
                            sym_idx
                        } else if import_symbols.contains(gf.symbol.as_str()) {
                            // Cross-object data import: an undefined external
                            // (registered once) the linker resolves.
                            if let Some(&sym_idx) = symbol_map.get(&gf.symbol) {
                                sym_idx
                            } else {
                                let sym_idx = next_symbol_index;
                                next_symbol_index += 1;
                                writer.add_symbol(
                                    &gf.symbol,
                                    0,
                                    0,
                                    0,
                                    true,
                                    crate::elf::constants::STT_NOTYPE,
                                );
                                symbol_map.insert(gf.symbol.clone(), sym_idx);
                                sym_idx
                            }
                        } else {
                            return Err(X86PipelineError::GlobalRefUnsupported {
                                function: ef.name.clone(),
                                symbol: gf.symbol.clone(),
                                reason:
                                    "ELF GlobalRef only supports symbols defined in the same x86 module or declared data imports"
                                        .to_string(),
                            });
                        };
                        (sym_idx, X86_64RelocType::Pc32)
                    }
                    X86SymbolRefFixupKind::ExternRefGot => {
                        let sym_idx = if let Some(&sym_idx) = symbol_map.get(&gf.symbol) {
                            sym_idx
                        } else {
                            let sym_idx = next_symbol_index;
                            next_symbol_index += 1;
                            writer.add_symbol(
                                &gf.symbol,
                                0,
                                0,
                                0,
                                true,
                                crate::elf::constants::STT_NOTYPE,
                            );
                            symbol_map.insert(gf.symbol.clone(), sym_idx);
                            sym_idx
                        };
                        (sym_idx, X86_64RelocType::GotPcRel)
                    }
                    X86SymbolRefFixupKind::TlsTlv => {
                        return Err(x86_symbol_ref_unsupported(
                            gf.kind,
                            ef.name.clone(),
                            gf.symbol.clone(),
                            "x86-64 ELF has no TLV model; Darwin-only relocation",
                        ));
                    }
                };
                let rela = Elf64Rela::x86_64(section_offset, sym_idx, reloc_type, -4);
                writer.add_relocation(0, rela);
            }
        }

        // Convert each call fixup into an R_X86_64_PLT32 relocation.
        // Addend is -4 (standard for x86-64 PC-relative: the displacement is
        // computed from the END of the 4-byte displacement field, but the
        // relocation offset points to the START of it, so an implicit -4
        // addend adjusts for the 4-byte field itself).
        for ef in encoded {
            for cf in &ef.call_fixups {
                let section_offset = checked_x86_object_u64_plus_usize(
                    &ef.name,
                    "ELF call relocation offset",
                    ef.text_offset,
                    cf.offset,
                )?;
                let sym_idx = if let Some(&sym_idx) = symbol_map.get(&cf.callee) {
                    sym_idx
                } else {
                    let sym_idx = next_symbol_index;
                    next_symbol_index += 1;
                    writer.add_symbol(&cf.callee, 0, 0, 0, true, STT_FUNC);
                    symbol_map.insert(cf.callee.clone(), sym_idx);
                    sym_idx
                };
                let rela = Elf64Rela::x86_64(section_offset, sym_idx, X86_64RelocType::Plt32, -4);
                writer.add_relocation(0, rela);
            }
        }

        // Serialize through the checked funnel: the ELF reparse gate
        // independently re-parses the emitted bytes against intent and (at
        // the default Enforce) fails the write closed on any mismatch — the
        // per-object binding half of the relocation inventory's Certified
        // composition.
        writer
            .write_checked()
            .map_err(|e| X86PipelineError::ElfReparse(e.to_string()))
    }

    /// Emit a multi-function x86-64 COFF object with REL32 CALL relocations.
    fn emit_module_coff(
        &self,
        encoded: &[X86EncodedFunc],
        combined_code: &[u8],
        combined_rdata: &[u8],
        globals: &[crate::pipeline::ObjectGlobal],
    ) -> Result<Vec<u8>, X86PipelineError> {
        use crate::coff::{CoffRelocation, CoffWriter};

        // Fail closed for module-level data globals on the Windows/COFF path.
        // GlobalRef to a *defined function* symbol is already supported and
        // tested below (it resolves through `symbol_map`); but emitting a
        // COFF `.data`/`.rdata` data symbol plus its IMAGE_REL_AMD64_REL32
        // GlobalRef relocation cannot be link-and-run verified in this
        // environment (no Windows host / linker), so we reject rather than
        // risk a silent miscompile. The Mach-O and ELF paths emit data-symbol
        // relocations because they are verified by the on-host AOT oracle.
        if !globals.is_empty() {
            return Err(X86PipelineError::GlobalRefUnsupported {
                function: encoded.first().map(|e| e.name.clone()).unwrap_or_default(),
                symbol: globals[0].name.clone(),
                reason: "x86-64 COFF module data-symbol globals are not yet \
                         link-verified on this host; emission is fail-closed"
                    .to_string(),
            });
        }

        let mut text_bytes = combined_code.to_vec();
        let mut rdata_reloc_offsets = Vec::new();
        for ef in encoded {
            for fixup in &ef.const_pool_rel32_fixups {
                if combined_rdata.is_empty() {
                    return Err(X86PipelineError::ConstantPool(
                        "module x86-64 COFF has .text constant-pool relocations but no .rdata"
                            .to_string(),
                    ));
                }
                let fixup_offset = u64::try_from(fixup.disp32_offset).map_err(|_| {
                    X86PipelineError::ConstantPool(format!(
                        "COFF constant-pool relocation offset {} does not fit in u64",
                        fixup.disp32_offset
                    ))
                })?;
                let section_offset = ef.text_offset.checked_add(fixup_offset).ok_or_else(|| {
                    X86PipelineError::ConstantPool(
                        "COFF constant-pool relocation offset overflow".to_string(),
                    )
                })?;
                let start = usize::try_from(section_offset).map_err(|_| {
                    X86PipelineError::ConstantPool(format!(
                        "COFF constant-pool relocation offset {section_offset} does not fit in usize"
                    ))
                })?;
                let end = start.checked_add(4).ok_or_else(|| {
                    X86PipelineError::ConstantPool(
                        "COFF constant-pool relocation patch range overflow".to_string(),
                    )
                })?;
                if end > text_bytes.len() {
                    return Err(X86PipelineError::ConstantPool(format!(
                        "COFF constant-pool relocation range {start}..{end} exceeds .text size {}",
                        text_bytes.len()
                    )));
                }
                let addend = ef
                    .const_pool_rdata_offset
                    .checked_add(u64::from(fixup.const_pool_offset))
                    .ok_or_else(|| {
                        X86PipelineError::ConstantPool(
                            "COFF constant-pool .rdata addend overflow".to_string(),
                        )
                    })?;
                let addend = i32::try_from(addend).map_err(|_| {
                    X86PipelineError::ConstantPool(format!(
                        "COFF constant-pool .rdata addend {addend} does not fit in REL32 field"
                    ))
                })?;
                text_bytes[start..end].copy_from_slice(&addend.to_le_bytes());
                let virtual_address = u32::try_from(section_offset).map_err(|_| {
                    X86PipelineError::ConstantPool(format!(
                        "COFF constant-pool relocation offset {section_offset} does not fit in u32"
                    ))
                })?;
                rdata_reloc_offsets.push(virtual_address);
            }
        }

        let mut writer = CoffWriter::new_x86_64();
        let text = writer.add_text_section_with_align(&text_bytes, x86_text_align_log2());
        let rdata = if combined_rdata.is_empty() {
            None
        } else {
            Some(writer.add_readonly_data_section(combined_rdata))
        };
        let mut unwind_records = Vec::new();
        if self.config.call_abi == X86CallAbi::WindowsX64 {
            let mut xdata_offset = 0u32;
            for ef in encoded {
                if let Some(metadata) = ef.frame_metadata.as_ref() {
                    let record = x86_64_coff_unwind_record(
                        metadata,
                        &ef.name,
                        ef.text_offset,
                        ef.code_len,
                        xdata_offset,
                    )?;
                    let unwind_info_len = checked_x86_object_u32(
                        &ef.name,
                        "COFF unwind-info length",
                        record.unwind_info.len(),
                    )?;
                    xdata_offset = xdata_offset.checked_add(unwind_info_len).ok_or_else(|| {
                        X86PipelineError::FrameLowering(
                            "COFF unwind .xdata size overflow".to_string(),
                        )
                    })?;
                    unwind_records.push(record);
                }
            }
        }
        unwind_records.sort_by_key(|record| record.text_offset);
        let (pdata_bytes, xdata_bytes) = if unwind_records.is_empty() {
            (Vec::new(), Vec::new())
        } else {
            build_x86_64_coff_unwind_sections(&unwind_records)?
        };
        let xdata = if xdata_bytes.is_empty() {
            None
        } else {
            Some(writer.add_unwind_data_section(&xdata_bytes))
        };
        let pdata = if pdata_bytes.is_empty() {
            None
        } else {
            Some(writer.add_exception_data_section(&pdata_bytes))
        };

        let mut symbol_map: std::collections::HashMap<String, u32> =
            std::collections::HashMap::new();
        for ef in encoded {
            let text_offset = checked_x86_object_u32_u64(
                &ef.name,
                "COFF function symbol offset",
                ef.text_offset,
            )?;
            let symbol_index = writer.add_function_symbol(&ef.name, text, text_offset);
            symbol_map.insert(ef.name.clone(), symbol_index);
        }
        let mut import_symbol_map: std::collections::HashMap<String, u32> =
            std::collections::HashMap::new();
        let rdata_symbol = rdata.map(|section| writer.add_static_section_symbol(".rdata", section));
        let text_symbol = pdata.map(|_| writer.add_static_section_symbol(".text", text));
        let xdata_symbol = xdata.map(|section| writer.add_static_section_symbol(".xdata", section));

        let mut text_relocations = Vec::new();
        if !rdata_reloc_offsets.is_empty() {
            let Some(rdata_symbol) = rdata_symbol else {
                return Err(X86PipelineError::ConstantPool(
                    "module x86-64 COFF has .text constant-pool relocations but no .rdata symbol"
                        .to_string(),
                ));
            };
            for virtual_address in rdata_reloc_offsets {
                text_relocations.push(CoffRelocation::amd64_rel32(virtual_address, rdata_symbol));
            }
        }
        for ef in encoded {
            for cf in &ef.call_fixups {
                let Some(&sym_idx) = symbol_map.get(&cf.callee) else {
                    return Err(X86PipelineError::CoffUndefinedExternalCall {
                        caller: ef.name.clone(),
                        callee: cf.callee.clone(),
                    });
                };
                let virtual_address = checked_x86_object_section_offset(
                    &ef.name,
                    "COFF call relocation offset",
                    ef.text_offset,
                    cf.offset,
                )?;
                text_relocations.push(CoffRelocation::amd64_rel32(virtual_address, sym_idx));
            }
            for gf in &ef.global_ref_fixups {
                let sym_idx = match gf.kind {
                    X86SymbolRefFixupKind::GlobalRef => {
                        let Some(&sym_idx) = symbol_map.get(&gf.symbol) else {
                            return Err(X86PipelineError::GlobalRefUnsupported {
                                function: ef.name.clone(),
                                symbol: gf.symbol.clone(),
                                reason:
                                    "COFF GlobalRef only supports symbols defined in the same x86 module"
                                        .to_string(),
                            });
                        };
                        sym_idx
                    }
                    X86SymbolRefFixupKind::ExternRefGot => *import_symbol_map
                        .entry(gf.symbol.clone())
                        .or_insert_with(|| {
                            let import_name = coff_x86_64_import_symbol_name(&gf.symbol);
                            writer.add_symbol(
                                &import_name,
                                0,
                                0,
                                crate::coff::IMAGE_SYM_TYPE_NULL,
                                crate::coff::IMAGE_SYM_CLASS_EXTERNAL,
                            )
                        }),
                    X86SymbolRefFixupKind::TlsTlv => {
                        return Err(x86_symbol_ref_unsupported(
                            gf.kind,
                            ef.name.clone(),
                            gf.symbol.clone(),
                            "x86-64 COFF has no TLV model; Darwin-only relocation",
                        ));
                    }
                };
                let virtual_address = checked_x86_object_section_offset(
                    &ef.name,
                    "COFF symbol-address relocation offset",
                    ef.text_offset,
                    gf.offset,
                )?;
                text_relocations.push(CoffRelocation::amd64_rel32(virtual_address, sym_idx));
            }
        }

        text_relocations.sort_by_key(|reloc| reloc.virtual_address);
        for relocation in text_relocations {
            writer.add_relocation((text - 1) as usize, relocation);
        }

        if let (Some(pdata), Some(text_symbol), Some(xdata_symbol)) =
            (pdata, text_symbol, xdata_symbol)
        {
            let pdata_idx = (pdata - 1) as usize;
            for (record_idx, _record) in unwind_records.iter().enumerate() {
                let begin = checked_x86_object_table_offset(
                    "<module>",
                    "COFF .pdata begin relocation offset",
                    record_idx,
                    12,
                )?;
                let end = checked_x86_object_table_member_offset(
                    "<module>",
                    "COFF .pdata end relocation offset",
                    record_idx,
                    12,
                    4,
                )?;
                let unwind = checked_x86_object_table_member_offset(
                    "<module>",
                    "COFF .pdata unwind relocation offset",
                    record_idx,
                    12,
                    8,
                )?;
                writer.add_relocation(
                    pdata_idx,
                    CoffRelocation::amd64_addr32nb(begin, text_symbol),
                );
                writer.add_relocation(pdata_idx, CoffRelocation::amd64_addr32nb(end, text_symbol));
                writer.add_relocation(
                    pdata_idx,
                    CoffRelocation::amd64_addr32nb(unwind, xdata_symbol),
                );
            }
        }

        Ok(writer.write()?)
    }

    /// Compile a trust_ir function through the full pipeline (ISel + codegen).
    ///
    /// This is a convenience entry point that runs ISel first, then the
    /// rest of the pipeline.
    pub fn compile_trust_ir_function(
        &self,
        input: &trust_cg_lower::Function,
    ) -> Result<Vec<u8>, X86PipelineError> {
        let (code, _) = self.compile_trust_ir_function_with_regalloc_pressure_evidence(input)?;
        Ok(code)
    }

    /// Compile a trust_ir function through ISel and return regalloc pressure
    /// evidence alongside the emitted bytes.
    pub fn compile_trust_ir_function_with_regalloc_pressure_evidence(
        &self,
        input: &trust_cg_lower::Function,
    ) -> Result<(Vec<u8>, X86RegallocPressureEvidence), X86PipelineError> {
        use trust_cg_lower::x86_64_isel::X86InstructionSelector;

        input.validate_eh_structure().map_err(|reason| {
            X86PipelineError::ISel(format!(
                "invalid exception-handling structure in `{}`: {reason}",
                input.name
            ))
        })?;

        let sig = trust_cg_lower::function::Signature {
            params: input.signature.params.clone(),
            returns: input.signature.returns.clone(),
        };

        let mut isel =
            X86InstructionSelector::with_abi(input.name.clone(), sig.clone(), self.config.call_abi);
        isel.set_scalarize_v4i32_imul_with_sse2(
            !self
                .config
                .target_features
                .contains(X86TargetFeature::Sse41),
        );

        // Propagate LIR stack-slot metadata so x86 StackAddr lowering can
        // resolve fixed slots and gate runtime-sized slots in frame lowering.
        isel.set_stack_slots(input.stack_slots.clone());

        // Seed Value->Type hints from the adapter (Call/CallIndirect result
        // types, see #381). Must happen BEFORE select_block.
        isel.seed_value_types(&input.value_types);
        isel.seed_function_value_use_counts(input);

        // Whole-function pre-scan for Iconst origins. Enables cross-block
        // rematerialization in `use_value` so an SSA constant defined in one
        // block can be reused in any non-dominated successor.
        isel.seed_iconst_origins(input.blocks.values().map(|bb| bb.instructions.as_slice()));

        let block_order = input.layout_order();
        for block_ref in &block_order {
            isel.ensure_block(*block_ref);
        }

        // Lower formal arguments.
        isel.lower_formal_arguments(&sig, input.entry_block)
            .map_err(|e| X86PipelineError::ISel(e.to_string()))?;

        for block_ref in &block_order {
            let basic_block = &input.blocks[block_ref];
            if *block_ref != input.entry_block && !basic_block.params.is_empty() {
                isel.define_block_params(&basic_block.params);
            }
            isel.select_block(*block_ref, &basic_block.instructions)
                .map_err(|e| X86PipelineError::ISel(e.to_string()))?;
        }

        let isel_func = isel
            .finalize_with_eh_info(&input.eh_info)
            .map_err(|e| X86PipelineError::ISel(e.to_string()))?;
        // This public convenience API performs ISel directly instead of
        // entering `Compiler::compile_x86_64`. Apply the same production gate
        // to the exact pre-pass ISel/LIR pair before any pass can erase the
        // provenance stamps it validates.
        crate::compiler::enforce_x86_dataflow_integrity(&isel_func, input).map_err(|error| {
            X86PipelineError::ISel(format!("x86 dataflow-integrity gate: {error}"))
        })?;
        self.compile_function_with_regalloc_pressure_evidence(&isel_func)
    }

    /// Compile a trust_ir function through ISel and the full x86 pass pipeline,
    /// returning the raw emitted code bytes while discarding the call/global-ref
    /// fixups, const-pool data, and frame metadata.
    ///
    /// Unlike [`Self::compile_trust_ir_function`], this does not require an
    /// undefined direct callee to fail closed: it stops at the
    /// fixups+frame stage rather than relocation emission, so tests that exercise
    /// outgoing-stack-arg/shadow-space frame shaping with a symbolic callee can
    /// still inspect the prologue/CALL/epilogue byte stream.
    #[cfg(test)]
    pub(crate) fn compile_trust_ir_function_emitting_call_fixups(
        &self,
        input: &trust_cg_lower::Function,
    ) -> Result<Vec<u8>, X86PipelineError> {
        use trust_cg_lower::x86_64_isel::X86InstructionSelector;

        input.validate_eh_structure().map_err(|reason| {
            X86PipelineError::ISel(format!(
                "invalid exception-handling structure in `{}`: {reason}",
                input.name
            ))
        })?;

        let sig = trust_cg_lower::function::Signature {
            params: input.signature.params.clone(),
            returns: input.signature.returns.clone(),
        };

        let mut isel =
            X86InstructionSelector::with_abi(input.name.clone(), sig.clone(), self.config.call_abi);
        isel.set_scalarize_v4i32_imul_with_sse2(
            !self
                .config
                .target_features
                .contains(X86TargetFeature::Sse41),
        );

        isel.set_stack_slots(input.stack_slots.clone());
        isel.seed_value_types(&input.value_types);
        isel.seed_function_value_use_counts(input);
        isel.seed_iconst_origins(input.blocks.values().map(|bb| bb.instructions.as_slice()));

        let block_order = input.layout_order();
        for block_ref in &block_order {
            isel.ensure_block(*block_ref);
        }

        isel.lower_formal_arguments(&sig, input.entry_block)
            .map_err(|e| X86PipelineError::ISel(e.to_string()))?;

        for block_ref in &block_order {
            let basic_block = &input.blocks[block_ref];
            if *block_ref != input.entry_block && !basic_block.params.is_empty() {
                isel.define_block_params(&basic_block.params);
            }
            isel.select_block(*block_ref, &basic_block.instructions)
                .map_err(|e| X86PipelineError::ISel(e.to_string()))?;
        }

        let isel_func = isel
            .finalize_with_eh_info(&input.eh_info)
            .map_err(|e| X86PipelineError::ISel(e.to_string()))?;
        reject_x86_eh_sidecar_drop(
            &self.config,
            &isel_func,
            "compile_trust_ir_function_emitting_call_fixups",
        )?;
        let (code, ..) =
            self.compile_function_with_fixups_and_frame_after_x86_passes(&isel_func)?;
        Ok(code)
    }

    // --- Phase implementations ---

    /// Insert prologue/epilogue into the function.
    fn insert_prologue_epilogue(
        &self,
        func: &mut X86ISelFunction,
        assignment: &X86RegAssignment,
        layout: &X86StackFrameLayout,
    ) {
        let prologue = generate_prologue(
            &assignment.used_callee_saved,
            &assignment.used_callee_saved_xmms,
            &layout.xmm_save_offsets,
            layout.frame_size,
        );
        let epilogue = generate_epilogue(
            &assignment.used_callee_saved,
            &assignment.used_callee_saved_xmms,
            &layout.xmm_save_offsets,
            layout.frame_size,
            layout.has_dynamic_alloc,
        );

        // Insert prologue at the start of the entry block.
        if let Some(entry_block) = func.block_order.first().copied()
            && let Some(mblock) = func.blocks.get_mut(&entry_block)
        {
            // Prepend prologue instructions.
            let mut new_insts = prologue;
            new_insts.append(&mut mblock.insts);
            mblock.insts = new_insts;
        }

        // Insert epilogue before every RET instruction.
        for block_id in func.block_order.clone() {
            if let Some(mblock) = func.blocks.get_mut(&block_id) {
                let mut new_insts = Vec::new();
                for inst in &mblock.insts {
                    if inst.opcode == X86Opcode::Ret {
                        new_insts.extend(epilogue.clone());
                    }
                    new_insts.push(inst.clone());
                }
                mblock.insts = new_insts;
            }
        }
    }

    /// Encode all instructions in the function to machine code bytes.
    ///
    /// Also returns fixup information for constant pool RIP-relative references.
    /// Each fixup is a `(disp32_byte_offset_in_code, const_pool_entry_index)`.
    fn encode_function_with_fixups(
        &self,
        func: &X86ISelFunction,
        alloc: &HashMap<VReg, X86PReg>,
    ) -> Result<(Vec<u8>, Vec<(usize, usize)>), X86PipelineError> {
        let (code, cp_fixups, _call_fixups, _global_ref_fixups) =
            self.encode_function_with_all_fixups(func, alloc)?;
        Ok((code, cp_fixups))
    }

    /// Encode a function, tracking both constant-pool fixups and call-site
    /// fixups for cross-function CALL relocations (#464).
    ///
    /// `call_fixups` records, for each `X86Opcode::Call` with a
    /// `X86ISelOperand::Symbol(name)` target, the byte offset of the `disp32`
    /// field within the encoded code and the target callee name. The caller
    /// (multi-function module emitter) converts these to proper Mach-O /
    /// ELF relocations against the combined `.text` section.
    ///
    /// This is a single-function primitive; it does not know about other
    /// functions' offsets in the combined section.
    fn encode_function_with_all_fixups(
        &self,
        func: &X86ISelFunction,
        alloc: &HashMap<VReg, X86PReg>,
    ) -> Result<
        (
            Vec<u8>,
            Vec<(usize, usize)>,
            Vec<X86CallFixup>,
            Vec<X86GlobalRefFixup>,
        ),
        X86PipelineError,
    > {
        let (code, cp_fixups, call_fixups, global_ref_fixups, _, _, _) =
            self.encode_function_with_all_fixups_and_block_metadata(func, alloc, &HashMap::new())?;
        Ok((code, cp_fixups, call_fixups, global_ref_fixups))
    }

    fn encode_function_with_all_fixups_and_block_metadata(
        &self,
        func: &X86ISelFunction,
        alloc: &HashMap<VReg, X86PReg>,
        branch_targets: &HashMap<(LirBlock, usize), LirBlock>,
    ) -> Result<
        (
            Vec<u8>,
            Vec<(usize, usize)>,
            Vec<X86CallFixup>,
            Vec<X86GlobalRefFixup>,
            HashMap<LirBlock, usize>,
            X86EncodedCallRanges,
            Vec<X86BranchFixup>,
        ),
        X86PipelineError,
    > {
        validate_x86_resolved_function_layout(func)?;

        let mut encoder = X86Encoder::new();
        let mut cp_fixups: Vec<(usize, usize)> = Vec::new();
        // Jump-table LeaRip fixups: (disp32_byte_offset, jump_table_index). Patched
        // after the block loop, once block_offsets are final, by appending the
        // i64 PC-relative delta table to the code (in .text, after the body).
        let mut jt_fixups: Vec<(usize, u32)> = Vec::new();
        let mut call_fixups: Vec<X86CallFixup> = Vec::new();
        let mut global_ref_fixups: Vec<X86GlobalRefFixup> = Vec::new();
        let mut block_offsets: HashMap<LirBlock, usize> = HashMap::new();
        let record_eh_call_ranges = !func.eh_info.call_sites.is_empty();
        let mut encoded_call_ranges =
            X86EncodedCallRanges::with_capacity(func.eh_info.call_sites.len());
        let mut branch_fixups: Vec<X86BranchFixup> = Vec::new();

        // ENC-3: per-emission decode-check gate. Record, per emitted
        // instruction, its byte range + the intended (resolved opcode, ops) +
        // any fixup hole, then decode-and-compare the whole stream at the end.
        // This is the SINGLE encode funnel used by BOTH the AOT emission paths
        // and the profiling x86 JIT path, so hooking it here covers both.
        let dc_mode = crate::decode_check::decode_check_mode();
        let dc_recording = !matches!(dc_mode, crate::decode_check::DecodeCheckMode::Off);
        let mut dc_items: Vec<
            crate::decode_check::DecodeCheckItem<crate::x86_64::decode_check::X86IntentInst>,
        > = Vec::new();

        // JCC-erratum padding state. Default-on; kill switch
        // `TCG_NO_X86_JCC_ALIGN=1`. ACCEPT counter via
        // `TCG_X86_JCC_ALIGN_LOG=1`. ⚑ Both controls are mandatory here: passes
        // in this backend have repeatedly fired ZERO times while looking healthy,
        // and only an accept counter has ever caught it.
        let jcc_align_on = x86_jcc_align_enabled();
        let mut jcc_pads = 0usize;
        let mut jcc_pad_bytes = 0usize;

        // Layout successor of each block: `block_order[i] -> block_order[i+1]`.
        // Used to elide a block-trailing `jmp <next block in layout>`: control
        // falls through to the identical instruction (the next block's first
        // byte), so skipping the encode is a pure layout identity — the same
        // fall-through LLVM emits. Elision requires (a) an unconditional Jmp,
        // (b) whose branch target is exactly the layout successor, (c) with
        // only skipped pseudos after it in the block. The instruction STAYS in
        // the ISel stream (every pre-encode gate, cert, and validator sees
        // it); only its bytes are skipped, and every remaining branch is
        // patched from the ACTUAL encoded block offsets
        // (`patch_x86_branch_fixups_to_block_offsets`), so the size change is
        // fully absorbed. Kill switch: `TCG_NO_BRANCH_LAYOUT=1` (OPT-8).
        let elide_fallthrough_jmp = x86_branch_layout_enabled();
        let layout_successor: HashMap<LirBlock, LirBlock> =
            func.block_order.windows(2).map(|w| (w[0], w[1])).collect();

        for &block_id in &func.block_order {
            block_offsets.insert(block_id, encoder.position());
            if let Some(mblock) = func.blocks.get(&block_id) {
                for (inst_idx, inst) in mblock.insts.iter().enumerate() {
                    // Skip pseudo-instructions.
                    if matches!(
                        inst.opcode,
                        X86Opcode::Nop | X86Opcode::Phi | X86Opcode::StackAlloc
                    ) {
                        continue;
                    }

                    // Fall-through elision: a trailing `jmp` to the very next
                    // block in layout order encodes zero bytes.
                    if elide_fallthrough_jmp
                        && inst.opcode == X86Opcode::Jmp
                        && layout_successor.contains_key(&block_id)
                        && branch_targets.get(&(block_id, inst_idx)).copied()
                            == layout_successor.get(&block_id).copied()
                        && mblock.insts[inst_idx + 1..].iter().all(|later| {
                            matches!(
                                later.opcode,
                                X86Opcode::Nop | X86Opcode::Phi | X86Opcode::StackAlloc
                            )
                        })
                    {
                        continue;
                    }

                    reject_unsupported_x86_isel_inst(inst, self.config.target_features)?;
                    let mut ops = resolve_inst_operands(inst, alloc);
                    let opcode = resolved_encode_opcode(inst, &ops);

                    // Intel JCC erratum (doc 334524): on Skylake-family cores a
                    // branch — or a macro-fused ALU+Jcc pair — whose bytes cross a
                    // 32-byte boundary, or end on one, is excluded from the decoded
                    // uop cache, forcing legacy decode every iteration. Measured on
                    // a Kaby Lake host at 28.5% for a front-end-bound loop.
                    //
                    // Placed HERE deliberately: after the pseudo skip and the
                    // fall-through-JMP elision (an elided jmp encodes zero bytes and
                    // is not a hazard), after operand resolution (the pad depends on
                    // the exact encoded length), and BEFORE `dc_start` — so the
                    // padding sits outside this instruction's recorded byte range and
                    // every downstream offset consumer derives from the post-pad
                    // position with no side table to update.
                    if jcc_align_on
                        && let Some(pad) = x86_jcc_erratum_pad(
                            encoder.position(),
                            opcode,
                            &ops,
                            &mblock.insts,
                            inst_idx,
                            alloc,
                        )
                    {
                        let mut left = pad;
                        while left > 0 {
                            // The encoder clamps NopMulti to 1..=15 bytes; chunk
                            // deterministically rather than widening that contract,
                            // which lives in a different crate from the decode-check
                            // canonical-byte table and must move in lockstep with it.
                            let chunk = left.min(15);
                            let mut nop_ops = X86InstOperands::none();
                            nop_ops.imm = chunk as i64;
                            let nop_start = encoder.position();
                            encoder
                                .encode_instruction(X86Opcode::NopMulti, &nop_ops)
                                .map_err(X86PipelineError::from)?;
                            let nop_end = encoder.position();
                            if dc_recording {
                                dc_items.push(crate::decode_check::DecodeCheckItem {
                                    start: nop_start,
                                    end: nop_end,
                                    intent: crate::x86_64::decode_check::X86IntentInst {
                                        opcode: X86Opcode::NopMulti,
                                        ops: nop_ops,
                                    },
                                    hole: None,
                                });
                            }
                            left -= chunk;
                        }
                        jcc_pads += 1;
                        jcc_pad_bytes += pad;
                    }

                    // ENC-3: byte offset at which THIS instruction's bytes begin.
                    let dc_start = encoder.position();

                    // For RIP-relative constant pool loads, the imm field holds
                    // the entry index. Record fixup and set disp=0 as placeholder.
                    if matches!(opcode, X86Opcode::MovssRipRel | X86Opcode::MovsdRipRel) {
                        let entry_idx = ops.imm as usize;
                        // The disp32 is the last 4 bytes of the encoded instruction.
                        // We set disp=0 for now; the fixup pass patches it later.
                        ops.disp = 0;
                        ops.imm = 0;

                        encoder
                            .encode_instruction(opcode, &ops)
                            .map_err(X86PipelineError::from)?;
                        let after = encoder.position();

                        // The disp32 occupies the last 4 bytes of the instruction.
                        let disp32_offset = after - 4;
                        cp_fixups.push((disp32_offset, entry_idx));
                    } else if matches!(opcode, X86Opcode::Call) {
                        // CALL rel32: locate the symbol operand (callee name) and
                        // record a call fixup for later relocation emission.
                        // The encoder emits `E8 dd dd dd dd` (5 bytes) with
                        // disp=0; the disp32 field is the last 4 bytes.
                        let callee_name = inst.operands.iter().find_map(|op| {
                            if let X86ISelOperand::Symbol(s) = op {
                                Some(s.clone())
                            } else {
                                None
                            }
                        });

                        encoder
                            .encode_instruction(opcode, &ops)
                            .map_err(X86PipelineError::from)?;
                        let after = encoder.position();

                        if let Some(name) = callee_name {
                            // disp32 occupies the last 4 bytes of the CALL rel32
                            // encoding; the linker adds an implicit -4 addend for
                            // PC-relative displacement (x86 RIP points to the
                            // instruction *after* the 4-byte displacement, which
                            // is already handled by Mach-O X86_64_RELOC_BRANCH
                            // and ELF R_X86_64_PLT32/PC32 semantics).
                            let disp32_offset = after - 4;
                            call_fixups.push(X86CallFixup {
                                offset: disp32_offset,
                                callee: name,
                            });
                        }
                        // Indirect CALLs with no Symbol operand (CallR / CallM,
                        // or rare direct CALLs with immediate targets) generate
                        // no relocation.
                    } else if matches!(
                        opcode,
                        X86Opcode::LeaRip | X86Opcode::MovRipRel | X86Opcode::MovRipRelTlv
                    ) {
                        let symbol_name = inst.operands.iter().find_map(|op| {
                            if let X86ISelOperand::Symbol(s) = op {
                                Some(s.clone())
                            } else {
                                None
                            }
                        });
                        // A jump-table LeaRip (`lea base, [rip + JT]`) carries a
                        // JumpTableIndex instead of a Symbol; its disp32 is patched
                        // post-layout to the table base (appended after the body).
                        let jt_idx = inst.operands.iter().find_map(|op| {
                            if let X86ISelOperand::JumpTableIndex(i) = op {
                                Some(*i)
                            } else {
                                None
                            }
                        });

                        if symbol_name.is_some() || jt_idx.is_some() {
                            ops.disp = 0;
                        }

                        encoder
                            .encode_instruction(opcode, &ops)
                            .map_err(X86PipelineError::from)?;
                        let after = encoder.position();

                        if let Some(symbol) = symbol_name {
                            global_ref_fixups.push(X86GlobalRefFixup {
                                offset: after - 4,
                                symbol,
                                kind: if matches!(opcode, X86Opcode::MovRipRel) {
                                    X86SymbolRefFixupKind::ExternRefGot
                                } else if matches!(opcode, X86Opcode::MovRipRelTlv) {
                                    X86SymbolRefFixupKind::TlsTlv
                                } else {
                                    X86SymbolRefFixupKind::GlobalRef
                                },
                            });
                        } else if let Some(idx) = jt_idx {
                            jt_fixups.push((after - 4, idx));
                        }
                    } else {
                        encoder
                            .encode_instruction(opcode, &ops)
                            .map_err(X86PipelineError::from)?;
                        if matches!(opcode, X86Opcode::Jmp | X86Opcode::Jcc) {
                            // ⚑ FAIL CLOSED ON A MISSING FIXUP. By this point
                            // `resolve_x86_branches` phase 2 has already replaced the
                            // `Block` operand with an `Imm` derived from
                            // `estimate_inst_size`, which is documented as
                            // CONSERVATIVE (`_ => 7`). The bytes now in the buffer are
                            // therefore an ESTIMATE, and they are only correct because
                            // the fixup below overwrites them from real block offsets.
                            //
                            // Skipping the push when the lookup misses — which is what
                            // the previous `&& let Some(..)` did — leaves that estimate
                            // in place as the final displacement: a branch to the wrong
                            // address, in a program that still decodes perfectly. ENC-3
                            // decode-check cannot see it (the Jcc is well-formed) and no
                            // differential test can see it unless the wrong target
                            // happens to change observable output.
                            //
                            // It is latent today only because the estimate is usually
                            // close. Anything that widens the estimate error — notably
                            // inserting alignment padding — turns it into a live
                            // miscompile, so the seam is closed before that lands.
                            let Some(&target) = branch_targets.get(&(block_id, inst_idx)) else {
                                return Err(X86PipelineError::MalformedFunction {
                                    function: func.name.clone(),
                                    detail: format!(
                                        "x86-64 encode: {:?} at block {block_id:?} inst {inst_idx} \
                                         has no branch-target entry, so its displacement would keep \
                                         the pre-encode ESTIMATE instead of the real block offset",
                                        opcode
                                    ),
                                });
                            };
                            let after = encoder.position();
                            branch_fixups.push(X86BranchFixup {
                                disp32_offset: after - 4,
                                target,
                            });
                        }
                    }

                    // EH byte-range authority: capture every direct or indirect
                    // machine call at the one point where its exact variable-
                    // length encoding is known. The resolver later binds the
                    // block-granular EH record to one of these entries.
                    if record_eh_call_ranges
                        && matches!(
                            inst.opcode,
                            X86Opcode::Call | X86Opcode::CallR | X86Opcode::CallM
                        )
                    {
                        let end = encoder.position();
                        if end <= dc_start {
                            return Err(X86PipelineError::MalformedFunction {
                                function: func.name.clone(),
                                detail: format!(
                                    "machine call {}.{} encoded an empty byte range",
                                    block_id.0, inst_idx
                                ),
                            });
                        }
                        if encoded_call_ranges
                            .insert((block_id, inst_idx), (dc_start, end))
                            .is_some()
                        {
                            return Err(X86PipelineError::MalformedFunction {
                                function: func.name.clone(),
                                detail: format!(
                                    "duplicate encoded call identity {}.{}",
                                    block_id.0, inst_idx
                                ),
                            });
                        }
                    }

                    // ENC-3: record this instruction's emitted byte range + the
                    // intended (resolved opcode, ops) + any fixup hole, for the
                    // end-of-function decode-check. `ops` here is post-mutation,
                    // so it matches the bytes actually emitted.
                    if dc_recording {
                        let dc_end = encoder.position();
                        if dc_end > dc_start {
                            use crate::decode_check::{FixupHole, FixupHoleKind};
                            let hole_off = (dc_end - dc_start).saturating_sub(4);
                            let has_symbol = inst
                                .operands
                                .iter()
                                .any(|op| matches!(op, X86ISelOperand::Symbol(_)));
                            let has_jt = inst
                                .operands
                                .iter()
                                .any(|op| matches!(op, X86ISelOperand::JumpTableIndex(_)));
                            let hole = if matches!(
                                opcode,
                                X86Opcode::MovssRipRel | X86Opcode::MovsdRipRel
                            ) {
                                Some(FixupHole {
                                    offset_in_inst: hole_off,
                                    width: 4,
                                    kind: FixupHoleKind::ConstPool,
                                })
                            } else if matches!(opcode, X86Opcode::Call) && has_symbol {
                                Some(FixupHole {
                                    offset_in_inst: hole_off,
                                    width: 4,
                                    kind: FixupHoleKind::Call,
                                })
                            } else if matches!(
                                opcode,
                                X86Opcode::LeaRip | X86Opcode::MovRipRel | X86Opcode::MovRipRelTlv
                            ) && has_symbol
                            {
                                let kind = if matches!(opcode, X86Opcode::MovRipRel) {
                                    FixupHoleKind::ExternRefGot
                                } else if matches!(opcode, X86Opcode::MovRipRelTlv) {
                                    FixupHoleKind::TlsTlv
                                } else {
                                    FixupHoleKind::GlobalRef
                                };
                                Some(FixupHole {
                                    offset_in_inst: hole_off,
                                    width: 4,
                                    kind,
                                })
                            } else if matches!(opcode, X86Opcode::LeaRip) && has_jt {
                                // Jump-table LeaRip disp32: a post-layout-patched
                                // RIP-relative sentinel to the appended table, same
                                // hole shape as a const-pool RIP disp.
                                Some(FixupHole {
                                    offset_in_inst: hole_off,
                                    width: 4,
                                    kind: FixupHoleKind::ConstPool,
                                })
                            } else if matches!(opcode, X86Opcode::Jmp | X86Opcode::Jcc) {
                                // Branch rel32 is a placeholder patched by the
                                // branch-fixup pass — always treat it as a hole.
                                Some(FixupHole {
                                    offset_in_inst: hole_off,
                                    width: 4,
                                    kind: FixupHoleKind::Branch,
                                })
                            } else {
                                None
                            };
                            dc_items.push(crate::decode_check::DecodeCheckItem {
                                start: dc_start,
                                end: dc_end,
                                intent: crate::x86_64::decode_check::X86IntentInst {
                                    opcode,
                                    ops: ops.clone(),
                                },
                                hole,
                            });
                        }
                    }
                }
            }
        }

        if jcc_pads > 0 && crate::env_lock::var_os("TCG_X86_JCC_ALIGN_LOG").is_some() {
            eprintln!(
                "[jcc-align] ACCEPT {jcc_pads} pads, {jcc_pad_bytes} bytes in `{}`",
                func.name
            );
        }

        // ENC-3: decode-check the whole emitted stream against the recorded
        // intents before returning (pre-patch bytes: fixup holes are sentinels,
        // compared by placement not value). Fail-closed in Enforce mode.
        if dc_recording {
            crate::decode_check::run_decode_check(
                &crate::x86_64::decode_check::X86DecodeCheck,
                &dc_items,
                &encoder.bytes,
                dc_mode,
            )
            .map_err(|e| X86PipelineError::DecodeCheck(e.message))?;
        }

        let mut code = encoder.finish();

        // Jump-table emission (position-independent, no relocations): append each
        // referenced table's i64 PC-relative deltas to the code — in .text,
        // immediately after the function body, so the deltas
        // (`target_off - table_base`) and the RIP-relative LeaRip both resolve
        // within the single loaded code region. `block_offsets` are FINAL here
        // (the table follows every block, shifting none), and codegen types make
        // `LirBlock` the ISel `Block`, so the target lookup is direct. Every
        // failure mode (unknown table index / target with no block offset / a
        // delta beyond i64 or LEA disp beyond i32) is a hard error — fail closed,
        // never a silently mis-dispatched switch.
        if !jt_fixups.is_empty() {
            let mut table_base_of: HashMap<u32, usize> = HashMap::new();
            for &(_, jt_idx) in &jt_fixups {
                if table_base_of.contains_key(&jt_idx) {
                    continue;
                }
                // 8-byte align the table base (padding bytes are unreachable data
                // after the function's terminator). Entries are 8-byte signed
                // PC-relative deltas loaded by MovRMSib(scale=8).
                while !code.len().is_multiple_of(8) {
                    code.push(0x00);
                }
                let table_base = code.len();
                let jt = func.jump_tables.get(jt_idx as usize).ok_or_else(|| {
                    X86PipelineError::MalformedFunction {
                        function: func.name.clone(),
                        detail: format!("jump table index {jt_idx} out of range"),
                    }
                })?;
                for &tgt in &jt.targets {
                    let tgt_off = *block_offsets.get(&tgt).ok_or_else(|| {
                        X86PipelineError::MalformedFunction {
                            function: func.name.clone(),
                            detail: format!("jump table target {tgt:?} has no block offset"),
                        }
                    })?;
                    // delta = target_offset - table_base, as a 64-bit signed value
                    // (offsets are within one object's .text, so the difference
                    // fits i64 trivially; a table_base or target beyond i64 is a
                    // hard error via the checked usize->i64 conversions below).
                    let tgt_off_i64 = i64::try_from(tgt_off).map_err(|_| {
                        X86PipelineError::MalformedFunction {
                            function: func.name.clone(),
                            detail: "jump table target offset exceeds i64".to_string(),
                        }
                    })?;
                    let table_base_i64 = i64::try_from(table_base).map_err(|_| {
                        X86PipelineError::MalformedFunction {
                            function: func.name.clone(),
                            detail: "jump table base offset exceeds i64".to_string(),
                        }
                    })?;
                    let entry = tgt_off_i64.checked_sub(table_base_i64).ok_or_else(|| {
                        X86PipelineError::MalformedFunction {
                            function: func.name.clone(),
                            detail: "jump table PC-relative delta exceeds i64".to_string(),
                        }
                    })?;
                    code.extend_from_slice(&entry.to_le_bytes());
                }
                table_base_of.insert(jt_idx, table_base);
            }
            // Patch each referencing LeaRip disp32 = table_base - (lea_end).
            // RIP points PAST the disp32 (x86 convention), i.e. lea_disp32_off + 4.
            for &(lea_disp32_off, jt_idx) in &jt_fixups {
                let table_base = table_base_of[&jt_idx];
                let table_base_i64 =
                    i64::try_from(table_base).map_err(|_| X86PipelineError::MalformedFunction {
                        function: func.name.clone(),
                        detail: "jump table base offset exceeds i64".to_string(),
                    })?;
                let lea_end = i64::try_from(lea_disp32_off)
                    .ok()
                    .and_then(|off| off.checked_add(4))
                    .ok_or_else(|| X86PipelineError::MalformedFunction {
                        function: func.name.clone(),
                        detail: "jump table LeaRip offset exceeds i64".to_string(),
                    })?;
                let disp_i64 = table_base_i64.checked_sub(lea_end).ok_or_else(|| {
                    X86PipelineError::MalformedFunction {
                        function: func.name.clone(),
                        detail: "jump table LeaRip displacement exceeds i64".to_string(),
                    }
                })?;
                let disp =
                    i32::try_from(disp_i64).map_err(|_| X86PipelineError::MalformedFunction {
                        function: func.name.clone(),
                        detail: "jump table LeaRip displacement exceeds i32".to_string(),
                    })?;
                code[lea_disp32_off..lea_disp32_off + 4].copy_from_slice(&disp.to_le_bytes());
            }
        }

        Ok((
            code,
            cp_fixups,
            call_fixups,
            global_ref_fixups,
            block_offsets,
            encoded_call_ranges,
            branch_fixups,
        ))
    }

    /// Encode all instructions (legacy, no constant pool fixup tracking).
    #[allow(dead_code)]
    fn encode_function(
        &self,
        func: &X86ISelFunction,
        alloc: &HashMap<VReg, X86PReg>,
    ) -> Result<Vec<u8>, X86PipelineError> {
        let (code, _fixups) = self.encode_function_with_fixups(func, alloc)?;
        Ok(code)
    }

    /// Emit an ELF .o file wrapping the encoded machine code.
    #[allow(dead_code)]
    fn emit_elf(&self, func_name: &str, code: &[u8]) -> Result<Vec<u8>, X86PipelineError> {
        self.emit_elf_with_rodata(func_name, code, &[], None)
    }

    /// Emit an ELF .o file with optional .rodata section for constant pool.
    fn emit_elf_with_rodata(
        &self,
        func_name: &str,
        code: &[u8],
        rodata: &[u8],
        frame_metadata: Option<&X86FrameMetadata>,
    ) -> Result<Vec<u8>, X86PipelineError> {
        use crate::elf::constants::{SHF_ALLOC, SHT_PROGBITS};

        let mut writer = ElfWriter::new(ElfMachine::X86_64);
        writer.add_text_section_with_align(code, 1u64 << x86_text_align_log2());
        if !rodata.is_empty() {
            writer.add_section(".rodata", rodata, SHT_PROGBITS, SHF_ALLOC, 8);
        }
        writer.add_symbol(func_name, 1, 0, code.len() as u64, true, 2); // STT_FUNC
        if let Some(metadata) = frame_metadata {
            let code_len = checked_x86_code_len(func_name, code.len())?;
            if let Some(record) = x86_64_dynamic_eh_frame_record(metadata, code_len, 1) {
                add_x86_64_eh_frame_to_elf(&mut writer, &[record]);
            }
        }
        // Same checked funnel as the module emitter: every x86-64 ELF object
        // this pipeline serializes is reparse-gated.
        writer
            .write_checked()
            .map_err(|e| X86PipelineError::ElfReparse(e.to_string()))
    }

    /// Emit a Mach-O .o file wrapping the encoded machine code.
    #[allow(dead_code)]
    fn emit_macho(&self, func_name: &str, code: &[u8]) -> Result<Vec<u8>, X86PipelineError> {
        self.emit_macho_with_rodata(func_name, code, &[], None)
    }

    /// Emit a Mach-O .o file with optional __TEXT,__const and __TEXT,__eh_frame sections.
    fn emit_macho_with_rodata(
        &self,
        func_name: &str,
        code: &[u8],
        rodata: &[u8],
        frame_metadata: Option<&X86FrameMetadata>,
    ) -> Result<Vec<u8>, X86PipelineError> {
        use crate::macho::constants::S_REGULAR;

        let mut writer = MachOWriter::for_target(MachOTarget::X86_64);
        writer.add_text_section_with_align(code, x86_text_align_log2());
        if !rodata.is_empty() {
            // Use __TEXT,__const for read-only constant data (float literals).
            // Alignment = 3 (2^3 = 8 bytes, sufficient for f64 alignment).
            writer.add_custom_section(b"__const", b"__TEXT", rodata, 3, S_REGULAR);
        }

        // Mach-O convention: symbol names have underscore prefix.
        let macho_name = format!("_{}", func_name);
        let symbol_id = writer.add_symbol(&macho_name, 1, 0, true)?;

        if let Some(metadata) = frame_metadata {
            // Single-function backtrace-only path (no EH structure); the emitter
            // still skips a non-dynamic-alloc frame internally.
            let code_len = checked_x86_code_len(func_name, code.len())?;
            let input = X86EhFrameInput {
                callee_saved: metadata.callee_saved.clone(),
                frame_size: metadata.frame_size,
                code_len,
                has_dynamic_alloc: metadata.has_dynamic_alloc,
                function_symbol_id: symbol_id,
                eh: None,
            };
            add_x86_64_eh_frame_to_macho(&mut writer, &[input])?;
        }

        Ok(writer.write()?)
    }

    /// Emit a COFF .obj file wrapping the encoded machine code.
    fn emit_coff_with_rodata(
        &self,
        func_name: &str,
        code: &[u8],
        rodata: &[u8],
        rdata_rel32_offsets: &[usize],
        frame_metadata: Option<&X86FrameMetadata>,
    ) -> Result<Vec<u8>, X86PipelineError> {
        if rodata.is_empty() && !rdata_rel32_offsets.is_empty() {
            return Err(X86PipelineError::ConstantPool(
                "single-function x86-64 COFF has .text constant-pool relocations but no .rdata"
                    .to_string(),
            ));
        }

        let mut writer = crate::coff::CoffWriter::new_x86_64();
        let text = writer.add_text_section_with_align(code, x86_text_align_log2());
        let rdata = if rodata.is_empty() {
            None
        } else {
            Some(writer.add_readonly_data_section(rodata))
        };
        let unwind_record = frame_metadata
            .map(|metadata| {
                let code_len = checked_x86_code_len(func_name, code.len())?;
                x86_64_coff_unwind_record(metadata, func_name, 0, code_len, 0)
            })
            .transpose()?;
        let (pdata_bytes, xdata_bytes) = if let Some(record) = unwind_record.as_ref() {
            build_x86_64_coff_unwind_sections(std::slice::from_ref(record))?
        } else {
            (Vec::new(), Vec::new())
        };
        let xdata = if xdata_bytes.is_empty() {
            None
        } else {
            Some(writer.add_unwind_data_section(&xdata_bytes))
        };
        let pdata = if pdata_bytes.is_empty() {
            None
        } else {
            Some(writer.add_exception_data_section(&pdata_bytes))
        };

        writer.add_function_symbol(func_name, text, 0);
        if let Some(rdata) = rdata {
            let rdata_symbol = writer.add_static_section_symbol(".rdata", rdata);
            for &offset in rdata_rel32_offsets {
                let virtual_address = u32::try_from(offset).map_err(|_| {
                    X86PipelineError::ConstantPool(format!(
                        "COFF constant-pool relocation offset {offset} does not fit in u32"
                    ))
                })?;
                writer.add_relocation(
                    (text - 1) as usize,
                    crate::coff::CoffRelocation::amd64_rel32(virtual_address, rdata_symbol),
                );
            }
        }
        if let (Some(xdata), Some(pdata)) = (xdata, pdata) {
            let text_symbol = writer.add_static_section_symbol(".text", text);
            let xdata_symbol = writer.add_static_section_symbol(".xdata", xdata);
            let pdata_idx = (pdata - 1) as usize;
            for (record_idx, _record) in unwind_record.iter().enumerate() {
                let begin = checked_x86_object_table_offset(
                    func_name,
                    "COFF .pdata begin relocation offset",
                    record_idx,
                    12,
                )?;
                let end = checked_x86_object_table_member_offset(
                    func_name,
                    "COFF .pdata end relocation offset",
                    record_idx,
                    12,
                    4,
                )?;
                let unwind = checked_x86_object_table_member_offset(
                    func_name,
                    "COFF .pdata unwind relocation offset",
                    record_idx,
                    12,
                    8,
                )?;
                writer.add_relocation(
                    pdata_idx,
                    crate::coff::CoffRelocation::amd64_addr32nb(begin, text_symbol),
                );
                writer.add_relocation(
                    pdata_idx,
                    crate::coff::CoffRelocation::amd64_addr32nb(end, text_symbol),
                );
                writer.add_relocation(
                    pdata_idx,
                    crate::coff::CoffRelocation::amd64_addr32nb(unwind, xdata_symbol),
                );
            }
        }
        Ok(writer.write()?)
    }
}

// ---------------------------------------------------------------------------
// Convenience functions
// ---------------------------------------------------------------------------

/// Compile an x86-64 ISel function to raw machine code bytes.
pub fn x86_compile_to_bytes(func: &X86ISelFunction) -> Result<Vec<u8>, X86PipelineError> {
    let pipeline = X86Pipeline::default_config();
    pipeline.compile_function(func)
}

/// Compile an x86-64 ISel function to an ELF .o file.
pub fn x86_compile_to_elf(func: &X86ISelFunction) -> Result<Vec<u8>, X86PipelineError> {
    let pipeline = X86Pipeline::new(X86PipelineConfig {
        emit_elf: true,
        emit_frame: true,
        ..X86PipelineConfig::default()
    });
    pipeline.compile_function(func)
}

/// Compile an x86-64 ISel function to a Mach-O .o file.
///
/// Produces a valid x86-64 Mach-O relocatable object file suitable for
/// linking on macOS. The function is emitted as a global symbol with
/// Mach-O name mangling (_prefix).
pub fn x86_compile_to_macho(func: &X86ISelFunction) -> Result<Vec<u8>, X86PipelineError> {
    let pipeline = X86Pipeline::new(X86PipelineConfig {
        output_format: X86OutputFormat::MachO,
        emit_frame: true,
        ..X86PipelineConfig::default()
    });
    pipeline.compile_function(func)
}

/// Compile an x86-64 ISel function to a COFF .obj file.
///
/// Produces a parseable x86-64 COFF relocatable object file suitable for the
/// Windows AOT path's first production slice.
pub fn x86_compile_to_coff(func: &X86ISelFunction) -> Result<Vec<u8>, X86PipelineError> {
    let pipeline = X86Pipeline::new(X86PipelineConfig {
        output_format: X86OutputFormat::Coff,
        emit_frame: true,
        ..X86PipelineConfig::default()
    });
    pipeline.compile_function(func)
}

/// Compile an x86-64 ISel function using the full greedy register allocator.
///
/// Equivalent to `x86_compile_to_bytes` since the default pipeline now uses
/// `Full(Greedy)`. Retained for backward compatibility and explicitness.
pub fn x86_compile_with_greedy_regalloc(
    func: &X86ISelFunction,
) -> Result<Vec<u8>, X86PipelineError> {
    let pipeline = X86Pipeline::new(X86PipelineConfig {
        regalloc_mode: X86RegAllocMode::Full(AllocStrategy::Greedy),
        ..X86PipelineConfig::default()
    });
    pipeline.compile_function(func)
}

/// Build a simple `add(a: i64, b: i64) -> i64` x86-64 ISel function for testing.
///
/// System V AMD64 ABI: a in RDI, b in RSI, return in RAX.
pub fn build_x86_add_test_function() -> X86ISelFunction {
    use trust_cg_lower::function::Signature;
    use trust_cg_lower::instructions::Block;
    use trust_cg_lower::types::Type;

    let sig = Signature {
        params: vec![Type::I64, Type::I64],
        returns: vec![Type::I64],
    };

    let mut func = X86ISelFunction::new("add".to_string(), sig);
    let entry = Block(0);
    func.ensure_block(entry);

    let v0 = VReg::new(0, RegClass::Gpr64);
    let v1 = VReg::new(1, RegClass::Gpr64);
    let v2 = VReg::new(2, RegClass::Gpr64);
    func.next_vreg = 3;

    // MOV v0, RDI (arg 0)
    func.push_inst(
        entry,
        X86ISelInst::new(
            X86Opcode::MovRR,
            vec![
                X86ISelOperand::VReg(v0),
                X86ISelOperand::PReg(x86_64_regs::RDI),
            ],
        ),
    );

    // MOV v1, RSI (arg 1)
    func.push_inst(
        entry,
        X86ISelInst::new(
            X86Opcode::MovRR,
            vec![
                X86ISelOperand::VReg(v1),
                X86ISelOperand::PReg(x86_64_regs::RSI),
            ],
        ),
    );

    // ADD v2, v0, v1
    func.push_inst(
        entry,
        X86ISelInst::new(
            X86Opcode::AddRR,
            vec![
                X86ISelOperand::VReg(v2),
                X86ISelOperand::VReg(v0),
                X86ISelOperand::VReg(v1),
            ],
        ),
    );

    // MOV RAX, v2 (return value)
    func.push_inst(
        entry,
        X86ISelInst::new(
            X86Opcode::MovRR,
            vec![
                X86ISelOperand::PReg(x86_64_regs::RAX),
                X86ISelOperand::VReg(v2),
            ],
        ),
    );

    // RET
    func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

    func
}

/// Build a simple `const42() -> i64` x86-64 ISel function for testing.
///
/// Returns the constant 42.
pub fn build_x86_const_test_function() -> X86ISelFunction {
    use trust_cg_lower::function::Signature;
    use trust_cg_lower::instructions::Block;
    use trust_cg_lower::types::Type;

    let sig = Signature {
        params: vec![],
        returns: vec![Type::I64],
    };

    let mut func = X86ISelFunction::new("const42".to_string(), sig);
    let entry = Block(0);
    func.ensure_block(entry);

    let v0 = VReg::new(0, RegClass::Gpr64);
    func.next_vreg = 1;

    // MOV v0, 42
    func.push_inst(
        entry,
        X86ISelInst::new(
            X86Opcode::MovRI,
            vec![X86ISelOperand::VReg(v0), X86ISelOperand::Imm(42)],
        ),
    );

    // MOV RAX, v0
    func.push_inst(
        entry,
        X86ISelInst::new(
            X86Opcode::MovRR,
            vec![
                X86ISelOperand::PReg(x86_64_regs::RAX),
                X86ISelOperand::VReg(v0),
            ],
        ),
    );

    // RET
    func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

    func
}

