    #[test]
    fn x86_public_compile_rejects_reachable_layout_omission() {
        let pipeline = X86Pipeline::new(X86PipelineConfig::default());
        let mut func = minimal_func("reachable_x86_layout_omission");
        let omitted = Block(1);
        func.ensure_block(omitted);
        func.push_inst(
            Block(0),
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(omitted)]),
        );
        func.push_inst(omitted, X86ISelInst::new(X86Opcode::Ret, vec![]));
        func.blocks
            .get_mut(&Block(0))
            .unwrap()
            .successors
            .push(omitted);
        func.block_order = vec![Block(0)];

        let err = pipeline
            .compile_function(&func)
            .expect_err("a laid-out branch may not target an omitted map block");
        assert!(matches!(err, X86PipelineError::MalformedFunction { .. }));
        assert!(err.to_string().contains("absent from block_order"));
    }

