    #[test]
    fn x86_boundary_rejects_stale_cfg_before_tv5_dataflow() {
        let pipeline = X86Pipeline::new(X86PipelineConfig::default());
        let mut func = minimal_func("stale_x86_cfg");
        let successor = Block(1);
        func.ensure_block(successor);
        func.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::Call,
                vec![X86ISelOperand::Symbol("void_call".into())],
            ),
        );
        func.push_inst(
            Block(0),
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(successor)]),
        );
        func.push_inst(
            successor,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RBX), X86ISelOperand::PReg(RAX)],
            ),
        );
        func.push_inst(successor, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let err = pipeline
            .compile_function(&func)
            .expect_err("a branch edge omitted from successors must fail before TV5");
        assert!(matches!(&err, X86PipelineError::MalformedFunction { .. }));
        assert!(err.to_string().contains("successor metadata"));

        func.blocks
            .get_mut(&Block(0))
            .unwrap()
            .successors
            .push(successor);
        let tv5 = pipeline
            .recheck_post_regalloc(&func, &HashMap::new(), &HashSet::new())
            .expect_err("with exact CFG metadata TV5 must see the cross-block clobber");
        assert!(tv5.to_string().contains("POST-RA-DATAFLOW"));
    }

    #[test]
    fn x86_symbolic_boundary_rejects_resolved_branch_bypass() {
        let mut func = minimal_func("resolved_x86_cfg_bypass");
        let symbolic_source = Block(1);
        let target = Block(2);
        func.ensure_block(symbolic_source);
        func.ensure_block(target);
        func.push_inst(
            Block(0),
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Imm(0)]),
        );
        func.push_inst(
            symbolic_source,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(target)]),
        );
        func.push_inst(target, X86ISelInst::new(X86Opcode::Ret, vec![]));
        // Deliberately omit all successor metadata. A resolved branch in one
        // block must not disable exact checking for symbolic branches elsewhere.

        let err = validate_x86_function_layout(&func)
            .expect_err("resolved branch operands must be rejected before CFG authority");
        assert!(err.to_string().contains("resolved branch immediate"));
    }

    #[test]
    fn x86_cfg_derivation_treats_empty_and_all_pseudo_blocks_as_fallthrough() {
        for with_pseudo in [false, true] {
            let mut func = minimal_func(&format!("x86_fallthrough_{with_pseudo}"));
            let next = Block(1);
            func.ensure_block(next);
            if with_pseudo {
                func.push_inst(Block(0), X86ISelInst::new(X86Opcode::Nop, vec![]));
            }
            func.push_inst(next, X86ISelInst::new(X86Opcode::Ret, vec![]));
            func.blocks
                .get_mut(&Block(0))
                .unwrap()
                .successors
                .push(next);

            validate_x86_function_layout(&func)
                .expect("empty/all-pseudo blocks must fall through in layout order");
        }
    }

    #[test]
    fn x86_cfg_derivation_uses_last_non_pseudo_terminator() {
        let mut func = minimal_func("x86_trailing_pseudo_after_branch");
        let layout_next = Block(1);
        let target = Block(2);
        func.ensure_block(layout_next);
        func.ensure_block(target);
        func.push_inst(
            Block(0),
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(target)]),
        );
        func.push_inst(Block(0), X86ISelInst::new(X86Opcode::Nop, vec![]));
        for block in [layout_next, target] {
            func.push_inst(block, X86ISelInst::new(X86Opcode::Ret, vec![]));
        }
        func.blocks
            .get_mut(&Block(0))
            .unwrap()
            .successors
            .push(target);

        validate_x86_function_layout(&func)
            .expect("a trailing pseudo must not invent a layout-fallthrough edge");
    }

    fn test_vreg(id: u32) -> VReg {
        VReg::new(id, RegClass::Gpr64)
    }

    fn test_vreg_op(id: u32) -> X86ISelOperand {
        X86ISelOperand::VReg(test_vreg(id))
    }

    fn test_fpr128_vreg(id: u32) -> VReg {
        VReg::new(id, RegClass::Fpr128)
    }

    fn test_fpr128_op(id: u32) -> X86ISelOperand {
        X86ISelOperand::VReg(test_fpr128_vreg(id))
    }

    fn base_disp_mem(base: X86PReg, disp: i32) -> X86ISelOperand {
        X86ISelOperand::MemAddr {
            base: Box::new(X86ISelOperand::PReg(base)),
            disp,
        }
    }

    fn base_disp_mem_inst(
        opcode: X86Opcode,
        reg: X86PReg,
        base: X86PReg,
        disp: i32,
    ) -> X86ISelInst {
        X86ISelInst::new(
            opcode,
            vec![X86ISelOperand::PReg(reg), base_disp_mem(base, disp)],
        )
    }

    fn encoded_base_disp_mem_len(
        opcode: X86Opcode,
        reg: X86PReg,
        base: X86PReg,
        disp: i64,
    ) -> usize {
        let mut encoder = X86Encoder::new();
        encoder
            .encode_instruction(opcode, &X86InstOperands::rm(reg, base, disp))
            .unwrap()
    }

    fn code_contains_pmulld(code: &[u8]) -> bool {
        code.windows(4)
            .any(|bytes| bytes == [0x66, 0x0F, 0x38, 0x40])
            || code.windows(5).any(|bytes| {
                bytes[0] == 0x66
                    && (0x40..=0x4F).contains(&bytes[1])
                    && bytes[2] == 0x0F
                    && bytes[3] == 0x38
                    && bytes[4] == 0x40
            })
    }

    fn code_contains_sse2_opcode(code: &[u8], opcode: u8) -> bool {
        code.windows(3).any(|bytes| bytes == [0x66, 0x0F, opcode])
            || code.windows(4).any(|bytes| {
                bytes[0] == 0x66
                    && (0x40..=0x4F).contains(&bytes[1])
                    && bytes[2] == 0x0F
                    && bytes[3] == opcode
            })
    }

    fn v128_bool_select_func(name: &str) -> X86ISelFunction {
        let mut func = minimal_func(name);
        func.next_vreg = 4;
        func.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::V128BoolSelect,
                vec![
                    test_fpr128_op(0),
                    test_fpr128_op(1),
                    test_fpr128_op(2),
                    test_fpr128_op(3),
                ],
            ),
        );
        func
    }

    fn entry_insts(func: &X86ISelFunction) -> &[X86ISelInst] {
        &func.blocks.get(&Block(0)).unwrap().insts
    }

    fn entry_opcodes(func: &X86ISelFunction) -> Vec<X86Opcode> {
        entry_insts(func).iter().map(|inst| inst.opcode).collect()
    }

