    #[test]
    fn test_expand_x86_v128_bool_select_uses_pblendvb_with_implicit_xmm0() {
        let mut func = v128_bool_select_func("v128_bool_select_sse41");

        expand_x86_vector_bool_selects(&mut func, X86TargetFeatures::current()).unwrap();

        let insts = entry_insts(&func);
        assert_eq!(
            entry_opcodes(&func),
            vec![
                X86Opcode::MovdqaRR,
                X86Opcode::MovdqaRR,
                X86Opcode::Pblendvb,
            ]
        );
        assert_eq!(
            insts[0].operands,
            vec![test_fpr128_op(0), test_fpr128_op(3)]
        );
        assert_eq!(
            insts[1].operands,
            vec![X86ISelOperand::PReg(XMM0), test_fpr128_op(1)]
        );
        assert_eq!(
            insts[2].operands,
            vec![test_fpr128_op(0), test_fpr128_op(2)]
        );

        let ra_func = x86_isel_to_regalloc(&func).unwrap();
        let blend = &ra_func.insts[2];
        assert_eq!(blend.defs, vec![RegAllocOperand::VReg(test_fpr128_vreg(0))]);
        assert_eq!(
            blend.uses,
            vec![
                RegAllocOperand::VReg(test_fpr128_vreg(0)),
                RegAllocOperand::VReg(test_fpr128_vreg(2)),
            ]
        );
        assert!(blend.implicit_defs.is_empty());
        assert_eq!(blend.implicit_uses, vec![regalloc_preg(XMM0)]);
    }

