    /// Binds the popcnt EMITTER to the proven SWAR model: `expand_x86_popcnt_inst`
    /// must emit exactly the Hacker's-Delight fold masks that
    /// `trust_cg_verify::pass_validators::PopcntSwarExpansionValidator` proves
    /// compute the population count (and that `validate_x86_popcnt_expansion_canary`
    /// checks on every x86 compile). If the emitter's masks drift, the canary
    /// would be validating a model the encoder no longer emits — so pin them.
    #[test]
    fn popcnt_swar_expansion_emits_the_proven_fold_masks() {
        let mut func = minimal_func("popcnt64");
        func.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::Popcnt,
                vec![
                    X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                    X86ISelOperand::VReg(VReg::new(1, RegClass::Gpr64)),
                ],
            ),
        );

        expand_x86_generic_popcnts(&mut func, X86TargetFeatures::generic_x86_64()).unwrap();

        let insts = &func.blocks[&Block(0)].insts;
        assert!(
            !insts.iter().any(|i| i.opcode == X86Opcode::Popcnt),
            "Popcnt must be expanded away on the no-POPCNT generic target"
        );
        let movri_imms: Vec<i64> = insts
            .iter()
            .filter(|i| i.opcode == X86Opcode::MovRI)
            .filter_map(|i| match i.operands.get(1) {
                Some(X86ISelOperand::Imm(v)) => Some(*v),
                _ => None,
            })
            .collect();
        for expected in [
            0x5555_5555_5555_5555_i64,
            0x3333_3333_3333_3333,
            0x0f0f_0f0f_0f0f_0f0f,
        ] {
            assert!(
                movri_imms.contains(&expected),
                "popcnt SWAR fold mask {expected:#x} missing (emitter drifted from the proven model): {movri_imms:x?}"
            );
        }
        assert!(
            insts.iter().any(|i| i.opcode == X86Opcode::AndRI
                && matches!(i.operands.get(1), Some(X86ISelOperand::Imm(0x7f)))),
            "popcnt SWAR final mask 0x7f missing"
        );
    }

    /// Pins the four Sentinel-S5 guard-carrier expansions to their CORRECT trap
    /// CONDITION — the silent-miscompile risk of the post-cert encoder expansion
    /// (each carrier is a proof-only pseudo SKIPPED by the per-instruction
    /// verifier, then rewritten here into a CMP/TEST + Jcc + UD2 the certificate
    /// never saw). Zero-checks (null / div-by-zero) MUST trap on E (== 0);
    /// range-checks (bounds / shift) MUST trap on AE (unsigned >=). A flipped
    /// condition would silently invert every guard. (CMP/TEST/Jcc are themselves
    /// proven opcodes; this binds the EXPANSION's structure + condition choice.)
    #[test]
    fn guard_carrier_expansions_emit_the_correct_trap_condition() {
        let reg = |i| X86ISelOperand::VReg(VReg::new(i, RegClass::Gpr64));
        // (carrier, expected compare opcode, expected trap condition).
        let cases: Vec<(X86ISelInst, X86Opcode, X86CondCode)> = vec![
            (
                X86ISelInst::new(X86Opcode::TrapDivZeroExact, vec![reg(0)]),
                X86Opcode::TestRR,
                X86CondCode::E,
            ),
            (
                X86ISelInst::new(X86Opcode::TrapNullIfZeroExact, vec![reg(0)]),
                X86Opcode::TestRR,
                X86CondCode::E,
            ),
            (
                X86ISelInst::new(
                    X86Opcode::TrapBoundsCheckExact,
                    vec![reg(0), reg(1), X86ISelOperand::Imm(8)],
                ),
                X86Opcode::CmpRI,
                X86CondCode::AE,
            ),
            (
                X86ISelInst::new(
                    X86Opcode::TrapShiftRangeExact,
                    vec![reg(0), X86ISelOperand::Imm(64)],
                ),
                X86Opcode::CmpRI,
                X86CondCode::AE,
            ),
        ];

        for (carrier, expect_cmp, expect_cc) in cases {
            let op = carrier.opcode;
            let mut func = minimal_func("guard_carrier");
            func.push_inst(Block(0), carrier);
            match op {
                X86Opcode::TrapDivZeroExact => {
                    expand_x86_div_zero_check_carriers_after_canary(&mut func, expect_cc).unwrap()
                }
                X86Opcode::TrapNullIfZeroExact => {
                    expand_x86_null_check_carriers_after_canary(&mut func, expect_cc).unwrap()
                }
                X86Opcode::TrapBoundsCheckExact => {
                    expand_x86_bounds_check_carriers_after_canary(&mut func, expect_cc).unwrap()
                }
                X86Opcode::TrapShiftRangeExact => {
                    expand_x86_shift_range_check_carriers_after_canary(&mut func, expect_cc)
                        .unwrap()
                }
                _ => unreachable!(),
            }
            let insts = &func.blocks[&Block(0)].insts;
            assert!(
                !insts.iter().any(|i| i.opcode == op),
                "{op:?} carrier must be expanded away"
            );
            assert!(
                insts.iter().any(|i| i.opcode == expect_cmp),
                "{op:?} must emit {expect_cmp:?}"
            );
            let jcc_cc = insts
                .iter()
                .find(|i| i.opcode == X86Opcode::Jcc)
                .and_then(|i| match i.operands.first() {
                    Some(X86ISelOperand::CondCode(cc)) => Some(*cc),
                    _ => None,
                });
            assert_eq!(
                jcc_cc,
                Some(expect_cc),
                "{op:?} must trap on {expect_cc:?} (a flipped condition inverts the guard)"
            );
            assert!(
                func.blocks
                    .values()
                    .any(|b| b.insts.iter().any(|i| i.opcode == X86Opcode::Ud2)),
                "{op:?} must produce a UD2 trap block"
            );
        }
    }

