    #[test]
    fn test_pipeline_expands_v8i16_mask_extract_to_compact_lane_bits() {
        let mut func = minimal_func("v8i16_mask_extract_pipeline");
        let entry = Block(0);
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::V8I16MaskExtract,
                vec![X86ISelOperand::PReg(EAX), X86ISelOperand::PReg(XMM2)],
            ),
        );

        expand_x86_vector_mask_extracts(&mut func).unwrap();
        let insts = &func.blocks.get(&entry).unwrap().insts;

        assert_eq!(
            insts.iter().map(|inst| inst.opcode).collect::<Vec<_>>(),
            vec![
                X86Opcode::Pmovmskb,
                X86Opcode::AndRI,
                X86Opcode::MovRR32,
                X86Opcode::ShrRI,
                X86Opcode::OrRR,
                X86Opcode::AndRI,
                X86Opcode::MovRR32,
                X86Opcode::ShrRI,
                X86Opcode::OrRR,
                X86Opcode::AndRI,
                X86Opcode::MovRR32,
                X86Opcode::ShrRI,
                X86Opcode::OrRR,
                X86Opcode::AndRI,
            ]
        );

        let imms = insts
            .iter()
            .flat_map(|inst| inst.operands.iter())
            .filter_map(|op| match op {
                X86ISelOperand::Imm(imm) => Some(*imm),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(imms, vec![0x5555, 1, 0x3333, 2, 0x0f0f, 4, 0x00ff]);
    }

    #[test]
    fn test_pipeline_expands_v2i64_mask_extract_to_compact_lane_bits() {
        let mut func = minimal_func("v2i64_mask_extract_pipeline");
        let entry = Block(0);
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::V2I64MaskExtract,
                vec![X86ISelOperand::PReg(EAX), X86ISelOperand::PReg(XMM2)],
            ),
        );
        let pipeline = raw_no_frame_x86_pipeline();

        let code = pipeline.compile_function(&func).unwrap();

        assert_eq!(
            code,
            vec![
                0x66, 0x0F, 0xD7, 0xC2, // PMOVMSKB EAX, XMM2
                0xC1, 0xE8, 0x07, // SHR EAX, 7
                0x83, 0xE0, 0x03, // AND EAX, 0x03
            ]
        );
    }

