    #[test]
    fn test_manual_sib_isel_opcodes_fail_closed() {
        let pipeline = raw_no_frame_x86_pipeline();

        for opcode in [X86Opcode::MovRMSib, X86Opcode::MovMRSib, X86Opcode::LeaSib] {
            let mut func = minimal_func("manual_sib_fail_closed");
            func.push_inst(
                Block(0),
                X86ISelInst::new(
                    opcode,
                    vec![
                        X86ISelOperand::PReg(RAX),
                        X86ISelOperand::PReg(RBP),
                        X86ISelOperand::PReg(RDI),
                        X86ISelOperand::Imm(4),
                        X86ISelOperand::Imm(16),
                    ],
                ),
            );

            match pipeline.compile_function(&func) {
                Err(X86PipelineError::ISel(msg)) => {
                    assert!(
                        msg.contains("SIB ISel opcodes require X86ISelOperand::SibMemAddr"),
                        "unexpected {opcode:?} fail-closed message: {msg}"
                    );
                }
                other => panic!("expected {opcode:?} to fail closed in ISel, got {other:?}"),
            }
        }
    }

    fn sib_mem(base: X86ISelOperand, index: X86ISelOperand) -> X86ISelOperand {
        X86ISelOperand::SibMemAddr {
            base: Box::new(base),
            index: Box::new(index),
            scale: 4,
            disp: 16,
        }
    }

    #[test]
    fn test_sib_isel_operand_encodes_load_store_and_lea() {
        let pipeline = raw_no_frame_x86_pipeline();

        let cases = [
            (
                X86Opcode::MovRMSib,
                vec![
                    X86ISelOperand::PReg(RAX),
                    sib_mem(
                        X86ISelOperand::PReg(x86_64_regs::RBX),
                        X86ISelOperand::PReg(x86_64_regs::RCX),
                    ),
                ],
                vec![0x48, 0x8B, 0x44, 0x8B, 0x10],
            ),
            (
                X86Opcode::MovMRSib,
                vec![
                    sib_mem(
                        X86ISelOperand::PReg(x86_64_regs::RBX),
                        X86ISelOperand::PReg(x86_64_regs::RCX),
                    ),
                    X86ISelOperand::PReg(RAX),
                ],
                vec![0x48, 0x89, 0x44, 0x8B, 0x10],
            ),
            (
                X86Opcode::LeaSib,
                vec![
                    X86ISelOperand::PReg(RAX),
                    sib_mem(
                        X86ISelOperand::PReg(x86_64_regs::RBX),
                        X86ISelOperand::PReg(x86_64_regs::RCX),
                    ),
                ],
                vec![0x48, 0x8D, 0x44, 0x8B, 0x10],
            ),
        ];

        for (opcode, operands, expected) in cases {
            let mut func = minimal_func("sib_isel_bridge_encode");
            func.push_inst(Block(0), X86ISelInst::new(opcode, operands));

            let bytes = pipeline.compile_function(&func).unwrap_or_else(|err| {
                panic!("{opcode:?} should compile through SIB bridge: {err:?}")
            });
            assert_eq!(bytes, expected, "{opcode:?} encoded bytes");
        }
    }

    #[test]
    fn test_sib_isel_regalloc_conversion_tracks_base_and_index_uses() {
        let dst = test_vreg(0);
        let base = test_vreg(1);
        let index = test_vreg(2);
        let mut func = minimal_func("sib_regalloc_uses");
        func.next_vreg = 3;
        func.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::LeaSib,
                vec![
                    X86ISelOperand::VReg(dst),
                    sib_mem(X86ISelOperand::VReg(base), X86ISelOperand::VReg(index)),
                ],
            ),
        );

        let ra_func = x86_isel_to_regalloc(&func).expect("SIB ISel should convert to regalloc");
        let ra_inst = &ra_func.insts[0];
        assert_eq!(ra_inst.defs, vec![RegAllocOperand::VReg(dst)]);
        assert_eq!(
            ra_inst.uses,
            vec![
                RegAllocOperand::VReg(base),
                RegAllocOperand::Imm(16),
                RegAllocOperand::VReg(index),
                RegAllocOperand::Imm(4),
            ]
        );
    }

    fn array_gep_return_lir(name: &str, elem_ty: Type) -> LirFunction {
        let mut func = LirFunction::new(
            name,
            Signature {
                params: vec![Type::I64, Type::I64],
                returns: vec![Type::I64],
            },
        );
        let entry = Block(0);
        func.entry_block = entry;
        func.block_order.push(entry);
        func.blocks.insert(
            entry,
            BasicBlock {
                params: vec![],
                instructions: vec![
                    Instruction {
                        opcode: Opcode::ArrayGep { elem_ty },
                        args: vec![Value(0), Value(1)],
                        results: vec![Value(2)],
                    },
                    Instruction {
                        opcode: Opcode::Return,
                        args: vec![Value(2)],
                        results: vec![],
                    },
                ],
                source_locs: vec![],
            },
        );
        func
    }

    fn has_imul_imm_opcode(code: &[u8]) -> bool {
        code.iter().any(|byte| matches!(byte, 0x69 | 0x6b))
    }

    #[test]
    fn test_array_gep_supported_scales_compile_without_imul_imm() {
        let pipeline = raw_no_frame_x86_pipeline();

        for (elem_ty, name) in [
            (Type::I8, "array_gep_scale1"),
            (Type::I16, "array_gep_scale2"),
            (Type::I32, "array_gep_scale4"),
            (Type::F64, "array_gep_scale8"),
        ] {
            let func = array_gep_return_lir(name, elem_ty);
            let code = pipeline.compile_trust_ir_function(&func).unwrap();

            assert!(
                code.contains(&0x8d),
                "{name} should encode LEA for scaled ArrayGep; code={code:02x?}"
            );
            assert!(
                !has_imul_imm_opcode(&code),
                "{name} should not encode IMUL immediate for supported SIB scale; code={code:02x?}"
            );
        }
    }

