    #[test]
    fn x86_isel_to_regalloc_preserves_ptest_operand_precise_memory_flags() {
        let mut func = minimal_func("ptest_flags_to_regalloc");
        func.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::Ptest,
                vec![X86ISelOperand::PReg(XMM0), X86ISelOperand::PReg(XMM1)],
            ),
        );
        func.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::Ptest,
                vec![
                    X86ISelOperand::PReg(XMM0),
                    X86ISelOperand::MemAddr {
                        base: Box::new(X86ISelOperand::PReg(RAX)),
                        disp: 16,
                    },
                ],
            ),
        );

        let ra_func = x86_isel_to_regalloc(&func).unwrap();

        assert_eq!(ra_func.insts.len(), 2);
        assert!(ra_func.insts[0].flags.has_side_effects());
        assert!(!ra_func.insts[0].flags.reads_memory());
        assert!(ra_func.insts[1].flags.has_side_effects());
        assert!(ra_func.insts[1].flags.reads_memory());
    }

