    fn x86_opt_level_pass_schedules_match_policy() {
        let pass_names = |level| {
            let pm = X86Pipeline::x86_pass_manager_for_opt_level(level);
            pm.pass_names()
                .into_iter()
                .map(str::to_string)
                .collect::<Vec<_>>()
        };

        assert!(pass_names(trust_cg_opt::OptLevel::O0).is_empty());
        assert_eq!(
            pass_names(trust_cg_opt::OptLevel::O1),
            vec![
                "x86-licm".to_string(),
                "x86-copy-prop".to_string(),
                "x86-peephole".to_string(),
                "x86-dce".to_string(),
                "x86-if-convert".to_string(),
                "x86-branch-layout".to_string(),
            ]
        );

        let production_order = vec![
            "x86-vectorize".to_string(),
            "x86-sroa".to_string(),
            "x86-licm".to_string(),
            "x86-strength-reduce".to_string(),
            "x86-loop-unroll".to_string(),
            "x86-const-fold".to_string(),
            "x86-const-guard-elim".to_string(),
            "x86-block-merge".to_string(),
            "x86-copy-prop".to_string(),
            "x86-cse".to_string(),
            "x86-peephole".to_string(),
            "x86-bounds-check-elim".to_string(),
            "x86-dce".to_string(),
            "x86-loop-rotate".to_string(),
            "x86-cmov-swap".to_string(),
            "x86-if-convert".to_string(),
            "x86-branch-layout".to_string(),
        ];
        assert_eq!(pass_names(trust_cg_opt::OptLevel::O2), production_order);
        assert_eq!(pass_names(trust_cg_opt::OptLevel::Os), production_order);
        assert_eq!(pass_names(trust_cg_opt::OptLevel::O3), production_order);
    }

    /// The `TCG_NO_BRANCH_LAYOUT` kill switch removes exactly the OPT-8 pass
    /// from both schedules (deterministic variants — no env mutation in
    /// tests).
    #[test]
    fn x86_branch_layout_kill_switch_removes_only_that_pass() {
        let names = |pm: &trust_cg_opt::X86PassManager| {
            pm.pass_names()
                .into_iter()
                .map(str::to_string)
                .collect::<Vec<_>>()
        };

        let o1_on = X86Pipeline::x86_o1_pass_manager_with_branch_layout(true);
        let o1_off = X86Pipeline::x86_o1_pass_manager_with_branch_layout(false);
        assert_eq!(
            names(&o1_on).last().map(String::as_str),
            Some("x86-branch-layout")
        );
        assert_eq!(names(&o1_on)[..names(&o1_on).len() - 1], names(&o1_off)[..]);

        let o2_on = X86Pipeline::x86_o2_pass_manager_with_branch_layout(true);
        let o2_off = X86Pipeline::x86_o2_pass_manager_with_branch_layout(false);
        assert_eq!(
            names(&o2_on).last().map(String::as_str),
            Some("x86-branch-layout")
        );
        assert_eq!(names(&o2_on)[..names(&o2_on).len() - 1], names(&o2_off)[..]);
    }

    /// OPT-8 encoder elision: a block-trailing `jmp <layout-next>` must
    /// compile to EXACTLY the bytes of the same function with the jmp absent
    /// (fall-through identity), while a jmp to a non-adjacent block still
    /// emits its 5 bytes.
    #[test]
    fn trailing_jmp_to_layout_next_elides_to_fallthrough_identity() {
        let sig = Signature {
            params: vec![],
            returns: vec![Type::I64],
        };
        let pipeline = raw_no_frame_x86_pipeline();

        // Variant 1: entry ends `jmp b1` with b1 the layout successor.
        let mut with_jmp = X86ISelFunction::new("elide_jmp".to_string(), sig.clone());
        let (b0, b1) = (Block(0), Block(1));
        for b in [b0, b1] {
            with_jmp.ensure_block(b);
        }
        with_jmp.push_inst(
            b0,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::Imm(7),
                ],
            ),
        );
        with_jmp.push_inst(
            b0,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b1)]),
        );
        with_jmp.push_inst(b1, X86ISelInst::new(X86Opcode::Ret, vec![]));
        with_jmp.blocks.get_mut(&b0).unwrap().successors = vec![b1];

        // Variant 2: identical, but pure fall-through (no jmp at all).
        let mut without_jmp = X86ISelFunction::new("elide_jmp".to_string(), sig.clone());
        for b in [b0, b1] {
            without_jmp.ensure_block(b);
        }
        without_jmp.push_inst(
            b0,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::Imm(7),
                ],
            ),
        );
        without_jmp.push_inst(b1, X86ISelInst::new(X86Opcode::Ret, vec![]));
        without_jmp.blocks.get_mut(&b0).unwrap().successors = vec![b1];

        let jmp_bytes = pipeline.compile_function(&with_jmp).unwrap();
        let fallthrough_bytes = pipeline.compile_function(&without_jmp).unwrap();
        assert_eq!(
            jmp_bytes, fallthrough_bytes,
            "jmp <layout-next> must be a byte-level fall-through identity"
        );

        // Variant 3: the jmp targets a NON-adjacent block — must still emit
        // its 5 near-jmp bytes (no over-elision).
        let mut far_jmp = X86ISelFunction::new("far_jmp".to_string(), sig);
        let (b0, b1, b2) = (Block(0), Block(1), Block(2));
        for b in [b0, b1, b2] {
            far_jmp.ensure_block(b);
        }
        far_jmp.push_inst(
            b0,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::Imm(7),
                ],
            ),
        );
        far_jmp.push_inst(
            b0,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b2)]),
        );
        // b1 also targets b2, so b2 has TWO predecessors. Without that,
        // `X86BlockMerge` would legitimately fold b2 into b0 and delete the very
        // jmp whose encoding this variant is asserting — the fixture, not the
        // property, would be what changed. b1 -> b2 is adjacent so it elides to
        // a fall-through and contributes no bytes.
        far_jmp.push_inst(
            b1,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b2)]),
        );
        far_jmp.push_inst(b2, X86ISelInst::new(X86Opcode::Ret, vec![]));
        far_jmp.blocks.get_mut(&b0).unwrap().successors = vec![b2];
        far_jmp.blocks.get_mut(&b1).unwrap().successors = vec![b2];

        let far_bytes = pipeline.compile_function(&far_jmp).unwrap();
        assert_eq!(
            far_bytes.len(),
            jmp_bytes.len() + 5,
            "non-adjacent jmp keeps its 5 bytes (b1's adjacent jmp elides)"
        );
    }

    /// OPT-8 production wiring, end-to-end at O1: the DEFAULT schedule
    /// (latch rule on, fall-through rule off) — with the validator-backed
    /// `admit_x86_cc_inversion` callback — moves a loop latch's back-edge
    /// off the unconditional `jmp` and onto the (taken) `jcc`, so the hot
    /// loop pays one branch per iteration and the exit `jmp` becomes
    /// elidable. This is the profile-independent win (p2_collatz -32%,
    /// b1_mispredict -13%); the fall-through rule that regressed
    /// p6_branch_match is default-off (`X86BranchLayoutConfig::default`).
    #[test]
    fn o1_schedule_moves_latch_back_edge_onto_the_jcc_via_validated_admission() {
        let sig = Signature {
            params: vec![],
            returns: vec![Type::I64],
        };
        let mut func = X86ISelFunction::new("latch_o1".to_string(), sig);
        // b0 preheader -> b1 body -> b2 latch (cmp; jcc GE exit; jmp header)
        // -> {b3 exit, b1 header}.
        let (b0, b1, b2, b3) = (Block(0), Block(1), Block(2), Block(3));
        for b in [b0, b1, b2, b3] {
            func.ensure_block(b);
        }
        func.push_inst(
            b0,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::Imm(0),
                ],
            ),
        );
        func.push_inst(
            b0,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b1)]),
        );
        func.push_inst(
            b1,
            X86ISelInst::new(
                X86Opcode::AddRI,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::Imm(1),
                ],
            ),
        );
        func.push_inst(
            b2,
            X86ISelInst::new(
                X86Opcode::CmpRI,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::Imm(10),
                ],
            ),
        );
        func.push_inst(
            b2,
            X86ISelInst::new(
                X86Opcode::Jcc,
                vec![
                    X86ISelOperand::CondCode(X86CondCode::GE),
                    X86ISelOperand::Block(b3),
                ],
            ),
        );
        func.push_inst(
            b2,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b1)]),
        );
        func.push_inst(b3, X86ISelInst::new(X86Opcode::Ret, vec![]));
        func.blocks.get_mut(&b0).unwrap().successors = vec![b1];
        func.blocks.get_mut(&b1).unwrap().successors = vec![b2];
        func.blocks.get_mut(&b2).unwrap().successors = vec![b3, b1];

        let pipeline = X86Pipeline::new(X86PipelineConfig {
            opt_level: trust_cg_opt::OptLevel::O1,
            emit_frame: false,
            regalloc_mode: X86RegAllocMode::Simplified,
            ..X86PipelineConfig::default()
        });
        let _ = pipeline.run_x86_optimization_passes(&mut func);

        let latch = &func.blocks[&b2].insts;
        let n = latch.len();
        assert_eq!(
            latch[n - 2].operands,
            vec![
                X86ISelOperand::CondCode(X86CondCode::L),
                X86ISelOperand::Block(b1),
            ],
            "back-edge (header b1) must ride the inverted jcc (GE -> L)"
        );
        assert_eq!(
            latch[n - 1].operands,
            vec![X86ISelOperand::Block(b3)],
            "exit jmp targets the exit block (layout successor, elided at encode)"
        );
    }

    /// The production admission callback: every true hardware complement is
    /// admitted (validator-proven + chain-checked); any mismatched pair is
    /// refused outright.
    #[test]
    fn admit_x86_cc_inversion_accepts_complements_and_refuses_mismatches() {
        use trust_cg_ir::x86_64_ops::X86CondCode::*;
        for cc in [O, NO, B, AE, E, NE, BE, A, S, NS, P, NP, L, GE, LE, G] {
            assert!(
                admit_x86_cc_inversion(cc, cc.invert()),
                "{cc:?} -> {:?} must be admitted",
                cc.invert()
            );
            assert!(
                !admit_x86_cc_inversion(cc, cc),
                "{cc:?} -> {cc:?} (no inversion) must be refused"
            );
        }
    }

    #[test]
    fn x86_opt_level_o0_preserves_o2_rewrites_isel_shape() {
        let mut o0_func = optimizable_add_ri_func("x86_opt_level_o0");
        let mut o2_func = o0_func.clone();
        let o0_pipeline = X86Pipeline::new(X86PipelineConfig {
            opt_level: trust_cg_opt::OptLevel::O0,
            ..X86PipelineConfig::default()
        });
        let o2_pipeline = X86Pipeline::new(X86PipelineConfig {
            opt_level: trust_cg_opt::OptLevel::O2,
            ..X86PipelineConfig::default()
        });

        let o0_stats = o0_pipeline.run_x86_optimization_passes(&mut o0_func);
        let o2_stats = o2_pipeline.run_x86_optimization_passes(&mut o2_func);

        assert_eq!(o0_stats.total_pass_runs(), 0);
        // Sixteen production passes: vectorize, SROA, LICM, strength-reduce,
        // loop-unroll, const-fold, const-guard-elim, block-merge, copy-prop,
        // CSE, peephole, bounds-check-elim, DCE, loop-rotate, cmov-swap,
        // if-convert, and branch-layout.
        // (SROA added in c70e396; dominated-compare bounds-check elimination
        // in f6f73d3; loop rotation defaulted on in c033ba54; full unroll +
        // const-guard-elim defaulted on 2026-07-20; straight-line block-merge
        // 2026-08-09.)
        assert_eq!(o2_stats.total_pass_runs(), 17);
        assert!(
            entry_opcodes(&o0_func).contains(&X86Opcode::AddRI),
            "O0 must preserve the optimizable AddRI before regalloc"
        );
        assert_eq!(
            entry_opcodes(&o2_func),
            vec![
                X86Opcode::MovRI,
                X86Opcode::CmpRI,
                X86Opcode::MovRR,
                X86Opcode::Ret,
            ],
            "O2 should fold the AddRI and let DCE remove the now-dead source"
        );
    }

    #[test]
    fn x86_opt_level_o3_runs_production_schedule_to_bounded_fixpoint() {
        let mut func = optimizable_add_ri_func("x86_opt_level_o3");
        let pipeline = X86Pipeline::new(X86PipelineConfig {
            opt_level: trust_cg_opt::OptLevel::O3,
            ..X86PipelineConfig::default()
        });

        let stats = pipeline.run_x86_optimization_passes(&mut func);

        assert!(stats.iterations <= TCG_X86_O3_FIXPOINT_MAX_ITERATIONS);
        assert!(
            stats.total_pass_runs() >= X86Pipeline::x86_o2_pass_manager().num_passes(),
            "O3 should run at least one production-order iteration"
        );
        assert_eq!(
            stats
                .runs
                .iter()
                .map(|(name, _)| name.as_str())
                .collect::<Vec<_>>(),
            vec![
                "x86-vectorize",
                "x86-sroa",
                "x86-licm",
                "x86-strength-reduce",
                "x86-loop-unroll",
                "x86-const-fold",
                "x86-const-guard-elim",
                "x86-block-merge",
                "x86-copy-prop",
                "x86-cse",
                "x86-peephole",
                "x86-bounds-check-elim",
                "x86-dce",
                "x86-loop-rotate",
                "x86-cmov-swap",
                "x86-if-convert",
                "x86-branch-layout",
            ]
        );
    }

    #[test]
    fn compile_function_runs_default_x86_optimization_passes() {
        let pipeline = raw_no_frame_x86_pipeline();
        let func = optimizable_add_ri_func("default_x86_opts");

        let mut expected = minimal_func("default_x86_opts");
        expected.next_vreg = 2;
        expected.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![test_vreg_op(1), X86ISelOperand::Imm(30)],
            ),
        );
        expected.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::CmpRI,
                vec![test_vreg_op(1), X86ISelOperand::Imm(30)],
            ),
        );
        expected.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RAX), test_vreg_op(1)],
            ),
        );
        expected.push_inst(Block(0), X86ISelInst::new(X86Opcode::Ret, vec![]));

        let default_bytes = pipeline.compile_function(&func).unwrap();
        let expected_bytes = pipeline
            .compile_function_after_x86_passes(&expected)
            .unwrap();
        let unoptimized_bytes = pipeline.compile_function_after_x86_passes(&func).unwrap();

        assert_eq!(default_bytes, expected_bytes);
        assert_ne!(unoptimized_bytes, expected_bytes);
    }

