    fn runtime_stack_addr_lir(name: &str, align: u32, with_stack_arg_call: bool) -> LirFunction {
        let mut func = LirFunction::new(
            name,
            Signature {
                params: vec![Type::I64],
                returns: vec![Type::I64],
            },
        );
        let entry = Block(0);
        func.entry_block = entry;
        func.block_order.push(entry);
        func.stack_slots.push(StackSlotInfo::new_dynamic_with_unit(
            StackSlotSizeSource::Value(0),
            8,
            align,
        ));

        let mut instructions = vec![Instruction {
            opcode: Opcode::StackAddr { slot: 0 },
            args: vec![],
            results: vec![Value(1)],
        }];
        if with_stack_arg_call {
            instructions.push(Instruction {
                opcode: Opcode::Call {
                    name: "callee".to_string(),
                },
                args: vec![Value(1); 8],
                results: vec![],
            });
        }
        instructions.push(Instruction {
            opcode: Opcode::Iconst {
                ty: Type::I64,
                imm: 0,
            },
            args: vec![],
            results: vec![Value(2)],
        });
        instructions.push(Instruction {
            opcode: Opcode::Return,
            args: vec![Value(2)],
            results: vec![],
        });

        func.blocks.insert(
            entry,
            BasicBlock {
                params: vec![],
                instructions,
                source_locs: vec![],
            },
        );
        func
    }

    fn runtime_stack_alloc_isel(name: &str) -> X86ISelFunction {
        let mut func = minimal_func(name);
        let dst = VReg {
            id: 0,
            class: RegClass::Gpr64,
        };
        func.stack_slots.push(StackSlotInfo::new_dynamic_with_unit(
            StackSlotSizeSource::Value(0),
            8,
            16,
        ));
        func.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::StackAlloc,
                vec![
                    X86ISelOperand::VReg(dst),
                    X86ISelOperand::Imm(2),
                    X86ISelOperand::Imm(8),
                    X86ISelOperand::Imm(16),
                ],
            ),
        );
        func.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RAX), X86ISelOperand::VReg(dst)],
            ),
        );
        func.push_inst(Block(0), X86ISelInst::new(X86Opcode::Ret, vec![]));
        func
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    struct ObjectSection {
        offset: usize,
        size: usize,
        reloc_offset: usize,
        reloc_count: u32,
    }

    fn read_u16(bytes: &[u8], offset: usize) -> u16 {
        u16::from_le_bytes([bytes[offset], bytes[offset + 1]])
    }

    fn read_u32(bytes: &[u8], offset: usize) -> u32 {
        u32::from_le_bytes([
            bytes[offset],
            bytes[offset + 1],
            bytes[offset + 2],
            bytes[offset + 3],
        ])
    }

    fn read_u64(bytes: &[u8], offset: usize) -> u64 {
        u64::from_le_bytes([
            bytes[offset],
            bytes[offset + 1],
            bytes[offset + 2],
            bytes[offset + 3],
            bytes[offset + 4],
            bytes[offset + 5],
            bytes[offset + 6],
            bytes[offset + 7],
        ])
    }

    fn cstr(bytes: &[u8]) -> &str {
        let end = bytes.iter().position(|&b| b == 0).unwrap_or(bytes.len());
        std::str::from_utf8(&bytes[..end]).unwrap()
    }

    fn find_elf_section(bytes: &[u8], target: &str) -> Option<ObjectSection> {
        let shoff = read_u64(bytes, 40) as usize;
        let shentsize = read_u16(bytes, 58) as usize;
        let shnum = read_u16(bytes, 60) as usize;
        let shstrndx = read_u16(bytes, 62) as usize;
        let shstr = shoff + shstrndx * shentsize;
        let shstr_offset = read_u64(bytes, shstr + 24) as usize;
        let shstr_size = read_u64(bytes, shstr + 32) as usize;
        let shstr_data = &bytes[shstr_offset..shstr_offset + shstr_size];

        for i in 0..shnum {
            let shdr = shoff + i * shentsize;
            let name_offset = read_u32(bytes, shdr) as usize;
            let name = cstr(&shstr_data[name_offset..]);
            if name == target {
                return Some(ObjectSection {
                    offset: read_u64(bytes, shdr + 24) as usize,
                    size: read_u64(bytes, shdr + 32) as usize,
                    reloc_offset: 0,
                    reloc_count: 0,
                });
            }
        }
        None
    }

    fn elf_section_addralign(bytes: &[u8], target: &str) -> Option<u64> {
        let shoff = read_u64(bytes, 40) as usize;
        let shentsize = read_u16(bytes, 58) as usize;
        let shnum = read_u16(bytes, 60) as usize;
        let shstrndx = read_u16(bytes, 62) as usize;
        let shstr = shoff + shstrndx * shentsize;
        let shstr_offset = read_u64(bytes, shstr + 24) as usize;
        let shstr_size = read_u64(bytes, shstr + 32) as usize;
        let shstr_data = &bytes[shstr_offset..shstr_offset + shstr_size];

        for i in 0..shnum {
            let shdr = shoff + i * shentsize;
            let name_offset = read_u32(bytes, shdr) as usize;
            if cstr(&shstr_data[name_offset..]) == target {
                return Some(read_u64(bytes, shdr + 48));
            }
        }
        None
    }

    fn find_macho_section(bytes: &[u8], target: &[u8]) -> Option<ObjectSection> {
        let nsects = read_u32(bytes, 32 + 64) as usize;
        for i in 0..nsects {
            let sec_offset = 32 + 72 + i * 80;
            let sectname = &bytes[sec_offset..sec_offset + 16];
            if sectname.starts_with(target) {
                return Some(ObjectSection {
                    offset: read_u32(bytes, sec_offset + 48) as usize,
                    size: read_u64(bytes, sec_offset + 40) as usize,
                    reloc_offset: read_u32(bytes, sec_offset + 56) as usize,
                    reloc_count: read_u32(bytes, sec_offset + 60),
                });
            }
        }
        None
    }

    fn short_coff_name(bytes: &[u8]) -> &str {
        let end = bytes
            .iter()
            .position(|byte| *byte == 0)
            .unwrap_or(bytes.len());
        std::str::from_utf8(&bytes[..end]).unwrap()
    }

    fn find_coff_section(bytes: &[u8], target: &str) -> Option<ObjectSection> {
        let section_count = read_u16(bytes, 2) as usize;
        for idx in 0..section_count {
            let section = 20 + idx * 40;
            if short_coff_name(&bytes[section..section + 8]) == target {
                return Some(ObjectSection {
                    offset: read_u32(bytes, section + 20) as usize,
                    size: read_u32(bytes, section + 16) as usize,
                    reloc_offset: read_u32(bytes, section + 24) as usize,
                    reloc_count: read_u16(bytes, section + 32) as u32,
                });
            }
        }
        None
    }

    fn coff_section_characteristics(bytes: &[u8], target: &str) -> Option<u32> {
        let section_count = read_u16(bytes, 2) as usize;
        for idx in 0..section_count {
            let section = 20 + idx * 40;
            if short_coff_name(&bytes[section..section + 8]) == target {
                return Some(read_u32(bytes, section + 36));
            }
        }
        None
    }

