    #[test]
    fn test_x86_imulrmsib_size_estimate_covers_worst_case_encoding() {
        // Estimate pin: REX.W + 0F AF + ModRM + SIB + disp32 = 9 bytes max.
        // The estimate must be >= every encodable form (branch-relaxation
        // conservative-max contract).
        let sib = X86ISelOperand::SibMemAddr {
            base: Box::new(test_vreg_op(0)),
            index: Box::new(test_vreg_op(1)),
            scale: 1,
            disp: 0,
        };
        let inst = X86ISelInst::new(X86Opcode::ImulRMSib, vec![X86ISelOperand::PReg(RAX), sib]);
        assert_eq!(estimate_inst_size(&inst), 9);
        // Worst-case real encoding: disp32 form.
        use trust_cg_ir::x86_64_regs::{RBX, RCX};
        let mut enc = X86Encoder::new();
        let mut ops = X86InstOperands::none();
        ops.dst = Some(RAX);
        ops.base = Some(RBX);
        ops.index = Some(RCX);
        ops.scale = 4;
        ops.disp = 0x1000;
        let len = enc
            .encode_instruction(X86Opcode::ImulRMSib, &ops)
            .expect("encodes");
        assert!(len <= 9, "encoded {len} must be <= the 9-byte estimate");
    }

