    /// Recheck (5): a spill-slot READ with no store anywhere in the final
    /// stream is a pipeline bug (the cf9dc74 escape class — a carrier-kept
    /// vreg whose def was dropped shipped a runtime test of a never-written
    /// slot). The checker must flag the read-only slot and stay quiet once a
    /// store exists or when the displacement is not a spill slot.
    #[test]
    fn test_x86_uninitialized_spill_read_flags_read_only_slot() {
        let rbp_mem = |disp: i32| X86ISelOperand::MemAddr {
            base: Box::new(X86ISelOperand::PReg(RBP)),
            disp,
        };
        let r10 = X86ISelOperand::PReg(R10);
        let spill_disps: HashSet<i32> = [-160].into_iter().collect();

        // Read-only spill slot: flagged.
        let mut func = minimal_func("spill_read_no_store");
        func.push_inst(
            Block(0),
            X86ISelInst::new(X86Opcode::MovRM, vec![r10.clone(), rbp_mem(-160)]),
        );
        assert_eq!(
            x86_uninitialized_spill_read(&func, &spill_disps),
            Some(-160)
        );

        // Same read at a NON-spill displacement: not the checker's business.
        let other_disps: HashSet<i32> = [-8].into_iter().collect();
        assert_eq!(x86_uninitialized_spill_read(&func, &other_disps), None);

        // Adding a store to the slot anywhere silences the check.
        func.push_inst(
            Block(0),
            X86ISelInst::new(X86Opcode::MovMR, vec![rbp_mem(-160), r10.clone()]),
        );
        assert_eq!(x86_uninitialized_spill_read(&func, &spill_disps), None);

        // A folded ALU rhs read ([dst, dst, mem]) counts as a read too.
        let mut func2 = minimal_func("spill_folded_rhs_read");
        func2.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![r10.clone(), r10.clone(), rbp_mem(-160)],
            ),
        );
        assert_eq!(
            x86_uninitialized_spill_read(&func2, &spill_disps),
            Some(-160)
        );
    }

