    #[test]
    fn test_compile_trust_ir_v4i32_lane_shift_scalarized_paths_encode_sse2_reassembly() {
        for (name, opcode) in [
            ("ishl", Opcode::Ishl),
            ("ushr", Opcode::Ushr),
            ("sshr", Opcode::Sshr),
        ] {
            let func =
                v4i32_lane_shift_return_lir(&format!("v4i32_lane_shift_scalarized_{name}"), opcode);
            let pipeline = X86Pipeline::new(X86PipelineConfig {
                emit_frame: true,
                ..X86PipelineConfig::default()
            });
            let code = pipeline.compile_trust_ir_function(&func).unwrap();
            assert!(!code.is_empty(), "{name}");
            assert_eq!(*code.last().unwrap(), 0xC3, "{name}");
            assert!(
                code.windows(3).any(|bytes| bytes == [0x66, 0x0F, 0x62]),
                "{name} should encode PUNPCKLDQ in scalarized lane shift: {code:02x?}"
            );
            assert!(
                code.windows(3).any(|bytes| bytes == [0x66, 0x0F, 0x6C]),
                "{name} should encode PUNPCKLQDQ in scalarized lane shift: {code:02x?}"
            );
            assert!(
                !code
                    .windows(4)
                    .any(|bytes| bytes == [0x66, 0x0F, 0x3A, 0x22]),
                "{name} should not reassemble with PINSRD: {code:02x?}"
            );
            assert!(
                !code
                    .windows(4)
                    .any(|bytes| bytes == [0x66, 0x0F, 0x3A, 0x16]),
                "{name} should not extract with PEXTRD: {code:02x?}"
            );
            assert!(
                code.contains(&0xD3),
                "{name} should encode variable scalar shifts: {code:02x?}"
            );
        }
    }

    #[test]
    fn test_compile_trust_ir_v4i32_imul_scalarized_path_encodes() {
        let mut func = LirFunction::new(
            "v4i32_imul_scalarized",
            Signature {
                params: vec![Type::I64, Type::I64, Type::I64],
                returns: vec![],
            },
        );
        let entry = Block(0);
        func.entry_block = entry;
        func.block_order.push(entry);
        func.blocks.insert(
            entry,
            BasicBlock {
                params: vec![],
                instructions: vec![
                    Instruction {
                        opcode: Opcode::Load {
                            ty: Type::V128,
                            align: None,
                        },
                        args: vec![Value(0)],
                        results: vec![Value(3)],
                    },
                    Instruction {
                        opcode: Opcode::Load {
                            ty: Type::V128,
                            align: None,
                        },
                        args: vec![Value(1)],
                        results: vec![Value(4)],
                    },
                    Instruction {
                        opcode: Opcode::Imul,
                        args: vec![Value(3), Value(4)],
                        results: vec![Value(5)],
                    },
                    Instruction {
                        opcode: Opcode::Store {
                            ty: Type::V128,
                            align: None,
                        },
                        args: vec![Value(5), Value(2)],
                        results: vec![],
                    },
                    Instruction {
                        opcode: Opcode::Return,
                        args: vec![],
                        results: vec![],
                    },
                ],
                source_locs: vec![],
            },
        );

        let pipeline = X86Pipeline::new(X86PipelineConfig {
            emit_frame: true,
            output_format: X86OutputFormat::RawBytes,
            regalloc_mode: X86RegAllocMode::Simplified,
            opt_level: trust_cg_opt::OptLevel::O0,
            ..X86PipelineConfig::generic_x86_64()
        });
        let code = pipeline.compile_trust_ir_function(&func).unwrap();
        assert!(!code.is_empty());
        assert_eq!(*code.last().unwrap(), 0xC3);
        assert!(
            code_contains_sse2_opcode(&code, 0xF4),
            "expected encoded PMULUDQ in generic v4i32 multiply: {code:02x?}"
        );
        assert!(
            !code.windows(2).any(|bytes| bytes == [0x0F, 0xAF]),
            "generic v4i32 multiply should avoid scalar GPR IMUL lane crossings: {code:02x?}"
        );
        assert!(
            code_contains_sse2_opcode(&code, 0x62),
            "expected encoded PUNPCKLDQ in scalarized v4i32 multiply: {code:02x?}"
        );
        assert!(
            !code_contains_pmulld(&code),
            "generic scalarized v4i32 multiply should not encode PMULLD: {code:02x?}"
        );
        assert!(
            !code.windows(3).any(|bytes| bytes == [0x0F, 0x3A, 0x22]),
            "scalarized v4i32 multiply should not reassemble with PINSRD: {code:02x?}"
        );
        assert!(
            !code.windows(3).any(|bytes| bytes == [0x0F, 0x3A, 0x16]),
            "scalarized v4i32 multiply should not extract with PEXTRD: {code:02x?}"
        );
    }

