    #[test]
    fn test_compile_trust_ir_runtime_stack_addr_windows_call_reserves_dynamic_outgoing_gap() {
        let func = runtime_stack_addr_lir("stack_addr_runtime_windows_call", 16, true);
        let pipeline = X86Pipeline::new(X86PipelineConfig {
            emit_frame: true,
            call_abi: X86CallAbi::WindowsX64,
            ..X86PipelineConfig::default()
        });

        let code = pipeline
            .compile_trust_ir_function_emitting_call_fixups(&func)
            .unwrap();
        let sub_rsp_64 = [0x48, 0x83, 0xEC, 0x40];
        let sub_rsp_64_count = code
            .windows(sub_rsp_64.len())
            .filter(|window| *window == sub_rsp_64)
            .count();

        assert!(
            sub_rsp_64_count >= 1,
            "Windows runtime StackAddr with stack-arg calls should reserve a dynamic outgoing gap below the returned object: {code:02x?}"
        );
        assert_eq!(*code.last().unwrap(), 0xC3);
    }

