    #[test]
    fn test_compile_trust_ir_runtime_stack_addr_elf_object_emits_eh_frame() {
        use crate::elf::constants::R_X86_64_PC32;

        let func = runtime_stack_addr_lir("stack_addr_runtime_object", 16, false);
        let pipeline = X86Pipeline::new(X86PipelineConfig {
            emit_frame: true,
            output_format: X86OutputFormat::Elf,
            ..X86PipelineConfig::default()
        });

        let obj = pipeline.compile_trust_ir_function(&func).unwrap();
        assert_eq!(&obj[0..4], &[0x7F, b'E', b'L', b'F']);
        let eh_frame = find_elf_section(&obj, ".eh_frame").expect("missing .eh_frame");
        assert!(eh_frame.size > 0);
        let rela = find_elf_section(&obj, ".rela.eh_frame").expect("missing .rela.eh_frame");
        assert_eq!(rela.size, 24, "one FDE pc-begin relocation expected");
        let r_info = read_u64(&obj, rela.offset + 8);
        assert_eq!(r_info as u32, R_X86_64_PC32);
    }

    #[test]
    fn test_compile_trust_ir_runtime_stack_addr_macho_object_emits_eh_frame() {
        use crate::macho::constants::{X86_64_RELOC_SUBTRACTOR, X86_64_RELOC_UNSIGNED};

        let func = runtime_stack_addr_lir("stack_addr_runtime_macho_object", 32, false);
        let pipeline = X86Pipeline::new(X86PipelineConfig {
            emit_frame: true,
            output_format: X86OutputFormat::MachO,
            ..X86PipelineConfig::default()
        });

        let obj = pipeline.compile_trust_ir_function(&func).unwrap();
        assert_eq!(read_u32(&obj, 0), 0xFEEDFACF);
        let eh_frame = find_macho_section(&obj, b"__eh_frame").expect("missing __eh_frame");
        assert!(eh_frame.size > 0);
        assert_eq!(eh_frame.reloc_count, 2);
        let first = read_u32(&obj, eh_frame.reloc_offset + 4);
        let second = read_u32(&obj, eh_frame.reloc_offset + 12);
        assert_eq!((first >> 28) & 0xF, X86_64_RELOC_SUBTRACTOR);
        assert_eq!((second >> 28) & 0xF, X86_64_RELOC_UNSIGNED);
    }

