    #[test]
    fn test_single_function_macho_eh_with_constant_pool_matches_module_authority() {
        let mut func = build_x86_eh_test_function("eh_single_const_pool");
        let constant = 1.25f64.to_le_bytes();
        func.const_pool_entries.push(X86ISelConstPoolEntry {
            data: constant.to_vec(),
            align: 8,
        });
        let dst = VReg::new(0, RegClass::Fpr64);
        func.next_vreg = 1;
        func.blocks
            .get_mut(&Block(0))
            .expect("entry block")
            .insts
            .insert(
                0,
                X86ISelInst::new(
                    X86Opcode::MovsdRipRel,
                    vec![X86ISelOperand::VReg(dst), X86ISelOperand::ConstPoolEntry(0)],
                ),
            );

        let pipeline = X86Pipeline::new(X86PipelineConfig {
            emit_frame: true,
            output_format: X86OutputFormat::MachO,
            ..X86PipelineConfig::default()
        });
        let single = pipeline
            .compile_function(&func)
            .expect("single-function EH plus constant pool must compile");
        let module = pipeline
            .compile_module(std::slice::from_ref(&func))
            .expect("one-function module is the unwind-emission authority");

        assert_eq!(
            single, module,
            "single-function EH emission must be byte-identical to the shared module path"
        );
        let text = find_macho_section(&single, b"__text").expect("missing __text");
        let text_bytes = &single[text.offset..text.offset + text.size];
        assert!(
            text_bytes.ends_with(&constant),
            "the inline constant pool must remain in __text after the throwing instruction range"
        );
        assert!(find_macho_section(&single, b"__gcc_except_tab").is_some());
        assert!(find_macho_section(&single, b"__eh_frame").is_some());
    }

