    #[test]
    fn test_compile_trust_ir_windows_x64_call_uses_fixed_frame_shadow_space() {
        let mut func = LirFunction::new(
            "windows_shadow_call",
            Signature {
                params: vec![],
                returns: vec![],
            },
        );
        let entry = Block(0);
        func.entry_block = entry;
        func.block_order.push(entry);
        func.blocks.insert(
            entry,
            BasicBlock {
                params: vec![],
                instructions: vec![
                    Instruction {
                        opcode: Opcode::Call {
                            name: "target".to_string(),
                        },
                        args: vec![],
                        results: vec![],
                    },
                    Instruction {
                        opcode: Opcode::Return,
                        args: vec![],
                        results: vec![],
                    },
                ],
                source_locs: vec![],
            },
        );

        let pipeline = X86Pipeline::new(X86PipelineConfig {
            emit_elf: false,
            emit_frame: true,
            opt_level: trust_cg_opt::OptLevel::O0,
            regalloc_mode: X86RegAllocMode::Simplified,
            call_abi: X86CallAbi::WindowsX64,
            ..X86PipelineConfig::default()
        });

        let code = pipeline
            .compile_trust_ir_function_emitting_call_fixups(&func)
            .unwrap();
        let call_offset = code
            .iter()
            .position(|byte| *byte == 0xE8)
            .expect("Windows x64 call lowering should emit CALL rel32");

        assert!(
            code.starts_with(&[0x55, 0x48, 0x89, 0xE5, 0x48, 0x83, 0xEC, 0x20])
                || code.starts_with(&[
                    0x55, 0x48, 0x89, 0xE5, 0x48, 0x81, 0xEC, 0x20, 0x00, 0x00, 0x00
                ]),
            "Windows x64 calls must reserve shadow space in the prologue: {code:02X?}"
        );
        assert!(call_offset > 0);
    }

