    #[test]
    fn test_elf_and_coff_text_alignment_tracks_jcc_kill_switch() {
        const COFF_SECTION_ALIGNMENT_MASK: u32 = 0x00F0_0000;

        let func = build_x86_const_test_function();
        let inspect = || {
            let elf = x86_compile_to_elf(&func).unwrap();
            let coff = x86_compile_to_coff(&func).unwrap();
            (
                elf_section_addralign(&elf, ".text").expect("missing ELF .text"),
                coff_section_characteristics(&coff, ".text").expect("missing COFF .text")
                    & COFF_SECTION_ALIGNMENT_MASK,
            )
        };

        let enabled =
            crate::env_lock::with_env_overrides_removed(&["TCG_NO_X86_JCC_ALIGN"], inspect);
        let disabled =
            crate::env_lock::with_env_overrides(&[("TCG_NO_X86_JCC_ALIGN", "1")], inspect);

        assert_eq!(
            enabled,
            (32, crate::coff::writer::IMAGE_SCN_ALIGN_32BYTES),
            "default-on JCC padding requires an exact 32-byte .text grid in both object formats"
        );
        assert_eq!(
            disabled,
            (16, crate::coff::IMAGE_SCN_ALIGN_16BYTES),
            "the kill switch must restore both object formats to their 16-byte convention"
        );
        assert_ne!(
            enabled, disabled,
            "the control must prove that the kill switch changes the serialized section headers"
        );
    }

