    #[test]
    fn test_windows_coff_framed_function_emits_unwind_metadata() {
        let mut func = minimal_func("framed");
        func.push_inst(Block(0), X86ISelInst::new(X86Opcode::Ret, vec![]));
        let pipeline = X86Pipeline::new(X86PipelineConfig {
            output_format: X86OutputFormat::Coff,
            emit_frame: true,
            regalloc_mode: X86RegAllocMode::Simplified,
            call_abi: X86CallAbi::WindowsX64,
            ..X86PipelineConfig::default()
        });

        let bytes = pipeline.compile_function(&func).unwrap();

        assert_eq!(read_u16(&bytes, 0), crate::coff::IMAGE_FILE_MACHINE_AMD64);
        let text = find_coff_section(&bytes, ".text").expect("missing .text");
        let pdata = find_coff_section(&bytes, ".pdata").expect("missing .pdata");
        let xdata = find_coff_section(&bytes, ".xdata").expect("missing .xdata");

        assert_eq!(
            &bytes[text.offset..text.offset + text.size],
            &[0x55, 0x48, 0x89, 0xE5, 0x5D, 0xC3]
        );
        assert_eq!(pdata.size, 12);
        assert_eq!(pdata.reloc_count, 3);
        assert_eq!(read_u32(&bytes, pdata.offset), 0);
        assert_eq!(read_u32(&bytes, pdata.offset + 4), 6);
        assert_eq!(read_u32(&bytes, pdata.offset + 8), 0);
        assert_eq!(xdata.size, 8);
        assert_eq!(
            &bytes[xdata.offset..xdata.offset + xdata.size],
            &[0x01, 0x04, 0x02, 0x05, 0x04, 0x03, 0x01, 0x50]
        );
        for idx in 0..3 {
            assert_eq!(
                read_u16(&bytes, pdata.reloc_offset + idx * 10 + 8),
                crate::coff::IMAGE_REL_AMD64_ADDR32NB
            );
        }
    }

