    #[test]
    fn test_windows_coff_module_non_leaf_emits_pdata_xdata() {
        let mut caller = minimal_func("caller");
        caller.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::Call,
                vec![X86ISelOperand::Symbol("callee".to_string())],
            ),
        );
        caller.push_inst(Block(0), X86ISelInst::new(X86Opcode::Ret, vec![]));
        let mut callee = minimal_func("callee");
        callee.push_inst(Block(0), X86ISelInst::new(X86Opcode::Ret, vec![]));
        let pipeline = X86Pipeline::new(X86PipelineConfig {
            output_format: X86OutputFormat::Coff,
            emit_frame: true,
            opt_level: trust_cg_opt::OptLevel::O0,
            regalloc_mode: X86RegAllocMode::Simplified,
            call_abi: X86CallAbi::WindowsX64,
            ..X86PipelineConfig::default()
        });

        let bytes = pipeline.compile_module(&[caller, callee]).unwrap();

        let text = find_coff_section(&bytes, ".text").expect("missing .text");
        let pdata = find_coff_section(&bytes, ".pdata").expect("missing .pdata");
        let xdata = find_coff_section(&bytes, ".xdata").expect("missing .xdata");

        // Function 1 is 19 bytes; function 2 is 6. Packed back-to-back that was
        // 25 total with fn2 at offset 19. With JCC-erratum function alignment
        // fn2 starts at 32, so .text is 38.
        //
        // ⚑ The point of this test after that change: the unwind records must
        // MOVE WITH the padding. They are derived from `text_offset`, which is
        // taken AFTER the alignment NOPs — if padding were inserted anywhere
        // that bypassed it, pdata would still say 19 and Windows would unwind
        // from the middle of the padding. The `32` below is that check.
        assert_eq!(text.size, 38);
        assert_eq!(text.reloc_count, 1);
        assert_eq!(read_u32(&bytes, text.reloc_offset), 9);
        assert_eq!(
            read_u16(&bytes, text.reloc_offset + 8),
            crate::coff::IMAGE_REL_AMD64_REL32
        );
        assert_eq!(pdata.size, 24);
        assert_eq!(pdata.reloc_count, 6);
        assert_eq!(read_u32(&bytes, pdata.offset), 0);
        assert_eq!(read_u32(&bytes, pdata.offset + 4), 19);
        assert_eq!(read_u32(&bytes, pdata.offset + 8), 0);
        let fn2_begin = read_u32(&bytes, pdata.offset + 12);
        assert_eq!(fn2_begin, 32, "fn2 must start on the aligned boundary");
        assert_eq!(
            fn2_begin % (1u32 << x86_text_align_log2()),
            0,
            "every function's unwind BeginAddress must sit on the alignment grid \
             the padding assumed"
        );
        assert_eq!(read_u32(&bytes, pdata.offset + 16), 38);
        assert_eq!(read_u32(&bytes, pdata.offset + 20), 12);
        assert_eq!(xdata.size, 20);
        assert_eq!(
            &bytes[xdata.offset..xdata.offset + xdata.size],
            &[
                0x01, 0x08, 0x03, 0x05, 0x08, 0x32, 0x04, 0x03, 0x01, 0x50, 0x00, 0x00, 0x01, 0x04,
                0x02, 0x05, 0x04, 0x03, 0x01, 0x50,
            ]
        );
        for idx in 0..6 {
            assert_eq!(
                read_u16(&bytes, pdata.reloc_offset + idx * 10 + 8),
                crate::coff::IMAGE_REL_AMD64_ADDR32NB
            );
        }
    }

    #[test]
    fn test_single_function_coff_emits_rdata_constant_pool_relocation() {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut func = X86ISelFunction::new("cp".to_string(), sig);
        let entry = Block(0);
        func.ensure_block(entry);
        func.const_pool_entries.push(X86ISelConstPoolEntry {
            data: 1.25f64.to_le_bytes().to_vec(),
            align: 8,
        });
        let dst = VReg::new(0, RegClass::Fpr64);
        func.next_vreg = 1;
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovsdRipRel,
                vec![X86ISelOperand::VReg(dst), X86ISelOperand::ConstPoolEntry(0)],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let pipeline = X86Pipeline::new(X86PipelineConfig {
            output_format: X86OutputFormat::Coff,
            opt_level: trust_cg_opt::OptLevel::O0,
            emit_frame: false,
            regalloc_mode: X86RegAllocMode::Simplified,
            ..X86PipelineConfig::default()
        });

        let bytes = pipeline.compile_function(&func).unwrap();

        assert_eq!(read_u16(&bytes, 0), crate::coff::IMAGE_FILE_MACHINE_AMD64);
        assert_eq!(read_u16(&bytes, 2), 2, "expected .text and .rdata");
        assert_eq!(
            read_u32(&bytes, 12),
            2,
            "expected function and .rdata symbols"
        );

        let text_header = 20;
        let rdata_header = text_header + 40;
        assert_eq!(&bytes[text_header..text_header + 5], b".text");
        assert_eq!(&bytes[rdata_header..rdata_header + 6], b".rdata");

        let text_raw = read_u32(&bytes, text_header + 20) as usize;
        let text_size = read_u32(&bytes, text_header + 16) as usize;
        let text_reloc_ptr = read_u32(&bytes, text_header + 24) as usize;
        assert_eq!(read_u16(&bytes, text_header + 32), 1);

        let rdata_raw = read_u32(&bytes, rdata_header + 20) as usize;
        let rdata_size = read_u32(&bytes, rdata_header + 16) as usize;
        assert_eq!(rdata_size, 8);
        assert_eq!(&bytes[rdata_raw..rdata_raw + 8], &1.25f64.to_le_bytes());

        let reloc_va = read_u32(&bytes, text_reloc_ptr) as usize;
        let reloc_sym = read_u32(&bytes, text_reloc_ptr + 4);
        assert_eq!(
            read_u16(&bytes, text_reloc_ptr + 8),
            crate::coff::IMAGE_REL_AMD64_REL32
        );
        assert_eq!(reloc_sym, 1, "relocation should target .rdata symbol");
        assert!(reloc_va + 4 <= text_size);
        assert_eq!(
            read_u32(&bytes, text_raw + reloc_va),
            0,
            "first constant-pool entry should use a section-relative addend, not stale inline RIP displacement"
        );

        let symtab = read_u32(&bytes, 8) as usize;
        let rdata_symbol = symtab + 18;
        assert_eq!(&bytes[rdata_symbol..rdata_symbol + 6], b".rdata");
        assert_eq!(read_u16(&bytes, rdata_symbol + 12), 2);
        assert_eq!(
            read_u16(&bytes, rdata_symbol + 14),
            crate::coff::IMAGE_SYM_TYPE_NULL
        );
        assert_eq!(
            bytes[rdata_symbol + 16],
            crate::coff::IMAGE_SYM_CLASS_STATIC
        );
    }

    #[test]
    fn test_compile_module_coff_emits_rel32_call_relocation() {
        let mut caller = build_x86_const_test_function();
        caller.name = "caller".to_string();
        let mut callee = build_x86_const_test_function();
        callee.name = "callee".to_string();

        // Put the cross-function CALL before the fixture's constant-producing
        // instructions. A call immediately before RET would invalidate the
        // fixture: RET reads RAX, which the call is allowed to clobber. Keeping
        // the existing RAX definition after the call makes this a valid stream
        // while still exercising the same cross-function relocation.
        {
            let block = caller.blocks.get_mut(&Block(0)).expect("entry block");
            block.insts.insert(
                0,
                X86ISelInst::new(
                    X86Opcode::Call,
                    vec![X86ISelOperand::Symbol("callee".to_string())],
                ),
            );
        }

        let pipeline = X86Pipeline::new(X86PipelineConfig {
            output_format: X86OutputFormat::Coff,
            emit_frame: true,
            ..X86PipelineConfig::default()
        });
        let bytes = pipeline.compile_module(&[caller, callee]).unwrap();

        assert_eq!(read_u16(&bytes, 0), crate::coff::IMAGE_FILE_MACHINE_AMD64);
        assert_eq!(
            read_u16(&bytes, 2),
            1,
            "combined COFF has one .text section"
        );
        assert_eq!(
            read_u16(&bytes, 20 + 32),
            1,
            "expected one .text relocation"
        );
        let reloc_ptr = read_u32(&bytes, 20 + 24) as usize;
        assert_eq!(
            read_u16(&bytes, reloc_ptr + 8),
            crate::coff::IMAGE_REL_AMD64_REL32
        );
        assert_eq!(
            read_u32(&bytes, reloc_ptr + 4),
            1,
            "COFF call relocation should target the in-module callee symbol"
        );
    }

    #[test]
    fn test_compile_module_coff_rejects_undefined_external_call() {
        let mut caller = minimal_func("caller");
        caller.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::Call,
                vec![X86ISelOperand::Symbol("external_callee".to_string())],
            ),
        );
        caller.push_inst(Block(0), X86ISelInst::new(X86Opcode::Ret, vec![]));

        let pipeline = X86Pipeline::new(X86PipelineConfig {
            output_format: X86OutputFormat::Coff,
            opt_level: trust_cg_opt::OptLevel::O0,
            emit_frame: false,
            regalloc_mode: X86RegAllocMode::Simplified,
            ..X86PipelineConfig::default()
        });

        let err = pipeline.compile_module(&[caller]).unwrap_err();
        let diagnostic = err.to_string();

        match err {
            X86PipelineError::CoffUndefinedExternalCall { caller, callee } => {
                assert_eq!(caller, "caller");
                assert_eq!(callee, "external_callee");
            }
            other => panic!("expected undefined COFF external-call rejection, got {other:?}"),
        }
        assert!(diagnostic.contains("undefined external call"));
        assert!(diagnostic.contains("caller"));
        assert!(diagnostic.contains("external_callee"));
    }

