    #[cfg(feature = "verify")]
    #[test]
    fn test_x86_64_elf_pc32_and_gotpcrel_relocation_inventory_promotes() {
        let mut global_ref = minimal_func("materialize");
        let dst = VReg::new(0, RegClass::Gpr64);
        global_ref.next_vreg = 1;
        global_ref.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::LeaRip,
                vec![
                    X86ISelOperand::VReg(dst),
                    X86ISelOperand::Symbol("callee".to_string()),
                ],
            ),
        );
        global_ref.push_inst(Block(0), X86ISelInst::new(X86Opcode::Ret, vec![]));

        let mut extern_ref = minimal_func("materialize_extern");
        let dst = VReg::new(1, RegClass::Gpr64);
        extern_ref.next_vreg = 2;
        extern_ref.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::MovRipRel,
                vec![
                    X86ISelOperand::VReg(dst),
                    X86ISelOperand::Symbol("external_data".to_string()),
                ],
            ),
        );
        extern_ref.push_inst(Block(0), X86ISelInst::new(X86Opcode::Ret, vec![]));

        let mut callee = minimal_func("callee");
        callee.push_inst(Block(0), X86ISelInst::new(X86Opcode::Ret, vec![]));

        let pipeline = X86Pipeline::new(X86PipelineConfig {
            opt_level: trust_cg_opt::OptLevel::O0,
            output_format: X86OutputFormat::Elf,
            emit_frame: false,
            regalloc_mode: X86RegAllocMode::Simplified,
            ..X86PipelineConfig::default()
        });
        let report = pipeline
            .module_relocation_inventory_report_after_x86_passes(
                &[global_ref, extern_ref, callee],
                &[],
                "x86-module.o",
                false,
            )
            .expect("x86 ELF relocation inventory should include PC32/GOTPCREL rows");

        // The PC32 (GlobalRef RIP-relative) and GOTPCREL (ExternRef) rows are
        // emitted, covered by the ELF data-proof lane, and the report is built
        // under the default-Enforce ELF reparse binding: promotable.
        let kinds: Vec<_> = report.entries.iter().map(|entry| entry.kind).collect();
        assert_eq!(
            kinds,
            [
                trust_cg_verify::ObjectRelocationKind::X86_64ElfPc32,
                trust_cg_verify::ObjectRelocationKind::X86_64ElfGotPcRel,
            ]
        );
        assert!(report.is_promotable(), "{report:?}");
        assert!(report.promotion_rejection_reason().is_none());

        // Negative control: an unproven ELF row (GOT32 has no value proof)
        // still fails closed even on a reparse-bound object.
        let unproven_report =
            trust_cg_verify::ObjectRelocationInventoryReport::from_emitted_kinds_with_registry_and_binding(
                "x86-module-malformed.o",
                [
                    trust_cg_verify::ObjectRelocationKind::X86_64ElfPc32,
                    trust_cg_verify::ObjectRelocationKind::X86_64ElfGot32,
                ],
                &trust_cg_verify::ObjectRelocationProofRegistry::x86_64_elf_production(),
                trust_cg_verify::ObjectProofBinding::ElfReparseEnforced,
            );
        assert!(!unproven_report.is_promotable());
        let reason = unproven_report
            .promotion_rejection_reason()
            .expect("the GOT32 row must reject promotion");
        assert!(
            reason.contains("R_X86_64_GOT32")
                && reason.contains("no object relocation proof is registered"),
            "unproven ELF rows should fail closed: {reason}"
        );
    }

