    #[test]
    fn test_macho_x86_64_no_eh_frame_section() {
        // Plain fixed-size x86-64 frames continue to use the legacy compact
        // linker path; __eh_frame is emitted only for dynamic StackAddr frames.
        let func = build_x86_add_test_function();
        let bytes = x86_compile_to_macho(&func).unwrap();

        fn read_u32(bytes: &[u8], offset: usize) -> u32 {
            u32::from_le_bytes([
                bytes[offset],
                bytes[offset + 1],
                bytes[offset + 2],
                bytes[offset + 3],
            ])
        }

        let nsects = read_u32(&bytes, 32 + 64);
        for i in 0..nsects as usize {
            let sec_offset = 32 + 72 + i * 80;
            let sectname = &bytes[sec_offset..sec_offset + 16];
            assert!(
                !sectname.starts_with(b"__eh_frame"),
                "fixed-frame x86-64 Mach-O should not contain __eh_frame"
            );
        }
    }

