    #[test]
    fn test_movri_size_estimate_matches_zero_extending_gpr64_encoding() {
        let legacy_small = X86ISelInst::new(
            X86Opcode::MovRI,
            vec![X86ISelOperand::PReg(RAX), X86ISelOperand::Imm(42)],
        );
        assert_eq!(estimate_inst_size(&legacy_small), 5);

        let legacy_high_u32 = X86ISelInst::new(
            X86Opcode::MovRI,
            vec![
                X86ISelOperand::PReg(RAX),
                X86ISelOperand::Imm(u32::MAX as i64),
            ],
        );
        assert_eq!(estimate_inst_size(&legacy_high_u32), 5);

        let extended_small = X86ISelInst::new(
            X86Opcode::MovRI,
            vec![X86ISelOperand::PReg(R10), X86ISelOperand::Imm(42)],
        );
        assert_eq!(estimate_inst_size(&extended_small), 6);

        let wide_movabs = X86ISelInst::new(
            X86Opcode::MovRI,
            vec![
                X86ISelOperand::PReg(RAX),
                X86ISelOperand::Imm(0x1_0000_0000),
            ],
        );
        assert_eq!(estimate_inst_size(&wide_movabs), 10);

        let negative_movabs = X86ISelInst::new(
            X86Opcode::MovRI,
            vec![X86ISelOperand::PReg(RAX), X86ISelOperand::Imm(-1)],
        );
        assert_eq!(estimate_inst_size(&negative_movabs), 10);
    }

    #[test]
    fn test_movri_size_estimate_covers_narrow_and_virtual_forms() {
        let legacy_gpr32 = X86ISelInst::new(
            X86Opcode::MovRI,
            vec![
                X86ISelOperand::PReg(EAX),
                X86ISelOperand::Imm(0x8000_0001u32 as i64),
            ],
        );
        assert_eq!(estimate_inst_size(&legacy_gpr32), 5);

        let extended_gpr32 = X86ISelInst::new(
            X86Opcode::MovRI,
            vec![X86ISelOperand::PReg(R10D), X86ISelOperand::Imm(42)],
        );
        assert_eq!(estimate_inst_size(&extended_gpr32), 6);

        let legacy_gpr8 = X86ISelInst::new(
            X86Opcode::MovRI,
            vec![X86ISelOperand::PReg(AL), X86ISelOperand::Imm(7)],
        );
        assert_eq!(estimate_inst_size(&legacy_gpr8), 2);

        let extended_gpr8 = X86ISelInst::new(
            X86Opcode::MovRI,
            vec![X86ISelOperand::PReg(R10B), X86ISelOperand::Imm(7)],
        );
        assert_eq!(estimate_inst_size(&extended_gpr8), 3);

        let legacy_gpr16 = X86ISelInst::new(
            X86Opcode::MovRI,
            vec![X86ISelOperand::PReg(AX), X86ISelOperand::Imm(0x1234)],
        );
        assert_eq!(estimate_inst_size(&legacy_gpr16), 4);

        let extended_gpr16 = X86ISelInst::new(
            X86Opcode::MovRI,
            vec![X86ISelOperand::PReg(R10W), X86ISelOperand::Imm(0x1234)],
        );
        assert_eq!(estimate_inst_size(&extended_gpr16), 5);

        let gpr64_vreg = VReg::new(100, RegClass::Gpr64);
        let gpr64_small = X86ISelInst::new(
            X86Opcode::MovRI,
            vec![X86ISelOperand::VReg(gpr64_vreg), X86ISelOperand::Imm(42)],
        );
        assert_eq!(estimate_inst_size(&gpr64_small), 6);

        let gpr64_wide = X86ISelInst::new(
            X86Opcode::MovRI,
            vec![
                X86ISelOperand::VReg(gpr64_vreg),
                X86ISelOperand::Imm(0x1_0000_0000),
            ],
        );
        assert_eq!(estimate_inst_size(&gpr64_wide), 10);

        let gpr32_vreg = VReg::new(101, RegClass::Gpr32);
        let gpr32_any_imm = X86ISelInst::new(
            X86Opcode::MovRI,
            vec![X86ISelOperand::VReg(gpr32_vreg), X86ISelOperand::Imm(-1)],
        );
        assert_eq!(estimate_inst_size(&gpr32_any_imm), 6);
    }

