    #[test]
    fn test_encoded_narrow_packed_memory_rhs_reduces_movdqu_reload_bytes() {
        fn contains_movdqu_load(code: &[u8]) -> bool {
            code.windows(3).any(|w| w == [0xF3, 0x0F, 0x6F])
                || code.windows(4).any(|w| {
                    w[0] == 0xF3 && (0x40..=0x4F).contains(&w[1]) && w[2] == 0x0F && w[3] == 0x6F
                })
        }

        let pipeline = raw_no_frame_x86_pipeline();
        for (opcode, opcode_byte) in [
            (X86Opcode::Pcmpgtb, 0x64),
            (X86Opcode::Pcmpgtw, 0x65),
            (X86Opcode::Paddb, 0xFC),
            (X86Opcode::Paddw, 0xFD),
            (X86Opcode::Psubb, 0xF8),
            (X86Opcode::Psubw, 0xF9),
            (X86Opcode::Pmullw, 0xD5),
        ] {
            let mem = X86ISelOperand::MemAddr {
                base: Box::new(X86ISelOperand::PReg(RBP)),
                disp: -16,
            };

            let mut folded = minimal_func("narrow_packed_folded_rhs_bytes");
            folded.push_inst(
                Block(0),
                X86ISelInst::new(
                    opcode,
                    vec![
                        X86ISelOperand::PReg(XMM0),
                        X86ISelOperand::PReg(XMM0),
                        mem.clone(),
                    ],
                ),
            );
            let (folded_code, _, _, _) = pipeline
                .encode_function_with_all_fixups(&folded, &HashMap::new())
                .unwrap();

            let mut explicit = minimal_func("narrow_packed_explicit_reload_bytes");
            explicit.push_inst(
                Block(0),
                X86ISelInst::new(X86Opcode::MovdquRM, vec![X86ISelOperand::PReg(XMM14), mem]),
            );
            explicit.push_inst(
                Block(0),
                X86ISelInst::new(
                    opcode,
                    vec![
                        X86ISelOperand::PReg(XMM0),
                        X86ISelOperand::PReg(XMM0),
                        X86ISelOperand::PReg(XMM14),
                    ],
                ),
            );
            let (explicit_code, _, _, _) = pipeline
                .encode_function_with_all_fixups(&explicit, &HashMap::new())
                .unwrap();

            assert!(
                folded_code
                    .windows(3)
                    .any(|w| w == [0x66, 0x0F, opcode_byte]),
                "{opcode:?} folded form must use legacy SSE2 opcode bytes: {folded_code:02X?}"
            );
            assert!(
                !folded_code.iter().any(|byte| matches!(byte, 0xC4 | 0xC5)),
                "{opcode:?} folded form must not use VEX/YMM prefix bytes: {folded_code:02X?}"
            );
            assert!(
                !contains_movdqu_load(&folded_code),
                "{opcode:?} folded memory RHS must remove the explicit MOVDQU reload: {folded_code:02X?}"
            );
            assert!(
                contains_movdqu_load(&explicit_code),
                "{opcode:?} explicit reload baseline should contain MOVDQU: {explicit_code:02X?}"
            );
            assert!(
                folded_code.len() < explicit_code.len(),
                "{opcode:?} folded memory RHS should be smaller than MOVDQU reload + RR op: folded={folded_code:02X?}, explicit={explicit_code:02X?}"
            );
        }
    }

    #[test]
    fn test_encoded_pshufd_memory_source_reduces_movdqu_reload_bytes() {
        fn contains_movdqu_load(code: &[u8]) -> bool {
            code.windows(3).any(|w| w == [0xF3, 0x0F, 0x6F])
                || code.windows(4).any(|w| {
                    w[0] == 0xF3 && (0x40..=0x4F).contains(&w[1]) && w[2] == 0x0F && w[3] == 0x6F
                })
        }

        let pipeline = raw_no_frame_x86_pipeline();
        let mem = X86ISelOperand::MemAddr {
            base: Box::new(X86ISelOperand::PReg(RBP)),
            disp: -16,
        };

        let mut folded = minimal_func("pshufd_folded_rhs_bytes");
        folded.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::Pshufd,
                vec![
                    X86ISelOperand::PReg(XMM0),
                    mem.clone(),
                    X86ISelOperand::Imm(0x1B),
                ],
            ),
        );
        let (folded_code, _, _, _) = pipeline
            .encode_function_with_all_fixups(&folded, &HashMap::new())
            .unwrap();

        let mut explicit = minimal_func("pshufd_explicit_reload_bytes");
        explicit.push_inst(
            Block(0),
            X86ISelInst::new(X86Opcode::MovdquRM, vec![X86ISelOperand::PReg(XMM14), mem]),
        );
        explicit.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::Pshufd,
                vec![
                    X86ISelOperand::PReg(XMM0),
                    X86ISelOperand::PReg(XMM14),
                    X86ISelOperand::Imm(0x1B),
                ],
            ),
        );
        let (explicit_code, _, _, _) = pipeline
            .encode_function_with_all_fixups(&explicit, &HashMap::new())
            .unwrap();

        assert!(
            folded_code.windows(3).any(|w| w == [0x66, 0x0F, 0x70]),
            "folded PSHUFD must use legacy SSE2 bytes: {folded_code:02X?}"
        );
        assert_eq!(
            folded_code.last(),
            Some(&0x1B),
            "folded PSHUFD must preserve the shuffle immediate: {folded_code:02X?}"
        );
        assert!(
            !folded_code.iter().any(|byte| matches!(byte, 0xC4 | 0xC5)),
            "folded PSHUFD must not use VEX/YMM prefix bytes: {folded_code:02X?}"
        );
        assert!(
            !contains_movdqu_load(&folded_code),
            "folded PSHUFD memory source must remove the explicit MOVDQU reload: {folded_code:02X?}"
        );
        assert!(
            contains_movdqu_load(&explicit_code),
            "explicit PSHUFD reload baseline should contain MOVDQU: {explicit_code:02X?}"
        );
        assert!(
            folded_code.len() < explicit_code.len(),
            "folded PSHUFD memory source should be smaller than MOVDQU reload + RR op: folded={folded_code:02X?}, explicit={explicit_code:02X?}"
        );
    }

    #[test]
    fn test_isel_to_regalloc_qword_lane_insert_extract_defs_and_uses() {
        let mut func = minimal_func("qword_lane_ra");
        let entry = Block(0);
        let dst_vec = VReg::new(0, RegClass::Fpr128);
        let old_vec = VReg::new(1, RegClass::Fpr128);
        let scalar = VReg::new(2, RegClass::Gpr64);
        let dst_scalar = VReg::new(3, RegClass::Gpr64);
        func.next_vreg = 4;

        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::Pinsrq,
                vec![
                    X86ISelOperand::VReg(dst_vec),
                    X86ISelOperand::VReg(old_vec),
                    X86ISelOperand::VReg(scalar),
                    X86ISelOperand::Imm(1),
                ],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::Pextrq,
                vec![
                    X86ISelOperand::VReg(dst_scalar),
                    X86ISelOperand::VReg(dst_vec),
                    X86ISelOperand::Imm(0),
                ],
            ),
        );

        let ra_func = x86_isel_to_regalloc(&func).unwrap();
        let pinsrq = &ra_func.insts[0];
        assert_eq!(pinsrq.defs, vec![RegAllocOperand::VReg(dst_vec)]);
        assert_eq!(
            pinsrq.uses,
            vec![
                RegAllocOperand::VReg(old_vec),
                RegAllocOperand::VReg(scalar),
                RegAllocOperand::Imm(1),
            ]
        );
        assert!(pinsrq.implicit_defs.is_empty());
        assert!(pinsrq.implicit_uses.is_empty());

        let pextrq = &ra_func.insts[1];
        assert_eq!(pextrq.defs, vec![RegAllocOperand::VReg(dst_scalar)]);
        assert_eq!(
            pextrq.uses,
            vec![RegAllocOperand::VReg(dst_vec), RegAllocOperand::Imm(0)]
        );
        assert!(pextrq.implicit_defs.is_empty());
        assert!(pextrq.implicit_uses.is_empty());
    }

