    #[test]
    fn test_isel_to_regalloc_addri_marks_operand0_live_in() {
        let sig = Signature {
            params: vec![
                trust_cg_lower::types::Type::I64,
                trust_cg_lower::types::Type::I64,
            ],
            returns: vec![trust_cg_lower::types::Type::I64],
        };
        let mut func = X86ISelFunction::new("add_imm_inplace".to_string(), sig);
        let entry = Block(0);
        func.ensure_block(entry);

        let v0 = VReg::new(0, RegClass::Gpr64);
        func.next_vreg = 1;

        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::VReg(v0),
                    X86ISelOperand::PReg(x86_64_regs::RDI),
                ],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRI,
                vec![X86ISelOperand::VReg(v0), X86ISelOperand::Imm(7)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::VReg(v0),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let ra_func = x86_isel_to_regalloc(&func).unwrap();
        let add = &ra_func.insts[1];
        assert_eq!(
            add.defs,
            vec![RegAllocOperand::VReg(VReg::new(0, RegClass::Gpr64))]
        );
        assert_eq!(
            add.uses,
            vec![
                RegAllocOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                RegAllocOperand::Imm(7),
            ]
        );
    }

