    #[test]
    fn test_replay_regalloc_pseudo_copy_lowers_to_x86_mov_variants() {
        let cases = [
            (
                VReg::new(0, RegClass::Gpr64),
                VReg::new(1, RegClass::Gpr64),
                X86Opcode::MovRR,
            ),
            (
                VReg::new(0, RegClass::Gpr32),
                VReg::new(1, RegClass::Gpr32),
                X86Opcode::MovRR32,
            ),
            (
                VReg::new(0, RegClass::Fpr32),
                VReg::new(1, RegClass::Fpr32),
                X86Opcode::MovssRR,
            ),
            (
                VReg::new(0, RegClass::Fpr64),
                VReg::new(1, RegClass::Fpr64),
                X86Opcode::MovsdRR,
            ),
            (
                VReg::new(0, RegClass::Fpr128),
                VReg::new(1, RegClass::Fpr128),
                X86Opcode::MovdqaRR,
            ),
        ];

        for (dst, src, expected_opcode) in cases {
            let replayed = replay_inserted_pseudo_copy(dst, src).unwrap();
            let insts = entry_insts(&replayed);
            assert_eq!(insts.len(), 1);
            assert_eq!(insts[0].opcode, expected_opcode);
            assert_eq!(
                insts[0].operands,
                vec![X86ISelOperand::VReg(dst), X86ISelOperand::VReg(src)]
            );
        }
    }

