    #[test]
    fn test_replay_regalloc_stream_rejects_inserted_remat_clone_typed_fail_closed() {
        let mut func = minimal_func("inserted_remat_clone_rejected");
        let entry = Block(0);
        let value = VReg::new(0, RegClass::Gpr64);
        func.next_vreg = 1;
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![X86ISelOperand::VReg(value), X86ISelOperand::Imm(7)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::VReg(value),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let before = x86_isel_to_regalloc(&func).unwrap();
        let mut after = before.clone();
        let remat_id = InstId(after.insts.len() as u32);
        after.insts.push(after.insts[0].clone());
        after.blocks[0].insts.insert(1, remat_id);

        let original_opcodes = entry_opcodes(&func);
        let err = replay_x86_regalloc_stream_mutations(&mut func, &before, &after, &HashSet::new())
            .expect_err(
                "inserted rematerialized clones must fail closed until x86 replay supports them",
            );

        let X86PipelineError::RegAllocRematerializationReplayUnsupported { opcode } = err else {
            panic!("expected typed remat replay rejection");
        };
        assert_eq!(opcode, X86Opcode::MovRI as u16);
        assert_eq!(
            entry_opcodes(&func),
            original_opcodes,
            "failed remat replay must not partially rewrite the x86 ISel stream"
        );
    }

