    #[test]
    fn test_replay_regalloc_stream_replays_split_use_rewrite_across_blocks() {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut func = X86ISelFunction::new("split_rewrites_multiblock".to_string(), sig);
        let entry = Block(0);
        let exit = Block(1);
        let original = VReg::new(0, RegClass::Gpr64);
        let split = VReg::new(1, RegClass::Gpr64);
        func.ensure_block(entry);
        func.ensure_block(exit);
        func.blocks.get_mut(&entry).unwrap().successors.push(exit);
        func.next_vreg = 1;
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![X86ISelOperand::VReg(original), X86ISelOperand::Imm(11)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(exit)]),
        );
        func.push_inst(
            exit,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::VReg(original),
                ],
            ),
        );
        func.push_inst(exit, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let before = x86_isel_to_regalloc(&func).unwrap();
        let mut after = before.clone();
        after.next_vreg = 2;
        let copy_id = InstId(after.insts.len() as u32);
        after.insts.push(regalloc_pseudo_copy(split, original));
        after.blocks[1].insts.insert(0, copy_id);
        after.insts[2].uses = vec![RegAllocOperand::VReg(split)];

        replay_x86_regalloc_stream_mutations(&mut func, &before, &after, &HashSet::new())
            .expect("split use in successor block should replay into x86 ISel");

        let exit_insts = &func.blocks.get(&exit).unwrap().insts;
        assert_eq!(exit_insts.len(), 3);
        assert_eq!(
            exit_insts[0].operands,
            vec![X86ISelOperand::VReg(split), X86ISelOperand::VReg(original)]
        );
        assert_eq!(
            exit_insts[1].operands,
            vec![
                X86ISelOperand::PReg(x86_64_regs::RAX),
                X86ISelOperand::VReg(split),
            ]
        );
    }

    #[test]
    fn test_replay_regalloc_stream_replays_join_start_edge_copies() {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut func = X86ISelFunction::new("split_rewrites_join_edge_copies".to_string(), sig);
        let entry = Block(0);
        let left = Block(1);
        let right = Block(2);
        let join = Block(3);
        let original = VReg::new(0, RegClass::Gpr64);
        let split = VReg::new(1, RegClass::Gpr64);
        for block in [entry, left, right, join] {
            func.ensure_block(block);
        }
        func.blocks.get_mut(&entry).unwrap().successors = vec![left, right];
        func.blocks.get_mut(&left).unwrap().successors.push(join);
        func.blocks.get_mut(&right).unwrap().successors.push(join);
        func.next_vreg = 1;
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![X86ISelOperand::VReg(original), X86ISelOperand::Imm(11)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::Jcc,
                vec![
                    X86ISelOperand::CondCode(X86CondCode::E),
                    X86ISelOperand::Block(right),
                ],
            ),
        );
        func.push_inst(
            left,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(join)]),
        );
        func.push_inst(
            right,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(join)]),
        );
        func.push_inst(
            join,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::VReg(original),
                ],
            ),
        );
        func.push_inst(join, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let before = x86_isel_to_regalloc(&func).unwrap();
        let mut after = before.clone();
        after.next_vreg = 2;
        let left_copy = InstId(after.insts.len() as u32);
        after.insts.push(regalloc_pseudo_copy(split, original));
        let right_copy = InstId(after.insts.len() as u32);
        after.insts.push(regalloc_pseudo_copy(split, original));
        after.blocks[1].insts.insert(0, left_copy);
        after.blocks[2].insts.insert(0, right_copy);
        after.insts[4].uses = vec![RegAllocOperand::VReg(split)];

        replay_x86_regalloc_stream_mutations(&mut func, &before, &after, &HashSet::new())
            .expect("join-start edge copies should replay into predecessor x86 blocks");

        let left_insts = &func.blocks.get(&left).unwrap().insts;
        let right_insts = &func.blocks.get(&right).unwrap().insts;
        let join_insts = &func.blocks.get(&join).unwrap().insts;
        assert_eq!(left_insts.len(), 2);
        assert_eq!(right_insts.len(), 2);
        assert_eq!(left_insts[0].opcode, X86Opcode::MovRR);
        assert_eq!(right_insts[0].opcode, X86Opcode::MovRR);
        assert_eq!(
            left_insts[0].operands,
            vec![X86ISelOperand::VReg(split), X86ISelOperand::VReg(original)]
        );
        assert_eq!(
            right_insts[0].operands,
            vec![X86ISelOperand::VReg(split), X86ISelOperand::VReg(original)]
        );
        assert_eq!(left_insts[1].opcode, X86Opcode::Jmp);
        assert_eq!(right_insts[1].opcode, X86Opcode::Jmp);
        assert_eq!(
            join_insts[0].operands,
            vec![
                X86ISelOperand::PReg(x86_64_regs::RAX),
                X86ISelOperand::VReg(split),
            ]
        );
    }

