    #[test]
    fn test_full_regalloc_callee_saved_collection_maps_gpr32_aliases_to_save_roots() {
        let allocation = HashMap::from([
            (VReg::new(0, RegClass::Gpr32), x86_64_regs::R12D),
            (VReg::new(1, RegClass::Gpr32), x86_64_regs::EDI),
            (VReg::new(2, RegClass::Gpr32), x86_64_regs::EAX),
            (VReg::new(3, RegClass::Gpr64), x86_64_regs::RBX),
            (VReg::new(4, RegClass::Fpr128), x86_64_regs::XMM6),
        ]);

        let (windows_gprs, windows_xmms) =
            x86_used_callee_saved_from_allocation(X86CallAbi::WindowsX64, &allocation);
        assert_eq!(
            windows_gprs,
            vec![x86_64_regs::RBX, x86_64_regs::RDI, x86_64_regs::R12]
        );
        assert_eq!(windows_xmms, vec![x86_64_regs::XMM6]);

        let (sysv_gprs, sysv_xmms) =
            x86_used_callee_saved_from_allocation(X86CallAbi::SystemV, &allocation);
        assert_eq!(sysv_gprs, vec![x86_64_regs::RBX, x86_64_regs::R12]);
        assert!(sysv_xmms.is_empty());
    }

    #[cfg(all(target_arch = "x86_64", target_os = "windows"))]
    #[test]
    fn test_windows_jit_block_counters_reject_simplified_regalloc() {
        let func = build_x86_const_test_function();
        let pipeline = X86Pipeline::new(X86PipelineConfig {
            regalloc_mode: X86RegAllocMode::Simplified,
            ..X86PipelineConfig::default()
        });

        let err = pipeline
            .compile_function_with_jit_block_counters_after_x86_passes(&func)
            .expect_err("Windows block counters must reject simplified regalloc");

        let X86PipelineError::RegAlloc(msg) = err else {
            panic!("expected regalloc rejection, got {err:?}");
        };
        assert!(msg.contains("Windows x86_64 JIT block counters require full regalloc"));
        assert!(msg.contains("R10"));
    }

    fn build_x86_high_gpr_pressure_function(live_values: u32) -> X86ISelFunction {
        let mut func = minimal_func("high_gpr_pressure");
        let entry = Block(0);
        func.next_vreg = live_values;

        for id in 0..live_values {
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::MovRI,
                    vec![
                        X86ISelOperand::VReg(VReg::new(id, RegClass::Gpr64)),
                        X86ISelOperand::Imm(id as i64 + 1),
                    ],
                ),
            );
        }
        for id in 1..live_values {
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::AddRR,
                    vec![
                        X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                        X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                        X86ISelOperand::VReg(VReg::new(id, RegClass::Gpr64)),
                    ],
                ),
            );
        }
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));
        func
    }

