    fn build_x86_parent_loop_preheader_pressure_function(live_values: u32) -> X86ISelFunction {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut func = X86ISelFunction::new("parent_loop_preheader_pressure".to_string(), sig);
        let entry = Block(0);
        let loop_block = Block(1);
        let exit = Block(2);
        for block in [entry, loop_block, exit] {
            func.ensure_block(block);
        }
        func.blocks
            .get_mut(&entry)
            .unwrap()
            .successors
            .push(loop_block);
        func.blocks.get_mut(&loop_block).unwrap().successors = vec![loop_block, exit];
        func.next_vreg = live_values;

        for id in 0..live_values {
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::MovRI,
                    vec![
                        X86ISelOperand::VReg(VReg::new(id, RegClass::Gpr64)),
                        X86ISelOperand::Imm(id as i64 + 1),
                    ],
                ),
            );
        }
        for _ in 0..live_values {
            func.push_inst(
                entry,
                X86ISelInst::new(X86Opcode::NopMulti, vec![X86ISelOperand::Imm(2)]),
            );
        }
        func.push_inst(
            entry,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(loop_block)]),
        );

        for id in 0..live_values {
            func.push_inst(
                loop_block,
                X86ISelInst::new(
                    X86Opcode::CmpRI,
                    vec![
                        X86ISelOperand::VReg(VReg::new(id, RegClass::Gpr64)),
                        X86ISelOperand::Imm(0),
                    ],
                ),
            );
        }
        func.push_inst(
            loop_block,
            X86ISelInst::new(
                X86Opcode::Jcc,
                vec![
                    X86ISelOperand::CondCode(X86CondCode::E),
                    X86ISelOperand::Block(exit),
                ],
            ),
        );
        func.push_inst(
            loop_block,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(loop_block)]),
        );

        func.push_inst(
            exit,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                ],
            ),
        );
        func.push_inst(exit, X86ISelInst::new(X86Opcode::Ret, vec![]));
        func
    }

    fn build_x86_loop_carried_multidef_function() -> X86ISelFunction {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut func = X86ISelFunction::new("loop_carried_multidef".to_string(), sig);
        let entry = Block(0);
        let loop_block = Block(1);
        let exit = Block(2);
        for block in [entry, loop_block, exit] {
            func.ensure_block(block);
        }
        func.blocks
            .get_mut(&entry)
            .unwrap()
            .successors
            .push(loop_block);
        func.blocks.get_mut(&loop_block).unwrap().successors = vec![loop_block, exit];
        func.next_vreg = 1;

        let counter = VReg::new(0, RegClass::Gpr64);
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![X86ISelOperand::VReg(counter), X86ISelOperand::Imm(0)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(loop_block)]),
        );

        func.push_inst(
            loop_block,
            X86ISelInst::new(
                X86Opcode::CmpRI,
                vec![X86ISelOperand::VReg(counter), X86ISelOperand::Imm(6)],
            ),
        );
        func.push_inst(
            loop_block,
            X86ISelInst::new(
                X86Opcode::Jcc,
                vec![
                    X86ISelOperand::CondCode(X86CondCode::E),
                    X86ISelOperand::Block(exit),
                ],
            ),
        );
        func.push_inst(
            loop_block,
            X86ISelInst::new(
                X86Opcode::AddRI,
                vec![X86ISelOperand::VReg(counter), X86ISelOperand::Imm(1)],
            ),
        );
        func.push_inst(
            loop_block,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(loop_block)]),
        );

        func.push_inst(
            exit,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::VReg(counter),
                ],
            ),
        );
        func.push_inst(exit, X86ISelInst::new(X86Opcode::Ret, vec![]));
        func
    }

    #[test]
    fn test_full_regalloc_high_pressure_materializes_spills_with_split_replay() {
        let func = build_x86_high_gpr_pressure_function(15);
        for strategy in [AllocStrategy::LinearScan, AllocStrategy::Greedy] {
            let pipeline = X86Pipeline::new(X86PipelineConfig {
                opt_level: trust_cg_opt::OptLevel::O0,
                regalloc_mode: X86RegAllocMode::Full(strategy),
                ..X86PipelineConfig::default()
            });
            let code = pipeline
                .compile_function(&func)
                .unwrap_or_else(|err| panic!("high-pressure {strategy:?} regalloc failed: {err}"));
            assert!(!code.is_empty(), "{strategy:?} should produce code");
            assert_eq!(*code.last().unwrap(), 0xC3, "last byte should be RET");
        }
    }

