    #[test]
    fn test_greedy_regalloc_join_block_rejects_splitting() {
        // ANY join block (a block with >1 predecessor) rejects splitting — the
        // greedy join-block split-copy placement is unsound under register
        // pressure even without a call crossing the join (MISCOMPILE #64).
        // Previously this CFG was admitted ("safe join"); it is now failed
        // closed to plain greedy spill.
        let func = build_x86_safe_join_cfg_function("join_split_guard");
        let ra_func = x86_isel_to_regalloc(&func).expect("x86 conversion should succeed");
        assert_eq!(
            x86_regalloc_splitting_cfg_diagnostic(&ra_func),
            Err(X86SplitReplayCfgDiagnostic::JoinBlockUnderSplit { join: BlockId(3) }),
        );
        assert!(
            !x86_regalloc_splitting_supported_cfg(&ra_func),
            "x86 splitting must be rejected for any join block — call-free join \
             split-copy placement is unsound under pressure (m64)"
        );
    }

    #[test]
    fn test_greedy_regalloc_call_across_join_rejects_splitting() {
        // A diamond CFG (entry -> {left,right} -> join) whose entry block makes a
        // `call` is the `?`-operator shape: a value live across the call AND the
        // join can lose its split copy on the taken path under the greedy
        // splitter, faulting/miscompiling at runtime. Splitting must be REJECTED
        // (fail closed to plain greedy spill) for this shape; the call-free
        // `build_x86_safe_join_cfg_function` join above keeps splitting.
        let mut func = build_x86_safe_join_cfg_function("call_across_join_guard");
        let entry = Block(0);
        // Prepend a real call into the entry block (before its conditional branch),
        // so the function has BOTH a call and a join block.
        let entry_block = func.blocks.get_mut(&entry).unwrap();
        entry_block.insts.insert(
            0,
            X86ISelInst::new(X86Opcode::Call, vec![X86ISelOperand::Imm(0)]),
        );
        let ra_func = x86_isel_to_regalloc(&func).expect("x86 conversion should succeed");
        assert_eq!(
            x86_regalloc_splitting_cfg_diagnostic(&ra_func),
            Err(X86SplitReplayCfgDiagnostic::CallAcrossJoin { join: BlockId(3) }),
        );
        assert!(
            !x86_regalloc_splitting_supported_cfg(&ra_func),
            "x86 splitting must be rejected when a function has both a call and a join \
             (the `?`-operator diamond) — its join split-copy placement is unsound there"
        );
    }

    #[test]
    fn test_greedy_regalloc_fixed_reg_clobber_rejects_splitting() {
        // A function containing a DIV (a fixed-physical-register clobber: the
        // dividend is pinned in RAX and RDX is clobbered) must reject splitting —
        // the greedy splitter does not model the implicit RAX/RDX def/use edges,
        // so a live range crossing the DIV can be spilled to / reloaded from a
        // slot the DIV corrupted (the div/rem-under-pressure miscompile, m52).
        // A plain MOV to a physical register (RAX for the return value) is NOT a
        // clobber and must keep splitting; the clobber-free fixture below proves
        // the guard does not fire on it.
        let mut func = build_x86_two_block_linear_high_gpr_pressure_function(4);
        let entry = Block(0);
        func.blocks.get_mut(&entry).unwrap().insts.insert(
            0,
            X86ISelInst::new(
                X86Opcode::Div,
                vec![X86ISelOperand::VReg(VReg::new(1, RegClass::Gpr64))],
            ),
        );
        let ra_func = x86_isel_to_regalloc(&func).expect("x86 conversion should succeed");
        assert_eq!(
            x86_regalloc_splitting_cfg_diagnostic(&ra_func),
            Err(X86SplitReplayCfgDiagnostic::FixedRegClobber {
                opcode: X86Opcode::Div as u16
            })
        );
        assert!(
            !x86_regalloc_splitting_supported_cfg(&ra_func),
            "a function containing a DIV fixed-register clobber must reject splitting"
        );

        // Sanity: the clobber-free fixture keeps splitting (a plain `mov RAX, vN`
        // for the return value is not treated as a clobber).
        let clean = build_x86_two_block_linear_high_gpr_pressure_function(4);
        let clean_ra = x86_isel_to_regalloc(&clean).expect("x86 conversion should succeed");
        assert_eq!(x86_regalloc_splitting_cfg_diagnostic(&clean_ra), Ok(()));
        assert!(
            x86_regalloc_splitting_supported_cfg(&clean_ra),
            "a plain `mov RAX, vN` return-value move is not a fixed-register clobber"
        );
    }

    #[test]
    fn test_x86_regalloc_opcode_is_fixed_reg_clobber_classification() {
        // The clobber set must be exactly the opcodes whose fixed RAX/RDX (etc.)
        // constraints `add_x86_fixed_implicit_operands` adds as implicit edges.
        for op in [
            X86Opcode::Div,
            X86Opcode::Idiv,
            X86Opcode::Mul,
            X86Opcode::Cdq,
            X86Opcode::Cqo,
            X86Opcode::Cmpxchg,
            X86Opcode::AtomicRmwCasLoop,
            X86Opcode::AtomicRmwCasLoop8,
            X86Opcode::AtomicRmwCasLoop16,
        ] {
            assert!(
                x86_regalloc_opcode_is_fixed_reg_clobber(op as u16),
                "{op:?} pins/clobbers a fixed physical register and must be flagged"
            );
        }
        // Ordinary explicit-operand ops (including the explicit `mov RAX, vN`
        // return-value setup) carry no implicit fixed-register edges and must NOT
        // be flagged, so they keep splitting.
        for op in [
            X86Opcode::MovRR,
            X86Opcode::MovRI,
            X86Opcode::AddRR,
            X86Opcode::SubRR,
            X86Opcode::Ret,
            X86Opcode::Jmp,
        ] {
            assert!(
                !x86_regalloc_opcode_is_fixed_reg_clobber(op as u16),
                "{op:?} has no implicit fixed-register clobber and must keep splitting"
            );
        }
    }

