    #[test]
    fn test_fixup_two_address_shift_rr_regalloc_does_not_clobber_count() {
        let mut func = minimal_func("shift_rr_count_not_clobbered");
        let entry = Block(0);
        let lhs = VReg::new(0, RegClass::Gpr64);
        let count = VReg::new(1, RegClass::Gpr64);
        let dst = VReg::new(2, RegClass::Gpr64);
        func.next_vreg = 3;

        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![X86ISelOperand::VReg(lhs), X86ISelOperand::Imm(9)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![X86ISelOperand::VReg(count), X86ISelOperand::Imm(2)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RCX),
                    X86ISelOperand::VReg(count),
                ],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::ShlRR,
                vec![X86ISelOperand::VReg(dst), X86ISelOperand::VReg(lhs)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::VReg(dst),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let pipeline = raw_no_frame_x86_pipeline();
        let assignment = pipeline
            .run_full_regalloc(&mut func, AllocStrategy::LinearScan)
            .expect("linear-scan regalloc should allocate shift regression");
        let dst_preg = assignment.allocation[&dst];
        assert!(
            !x86_64_regs::x86_regs_overlap(dst_preg, x86_64_regs::RCX),
            "shift result must not be allocated to RCX because CL holds the count"
        );

        fixup_two_address(&mut func, &assignment.allocation, X86CallAbi::SystemV).unwrap();

        let insts = &func.blocks[&entry].insts;
        let count_move_idx = insts
            .iter()
            .position(|inst| {
                inst.opcode == X86Opcode::MovRR
                    && inst.operands.first() == Some(&X86ISelOperand::PReg(x86_64_regs::RCX))
            })
            .expect("test function should still contain the count move into RCX");
        let shift_idx = insts
            .iter()
            .position(|inst| inst.opcode == X86Opcode::ShlRR)
            .expect("test function should still contain the register shift");
        assert!(
            count_move_idx + 1 < shift_idx,
            "two-address copy should be inserted between the count move and shift"
        );
        assert_eq!(insts[shift_idx - 1].opcode, X86Opcode::MovRR);
        let copy_dst = resolve_operand(&insts[shift_idx - 1].operands[0], &assignment.allocation)
            .expect("two-address copy destination should resolve");
        assert_eq!(copy_dst, dst_preg);
        assert!(
            !x86_64_regs::x86_regs_overlap(copy_dst, x86_64_regs::RCX),
            "two-address fixup must not write RCX before the shift consumes CL"
        );
    }

