    #[test]
    fn test_fixup_two_address_noncommutative_packed_sse_rhs_alias_uses_scratch() {
        for opcode in [
            X86Opcode::Pandn,
            X86Opcode::Pcmpgtb,
            X86Opcode::Pcmpgtw,
            X86Opcode::Pcmpgtd,
            X86Opcode::Psubb,
            X86Opcode::Psubw,
            X86Opcode::Psubd,
        ] {
            let mut func = minimal_func("packed_sse_rhs_alias_fixup_test");
            let entry = Block(0);
            let lhs = VReg::new(0, RegClass::Fpr128);
            let rhs = VReg::new(1, RegClass::Fpr128);
            let dst = VReg::new(2, RegClass::Fpr128);
            func.next_vreg = 3;

            func.push_inst(
                entry,
                X86ISelInst::new(
                    opcode,
                    vec![
                        X86ISelOperand::VReg(dst),
                        X86ISelOperand::VReg(lhs),
                        X86ISelOperand::VReg(rhs),
                    ],
                ),
            );

            let mut alloc = HashMap::new();
            alloc.insert(lhs, XMM0);
            alloc.insert(rhs, XMM1);
            alloc.insert(dst, XMM1);

            fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap();

            let insts = &func.blocks[&entry].insts;
            assert_eq!(
                insts.len(),
                3,
                "{opcode:?} should preserve rhs through a scratch sequence"
            );
            assert_eq!(insts[0].opcode, X86Opcode::MovdqaRR);
            assert_eq!(insts[1].opcode, opcode);
            assert_eq!(insts[2].opcode, X86Opcode::MovdqaRR);

            let scratch = X86ISelOperand::PReg(XMM14);
            assert_eq!(
                insts[0].operands,
                vec![scratch.clone(), X86ISelOperand::VReg(lhs)]
            );
            assert_eq!(
                insts[1].operands,
                vec![scratch.clone(), scratch.clone(), X86ISelOperand::VReg(rhs)]
            );
            assert_eq!(insts[2].operands, vec![X86ISelOperand::VReg(dst), scratch]);

            let copy_in = resolve_inst_operands(&insts[0], &alloc);
            assert_eq!(copy_in.dst, Some(XMM14));
            assert_eq!(copy_in.src, Some(XMM0));
            let packed_op = resolve_inst_operands(&insts[1], &alloc);
            assert_eq!(packed_op.dst, Some(XMM14));
            assert_eq!(packed_op.src, Some(XMM1));
            let copy_out = resolve_inst_operands(&insts[2], &alloc);
            assert_eq!(copy_out.dst, Some(XMM1));
            assert_eq!(copy_out.src, Some(XMM14));
        }
    }

    #[test]
    fn test_fixup_two_address_noncommutative_packed_sse_rhs_alias_fails_without_scratch() {
        let mut func = minimal_func("packed_sse_rhs_alias_no_scratch_test");
        let entry = Block(0);
        let lhs = VReg::new(0, RegClass::Fpr128);
        let rhs = VReg::new(1, RegClass::Fpr128);
        let dst = VReg::new(2, RegClass::Fpr128);
        func.next_vreg = 3;

        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::Pcmpgtd,
                vec![
                    X86ISelOperand::VReg(dst),
                    X86ISelOperand::VReg(lhs),
                    X86ISelOperand::VReg(rhs),
                ],
            ),
        );

        let mut alloc = HashMap::new();
        alloc.insert(lhs, XMM0);
        alloc.insert(rhs, XMM1);
        alloc.insert(dst, XMM1);
        for (idx, preg) in X86_ALLOCATABLE_XMMS.iter().copied().enumerate() {
            alloc.insert(VReg::new(10 + idx as u32, RegClass::Fpr128), preg);
        }

        let err = fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap_err();
        let X86PipelineError::RegAlloc(msg) = err else {
            panic!("expected RegAlloc fail-closed error");
        };
        assert!(
            msg.contains("cannot repair dst/rhs alias"),
            "unexpected error: {msg}"
        );
    }

