    // -----------------------------------------------------------------------
    // TV-5 ghost-operand contract + end-to-end fault injection
    // -----------------------------------------------------------------------

    /// Build `[opcode v1, v0, v2]` (three-address, vregs 0..=2) in a fresh
    /// function for driving `fixup_two_address` directly.
    fn tv5_three_address_func(opcode: X86Opcode) -> X86ISelFunction {
        let mut func = minimal_func("tv5_fixup");
        let entry = Block(0);
        func.next_vreg = 3;
        func.push_inst(
            entry,
            X86ISelInst::new(
                opcode,
                vec![test_vreg_op(0), test_vreg_op(1), test_vreg_op(2)],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));
        func
    }

    #[test]
    fn x86_packed_bitwise_fixup_uses_full_xmm_bridge() {
        use trust_cg_ir::x86_64_regs::{XMM0, XMM1, XMM2};

        for (opcode, class) in [
            (X86Opcode::Andps, RegClass::Fpr32),
            (X86Opcode::Andpd, RegClass::Fpr64),
        ] {
            let mut func = minimal_func("packed_bitwise_bridge");
            let entry = Block(0);
            let dst = VReg::new(0, class);
            let lhs = VReg::new(1, class);
            let rhs = VReg::new(2, class);
            func.next_vreg = 3;
            func.push_inst(
                entry,
                X86ISelInst::new(
                    opcode,
                    vec![
                        X86ISelOperand::VReg(dst),
                        X86ISelOperand::VReg(lhs),
                        X86ISelOperand::VReg(rhs),
                    ],
                ),
            );
            let alloc = HashMap::from([(dst, XMM2), (lhs, XMM0), (rhs, XMM1)]);

            fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap();

            let insts = &func.blocks[&entry].insts;
            assert_eq!(insts.len(), 2, "{opcode:?}: {insts:?}");
            assert_eq!(
                insts[0].opcode,
                X86Opcode::MovdqaRR,
                "{opcode:?} reads all 128 XMM bits and needs a full-width bridge"
            );
            assert_eq!(insts[1].opcode, opcode);
        }
    }

    /// PINNED GHOST CONTRACT: the tied-ghost-operand dataflow validator
    /// (trust-cg-verify::post_ra_dataflow) depends on `operands[1]` of a
    /// tied-form instruction surviving `fixup_two_address` as the
    /// encoder-ignored certificate of the intended tied source. Pin all
    /// three fixup arms:
    ///   arm 3 (bridge copy): the copy `[dst, lhs]` is inserted immediately
    ///     before the tied instruction and `operands[1]` is UNCHANGED;
    ///   arm 1 (commutative dst-aliases-rhs swap): operands 1 and 2 are
    ///     swapped so `operands[1]` resolves to a register overlapping
    ///     `operands[0]`;
    ///   arm 2 (non-commutative dst-aliases-rhs scratch triangle):
    ///     `operands[0]` and `operands[1]` are BOTH the same scratch PReg.
    #[test]
    fn x86_fixup_two_address_ghost_contract_pinned() {
        use trust_cg_ir::x86_64_regs::{RAX, RCX, RDX};
        let entry = Block(0);

        // Arm 3: dst(RAX) != lhs(RCX), rhs(RDX) disjoint -> bridge copy.
        let mut func = tv5_three_address_func(X86Opcode::AddRR);
        let alloc = HashMap::from([
            (test_vreg(0), RAX),
            (test_vreg(1), RCX),
            (test_vreg(2), RDX),
        ]);
        fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap();
        let insts = &func.blocks[&entry].insts;
        assert_eq!(insts.len(), 3, "bridge copy + tied inst + ret");
        assert_eq!(insts[0].opcode, X86Opcode::MovRR);
        assert_eq!(
            insts[0].operands,
            vec![test_vreg_op(0), test_vreg_op(1)],
            "the bridge copy must be `mov dst <- lhs`, adjacent to the tied inst"
        );
        assert_eq!(insts[1].opcode, X86Opcode::AddRR);
        assert_eq!(
            insts[1].operands[1],
            test_vreg_op(1),
            "arm 3 must leave the ghost operands[1] UNCHANGED"
        );

        // Arm 1: commutative, dst aliases rhs -> swap; op1 then aliases op0.
        let mut func = tv5_three_address_func(X86Opcode::AddRR);
        let alloc = HashMap::from([
            (test_vreg(0), RAX),
            (test_vreg(1), RCX),
            (test_vreg(2), RAX),
        ]);
        fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap();
        let insts = &func.blocks[&entry].insts;
        assert_eq!(insts.len(), 2, "swap arm inserts no copy");
        assert_eq!(insts[0].opcode, X86Opcode::AddRR);
        assert_eq!(
            insts[0].operands,
            vec![test_vreg_op(0), test_vreg_op(2), test_vreg_op(1)]
        );
        let op0 = resolve_operand(&insts[0].operands[0], &alloc).unwrap();
        let op1 = resolve_operand(&insts[0].operands[1], &alloc).unwrap();
        assert!(
            x86_64_regs::x86_regs_overlap(op0, op1),
            "after the commutative swap the ghost must alias the destination"
        );

        // Arm 2: non-commutative, dst aliases rhs -> scratch triangle.
        let mut func = tv5_three_address_func(X86Opcode::SubRR);
        let alloc = HashMap::from([
            (test_vreg(0), RAX),
            (test_vreg(1), RCX),
            (test_vreg(2), RAX),
        ]);
        fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap();
        let insts = &func.blocks[&entry].insts;
        assert_eq!(insts.len(), 4, "copy-in + tied inst + copy-out + ret");
        assert_eq!(insts[0].opcode, X86Opcode::MovRR);
        assert_eq!(insts[1].opcode, X86Opcode::SubRR);
        assert_eq!(insts[2].opcode, X86Opcode::MovRR);
        let scratch = insts[1].operands[0].clone();
        assert!(
            matches!(scratch, X86ISelOperand::PReg(_)),
            "arm 2 rewrites the destination to a scratch PReg"
        );
        assert_eq!(
            insts[1].operands[1], scratch,
            "arm 2 must set operands[0] == operands[1] == the scratch"
        );
        assert_eq!(insts[0].operands[0], scratch, "copy-in targets the scratch");
        assert_eq!(insts[0].operands[1], test_vreg_op(1));
        assert_eq!(insts[2].operands, vec![test_vreg_op(0), scratch]);
    }

    /// End-to-end fault injection over REAL fixup output: run
    /// `fixup_two_address`, assert the stream passes the TV-5 dataflow
    /// validator, then DELETE the inserted bridge copy and assert the
    /// validator refutes with tied-operand-value-mismatch — the exact
    /// empirically proven silent-miscompile shape.
    #[test]
    fn x86_post_ra_dataflow_end_to_end_fault_injection_refutes() {
        use trust_cg_ir::x86_64_regs::{RAX, RCX, RDX};
        use trust_cg_verify::post_ra_dataflow;
        use trust_cg_verify::post_regalloc_recheck::PostRegallocRecheckMode;

        let entry = Block(0);
        let mut func = tv5_three_address_func(X86Opcode::AddRR);
        let alloc = HashMap::from([
            (test_vreg(0), RAX),
            (test_vreg(1), RCX),
            (test_vreg(2), RDX),
        ]);
        fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap();

        // Green half: the un-mutated fixup output discharges the obligation.
        assert!(
            post_ra_dataflow::evaluate(&func, &alloc, "x86_64", PostRegallocRecheckMode::Enforce)
                .is_none(),
            "sound fixup output must pass the dataflow validator"
        );

        // Fault injection: delete the load-bearing bridge copy.
        let block = func.blocks.get_mut(&entry).unwrap();
        let bridge_idx = block
            .insts
            .iter()
            .position(|inst| inst.opcode == X86Opcode::MovRR)
            .expect("fixup must have inserted a MovRR bridge copy");
        block.insts.remove(bridge_idx);

        let violation =
            post_ra_dataflow::evaluate(&func, &alloc, "x86_64", PostRegallocRecheckMode::Enforce)
                .expect("deleting the bridge copy must fail closed");
        assert_eq!(violation.kind.tag(), "tied-operand-value-mismatch");
    }

    /// The pipeline recheck surfaces the TV-5 refutation as a fail-closed
    /// `X86PipelineError::RegAlloc` carrying the greppable tag (env is never
    /// set in tests; the compiled-in default is Enforce).
    #[test]
    fn x86_recheck_post_regalloc_dataflow_error_string() {
        use trust_cg_ir::x86_64_regs::{RAX, RCX, RDX};

        let entry = Block(0);
        let mut func = tv5_three_address_func(X86Opcode::AddRR);
        let alloc = HashMap::from([
            (test_vreg(0), RAX),
            (test_vreg(1), RCX),
            (test_vreg(2), RDX),
        ]);
        fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap();
        let block = func.blocks.get_mut(&entry).unwrap();
        let bridge_idx = block
            .insts
            .iter()
            .position(|inst| inst.opcode == X86Opcode::MovRR)
            .expect("fixup must have inserted a MovRR bridge copy");
        block.insts.remove(bridge_idx);

        let pipeline = X86Pipeline::new(X86PipelineConfig::default());
        let err = pipeline
            .recheck_post_regalloc(&func, &alloc, &HashSet::new())
            .expect_err("the corrupted stream must fail the recheck closed");
        match err {
            X86PipelineError::RegAlloc(msg) => {
                assert!(msg.contains("[TCG-POST-RA-DATAFLOW]"), "{msg}");
                assert!(msg.contains("tied-operand-value-mismatch"), "{msg}");
            }
            other => panic!("expected X86PipelineError::RegAlloc, got {other:?}"),
        }
    }

    /// Green end-to-end: a function whose lowering GUARANTEES a two-address
    /// bridge copy (dst != lhs on physical registers) compiles Ok through the
    /// full pipeline with the TV-5 dataflow gate live at its Enforce default.
    #[test]
    fn x86_post_ra_dataflow_green_end_to_end_bridge_copy() {
        use trust_cg_ir::x86_64_regs::{RAX, RCX, RDX};

        let mut func = minimal_func("tv5_green");
        let entry = Block(0);
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![X86ISelOperand::PReg(RCX), X86ISelOperand::Imm(1)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![X86ISelOperand::PReg(RDX), X86ISelOperand::Imm(2)],
            ),
        );
        // Three-address on pregs: dst(RAX) != lhs(RCX) forces the bridge.
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::PReg(RAX),
                    X86ISelOperand::PReg(RCX),
                    X86ISelOperand::PReg(RDX),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let pipeline = raw_no_frame_x86_pipeline();
        let code = pipeline
            .compile_function(&func)
            .expect("guaranteed-bridge function must compile with TV-5 enforced");
        assert!(!code.is_empty());
    }

    /// PINNED (movrr-coalesce x TV-5, green half): the post-fixup `MovRR`
    /// coalescer deletes a pure CSE copy and renames the downstream real
    /// reads AND the encoder-ignored tied ghost `operands[1]` in lockstep,
    /// and the transformed stream still discharges TV-5's tied-operand
    /// obligation (the sym-faithful-rename carve-out documented in
    /// trust-cg-verify::post_ra_dataflow's module doc).
    #[test]
    fn x86_movrr_coalesce_renames_ghost_and_passes_tv5() {
        use trust_cg_ir::x86_64_regs::{RBX, RCX, RDX, RSI};
        use trust_cg_verify::post_ra_dataflow;
        use trust_cg_verify::post_regalloc_recheck::PostRegallocRecheckMode;

        let entry = Block(0);
        let mut func = minimal_func("movrr_ghost_rename");
        // Post-fixup shape: pure CSE copy, arm-3 bridge, tied op, ret.
        //   movq %rbx, %rsi          (candidate: pdst=RSI <- psrc=RBX)
        //   movq %rsi, %rcx          (bridge: dst <- lhs)
        //   addq  [RCX, ghost=RSI, RDX]
        //   ret
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RSI), X86ISelOperand::PReg(RBX)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RCX), X86ISelOperand::PReg(RSI)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::PReg(RCX),
                    X86ISelOperand::PReg(RSI),
                    X86ISelOperand::PReg(RDX),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let alloc: HashMap<VReg, X86PReg> = HashMap::new();
        let removed = coalesce_x86_redundant_movrr_copies(&mut func, &alloc);
        assert_eq!(removed, 1, "exactly the pure CSE copy must be coalesced");

        let insts = &func.blocks[&entry].insts;
        assert_eq!(insts.len(), 3, "copy deleted; bridge + tied + ret remain");
        assert_eq!(insts[0].opcode, X86Opcode::MovRR);
        assert_eq!(
            insts[0].operands,
            vec![X86ISelOperand::PReg(RCX), X86ISelOperand::PReg(RBX)],
            "the bridge's real read must be renamed to the copy source"
        );
        assert_eq!(insts[1].opcode, X86Opcode::AddRR);
        assert_eq!(
            insts[1].operands[1],
            X86ISelOperand::PReg(RBX),
            "the tied ghost operands[1] must be renamed in lockstep"
        );

        assert!(
            post_ra_dataflow::evaluate(&func, &alloc, "x86_64", PostRegallocRecheckMode::Enforce)
                .is_none(),
            "the sym-faithful rename must discharge TV-5's tied obligation"
        );
    }

    /// PINNED (bridge-into-LEA x TV-5): the collapse must REUSE the `AddRR`'s
    /// own operands, so the destination keeps its VREG identity.
    ///
    /// Regression test. The first version of this rewrite built the `LeaSib`
    /// out of freshly spelled `PReg`s. The register written is identical, so
    /// every differential run passed — but the destination VREG lost its
    /// definition at this instruction, and TV-5 then walks back to that vreg's
    /// previous def. With a call in between it reports
    /// `call-severed-vreg-read` and the compile FAILS CLOSED. That took out
    /// 7 of the 18 bench programs at -O2/-O3.
    ///
    /// Asserting on the emitted opcode alone would NOT catch it, so this pins
    /// the operands themselves and re-runs TV-5.
    #[test]
    fn x86_bridge_into_lea_preserves_vreg_identity() {
        use trust_cg_ir::x86_64_regs::{RBX, RCX, RDI, RDX};
        use trust_cg_verify::post_ra_dataflow;
        use trust_cg_verify::post_regalloc_recheck::PostRegallocRecheckMode;

        let entry = Block(0);
        let mut func = minimal_func("bridge_into_lea_vregs");
        let vr = |id| VReg::new(id, trust_cg_ir::regs::RegClass::Gpr64);
        let (d, a, b) = (vr(0), vr(1), vr(2));

        //   movq  a, d              <- the two-address bridge
        //   addq  d, ghost a, b     <- tied add
        //   addq  rdi, rdi, rdi     <- full CC definer, so the add's flags die
        //   ret
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::VReg(d), X86ISelOperand::VReg(a)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::VReg(d),
                    X86ISelOperand::VReg(a),
                    X86ISelOperand::VReg(b),
                ],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::PReg(RDI),
                    X86ISelOperand::PReg(RDI),
                    X86ISelOperand::PReg(RDI),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let mut alloc: HashMap<VReg, X86PReg> = HashMap::new();
        alloc.insert(d, RCX);
        alloc.insert(a, RBX);
        alloc.insert(b, RDX);

        let removed = coalesce_x86_redundant_movrr_copies(&mut func, &alloc);
        assert_eq!(removed, 1, "the bridge copy must be collapsed into the LEA");

        let insts = &func.blocks[&entry].insts;
        assert_eq!(insts[0].opcode, X86Opcode::LeaSib);
        assert_eq!(
            insts[0].operands,
            vec![
                X86ISelOperand::VReg(d),
                X86ISelOperand::SibMemAddr {
                    base: Box::new(X86ISelOperand::VReg(a)),
                    index: Box::new(X86ISelOperand::VReg(b)),
                    scale: 1,
                    disp: 0,
                },
            ],
            "the LEA must carry the add's own VREG operands, not re-spelled PRegs \
             — re-spelling orphans the destination vreg's definition"
        );

        assert!(
            post_ra_dataflow::evaluate(&func, &alloc, "x86_64", PostRegallocRecheckMode::Enforce)
                .is_none(),
            "the collapsed stream must still discharge TV-5"
        );
    }

    /// PINNED (movrr-coalesce x TV-5, negative half): the GHOST-SKIPPING
    /// variant of the same transform — copy deleted, real reads renamed, ghost
    /// `operands[1]` left stale — is REFUTED by TV-5 with
    /// tied-operand-value-mismatch. This documents WHY the coalescer's ghost
    /// rename is mandatory (skipping it turns sound output into a spurious
    /// fail-closed compile error), i.e. the carve-out in
    /// trust-cg-verify::post_ra_dataflow is required, not merely permitted.
    #[test]
    fn x86_movrr_coalesce_ghost_skip_variant_refuted_by_tv5() {
        use trust_cg_ir::x86_64_regs::{RBX, RCX, RDX, RSI};
        use trust_cg_verify::post_ra_dataflow;
        use trust_cg_verify::post_regalloc_recheck::PostRegallocRecheckMode;

        let entry = Block(0);
        let mut func = minimal_func("movrr_ghost_skip");
        // Hand-built output of a HYPOTHETICAL ghost-skipping coalescer applied
        // to the stream in the green-half test above:
        //   movq %rbx, %rcx          (bridge renamed to the copy source)
        //   addq  [RCX, ghost=RSI(STALE), RDX]
        //   ret
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RCX), X86ISelOperand::PReg(RBX)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::PReg(RCX),
                    X86ISelOperand::PReg(RSI),
                    X86ISelOperand::PReg(RDX),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let alloc: HashMap<VReg, X86PReg> = HashMap::new();
        let violation =
            post_ra_dataflow::evaluate(&func, &alloc, "x86_64", PostRegallocRecheckMode::Enforce)
                .expect("a stale ghost sym after copy deletion must be refuted");
        assert_eq!(violation.kind.tag(), "tied-operand-value-mismatch");
    }

    /// PINNED (bail-on-bridge): a `MovRR` that is itself the arm-3 two-address
    /// bridge feeding a tied op is NEVER deleted — the scan classifies op0 of
    /// the tied form as a (partial, tied) machine read of the copy destination
    /// while the same instruction defines it, and bails before any mutation.
    #[test]
    fn x86_movrr_coalesce_never_deletes_tied_bridge() {
        use trust_cg_ir::x86_64_regs::{RBX, RCX, RDX};

        let entry = Block(0);
        let mut func = minimal_func("movrr_bridge_bail");
        //   movq %rbx, %rcx          (the bridge itself is the candidate)
        //   addq  [RCX, ghost=RBX, RDX]
        //   ret
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RCX), X86ISelOperand::PReg(RBX)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::PReg(RCX),
                    X86ISelOperand::PReg(RBX),
                    X86ISelOperand::PReg(RDX),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let alloc: HashMap<VReg, X86PReg> = HashMap::new();
        let removed = coalesce_x86_redundant_movrr_copies(&mut func, &alloc);
        assert_eq!(removed, 0, "a tied op's bridge copy must never be deleted");

        let insts = &func.blocks[&entry].insts;
        assert_eq!(insts.len(), 3, "stream must be untouched");
        assert_eq!(insts[0].opcode, X86Opcode::MovRR);
        assert_eq!(
            insts[0].operands,
            vec![X86ISelOperand::PReg(RCX), X86ISelOperand::PReg(RBX)]
        );
        assert_eq!(
            insts[1].operands[1],
            X86ISelOperand::PReg(RBX),
            "ghost untouched"
        );
    }

    /// PINNED (mirror drift): the coalescer's implicit-register model
    /// `x86_inst_implicit_gpr64_roots` must agree with regalloc's
    /// `add_x86_fixed_implicit_operands` at GPR64-root granularity over every
    /// opcode either side names, plus a no-implicit control set — the same
    /// pattern as TV-5's `post_ra_tied_lhs_index` mirror pin. If you add an
    /// opcode with implicit fixed GPRs to `add_x86_fixed_implicit_operands`,
    /// add it HERE and mirror it in `x86_inst_implicit_gpr64_roots` (an
    /// unmirrored implicit use could otherwise let the coalescer rename a
    /// read the mirror cannot see). Call/return conventions are excluded:
    /// the mirror models them separately from `call_arg_regs`/return-reg
    /// facts and treats calls as hard barriers regardless.
    #[test]
    fn x86_movrr_implicit_gpr64_mirror_agrees_with_regalloc_model() {
        use std::collections::BTreeSet;
        use trust_cg_regalloc::x86_adapter::preg_to_x86;

        fn mirror_roots(inst: &X86ISelInst) -> (BTreeSet<&'static str>, BTreeSet<&'static str>) {
            let mut uses = Vec::new();
            let mut defs = Vec::new();
            x86_inst_implicit_gpr64_roots(inst, &mut uses, &mut defs);
            let name_set = |v: &[X86PReg]| {
                v.iter()
                    .map(|&r| x86_64_regs::x86_preg_name(r))
                    .collect::<BTreeSet<_>>()
            };
            (name_set(&uses), name_set(&defs))
        }

        fn regalloc_roots(inst: &X86ISelInst) -> (BTreeSet<&'static str>, BTreeSet<&'static str>) {
            let mut implicit_defs = Vec::new();
            let mut implicit_uses = Vec::new();
            add_x86_fixed_implicit_operands(inst, &mut implicit_defs, &mut implicit_uses);
            let name_set = |v: &[trust_cg_regalloc::PReg]| {
                v.iter()
                    .filter_map(|&p| preg_to_x86(p))
                    .filter_map(x86_64_regs::x86_containing_gpr64)
                    .map(x86_64_regs::x86_preg_name)
                    .collect::<BTreeSet<_>>()
            };
            (name_set(&implicit_uses), name_set(&implicit_defs))
        }

        let gpr32_first_operand = || vec![X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr32))];

        // Every opcode named by either implicit-register model, each in the
        // operand shapes that change its fixed-register selection, plus
        // representative no-implicit controls.
        let cases: Vec<(X86Opcode, Vec<X86ISelOperand>)> = vec![
            (X86Opcode::Cdq, vec![]),
            (X86Opcode::Cqo, vec![]),
            (X86Opcode::ShlRR, vec![]),
            (X86Opcode::ShrRR, vec![]),
            (X86Opcode::SarRR, vec![]),
            (X86Opcode::Idiv, vec![]),
            (X86Opcode::Idiv, gpr32_first_operand()),
            (X86Opcode::Div, vec![]),
            (X86Opcode::Div, gpr32_first_operand()),
            (X86Opcode::Mul, vec![]),
            (X86Opcode::Mul, gpr32_first_operand()),
            (X86Opcode::Cmpxchg, vec![]),
            (X86Opcode::Cmpxchg, gpr32_first_operand()),
            (X86Opcode::AtomicRmwCasLoop, vec![]),
            (X86Opcode::AtomicRmwCasLoop, gpr32_first_operand()),
            (X86Opcode::AtomicRmwCasLoop8, vec![]),
            (X86Opcode::AtomicRmwCasLoop16, vec![]),
            (X86Opcode::Pblendvb, vec![]),
            // No-implicit controls: both models must agree on EMPTY.
            (X86Opcode::AddRR, vec![]),
            (X86Opcode::SubRR, vec![]),
            (X86Opcode::ImulRR, vec![]),
            (X86Opcode::XorRR, vec![]),
            (X86Opcode::MovRR, vec![]),
        ];

        for (opcode, operands) in cases {
            let inst = X86ISelInst::new(opcode, operands);
            let (m_uses, m_defs) = mirror_roots(&inst);
            let (r_uses, r_defs) = regalloc_roots(&inst);
            assert_eq!(
                m_uses, r_uses,
                "implicit GPR64-root USE mirror drift on {opcode:?} (operands {:?})",
                inst.operands
            );
            assert_eq!(
                m_defs, r_defs,
                "implicit GPR64-root DEF mirror drift on {opcode:?} (operands {:?})",
                inst.operands
            );
        }
    }

    /// PINNED (mirror drift): TV-5 Stage A's verify-owned commutativity
    /// mirror (`post_ra_spec_commutative_two_address_rr`) must agree with
    /// codegen's `is_x86_commutative_two_address_rr` over the entire
    /// two-address opcode surface (and representative non-two-address
    /// controls). Drift in either direction is a correctness hazard for the
    /// captured-spec check: OVER-inclusion could accept a swapped
    /// non-commutative op as sound; under-inclusion would refute a sound
    /// commutative swap (a false positive under enforce).
    #[test]
    fn x86_captured_spec_commutative_mirror_agrees_with_codegen() {
        use trust_cg_verify::post_ra_captured_spec::post_ra_spec_commutative_two_address_rr;

        let two_address: Vec<X86Opcode> = vec![
            X86Opcode::AddRR,
            X86Opcode::SubRR,
            X86Opcode::AdcRR,
            X86Opcode::SbbRR,
            X86Opcode::AndRR,
            X86Opcode::OrRR,
            X86Opcode::XorRR,
            X86Opcode::ImulRR,
            X86Opcode::Addsd,
            X86Opcode::Subsd,
            X86Opcode::Mulsd,
            X86Opcode::Divsd,
            X86Opcode::Andpd,
            X86Opcode::Addss,
            X86Opcode::Subss,
            X86Opcode::Mulss,
            X86Opcode::Divss,
            X86Opcode::Andps,
            X86Opcode::Pand,
            X86Opcode::Pandn,
            X86Opcode::Por,
            X86Opcode::Pxor,
            X86Opcode::Pcmpeqb,
            X86Opcode::Pcmpeqw,
            X86Opcode::Pcmpgtb,
            X86Opcode::Pcmpgtw,
            X86Opcode::Pcmpeqd,
            X86Opcode::Pcmpgtd,
            X86Opcode::Paddb,
            X86Opcode::Paddw,
            X86Opcode::Paddd,
            X86Opcode::Psubb,
            X86Opcode::Psubw,
            X86Opcode::Psubd,
            X86Opcode::Paddq,
            X86Opcode::Psubq,
            X86Opcode::Pmullw,
            X86Opcode::Pmuludq,
            X86Opcode::Punpcklbw,
            X86Opcode::Punpckldq,
            X86Opcode::Packuswb,
            X86Opcode::Punpckhbw,
            X86Opcode::Punpcklqdq,
            X86Opcode::Pmulld,
            X86Opcode::Pcmpeqq,
            X86Opcode::Pcmpgtq,
            X86Opcode::Addps,
            X86Opcode::Subps,
            X86Opcode::Mulps,
            X86Opcode::Divps,
            X86Opcode::Addpd,
            X86Opcode::Subpd,
            X86Opcode::Mulpd,
            X86Opcode::Divpd,
            X86Opcode::Minsd,
            X86Opcode::Maxsd,
            X86Opcode::Minss,
            X86Opcode::Maxss,
            X86Opcode::Cmpsd,
            X86Opcode::Cmpss,
            // Non-two-address controls (must be false on both sides).
            X86Opcode::MovRR,
            X86Opcode::MovRI,
            X86Opcode::CmpRR,
            X86Opcode::TestRR,
            X86Opcode::Lea,
            X86Opcode::Idiv,
        ];
        for opcode in two_address {
            assert_eq!(
                post_ra_spec_commutative_two_address_rr(opcode),
                is_x86_commutative_two_address_rr(opcode),
                "commutativity mirror drift on {opcode:?}"
            );
        }
    }

    #[test]
    fn test_materialize_spills_reloads_two_operand_add_lhs() {
        use trust_cg_ir::x86_64_regs::R10;

        let mut func = minimal_func("two_operand_spill_reload");
        let entry = Block(0);
        let v0 = VReg::new(0, RegClass::Gpr64);
        let v1 = VReg::new(1, RegClass::Gpr64);
        func.next_vreg = 2;
        func.stack_slots.push(StackSlotInfo::new(8, 8));

        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![X86ISelOperand::VReg(v0), X86ISelOperand::VReg(v1)],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let installed_spills = HashMap::from([(v0, 0)]);
        materialize_x86_spills(&mut func, &installed_spills, X86CallAbi::SystemV).unwrap();

        let insts = &func.blocks[&entry].insts;
        assert_eq!(
            entry_opcodes(&func),
            vec![
                X86Opcode::MovRM,
                X86Opcode::AddRR,
                X86Opcode::MovMR,
                X86Opcode::Ret
            ]
        );
        assert_eq!(insts[0].operands[0], X86ISelOperand::PReg(R10));
        assert_eq!(insts[0].operands[1], x86_spill_stack_mem(0));
        assert_eq!(
            insts[1].operands,
            vec![X86ISelOperand::PReg(R10), X86ISelOperand::VReg(v1)]
        );
        assert_eq!(insts[2].operands[0], x86_spill_stack_mem(0));
        assert_eq!(insts[2].operands[1], X86ISelOperand::PReg(R10));
    }

