    #[test]
    fn test_spill_remat_map_copy_hop_requires_class_exact() {
        // MovRR32 (narrow copy) of a Gpr64 frame address must NOT propagate
        // (would truncate the pointer). Uses MovRR32 -> not chased.
        let mut func = minimal_func("remat_copy_narrow");
        let entry = Block(0);
        let base = VReg::new(0, RegClass::Gpr64);
        let copy = VReg::new(1, RegClass::Gpr32);
        func.next_vreg = 2;
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::Lea,
                vec![
                    X86ISelOperand::VReg(base),
                    X86ISelOperand::MemAddr {
                        base: Box::new(X86ISelOperand::StackSlot(5)),
                        disp: 0,
                    },
                ],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR32,
                vec![X86ISelOperand::VReg(copy), X86ISelOperand::VReg(base)],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));
        assert!(!build_x86_spill_remat_map(&func).contains_key(&copy));
    }

    #[test]
