    #[test]
    fn test_materialize_spills_rematerializes_const_when_enabled() {
        use trust_cg_ir::x86_64_regs::R10;
        // Directly exercise the remat map through the operand rewriter (the
        // env gate only chooses whether to build the map; the map itself is
        // what changes the reload into a recompute).
        let v0 = VReg::new(0, RegClass::Gpr64);
        let remat_map = HashMap::from([(v0, X86SpillRemat::Const { imm: 42 })]);
        let installed = HashMap::from([(v0, 7u32)]);
        let mut state = X86SpillScratchState::new(X86CallAbi::SystemV);
        let mut loads = Vec::new();
        let mut op = X86ISelOperand::VReg(v0);
        rewrite_x86_spilled_operand(
            &mut op, &installed, &remat_map, &mut state, &mut loads, true, false,
        )
        .unwrap();
        assert_eq!(loads.len(), 1);
        assert_eq!(
            loads[0].opcode,
            X86Opcode::MovRI,
            "remat, not a stack reload"
        );
        assert_eq!(
            loads[0].operands,
            vec![X86ISelOperand::PReg(R10), X86ISelOperand::Imm(42)]
        );
        assert_eq!(op, X86ISelOperand::PReg(R10));
    }

