    #[test]
    fn test_materialize_spills_does_not_fold_pshufd_reused_operand_reload() {
        let mut func = minimal_func("fpr128_pshufd_src_reused");
        let entry = Block(0);
        let value = VReg::new(0, RegClass::Fpr128);
        func.next_vreg = 1;
        func.stack_slots.push(StackSlotInfo::new(16, 16));

        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::Pshufd,
                vec![
                    X86ISelOperand::VReg(value),
                    X86ISelOperand::VReg(value),
                    X86ISelOperand::Imm(0x1B),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let installed_spills = HashMap::from([(value, 0)]);
        let evidence =
            materialize_x86_spills(&mut func, &installed_spills, X86CallAbi::SystemV).unwrap();

        let insts = &func.blocks[&entry].insts;
        assert_eq!(
            entry_opcodes(&func),
            vec![
                X86Opcode::MovdquRM,
                X86Opcode::Pshufd,
                X86Opcode::MovdquMR,
                X86Opcode::Ret
            ]
        );
        assert_eq!(evidence.reload_count, 1);
        assert_eq!(evidence.store_count, 1);
        assert_eq!(insts[0].operands[1], x86_spill_stack_mem(0));
        assert_eq!(
            insts[1].operands,
            vec![
                X86ISelOperand::PReg(XMM14),
                X86ISelOperand::PReg(XMM14),
                X86ISelOperand::Imm(0x1B),
            ],
            "duplicated PSHUFD spill operands stay on the explicit reload/store path"
        );
        assert_eq!(insts[2].operands[0], x86_spill_stack_mem(0));
        assert_eq!(insts[2].operands[1], X86ISelOperand::PReg(XMM14));
    }

